def school_feature_tag_display_zh(label):
    text = clean_school_feature_tag_label(label)
    if not text:
        return ""
    key = re.sub(r"\s+", " ", text).strip().casefold()
    if key in SCHOOL_FEATURE_TAG_DISPLAY_ZH:
        return SCHOOL_FEATURE_TAG_DISPLAY_ZH[key]
    parts = [part.strip() for part in re.split(r"\s*/\s*", text) if part.strip()]
    chinese_parts = [part for part in parts if re.search(r"[\u4e00-\u9fff]", part)]
    if chinese_parts:
        return chinese_parts[-1]
    return text
