def content_extraction_dependency_metadata(row):
    values = rowdict(row)
    try:
        payload = json.loads(str(values.get("dependency_status_json") or "{}"))
    except (TypeError, ValueError, json.JSONDecodeError):
        return {}
    return payload if isinstance(payload, dict) else {}


def content_extraction_confidence_display(row):
    values = rowdict(row) or {}
    raw_value = values.get("extraction_confidence")
    if raw_value in (None, ""):
        return "暂无可靠指标"
    try:
        confidence = float(raw_value)
    except (TypeError, ValueError):
        return "暂无可靠指标"
    if not math.isfinite(confidence) or confidence < 0 or confidence > 1:
        return "暂无可靠指标"
    if confidence == 0:
        contract = content_extraction_dependency_metadata(values).get("extraction_confidence")
        if not isinstance(contract, dict) or contract.get("computed") is not True:
            return "暂无可靠指标"
    return f"{round(confidence * 100)}%"


def is_content_extraction_transcript_json_api(path):
    return bool(re.fullmatch(r"/content/extractions/\d+/accurate-transcript", str(path or "")))


def content_extraction_v1_failback_allowed(row):
    values = rowdict(row)
    if str(values.get("source_type") or "") != "v2":
        return False
    metadata = content_extraction_dependency_metadata(values)
    failure = metadata.get("latest_pipeline")
    if not isinstance(failure, dict):
        return False
    code = str(failure.get("failure_code") or "")
    return (
        str(values.get("process_status") or "") == "失败"
        and failure.get("failback_allowed") is True
        and code in CONTENT_EXTRACTION_V1_FAILBACK_CODES
    )


def build_content_extraction_client():
    token_path = CONTENT_EXTRACTION_V2_CACHE_ROOT / "service.token"
    try:
        token = token_path.read_text(encoding="utf-8").strip()
    except OSError:
        token = ""
    service_url = os.environ.get(
        "AAIE_CRM_CONTENT_EXTRACTION_SERVICE_URL",
        "http://127.0.0.1:8792",
    ).strip()
    return ContentExtractionClient(service_url, token, timeout=2.0)
