def normalize_school_fee_year_level(raw):
    text = re.sub(r"\s+", " ", str(raw or "")).strip()
    range_match = re.search(r"\bYears?\s*(\d{1,2})\s*(?:-|–|to)\s*(?:Year\s*)?(\d{1,2})\b", text, re.I)
    if range_match:
        return f"Year {range_match.group(1)}-{range_match.group(2)}"
    year_match = re.search(r"\bYear\s*(\d{1,2})\b", text, re.I)
    if year_match:
        return f"Year {year_match.group(1)}"
    if re.search(r"\b(Prep|Foundation)\b", text, re.I):
        return "Prep / Foundation"
    return ""

def extract_school_fee_rows_from_text(text):
    source_text = html.unescape(str(text or "").replace("\xa0", " "))
    default_year_match = re.search(r"\b(20\d{2})\b", source_text)
    default_year = default_year_match.group(1) if default_year_match else str(date.today().year)
    candidates = []
    for line in source_text.splitlines():
        line = re.sub(r"\s+", " ", line).strip(" -\t")
        if line:
            candidates.append(line)
    compact = re.sub(r"\s+", " ", source_text).strip()
    for keyword in ["application fee", "enrolment fee", "enrollment fee", "tuition fee", "school fee", "international student fee"]:
        pattern = rf"(.{{0,70}}{keyword}.{{0,110}}?(?:AUD|A\$|\$)\s?[\d,]+(?:\.\d+)?.{{0,40}})"
        candidates.extend(re.sub(r"\s+", " ", match.group(1)).strip() for match in re.finditer(pattern, compact, re.I))
    rows = []
    seen = set()
    fee_keywords = re.compile(r"\b(application|enrolment|enrollment|tuition|school fee|international student|申请费|学费)\b", re.I)
    amount_pattern = re.compile(r"(?:AUD|A\$|\$)\s?([\d,]+(?:\.\d+)?)", re.I)
    for raw in candidates:
        amount = amount_pattern.search(raw)
        if not amount:
            continue
        has_fee_word = bool(fee_keywords.search(raw))
        has_year_context = bool(re.search(r"\bYears?\s*\d{1,2}\s*(?:-|–|to)\s*(?:Year\s*)?\d{1,2}\b|\bYear\s*\d{1,2}\b", raw, re.I))
        if not has_fee_word and not has_year_context:
            continue
        if re.search(r"application|申请费", raw, re.I):
            fee_type = "Application Fee"
        elif re.search(r"enrolment|enrollment", raw, re.I):
            fee_type = "Enrolment Fee"
        else:
            fee_type = "Tuition"
        fee_year_match = re.search(r"\b(20\d{2})\b", raw)
        row = {
            "fee_type": fee_type,
            "year_level": "" if fee_type in {"Application Fee", "Enrolment Fee"} else normalize_school_fee_year_level(raw),
            "amount": amount.group(1),
            "fee_year": fee_year_match.group(1) if fee_year_match else default_year,
            "raw_text": raw,
        }
        key = tuple(row.values())
        if key in seen:
            continue
        seen.add(key)
        rows.append(row)
    return rows[:30]

