def normalize_state_fee_sector(value):
    text = str(value or "").strip()
    if not text:
        return ""
    return STATE_FEE_SECTOR_ALIASES.get(text.lower(), text)


def school_state_fee_sector(school):
    sector_key = str(school["sector_key"] if hasattr(school, "keys") and "sector_key" in school.keys() else school.get("sector_key", "")).strip()
    school_type = str(school["school_type"] if hasattr(school, "keys") and "school_type" in school.keys() else school.get("school_type", "")).strip()
    return normalize_state_fee_sector(sector_key or school_type)


def state_fee_amount_text(item):
    currency = item["currency"] if hasattr(item, "keys") else item.get("currency", "AUD")
    amount = item["amount"] if hasattr(item, "keys") else item.get("amount")
    amount_min = item["amount_min"] if hasattr(item, "keys") else item.get("amount_min")
    amount_max = item["amount_max"] if hasattr(item, "keys") else item.get("amount_max")
    frequency = item["billing_frequency"] if hasattr(item, "keys") else item.get("billing_frequency", "")
    prefix = f"{currency} "
    if amount is not None and str(amount) != "":
        text = prefix + format_money(Decimal(str(amount)))
    elif amount_min is not None and amount_max is not None:
        text = prefix + format_money(Decimal(str(amount_min))) + " - " + format_money(Decimal(str(amount_max)))
    else:
        text = prefix + "TBC"
    return f"{text} {frequency}".strip()


def active_state_fee_schedule(state, sector, effective_year=None):
    normalized_state = str(state or "").strip().upper()
    normalized_sector = normalize_state_fee_sector(sector)
    if not normalized_state or not normalized_sector:
        return None
    params = [normalized_state, normalized_sector]
    year_filter = ""
    if effective_year:
        year_filter = " AND effective_year=?"
        params.append(int(effective_year))
    return db.one(
        f"""SELECT * FROM state_fee_schedules
            WHERE upper(state)=? AND sector=? AND is_active=1{year_filter}
            ORDER BY effective_year DESC,id DESC LIMIT 1""",
        tuple(params),
    )


def state_fee_items(schedule_id):
    return db.all(
        "SELECT * FROM state_fee_items WHERE schedule_id=? ORDER BY category,sort_order,id",
        (schedule_id,),
    )


def state_fee_items_by_category(schedule_id):
    grouped = {key: [] for key in STATE_FEE_CATEGORY_LABELS}
    for item in state_fee_items(schedule_id):
        grouped.setdefault(item["category"], []).append(item)
    return grouped


def school_uses_state_fee_schedule(school):
    state = str(school["state"] if hasattr(school, "keys") and "state" in school.keys() else school.get("state", "")).strip().upper()
    return bool(state and school_state_fee_sector(school) == "Government" and active_state_fee_schedule(state, "Government"))


def year_level_number(value):
    text = str(value or "").strip()
    if re.search(r"\b(pre[-\s]?primary)\b", text, re.I):
        return -1
    if re.search(r"\b(preschool)\b", text, re.I):
        return -1
    if re.search(r"\b(prep|foundation|kindergarten|reception)\b", text, re.I):
        return 0
    match = re.search(r"\b(?:year\s*)?(\d{1,2})\b", text, re.I)
    return int(match.group(1)) if match else None


def state_fee_item_matches_year(item, year_level):
    number = year_level_number(year_level)
    if number is None:
        return False
    start = year_level_number(item["year_level_from"])
    end = year_level_number(item["year_level_to"])
    if start is None and end is None:
        return False
    if start is None:
        start = end
    if end is None:
        end = start
    return start <= number <= end


def state_fee_tuition_item_for_year(items, year_level):
    for item in items:
        if item["category"] == "tuition" and state_fee_item_matches_year(item, year_level):
            return item
    return None


def school_fee_row_value(row, key, default=""):
    if row is None:
        return default
    if hasattr(row, "keys"):
        return row[key] if key in row.keys() else default
    return row.get(key, default)


def school_accepted_fee_year_levels(school):
    levels = []
    raw_levels = school_fee_row_value(school, "accepted_international_year_levels", "[]")
    if isinstance(raw_levels, list):
        levels = [str(item) for item in raw_levels if str(item).strip() and str(item) != "Unknown"]
    else:
        try:
            parsed = json.loads(raw_levels or "[]")
            if isinstance(parsed, list):
                levels = [str(item) for item in parsed if str(item).strip() and str(item) != "Unknown"]
        except (TypeError, json.JSONDecodeError):
            levels = []
    pattern = school_fee_row_value(school, "accepted_international_year_level_pattern", "")
    if not levels and pattern in SCHOOL_YEAR_PATTERN_LEVELS:
        levels = [level for level in SCHOOL_YEAR_PATTERN_LEVELS[pattern] if level != "Unknown"]
    min_level = school_fee_row_value(school, "international_year_level_min", "")
    max_level = school_fee_row_value(school, "international_year_level_max", "")
    if not levels and min_level not in {"", "Unknown"} and max_level not in {"", "Unknown"}:
        start = year_level_number(min_level)
        end = year_level_number(max_level)
        if start is not None and end is not None:
            if start > end:
                start, end = end, start
            levels = [value for value in SCHOOL_YEAR_VALUES if value != "Unknown" and (year_level_number(value) or 0) >= start and (year_level_number(value) or 0) <= end]
    if school_report_prep_to_year12_fallback(school):
        levels = list(SCHOOL_YEAR_PATTERN_LEVELS["PrepToYear12"])
    return levels


def school_report_prep_to_year12_fallback(school):
    name = school_fee_row_value(school, "school_name", "") or school_fee_row_value(school, "name", "")
    normalized_name = re.sub(r"[^a-z0-9]+", "", str(name or "").lower())
    if "bayside" not in normalized_name or "p12college" not in normalized_name:
        return False
    pattern = school_fee_row_value(school, "accepted_international_year_level_pattern", "")
    if pattern != "Custom":
        return False
    year_levels = str(school_fee_row_value(school, "year_levels", "") or "")
    return bool(re.search(r"\bP\s*[-–]\s*12\b|\b10\s*[-–]\s*12\b|Year\s*12", year_levels, flags=re.I))


def school_report_year_range_from_raw_levels(raw_year_levels):
    text = str(raw_year_levels or "").strip()
    if not text:
        return "", None, None
    normalized = text.lower().replace("–", "-").replace("—", "-")
    if re.search(r"\b(?:p|prep|foundation|k)\s*-\s*(?:12|year\s*12)\b", normalized):
        return "Prep-Year 12 / 全年级", 0, 12

    numbers = set()
    for start, end in re.findall(r"(?:year\s*)?(\d{1,2})\s*-\s*(?:year\s*)?(\d{1,2})", normalized):
        start_num, end_num = int(start), int(end)
        if 1 <= start_num <= 12 and 1 <= end_num <= 12:
            if start_num > end_num:
                start_num, end_num = end_num, start_num
            numbers.update(range(start_num, end_num + 1))
    for item in re.findall(r"(?:year\s*)?(\d{1,2})", normalized):
        number = int(item)
        if 1 <= number <= 12:
            numbers.add(number)
    if not numbers:
        return "", None, None
    start_num, end_num = min(numbers), max(numbers)
    if numbers == set(range(start_num, end_num + 1)):
        return f"{start_num}-{end_num}", start_num, end_num
    return "", start_num, end_num


def state_fee_tuition_items_for_school(items, school):
    matched = []
    seen = set()
    for level in school_accepted_fee_year_levels(school):
        item = state_fee_tuition_item_for_year(items, level)
        if item and item["id"] not in seen:
            matched.append(item)
            seen.add(item["id"])
    return matched


def state_fee_decimal(value):
    if value is None or str(value) == "":
        return Decimal("0")
    return Decimal(str(value))


def state_fee_estimate(state, sector, year_level, need_homestay=False, need_arrival_support=False, need_accommodation_placement=False):
    schedule = active_state_fee_schedule(state, sector)
    if not schedule:
        return {"schedule": None, "items": [], "first_year_min": Decimal("0"), "first_year_max": Decimal("0"), "ongoing_min": Decimal("0"), "ongoing_max": Decimal("0")}
    items = state_fee_items(schedule["id"])
    selected = []
    tuition = state_fee_tuition_item_for_year(items, year_level)
    first_min = Decimal("0")
    first_max = Decimal("0")
    ongoing_min = Decimal("0")
    ongoing_max = Decimal("0")
    if tuition:
        amount = state_fee_decimal(tuition["amount"])
        selected.append(("Tuition Fee", tuition, "按年级自动匹配"))
        first_min += amount
        first_max += amount
        ongoing_min += amount
        ongoing_max += amount
    for item in items:
        name = item["fee_name"]
        category = item["category"]
        if category == "admin" and item["is_mandatory"]:
            selected.append((name, item, "一次性必收"))
            first_min += state_fee_decimal(item["amount"])
            first_max += state_fee_decimal(item["amount"])
        elif name == "Arrival Support Fee" and need_arrival_support:
            selected.append((name, item, "已选择"))
            first_min += state_fee_decimal(item["amount"])
            first_max += state_fee_decimal(item["amount"])
        elif name == "Accommodation Placement Fee" and need_accommodation_placement:
            selected.append((name, item, "已选择"))
            first_min += state_fee_decimal(item["amount"])
            first_max += state_fee_decimal(item["amount"])
        elif category == "accommodation" and need_homestay:
            frequency = (item["billing_frequency"] or "").lower()
            selected.append((name, item, "按费用周期估算；weekly 费用按 52 周估算"))
            min_amount = state_fee_decimal(item["amount_min"] if item["amount_min"] is not None else item["amount"])
            max_amount = state_fee_decimal(item["amount_max"] if item["amount_max"] is not None else item["amount"])
            if "per week" in frequency:
                first_min += min_amount * Decimal("52")
                first_max += max_amount * Decimal("52")
                ongoing_min += min_amount * Decimal("52")
                ongoing_max += max_amount * Decimal("52")
            elif min_amount or max_amount:
                first_min += min_amount
                first_max += max_amount
        elif category == "extra" and item["billing_frequency"] in {"per annum", "every 1-2 years", "every 2-3 years"}:
            selected.append((name, item, "预估费用"))
            first_min += state_fee_decimal(item["amount_min"] or item["amount"])
            first_max += state_fee_decimal(item["amount_max"] or item["amount"])
            if item["billing_frequency"] == "per annum":
                ongoing_min += state_fee_decimal(item["amount_min"] or item["amount"])
                ongoing_max += state_fee_decimal(item["amount_max"] or item["amount"])
    return {
        "schedule": schedule,
        "items": selected,
        "first_year_min": first_min,
        "first_year_max": first_max,
        "ongoing_min": ongoing_min,
        "ongoing_max": ongoing_max,
    }


def state_fee_item_payload(item):
    return {
        "id": item["id"],
        "category": item["category"],
        "category_label": STATE_FEE_CATEGORY_LABELS.get(item["category"], item["category"]),
        "fee_name": item["fee_name"],
        "school_level": item["school_level"] or "",
        "year_level_from": item["year_level_from"] or "",
        "year_level_to": item["year_level_to"] or "",
        "amount": item["amount"],
        "amount_min": item["amount_min"],
        "amount_max": item["amount_max"],
        "currency": item["currency"] or "AUD",
        "billing_frequency": item["billing_frequency"] or "",
        "is_mandatory": bool(item["is_mandatory"]),
        "notes": item["notes"] or "",
        "display_amount": state_fee_amount_text(item),
        "sort_order": item["sort_order"],
    }


def state_fee_schedule_payload(schedule, include_items=True):
    if not schedule:
        return None
    payload = {
        "id": schedule["id"],
        "state": schedule["state"],
        "sector": schedule["sector"],
        "schedule_name": schedule["schedule_name"],
        "source_name": schedule["source_name"] or "",
        "source_url": schedule["source_url"] or "",
        "effective_year": schedule["effective_year"],
        "effective_from_date": schedule["effective_from_date"] or "",
        "effective_to_date": schedule["effective_to_date"] or "",
        "is_active": bool(schedule["is_active"]),
        "notes": schedule["notes"] or "",
        "created_at": schedule["created_at"],
        "updated_at": schedule["updated_at"],
    }
    if include_items:
        grouped = {}
        for item in state_fee_items(schedule["id"]):
            grouped.setdefault(item["category"], []).append(state_fee_item_payload(item))
        payload["items_by_category"] = grouped
        payload["items"] = [item for group in grouped.values() for item in group]
    return payload


def state_fee_estimate_payload(state, sector, year_level, need_homestay=False, need_arrival_support=False, need_accommodation_placement=False):
    estimate = state_fee_estimate(state, sector, year_level, need_homestay, need_arrival_support, need_accommodation_placement)
    tuition_item = next((item for label, item, _note in estimate["items"] if label == "Tuition Fee"), None)
    return {
        "schedule": state_fee_schedule_payload(estimate["schedule"], include_items=False),
        "input": {
            "state": str(state or "").strip().upper(),
            "sector": normalize_state_fee_sector(sector),
            "year_level": year_level,
            "need_homestay": bool(need_homestay),
            "need_arrival_support": bool(need_arrival_support),
            "need_accommodation_placement": bool(need_accommodation_placement),
        },
        "matched_items": [
            {"label": label, "note": note, **state_fee_item_payload(item)}
                for label, item, note in estimate["items"]
        ],
        "matched_tuition_level": tuition_item["school_level"] if tuition_item else "",
        "matched_tuition_item": state_fee_item_payload(tuition_item) if tuition_item else None,
        "estimated_first_year_cost_range": {
            "currency": "AUD",
            "min": float(estimate["first_year_min"]),
            "max": float(estimate["first_year_max"]),
            "display": f"AUD {format_money(estimate['first_year_min'])} - {format_money(estimate['first_year_max'])}",
        },
        "estimated_ongoing_annual_cost_range": {
            "currency": "AUD",
            "min": float(estimate["ongoing_min"]),
            "max": float(estimate["ongoing_max"]),
            "display": f"AUD {format_money(estimate['ongoing_min'])} - {format_money(estimate['ongoing_max'])}",
        },
    }

