def school_feature_default_tags():
    try:
        rows = db.all(
            """SELECT t.id,t.category_id,t.tag_name_cn,t.tag_name_en,t.keywords,
                      c.category_name_cn,c.category_name_en
               FROM school_feature_tags t
               LEFT JOIN school_feature_categories c ON c.id=t.category_id
               WHERE t.is_active=1 AND COALESCE(c.is_active,1)=1
               ORDER BY c.sort_order,t.sort_order"""
        )
    except Exception:
        return []
    return [dict(row) for row in rows]


def normalize_school_feature_tags(tags=None):
    normalized = []
    for item in tags if tags is not None else school_feature_default_tags():
        if not hasattr(item, "keys"):
            continue
        data = dict(item)
        keywords = data.get("keywords") or []
        if isinstance(keywords, str):
            try:
                parsed_keywords = json.loads(keywords)
                keywords = parsed_keywords if isinstance(parsed_keywords, list) else [keywords]
            except Exception:
                keywords = re.split(r"[,，\n]+", keywords)
        names = [
            data.get("tag_name_cn") or data.get("tag_name_zh") or data.get("name_cn") or data.get("name"),
            data.get("tag_name_en") or data.get("name_en"),
            data.get("tag_key"),
        ]
        for name in names:
            if name:
                keywords.append(str(name))
        clean_keywords = []
        seen_keywords = set()
        for keyword in keywords:
            value = str(keyword or "").strip()
            if not value:
                continue
            lowered = value.lower()
            if lowered in seen_keywords:
                continue
            seen_keywords.add(lowered)
            clean_keywords.append(value)
        tag_name_cn = data.get("tag_name_cn") or data.get("tag_name_zh") or data.get("name_cn") or data.get("name") or data.get("tag_name_en") or data.get("tag_key")
        if not tag_name_cn or not clean_keywords:
            continue
        normalized.append(
            {
                "id": data.get("id") or data.get("tag_id"),
                "category_id": data.get("category_id"),
                "category_name_cn": data.get("category_name_cn") or data.get("category") or "",
                "category_name_en": data.get("category_name_en") or "",
                "tag_name_cn": str(tag_name_cn).strip(),
                "tag_name_en": str(data.get("tag_name_en") or data.get("name_en") or tag_name_cn).strip(),
                "keywords": clean_keywords,
            }
        )
    return normalized


def school_feature_excerpt(text, keyword, limit=260):
    clean = re.sub(r"\s+", " ", text or "").strip()
    if not clean:
        return ""
    needle = str(keyword or "").strip().lower()
    index = clean.lower().find(needle) if needle else -1
    if index < 0:
        return clean[:limit]
    start = max(0, index - 100)
    end = min(len(clean), index + len(needle) + 160)
    return ("..." if start else "") + clean[start:end] + ("..." if end < len(clean) else "")


