def school_feature_keyword_hit_count(text, keyword):
    clean_keyword = str(keyword or "").strip()
    if not clean_keyword:
        return 0
    lowered = clean_keyword.lower()
    if re.fullmatch(r"[a-z0-9][a-z0-9 &/+\-.]{1,80}", lowered):
        pattern = rf"(?<![a-z0-9]){re.escape(lowered)}(?![a-z0-9])"
        return len(re.findall(pattern, text))
    return text.count(lowered)


def is_weak_official_feature_keyword(keyword):
    value = re.sub(r"\s+", " ", str(keyword or "").strip().lower())
    return value in OFFICIAL_WEBSITE_WEAK_FEATURE_KEYWORDS


OFFICIAL_WEBSITE_COMPOUND_FEATURE_KEYWORDS = (
    ("academic", "extension", "academic extension"),
)


def official_website_compound_feature_hits(text, tag_keywords):
    lowered_keywords = {re.sub(r"\s+", " ", str(keyword or "").strip().lower()) for keyword in tag_keywords}
    hits = []
    hit_count = 0
    for first, second, phrase in OFFICIAL_WEBSITE_COMPOUND_FEATURE_KEYWORDS:
        if first not in lowered_keywords or second not in lowered_keywords:
            continue
        count = school_feature_keyword_hit_count(text, phrase)
        if count > 0:
            hits.append(phrase)
            hit_count += count
    return hits, hit_count


def is_noisy_official_feature_excerpt(excerpt, keyword=""):
    lowered = re.sub(r"\s+", " ", str(excerpt or "").lower())
    if not lowered:
        return False
    keyword_pos = lowered.find(str(keyword or "").strip().lower()) if keyword else -1
    for pattern in OFFICIAL_WEBSITE_NOISE_TEXT_PATTERNS:
        pattern_pos = lowered.find(pattern)
        if pattern_pos < 0:
            continue
        if keyword_pos < 0:
            return True
        if pattern_pos <= keyword_pos and keyword_pos - pattern_pos <= 180:
            return True
    return False


def is_negated_official_feature_keyword(excerpt, keyword=""):
    lowered = re.sub(r"\s+", " ", str(excerpt or "").lower())
    kw = re.sub(r"\s+", " ", str(keyword or "").strip().lower())
    if not lowered or not kw or len(kw) < 3:
        return False
    escaped = re.escape(kw)
    negated_patterns = (
        rf"\bnon[-\s]+{escaped}\b",
        rf"\bnot\s+{escaped}\b",
        rf"\bno\s+{escaped}\b",
        rf"\bwithout\s+{escaped}\b",
    )
    return any(re.search(pattern, lowered) for pattern in negated_patterns)


OFFICIAL_WEBSITE_SKIP_TAG_NAMES = {"男校", "女校", "混校"}
OFFICIAL_WEBSITE_SKIP_TAG_EXACT_NAMES = {"八大升学", "升学辅导", "大学申请支持", "职业规划支持", "校友资源"}


def is_skipped_official_feature_tag(tag_name):
    value = str(tag_name or "").strip()
    if value in OFFICIAL_WEBSITE_SKIP_TAG_NAMES or value in OFFICIAL_WEBSITE_SKIP_TAG_EXACT_NAMES:
        return True
    return value.endswith("方向")


def extract_pdf_text_from_bytes(pdf_bytes, max_pages=8):
    try:
        reader = PdfReader(io.BytesIO(pdf_bytes))
    except Exception as exc:
        return "", str(exc)
    parts = []
    for page in reader.pages[:max_pages]:
        try:
            parts.append(page.extract_text() or "")
        except Exception:
            continue
    return re.sub(r"\s+", " ", "\n".join(parts)).strip(), ""


def parse_school_website_html(html_text, page_url, soup_factory=None):
    try:
        if soup_factory is None:
            from bs4 import BeautifulSoup
            soup_factory = BeautifulSoup
        soup = soup_factory(html_text, "html.parser")
    except ImportError as exc:
        raise RuntimeError("缺少依赖 beautifulsoup4，无法解析官网页面。") from exc
    except Exception as exc:
        raise RuntimeError(f"官网页面解析失败：{exc}") from exc

    for node in soup(["script", "style", "noscript", "nav", "footer"]):
        if hasattr(node, "decompose"):
            node.decompose()
    title_node = soup.find("title") if hasattr(soup, "find") else None
    source_title = ""
    if title_node and hasattr(title_node, "get_text"):
        source_title = re.sub(r"\s+", " ", title_node.get_text(" ", strip=True)).strip()
    if not source_title:
        source_title = urlparse(page_url).netloc

    page_text = soup.get_text(" ", strip=True) if hasattr(soup, "get_text") else ""
    page_text = re.sub(r"\s+", " ", page_text).strip()
    pdf_links = []
    if hasattr(soup, "find_all"):
        for link in soup.find_all("a", href=True):
            href = link.get("href") if hasattr(link, "get") else ""
            if not href:
                continue
            absolute = urljoin(page_url, href)
            if absolute.lower().split("?", 1)[0].endswith(".pdf"):
                pdf_links.append(absolute)
    return source_title, page_text, list(dict.fromkeys(pdf_links))


def match_school_feature_tags_from_text(text, tag_definitions, source_url, source_type, source_title=""):
    clean = re.sub(r"\s+", " ", text or "").strip()
    lower_text = clean.lower()
    matches = []
    if not lower_text:
        return matches
    is_official_page = str(source_type or "").lower() == "official_website"
    for tag in tag_definitions:
        if is_official_page and is_skipped_official_feature_tag(tag.get("tag_name_cn")):
            continue
        matched_keywords = []
        hit_count = 0
        for keyword in tag["keywords"]:
            if is_official_page and is_weak_official_feature_keyword(keyword):
                continue
            count = school_feature_keyword_hit_count(lower_text, keyword)
            if count > 0:
                matched_keywords.append(keyword)
                hit_count += count
        if is_official_page and not matched_keywords:
            matched_keywords, hit_count = official_website_compound_feature_hits(lower_text, tag["keywords"])
        if not matched_keywords:
            continue
        best_keyword = matched_keywords[0]
        excerpt = school_feature_excerpt(clean, best_keyword)
        if is_official_page and is_noisy_official_feature_excerpt(excerpt, best_keyword):
            continue
        if is_official_page and is_negated_official_feature_keyword(excerpt, best_keyword):
            continue
        confidence = min(96, 55 + min(hit_count, 4) * 10 + (8 if source_type == "official_pdf" else 0))
        matches.append(
            {
                "tag_id": tag.get("id"),
                "category_id": tag.get("category_id"),
                "category": tag.get("category_name_cn") or tag.get("category_name_en") or "",
                "category_name_cn": tag.get("category_name_cn") or "",
                "category_name_en": tag.get("category_name_en") or "",
                "tag_name": tag["tag_name_cn"],
                "tag_name_cn": tag["tag_name_cn"],
                "tag_name_en": tag["tag_name_en"],
                "description": excerpt,
                "confidence_rate": confidence,
                "source_url": source_url,
                "source_title": source_title or source_url,
                "source_type": source_type,
                "source_excerpt": excerpt,
                "matched_keywords": matched_keywords,
            }
        )
    return matches


def merge_school_feature_matches(matches):
    merged = {}
    for item in matches:
        key = str(item.get("tag_name_cn") or item.get("tag_name") or item.get("tag_id") or "").strip().lower()
        existing = merged.get(key)
        if existing is None or int(item.get("confidence_rate") or 0) > int(existing.get("confidence_rate") or 0):
            merged[key] = dict(item)
        elif existing:
            existing_keywords = set(existing.get("matched_keywords") or [])
            for keyword in item.get("matched_keywords") or []:
                if keyword not in existing_keywords:
                    existing.setdefault("matched_keywords", []).append(keyword)
                    existing_keywords.add(keyword)
    return sorted(merged.values(), key=lambda row: (-int(row.get("confidence_rate") or 0), str(row.get("tag_name_cn") or "")))


def extract_school_features_from_official_url(official_url, tags=None, max_pdfs=3, timeout=12, requests_session=None, soup_factory=None):
    official_url = str(official_url or "").strip()
    parsed = urlparse(official_url)
    if not parsed.scheme and official_url and "." in official_url.split("/", 1)[0]:
        official_url = f"https://{official_url}"
        parsed = urlparse(official_url)
    result = {
        "status": "error",
        "source_url": official_url,
        "features": [],
        "pdfs": [],
        "message": "",
        "errors": [],
    }
    if parsed.scheme not in {"http", "https"}:
        result["error"] = "学校官网链接必须是 http 或 https。"
        result["message"] = result["error"]
        return result

    try:
        tag_definitions = normalize_school_feature_tags(tags)
        if not tag_definitions:
            result["status"] = "no_feature"
            result["message"] = "无特征"
            return result

        if requests_session is None:
            try:
                import requests
                requests_session = requests
            except ImportError as exc:
                raise RuntimeError("缺少依赖 requests，无法获取官网页面。") from exc

        headers = {"User-Agent": "AAIE-CRM-SchoolFeatureExtractor/1.0"}
        response = requests_session.get(official_url, timeout=timeout, headers=headers)
        if hasattr(response, "raise_for_status"):
            response.raise_for_status()
        html_text = getattr(response, "text", "")
        if not html_text:
            content = getattr(response, "content", b"")
            html_text = content.decode("utf-8", errors="ignore") if isinstance(content, bytes) else str(content or "")
        source_title, page_text, pdf_links = parse_school_website_html(html_text, official_url, soup_factory=soup_factory)

        matches = match_school_feature_tags_from_text(
            page_text,
            tag_definitions,
            official_url,
            "official_website",
            source_title=source_title,
        )

        for pdf_url in pdf_links[:max_pdfs]:
            pdf_record = {"url": pdf_url, "status": "skipped", "matched_count": 0, "error": ""}
            try:
                pdf_response = requests_session.get(pdf_url, timeout=timeout, headers=headers)
                if hasattr(pdf_response, "raise_for_status"):
                    pdf_response.raise_for_status()
                pdf_bytes = getattr(pdf_response, "content", b"")
                if isinstance(pdf_bytes, str):
                    pdf_bytes = pdf_bytes.encode("utf-8", errors="ignore")
                pdf_text, pdf_error = extract_pdf_text_from_bytes(pdf_bytes)
                if pdf_error:
                    pdf_record.update({"status": "error", "error": pdf_error})
                else:
                    pdf_matches = match_school_feature_tags_from_text(
                        pdf_text,
                        tag_definitions,
                        pdf_url,
                        "official_pdf",
                        source_title=Path(urlparse(pdf_url).path).name or pdf_url,
                    )
                    matches.extend(pdf_matches)
                    pdf_record.update({"status": "parsed", "matched_count": len(pdf_matches)})
            except Exception as exc:
                pdf_record.update({"status": "error", "error": str(exc)})
                result["errors"].append({"source_url": pdf_url, "error": str(exc)})
            result["pdfs"].append(pdf_record)

        result["features"] = merge_school_feature_matches(matches)
        if result["features"]:
            result["status"] = "matched"
            result["message"] = f"已匹配 {len(result['features'])} 个学校特色标签"
        else:
            result["status"] = "no_feature"
            result["message"] = "无特征"
        return result
    except Exception as exc:
        result["status"] = "error"
        result["error"] = str(exc)
        result["message"] = f"学校官网特色提取失败：{exc}"
        return result


def ensure_dirs():
    managed = getattr(STAGING, "runtime_configuration", None)
    if managed is not None:
        managed.require_ready()
        return
    for path in (LOCAL_BACKUP_DIR, PREVIEW_DIR, SCHOOL_PLAN_REPORT_DIR, SCHOOL_PLAN_CONFIRMATION_DIR, CONTRACT_SIGNING_DIR, UPLOAD_REVIEW_DIR, ASSET_DIR, LOG_DIR, TEMPLATE_DIR, MANAGED_TEMPLATE_DIR, TEMPLATE_ARCHIVE_DIR, BETTER_EDUCATION_IMPORT_DIR, SECRET_PATH.parent):
        if not (STAGING and path == ASSET_DIR):
            path.mkdir(parents=True, exist_ok=True)
    try:
        if not (STAGING and SCHOOL_LIBRARY_FILE_DIR in STAGING.read_roots):
            SCHOOL_LIBRARY_FILE_DIR.mkdir(parents=True, exist_ok=True)
    except OSError as exc:
        append_service_log("system", "school_library_dir_unavailable", repr(exc), path=str(SCHOOL_LIBRARY_FILE_DIR))
    for path in (SIGNATURE_DIR, STAMP_DIR):
        try:
            path.mkdir(parents=True, exist_ok=True)
        except OSError:
            pass
    if not SECRET_PATH.exists():
        SECRET_PATH.write_bytes(Fernet.generate_key())
        os.chmod(SECRET_PATH, 0o600)
    ensure_student_template()
    ensure_study_contract_template(STUDY_CONTRACT_TEMPLATE_PATH)


