def school_plan_document_year_text(row):
    parts = []
    for key in ("notes", "original_filename", "stored_filename", "file_path", "source_url"):
        try:
            value = row[key]
        except (KeyError, IndexError):
            value = ""
        if value:
            parts.append(str(value))
    return " ".join(parts)


def school_plan_display_ranked_school_name(value):
    return re.sub(r"^\s*\d+\s*[.)、]\s*", "", str(value or "").strip())


def school_plan_find_school_brochure_document(school_id, report_year):
    rows = db.all(
        """SELECT id,school_id,document_type,original_filename,stored_filename,file_path,file_size,source_url,notes,uploaded_at,updated_at
           FROM school_documents
           WHERE school_id=? AND document_type=?
           ORDER BY COALESCE(updated_at, uploaded_at) DESC, uploaded_at DESC, id DESC""",
        (school_id, "School Brochure"),
    )
    candidates = []
    for row in rows:
        source_url = str(row["source_url"] or "").strip()
        file_path = Path(row["file_path"] or "")
        if source_url or file_path.is_file():
            candidates.append(row)
    if not candidates:
        return None
    year = str(report_year or "").strip()
    if year:
        for row in candidates:
            if re.search(rf"(?<!\d){re.escape(year)}(?!\d)", school_plan_document_year_text(row)):
                return row
    return candidates[0]


def school_plan_find_school_brochure_pdf(school_id, report_year):
    rows = db.all(
        """SELECT id,school_id,document_type,original_filename,stored_filename,file_path,file_size,source_url,notes,uploaded_at,updated_at
           FROM school_documents
           WHERE school_id=? AND document_type=?
           ORDER BY COALESCE(updated_at, uploaded_at) DESC, uploaded_at DESC, id DESC""",
        (school_id, "School Brochure"),
    )
    candidates = []
    for row in rows:
        path = Path(row["file_path"] or "")
        if path.suffix.lower() != ".pdf" or not path.is_file():
            continue
        candidates.append(row)
    if not candidates:
        return None
    year = str(report_year or "").strip()
    if year:
        for row in candidates:
            if re.search(rf"(?<!\d){re.escape(year)}(?!\d)", school_plan_document_year_text(row)):
                return row
        return None
    return candidates[0]


