def school_plan_pdfunite_path():
    candidates = [
        SCHOOL_REPORT_PDFUNITE,
        Path(shutil.which("pdfunite") or ""),
        Path.home() / ".cache/codex-runtimes/codex-primary-runtime/dependencies/native/poppler/poppler/bin/pdfunite",
    ]
    for candidate in candidates:
        if candidate and candidate.is_file():
            return candidate
    return None


def school_plan_append_school_brochures(source_pdf, target_pdf, school_ids, report_year):
    source_pdf = Path(source_pdf)
    target_pdf = Path(target_pdf)
    attached = []
    brochure_rows = []
    for school_id in school_ids:
        brochure = school_plan_find_school_brochure_pdf(school_id, report_year)
        if not brochure:
            append_service_log("admin", "No School Brochure found", school_id=school_id, report_year=report_year)
            continue
        brochure_rows.append(brochure)

    if not brochure_rows:
        if source_pdf.resolve() != target_pdf.resolve():
            target_pdf.parent.mkdir(parents=True, exist_ok=True)
            shutil.copyfile(source_pdf, target_pdf)
        return attached

    target_pdf.parent.mkdir(parents=True, exist_ok=True)
    temp_paths = []
    merge_inputs = [source_pdf]
    pdfunite = school_plan_pdfunite_path()
    if not pdfunite:
        append_service_log("admin", "school_plan_brochure_pdfunite_unavailable", target_pdf=str(target_pdf))
        raise RuntimeError("学校宣传册合并工具不可用，请检查 PDF 合并工具配置。")
    try:
        with tempfile.NamedTemporaryFile(
            suffix=".school-plan-brochure-divider.pdf",
            dir=target_pdf.parent,
            delete=False,
        ) as divider_file:
            divider_path = Path(divider_file.name)
            divider_file.write(school_plan_appendix_divider_pdf_bytes(report_year))
        temp_paths.append(divider_path)
        merge_inputs.append(divider_path)
        for brochure in brochure_rows:
            brochure_path = Path(brochure["file_path"])
            merge_inputs.append(brochure_path)
            attached.append({
                "document_id": brochure["id"],
                "school_id": brochure["school_id"],
                "document_type": brochure["document_type"],
                "file_name": brochure["original_filename"] or brochure["stored_filename"],
            })
        write_target = target_pdf
        if source_pdf.resolve() == target_pdf.resolve():
            write_target = target_pdf.with_name(f"{target_pdf.stem}.merge.tmp.pdf")
            temp_paths.append(write_target)
        result = subprocess.run(
            [str(pdfunite), *[str(path) for path in merge_inputs], str(write_target)],
            cwd=str(APP_DIR),
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            timeout=120,
        )
        if result.returncode != 0:
            raise RuntimeError((result.stderr or result.stdout or "pdfunite failed").strip())
        if write_target != target_pdf:
            write_target.replace(target_pdf)
        return attached
    except Exception as exc:
        append_service_log("admin", "school_plan_brochure_pdfunite_failed", repr(exc), target_pdf=str(target_pdf))
        raise RuntimeError("学校宣传册合并失败，请检查宣传册文件及 PDF 合并工具权限。") from exc
    finally:
        for temp_path in temp_paths:
            try:
                if temp_path.exists():
                    temp_path.unlink()
            except OSError:
                pass


def safe_log_path(file_name):
    if file_name not in SYSTEM_LOG_FILES:
        raise ValueError("日志文件不存在")
    if file_name.startswith("watchdog"):
        state_path = (WATCHDOG_STATE_DIR / file_name).resolve()
        if state_path.exists():
            ensure_within(state_path, WATCHDOG_STATE_DIR)
            return state_path
    path = (LOG_DIR / file_name).resolve()
    ensure_within(path, LOG_DIR)
    return path


def tail_text(path, max_bytes=160 * 1024):
    if not path.exists():
        return ""
    size = path.stat().st_size
    with path.open("rb") as fh:
        if size > max_bytes:
            fh.seek(size - max_bytes)
            prefix = b"... earlier log lines hidden ...\n"
        else:
            prefix = b""
        data = prefix + fh.read()
    return data.decode("utf-8", errors="replace")


def parse_log_timestamp(line):
    text = str(line or "").split(" | ", 1)[0].strip()
    if not text:
        return None
    try:
        return datetime.fromisoformat(text)
    except ValueError:
        return None


def human_duration_since(value):
    if not value:
        return "未知"
    if isinstance(value, str):
        parsed = parse_log_timestamp(value)
    else:
        parsed = value
    if not parsed:
        return "未知"
    seconds = max(0, int((datetime.now().astimezone() - parsed).total_seconds()))
    days, seconds = divmod(seconds, 86400)
    hours, seconds = divmod(seconds, 3600)
    minutes, _seconds = divmod(seconds, 60)
    if days:
        return f"{days}天 {hours}小时"
    if hours:
        return f"{hours}小时 {minutes}分钟"
    return f"{minutes}分钟"


def process_alive_from_pid_file(path):
    try:
        raw = Path(path).read_text(encoding="utf-8").strip()
        pid = int(raw) if raw else 0
    except (OSError, ValueError):
        return False, ""
    if not pid:
        return False, ""
    try:
        os.kill(pid, 0)
        return True, str(pid)
    except ProcessLookupError:
        return False, str(pid)
    except PermissionError:
        return True, str(pid)


def watchdog_file_candidates(file_name):
    candidates = [WATCHDOG_STATE_DIR / file_name, LOG_DIR / file_name]
    unique = []
    seen = set()
    for path in candidates:
        resolved = str(path)
        if resolved not in seen:
            seen.add(resolved)
            unique.append(path)
    return unique


def watchdog_log_lines():
    lines = []
    for path in watchdog_file_candidates("watchdog.log"):
        text = tail_text(path)
        if text:
            lines.extend(text.splitlines())
    return lines


def watchdog_pid_alive():
    for path in watchdog_file_candidates("watchdog.pid"):
        alive, pid = process_alive_from_pid_file(path)
        if alive:
            return True, pid
    return False, ""


def watchdog_lock_holder_pid():
    for path in watchdog_file_candidates("watchdog.lock"):
        lock_pid = watchdog_lock_holder_pid_for_path(path)
        if lock_pid:
            return lock_pid
    return ""


def watchdog_lock_holder_pid_for_path(path):
    try:
        result = subprocess.run(
            ["/usr/sbin/lsof", "-n", "-t", str(path)],
            cwd=str(APP_DIR),
            stdout=subprocess.PIPE,
            stderr=subprocess.DEVNULL,
            text=True,
            timeout=2,
            check=False,
        )
    except Exception:
        return ""
    for raw_pid in result.stdout.splitlines():
        pid = raw_pid.strip()
        if pid:
            return pid
    return ""


def health_snapshot_now():
    return datetime.now().astimezone()


def launch_agent_enabled_snapshot():
    domain = f"gui/{os.getuid()}"
    try:
        result = subprocess.run(
            ["/bin/launchctl", "print-disabled", domain],
            cwd=str(APP_DIR),
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            timeout=2,
            check=False,
        )
    except Exception as exc:
        return {"known": False, "text": "", "error": str(exc)}
    known = result.returncode == 0
    return {
        "known": known,
        "text": result.stdout if known else "",
        "error": "" if known else (result.stderr.strip() or "print-disabled failed"),
    }


def launch_agent_status(label, *, enabled_snapshot=None):
    domain = f"gui/{os.getuid()}"
    enabled_snapshot = enabled_snapshot or launch_agent_enabled_snapshot()
    try:
        result = subprocess.run(
            ["/bin/launchctl", "print", f"{domain}/{label}"],
            cwd=str(APP_DIR),
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            timeout=2,
            check=False,
        )
    except Exception as exc:
        return {
            **parse_launchctl_job("", loaded=False),
            "enabled": False,
            "error": str(exc),
        }
    enabled_state_known = bool(enabled_snapshot.get("known"))
    loaded = result.returncode == 0
    enabled = enabled_state_known and parse_launchctl_disabled(
        enabled_snapshot.get("text") or "", label
    )
    if not loaded:
        error = result.stderr.strip() or "LaunchAgent not loaded"
    elif not enabled_state_known:
        error = "LaunchAgent enabled state unavailable"
    else:
        error = ""
    return {
        **parse_launchctl_job(result.stdout, loaded=loaded),
        "enabled": enabled,
        "error": error,
    }


def listener_pids_for_port(port):
    try:
        result = subprocess.run(
            ["/usr/sbin/lsof", "-nP", f"-iTCP:{int(port)}", "-sTCP:LISTEN", "-t"],
            cwd=str(APP_DIR),
            stdout=subprocess.PIPE,
            stderr=subprocess.DEVNULL,
            text=True,
            timeout=2,
            check=False,
        )
    except Exception:
        return ()
    pids = []
    for line in result.stdout.splitlines():
        value = line.strip()
        if value.isdigit() and int(value) not in pids:
            pids.append(int(value))
    return tuple(pids)


def nas_recovery_heartbeat():
    heartbeat = {
        "path": str(NAS_RECOVERY_STATE_PATH),
        "last_run_at": "",
        "last_success_at": "",
        "last_result": "",
        "error": "",
    }
    try:
        state = json.loads(NAS_RECOVERY_STATE_PATH.read_text(encoding="utf-8"))
        if not isinstance(state, dict):
            raise ValueError("state payload is not an object")
        heartbeat["last_run_at"] = str(state.get("last_run_at") or "")
    except Exception as exc:
        heartbeat["error"] = f"{NAS_RECOVERY_STATE_PATH}: {type(exc).__name__}"
        return heartbeat
    try:
        events = tail_text(NAS_RECOVERY_EVENTS_PATH, max_bytes=256 * 1024).splitlines()
        for line in reversed(events):
            try:
                event = json.loads(line)
            except (TypeError, ValueError):
                continue
            if not heartbeat["last_result"]:
                heartbeat["last_result"] = str(event.get("recovery_result") or "")
            if (
                not heartbeat["last_success_at"]
                and event.get("recovery_result")
                in {"healthy", "recovered", "recovered_during_grace"}
            ):
                heartbeat["last_success_at"] = str(event.get("timestamp") or "")
            if heartbeat["last_result"] and heartbeat["last_success_at"]:
                break
    except OSError as exc:
        heartbeat["error"] = f"{NAS_RECOVERY_EVENTS_PATH}: {type(exc).__name__}"
    return heartbeat


def local_health_check(url):
    try:
        with urllib.request.urlopen(url, timeout=1.5) as response:
            payload = response.read(32 * 1024)
            data = json.loads(payload.decode("utf-8", errors="replace"))
            return {"online": 200 <= response.status < 300, "status": response.status, "data": data, "error": ""}
    except Exception as exc:
        return {"online": False, "status": 0, "data": {}, "error": str(exc)}


def authoritative_health_check(url, expected_fields):
    result = local_health_check(url)
    if not result.get("online"):
        return result
    data = result.get("data") or {}
    if not isinstance(data, dict):
        return {
            **result,
            "online": False,
            "data": {},
            "error": "health payload is not an object",
        }
    mismatches = [
        f"{key}={data.get(key)!r}"
        for key, expected in expected_fields.items()
        if data.get(key) != expected
    ]
    if mismatches:
        return {
            **result,
            "online": False,
            "error": "health identity mismatch: " + ", ".join(mismatches),
        }
    return result


def basic_health_payload(service_mode, port):
    database_status = "ok" if DB_PATH.is_file() else "missing"
    storage_status = "ok" if APP_DIR.is_dir() and os.access(APP_DIR, os.R_OK | os.W_OK) else "warning"
    nas_status = nas.status()
    nas_ready = bool(nas_status.get("ready"))
    return {
        "status": "ok",
        "service": service_mode,
        "port": port,
        "timestamp": now_iso(),
        "version": VERSION,
        **({"environment": getattr(STAGING, "mode", "staging"), "database_path": str(DB_PATH), "storage_path": str(STAGING.storage), "pid": os.getpid()} if STAGING else {}),
        **({"source_root": str(SOURCE_DIR), "config_sha256": STAGING.runtime_configuration.config_sha256} if getattr(STAGING, "runtime_configuration", None) is not None else {}),
        "business_write_gate": APP_WRITE_GATE.status() if APP_WRITE_GATE is not None else {"state": "NOT_CONFIGURED"},
        "dependencies": {
            "database": database_status,
            "storage": storage_status,
            "nas": "ok" if nas_ready else "warning",
        },
        "nas": {
            "ready": nas_ready,
            "root": nas_status.get("root", ""),
            "readable": bool(nas_status.get("readable")),
            "writable": bool(nas_status.get("writable")),
            "error_code": nas_status.get("access_error_code", ""),
            "message": nas_status.get("access_message") or nas_status.get("root_error", ""),
        },
    }


def deep_health_payload(service_mode, port):
    payload = basic_health_payload(service_mode, port)
    nas_status = payload["nas"]
    payload["checks"] = {
        "database_path": str(DB_PATH),
        "database_file_exists": DB_PATH.is_file(),
        "app_storage_path": str(APP_DIR),
        "app_storage_writable": os.access(APP_DIR, os.R_OK | os.W_OK),
        "logs_path": str(LOG_DIR),
        "logs_writable": os.access(LOG_DIR, os.R_OK | os.W_OK) if LOG_DIR.exists() else False,
        "school_storage_path": str(SCHOOL_LIBRARY_FILE_DIR),
        "school_storage_available": SCHOOL_LIBRARY_FILE_DIR.exists(),
        "nas_root": nas_status["root"],
        "nas_readable": nas_status["readable"],
        "nas_writable": nas_status["writable"],
        "nas_ready": nas_status["ready"],
        "google_drive_status": db.setting("GOOGLE_DRIVE_CONNECTION_STATUS", "Not Connected"),
    }
    payload["note"] = "Deep health is diagnostic only; /health stays lightweight and does not depend on Google Drive, LibreOffice, OCR, Cloudflare, or school crawler checks."
    return payload


def public_link_check():
    base = str(parent_form_base_url() or "").rstrip("/")
    if not base:
        return {"online": False, "url": "", "status": 0, "error": "Parent Form URL 未设置"}
    url = f"{base}/health"
    request = urllib.request.Request(
        url,
        headers={
            "Accept": "application/json",
            "User-Agent": "AAIECRM-Parent-Health/1.0",
        },
    )
    try:
        with urllib.request.urlopen(request, timeout=2.5) as response:
            payload = response.read(32 * 1024)
            data = json.loads(payload.decode("utf-8", errors="replace"))
            status = response.status
    except urllib.error.HTTPError as exc:
        return {"online": False, "url": url, "status": exc.code, "error": str(exc)}
    except Exception as exc:
        return {"online": False, "url": url, "status": 0, "error": str(exc)}
    result = {
        "online": 200 <= status < 300,
        "url": url,
        "status": status,
        "data": data,
        "error": "",
    }
    if not result["online"]:
        result["error"] = f"HTTP {status}"
        return result
    if not isinstance(data, dict):
        result["online"] = False
        result["data"] = {}
        result["error"] = "health payload is not an object"
        return result
    expected_fields = {"status": "ok", "service": "parent", "port": 8781}
    mismatches = [
        f"{key}={data.get(key)!r}"
        for key, expected in expected_fields.items()
        if data.get(key) != expected
    ]
    if mismatches:
        result["online"] = False
        result["error"] = "health identity mismatch: " + ", ".join(mismatches)
    return result


def latest_service_start(service):
    candidates = []
    service_log = LOG_DIR / f"{service}.log"
    if service_log.exists():
        for line in tail_text(service_log).splitlines():
            if "startup_requested" in line:
                stamp = parse_log_timestamp(line)
                if stamp:
                    candidates.append(stamp)
    for watchdog_log in watchdog_file_candidates("watchdog.log"):
        if watchdog_log.exists():
            needle = f"service={service}"
            for line in tail_text(watchdog_log).splitlines():
                if "service_started" in line and needle in line:
                    stamp = parse_log_timestamp(line)
                    if stamp:
                        candidates.append(stamp)
    return max(candidates) if candidates else None


def system_health_snapshot():
    now = health_snapshot_now()
    watchdog_alive, watchdog_pid = watchdog_pid_alive()
    if not watchdog_alive:
        lock_pid = watchdog_lock_holder_pid()
        if lock_pid:
            watchdog_alive, watchdog_pid = True, lock_pid
    enabled_snapshot = launch_agent_enabled_snapshot()
    with ThreadPoolExecutor(max_workers=12) as executor:
        probes = {
            "admin_job": executor.submit(
                launch_agent_status,
                ADMIN_LAUNCH_AGENT_LABEL,
                enabled_snapshot=enabled_snapshot,
            ),
            "parent_job": executor.submit(
                launch_agent_status,
                PARENT_LAUNCH_AGENT_LABEL,
                enabled_snapshot=enabled_snapshot,
            ),
            "nas_job": executor.submit(
                launch_agent_status,
                NAS_RECOVERY_LAUNCH_AGENT_LABEL,
                enabled_snapshot=enabled_snapshot,
            ),
            "content_job": executor.submit(
                launch_agent_status,
                CONTENT_EXTRACTION_LAUNCH_AGENT_LABEL,
                enabled_snapshot=enabled_snapshot,
            ),
            "admin_listener": executor.submit(listener_pids_for_port, 8780),
            "parent_listener": executor.submit(listener_pids_for_port, 8781),
            "content_listener": executor.submit(listener_pids_for_port, 8792),
            "admin_health": executor.submit(
                authoritative_health_check,
                "http://127.0.0.1:8780/health",
                {"status": "ok", "service": "admin", "port": 8780},
            ),
            "parent_health": executor.submit(
                authoritative_health_check,
                "http://127.0.0.1:8781/health",
                {"status": "ok", "service": "parent", "port": 8781},
            ),
            "content_health": executor.submit(
                authoritative_health_check,
                "http://127.0.0.1:8792/lifecycle-health",
                {
                    "ok": True,
                    "service_name": "content_extraction",
                    "port": 8792,
                    "source_mode": "production",
                },
            ),
            "public_link": executor.submit(public_link_check),
            "nas_heartbeat": executor.submit(nas_recovery_heartbeat),
        }
        observations = {name: future.result() for name, future in probes.items()}
    admin_health = observations["admin_health"]
    parent_health = observations["parent_health"]
    content_extraction_health = observations["content_health"]
    public_link = observations["public_link"]
    watchdog_lines = watchdog_log_lines()
    recent_lines = watchdog_lines[-30:]
    restarts_total = sum(1 for line in watchdog_lines if "service_started" in line)
    restarts_24h = 0
    failures_24h = 0
    last_restart = ""
    last_problem = ""
    last_health_ok = ""
    last_health_failed = ""
    last_watchdog = ""
    for line in watchdog_lines:
        stamp = parse_log_timestamp(line)
        if stamp and (now - stamp).total_seconds() <= 86400:
            if "service_started" in line:
                restarts_24h += 1
            if "health_check_failed" in line or "service_process_missing" in line or ("health_check_after_restart" in line and "failed" in line):
                failures_24h += 1
        if "watchdog_started" in line:
            last_watchdog = line
        if "service_started" in line:
            last_restart = line
        if "health_check_passed" in line or ("health_check_after_restart" in line and " ok " in f" {line} "):
            last_health_ok = line
        if "health_check_failed" in line or "service_process_missing" in line or "service_stop_error" in line or ("health_check_after_restart" in line and "failed" in line):
            last_problem = line
            last_health_failed = line
    admin_start = latest_service_start("admin")
    parent_start = latest_service_start("parent")
    watchdog_start = parse_log_timestamp(last_watchdog)
    legacy_watchdog = {
        "online": watchdog_alive,
        "pid": watchdog_pid,
        "uptime": human_duration_since(watchdog_start),
        "last_started": last_watchdog,
        "authority": False,
    }
    snapshot = resolve_system_health(
        admin_observation={
            "launch_agent": observations["admin_job"],
            "listener_pids": observations["admin_listener"],
            "health": admin_health,
            "uptime": human_duration_since(admin_start),
        },
        parent_observation={
            "launch_agent": observations["parent_job"],
            "listener_pids": observations["parent_listener"],
            "health": parent_health,
            "uptime": human_duration_since(parent_start),
        },
        nas_recovery_observation={
            "launch_agent": observations["nas_job"],
            "heartbeat": observations["nas_heartbeat"],
        },
        content_extraction_observation={
            "launch_agent": observations["content_job"],
            "listener_pids": observations["content_listener"],
            "health": content_extraction_health,
            "uptime": "由 8792 LaunchAgent 管理",
        },
        external_link=public_link,
        data_mode=nas.status().get("mode", "test"),
        legacy_watchdog=legacy_watchdog,
        now=now,
    )
    snapshot.update({
        # Compatibility aliases and metrics remain diagnostic-only. They are not
        # inputs to current service or monitor authority.
        "watchdog": legacy_watchdog,
        "metrics": {
            "restarts_total": restarts_total,
            "restarts_24h": restarts_24h,
            "failures_24h": failures_24h,
            "last_restart": last_restart,
            "last_problem": last_problem,
            "last_health_ok": last_health_ok,
            "last_health_failed": last_health_failed,
            "restart_loop_warning": restarts_24h >= 5 or failures_24h >= 10,
        },
        "recent_lines": recent_lines,
    })
    return snapshot


TOPBAR_HEALTH_CACHE_TTL_SECONDS = 10.0
TOPBAR_HEALTH_FAILURE_CACHE_TTL_SECONDS = 3.0
_TOPBAR_HEALTH_CACHE_CONDITION = threading.Condition()
_TOPBAR_HEALTH_CACHE = {
    "value": None,
    "expires_at": 0.0,
    "refreshing": False,
}


def cached_system_health_snapshot():
    while True:
        now = time.monotonic()
        with _TOPBAR_HEALTH_CACHE_CONDITION:
            value = _TOPBAR_HEALTH_CACHE["value"]
            if value is not None and now < _TOPBAR_HEALTH_CACHE["expires_at"]:
                return copy.deepcopy(value)
            if not _TOPBAR_HEALTH_CACHE["refreshing"]:
                _TOPBAR_HEALTH_CACHE["refreshing"] = True
                break
            _TOPBAR_HEALTH_CACHE_CONDITION.wait()
    try:
        value = system_health_snapshot()
    except Exception:
        with _TOPBAR_HEALTH_CACHE_CONDITION:
            _TOPBAR_HEALTH_CACHE["refreshing"] = False
            _TOPBAR_HEALTH_CACHE_CONDITION.notify_all()
        raise
    ttl = (
        TOPBAR_HEALTH_CACHE_TTL_SECONDS
        if value.get("overall_ok")
        else TOPBAR_HEALTH_FAILURE_CACHE_TTL_SECONDS
    )
    with _TOPBAR_HEALTH_CACHE_CONDITION:
        _TOPBAR_HEALTH_CACHE["value"] = copy.deepcopy(value)
        _TOPBAR_HEALTH_CACHE["expires_at"] = time.monotonic() + ttl
        _TOPBAR_HEALTH_CACHE["refreshing"] = False
        _TOPBAR_HEALTH_CACHE_CONDITION.notify_all()
    return copy.deepcopy(value)


def active_users_snapshot():
    cutoff = (datetime.now(timezone.utc).astimezone() - timedelta(minutes=ONLINE_USER_WINDOW_MINUTES)).isoformat(timespec="seconds")
    rows = db.all(
        """SELECT u.display_name,u.username,MAX(s.last_seen_at) last_seen_at
           FROM sessions s JOIN users u ON u.id=s.user_id
           WHERE s.expires_at>? AND s.last_seen_at>?
             AND u.is_active=1 AND u.deleted_at IS NULL
           GROUP BY u.id,u.display_name,u.username
           ORDER BY u.display_name""",
        (now_iso(), cutoff),
    )
    names = [row["display_name"] or row["username"] for row in rows]
    return {
        "count": len(rows),
        "names": names,
        "names_text": "、".join(names) or "暂无在线用户",
        "window_minutes": ONLINE_USER_WINDOW_MINUTES,
    }


