def local_year():
    return datetime.now().astimezone().year


def current_year():
    return local_year()


def rowdict(row):
    return dict(row) if row else None


def split_multi(form, name):
    value = form.get(name, [])
    if isinstance(value, list):
        return value
    return [value] if value else []


def parse_request_body(handler):
    length = int(handler.headers.get("Content-Length", "0") or 0)
    if length > MAX_REQUEST:
        raise ValueError("上传内容超过 250MB 限制")
    body = handler.rfile.read(length)
    content_type = handler.headers.get("Content-Type", "")
    if content_type.startswith("application/x-www-form-urlencoded"):
        raw = parse_qs(body.decode("utf-8"), keep_blank_values=True)
        form = {key: values if len(values) > 1 else values[0] for key, values in raw.items()}
        return form, []
    if content_type.startswith("multipart/form-data"):
        message = BytesParser(policy=default).parsebytes(
            b"Content-Type: " + content_type.encode("ascii", "ignore") + b"\r\nMIME-Version: 1.0\r\n\r\n" + body
        )
        form = {}
        files = []
        for part in message.iter_parts():
            disposition = part.get_content_disposition()
            if disposition != "form-data":
                continue
            name = part.get_param("name", header="content-disposition")
            filename = part.get_filename()
            payload = part.get_payload(decode=True) or b""
            if filename:
                files.append(Upload(name or "file", Path(filename).name, part.get_content_type(), payload))
            else:
                value = payload.decode(part.get_content_charset() or "utf-8", errors="replace")
                if name in form:
                    form[name] = form[name] if isinstance(form[name], list) else [form[name]]
                    form[name].append(value)
                else:
                    form[name] = value
        return form, files
    if content_type.startswith("application/json"):
        return json.loads(body or b"{}"), []
    return {}, []


def normalize_form(form):
    data = {}
    for name, meta in FIELD_MAP.items():
        if meta["type"] == "checkbox":
            data[name] = split_multi(form, name)
        else:
            value = form.get(name, "")
            normalized = value[-1] if isinstance(value, list) else value.strip() if isinstance(value, str) else value
            if (
                name == "higher_education_course_type"
                and normalized in {"", "请选择", "未选择", None}
            ):
                normalized = None
            data[name] = normalize_date_value(normalized) if name in DATE_FIELDS else normalized
    return data


def field_options_text(options):
    if not options:
        return ""
    labels = []
    for raw in options:
        value, _, label = raw.partition("|")
        labels.append(label or value)
    return " / ".join(labels)


def option_lookup(options):
    lookup = {}
    for raw in options or []:
        value, _, label = raw.partition("|")
        label = label or value
        lookup[value.strip()] = value.strip()
        lookup[label.strip()] = value.strip()
    return lookup


def normalize_import_value(name, value):
    meta = FIELD_MAP[name]
    if value is None:
        return [] if meta["type"] == "checkbox" else ""
    if isinstance(value, (datetime, date)):
        value = value.date() if isinstance(value, datetime) else value
        value = value.isoformat()
    else:
        value = str(value).strip()
    if not value:
        return [] if meta["type"] == "checkbox" else ""
    lookup = option_lookup(meta.get("options"))
    if meta["type"] == "checkbox":
        parts = [part.strip() for part in re.split(r"[,，;；、\n]+", value) if part.strip()]
        return [lookup.get(part, part) for part in parts]
    if lookup:
        return lookup.get(value, value)
    if name in DATE_FIELDS:
        return normalize_date_value(value)
    return value


def missing_student_fields(data, declaration_ok=True):
    missing = []
    parent_accompaniment_excluded_fields = {
        "accommodation_preference",
        "smoke_allergy",
        "food_allergy",
        "pet_allergy",
        "medicine_allergy",
    }
    for name in REQUIRED_FIELDS:
        if data.get("requires_parent_accompaniment") == "是" and name in parent_accompaniment_excluded_fields:
            continue
        if not data.get(name):
            missing.append(name)
    for name in DATE_FIELDS:
        if data.get(name) and not is_valid_date_value(data.get(name)):
            missing.append(name)
    stream = str(data.get("application_stream") or "").strip()
    if stream and stream not in {"school_education", "higher_education"}:
        missing.append("application_stream")
    if stream == "school_education" and not data.get("applying_year_level"):
        missing.append("applying_year_level")
    if stream == "higher_education":
        course_type = str(data.get("higher_education_course_type") or "").strip()
        if course_type not in {"Foundation", "Diploma", "Bachelor", "Postgraduate", "Package"}:
            missing.append("higher_education_course_type")
        if course_type == "Package" and str(data.get("higher_education_package_combination") or "").strip() not in {
            "Foundation + Bachelor", "Diploma + Bachelor", "Foundation + Diploma + Bachelor"
        }:
            missing.append("higher_education_package_combination")
    if not declaration_ok:
        missing.append("declaration")
    if data.get("requires_parent_accompaniment") == "是" and not data.get("accompanying_person_relationship"):
        missing.append("accompanying_person_relationship")
    if data.get("parents_australia_visa_refusal") == "有" and not data.get("parents_australia_visa_refusal_person"):
        missing.append("parents_australia_visa_refusal_person")
    return missing


def missing_student_labels(field_names):
    labels = []
    for name in field_names:
        if name == "declaration":
            labels.append("资料使用声明")
        else:
            labels.append(FIELD_MAP[name]["label"])
    return labels


def validate_student_data(data, declaration_ok=True):
    missing = missing_student_fields(data, declaration_ok)
    return missing_student_labels(missing)
    return missing


def ensure_student_template():
    TEMPLATE_DIR.mkdir(parents=True, exist_ok=True)
    if STUDENT_TEMPLATE_PATH.exists():
        try:
            existing = load_workbook(STUDENT_TEMPLATE_PATH, read_only=True, data_only=True)
            sheet = existing["学生信息表"]
            current_options = {
                name: field_options_text(meta.get("options"))
                for name, meta in FIELD_MAP.items()
            }
            for row in sheet.iter_rows(min_row=4, values_only=True):
                field_name = row[2]
                if field_name in FIELD_MAP and (
                    row[1] != FIELD_MAP[field_name]["label"]
                    or (row[5] or "") != current_options[field_name]
                ):
                    break
            else:
                return STUDENT_TEMPLATE_PATH
        except Exception:
            pass
    workbook = Workbook()
    sheet = workbook.active
    sheet.title = "学生信息表"
    sheet.append(["AAIE 学生信息导入模板"])
    sheet.append(["填写说明", "请只填写“家长/学生填写”这一列。不要修改字段名。日期请用 YYYY-MM-DD。多选可用顿号、逗号或换行分隔。"])
    sheet.append(["分区", "中文字段", "系统字段", "必填", "家长/学生填写", "可选项/说明"])
    sheet.freeze_panes = "A4"
    widths = {"A": 18, "B": 28, "C": 34, "D": 8, "E": 34, "F": 55}
    for col, width in widths.items():
        sheet.column_dimensions[col].width = width
    title_fill = PatternFill("solid", fgColor="1F5A75")
    header_fill = PatternFill("solid", fgColor="DCEBED")
    required_fill = PatternFill("solid", fgColor="FDECEC")
    sheet["A1"].font = Font(bold=True, color="FFFFFF", size=16)
    sheet["A1"].fill = title_fill
    sheet.merge_cells("A1:F1")
    sheet["A2"].alignment = Alignment(wrap_text=True, vertical="top")
    sheet.merge_cells("B2:F2")
    for cell in sheet[3]:
        cell.font = Font(bold=True)
        cell.fill = header_fill
        cell.alignment = Alignment(horizontal="center")
    row_number = 4
    for _, section_title, fields in SECTIONS:
        for name, label, kind, required, options in fields:
            sheet.append([section_title, label, name, "是" if required else "否", "", field_options_text(options)])
            row = sheet[row_number]
            if required:
                row[3].fill = required_fill
            row[4].alignment = Alignment(wrap_text=True, vertical="top")
            row[5].alignment = Alignment(wrap_text=True, vertical="top")
            if options and len(field_options_text(options)) < 250:
                validation = DataValidation(type="list", formula1=f'"{field_options_text(options).replace(" / ", ",")}"', allow_blank=not required)
                sheet.add_data_validation(validation)
                validation.add(row[4])
            if kind == "date":
                row[4].number_format = "yyyy-mm-dd"
            row[2].font = Font(color="5E6B73")
            row_number += 1
    sheet["E4"].comment = Comment("示例：ZHANG", "AAIE CRM")
    workbook.save(STUDENT_TEMPLATE_PATH)
    return STUDENT_TEMPLATE_PATH


def data_from_template_bytes(payload):
    workbook = load_workbook(io.BytesIO(payload), data_only=True)
    if "学生信息表" not in workbook.sheetnames:
        raise ValueError("模板中找不到“学生信息表”工作表")
    sheet = workbook["学生信息表"]
    data = {name: [] if meta["type"] == "checkbox" else "" for name, meta in FIELD_MAP.items()}
    found = set()
    for row in sheet.iter_rows(min_row=4, values_only=True):
        field_name = str(row[2] or "").strip() if len(row) > 2 else ""
        if field_name not in FIELD_MAP:
            continue
        data[field_name] = normalize_import_value(field_name, row[4] if len(row) > 4 else "")
        found.add(field_name)
    if len(found) < max(10, len(FIELD_MAP) // 2):
        raise ValueError("上传的 Excel 不是当前 AAIE CRM 学生信息模板，或字段名被修改")
    return data


def create_student_from_form(data, token_row=None, consultant_id=None, source_token=""):
    year = local_year()
    encrypted_password = ""
    if data.get("account_password"):
        encrypted_password = fernet().encrypt(data["account_password"].encode("utf-8")).decode("ascii")
    data_for_storage = dict(data)
    data_for_storage.pop("account_password", None)
    data_for_storage["parent_requested_pathway"] = derive_parent_requested_pathway(
        data_for_storage.get("higher_education_course_type"),
        data_for_storage.get("higher_education_package_combination"),
    ) if data_for_storage.get("application_stream") == "higher_education" else ""
    created = now_iso()
    assigned_consultant_id = consultant_id or (token_row["consultant_id"] if token_row else None)
    source_token = source_token or (token_row["token"] if token_row else "")

    with db.transaction() as conn:
        if token_row:
            current_token = conn.execute(
                "SELECT * FROM parent_form_tokens WHERE token=?",
                (token_row["token"],),
            ).fetchone()
            if not current_token:
                raise ParentFormNotFound("parent form link not found")
            if current_token["submitted_at"]:
                raise ParentFormSubmitted("parent form has already been submitted")
            if current_token["invalidated_at"]:
                raise ParentFormRevoked("parent form link has been revoked")
            if is_expired(current_token["expires_at"]):
                raise ParentFormExpired("parent form link has expired")
        seq = conn.execute("SELECT last_value FROM student_sequences WHERE year=?", (year,)).fetchone()
        number = (seq["last_value"] if seq else 0) + 1
        if number > 9999:
            raise RuntimeError("本年度 Student ID 流水号已用完")
        conn.execute(
            "INSERT INTO student_sequences(year,last_value) VALUES(?,?) ON CONFLICT(year) DO UPDATE SET last_value=excluded.last_value",
            (year, number),
        )
        student_id = f"{year}{number:04d}"
        conn.execute(
            """INSERT INTO students(
              student_id,passport_last_name,passport_first_name,english_nickname,gender,date_of_birth,
              current_year_level,application_stream,higher_education_course_type,higher_education_package_combination,parent_requested_pathway,preferred_intake_year,preferred_intake_term,applying_year_level,
              preferred_cities_json,visa_status,previous_name,home_address,home_postcode,australia_address,
              australia_postcode,home_phone,mobile_phone,student_email,consultant_id,current_status,
              nas_status,general_notes,source_token,created_date,updated_at,form_data_json
            ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,'New','pending',?,?,?,?,?)""",
            (
                student_id, data["passport_last_name"], data["passport_first_name"], data.get("english_nickname"),
                data.get("gender"), data.get("date_of_birth"), data.get("current_year_level"),
                data_for_storage.get("application_stream") or None,
                data_for_storage.get("higher_education_course_type") or None,
                data_for_storage.get("higher_education_package_combination") or None,
                data_for_storage.get("parent_requested_pathway") or None,
                data.get("preferred_intake_year"), data.get("preferred_intake_term"),
                data.get("applying_year_level"), json.dumps(data.get("preferred_cities", []), ensure_ascii=False),
                data.get("visa_status"), data.get("previous_name"), data.get("home_address"),
                data.get("home_postcode"), data.get("australia_address"), data.get("australia_postcode"),
                data.get("home_phone"), data.get("mobile_phone"), data.get("student_email"),
                assigned_consultant_id, data.get("general_notes"), source_token, created, created,
                json.dumps(data_for_storage, ensure_ascii=False),
            ),
        )
        for parent_type in ("father", "mother"):
            prefix = parent_type + "_"
            conn.execute(
                """INSERT INTO parents(student_id,parent_type,passport_last_name,passport_first_name,date_of_birth,
                   mobile,email,employer,work_address,work_postcode,work_phone,position,marital_status,religion,
                   highest_school,highest_qualification,migration_application_status,migration_notes)
                   VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                (
                    student_id, parent_type, data.get(prefix + "passport_last_name"),
                    data.get(prefix + "passport_first_name"), data.get(prefix + "date_of_birth"),
                    data.get(prefix + "mobile"), data.get(prefix + "email"), data.get(prefix + "employer"),
                    data.get(prefix + "work_address"), data.get(prefix + "work_postcode"),
                    data.get(prefix + "work_phone"), data.get(prefix + "position"),
                    data.get(prefix + "marital_status"), data.get(prefix + "religion"),
                    data.get(prefix + "highest_school"), data.get(prefix + "highest_qualification"),
                    data.get(prefix + "migration_application_status"), data.get(prefix + "migration_notes"),
                ),
            )
        sibling_fields = ("name", "gender", "dob", "school_company", "year_level")
        for idx in (1, 2):
            if any(data.get(f"sibling_{idx}_{field}") for field in sibling_fields):
                conn.execute(
                    """INSERT INTO siblings(student_id,sibling_order,name,gender,date_of_birth,school_company,year_level)
                       VALUES(?,?,?,?,?,?,?)""",
                    (
                        student_id, idx, data.get(f"sibling_{idx}_name"), data.get(f"sibling_{idx}_gender"),
                        data.get(f"sibling_{idx}_dob"), data.get(f"sibling_{idx}_school_company"),
                        data.get(f"sibling_{idx}_year_level"),
                    ),
                )
        for table, section_name in (
            ("accommodation_preferences", "accommodation"),
            ("health_declarations", "health"),
            ("visa_risk_info", "visa"),
            ("emergency_contacts", "emergency"),
        ):
            payload = {
                k: v for k, v in data_for_storage.items()
                if k in FIELD_MAP and FIELD_MAP[k]["section"] == section_name
            }
            conn.execute(f"INSERT INTO {table}(student_id,data_json) VALUES(?,?)", (student_id, json.dumps(payload, ensure_ascii=False)))
        study = {
            k: v for k, v in data_for_storage.items()
            if k in FIELD_MAP and FIELD_MAP[k]["section"] == "study"
        }
        conn.execute(
            "INSERT INTO study_background(student_id,data_json,account_password_encrypted) VALUES(?,?,?)",
            (student_id, json.dumps(study, ensure_ascii=False), encrypted_password),
        )
        conn.execute("INSERT INTO workflow_status(student_id,current_stage) VALUES(?,?)", (student_id, "建档"))
        if token_row:
            cursor = conn.execute(
                """UPDATE parent_form_tokens
                   SET submitted_at=?, student_id=?
                   WHERE token=?
                     AND submitted_at IS NULL
                     AND invalidated_at IS NULL
                     AND expires_at>?""",
                (created, student_id, token_row["token"], created),
            )
            if cursor.rowcount != 1:
                raise ParentFormSubmitted("parent form has already been submitted or revoked")
            ParentFormRepository(db).delete_draft(conn, token_row["token"])
        if is_workflow_v2_active(conn):
            record_application_lifecycle_event(
                conn,
                "PARENT_FORM_SUBMITTED" if token_row else "STUDENT_CREATED",
                occurred_at=created,
                actor_user_id=None,
                student_id=student_id,
                parent_form_token=token_row["token"] if token_row else None,
                education_stream=data.get("application_stream") or "school_education",
            )

    folder = None
    try:
        folder = nas.create_student_tree(student_id, data["passport_first_name"], data["passport_last_name"])
        student = db.one("SELECT * FROM students WHERE student_id=? AND deleted_at IS NULL", (student_id,))
        output, version = student_info_docx_version_path(folder / "Applications", student)
        generate_student_info(student, output)
        db.execute("UPDATE students SET folder_path=?,nas_status='ready',updated_at=? WHERE student_id=?", (str(folder), now_iso(), student_id))
        db.execute(
            """INSERT INTO student_documents(student_id,folder_category,document_type,original_name,stored_name,
               file_path,version,file_size,uploaded_at,is_active) VALUES(?,'Applications','StudentInfo',?,?,?,?,?,?,1)""",
            (student_id, output.name, output.name, str(output), version, output.stat().st_size, now_iso()),
        )
    except Exception as exc:
        db.execute("UPDATE students SET nas_status='error',updated_at=? WHERE student_id=?", (now_iso(), student_id))
        reminder_insert({
            "student_id": student_id,
            "reminder_type": "NAS setup failed",
            "due_date": datetime.now().astimezone().date().isoformat(),
            "notes": str(exc),
            "source_type": "student_storage",
            "source_record_id": student_id,
            "source_module": "storage",
            "source_object_type": "student",
            "source_object_id": student_id,
            "source_event_type": "student_storage.setup_failed",
        })
    return student_id


def ensure_student_storage(student):
    if student["folder_path"]:
        folder = nas.student_folder(student)
        folder.mkdir(parents=True, exist_ok=True)
        for name in STANDARD_FOLDERS:
            ensure_within(folder / name, folder).mkdir(exist_ok=True)
    else:
        folder = nas.create_student_tree(student["student_id"], student["passport_first_name"], student["passport_last_name"])
    refreshed = db.one("SELECT * FROM students WHERE student_id=?", (student["student_id"],))
    existing = db.one(
        """SELECT * FROM student_documents
           WHERE student_id=? AND document_type='StudentInfo' AND is_active=1
           ORDER BY version DESC,id DESC LIMIT 1""",
        (student["student_id"],),
    )
    if existing:
        existing = ensure_student_info_document_filename(refreshed, existing)
    existing_path = Path(existing["file_path"]) if existing and existing["file_path"] else None
    if not existing_path or not existing_path.is_file():
        output, version = student_info_docx_version_path(folder / "Applications", refreshed)
        generate_student_info(refreshed, output)
        db.execute(
            """INSERT INTO student_documents(student_id,folder_category,document_type,original_name,stored_name,
               file_path,version,file_size,uploaded_at,is_active) VALUES(?,'Applications','StudentInfo',?,?,?,?,?,?,1)""",
            (student["student_id"], output.name, output.name, str(output), version, output.stat().st_size, now_iso()),
        )
    db.execute("UPDATE students SET folder_path=?,nas_status='ready',updated_at=? WHERE student_id=?", (str(folder), now_iso(), student["student_id"]))
    return db.one("SELECT * FROM students WHERE student_id=?", (student["student_id"],))


def get_permissions(user):
    if not user:
        return []
    try:
        return json.loads(user["permissions_json"])
    except Exception:
        return []


def allowed(user, permission):
    permissions = get_permissions(user)
    return "*" in permissions or permission in permissions


MODULE_LABELS = {key: zh for key, _en, zh, _route, _order, _category in MODULE_DEFINITIONS}
MODULE_EN_LABELS = {key: en for key, en, _zh, _route, _order, _category in MODULE_DEFINITIONS}
SECTION_LABELS = {section_id: title for section_id, title, _fields in SECTIONS}
CONTENT_CENTER_ALLOWED_USERNAMES = {"admin", "sonnyz"}
SAFEBOX_STATUSES = ("进行中", "已完成", "稳定基准", "有问题", "测试失败", "未提交", "有风险", "已废弃")
PROFILE_SECTION_ORDER = [
    "basic", "contact", "siblings", "father", "mother", "accommodation",
    "health", "visa", "study", "emergency", "notes",
]


def role_module_preset(role_name):
    return set(ROLE_MODULE_PRESETS.get(role_name or "", ROLE_MODULE_PRESETS.get("View Only", [])))


def form_text_value(form, key, default=""):
    value = form.get(key, default)
    if isinstance(value, list):
        value = value[-1] if value else default
    return str(value if value is not None else "").strip()


def safebox_clean_status(value):
    status = str(value or "").strip()
    return status if status in SAFEBOX_STATUSES else "进行中"


def safebox_database_changed_value(form):
    return 1 if form_text_value(form, "database_changed").lower() in {"1", "true", "yes", "on", "是"} else 0


def safebox_status_class(status):
    return {
        "进行中": "info",
        "已完成": "ok",
        "稳定基准": "ok",
        "有问题": "warn",
        "测试失败": "danger",
        "未提交": "warn",
        "有风险": "warn",
        "已废弃": "neutral",
    }.get(status, "neutral")


def safebox_restore_instruction(record):
    if "restore_instruction" in record.keys() and record["restore_instruction"]:
        return record["restore_instruction"]
    database_changed = "是" if int(record["database_changed"] or 0) else "否"
    return "\n".join([
        "请按 SAFEBOX 流程恢复到以下记录：",
        f"SAFEBOX 名称：{record['safebox_name'] or ''}",
        f"分支名：{record['branch_name'] or ''}",
        f"修改前 commit：{record['before_commit'] or ''}",
        f"修改后 commit：{record['after_commit'] or ''}",
        f"备份目录：{record['backup_dir'] or ''}",
        "需要检查的文件：",
        record["modified_files"] or "未记录",
        f"数据库是否变更：{database_changed}",
        "回滚建议：",
        record["rollback_advice"] or "先创建新的恢复分支，人工检查文件和数据库备份；不要直接执行 git reset。",
        "",
        "注意：本按钮只复制文本，不执行 git reset，不恢复数据库。",
    ])


def restore_calendar_parse_stamp(value):
    try:
        return datetime.strptime(str(value), "%Y%m%d_%H%M%S")
    except (TypeError, ValueError):
        return None


def restore_calendar_health_text(value):
    if isinstance(value, dict):
        if value.get("ok") is True:
            return "ok"
        if value.get("ok") is False:
            return value.get("error") or value.get("body") or "failed"
        return json.dumps(value, ensure_ascii=False)
    if value in (None, ""):
        return "未记录"
    return str(value)


def restore_calendar_type_info(meta, source_kind, read_error=""):
    raw_type = str((meta or {}).get("restore_point_type") or "").strip().lower()
    status = str((meta or {}).get("restore_point_status") or "").strip().lower()
    if read_error:
        return "failed", "Failed", "metadata 缺失 / 无法读取"
    if raw_type == "stable":
        return "stable", "Stable Restore Point", ""
    if raw_type in {"dirty_backup", "dirty"} or source_kind == "dirty":
        return "dirty", "Dirty Backup", ""
    if raw_type in {"skipped", "failed_precheck"} or status in {"not_created", "skipped", "failed"}:
        reason = (meta or {}).get("skip_reason") or (meta or {}).get("notes") or "precheck failed"
        return "skipped", "Skipped", str(reason)
    return "failed", "Failed", "metadata 缺失 / 无法读取"


def restore_calendar_metadata_summary(meta, read_error=""):
    if read_error:
        return read_error
    summary = {
        "restore_point_type": meta.get("restore_point_type"),
        "restore_point_status": meta.get("restore_point_status"),
        "branch": meta.get("branch"),
        "commit": meta.get("commit"),
        "git_status_clean": meta.get("git_status_clean"),
        "db_quick_check": meta.get("db_quick_check"),
        "latest_stable_tag": meta.get("latest_stable_tag"),
        "notes": meta.get("notes"),
    }
    return json.dumps(summary, ensure_ascii=False, indent=2)


def restore_calendar_restore_plan(point):
    meta = point["metadata"]
    check_first = "\n".join([
        "恢复前必须先人工备份当前状态。",
        "本计划只供复制和人工核对，不自动执行。",
        f"Restore point path: {point['path']}",
        f"Commit: {meta.get('commit') or ''}",
    ])
    if point["category"] == "stable":
        db_backup = Path(point["path"]) / "database" / "aaie_crm.db"
        return "\n".join([
            "Stable Restore Point 恢复计划（人工执行前核对）",
            check_first,
            f"Database backup path: {db_backup}",
            "确认 metadata.json 中 restore_point_type=stable。",
            "确认 PRAGMA quick_check 为 ok。",
            "确认恢复前已经创建当前状态备份。",
            "不要自动执行恢复；由管理员人工决定 Git 和数据库恢复步骤。",
        ])
    if point["category"] == "dirty":
        return "\n".join([
            "Dirty Worktree Backup 检查计划",
            check_first,
            f"Git diff patch: {Path(point['path']) / 'git.diff.patch'}",
            f"Modified files backup: {Path(point['path']) / 'modified_files'}",
            "这不是稳定恢复点，只建议人工比较 patch 和备份文件。",
            "不建议直接覆盖任何文件。",
        ])
    return "\n".join([
        "Skipped / Failed Restore Point 检查计划",
        check_first,
        f"Reason: {point['reason'] or point['read_error'] or 'unknown'}",
        "该记录不能作为稳定恢复点。",
    ])


def restore_calendar_precheck_command():
    workspace = str(Path(__file__).resolve().parent)
    return "\n".join([
        f'cd "{workspace}"',
        "git status --short",
        "git branch --show-current",
        "git log --oneline -1",
        "sqlite3 database/aaie_crm.db 'PRAGMA quick_check;'",
    ])


def restore_calendar_load_points(root):
    root = Path(root)
    points = []
    sources = (
        ("hourly", root / "backups" / "restore-points" / "hourly"),
        ("dirty", root / "backups" / "restore-points" / "dirty"),
    )
    for source_kind, base in sources:
        if not base.is_dir():
            continue
        for folder in sorted(base.iterdir()):
            if not folder.is_dir():
                continue
            stamp = restore_calendar_parse_stamp(folder.name)
            if not stamp:
                continue
            metadata_path = folder / "metadata.json"
            meta = {}
            read_error = ""
            if not metadata_path.is_file():
                read_error = "metadata 缺失 / 无法读取"
            else:
                try:
                    meta = json.loads(metadata_path.read_text(encoding="utf-8"))
                    if not isinstance(meta, dict):
                        meta = {}
                        read_error = "metadata 缺失 / 无法读取"
                except (OSError, json.JSONDecodeError, UnicodeDecodeError):
                    meta = {}
                    read_error = "metadata 缺失 / 无法读取"
            category, label, reason = restore_calendar_type_info(meta, source_kind, read_error)
            points.append({
                "id": f"{source_kind}:{folder.name}",
                "source_kind": source_kind,
                "stamp": stamp,
                "date": stamp.strftime("%Y-%m-%d"),
                "month": stamp.strftime("%Y-%m"),
                "hour": stamp.strftime("%H:%M"),
                "path": str(folder),
                "metadata": meta,
                "metadata_path": str(metadata_path),
                "read_error": read_error,
                "category": category,
                "label": label,
                "reason": reason,
                "metadata_summary": restore_calendar_metadata_summary(meta, read_error),
            })
    return sorted(points, key=lambda item: item["stamp"])


def restore_calendar_counts(points):
    by_date = {}
    for point in points:
        counts = by_date.setdefault(point["date"], {"stable": 0, "dirty": 0, "skipped": 0, "failed": 0})
        counts[point["category"]] = counts.get(point["category"], 0) + 1
    return by_date


def restore_calendar_month_days(month_value):
    try:
        first = datetime.strptime(month_value, "%Y-%m").date().replace(day=1)
    except (TypeError, ValueError):
        today = date.today()
        first = today.replace(day=1)
    if first.month == 12:
        next_month = first.replace(year=first.year + 1, month=1)
    else:
        next_month = first.replace(month=first.month + 1)
    days = []
    cursor = first - timedelta(days=first.weekday())
    while cursor < next_month or cursor.weekday() != 0:
        days.append(cursor)
        cursor += timedelta(days=1)
    return first.strftime("%Y-%m"), days


def profile_sections():
    by_id = {section_id: (section_id, title, fields) for section_id, title, fields in SECTIONS}
    ordered = [by_id[section_id] for section_id in PROFILE_SECTION_ORDER if section_id in by_id]
    ordered.extend(section for section in SECTIONS if section[0] not in PROFILE_SECTION_ORDER)
    return localized_profile_sections(ordered)


