def user_module_keys(user):
    if not user:
        return set()
    if user.get("role_name") == "Admin":
        keys = {key for key, *_ in MODULE_DEFINITIONS}
        if not is_content_center_allowed_user(user):
            keys.discard("content_center")
        return keys
    raw = user.get("module_permissions_json") or "[]"
    try:
        keys = set(json.loads(raw))
    except Exception:
        keys = role_module_preset(user.get("role_name"))
    if is_content_center_allowed_user(user):
        keys.add("content_center")
    else:
        keys.discard("content_center")
    return keys


def can_access_module(user, module_key):
    if module_key == "agent_reach":
        return can_access_agent_reach(user)
    if not module_key:
        return True
    if module_key == "content_center":
        return is_content_center_allowed_user(user)
    if module_key in {"student_contracts", "contract_management_center"}:
        return can_access_contract_module(user, module_key)
    if module_key == REVENUE_MODULE_KEY:
        return can_access_revenue(user)
    return module_key in user_module_keys(user)


