        "can_edit_scripts", "can_review_scripts", "can_approve_scripts",
        "can_schedule_posts", "can_mark_published", "can_enter_performance_data",
        "can_view_performance", "can_manage_material_library", "can_import_old_data",
        "can_upload_documents", "can_review_features", "can_edit_zone_data",
        "can_edit_academic_info", "can_upload_logo", "can_run_scraper",
        "can_view_reports", "can_generate_reports",
