def can_review_module_action(user, module, action="upload"):
    config = MODULE_REVIEW_CONFIG.get(module, {})
    module_key = REVIEW_MODULE_KEYS.get(module)
    if allowed(user, config.get("permission", "")):
        return True
    if not module_key or not can_access_module(user, module_key):
        return False
    if action == "view":
        return can_module_action(user, module_key, "view") or can_module_action(user, module_key, "upload")
    if action == "confirm":
        return (
            can_module_action(user, module_key, "confirm_upload_review")
            or can_module_action(user, module_key, "upload")
            or can_module_action(user, module_key, "create")
        )
    return can_module_action(user, module_key, action)


def can_workflow_module_save(user, module):
    config = MODULE_REVIEW_CONFIG.get(module, {})
    module_key = REVIEW_MODULE_KEYS.get(module)
    if allowed(user, config.get("permission", "")):
        return True
    if not module_key or not can_access_module(user, module_key):
        return False
    return any(
        can_module_action(user, module_key, action)
        for action in ("edit", "create", "upload", "confirm_upload_review")
    )


