def save_user_module_permissions(user_id, module_keys, updated_by, role_name=None):
    selected = set(module_keys)
    target = db.one("SELECT u.username,r.name role_name FROM users u JOIN roles r ON r.id=u.role_id WHERE u.id=?", (user_id,))
    if not role_name:
        role_name = target["role_name"] if target else ""
    role_row = db.one("SELECT permissions_json FROM roles WHERE name=?", (role_name,)) if role_name else None
    role_permissions = set(json.loads(role_row["permissions_json"])) if role_row else set()
    stamp = now_iso()
    for key, *_ in MODULE_DEFINITIONS:
        can_access = 1 if key in selected else 0
        school_manager = can_access and key == "school_library" and role_name in {"Admin", "Manager"}
        can_edit = 1 if can_access and (role_name == "Admin" or school_manager or (key == "students" and "students.edit" in role_permissions)) else 0
        workflow_upload = can_access and key in {"applications", "offer", "coe_oshc", "visa", "payments"} and role_name != "View Only"
        workflow_review = workflow_upload and key in {"applications", "offer", "coe_oshc", "payments"}
        file_manager_full = can_access and key == "file_manager" and role_name in {"Admin", "Manager"}
        file_manager_restore = can_access and key == "file_manager" and role_name == "Admin"
        db.execute(
            """INSERT INTO user_module_permissions(
               user_id,module_key,can_access,can_view,can_edit,can_open,can_download,can_upload,can_mark_delete,
               can_mark_move,can_mark_rename,can_cancel_file_marker,can_mark_file_marker_processed,
               can_restore,can_create,can_confirm_upload_review,created_at,updated_at,updated_by
            ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
               ON CONFLICT(user_id,module_key) DO UPDATE SET
                 can_access=excluded.can_access,
                 can_view=excluded.can_view,
                 can_create=excluded.can_create,
                 can_edit=excluded.can_edit,
                 can_open=excluded.can_open,
                 can_download=excluded.can_download,
                 can_upload=excluded.can_upload,
                 can_mark_delete=excluded.can_mark_delete,
                 can_mark_move=excluded.can_mark_move,
                 can_mark_rename=excluded.can_mark_rename,
                 can_cancel_file_marker=excluded.can_cancel_file_marker,
                 can_mark_file_marker_processed=excluded.can_mark_file_marker_processed,
                 can_restore=excluded.can_restore,
                 can_confirm_upload_review=excluded.can_confirm_upload_review,
                 updated_at=excluded.updated_at,
                 updated_by=excluded.updated_by""",
            (
                user_id, key, can_access, can_access, can_edit,
                0,
                1 if file_manager_full else 0,
                1 if file_manager_full or workflow_upload or school_manager else 0,
                1 if file_manager_full else 0,
                1 if file_manager_full else 0,
                1 if file_manager_full else 0,
                1 if file_manager_full else 0,
                1 if file_manager_full else 0,
                1 if file_manager_restore else 0,
                1 if workflow_upload or school_manager else 0,
                1 if workflow_review else 0,
                stamp, stamp, updated_by,
            ),
        )
        if key == "reminders":
            reminder_manager = can_access and role_name in {"Admin", "Manager"}
            reminder_staff = can_access and role_name in {"Consultant", "Visa Officer", "Finance"}
            db.execute(
                """UPDATE user_module_permissions SET
                   can_create=?,can_edit=?,can_complete=?,can_dismiss=?,can_reassign=?,can_manage_rules=?
                   WHERE user_id=? AND module_key='reminders'""",
                (
                    1 if reminder_manager or reminder_staff else 0,
                    1 if reminder_manager else 0,
                    1 if reminder_manager or reminder_staff else 0,
                    1 if reminder_manager or reminder_staff else 0,
                    1 if reminder_manager else 0,
                    1 if can_access and role_name == "Admin" else 0,
                    user_id,
                ),
            )
        if key == "content_center":
            content_allowed = bool(target and str(target["username"] or "").strip().lower() in CONTENT_CENTER_ALLOWED_USERNAMES)
            content_full = can_access and content_allowed
            content_view = can_access and content_allowed
            db.execute(
                """UPDATE user_module_permissions SET
                   can_view_dashboard=?,can_view_topics=?,can_create_topics=?,can_edit_topics=?,
                   can_generate_scripts=?,can_edit_scripts=?,can_review_scripts=?,can_approve_scripts=?,
                   can_schedule_posts=?,can_mark_published=?,can_enter_performance_data=?,
                   can_view_performance=?,can_manage_material_library=?,can_import_old_data=?
                   WHERE user_id=? AND module_key='content_center'""",
                (
                    1 if content_view or content_full else 0,
                    1 if content_view or content_full else 0,
                    1 if content_full else 0,
                    1 if content_full else 0,
                    1 if content_full else 0,
                    1 if content_full else 0,
                    1 if content_full else 0,
                    1 if content_full else 0,
                    1 if content_full else 0,
                    1 if content_full else 0,
                    1 if content_full else 0,
                    1 if content_view or content_full else 0,
                    1 if content_full else 0,
                    1 if content_full else 0,
                    user_id,
                ),
            )


