def display_field_value(value):
    if isinstance(value, list):
        return "、".join(str(item) for item in value)
    return str(value if value is not None else "")


def student_account_password(student_id):
    row = db.one("SELECT account_password_encrypted FROM study_background WHERE student_id=?", (student_id,))
    if not row or not row["account_password_encrypted"]:
        return ""
    try:
        return fernet().decrypt(row["account_password_encrypted"].encode("ascii")).decode("utf-8")
    except Exception:
        return ""


def student_profile_changes(old_data, new_data):
    changes = []
    for name, meta in FIELD_MAP.items():
        if name == "account_password":
            continue
        old_value = old_data.get(name, [] if meta["type"] == "checkbox" else "")
        new_value = new_data.get(name, [] if meta["type"] == "checkbox" else "")
        if display_field_value(old_value) != display_field_value(new_value):
            changes.append({
                "section": SECTION_LABELS.get(meta["section"], meta["section"]),
                "field_name": name,
                "field_label": meta["label"],
                "old_value": display_field_value(old_value),
                "new_value": display_field_value(new_value),
            })
    return changes


def replace_student_related_records(conn, student_id, data_for_storage, account_password=""):
    conn.execute("DELETE FROM parents WHERE student_id=?", (student_id,))
    for parent_type in ("father", "mother"):
        prefix = parent_type + "_"
        conn.execute(
            """INSERT INTO parents(student_id,parent_type,passport_last_name,passport_first_name,date_of_birth,
               mobile,email,employer,work_address,work_postcode,work_phone,position,marital_status,religion,
               highest_school,highest_qualification,migration_application_status,migration_notes)
               VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
            (
                student_id, parent_type, data_for_storage.get(prefix + "passport_last_name"),
                data_for_storage.get(prefix + "passport_first_name"), data_for_storage.get(prefix + "date_of_birth"),
                data_for_storage.get(prefix + "mobile"), data_for_storage.get(prefix + "email"), data_for_storage.get(prefix + "employer"),
                data_for_storage.get(prefix + "work_address"), data_for_storage.get(prefix + "work_postcode"),
                data_for_storage.get(prefix + "work_phone"), data_for_storage.get(prefix + "position"),
                data_for_storage.get(prefix + "marital_status"), data_for_storage.get(prefix + "religion"),
                data_for_storage.get(prefix + "highest_school"), data_for_storage.get(prefix + "highest_qualification"),
                data_for_storage.get(prefix + "migration_application_status"), data_for_storage.get(prefix + "migration_notes"),
            ),
        )
    conn.execute("DELETE FROM siblings WHERE student_id=?", (student_id,))
    sibling_fields = ("name", "gender", "dob", "school_company", "year_level")
    for idx in (1, 2):
        if any(data_for_storage.get(f"sibling_{idx}_{field}") for field in sibling_fields):
            conn.execute(
                """INSERT INTO siblings(student_id,sibling_order,name,gender,date_of_birth,school_company,year_level)
                   VALUES(?,?,?,?,?,?,?)""",
                (
                    student_id, idx, data_for_storage.get(f"sibling_{idx}_name"), data_for_storage.get(f"sibling_{idx}_gender"),
                    data_for_storage.get(f"sibling_{idx}_dob"), data_for_storage.get(f"sibling_{idx}_school_company"),
                    data_for_storage.get(f"sibling_{idx}_year_level"),
                ),
            )
    for table, section_name in (
        ("accommodation_preferences", "accommodation"),
        ("health_declarations", "health"),
        ("visa_risk_info", "visa"),
        ("emergency_contacts", "emergency"),
    ):
        payload = {
            k: v for k, v in data_for_storage.items()
            if k in FIELD_MAP and FIELD_MAP[k]["section"] == section_name
        }
        conn.execute(f"DELETE FROM {table} WHERE student_id=?", (student_id,))
        conn.execute(f"INSERT INTO {table}(student_id,data_json) VALUES(?,?)", (student_id, json.dumps(payload, ensure_ascii=False)))
    study = {
        k: v for k, v in data_for_storage.items()
        if k in FIELD_MAP and FIELD_MAP[k]["section"] == "study"
    }
    existing_study = conn.execute("SELECT account_password_encrypted FROM study_background WHERE student_id=?", (student_id,)).fetchone()
    if account_password:
        encrypted_password = fernet().encrypt(account_password.encode("utf-8")).decode("ascii")
    else:
        encrypted_password = existing_study["account_password_encrypted"] if existing_study else ""
    conn.execute("DELETE FROM study_background WHERE student_id=?", (student_id,))
    conn.execute(
        "INSERT INTO study_background(student_id,data_json,account_password_encrypted) VALUES(?,?,?)",
        (student_id, json.dumps(study, ensure_ascii=False), encrypted_password),
    )


def update_student_profile(student, data, user, ip="", user_agent=""):
    old_data = student_form_values(student)
    account_password = str(data.get("account_password") or "")
    data_for_storage = dict(data)
    data_for_storage.pop("account_password", None)
    data_for_storage["parent_requested_pathway"] = derive_parent_requested_pathway(
        data_for_storage.get("higher_education_course_type"),
        data_for_storage.get("higher_education_package_combination"),
    ) if data_for_storage.get("application_stream") == "higher_education" else ""
    changes = student_profile_changes(old_data, data_for_storage)
    changed_at = now_iso()
    with db.transaction() as conn:
        conn.execute(
            """UPDATE students SET passport_last_name=?,passport_first_name=?,english_nickname=?,gender=?,
               date_of_birth=?,current_year_level=?,application_stream=?,higher_education_course_type=?,higher_education_package_combination=?,parent_requested_pathway=?,preferred_intake_year=?,preferred_intake_term=?,
               applying_year_level=?,preferred_cities_json=?,visa_status=?,previous_name=?,home_address=?,
               home_postcode=?,australia_address=?,australia_postcode=?,home_phone=?,mobile_phone=?,
               student_email=?,general_notes=?,updated_at=?,updated_by=?,form_data_json=? WHERE student_id=?""",
            (
                data_for_storage["passport_last_name"], data_for_storage["passport_first_name"],
                data_for_storage.get("english_nickname"), data_for_storage.get("gender"),
                data_for_storage.get("date_of_birth"), data_for_storage.get("current_year_level"),
                data_for_storage.get("application_stream"), data_for_storage.get("higher_education_course_type"),
                data_for_storage.get("higher_education_package_combination"), data_for_storage.get("parent_requested_pathway"),
                data_for_storage.get("preferred_intake_year"), data_for_storage.get("preferred_intake_term"),
                data_for_storage.get("applying_year_level"), json.dumps(data_for_storage.get("preferred_cities", []), ensure_ascii=False),
                data_for_storage.get("visa_status"), data_for_storage.get("previous_name"), data_for_storage.get("home_address"),
                data_for_storage.get("home_postcode"), data_for_storage.get("australia_address"), data_for_storage.get("australia_postcode"),
                data_for_storage.get("home_phone"), data_for_storage.get("mobile_phone"), data_for_storage.get("student_email"),
                data_for_storage.get("general_notes"), changed_at, user["id"], json.dumps(data_for_storage, ensure_ascii=False),
                student["student_id"],
            ),
        )
        replace_student_related_records(conn, student["student_id"], data_for_storage, account_password)
        for change in changes:
            conn.execute(
                """INSERT INTO student_change_logs(student_id,changed_by,changed_by_username,section,field_name,old_value,new_value,changed_at)
                   VALUES(?,?,?,?,?,?,?,?)""",
                (
                    student["student_id"], user["id"], user["username"], change["section"], change["field_name"],
                    change["old_value"], change["new_value"], changed_at,
                ),
            )
    if changes:
        db.audit(
            user, "student_profile_updated", "students", student["student_id"],
            old_value=json.dumps([{k: c[k] for k in ("section", "field_name", "old_value")} for c in changes], ensure_ascii=False),
            new_value=json.dumps([{k: c[k] for k in ("section", "field_name", "new_value")} for c in changes], ensure_ascii=False),
            ip=ip, device=user_agent, student_id=student["student_id"],
        )
    return changes


def regenerate_student_info_version(student, user):
    if student["nas_status"] != "ready" or not student["folder_path"]:
        raise ValueError("学生文件夹尚未就绪，不能重新生成 StudentInfo.docx。")
    root = nas.student_folder(student)
    folder = ensure_within(root / "Applications", root)
    folder.mkdir(exist_ok=True)
    target, version = student_info_docx_version_path(folder, student)
    generate_student_info(student, target)
    db.execute(
        """INSERT INTO student_documents(student_id,folder_category,document_type,original_name,stored_name,
           file_path,version,file_size,uploaded_by,uploaded_at,preview_path,is_active)
           VALUES(?,'Applications','StudentInfo',?,?,?,?,?,?,?,?,1)""",
        (student["student_id"], target.name, target.name, str(target), version, target.stat().st_size, user["id"], now_iso(), ""),
    )
    db.audit(user, "student_info_docx_regenerated", "students", student["student_id"], file_path=str(target), student_id=student["student_id"])
    return target


def detect_document_type(filename):
    compact = re.sub(r"[^A-Za-z0-9]", "", filename).lower()
    if "transcript" in compact:
        return "Transcripts"
    if "passport" in compact:
        if any(token in compact for token in ("father", "dad", "papa")):
            return "FatherPassport"
        if any(token in compact for token in ("mother", "mom", "mum", "mama")):
            return "MotherPassport"
        if "guardian" in compact:
            return "GuardianPassport"
        return "StudentPassport"
    for kind in DOCUMENT_TYPES:
        if re.sub(r"[^A-Za-z0-9]", "", kind).lower() in compact:
            return kind
    return "Others"


def document_type_label(kind):
    return DOCUMENT_TYPE_LABELS.get(kind, kind)


def module_document_type_label(module, kind):
    if kind in OPTIONAL_MODULE_DOCUMENT_TYPES.get(module, set()):
        return f"{document_type_label(kind)}（可选）"
    if module == "Payments":
        return PAYMENT_DOCUMENT_TYPE_LABELS.get(kind, kind)
    return document_type_label(kind)


def module_document_types(module):
    return MODULE_DOCUMENT_TYPES.get(module, [])


def is_optional_module_document_type(module, kind):
    return kind in OPTIONAL_MODULE_DOCUMENT_TYPES.get(module, set())


def file_size_label(size):
    try:
        value = float(size or 0)
    except Exception:
        value = 0
    for unit in ("B", "KB", "MB", "GB"):
        if value < 1024 or unit == "GB":
            return f"{value:.0f} {unit}" if unit == "B" else f"{value:.1f} {unit}"
        value /= 1024
    return f"{value:.1f} GB"


def safe_file_manager_component(value, label="路径"):
    raw = str(value or "").strip()
    if not raw or "/" in raw or "\\" in raw or raw in {".", ".."} or ".." in Path(raw).parts:
        raise NasSafetyError(f"{label}无效")
    return raw


def file_manager_root():
    return nas.active_root()


def file_manager_resolve(year="", student="", folder="", file_name=""):
    root = file_manager_root()
    if year and safe_file_manager_component(year, "年份") != root.name:
        raise NasSafetyError("文件管理只能访问当前已授权的学生存储根目录")
    target = root
    student_name = ""
    module_folder = ""
    if student:
        student_name = safe_file_manager_component(student, "学生文件夹")
        target = ensure_within(root / student_name, root)
    if folder:
        module_folder = safe_file_manager_component(folder, "模块文件夹")
        if module_folder not in STANDARD_FOLDERS:
            raise NasSafetyError("未知模块文件夹")
        target = ensure_within(target / module_folder, root)
    if file_name:
        target = ensure_within(target / safe_file_manager_component(file_name, "文件名"), root)
    return root, target, student_name, module_folder


def file_manager_student_for_folder(student_folder):
    try:
        safe = Path(student_folder).resolve()
    except Exception:
        return None
    for row in db.all("SELECT student_id,passport_first_name,passport_last_name,folder_path FROM students WHERE folder_path IS NOT NULL"):
        try:
            if Path(row["folder_path"]).resolve() == safe:
                return row
        except Exception:
            continue
    return None


def file_manager_marker_for_path(file_path):
    return db.one(
        "SELECT * FROM file_action_markers WHERE file_path=? ORDER BY id DESC LIMIT 1",
        (str(file_path),),
    )


def file_manager_marker_visual_status(marker):
    if not marker:
        return "Normal"
    if marker["marker_status"] == "Active":
        return marker["marker_type"]
    return marker["marker_status"]


def file_manager_marker_tag(marker):
    visual = file_manager_marker_visual_status(marker)
    css = FILE_MANAGER_MARKER_CLASSES.get(visual, "normal")
    premium_css = {
        "PendingDelete": "file-manager-marker-pending-delete",
        "PendingMove": "file-manager-marker-pending-move",
        "PendingRename": "file-manager-marker-pending-rename",
        "Processed": "file-manager-marker-processed",
        "Cancelled": "file-manager-marker-cancelled",
    }.get(visual, "")
    return f'<span class="file-marker-tag file-manager-marker-status {esc(css)} {esc(premium_css)}">{esc(FILE_MANAGER_MARKER_LABELS.get(visual, visual))}</span>'


