def review_target_component(value):
    if not str(value or "").strip():
        return ""
    cleaned = sanitize_component(value).replace(" ", "")
    cleaned = re.sub(r"[^A-Za-z0-9._()-]", "", cleaned)
    return cleaned[:80]


def classified_filename(document_type, original_name, target_name=""):
    if not document_type:
        raise ValueError("请选择 DocumentType")
    suffix = re.sub(r"[^A-Za-z0-9.]", "", Path(original_name or "").suffix)[:10].lower()
    date_stamp = datetime.now().astimezone().strftime("%Y%m%d")
    pieces = [document_type]
    target = review_target_component(target_name)
    if target:
        pieces.append(target)
    pieces.extend([date_stamp, "V1"])
    return "_".join(pieces) + suffix


