def can_generate_contract(user):
    return can_access_module(user, "student_contracts")


def can_revise_contract(user):
    return can_access_module(user, "student_contracts")


def can_manage_transfer_contract(user):
    """Preserve approved Manager inheritance without expanding Staff authority."""
    return bool(
        user
        # Existing Manager derivative; no username or role-prefix matching.
        and str(user.get("role_name") or "") in {
            "Admin", "Manager", "Manager + Student Cases",
        }
        and can_generate_contract(user)
    )

def restrict_contract_creation_for_transfer_context(contracts, lifecycle_contexts, user):
    """Keep every contract-creation path behind the exact Transfer authority."""
    if can_manage_transfer_contract(user):
        return False
    for contract in contracts:
        values = dict(contract)
        if normalize_contract_type(values.get("contract_type")) != "TransferApplicationContract":
            continue
        if values.get("application_cycle_id") is None:
            return True
        context = lifecycle_contexts.get(int(values["id"]))
        # Only an exact, explicitly closed Transfer lifecycle proves history.
        # Missing, cross-type, or mismatched ownership remains fail-closed.
        if (
            context is None
            or str(context.lifecycle_type or "") != "transfer"
            or context.cycle_id != int(values["application_cycle_id"])
            or str(context.cycle_status or "") != "closed"
        ):
            return True
    return False

def restrict_contract_creation_for_student_transfer_context(student_id, user):
    """Server-side counterpart to the Student Contracts presentation gate."""
    if can_manage_transfer_contract(user):
        return False
    return bool(db.one(
        """SELECT contract.id FROM contracts AS contract
             LEFT JOIN application_cycles AS cycle
               ON cycle.id=contract.application_cycle_id
            WHERE contract.student_id=?
              AND contract.contract_type='TransferApplicationContract'
              AND contract.deleted_at IS NULL AND contract.voided_at IS NULL
              AND (cycle.id IS NULL
                   OR COALESCE(cycle.student_id,'')<>contract.student_id
                   OR COALESCE(cycle.cycle_type,'')<>'transfer'
                   OR COALESCE(cycle.status,'')<>'closed')
            LIMIT 1""",
        (student_id,),
    ))

def require_transfer_contract_signable(contract):
    if dict(contract).get("contract_type") != "TransferApplicationContract":
        return None
    connection = db.connect()
    try:
        return transfer_contract_authority.require_signable(
            connection,
            contract,
            snapshot_payload(contract["standalone_data_json"] or ""),
        )
    finally:
        db._release_connection(connection)

def is_unbound_transfer_draft(contract):
    values = dict(contract)
    return (
        normalize_contract_type(values.get("contract_type"))
        == "TransferApplicationContract"
        and normalize_contract_status(values.get("contract_status")) == "Draft"
        and values.get("application_cycle_id") is None
        and not is_published_v2_snapshot(
            snapshot_payload(values.get("standalone_data_json") or "")
        )
    )

def require_transfer_pdf_bytes(contract, data):
    transfer_contract_authority.validate_pdf_data(data, contract)

def require_transfer_pdf_file(contract, path):
    if dict(contract).get("contract_type") != "TransferApplicationContract":
        return
    if not path or not Path(path).is_file():
        raise ValueError("SOURCE VERIFICATION HOLD: signed Transfer artifact is missing")
    require_transfer_pdf_bytes(contract, Path(path).read_bytes())

def require_transfer_status_artifact(contract, status):
    if status in ("ParentSigned", "FullyExecuted"):
        field = "final_signed_file_path" if status == "FullyExecuted" else "signed_file_path"
        require_transfer_pdf_file(contract, dict(contract).get(field))

def contract_effective_draft_for_view(contract, user):
    """Keep unauthorized Transfer GET views free of document/database writes."""
    contract_type = normalize_contract_type(contract["contract_type"])
    if (
        contract_type == "TransferApplicationContract"
        and not can_manage_transfer_contract(user)
    ):
        existing_path = (
            contract["contract_file_path"]
            if "contract_file_path" in contract.keys()
            else None
        )
        return Path(existing_path) if existing_path else None
    return ensure_contract_effective_draft_file(contract, user)

def contract_uid_for_view(contract, user):
    """Return the persisted UID without creating one for unauthorized Transfer views."""
    contract_type = normalize_contract_type(contract["contract_type"])
    if (
        contract_type == "TransferApplicationContract"
        and not can_manage_transfer_contract(user)
    ):
        return contract["contract_uid"] if "contract_uid" in contract.keys() else ""
    return ensure_contract_uid(contract)


