def service_type_label(value):
    return dict(STUDY_CONTRACT_SERVICE_TYPES).get(normalize_service_type_value(value), value or "")


def service_scope_key_from_label(label):
    text = str(label or "").strip()
    for value, default_label in STUDY_CONTRACT_SERVICE_SCOPES:
        if text == default_label:
            return value
    digest = hashlib.sha1(text.encode("utf-8")).hexdigest()[:12]
    return f"custom_scope_{digest}"


def normalize_study_contract_service_scope_items(items):
    normalized = []
    seen_values = set()
    default_by_label = {label: value for value, label in STUDY_CONTRACT_SERVICE_SCOPES}
    for item in items or []:
        if isinstance(item, dict):
            label = str(item.get("label") or item.get("text") or "").strip()
            value = str(item.get("value") or "").strip()
        elif isinstance(item, (list, tuple)) and len(item) >= 2:
            value = str(item[0] or "").strip()
            label = str(item[1] or "").strip()
        else:
            label = str(item or "").strip()
            value = ""
        if not label:
            continue
        value = value or default_by_label.get(label) or service_scope_key_from_label(label)
        if value in seen_values:
            continue
        normalized.append((value, label))
        seen_values.add(value)
    return normalized


def parse_study_contract_service_scope_items_text(text):
    lines = [line.strip() for line in str(text or "").splitlines() if line.strip()]
    return normalize_study_contract_service_scope_items(lines)


def study_contract_service_scope_items():
    try:
        stored = json.loads(db.setting(STUDY_CONTRACT_SERVICE_SCOPES_SETTING, "[]") or "[]")
    except json.JSONDecodeError:
        stored = []
    items = normalize_study_contract_service_scope_items(stored)
    return items or list(STUDY_CONTRACT_SERVICE_SCOPES)


def study_contract_service_scope_items_text():
    return "\n".join(label for _value, label in study_contract_service_scope_items())


def save_study_contract_service_scope_items(form, user):
    current = study_contract_service_scope_items()
    raw = form.get("study_contract_service_scope_items")
    updated = parse_study_contract_service_scope_items_text(raw)
    if not updated:
        updated = list(STUDY_CONTRACT_SERVICE_SCOPES)
    changed = []
    if updated != current:
        changed.append({"key": "study_contract_service_scope_items", "old": current, "new": updated})
        payload = [{"value": value, "label": label} for value, label in updated]
        db.set_setting(STUDY_CONTRACT_SERVICE_SCOPES_SETTING, json.dumps(payload, ensure_ascii=False), user["id"] if user else None)
    return changed, updated


def contract_refund_template_editor_rows():
    rows = active_refund_templates()
    editable_types = {"visa_refusal_no_further_application", "school_application_failure"}
    rows = [row for row in rows if row.get("refund_policy_type") in editable_types]
    order = {"visa_refusal_no_further_application": 0, "school_application_failure": 1}
    return sorted(rows, key=lambda row: order.get(row.get("refund_policy_type"), 99))


def save_contract_refund_template_texts(form, user):
    changed = []
    updated = []
    for row in contract_refund_template_editor_rows():
        form_key = f"refund_template_text_{row['id']}"
        if form_key not in form:
            continue
        new_text = str(form.get(form_key) or "").strip()
        old_text = row.get("refund_policy_text") or ""
        updated.append({"id": row["id"], "refund_policy_type": row["refund_policy_type"], "refund_policy_text": new_text})
        if new_text != old_text:
            db.execute(
                "UPDATE contract_refund_templates SET refund_policy_text=?,updated_at=? WHERE id=?",
                (new_text, now_iso(), row["id"]),
            )
            changed.append({
                "id": row["id"],
                "template_name": row.get("template_name") or "",
                "refund_policy_type": row.get("refund_policy_type") or "",
                "old": old_text,
                "new": new_text,
            })
    if changed:
        db.audit(
            user,
            "contract_refund_templates_updated",
            "template_management",
            record_id="contract_refund_templates",
            old_value=json.dumps([{k: item[k] for k in ("id", "refund_policy_type", "old")} for item in changed], ensure_ascii=False),
            new_value=json.dumps([{k: item[k] for k in ("id", "refund_policy_type", "new")} for item in changed], ensure_ascii=False),
        )
    return changed, updated


def service_scope_label(value):
    domain_label = contract_domain_service_label(value)
    if domain_label != value:
        return domain_label
    return dict(study_contract_service_scope_items()).get(value, dict(STUDY_CONTRACT_SERVICE_SCOPES).get(value, value or ""))


def split_selected_scopes(form):
    selected = form.get("service_scope", [])
    if isinstance(selected, str):
        selected = [selected]
    allowed_values = {value for value, _ in study_contract_service_scope_items()}
    return [value for value in selected if value in allowed_values]


def selected_contract_service_scopes(form):
    if "contract_type" not in form:
        selected = split_selected_scopes(form)
        if "service_scope_submitted" in form:
            return selected
        return selected or default_contract_service_scopes()
    contract_type = normalize_contract_type(form.get("contract_type") or DEFAULT_CONTRACT_TYPE)
    selected = form.get("service_scope", [])
    return list(normalize_selected_services(
        contract_type,
        selected,
        submitted="service_scope_submitted" in form,
    ))


def default_contract_service_scopes():
    return [
        value
        for value, label in study_contract_service_scope_items()
        if value not in STUDY_CONTRACT_DEFAULT_EXCLUDED_SCOPES
        and label not in {"590 陪读签证递交", "590 陪读签证相关咨询"}
    ]


def normalize_service_type_value(value):
    value = value or "StudyConsultingAndVisaService"
    allowed = {item for item, _ in STUDY_CONTRACT_SERVICE_TYPES}
    if value in allowed:
        return value
    for item, label in STUDY_CONTRACT_SERVICE_TYPES:
        if value == label:
            return item
    return "StudyConsultingAndVisaService"


def contract_service_fee_setting_key(service_type):
    return f"contract_service_fee_{normalize_service_type_value(service_type)}"


def money_decimal(value):
    text = str(value or "").strip().replace(",", "").replace("AUD", "").replace("AU$", "").replace("AU", "").replace("$", "")
    if not text:
        return None
    try:
        return Decimal(text)
    except InvalidOperation:
        return None


def format_money(value):
    if value is None:
        return ""
    normalized = value.quantize(Decimal("0.01")).normalize()
    text = format(normalized, "f")
    return text[:-3] if text.endswith(".00") else text


def contract_service_fee_for_type(service_type, fallback=""):
    configured = db.setting(contract_service_fee_setting_key(service_type), "")
    return str(configured or fallback or "").strip()


def contract_service_type_options(selected="", fallback_fee=""):
    selected_value = normalize_service_type_value(selected)
    options = []
    for value, label in STUDY_CONTRACT_SERVICE_TYPES:
        options.append(
            f'<option value="{esc(value)}" {"selected" if value == selected_value else ""}>{esc(label)}</option>'
        )
    return "".join(options)


def calculated_contract_fees(form):
    payment_method = form.get("service_fee_currency") or ""
    if payment_method in CONTRACT_EDITABLE_FEE_PAYMENT_METHODS:
        base_fee = str(form.get("consulting_and_visa_service_fee") or "").strip()
    else:
        base_fee = CONTRACT_FIXED_SERVICE_FEE
    discount = contract_discount_amount_from_form(form)
    base_value = money_decimal(base_fee)
    discount_value = money_decimal(discount) if discount else Decimal("0")
    if discount_value is None or discount_value < 0:
        discount_value = Decimal("0")
    if base_value is not None and discount_value > base_value:
        discount_value = base_value
    final_fee = format_money(base_value - discount_value) if base_value is not None else ""
    normalized_discount = format_money(discount_value) if discount else ""
    return base_fee, normalized_discount, final_fee


def calculated_refusal_refund_amount(final_fee):
    final_value = money_decimal(final_fee)
    deduction_value = money_decimal(CONTRACT_VISA_REFUSAL_DEDUCTION) or Decimal("0")
    if final_value is None:
        return ""
    refund = final_value - deduction_value
    if refund < 0:
        refund = Decimal("0")
    return format_money(refund)


def calculated_school_failure_refund_amount(final_fee):
    return format_money(money_decimal(final_fee)) if money_decimal(final_fee) is not None else ""


