def discount_enabled_from_amount(amount):
    text = str(amount or "").strip()
    if not text:
        return "no"
    normalized = text.replace(",", "").replace("AUD", "").replace("$", "").strip()
    try:
        return "yes" if float(normalized) != 0 else "no"
    except ValueError:
        return "no" if normalized in {"0", "0.0", "0.00", "无", "没有", "none", "None"} else "yes"


