def contract_template_default():
    row = db.one("SELECT * FROM contract_refund_templates WHERE is_active=1 ORDER BY id LIMIT 1")
    return rowdict(row) if row else {}


def normalize_refund_policy_types(value):
    if isinstance(value, list):
        raw_values = value
    elif value:
        raw_values = re.split(r"[,，]", str(value))
    else:
        raw_values = []
    normalized = []
    seen = set()
    for item in raw_values:
        text = str(item or "").strip()
        if text and text not in seen:
            normalized.append(text)
            seen.add(text)
    return normalized


def active_refund_templates():
    return [rowdict(row) for row in db.all("SELECT * FROM contract_refund_templates WHERE is_active=1 ORDER BY id")]


def selected_contract_refund_templates(form, fallback=None):
    selected_types = normalize_refund_policy_types(form.get("refund_policy_type"))
    if not selected_types and fallback:
        selected_types = normalize_refund_policy_types(fallback.get("refund_policy_type"))
    templates = active_refund_templates()
    if selected_types:
        selected = [template for template in templates if template["refund_policy_type"] in selected_types]
    else:
        selected = templates
    if selected:
        return selected
    return [fallback] if fallback else []


def combined_refund_template(templates):
    templates = [template for template in templates if template]
    return {
        "refund_policy_type": ",".join(template.get("refund_policy_type") or "" for template in templates if template.get("refund_policy_type")),
        "refund_policy_text": "\n\n".join(template.get("refund_policy_text") or "" for template in templates if template.get("refund_policy_text")),
        "refund_notes": "\n".join(template.get("refund_notes") or "" for template in templates if template.get("refund_notes")),
    }


