def validate_contract_generation_payload(payload):
    missing = []
    if not str(payload.get("company_legal_name") or "").strip():
        missing.append("甲方公司名称")
    if not str(payload.get("company_abn_acn") or "").strip():
        missing.append("甲方 ABN / ACN")
    if not str(payload.get("parent_signer_name") or "").strip():
        missing.append("乙方签署人姓名")
    if not (str(payload.get("parent_phone") or "").strip() or str(payload.get("parent_email") or "").strip()):
        missing.append("乙方电话或邮箱")
    if not str(payload.get("student_full_name") or "").strip():
        missing.append("学生姓名")
    if not str(payload.get("contract_date") or "").strip():
        missing.append("合同日期")
    if not str(payload.get("final_fee_amount") or payload.get("consulting_and_visa_service_fee") or "").strip():
        missing.append("服务费用")
    scopes = payload.get("service_scope_items") or []
    if not scopes and not str(payload.get("service_scope_override_text") or payload.get("other_service_scope_text") or "").strip():
        missing.append("服务范围")
    return missing


def contract_generation_missing_error(payload):
    missing = validate_contract_generation_payload(payload)
    if missing:
        raise ValueError("合同生成前请先补充：" + "、".join(missing))


