def authority_contract_signer(student, form):
    try:
        student_data = json.loads(student["form_data_json"] or "{}")
    except (TypeError, json.JSONDecodeError):
        student_data = {}
    parents = [
        rowdict(row)
        for row in db.all(
            "SELECT * FROM parents WHERE student_id=? ORDER BY parent_type",
            (student["student_id"],),
        )
    ]
    source = str(form.get("parent_signer_source") or "").strip().lower()
    candidate = signer_candidate(source, student_data, parents)
    other_source = "mother" if source == "father" else "father"
    other_candidate = signer_candidate(other_source, student_data, parents)
    expected_relationship = "父亲" if source == "father" else "母亲"
    posted_name = str(form.get("parent_signer_name") or "").strip()
    posted_relationship = str(form.get("parent_signer_relationship") or "").strip()
    if not candidate["name"]:
        raise PublishedTemplateAuthorityError("所选签署人的主档姓名缺失，不能生成合同。")
    if posted_name and posted_name != candidate["name"]:
        raise PublishedTemplateAuthorityError("签署人姓名必须与所选父亲或母亲的主档资料一致。")
    if posted_relationship and posted_relationship != expected_relationship:
        raise PublishedTemplateAuthorityError("签署人关系与所选父亲或母亲不一致。")
    signer = {
        "source": source,
        "name": candidate["name"],
        "relationship": expected_relationship,
        "phone": candidate["phone"],
        "email": candidate["email"],
    }
    for field, form_key in (("phone", "parent_phone"), ("email", "parent_email")):
        posted = str(form.get(form_key) or "").strip()
        if signer[field] and posted and posted != signer[field]:
            raise PublishedTemplateAuthorityError(
                "已有的签署人联系方式不能由合同POST覆盖。"
            )
        if not signer[field]:
            if posted and posted == other_candidate[field]:
                raise PublishedTemplateAuthorityError(
                    "所选签署人的缺失联系方式不得借用另一位家长资料。"
                )
            signer[field] = posted
    if not signer["phone"] or not signer["email"]:
        raise PublishedTemplateAuthorityError("所选签署人缺少电话或邮箱，请在合同页补填。")
    return signer


