def generate_contract_standard_reset_revision(contract_id, user):
    contract = db.one("SELECT * FROM contracts WHERE id=?", (contract_id,))
    if not contract:
        raise ValueError("合同不存在")
    if is_unbound_transfer_draft(contract):
        raise PermissionError("Transfer合同必须先通过来源权威生成 Published V2 合同。")
    if is_published_v2_snapshot(snapshot_payload(contract["standalone_data_json"] or "")):
        raise PermissionError("Published V2合同不能恢复为旧V6或contract_domain正文。")
    if not can_revise_contract(user):
        raise PermissionError("你没有修改合同的权限")
    normalized_status = normalize_contract_status(contract["contract_status"])
    if normalized_status in {"ParentSigned", "FullyExecuted"}:
        raise PermissionError("已签署合同不能直接覆盖，请创建新合同版本或补充协议。")
    if normalized_status in {"Deleted", "Voided", "Revoked", "Superseded"}:
        raise PermissionError("当前合同状态不能恢复标准模板。")

    base = ensure_contract_base_version(contract)
    now = now_iso()
    payload = contract_base_payload_from_existing(contract)
    payload["contract_uid"] = ensure_contract_uid(contract)
    payload["standard_clause_texts"] = study_contract_standard_texts()
    payload.pop("service_scope_override_text", None)
    payload["refund_policy_text"] = fill_contract_refund_text(payload.get("refund_policy_text") or "", payload)
    standard_sections = contract_editor_section_contents(payload)
    previous_sections = {key: contract_section_current_content(contract, key) for key, _label in CONTRACT_REVISION_SECTIONS}
    changed_sections = [
        key for key, _label in CONTRACT_REVISION_SECTIONS
        if str(previous_sections.get(key) or "").strip() != str(standard_sections.get(key) or "").strip()
    ]
    if not changed_sections:
        changed_sections = ["service_scope"]

    request_id = db.execute(
        """INSERT INTO contract_revision_requests(contract_id,student_id,base_version_id,request_channel,
           requested_by_name,request_received_date,parent_request_text,revision_reason,revision_instruction,
           risk_warning,status,prepared_by,prepared_at,created_at,updated_at)
           VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
        (
            contract_id, contract["student_id"], base["id"], "内部修改", "", now[:10], "",
            "恢复使用标准模板", "恢复当前合同正文为标准模板生成内容", "", "Generated",
            user["id"], now, now, now,
        ),
    )
    version_number = next_contract_revision_number(contract_id)
    folder = contract_revision_target_folder(contract)
    stamp = datetime.now().astimezone().strftime("%Y%m%d")
    target, file_version = next_version_path(folder, f"StudyAbroadContractRevision_{stamp}_V{version_number}.docx")
    generate_study_contract_document(payload, target)
    version_id = db.execute(
        """INSERT INTO contract_versions(contract_id,student_id,version_number,version_label,file_path_docx,status,
           revision_reason,parent_request_text,change_summary,generated_by,generated_at,created_at)
           VALUES(?,?,?,?,?,?,?,?,?,?,?,?)""",
        (
            contract_id, contract["student_id"], version_number, f"V{version_number}", str(target), "Active",
            "恢复使用标准模板", "", "恢复当前学生合同为标准模板正文", user["id"], now, now,
        ),
    )
    for section_key, _label in CONTRACT_REVISION_SECTIONS:
        section_title = contract_revision_section_label(section_key)
        new_content = standard_sections.get(section_key) or ""
        db.execute(
            """INSERT INTO contract_sections(contract_id,version_id,section_key,section_title,section_content,
               source_type,updated_by,created_at,updated_at)
               VALUES(?,?,?,?,?,?,?,?,?)""",
            (contract_id, version_id, section_key, section_title, new_content, "Standard Template Reset", user["id"], now, now),
        )
        if section_key in changed_sections:
            db.execute(
                """INSERT INTO contract_revision_changes(revision_request_id,contract_id,version_id,section_key,
                   section_title,old_content,new_content,change_reason,changed_by,changed_at,created_at,updated_at)
                   VALUES(?,?,?,?,?,?,?,?,?,?,?,?)""",
                (
                    request_id, contract_id, version_id, section_key, section_title,
                    previous_sections.get(section_key) or "", new_content, "恢复使用标准模板",
                    user["id"], now, now, now,
                ),
            )
    update_contract_record_for_editor_revision(contract, payload, target, user)
    document_id = None
    if contract["student_id"]:
        document_id = db.execute(
            """INSERT INTO student_documents(student_id,folder_category,document_type,original_name,stored_name,
               file_path,version,file_size,uploaded_by,uploaded_at,preview_path,is_active)
               VALUES(?,?,?,?,?,?,?,?,?,?,?,1)""",
            (
                contract["student_id"], "Forms", "StudyAbroadContractRevision",
                target.name, target.name, str(target), file_version, target.stat().st_size,
                user["id"], now, "",
            ),
        )
    updated_contract = db.one("SELECT * FROM contracts WHERE id=?", (contract_id,))
    effective_path = ensure_contract_effective_draft_file(updated_contract, user)
    contract_output_debug_log("standard_reset_generated", updated_contract, actual_revision_docx_source=effective_path)
    invalidated_links = invalidate_contract_signing_links_for_revision(contract, user, now)
    clear_contract_signing_source_cache(contract_id)
    db.audit(
        user,
        "contract_standard_template_restored",
        "contracts",
        contract_id,
        file_path=str(target),
        new_value=json.dumps({
            "version": version_number,
            "document_id": document_id,
            "changed_sections": changed_sections,
            "invalidated_links": invalidated_links,
        }, ensure_ascii=False),
        student_id=contract["student_id"],
        contract_id=str(contract_id),
    )
    return {
        "version_number": version_number,
        "version_id": version_id,
        "revision_request_id": request_id,
        "file_path_docx": str(target),
        "document_id": document_id,
        "invalidated_links": invalidated_links,
    }


def generate_contract_revision_version(contract_id, user, section_key, final_content, revision_reason,
                                       parent_request_text="", revision_instruction="", request_channel="",
                                       request_received_date="", notes=""):
    contract = db.one("SELECT * FROM contracts WHERE id=?", (contract_id,))
    if not contract:
        raise ValueError("合同不存在")
    if is_published_v2_snapshot(snapshot_payload(contract["standalone_data_json"] or "")):
        raise PermissionError("Published V2合同不能通过旧条款修订入口改变冻结正文。")
    if not can_revise_contract(user):
        raise PermissionError("你没有修改合同的权限")
    section_key = str(section_key or "").strip()
    if section_key not in CONTRACT_REVISION_SECTION_LABELS:
        raise ValueError("请选择要修改的合同部分")
    final_content = str(final_content or "").strip()
    if not final_content:
        raise ValueError("请填写修改后的内容")
    revision_reason = str(revision_reason or "").strip()
    if not revision_reason:
        raise ValueError("请填写修改原因")
    normalized_status = normalize_contract_status(contract["contract_status"])
    if normalized_status in {"ParentSigned", "FullyExecuted"}:
        raise PermissionError("已签署合同不能直接修改，请创建补充协议或重新生成新合同版本。")

    base = ensure_contract_base_version(contract)
    original_content = contract_section_current_content(contract, section_key)
    now = now_iso()
    db.audit(
        user, "contract_revision_started", "contracts", contract_id,
        old_value=json.dumps({"section": section_key}, ensure_ascii=False),
        new_value=revision_reason, ip="", device="",
        student_id=contract["student_id"], contract_id=str(contract_id),
    )
    warning = contract_revision_risk_warning(section_key)
    if warning:
        db.audit(
            user, "contract_sensitive_clause_warning_shown", "contracts", contract_id,
            new_value=json.dumps({"section": section_key, "warning": warning}, ensure_ascii=False),
            student_id=contract["student_id"], contract_id=str(contract_id),
        )
    request_id = db.execute(
        """INSERT INTO contract_revision_requests(contract_id,student_id,base_version_id,request_channel,
           requested_by_name,request_received_date,parent_request_text,revision_reason,revision_instruction,
           risk_warning,status,prepared_by,prepared_at,created_at,updated_at)
           VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
        (
            contract_id, contract["student_id"], base["id"], request_channel or "",
            "", request_received_date or "", parent_request_text or "", revision_reason,
            revision_instruction or "", warning, "Generated", user["id"], now, now, now,
        ),
    )
    version_number = next_contract_revision_number(contract_id)
    payload = contract_payload_from_existing(contract)
    payload["contract_uid"] = ensure_contract_uid(contract)
    apply_contract_revision_to_payload(payload, section_key, final_content)
    folder = contract_revision_target_folder(contract)
    stamp = datetime.now().astimezone().strftime("%Y%m%d")
    target, file_version = next_version_path(folder, f"StudyAbroadContractRevision_{stamp}_V{version_number}.docx")
    generate_study_contract_document(payload, target)
    version_id = db.execute(
        """INSERT INTO contract_versions(contract_id,version_number,version_label,file_path_docx,status,
           revision_reason,change_summary,generated_by,generated_at,created_at)
           VALUES(?,?,?,?,?,?,?,?,?,?)""",
        (
            contract_id, version_number, f"V{version_number}", str(target), "Active",
            revision_reason, f"{contract_revision_section_label(section_key)} 已修改", user["id"], now, now,
        ),
    )
    db.execute(
        """INSERT INTO contract_sections(contract_id,version_id,section_key,section_title,section_content,
           source_type,updated_by,created_at,updated_at)
           VALUES(?,?,?,?,?,?,?,?,?)""",
        (contract_id, version_id, section_key, contract_revision_section_label(section_key), final_content, "Manual Revision", user["id"], now, now),
    )
    db.execute(
        """INSERT INTO contract_revision_changes(revision_request_id,contract_id,version_id,section_key,
           section_title,old_content,new_content,change_reason,changed_by,changed_at,created_at,updated_at)
           VALUES(?,?,?,?,?,?,?,?,?,?,?,?)""",
        (request_id, contract_id, version_id, section_key, contract_revision_section_label(section_key), original_content, final_content, revision_reason, user["id"], now, now, now),
    )
    update_contract_record_for_revision(contract, payload, section_key, final_content, target, user)
    if contract["student_id"]:
        db.execute(
            """INSERT INTO student_documents(student_id,folder_category,document_type,original_name,stored_name,
               file_path,version,file_size,uploaded_by,uploaded_at,preview_path,is_active)
               VALUES(?,?,?,?,?,?,?,?,?,?,?,1)""",
            (
                contract["student_id"], "Forms", "StudyAbroadContractRevision",
                target.name, target.name, str(target), file_version, target.stat().st_size,
                user["id"], now, "", 
            ),
        )
    updated_contract = db.one("SELECT * FROM contracts WHERE id=?", (contract_id,))
    effective_path = ensure_contract_effective_draft_file(updated_contract, user)
    contract_output_debug_log("manual_revision_generated", updated_contract, actual_revision_docx_source=effective_path)
    db.audit(
        user, "contract_section_manually_edited", "contracts", contract_id,
        old_value=original_content, new_value=final_content, file_path=str(target),
        student_id=contract["student_id"], contract_id=str(contract_id),
    )
    db.audit(
        user, "contract_revised_version_generated", "contracts", contract_id,
        file_path=str(target), new_value=json.dumps({"version": version_number, "section": section_key}, ensure_ascii=False),
        student_id=contract["student_id"], contract_id=str(contract_id),
    )
    return {
        "version_number": version_number,
        "version_id": version_id,
        "revision_request_id": request_id,
        "file_path_docx": str(target),
    }


def contract_uid_for_today():
    stamp = datetime.now().astimezone().strftime("%Y%m%d")
    prefix = f"CONTRACT-{stamp}-"
    row = db.one(
        "SELECT contract_uid FROM contracts WHERE contract_uid LIKE ? ORDER BY contract_uid DESC LIMIT 1",
        (prefix + "%",),
    )
    next_value = 1
    if row and row["contract_uid"]:
        try:
            next_value = int(str(row["contract_uid"]).rsplit("-", 1)[-1]) + 1
        except ValueError:
            next_value = 1
    while True:
        candidate = f"{prefix}{next_value:04d}"
        if not db.one("SELECT id FROM contracts WHERE contract_uid=?", (candidate,)):
            return candidate
        next_value += 1


def ensure_contract_uid(contract):
    if contract and "contract_uid" in contract.keys() and contract["contract_uid"]:
        return contract["contract_uid"]
    uid = contract_uid_for_today()
    if contract:
        db.execute("UPDATE contracts SET contract_uid=? WHERE id=?", (uid, contract["id"]))
    return uid


def standalone_contract_folder(contract_uid, category="generated"):
    safe_uid = sanitize_component(contract_uid)
    if category not in {"generated", "signed", "final"}:
        category = "generated"
    folder = STANDALONE_CONTRACT_ROOT / safe_uid / category
    folder.mkdir(parents=True, exist_ok=True)
    return folder


def compact_filename_part(value, fallback="Unknown"):
    text = re.sub(r"[^A-Za-z0-9]+", "", str(value or ""))
    return text or fallback


def dob_filename_part(value):
    text = re.sub(r"[^0-9]", "", str(value or ""))
    return text[:8] if len(text) >= 8 else (text or "NoDOB")


def final_contract_base_filename(contract, student=None):
    data = {}
    student_data = {}
    if contract:
        raw = standalone_contract_data(contract)
        data = raw.get("contract_payload") or {}
        student_data = raw.get("student_form_data") or {}
    if student:
        student_name = f"{student['passport_first_name']} {student['passport_last_name']}"
        student_id_value = student["student_id"]
        dob = student["date_of_birth"]
    else:
        student_name = data.get("student_full_name") or f"{student_data.get('passport_first_name') or ''} {student_data.get('passport_last_name') or ''}".strip() or "StandaloneStudent"
        student_id_value = "NoStudentID"
        dob = data.get("student_date_of_birth") or student_data.get("date_of_birth") or ""
    stamp = datetime.now().astimezone().strftime("%Y%m%d")
    return f"{compact_filename_part(student_name)}_{compact_filename_part(student_id_value, 'NoStudentID')}_{dob_filename_part(dob)}_FinalStudyAbroadContract_{stamp}_V1.pdf"


