def save_contract_secure_asset(upload, target):
    suffix = Path(upload.filename or "").suffix.lower()
    if suffix not in {".png", ".jpg", ".jpeg"}:
        raise ValueError("图片只支持 PNG 或 JPG")
    target.parent.mkdir(parents=True, exist_ok=True)
    image = Image.open(io.BytesIO(upload.data))
    image = image.convert("RGBA")
    image.save(target, format="PNG")
    os.chmod(target, 0o600)
    return target


def float_setting(key, default):
    try:
        return float(db.setting(key, str(default)))
    except (TypeError, ValueError):
        return float(default)


def local_company_signing_date():
    return datetime.now(ZoneInfo("Australia/Melbourne")).strftime("%Y年%m月%d日")


def reportlab_chinese_font():
    embedded_candidates = [
        ("AAIEArialUnicode", "/System/Library/Fonts/Supplemental/Arial Unicode.ttf"),
        ("AAIESTHeiti", "/System/Library/Fonts/STHeiti Medium.ttc"),
        ("AAIESTHeitiLight", "/System/Library/Fonts/STHeiti Light.ttc"),
    ]
    for font_name, font_path in embedded_candidates:
        try:
            if font_name not in pdfmetrics.getRegisteredFontNames() and Path(font_path).exists():
                pdfmetrics.registerFont(TTFont(font_name, font_path))
            if font_name in pdfmetrics.getRegisteredFontNames():
                return font_name
        except Exception:
            pass
    font_name = "STSong-Light"
    try:
        pdfmetrics.registerFont(UnicodeCIDFont(font_name))
        return font_name
    except Exception:
        return "Helvetica"


def school_plan_reportlab_chinese_font():
    return school_plan_reportlab_font_names()["medium"]


def school_plan_reportlab_font_names():
    names = {
        "regular": "AAIENotoSansSCRegular",
        "medium": "AAIENotoSansSCMedium",
        "bold": "AAIENotoSansSCBold",
    }
    font_name = "AAIENotoSansSC"
    try:
        candidates = {
            "regular": SCHOOL_PLAN_REPORT_FONT_FILES.get(400),
            "medium": SCHOOL_PLAN_REPORT_FONT_FILES.get(500),
            "bold": SCHOOL_PLAN_REPORT_FONT_FILES.get(700),
        }
        for key, path in candidates.items():
            if path and path.is_file() and names[key] not in pdfmetrics.getRegisteredFontNames():
                pdfmetrics.registerFont(TTFont(names[key], str(path)))
        if all(name in pdfmetrics.getRegisteredFontNames() for name in names.values()):
            pdfmetrics.registerFontFamily(
                font_name,
                normal=names["medium"],
                bold=names["bold"],
                italic=names["regular"],
                boldItalic=names["bold"],
            )
            return names
    except Exception:
        pass
    fallback = reportlab_chinese_font()
    return {"regular": fallback, "medium": fallback, "bold": fallback}


