def image_height_for_width(path, width):
    image = contract_asset_visible_image(path)
    w, h = image.size
    if not w:
        return width
    return width * (h / w)


def transparent_contract_asset_image(path):
    image = Image.open(path).convert("RGBA")
    pixels = []
    for red, green, blue, alpha in image.getdata():
        if alpha == 0:
            pixels.append((red, green, blue, 0))
            continue
        if red >= 246 and green >= 246 and blue >= 246:
            pixels.append((255, 255, 255, 0))
        elif red >= 232 and green >= 232 and blue >= 232:
            fade = (max(red, green, blue) - 232) / 14
            pixels.append((red, green, blue, int(alpha * max(0, 1 - fade))))
        else:
            pixels.append((red, green, blue, alpha))
    image.putdata(pixels)
    return image


def contract_asset_visible_image(path, padding=2):
    """Return only visible ink so transparent canvas margins do not shrink signatures."""
    image = transparent_contract_asset_image(path)
    bounds = image.getchannel("A").getbbox()
    if not bounds:
        raise ValueError("签名内容为空，请重新签名。")
    left, top, right, bottom = bounds
    padding = max(0, int(padding or 0))
    left = max(0, left - padding)
    top = max(0, top - padding)
    right = min(image.width, right + padding)
    bottom = min(image.height, bottom + padding)
    return image.crop((left, top, right, bottom))


def transparent_contract_asset_reader(path):
    return ImageReader(contract_asset_visible_image(path))


def transparent_contract_asset_png_bytes(path):
    image = transparent_contract_asset_image(path)
    output = io.BytesIO()
    image.save(output, format="PNG")
    return output.getvalue()


def draw_image_preserving_aspect(pdf_canvas, path, x, y, width):
    height = image_height_for_width(path, width)
    pdf_canvas.drawImage(transparent_contract_asset_reader(path), x, y, width=width, height=height, mask="auto")


def draw_image_contained_in_box(pdf_canvas, path, x, y, width, height, padding=2):
    image = contract_asset_visible_image(path)
    image_width, image_height = image.size
    if not image_width or not image_height:
        return
    max_width = max(1, width - padding * 2)
    max_height = max(1, height - padding * 2)
    scale = min(max_width / image_width, max_height / image_height)
    draw_width = image_width * scale
    draw_height = image_height * scale
    draw_x = x + padding
    draw_y = y + padding
    pdf_canvas.drawImage(
        ImageReader(image),
        draw_x,
        draw_y,
        width=draw_width,
        height=draw_height,
        mask="auto",
    )


def draw_image_exact_size(pdf_canvas, path, x, y, width, height):
    pdf_canvas.drawImage(
        ImageReader(transparent_contract_asset_image(path)),
        x,
        y,
        width=width,
        height=height,
        mask="auto",
    )


def manual_rect_to_pdf(rotation, page_width, page_height, x, y, width, height):
    rotation = int(rotation or 0) % 360
    if rotation == 90:
        return y, page_height - x - width, height, width
    if rotation == 180:
        return page_width - x - width, page_height - y - height, width, height
    if rotation == 270:
        return page_width - y - height, x, height, width
    return x, y, width, height


def manual_point_to_pdf(rotation, page_width, page_height, x, y):
    rotation = int(rotation or 0) % 360
    if rotation == 90:
        return y, page_height - x
    if rotation == 180:
        return page_width - x, page_height - y
    if rotation == 270:
        return page_width - y, x
    return x, y


def _page_index_from_setting(page_setting, last_index):
    if str(page_setting or "last").lower() == "last":
        return last_index
    try:
        index = int(page_setting) - 1
    except (TypeError, ValueError):
        return last_index
    return max(0, min(last_index, index))


def _contract_body_last_page_index(reader):
    last_index = len(reader.pages) - 1
    body_last = last_index
    for index in range(last_index, -1, -1):
        try:
            text = reader.pages[index].extract_text() or ""
        except Exception:
            text = ""
        xobjects = reader.pages[index].get("/Resources", {}).get("/XObject", {})
        if "AAIE 合同签署确认" in text or "Contract Signature Confirmation" in text:
            body_last = index - 1
            continue
        if not text.strip() and not xobjects:
            body_last = index - 1
            continue
        break
    return max(0, body_last)


def _contract_signature_anchors(source_pdf):
    try:
        import pdfplumber
    except Exception:
        return {}
    anchors = {}
    try:
        with pdfplumber.open(str(source_pdf)) as pdf:
            for page_index, page in enumerate(pdf.pages):
                words = page.extract_words(x_tolerance=2, y_tolerance=3) or []
                for word_index, word in enumerate(words):
                    text = word.get("text", "")
                    if "Sonny" in text:
                        x1 = float(word.get("x1", 0))
                        top = float(word.get("top", 0))
                        bottom = float(word.get("bottom", top))
                        if word_index + 1 < len(words) and "Zhang" in words[word_index + 1].get("text", ""):
                            next_word = words[word_index + 1]
                            x1 = max(x1, float(next_word.get("x1", x1)))
                            top = min(top, float(next_word.get("top", top)))
                            bottom = max(bottom, float(next_word.get("bottom", bottom)))
                        anchors["sonny"] = {
                            "page_index": page_index,
                            "x1": x1,
                            "y": float(page.height) - bottom,
                        }
                    if "甲方签署日期" in text:
                        anchors["company_date"] = {
                            "page_index": page_index,
                            "x1": float(word.get("x1", 0)),
                            "y": float(page.height) - float(word.get("bottom", 0)),
                        }
                if "sonny" in anchors and "company_date" in anchors:
                    break
    except Exception:
        return {}
    return anchors


def _contract_aaie_signature_cell_bounds(source_pdf, page_index, sonny_anchor):
    """Return the Master Layout left signature-cell bounds in PDF coordinates."""
    try:
        import pdfplumber
    except Exception:
        return None
    try:
        with pdfplumber.open(str(source_pdf)) as pdf:
            if page_index < 0 or page_index >= len(pdf.pages):
                return None
            page = pdf.pages[page_index]
            anchor_y = float(sonny_anchor.get("y") or 0)
            anchor_x = float(sonny_anchor.get("x1") or 0)
            vertical = [
                line for line in page.lines
                if abs(float(line.get("x0", 0)) - float(line.get("x1", 0))) <= 1
                and float(line.get("y1", 0)) - float(line.get("y0", 0)) >= 80
                and float(line.get("y0", 0)) <= anchor_y <= float(line.get("y1", 0))
            ]
            left_candidates = [
                line for line in vertical
                if float(line.get("x0", 0)) <= anchor_x
            ]
            divider_candidates = [
                line for line in vertical
                if float(line.get("x0", 0)) > max(anchor_x + 40, float(page.width) * 0.4)
            ]
            if not left_candidates or not divider_candidates:
                return None
            left = max(left_candidates, key=lambda line: float(line.get("x0", 0)))
            divider = min(
                divider_candidates, key=lambda line: float(line.get("x0", 0))
            )
            bounds = {
                "x0": float(left["x0"]),
                "x1": float(divider["x0"]),
                "y0": max(float(left["y0"]), float(divider["y0"])),
                "y1": min(float(left["y1"]), float(divider["y1"])),
            }
            if bounds["x1"] - bounds["x0"] < 120 or bounds["y1"] - bounds["y0"] < 80:
                return None
            return bounds
    except Exception:
        return None


def _contained_image_placement(path, x, y, width, bounds, padding=6):
    """Clamp one aspect-preserving image rectangle inside a PDF cell."""
    available_width = max(1, float(bounds["x1"]) - float(bounds["x0"]) - 2 * padding)
    available_height = max(1, float(bounds["y1"]) - float(bounds["y0"]) - 2 * padding)
    width = min(float(width), available_width)
    height = image_height_for_width(path, width)
    if height > available_height and height > 0:
        width *= available_height / height
        height = available_height
    x = min(
        float(bounds["x1"]) - padding - width,
        max(float(bounds["x0"]) + padding, float(x)),
    )
    y = min(
        float(bounds["y1"]) - padding - height,
        max(float(bounds["y0"]) + padding, float(y)),
    )
    return x, y, width


def _contained_aaie_signature_stamp_placement(
    signature_path, stamp_path, signature_width, stamp_width, bounds, padding=2
):
    """Keep the overlapping AAIE composition top-aligned below the date."""
    signature_width = float(signature_width)
    stamp_width = float(stamp_width)
    signature_height = image_height_for_width(signature_path, signature_width)
    stamp_height = image_height_for_width(stamp_path, stamp_width)
    stamp_offset_x = max(24.0, signature_width * 0.42)
    signature_offset_y = 0.0
    cluster_width = max(signature_width, stamp_offset_x + stamp_width)
    cluster_height = max(signature_offset_y + signature_height, stamp_height)
    available_width = max(
        1.0, float(bounds["x1"]) - float(bounds["x0"]) - 2 * padding
    )
    available_height = max(
        1.0, float(bounds["y1"]) - float(bounds["y0"]) - 2 * padding
    )
    scale = min(1.0, available_width / cluster_width, available_height / cluster_height)
    signature_width *= scale
    stamp_width *= scale
    signature_height *= scale
    stamp_height *= scale
    stamp_offset_x *= scale
    signature_offset_y *= scale
    cluster_width *= scale
    cluster_x = (
        float(bounds["x0"]) + padding + (available_width - cluster_width) / 2
    )
    cluster_y = float(bounds["y1"]) - padding - max(
        signature_offset_y + signature_height, stamp_height
    )
    return {
        "signature": (
            cluster_x,
            cluster_y + signature_offset_y,
            signature_width,
        ),
        "stamp": (
            cluster_x + stamp_offset_x,
            cluster_y,
            stamp_width,
        ),
    }


def _contract_parent_signature_section_anchors(source_pdf, page_index):
    fallback = {"page_index": page_index}
    try:
        import pdfplumber
    except Exception:
        return fallback
    try:
        with pdfplumber.open(str(source_pdf)) as pdf:
            if page_index < 0 or page_index >= len(pdf.pages):
                return fallback
            page = pdf.pages[page_index]
            anchors = {"page_index": page_index}
            for word in page.extract_words(x_tolerance=2, y_tolerance=3) or []:
                text = str(word.get("text") or "")
                x0 = float(word.get("x0", 0))
                x1 = float(word.get("x1", x0))
                bottom = float(word.get("bottom", 0))
                y = float(page.height) - bottom
                if "委托方" in text and "乙方签字" in text:
                    anchors["signature_x"] = min(float(page.width) - 145, x0 + 150)
                    anchors["signature_y"] = max(36, y - 2)
                    anchors["signature_box_width"] = min(122, max(90, float(page.width) - anchors["signature_x"] - 24))
                    anchors["signature_box_height"] = 40
                if "法定代理人" in text or ("监护人" in text and ("签字" in text or "名字" in text)):
                    anchors["name_x"] = min(float(page.width) - 120, x0 + 190)
                    anchors["name_y"] = max(36, y + 2)
                    anchors["name_label_x"] = x0
                    anchors["name_label_y"] = max(36, y + 2)
                    anchors["name_label_clear_x"] = x0 - 1
                    anchors["name_label_clear_y"] = max(32, y - 3)
                    anchors["name_label_clear_width"] = max(125, anchors["name_x"] - x0 - 6)
                    anchors["name_underline_clear_x"] = x0 - 1
                    anchors["name_underline_clear_y"] = max(24, y - 24)
                    anchors["name_underline_clear_width"] = max(180, float(page.width) - x0 - 24)
                if "家长/乙方签署日期" in text:
                    anchors["date_label_x"] = x0
                    anchors["date_label_y"] = max(28, y + 2)
                    anchors["date_row_clear_x"] = x0 - 1
                    anchors["date_row_clear_y"] = max(22, y - 6)
                    anchors["date_row_clear_width"] = min(240, max(170, float(page.width) - x0 - 24))
                    anchors["date_clear_x"] = min(float(page.width) - 155, x0 + 98)
                    anchors["date_clear_width"] = min(190, max(145, float(page.width) - anchors["date_clear_x"] - 18))
                    anchors["date_x"] = min(float(page.width) - 120, x0 + 104)
                    anchors["date_y"] = max(28, y + 2)
                    anchors["date_line_y"] = max(26, y + 1)
            signature_x = float(anchors.get("signature_x") or 0)
            signature_y = float(anchors.get("signature_y") or 0)
            if signature_x and signature_y:
                vertical = [
                    line for line in page.lines
                    if abs(float(line.get("x0", 0)) - float(line.get("x1", 0))) <= 1
                    and float(line.get("y1", 0)) - float(line.get("y0", 0)) >= 80
                    and float(line.get("y0", 0)) <= signature_y <= float(line.get("y1", 0))
                ]
                right_candidates = [
                    float(line.get("x0", 0)) for line in vertical
                    if float(line.get("x0", 0)) > signature_x
                ]
                if right_candidates:
                    right_border = min(right_candidates)
                    anchors["signature_cell_x1"] = right_border
                    anchors["signature_box_width"] = min(
                        float(anchors.get("signature_box_width") or 122),
                        max(1, right_border - signature_x - 4),
                    )
            return anchors
    except Exception:
        return fallback


def parent_signature_date_text(signed_at):
    # Persist the signing day's Melbourne date, including retries on later days.
    raw = str(signed_at or "").strip()
    try:
        parsed = datetime.fromisoformat(raw.replace("Z", "+00:00"))
    except ValueError:
        return raw.split("T", 1)[0]
    melbourne = ZoneInfo("Australia/Melbourne")
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=melbourne)
    return parsed.astimezone(melbourne).strftime("%Y年%m月%d日")


def apply_parent_signature_to_contract_signature_section(source_pdf, signature_image_path, target_pdf, parent_name="", signed_at=None):
    source_pdf = Path(source_pdf)
    signature_image_path = Path(signature_image_path)
    target_pdf = Path(target_pdf)
    if source_pdf.suffix.lower() != ".pdf":
        raise ValueError("家长电子签名只能写入 PDF 合同。")
    if not source_pdf.is_file():
        raise FileNotFoundError("合同 PDF 不存在。")
    if not signature_image_path.is_file():
        raise FileNotFoundError("家长电子签名图片不存在。")
    reader = PdfReader(str(source_pdf))
    if not reader.pages:
        raise ValueError("合同 PDF 没有页面。")
    body_last_index = _contract_body_last_page_index(reader)
    target_index = body_last_index
    anchors = {"page_index": target_index}
    for candidate_index in range(body_last_index, -1, -1):
        candidate = _contract_parent_signature_section_anchors(source_pdf, candidate_index)
        if any(key in candidate for key in ("signature_x", "name_x", "date_x")):
            anchors = candidate
            target_index = candidate_index
            break
    writer = PdfWriter()
    for index, page in enumerate(reader.pages):
        if index > body_last_index:
            continue
        if index == target_index:
            width = float(page.mediabox.width)
            height = float(page.mediabox.height)
            signature_x = float(anchors.get("signature_x") or (width * 0.67))
            signature_y = float(anchors.get("signature_y") or (height * 0.21))
            signature_width = float(anchors.get("signature_box_width") or min(98, width * 0.18))
            signature_height = float(anchors.get("signature_box_height") or 40)
            name_x = float(anchors.get("name_x") or signature_x)
            name_y = float(anchors.get("name_y") or max(36, signature_y - 34))
            date_x = float(anchors.get("date_x") or signature_x)
            date_y = float(anchors.get("date_y") or max(28, signature_y - 68))
            overlay_stream = io.BytesIO()
            c = canvas.Canvas(overlay_stream, pagesize=(width, height))
            draw_image_contained_in_box(c, signature_image_path, signature_x, signature_y, signature_width, signature_height)
            fonts = school_plan_reportlab_font_names()
            c.setFillColor(colors.HexColor("#111827"))
            c.setFont(fonts["medium"], 9.2)
            if "name_label_x" in anchors:
                c.setFillColor(colors.white)
                c.rect(
                    float(anchors.get("name_underline_clear_x") or name_x),
                    float(anchors.get("name_underline_clear_y") or name_y - 24),
                    float(anchors.get("name_underline_clear_width") or 180),
                    16,
                    stroke=0,
                    fill=1,
                )
                c.rect(
                    float(anchors.get("name_label_clear_x") or name_x),
                    float(anchors.get("name_label_clear_y") or name_y - 3),
                    float(anchors.get("name_label_clear_width") or 140),
                    13,
                    stroke=0,
                    fill=1,
                )
                c.setFillColor(colors.HexColor("#111827"))
                c.drawString(float(anchors["name_label_x"]), float(anchors["name_label_y"]), "法定代理人或者监护人（名字）：")
            if parent_name:
                c.drawString(name_x, name_y, str(parent_name))
            date_text = parent_signature_date_text(signed_at)
            if date_text:
                date_clear_x = float(anchors.get("date_clear_x") or date_x)
                date_clear_width = float(anchors.get("date_clear_width") or 128)
                date_line_y = float(anchors.get("date_line_y") or (date_y - 3))
                c.setFillColor(colors.white)
                if "date_label_x" in anchors:
                    c.rect(
                        float(anchors.get("date_row_clear_x") or date_clear_x - 1),
                        float(anchors.get("date_row_clear_y") or date_line_y - 7),
                        float(anchors.get("date_row_clear_width") or date_clear_width),
                        18,
                        stroke=0,
                        fill=1,
                    )
                    c.setFillColor(colors.HexColor("#111827"))
                    c.drawString(float(anchors["date_label_x"]), float(anchors["date_label_y"]), "家长/乙方签署日期：")
                else:
                    c.rect(date_clear_x - 1, date_line_y - 7, date_clear_width, 18, stroke=0, fill=1)
                c.setFillColor(colors.HexColor("#111827"))
                c.drawString(date_x, date_y, date_text)
            c.save()
            overlay_stream.seek(0)
            overlay = PdfReader(overlay_stream)
            page.merge_page(overlay.pages[0])
        writer.add_page(page)
    target_pdf.parent.mkdir(parents=True, exist_ok=True)
    with target_pdf.open("wb") as fh:
        writer.write(fh)
    return target_pdf


def apply_aaie_signature_and_stamp(source_pdf, target_pdf, company_signing_date=None):
    source_pdf = Path(source_pdf)
    target_pdf = Path(target_pdf)
    if source_pdf.suffix.lower() != ".pdf":
        raise ValueError("MVP 阶段只能对 PDF 签署版合同加盖 AAIE 签名和公章")
    signature_path, stamp_path = active_contract_asset_paths()
    if not signature_path.is_file() or not stamp_path.is_file():
        raise ValueError("AAIE signature/stamp assets are not configured.")
    reader = PdfReader(str(source_pdf))
    if not reader.pages:
        raise ValueError("签署版合同 PDF 没有页面")
    writer = PdfWriter()
    placement = contract_stamp_placement()
    anchors = _contract_signature_anchors(source_pdf)
    master_layout_signature = any(
        "AAIE / 甲方（签字 / 盖章）" in (page.extract_text() or "")
        for page in reader.pages
    )
    company_signing_date = company_signing_date or local_company_signing_date()
    master_cell = None
    if master_layout_signature:
        sonny = anchors.get("sonny")
        company_date = anchors.get("company_date")
        if not sonny or not company_date or sonny["page_index"] != company_date["page_index"]:
            raise ValueError("无法定位甲方签署区域及日期，最终合同尚未生成。")
        master_cell = _contract_aaie_signature_cell_bounds(source_pdf, sonny["page_index"], sonny)
        if not master_cell or not (
            master_cell["x0"] < company_date["x1"] < master_cell["x1"] - 20
            and master_cell["y0"] + 30 < company_date["y"] < master_cell["y1"]
        ):
            raise ValueError("无法确认甲方签署边框，最终合同尚未生成。")
    last_index = _contract_body_last_page_index(reader)
    for index, page in enumerate(reader.pages):
        sonny = anchors.get("sonny")
        company_date = anchors.get("company_date")
        signature_page_index = sonny["page_index"] if sonny else _page_index_from_setting(placement["signature_page"], last_index)
        stamp_page_index = sonny["page_index"] if sonny else _page_index_from_setting(placement["stamp_page"], last_index)
        date_page_index = company_date["page_index"] if company_date else _page_index_from_setting(placement["company_date_page"], last_index)
        if index in {signature_page_index, stamp_page_index, date_page_index}:
            width = float(page.mediabox.width)
            height = float(page.mediabox.height)
            overlay_stream = io.BytesIO()
            c = canvas.Canvas(overlay_stream, pagesize=(width, height))
            aaie_cell = (
                master_cell
                if master_layout_signature and sonny and index == sonny["page_index"]
                else None
            )
            aaie_asset_bounds = aaie_cell
            if (
                aaie_cell
                and company_date
                and index == company_date["page_index"]
            ):
                protected_bounds = dict(aaie_cell)
                protected_bounds["y0"] = float(aaie_cell["y0"])
                protected_bounds["y1"] = min(
                    float(aaie_cell["y1"]), float(company_date["y"]) - 6
                )
                if protected_bounds["y1"] - protected_bounds["y0"] >= 24:
                    aaie_asset_bounds = protected_bounds
            aaie_asset_placement = None
            if (
                aaie_asset_bounds
                and index == signature_page_index
                and index == stamp_page_index
            ):
                aaie_asset_placement = _contained_aaie_signature_stamp_placement(
                    signature_path,
                    stamp_path,
                    min(placement["signature_width"], 82) * 1.15,
                    min(placement["stamp_width"], 48) * 1.15,
                    aaie_asset_bounds,
                )
            if index == signature_page_index:
                signature_width = min(placement["signature_width"], 115) if master_layout_signature else placement["signature_width"]
                signature_x = min(width - signature_width - 24, max(24, sonny["x1"] - 65) if sonny else placement["signature_x"])
                signature_y = max(24, sonny["y"] - 18 if sonny else placement["signature_y"])
                if aaie_asset_placement:
                    signature_x, signature_y, signature_width = aaie_asset_placement["signature"]
                elif aaie_asset_bounds:
                    signature_x, signature_y, signature_width = _contained_image_placement(
                        signature_path, signature_x, signature_y, signature_width,
                        aaie_asset_bounds,
                    )
                draw_image_preserving_aspect(c, signature_path, signature_x, signature_y, signature_width)
            if index == stamp_page_index:
                if sonny:
                    stamp_width = min(placement["stamp_width"], 78) if master_layout_signature else placement["stamp_width"]
                    signature_y = max(24, sonny["y"] - 18)
                    stamp_x = min(width - stamp_width - 24, max(24, sonny["x1"] - 35))
                    stamp_y = max(24, signature_y - 20)
                else:
                    stamp_width = placement["stamp_width"]
                    stamp_x = placement["stamp_x"]
                    stamp_y = placement["stamp_y"]
                if aaie_asset_placement:
                    stamp_x, stamp_y, stamp_width = aaie_asset_placement["stamp"]
                elif aaie_asset_bounds:
                    stamp_x, stamp_y, stamp_width = _contained_image_placement(
                        stamp_path, stamp_x, stamp_y, stamp_width, aaie_asset_bounds
                    )
                draw_image_preserving_aspect(c, stamp_path, stamp_x, stamp_y, stamp_width)
            if index == date_page_index:
                date_x = min(width - 120, (company_date["x1"] + 10) if company_date else placement["company_date_x"])
                date_y = max(24, (company_date["y"] - 1) if company_date else placement["company_date_y"])
                date_font = reportlab_chinese_font()
                date_size = placement["company_date_font_size"]
                if aaie_cell:
                    date_size = min(10.0, max(6.0, float(date_size)))
                    available = float(aaie_cell["x1"]) - 6 - date_x
                    text_width = pdfmetrics.stringWidth(company_signing_date, date_font, date_size)
                    if available <= 0 or text_width <= 0:
                        raise ValueError("甲方签署日期无法放入边框。")
                    date_size *= min(1.0, available / text_width)
                    if date_size < 6 or date_y < aaie_cell["y0"] + 6 or date_y + date_size > aaie_cell["y1"] - 6:
                        raise ValueError("甲方签署日期无法完整显示在边框内。")
                c.setFont(date_font, date_size)
                c.drawString(date_x, date_y, company_signing_date)
            c.save()
            overlay_stream.seek(0)
            overlay = PdfReader(overlay_stream)
            page.merge_page(overlay.pages[0])
        writer.add_page(page)
    target_pdf.parent.mkdir(parents=True, exist_ok=True)
    with target_pdf.open("wb") as fh:
        writer.write(fh)
    return target_pdf


def apply_manual_aaie_signature_and_stamp(source_pdf, target_pdf, placement, company_signing_date=None):
    source_pdf = Path(source_pdf)
    target_pdf = Path(target_pdf)
    if source_pdf.suffix.lower() != ".pdf":
        raise ValueError("MVP 阶段手动签名盖章只支持 PDF，请先将图片转换为 PDF 后再上传。")
    signature_path, stamp_path = active_contract_asset_paths()
    if not signature_path.is_file() or not stamp_path.is_file():
        raise ValueError("AAIE signature/stamp assets are not configured.")
    reader = PdfReader(str(source_pdf))
    if not reader.pages:
        raise ValueError("签署版合同 PDF 没有页面")
    writer = PdfWriter()
    company_signing_date = company_signing_date or local_company_signing_date()
    page_number = max(1, min(len(reader.pages), int(placement.get("page_number") or len(reader.pages))))
    target_index = page_number - 1
    rotation = int(placement.get("page_rotation") or 0) % 360
    for index, page in enumerate(reader.pages):
        if index == target_index:
            page_width = float(page.mediabox.width)
            page_height = float(page.mediabox.height)
            overlay_stream = io.BytesIO()
            c = canvas.Canvas(overlay_stream, pagesize=(page_width, page_height))
            stamp_x, stamp_y, stamp_w, stamp_h = manual_rect_to_pdf(
                rotation, page_width, page_height,
                float(placement["stamp_x"]), float(placement["stamp_y"]),
                float(placement["stamp_width"]), float(placement["stamp_height"]),
            )
            signature_x, signature_y, signature_w, signature_h = manual_rect_to_pdf(
                rotation, page_width, page_height,
                float(placement["signature_x"]), float(placement["signature_y"]),
                float(placement["signature_width"]), float(placement["signature_height"]),
            )
            date_x, date_y = manual_point_to_pdf(
                rotation, page_width, page_height,
                float(placement["date_x"]), float(placement["date_y"]),
            )
            draw_image_exact_size(c, signature_path, signature_x, signature_y, signature_w, signature_h)
            draw_image_exact_size(c, stamp_path, stamp_x, stamp_y, stamp_w, stamp_h)
            c.setFont(reportlab_chinese_font(), float(placement.get("date_font_size") or 10))
            c.drawString(date_x, date_y, company_signing_date)
            c.save()
            overlay_stream.seek(0)
            overlay = PdfReader(overlay_stream)
            page.merge_page(overlay.pages[0])
        writer.add_page(page)
    target_pdf.parent.mkdir(parents=True, exist_ok=True)
    with target_pdf.open("wb") as fh:
        writer.write(fh)
    return target_pdf


def render_contract_signature_confirmation_pdf(
    target, *, company, parent_signer_name, parent_relationship, parent_contact,
    student_name, contract_title, contract_uid, wechat_identity, signed_at_display,
    signed_ip, user_agent, signature_image_path,
):
    """Render the canonical electronic-signing confirmation page."""
    target = Path(target)
    target.parent.mkdir(parents=True, exist_ok=True)
    fonts = school_plan_reportlab_font_names()
    font = fonts["regular"]
    bold = fonts["bold"]
    c = canvas.Canvas(str(target), pagesize=A4)
    width, height = A4
    c.setFillColor(colors.HexColor("#10233f"))
    c.setFont(bold, 20)
    c.drawString(22 * mm, height - 28 * mm, "AAIE 合同签署确认")
    c.setFont(font, 9)
    c.setFillColor(colors.HexColor("#475569"))
    c.drawString(22 * mm, height - 38 * mm, "Contract Signature Confirmation")
    rows = [
        ("甲方签约主体", company["company_legal_name"]),
        ("甲方 ABN / ACN", company["company_abn_acn"]),
        ("乙方签署人", parent_signer_name),
        ("乙方与学生关系", parent_relationship),
        ("乙方电话 / 邮箱", parent_contact),
        ("学生", student_name),
        ("合同名称", contract_title),
        ("合同编号", contract_uid),
        ("微信身份", wechat_identity),
        ("签署日期", signed_at_display),
        ("签署 IP", signed_ip),
        ("User-Agent", str(user_agent or "")[:92]),
    ]
    y = height - 56 * mm
    c.setFont(font, 9)
    for label, value in rows:
        c.setFillColor(colors.HexColor("#64748b"))
        c.drawString(22 * mm, y, label)
        c.setFillColor(colors.HexColor("#111827"))
        c.drawString(56 * mm, y, str(value or ""))
        y -= 8 * mm
    y -= 8 * mm
    c.setFont(bold, 12)
    c.setFillColor(colors.HexColor("#10233f"))
    c.drawString(22 * mm, y, "家长电子签名")
    y -= 52 * mm
    try:
        c.drawImage(
            ImageReader(signature_image_path), 24 * mm, y,
            width=92 * mm, height=38 * mm, preserveAspectRatio=True, mask="auto",
        )
    except Exception:
        c.setFont(font, 9)
        c.drawString(24 * mm, y + 20 * mm, "签名图片无法预览，请查看系统原始记录。")
    c.setStrokeColor(colors.HexColor("#94a3b8"))
    c.line(24 * mm, y - 2 * mm, 118 * mm, y - 2 * mm)
    c.setFillColor(colors.Color(0.08, 0.36, 0.78, alpha=0.08))
    c.setFont(bold, 28)
    c.saveState()
    c.translate(width / 2, height / 2)
    c.rotate(-28)
    c.drawCentredString(0, 0, "AAIE / AOYA")
    c.restoreState()
    c.setFont(font, 8)
    c.setFillColor(colors.HexColor("#64748b"))
    c.drawString(22 * mm, 16 * mm, "Confidential · Prepared by AAIE / AOYA")
    c.save()
    return target


def workflow_stage_index(stage):
    stage = normalize_workflow_stage(stage)
    keys = [key for key, _ in WORKFLOW_STAGES]
    return keys.index(stage) if stage in keys else 0


def workflow_stage_sort_key(row):
    return workflow_stage_index(row["current_stage"])


def next_workflow_stage(stage):
    index = workflow_stage_index(stage)
    if index >= len(WORKFLOW_STAGES) - 1:
        return WORKFLOW_STAGES[index][0]
    return WORKFLOW_STAGES[index + 1][0]


