def school_plan_share_link_status(link_row):
    if not link_row:
        return "missing"
    status = str(link_row["status"] or "active")
    if status == "revoked":
        return "revoked"
    if status == "confirmed" or link_row["confirmed_at"]:
        return "confirmed"
    if is_expired(link_row["expires_at"]):
        return "expired"
    if link_row["bound_wechat_openid"]:
        return "logged_in"
    if link_row["first_viewed_at"]:
        return "opened"
    return "not_opened"


