def workflow_next_action(stage, alerts=None):
    alerts = alerts or []
    if any(item.get("key") in {"missing_passport", "missing_birth"} for item in alerts):
        return "补齐必需申请材料"
    if any(item.get("key") == "offer_expiring" for item in alerts):
        return "尽快确认 Offer 接受和押金"
    if any(item.get("key") == "visa_expiring" for item in alerts):
        return "检查签证到期提醒并安排后续动作"
    return WORKFLOW_NEXT_ACTIONS.get(normalize_workflow_stage(stage), "暂无下一步事项")


def workflow_state_from_alerts(alerts):
    levels = {item.get("level") for item in alerts or []}
    if "risk" in levels:
        return "risk"
    if "waiting" in levels:
        return "waiting"
    return "normal"


def workflow_progress_html(stage, state="normal"):
    stage = normalize_workflow_stage(stage)
    index = workflow_stage_index(stage)
    steps = " / ".join(
        f"{i + 1}. {label}{' 当前' if i == index else ''}"
        for i, (_, label) in enumerate(WORKFLOW_STAGES)
    )
    segments = "".join(
        f'<i class="stage-segment stage-segment-{i + 1} {"done" if i < index else "current" if i == index else "todo"}" '
        f'title="{i + 1}. {esc(label)}"></i>'
        for i, (_, label) in enumerate(WORKFLOW_STAGES)
    )
    label = workflow_stage_label(stage)
    return (
        f'<div class="stage-progress stage-current-{index + 1} workflow-state-{esc(state)}" title="{esc(steps)}">'
        f'<div class="stage-bar">{segments}</div>'
        f'<div class="stage-caption"><span>{index + 1}/{len(WORKFLOW_STAGES)}</span>{esc(label)}</div>'
        f'</div>'
    )


def workflow_date_value(value):
    if not value:
        return None
    text = str(value).strip()
    if not text:
        return None
    text = text.replace("Z", "+00:00")
    candidates = [text, text[:19], text[:10]]
    for candidate in candidates:
        if not candidate:
            continue
        try:
            return datetime.fromisoformat(candidate).date()
        except ValueError:
            pass
    for fmt in ("%d/%m/%Y", "%d-%m-%Y", "%Y/%m/%d"):
        try:
            return datetime.strptime(text[:10], fmt).date()
        except ValueError:
            pass
    return None


def workflow_days_between(start_value, end_value):
    start = workflow_date_value(start_value)
    end = workflow_date_value(end_value)
    if not start or not end:
        return None
    return max(0, (end - start).days)


MELBOURNE_TZ = ZoneInfo("Australia/Melbourne")
DASHBOARD_BUSINESS_TREND_METRICS = (
    ("signed", "签约", "签约学生人数", "dashboard-business-trend-chart__series--signed"),
    ("offer", "Offer", "获得 Offer 的学生人数", "dashboard-business-trend-chart__series--offer"),
    ("visa", "下签", "获签学生人数", "dashboard-business-trend-chart__series--visa"),
)


def dashboard_business_date_value(value):
    if not value:
        return None
    text = str(value).strip()
    if not text:
        return None
    normalized = text.replace("Z", "+00:00")
    try:
        parsed = datetime.fromisoformat(normalized)
        if parsed.tzinfo:
            return parsed.astimezone(MELBOURNE_TZ).date()
        return parsed.date()
    except ValueError:
        pass
    for candidate in (text[:10], text):
        try:
            return date.fromisoformat(candidate)
        except ValueError:
            pass
    return workflow_date_value(text)


def normalize_dashboard_trend_period(value):
    return value if value in {"weekly", "monthly"} else "weekly"


def dashboard_month_delta(month_start, delta):
    year = month_start.year + ((month_start.month - 1 + delta) // 12)
    month = ((month_start.month - 1 + delta) % 12) + 1
    return date(year, month, 1)


def dashboard_business_trend_periods(period, today=None):
    period = normalize_dashboard_trend_period(period)
    if today is None:
        today = datetime.now(MELBOURNE_TZ).date()
    elif isinstance(today, datetime):
        today = today.astimezone(MELBOURNE_TZ).date() if today.tzinfo else today.date()
    if period == "monthly":
        current_month = today.replace(day=1)
        periods = []
        for offset in range(5, -1, -1):
            start = dashboard_month_delta(current_month, -offset)
            end = dashboard_month_delta(start, 1) - timedelta(days=1)
            periods.append({
                "key": start.strftime("%Y-%m"),
                "label": start.strftime("%b"),
                "range_label": f"{start.isoformat()} 至 {end.isoformat()}",
                "start": start,
                "end": end,
                "partial": start <= today <= end,
            })
        return periods
    current_week = today - timedelta(days=today.weekday())
    periods = []
    for offset in range(7, -1, -1):
        start = current_week - timedelta(days=offset * 7)
        end = start + timedelta(days=6)
        periods.append({
            "key": start.isoformat(),
            "label": f"{start.strftime('%d %b')}",
            "range_label": f"{start.isoformat()} 至 {end.isoformat()}",
            "start": start,
            "end": end,
            "partial": start <= today <= end,
        })
    return periods


def dashboard_business_trend_count(rows, date_key, valid_row, periods):
    per_period = []
    audit = {
        "raw_records": len(rows),
        "eligible_records": 0,
        "deduped_students_total": 0,
        "excluded_duplicate_records": 0,
        "excluded_no_date_records": 0,
        "excluded_invalid_status_records": 0,
        "excluded_unlinked_records": 0,
    }
    for period in periods:
        period_records = 0
        student_ids = set()
        for row in rows:
            if not row["student_id"]:
                continue
            if not valid_row(row):
                continue
            day = dashboard_business_date_value(row[date_key])
            if day and period["start"] <= day <= period["end"]:
                period_records += 1
                student_ids.add(row["student_id"])
        count = len(student_ids)
        per_period.append({
            "period_key": period["key"],
            "raw_records": period_records,
            "value": count,
            "deduped_records": max(0, period_records - count),
        })
        audit["excluded_duplicate_records"] += max(0, period_records - count)
    all_students = set()
    for row in rows:
        if not row["student_id"]:
            audit["excluded_unlinked_records"] += 1
            continue
        if not valid_row(row):
            audit["excluded_invalid_status_records"] += 1
            continue
        if not dashboard_business_date_value(row[date_key]):
            audit["excluded_no_date_records"] += 1
            continue
        audit["eligible_records"] += 1
        all_students.add(row["student_id"])
    audit["deduped_students_total"] = len(all_students)
    return per_period, audit


def dashboard_business_axis_ticks(max_value):
    if max_value <= 0:
        return [0]
    step = max(1, math.ceil(max_value / 3))
    axis_max = step * 3
    return [step * index for index in range(4)]


def dashboard_business_trend_data(period="weekly", today=None):
    period = normalize_dashboard_trend_period(period)
    periods = dashboard_business_trend_periods(period, today)
    signed_rows = db.all(
        """SELECT id,student_id,contract_status,fully_executed_at,deleted_at,voided_at
           FROM contracts"""
    )
    offer_rows = db.all(
        """SELECT id,student_id,document_type,offer_date,offer_status
           FROM offers"""
    )
    visa_rows = db.all(
        """SELECT id,student_id,visa_status,visa_grant_date
           FROM visas"""
    )
    signed_values, signed_audit = dashboard_business_trend_count(
        signed_rows,
        "fully_executed_at",
        lambda row: row["contract_status"] == "FullyExecuted" and not row["deleted_at"] and not row["voided_at"],
        periods,
    )
    offer_values, offer_audit = dashboard_business_trend_count(
        offer_rows,
        "offer_date",
        lambda row: row["document_type"] == "Offer",
        periods,
    )
    visa_values, visa_audit = dashboard_business_trend_count(
        visa_rows,
        "visa_grant_date",
        lambda row: str(row["visa_status"] or "").strip().lower() == "granted",
        periods,
    )
    series = {
        "signed": signed_values,
        "offer": offer_values,
        "visa": visa_values,
    }
    max_value = max((item["value"] for values in series.values() for item in values), default=0)
    ticks = dashboard_business_axis_ticks(max_value)
    axis_max = ticks[-1] if ticks else 0
    return {
        "period": period,
        "periods": [
            {
                **period_item,
                "start": period_item["start"].isoformat(),
                "end": period_item["end"].isoformat(),
            }
            for period_item in periods
        ],
        "series": series,
        "max_value": max_value,
        "axis_max": axis_max,
        "y_ticks": ticks,
        "empty": max_value == 0,
        "audit": {
            "signed": signed_audit,
            "offer": offer_audit,
            "visa": visa_audit,
        },
    }


def dashboard_business_trend_chart_html(trend):
    width = 240
    height = 56
    plot_left = 8
    plot_top = 8
    plot_width = 224
    plot_height = 34
    baseline = plot_top + plot_height
    periods = trend["periods"]
    series = trend["series"]
    period_tabs = "".join(
        f'<a class="{"is-active" if trend["period"] == key else ""}" href="/?trend_period={key}#dashboard-business-trend-chart">{label}</a>'
        for key, label in (("weekly", "按周"), ("monthly", "按月"))
    )
    metric_cards = []
    point_gap = plot_width / max(1, len(periods) - 1)
    first_label = periods[0]["label"] if periods else ""
    last_label = periods[-1]["label"] if periods else ""
    for metric_key, short_label, full_label, class_name in DASHBOARD_BUSINESS_TREND_METRICS:
        values = [item["value"] for item in series[metric_key]]
        metric_max = max(values, default=0)
        coords = []
        points = []
        for period_index, period_item in enumerate(periods):
            value = values[period_index]
            x = plot_left + point_gap * period_index if len(periods) > 1 else plot_left + plot_width / 2
            y = baseline if metric_max <= 0 else baseline - (value / metric_max * plot_height)
            coords.append((x, y))
            point_class = " dashboard-business-trend-chart__sparkline-point--last" if period_index == len(periods) - 1 else ""
            title = f"{period_item['range_label']} · {full_label} · {value} 名学生"
            points.append(
                f'<circle tabindex="0" class="dashboard-business-trend-chart__sparkline-point {class_name}{point_class}" '
                f'cx="{x:.2f}" cy="{y:.2f}" r="{3.8 if point_class else 2.2}">'
                f'<title>{esc(title)}</title></circle>'
            )
        path_d = " ".join(
            f'{"M" if index == 0 else "L"} {x:.2f} {y:.2f}'
            for index, (x, y) in enumerate(coords)
        )
        total = sum(values)
        metric_cards.append(f"""
            <div class="dashboard-business-trend-chart__metric dashboard-business-trend-chart__metric--{metric_key}">
              <div class="dashboard-business-trend-chart__metric-head">
                <span>{esc(short_label)}</span>
                <strong>{total}</strong>
              </div>
              <svg class="dashboard-business-trend-chart__sparkline" viewBox="0 0 {width} {height}" preserveAspectRatio="none" role="img" aria-label="{esc(short_label)}趋势">
                <path class="dashboard-business-trend-chart__sparkline-line {class_name}" d="{path_d}" fill="none"></path>
                <g class="dashboard-business-trend-chart__sparkline-points">{''.join(points)}</g>
              </svg>
              <div class="dashboard-business-trend-chart__range-labels"><span>{esc(first_label)}</span><span>{esc(last_label)}</span></div>
            </div>
        """)
    empty = (
        '<p class="dashboard-business-trend-chart__empty">当前时间范围暂无签约、Offer 或获签记录。</p>'
        if trend["empty"] else ""
    )
    return f"""
        <section id="dashboard-business-trend-chart" class="dashboard-business-trend-chart">
          <header class="dashboard-business-trend-chart__header">
            <div><h2>签约 / Offer / 下签趋势</h2><p>按学生去重，使用真实业务日期统计。</p></div>
            <nav class="dashboard-business-trend-chart__period-tabs" aria-label="趋势周期切换">{period_tabs}</nav>
          </header>
          <div class="dashboard-business-trend-chart__metrics">
            {''.join(metric_cards)}
            {empty}
          </div>
        </section>"""


def dashboard_key_items_30day_windows(today=None):
    if today is None:
        today = datetime.now(MELBOURNE_TZ).date()
    elif isinstance(today, datetime):
        today = today.astimezone(MELBOURNE_TZ).date() if today.tzinfo else today.date()
    return [
        {"key": "future_1_7", "label": "未来1-7天", "start": today, "end": today + timedelta(days=6)},
        {"key": "future_8_14", "label": "未来8-14天", "start": today + timedelta(days=7), "end": today + timedelta(days=13)},
        {"key": "future_15_21", "label": "未来15-21天", "start": today + timedelta(days=14), "end": today + timedelta(days=20)},
        {"key": "future_22_30", "label": "未来22-30天", "start": today + timedelta(days=21), "end": today + timedelta(days=29)},
    ]


def dashboard_key_items_reminder_due_date(row):
    due_value = row["due_datetime"] if row["due_datetime"] else row["due_date"]
    return dashboard_business_date_value(due_value)


def dashboard_key_items_reminder_active(row):
    effective = reminder_effective_status(row)
    if effective in {"Completed", "Dismissed", "Cancelled", "Snoozed"}:
        return False
    if row["completed_at"] or row["dismissed_at"]:
        return False
    return True


def dashboard_key_items_business_key(row, due_day):
    related_module = str(row["related_module"] or "").strip()
    related_record_id = str(row["related_record_id"] or "").strip()
    if related_module and related_record_id:
        return f"related:{related_module}:{related_record_id}", "related", related_module, related_record_id
    source_type = str(row["source_type"] or "").strip()
    source_record_id = str(row["source_record_id"] or "").strip()
    if source_type and source_record_id:
        return f"source:{source_type}:{source_record_id}", "source", source_type, source_record_id
    student_id = str(row["student_id"] or "").strip()
    reminder_type = row["reminder_type"] or "manual"
    return f"fallback:{student_id}:{reminder_type}:{due_day.isoformat()}", "fallback", "", ""


def dashboard_key_items_node_label(row, due_day):
    reminder_day = dashboard_business_date_value(row["reminder_datetime"])
    if reminder_day:
        days = (due_day - reminder_day).days
        if days > 0:
            return f"{days}天"
        if days == 0:
            return "当天"
    return row["title"] or reminder_type_label(row["reminder_type"])


def dashboard_key_items_business_title(reminder_type, due_label, title):
    if reminder_type == "offer_expiry":
        return f"Offer 于 {due_label} 到期"
    return title or reminder_type


def dashboard_key_items_30day_data(today=None):
    windows = dashboard_key_items_30day_windows(today)
    rows = db.all(
        """SELECT r.id,r.student_id,r.reminder_type,r.title,r.due_date,r.due_datetime,r.status,
                  r.completed_at,r.dismissed_at,r.reminder_datetime,r.snooze_until,
                  r.source_type,r.source_record_id,r.related_module,r.related_record_id,
                  s.passport_first_name,s.passport_last_name
           FROM reminders r
           LEFT JOIN students s ON s.student_id=r.student_id
           ORDER BY COALESCE(NULLIF(r.due_datetime,''),NULLIF(r.due_date,'')) ASC,r.id ASC"""
    )
    window_groups = {window["key"]: {} for window in windows}
    seen_ids = set()
    audit = {
        "raw_records": len(rows),
        "nonempty_due_records": 0,
        "eligible_records": 0,
        "eligible_reminder_nodes": 0,
        "business_items": 0,
        "collapsed_reminder_nodes": 0,
        "excluded_duplicate_ids": 0,
        "excluded_no_date": 0,
        "excluded_overdue": 0,
        "excluded_after_range": 0,
        "excluded_completed_or_cancelled": 0,
    }
    range_start = windows[0]["start"]
    range_end = windows[-1]["end"]
    for row in rows:
        reminder_id = row["id"]
        if reminder_id in seen_ids:
            audit["excluded_duplicate_ids"] += 1
            continue
        seen_ids.add(reminder_id)
        due_day = dashboard_key_items_reminder_due_date(row)
        if not due_day:
            audit["excluded_no_date"] += 1
            continue
        audit["nonempty_due_records"] += 1
        if due_day < range_start:
            audit["excluded_overdue"] += 1
            continue
        if due_day > range_end:
            audit["excluded_after_range"] += 1
            continue
        if not dashboard_key_items_reminder_active(row):
            audit["excluded_completed_or_cancelled"] += 1
            continue
        audit["eligible_records"] += 1
        audit["eligible_reminder_nodes"] += 1
        reminder_type = row["reminder_type"] or "manual"
        for window in windows:
            if window["start"] <= due_day <= window["end"]:
                student_id = row["student_id"] or ""
                student_name = " ".join(part for part in [row["passport_first_name"], row["passport_last_name"]] if part).strip()
                student_label = "未关联学生"
                if student_id:
                    student_label = f"{student_name} · {student_id}" if student_name else student_id
                due_label = due_day.strftime("%d/%m")
                aggregation_key, aggregation_source, aggregation_module, aggregation_record_id = dashboard_key_items_business_key(row, due_day)
                grouped = window_groups[window["key"]].get(aggregation_key)
                if grouped is None:
                    grouped = {
                        "id": reminder_id,
                        "first_reminder_id": reminder_id,
                        "reminder_ids": [],
                        "student_id": student_id,
                        "student_label": student_label,
                        "reminder_type": reminder_type,
                        "type_label": reminder_type_label(reminder_type),
                        "due_date": due_day.isoformat(),
                        "due_label": due_label,
                        "title": dashboard_key_items_business_title(reminder_type, due_label, row["title"]),
                        "status": row["status"] or "",
                        "href": f"/students/{student_id}" if student_id else "",
                        "aggregation_key": aggregation_key,
                        "aggregation_source": aggregation_source,
                        "aggregation_module": aggregation_module,
                        "aggregation_record_id": aggregation_record_id,
                        "reminder_node_count": 0,
                        "reminder_node_labels": [],
                    }
                    window_groups[window["key"]][aggregation_key] = grouped
                node_label = dashboard_key_items_node_label(row, due_day)
                grouped["reminder_ids"].append(reminder_id)
                grouped["reminder_node_count"] += 1
                if node_label not in grouped["reminder_node_labels"]:
                    grouped["reminder_node_labels"].append(node_label)
                break
    window_items = {
        window["key"]: sorted(
            window_groups[window["key"]].values(),
            key=lambda item: (item["due_date"], item["first_reminder_id"]),
        )
        for window in windows
    }
    category_totals = {}
    for items in window_items.values():
        for item in items:
            category_totals[item["reminder_type"]] = category_totals.get(item["reminder_type"], 0) + 1
    audit["business_items"] = sum(len(items) for items in window_items.values())
    audit["collapsed_reminder_nodes"] = max(0, audit["eligible_reminder_nodes"] - audit["business_items"])
    max_count = max((len(window_items[window["key"]]) for window in windows), default=0)
    chart_height = 54
    rendered_windows = []
    for window in windows:
        items = window_items[window["key"]]
        count = len(items)
        fill_height = 0 if max_count == 0 else (count / max_count) * chart_height
        categories = {}
        student_ids = set()
        for item in items:
            categories[item["reminder_type"]] = categories.get(item["reminder_type"], 0) + 1
            if item["student_id"]:
                student_ids.add(item["student_id"])
        rendered_windows.append({
            "key": window["key"],
            "label": window["label"],
            "start": window["start"].isoformat(),
            "end": window["end"].isoformat(),
            "range_label": f"{window['start'].strftime('%d/%m')}-{window['end'].strftime('%d/%m')}",
            "count": count,
            "fill_height": fill_height,
            "fill_y": 8 + chart_height - fill_height,
            "categories": categories,
            "student_count": len(student_ids),
            "items": items,
            "hidden_count": max(0, len(items) - 5),
        })
    return {
        "today": windows[0]["start"].isoformat(),
        "end": range_end.isoformat(),
        "total": sum(window["count"] for window in rendered_windows),
        "max_count": max_count,
        "empty": max_count == 0,
        "windows": rendered_windows,
        "category_totals": category_totals,
        "audit": audit,
        "drilldown_supported": False,
        "drilldown_note": "Reminder Center currently supports tab filters only; no date_from/date_to reminder route is available.",
    }


def dashboard_key_items_30day_html(data):
    colors = {
        "future_1_7": "urgent",
        "future_8_14": "soon",
        "future_15_21": "later",
        "future_22_30": "tail",
    }
    windows_html = []
    for window_index, window in enumerate(data["windows"]):
        category_text = "、".join(
            f"{reminder_type_label(kind)} {count}"
            for kind, count in sorted(window["categories"].items(), key=lambda item: (-item[1], item[0]))
        )
        title = f"{window['start']} 至 {window['end']}，共 {window['count']} 项"
        if category_text:
            title += f"，{category_text}"
        fill_height = float(window["fill_height"])
        fill_y = float(window["fill_y"])
        urgency = colors.get(window["key"], "tail")
        detail_html = '<p class="dashboard-key-items-30day__none">暂无事项</p>'
        if window["count"]:
            item_rows = []
            for item in window["items"][:5]:
                student = (
                    f'<a href="{esc(item["href"])}">{esc(item["student_label"])}</a>'
                    if item["href"] else f'<span>{esc(item["student_label"])}</span>'
                )
                node_summary = ""
                if item.get("reminder_node_count", 1) > 1:
                    node_labels = " / ".join(
                        f'<span>{esc(label)}</span>'
                        for label in item.get("reminder_node_labels", [])
                    )
                    node_summary = (
                        f'<small class="dashboard-key-items-30day__node-summary">'
                        f'{item["reminder_node_count"]}个提醒节点：{node_labels}</small>'
                    )
                item_rows.append(f"""
                <div class="dashboard-key-items-30day__popover-item">
                  <time>{esc(item["due_label"])}</time>
                  <div class="dashboard-key-items-30day__popover-main">
                    {student}
                    <span class="dashboard-key-items-30day__popover-title">{esc(item["title"])}</span>
                    {node_summary}
                  </div>
                  <span class="dashboard-key-items-30day__popover-type">{esc(item["type_label"])}</span>
                </div>""")
            more = f'<p class="dashboard-key-items-30day__more">另有 {window["hidden_count"]} 项 · <a href="/reminders">打开提醒中心</a></p>' if window["hidden_count"] else ""
            align_class = "dashboard-key-items-30day__popover-shell--align-left" if window_index < 2 else "dashboard-key-items-30day__popover-shell--align-right"
            popover_align_class = "dashboard-key-items-30day__popover--align-left" if window_index < 2 else "dashboard-key-items-30day__popover--align-right"
            popover_id = f"dashboard-key-items-popover-window-{window_index + 1}"
            anchor_name = f"--dashboard-key-items-window-{window_index + 1}"
            aria_label = f"查看{window['label']}的{window['count']}项关键事项"
            detail_html = f"""
            <div class="dashboard-key-items-30day__popover-shell {align_class}">
              <button type="button" class="dashboard-key-items-30day__trigger" popovertarget="{popover_id}" aria-label="{esc(aria_label)}" style="anchor-name: {anchor_name};">{window["count"]}项 · 查看详情</button>
              <div id="{popover_id}" class="dashboard-key-items-30day__popover {popover_align_class}" popover="auto" style="position-anchor: {anchor_name};">{''.join(item_rows)}{more}</div>
            </div>"""
        windows_html.append(f"""
          <article class="dashboard-key-items-30day__window dashboard-key-items-30day__window--{urgency}" tabindex="0">
            <div class="dashboard-key-items-30day__meta">
              <span class="dashboard-key-items-30day__label">{esc(window["label"])}</span>
              <strong class="dashboard-key-items-30day__count">{window["count"]}</strong>
            </div>
            <svg class="dashboard-key-items-30day__mini-bar" viewBox="0 0 48 72" role="img" aria-label="{esc(title)}">
              <title>{esc(title)}</title>
              <rect class="dashboard-key-items-30day__track" x="18" y="8" width="12" height="54" rx="6"></rect>
              <rect class="dashboard-key-items-30day__fill" x="18" y="{fill_y:.2f}" width="12" height="{fill_height:.2f}" rx="6"></rect>
            </svg>
            <small class="dashboard-key-items-30day__dates">{esc(window["range_label"])}</small>
            {detail_html}
          </article>
        """)
    empty = '<p class="dashboard-key-items-30day__empty">未来30天暂无待处理事项</p>' if data["empty"] else ""
    return f"""
        <section id="dashboard-key-items-30day" class="dashboard-key-items-30day" aria-label="未来30天关键事项">
          <header class="dashboard-key-items-30day__header">
            <div><h2>未来30天关键事项</h2><p>按独立业务事项统计，同一事项的多个提醒节点自动合并。</p></div>
            <span class="dashboard-key-items-30day__total">共 {data["total"]} 项</span>
          </header>
          <div class="dashboard-key-items-30day__windows">{''.join(windows_html)}</div>
          {empty}
        </section>"""


