def student_workflow_overview_html(student, materials_missing, offers, coes, visas, docs):
    doc_categories = {row["folder_category"] for row in docs}
    homestay_itinerary_done = "Homestay + Airport Pickup" in doc_categories
    final_stage = workflow_stage_index(workflow_row_value(student, "current_stage")) >= workflow_stage_index("签证下签或拒签") or homestay_itinerary_done
    steps = [
        ("Parent Form", "Completed" if workflow_row_value(student, "source_token") else "In Progress"),
        ("Materials", "Completed" if workflow_row_value(student, "materials_checked") else ("In Progress" if len(materials_missing) < len(required_application_document_types(workflow_row_value(student, "applying_year_level"))) else "Not Started")),
        ("Offer", "Completed" if offers else "Not Started"),
        ("COE + OSHC", "Completed" if coes else "Not Started"),
        ("VISA", "Completed" if visas else "Not Started"),
        ("Homestay / Airport Pickup / Itinerary", "Completed" if homestay_itinerary_done else "Not Started"),
        ("Completed", "Completed" if final_stage else "Not Started"),
    ]
    current_index = 0
    for index, (_label, status) in enumerate(steps):
        if status == "Completed":
            current_index = min(index + 1, len(steps) - 1)
    rendered = []
    for index, (label, status) in enumerate(steps):
        state = status.lower().replace(" ", "-")
        if index == current_index and status != "Completed":
            state = "in-progress"
            status = "In Progress"
        label_html = workflow_overview_step_label_html(label)
        rendered.append(
            f'<div class="workflow-step {state}">'
            f'<span class="workflow-step-index">{index + 1}</span>'
            f'<div class="workflow-step-body">{label_html}<small>{esc(status)}</small></div>'
            f'</div>'
        )
    return (
        '<div class="student-workflow-overview-stack">'
        '<div class="student-workflow-rail workflow-progress-modern">'
        + "".join(rendered)
        + "</div>"
        + workflow_duration_summary_html(student, final_stage)
        + "</div>"
    )


def workflow_overview_step_label_html(label):
    return f'<strong class="workflow-step-title">{esc(label)}</strong>'


def display_datetime(value):
    if not value:
        return ""
    text = str(value).replace("T", " ")
    if "+" in text:
        text = text.split("+", 1)[0]
    return text[:16]


def content_created_datetime_display(value):
    """Render canonical content creation time in Melbourne local time."""
    if not value:
        return "未填写"
    try:
        parsed = datetime.fromisoformat(str(value).strip().replace("Z", "+00:00"))
        if parsed.tzinfo is None:
            parsed = parsed.replace(tzinfo=timezone.utc)
        return parsed.astimezone(MELBOURNE_TZ).strftime("%d/%m/%Y %H:%M")
    except (TypeError, ValueError):
        return "未填写"


def normalize_contract_status(status):
    text = str(status or "Draft").strip()
    legacy = {
        "active": "Active",
        "published": "Sent",
        "signed": "ParentSigned",
        "parentsigned": "ParentSigned",
        "fullyexecuted": "FullyExecuted",
        "revoked": "Revoked",
        "deleted": "Deleted",
        "voided": "Voided",
        "superseded": "Superseded",
        "cancelled": "Cancelled",
        "expired": "Expired",
        "sent": "Sent",
        "draft": "Draft",
    }
    return legacy.get(text.lower(), text if text in CONTRACT_STATUS_LABELS else "Draft")


def contract_status_label(status):
    status = normalize_contract_status(status)
    return CONTRACT_STATUS_LABELS.get(status, status)


def contract_status_badge(contract):
    status = normalize_contract_status(contract["contract_status"])
    status_classes = {
        "Draft": "status neutral",
        "Active": "status ok",
        "Sent": "status info",
        "ParentSigned": "status warn",
        "FullyExecuted": "status ok",
        "Revoked": "status danger",
        "Deleted": "status dark",
        "Voided": "status danger",
        "Superseded": "status neutral",
        "Cancelled": "status danger",
        "Expired": "status dark",
    }
    class_name = status_classes.get(status, "status neutral")
    time_value = contract["fully_executed_at"] if status == "FullyExecuted" and "fully_executed_at" in contract.keys() else contract["signed_at"]
    signed_line = f'<small>{esc(display_datetime(time_value))}</small>' if status in {"ParentSigned", "FullyExecuted"} and time_value else ""
    return f'<span class="{class_name}">{esc(contract_status_label(status))}</span>{signed_line}'


def contract_status_options(selected=""):
    selected = normalize_contract_status(selected)
    return "".join(
        f'<option value="{esc(value)}" {"selected" if value == selected else ""}>{esc(label)}</option>'
        for value, label in CONTRACT_STATUS_LABELS.items()
    )


def set_workflow_stage(student_id, stage):
    if is_workflow_v2_active(db):
        raise CycleConflictError(
            "canonical Workflow V2 does not accept direct legacy stage writes"
        )
    stage = normalize_workflow_stage(stage)
    current = db.one("SELECT current_stage FROM workflow_status WHERE student_id=?", (student_id,))
    if not current:
        return
    current_stage = normalize_workflow_stage(current["current_stage"])
    current_index = workflow_stage_index(current_stage)
    target_index = workflow_stage_index(stage)
    if target_index <= current_index:
        return
    next_stage = WORKFLOW_STAGES[min(target_index, current_index + 1)][0]
    db.execute("UPDATE workflow_status SET current_stage=? WHERE student_id=?", (next_stage, student_id))
    db.execute("UPDATE students SET current_status=?,updated_at=? WHERE student_id=?", (next_stage, now_iso(), student_id))
    if next_stage == "签约":
        set_workflow_milestone(student_id, "contract_signed_at")
    elif next_stage == "签证递交":
        set_workflow_milestone(student_id, "visa_lodged_at")
    elif next_stage == "签证下签或拒签":
        set_workflow_milestone(student_id, "visa_finalized_at")
    refresh_workflow_completion_metrics(student_id, source="stage_advanced")


def advance_workflow_stage_to(student_id, stage):
    """Advance automatic workflow events through ordered stages without allowing backwards moves."""
    if is_workflow_v2_active(db):
        return "canonical_v2"
    target_stage = normalize_workflow_stage(stage)
    for _ in WORKFLOW_STAGES:
        current = db.one("SELECT current_stage FROM workflow_status WHERE student_id=?", (student_id,))
        if not current:
            return ""
        current_stage = normalize_workflow_stage(current["current_stage"])
        if workflow_stage_index(current_stage) >= workflow_stage_index(target_stage):
            return current_stage
        set_workflow_stage(student_id, target_stage)
    current = db.one("SELECT current_stage FROM workflow_status WHERE student_id=?", (student_id,))
    return normalize_workflow_stage(current["current_stage"]) if current else ""


def safe_filename(filename):
    stem = sanitize_component(Path(filename).stem).replace(" ", "_")
    suffix = re.sub(r"[^A-Za-z0-9.]", "", Path(filename).suffix)[:10].lower()
    return (stem[:160] or "file") + suffix


def student_info_filename_part(value):
    text = re.sub(r"\s+", " ", str(value or "")).strip()
    text = sanitize_component(text)
    text = re.sub(r"\s+", " ", text).strip()
    return text if text != "Unnamed" else ""


def record_value(record, key, default=""):
    if not record:
        return default
    if hasattr(record, "get"):
        return record.get(key, default)
    try:
        return record[key]
    except Exception:
        return default


def student_info_docx_filename(student, version=None):
    first = student_info_filename_part(record_value(student, "passport_first_name"))
    last = student_info_filename_part(record_value(student, "passport_last_name"))
    display_name = f"{first} {last}".strip() if first and last else "Student"
    suffix = f"_v{version}" if version and int(version) > 1 else ""
    return f"{display_name}_info{suffix}.docx"


def student_info_docx_version_path(folder, student):
    folder = Path(folder)
    base = folder / student_info_docx_filename(student)
    if not base.exists():
        return base, 1
    version = 2
    while True:
        candidate = folder / student_info_docx_filename(student, version)
        if not candidate.exists():
            return candidate, version
        version += 1


def ensure_student_info_document_filename(student, document):
    if not student or not document or document["document_type"] != "StudentInfo" or not document["file_path"]:
        return document
    desired_name = student_info_docx_filename(student)
    current_path = Path(document["file_path"])
    if document["stored_name"] == desired_name and document["original_name"] == desired_name and current_path.name == desired_name:
        return document
    folder = nas.student_folder(student)
    safe_current = ensure_within(current_path, folder)
    if not safe_current.is_file():
        return document
    safe_target = safe_current.with_name(desired_name)
    stored_target = current_path.with_name(desired_name)
    version = int(document["version"] or 1)
    if safe_target.exists() and safe_target.resolve() != safe_current.resolve():
        safe_target, version = student_info_docx_version_path(safe_current.parent, student)
        stored_target = current_path.with_name(safe_target.name)
    else:
        version = 1 if safe_target.name == desired_name else version
    if safe_current.resolve() != safe_target.resolve():
        safe_current.rename(safe_target)
    file_size = safe_target.stat().st_size
    db.execute(
        """UPDATE student_documents
           SET original_name=?,stored_name=?,file_path=?,version=?,file_size=?,preview_path=NULL
           WHERE id=?""",
        (safe_target.name, safe_target.name, str(stored_target), version, file_size, document["id"]),
    )
    return db.one("SELECT * FROM student_documents WHERE id=?", (document["id"],))


