def ensure_generated_application_document_filename(document):
    if not document or document["document_type"] not in GENERATED_APPLICATION_DOCUMENT_TYPES or not document["file_path"]:
        return document
    archived_name = Path(document["file_path"]).name
    if not archived_name:
        return document
    if document["original_name"] == archived_name and document["stored_name"] == archived_name:
        return document
    db.execute(
        "UPDATE student_documents SET original_name=?,stored_name=? WHERE id=?",
        (archived_name, archived_name, document["id"]),
    )
    return db.one("SELECT * FROM student_documents WHERE id=?", (document["id"],))
    return db.one("SELECT * FROM student_documents WHERE id=?", (document["id"],))


def next_version_path(folder, filename):
    path = folder / safe_filename(filename)
    if not path.exists():
        match = re.search(r"_V(\d+)$", path.stem, re.I)
        return path, int(match.group(1)) if match else 1
    match = re.search(r"_V(\d+)$", path.stem, re.I)
    base = re.sub(r"_V\d+$", "", path.stem, flags=re.I)
    current = int(match.group(1)) if match else 1
    while True:
        current += 1
        candidate = path.with_name(f"{base}_V{current}{path.suffix}")
        if not candidate.exists():
            return candidate, current


