def abs_region_code_issue(region_code, year="2021", region_type="SAL"):
    code = re.sub(r"[^0-9]", "", str(region_code or "").strip())
    year_digits = re.sub(r"[^0-9]", "", str(year or "").strip())
    region_label = str(region_type or "SAL").upper()
    if not code:
        return f"尚未填写 ABS {region_label} geography code。"
    if year_digits and code == year_digits and len(code) == 4:
        return f"ABS {region_label} Code 看起来填的是年份 {code}，不是 geography code。"
    if len(code) < 5:
        return f"ABS {region_label} Code 位数太短，请先确认正确的 ABS geography code。"
    return ""

