def data_update_property_rows(path, property_type, period=""):
    from scripts import import_vic_school_living_costs as living_import

    try:
        rows = list(living_import.worksheet_rows(path))
    except Exception:
        rows = living_import.legacy_property_xls_rows(path, period=period)
    if not rows and str(path).lower().endswith(".xls"):
        rows = living_import.legacy_property_xls_rows(path, period=period)
    prepared = []
    for row in rows:
        suburb = str(row.get("suburb") or row.get("locality") or row.get("town") or "").strip()
        price = living_import.clean_number(row.get("median_sale_price") or row.get("median_price") or row.get("median"))
        if not suburb or price is None:
            continue
        sales_count = living_import.clean_number(row.get("sales_count") or row.get("number_of_sales") or row.get("sales"))
        prepared.append({
            "suburb": suburb,
            "property_type": property_type,
            "median_sale_price": price,
            "period": period or str(row.get("period") or row.get("quarter") or Path(path).stem).strip(),
            "sales_count": int(sales_count) if sales_count is not None else None,
        })
    return prepared

