def data_update_row_lookup(row, *names):
    normalized = {re.sub(r"[^a-z0-9]+", "_", str(key or "").strip().lower()).strip("_"): value for key, value in row.items()}
    for name in names:
        key = re.sub(r"[^a-z0-9]+", "_", str(name or "").strip().lower()).strip("_")
        if key in normalized and normalized[key] not in {None, ""}:
            return normalized[key]
    return ""

def data_update_spreadsheet_rows(path):
    path = Path(path)
    if path.suffix.lower() == ".csv":
        with path.open("r", encoding="utf-8-sig", newline="") as handle:
            yield from csv.DictReader(handle)
        return
    workbook = load_workbook(path, read_only=True, data_only=True)
    try:
        for sheet in workbook.worksheets:
            rows = list(sheet.iter_rows(values_only=True))
            header_index = None
            headers = []
            for index, row in enumerate(rows[:40]):
                cleaned = [str(cell or "").strip() for cell in row]
                normalized = {re.sub(r"[^a-z0-9]+", "_", item.lower()).strip("_") for item in cleaned if item}
                if normalized.intersection({"suburb", "postcode", "lga", "lga_name", "area_name", "data_level", "area_type"}):
                    header_index = index
                    headers = cleaned
                    break
            if header_index is None:
                continue
            for raw in rows[header_index + 1:]:
                item = {headers[i]: raw[i] for i in range(min(len(headers), len(raw))) if headers[i]}
                if len([value for value in item.values() if value not in {None, ""}]) >= 2:
                    yield item
    finally:
        workbook.close()

def data_update_crime_data_level(row):
    level = str(data_update_row_lookup(row, "data_level", "area_type", "data level", "area type") or "").strip().lower()
    level = {"local government area": "lga", "suburb/town": "suburb"}.get(level, level)
    if level in CSA_CRIME_DATA_LEVELS:
        return level
    if data_update_row_lookup(row, "suburb", "locality", "suburb/town name"):
        return "suburb"
    if data_update_row_lookup(row, "postcode", "post code"):
        return "postcode"
    if data_update_row_lookup(row, "lga", "lga_name", "local government area"):
        return "lga"
    return ""

def data_update_stage_vic_crime_statistics(db_handle, job_id, source_file, state="VIC"):
    source_file = Path(source_file)
    state = str(state or "").strip().upper()
    if state not in SCHOOL_DATA_IMPORT_STATES:
        raise ValueError(f"Unsupported crime data state: {state or '(blank)'}")
    stamp = now_iso()
    db_handle.execute("DELETE FROM staging_crime_statistics WHERE job_id=?", (job_id,))
    created = updated = failed = 0
    staged_suburbs = []
    staged_postcodes = []
    staged_lgas = []
    periods = set()
    rows = []
    if state == "VIC":
        try:
            from scripts import import_vic_crime_stats as vic_crime_import

            resource = {"url": str(source_file), "name": source_file.name}
            stats = vic_crime_import.aggregate_recorded_offences(resource, source_file)
            if stats:
                latest_period = max((stat.get("data_year_ending") or "" for stat in stats), key=csa_crime_year_ending_sort_key)
                stats = [stat for stat in stats if (stat.get("data_year_ending") or "") == latest_period]
            for stat in stats:
                rows.append({
                    "data_level": stat.get("data_level"),
                    "area_name": stat.get("area_name"),
                    "suburb": stat.get("suburb"),
                    "postcode": stat.get("postcode"),
                    "lga_name": stat.get("lga_name"),
                    "data_year_ending": stat.get("data_year_ending"),
                    "source_dataset": stat.get("source_dataset") or "recorded_offences",
                    "total_recorded_offences": stat.get("total_recorded_offences"),
                    "offence_rate_per_100000": stat.get("offence_rate_per_100000"),
                })
        except Exception:
            rows = []
    if not rows:
        rows = list(data_update_spreadsheet_rows(source_file))
    existing_keys = {
        (
            row["area_type"],
            str(row["area_name"] or "").strip().lower(),
            row["offence_category"] or "",
            row["source_period"] or "",
        )
        for row in db_handle.all(
            """SELECT area_type,area_name,offence_category,source_period
               FROM crime_statistics
               WHERE state=?""",
            (state,),
        )
    }
    staged_records = []
    for row in rows:
        data_level = data_update_crime_data_level(row)
        if not data_level:
            failed += 1
            continue
        suburb = str(data_update_row_lookup(row, "suburb", "locality", "suburb/town name") or "").strip()
        postcode = re.sub(r"[^0-9]", "", str(data_update_row_lookup(row, "postcode", "post code") or ""))
        lga_name = str(data_update_row_lookup(row, "lga", "lga_name", "local government area") or "").strip()
        area_name = str(data_update_row_lookup(row, "area_name", "area", "local government area") or "").strip()
        if data_level == "suburb":
            area_name = suburb or area_name
        elif data_level == "postcode":
            area_name = postcode or area_name
        elif data_level == "lga":
            area_name = lga_name or area_name
        period = str(data_update_row_lookup(row, "data_year_ending", "year ending", "period", "source_period") or source_file.stem).strip()
        source_dataset = str(data_update_row_lookup(row, "source_dataset", "dataset") or "recorded_offences").strip()
        offence_count = csa_crime_number(data_update_row_lookup(row, "total_recorded_offences", "recorded offences", "offences", "offence_count"), integer=True)
        offence_rate = csa_crime_number(data_update_row_lookup(row, "offence_rate_per_100000", "rate per 100,000 population", "offence rate", "offence_rate_per_100k"))
        if not area_name or not period or (offence_count is None and offence_rate is None):
            failed += 1
            continue
        if suburb:
            staged_suburbs.append(suburb)
        if postcode:
            staged_postcodes.append(postcode)
        if lga_name:
            staged_lgas.append(lga_name)
        periods.add(period)
        if (data_level, area_name.strip().lower(), "recorded_offences", period) in existing_keys:
            updated += 1
        else:
            created += 1
        staged_records.append(
            (
                job_id, state, data_level, area_name.strip(), suburb, postcode, lga_name.strip(),
                "recorded_offences", source_dataset, offence_count, offence_rate,
                "", period, CSA_CRIME_SOURCE if state == "VIC" else f"{state} crime data manual upload", period, stamp, "Valid", "",
            )
        )
    source_period = sorted(periods, key=csa_crime_year_ending_sort_key)[-1] if periods else ""
    if source_period:
        staged_records = [record for record in staged_records if record[14] == source_period]
        created = updated = 0
        staged_suburbs = [record[4] for record in staged_records if record[4]]
        staged_postcodes = [record[5] for record in staged_records if record[5]]
        staged_lgas = [record[6] for record in staged_records if record[6]]
        for record in staged_records:
            key = (record[2], str(record[3] or "").strip().lower(), record[7] or "", record[14] or "")
            if key in existing_keys:
                updated += 1
            else:
                created += 1
    if staged_records:
        with db_handle.transaction() as conn:
            conn.executemany(
                """INSERT INTO staging_crime_statistics(
                   job_id,state,area_type,area_name,suburb,postcode,lga_name,
                   offence_category,offence_subcategory,offence_count,offence_rate_per_100k,
                   period_start,period_end,source,source_period,last_updated,
                   validation_status,validation_error
                ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                staged_records,
            )
    unmatched_lga = 0
    for lga in sorted({item for item in staged_lgas if item}):
        if not db_handle.one("SELECT 1 found FROM geo_areas WHERE UPPER(COALESCE(state,''))=? AND lower(COALESCE(area_name,''))=lower(?) LIMIT 1", (state, lga)):
            unmatched_lga += 1
    return {
        "source_name": "Crime Statistics Agency Victoria" if state == "VIC" else f"{state} crime data manual upload",
        "source_file": str(source_file),
        "source_period": source_period,
        "records_found": created + updated + failed,
        "records_created": created,
        "records_updated": updated,
        "records_failed": failed,
        "unmatched_suburb_count": data_update_area_unmatched_count(db_handle, state, staged_suburbs),
        "unmatched_postcode_count": len({postcode for postcode in staged_postcodes if postcode}) if not staged_postcodes else 0,
        "unmatched_lga_sa2_count": unmatched_lga,
        "needs_manual_confirmation_count": created + updated,
        "affected_school_count": db_handle.one("SELECT COUNT(*) count FROM schools WHERE UPPER(COALESCE(state,''))=?", (state,))["count"],
        "recalculates_market_summary": False,
        "recalculates_crime_summary": True,
        "publish_requires_confirmation": True,
    }

def data_update_stage_nsw_crime_statistics(db_handle, job_id, source_file):
    from scripts import import_au_crime_stats as au_crime_import

    source_file = Path(source_file)
    source_url = f"{au_crime_import.NSW_BOCSAR_SOURCE_PAGE} | {au_crime_import.NSW_BOCSAR_LGA_URL}"
    stats = au_crime_import.parse_nsw_bocsar_lga(source_file, source_url)
    stamp = now_iso()
    db_handle.execute("DELETE FROM staging_crime_statistics WHERE job_id=?", (job_id,))
    existing_keys = {
        (
            row["area_type"],
            str(row["area_name"] or "").strip().lower(),
            row["offence_category"] or "",
            row["source_period"] or "",
        )
        for row in db_handle.all(
            """SELECT area_type,area_name,offence_category,source_period
               FROM crime_statistics
               WHERE state='NSW'"""
        )
    }
    created = updated = failed = 0
    staged_lgas = []
    periods = set()
    staged_records = []
    for stat in stats:
        area_name = str(stat.get("area_name") or stat.get("lga_name") or "").strip()
        period = str(stat.get("data_year_ending") or "").strip()
        offence_count = stat.get("total_recorded_offences")
        if not area_name or not period or offence_count is None:
            failed += 1
            continue
        staged_lgas.append(area_name)
        periods.add(period)
        key = ("lga", area_name.lower(), "recorded_offences", period)
        if key in existing_keys:
            updated += 1
        else:
            created += 1
        staged_records.append((
            job_id, "NSW", "lga", area_name, "", "", area_name,
            "recorded_offences", stat.get("source_dataset") or "nsw_bocsar_lga_recorded_criminal_incidents",
            offence_count, stat.get("offence_rate_per_100000"),
            "", period, stat.get("source") or "NSW Bureau of Crime Statistics and Research",
            period, stamp, "Valid", "",
        ))
    if staged_records:
        with db_handle.transaction() as conn:
            conn.executemany(
                """INSERT INTO staging_crime_statistics(
                   job_id,state,area_type,area_name,suburb,postcode,lga_name,
                   offence_category,offence_subcategory,offence_count,offence_rate_per_100k,
                   period_start,period_end,source,source_period,last_updated,
                   validation_status,validation_error
                ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                staged_records,
            )
    unmatched_lga = 0
    for lga in sorted({item for item in staged_lgas if item}):
        if not db_handle.one("SELECT 1 found FROM geo_areas WHERE UPPER(COALESCE(state,''))='NSW' AND lower(COALESCE(area_name,''))=lower(?) LIMIT 1", (lga,)):
            unmatched_lga += 1
    source_period = sorted(periods, key=csa_crime_year_ending_sort_key)[-1] if periods else ""
    return {
        "source_name": "NSW Bureau of Crime Statistics and Research",
        "source_file": str(source_file),
        "source_period": source_period,
        "records_found": created + updated + failed,
        "records_created": created,
        "records_updated": updated,
        "records_failed": failed,
        "unmatched_suburb_count": 0,
        "unmatched_postcode_count": 0,
        "unmatched_lga_sa2_count": unmatched_lga,
        "needs_manual_confirmation_count": created + updated,
        "affected_school_count": db_handle.one("SELECT COUNT(*) count FROM schools WHERE UPPER(COALESCE(state,''))='NSW'")["count"],
        "recalculates_market_summary": False,
        "recalculates_crime_summary": True,
        "publish_requires_confirmation": True,
    }

def data_update_school_sector_key(value):
    text = str(value or "").strip().lower()
    if any(token in text for token in ("government", "public", "gov")):
        return "public"
    if any(token in text for token in ("catholic", "independent", "private", "non-government", "nongovernment")):
        return "private"
    return "public" if not text else text

def data_update_stage_school_base(db_handle, job_id, source_file):
    source_file = Path(source_file)
    rows = list(data_update_spreadsheet_rows(source_file))
    stamp = now_iso()
    db_handle.execute("DELETE FROM staging_schools WHERE job_id=?", (job_id,))
    created = updated = failed = 0
    staged_suburbs = []
    periods = set()
    for row in rows:
        school_name = str(data_update_row_lookup(row, "school_name", "school name", "name") or "").strip()
        state = str(data_update_row_lookup(row, "state") or "VIC").strip().upper()
        if not school_name or not state:
            failed += 1
            continue
        sector = str(data_update_row_lookup(row, "sector", "school_sector", "education_sector") or "").strip()
        school_type = str(data_update_row_lookup(row, "school_type", "school type", "type") or ("Public" if data_update_school_sector_key(sector) == "public" else "Private")).strip()
        address = str(data_update_row_lookup(row, "address", "school_address", "street_address") or "").strip()
        suburb = str(data_update_row_lookup(row, "suburb", "town", "locality") or "").strip()
        postcode = re.sub(r"[^0-9]", "", str(data_update_row_lookup(row, "postcode", "post_code", "postal_code") or ""))
        latitude = market_number(data_update_row_lookup(row, "latitude", "lat", "y"))
        longitude = market_number(data_update_row_lookup(row, "longitude", "lon", "lng", "x"))
        year_levels = str(data_update_row_lookup(row, "year_levels", "year levels") or "").strip()
        website = str(data_update_row_lookup(row, "website", "website_url", "school_website") or "").strip()
        existing = db_handle.one("SELECT id FROM schools WHERE UPPER(COALESCE(state,''))=? AND school_name=?", (state, school_name))
        if existing:
            updated += 1
            school_id = existing["id"]
        else:
            created += 1
            school_id = None
        if suburb:
            staged_suburbs.append(suburb)
        periods.add(source_file.stem)
        db_handle.execute(
            """INSERT INTO staging_schools(
               job_id,school_id,school_name,state,sector,school_type,address,suburb,postcode,
               latitude,longitude,year_levels,website,source,status,last_updated,validation_status,validation_error
            ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
            (
                job_id, school_id, school_name, state, sector, school_type, address, suburb, postcode,
                latitude, longitude, year_levels, website, str(source_file), "active", stamp, "Valid", "",
            ),
        )
    return {
        "source_name": "School basic data",
        "source_file": str(source_file),
        "source_period": sorted(periods)[-1] if periods else "",
        "records_found": created + updated + failed,
        "records_created": created,
        "records_updated": updated,
        "records_failed": failed,
        "records_inactivated": 0,
        "unmatched_suburb_count": data_update_area_unmatched_count(db_handle, "VIC", staged_suburbs),
        "unmatched_postcode_count": 0,
        "unmatched_lga_sa2_count": 0,
        "needs_manual_confirmation_count": created + updated,
        "affected_school_count": created + updated,
        "recalculates_market_summary": True,
        "recalculates_crime_summary": True,
        "publish_requires_confirmation": True,
    }

def data_update_profile_normalize_key(value):
    return re.sub(r"[^a-z0-9]+", "_", str(value or "").strip().lower()).strip("_")

def data_update_profile_lookup(row, *aliases):
    wanted = {data_update_profile_normalize_key(alias) for alias in aliases}
    for key, value in row.items():
        if data_update_profile_normalize_key(key) in wanted and value not in {None, ""}:
            return value, str(key or "")
    return "", ""

def data_update_profile_number(value):
    if value is None:
        return None
    text = str(value).replace(",", "").replace("%", "").strip()
    if not text:
        return None
    match = re.search(r"-?\d+(?:\.\d+)?", text)
    if not match:
        return None
    try:
        return float(match.group(0))
    except ValueError:
        return None

def data_update_profile_int(value):
    number = data_update_profile_number(value)
    return int(round(number)) if number is not None else None

def data_update_profile_percentage(value):
    number = data_update_profile_number(value)
    if number is None:
        return None
    return round(number, 2)

def data_update_school_profile_rows(path):
    path = Path(path)
    if path.suffix.lower() == ".csv":
        with path.open("r", encoding="utf-8-sig", newline="") as handle:
            yield from csv.DictReader(handle)
        return
    workbook = load_workbook(path, read_only=True, data_only=True)
    header_markers = {
        "school_name", "school", "acara_school_id", "acara_id", "myschool_school_id",
        "calendar_year", "source_year", "data_year", "icsea", "school_icsea_value",
        "total_enrolments", "total_enrolment", "boys", "girls",
    }
    try:
        for sheet in workbook.worksheets:
            rows = list(sheet.iter_rows(values_only=True))
            header_index = None
            headers = []
            for index, raw in enumerate(rows[:60]):
                cleaned = [str(cell or "").strip() for cell in raw]
                normalized = {data_update_profile_normalize_key(item) for item in cleaned if item}
                if len(normalized.intersection(header_markers)) >= 2 or (
                    "school_name" in normalized and {"boys", "girls"}.intersection(normalized)
                ):
                    header_index = index
                    headers = cleaned
                    break
            if header_index is None:
                continue
            for raw in rows[header_index + 1:]:
                item = {headers[i]: raw[i] for i in range(min(len(headers), len(raw))) if headers[i]}
                if len([value for value in item.values() if value not in {None, ""}]) >= 2:
                    yield item
    finally:
        workbook.close()

def data_update_acara_fetch_bytes(location):
    location = str(location or "").strip()
    if not location:
        raise ValueError("ACARA source URL is empty.")
    parsed = urlparse(location)
    if parsed.scheme in {"", "file"}:
        local_path = Path(unquote(parsed.path)) if parsed.scheme == "file" else Path(location)
        payload = local_path.read_bytes()
        if len(payload) > ACARA_DOWNLOAD_MAX_BYTES:
            raise ValueError("ACARA source file is too large.")
        return payload, local_path.name, local_path.as_uri()
    request = urllib.request.Request(
        location,
        headers={
            "User-Agent": "AAIE-CRM/1.0 (+https://www.aaie.com.au; ACARA data update)",
            "Accept": "text/html,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,*/*",
        },
    )
    with urllib.request.urlopen(request, timeout=90) as response:
        payload = response.read(ACARA_DOWNLOAD_MAX_BYTES + 1)
        if len(payload) > ACARA_DOWNLOAD_MAX_BYTES:
            raise ValueError("ACARA source file is too large.")
        final_url = response.geturl()
    filename = Path(unquote(urlparse(final_url).path)).name or Path(unquote(parsed.path)).name or "acara_school_profile.xlsx"
    return payload, filename, final_url

def data_update_acara_fetch_text(location):
    payload, _filename, final_url = data_update_acara_fetch_bytes(location)
    try:
        return payload.decode("utf-8"), final_url
    except UnicodeDecodeError:
        return payload.decode("latin-1", errors="replace"), final_url

def data_update_acara_profile_link_from_html(html_text, base_url):
    candidates = []
    for match in re.finditer(r"<a\b[^>]*href=[\"']([^\"']+)[\"'][^>]*>(.*?)</a>", html_text or "", re.I | re.S):
        href = html.unescape(match.group(1)).strip()
        label = html.unescape(re.sub(r"<[^>]+>", " ", match.group(2) or " "))
        combined = f"{label} {href}"
        normalized = re.sub(r"[^a-z0-9]+", " ", combined.lower()).strip()
        suffix = Path(urlparse(href).path).suffix.lower()
        if suffix not in {".xlsx", ".xlsm", ".csv"}:
            continue
        if "school profile" not in normalized and "schoolprofile" not in combined.lower().replace(" ", ""):
            continue
        if "school location" in normalized:
            continue
        years = [int(item) for item in re.findall(r"\b(20\d{2})\b", combined)]
        latest_year = max(years) if years else 0
        is_historical = any(word in normalized for word in ("historical", "2008 2025", "2008-2025"))
        score = latest_year * 10 + (0 if is_historical else 100000) + (1000 if label else 0)
        candidates.append((score, latest_year, urljoin(base_url, href)))
    if not candidates:
        raise FileNotFoundError("Could not find a School Profile XLSX link on the ACARA data access page.")
    candidates.sort(reverse=True)
    return candidates[0][2]

def data_update_download_acara_school_profile(source_paths=None):
    source_paths = source_paths or {}
    download_url = source_paths.get("school_profile_download_url")
    index_location = (
        source_paths.get("school_profile_index_file")
        or source_paths.get("school_profile_index_url")
        or source_paths.get("school_profile_page_url")
        or ACARA_DATA_ACCESS_URL
    )
    if not download_url:
        if source_paths.get("school_profile_index_file"):
            index_location = Path(index_location).resolve().as_uri()
        page_html, final_index_url = data_update_acara_fetch_text(index_location)
        download_url = data_update_acara_profile_link_from_html(page_html, final_index_url)
    payload, filename, final_download_url = data_update_acara_fetch_bytes(download_url)
    suffix = Path(urlparse(final_download_url).path).suffix.lower() or Path(filename).suffix.lower()
    if suffix not in {".xlsx", ".xlsm", ".csv"}:
        raise ValueError("ACARA School Profile download is not an XLSX, XLSM, or CSV file.")
    download_dir = Path(source_paths.get("school_profile_download_dir") or ACARA_SCHOOL_PROFILE_DIR)
    download_dir.mkdir(parents=True, exist_ok=True)
    stored_path, _version = next_version_path(download_dir, filename or f"acara_school_profile{suffix}")
    stored_path.write_bytes(payload)
    return {
        "path": stored_path,
        "source_url": final_download_url,
        "index_url": index_location,
    }

def data_update_profile_calculated_values(values):
    total = values.get("total_enrolments")
    boys = values.get("boys_count")
    girls = values.get("girls_count")
    teaching_fte = values.get("teaching_staff_fte")
    school_icsea = values.get("school_icsea_value")
    average_icsea = values.get("average_icsea_value")
    notes = []
    if school_icsea is not None and average_icsea is None:
        average_icsea = 1000
        values["average_icsea_value"] = 1000
        values["icsea_comparison_baseline"] = 1000
        notes.append("Average ICSEA value not supplied; national ICSEA baseline 1000 used.")
    elif average_icsea is not None:
        values["icsea_comparison_baseline"] = average_icsea
    if total:
        if boys is None and girls is not None and total >= girls:
            boys = int(round(total - girls))
            values["boys_count"] = boys
        if girls is None and boys is not None and total >= boys:
            girls = int(round(total - boys))
            values["girls_count"] = girls
        if boys is not None:
            values["boys_percentage"] = round(boys / total * 100, 2)
        if girls is not None:
            values["girls_percentage"] = round(girls / total * 100, 2)
        if values.get("boys_percentage") is not None and values.get("girls_percentage") is not None:
            values["gender_balance_score"] = round(abs(values["boys_percentage"] - values["girls_percentage"]), 2)
        if values.get("indigenous_students_value_type") == "count" and values.get("indigenous_students_value") is not None:
            values["indigenous_students_percentage"] = round(values["indigenous_students_value"] / total * 100, 2)
        if values.get("lbote_value_type") == "count" and values.get("lbote_value") is not None:
            values["lbote_percentage"] = round(values["lbote_value"] / total * 100, 2)
    if values.get("indigenous_students_value_type") == "percentage" and values.get("indigenous_students_value") is not None:
        values["indigenous_students_percentage"] = data_update_profile_percentage(values["indigenous_students_value"])
    if values.get("lbote_value_type") == "percentage" and values.get("lbote_value") is not None:
        values["lbote_percentage"] = data_update_profile_percentage(values["lbote_value"])
    if total and teaching_fte:
        values["student_to_teacher_ratio"] = round(total / teaching_fte, 2)
    if school_icsea is not None and average_icsea is not None:
        values["icsea_difference_from_baseline"] = int(round(school_icsea - average_icsea))
    values["notes"] = " ".join(part for part in [values.get("notes") or "", " ".join(notes)] if part).strip()
    return values

def data_update_profile_extract_row(row, source_file, imported_at, source_url=""):
    school_name, _ = data_update_profile_lookup(row, "school_name", "school name", "school")
    state, _ = data_update_profile_lookup(row, "state", "state_name")
    suburb, _ = data_update_profile_lookup(row, "suburb", "town", "locality")
    postcode, _ = data_update_profile_lookup(row, "postcode", "post_code", "postal_code")
    sector, _ = data_update_profile_lookup(row, "sector", "school_sector", "education_sector")
    source_year, _ = data_update_profile_lookup(row, "source_year", "calendar_year", "data_year", "year")
    acara_school_id, _ = data_update_profile_lookup(row, "acara_school_id", "acara sml id", "acara id", "acara school id", "school_id")
    myschool_school_id, _ = data_update_profile_lookup(row, "myschool_school_id", "my school id", "myschool id")
    indigenous_value, indigenous_header = data_update_profile_lookup(row, "indigenous_students_percentage", "indigenous students percentage", "indigenous students (%)", "indigenous enrolments (%)", "indigenous_students", "indigenous students")
    lbote_value, lbote_header = data_update_profile_lookup(row, "lbote_percentage", "language_background_other_than_english_percentage", "language background other than english (%)", "language background other than english - yes (%)", "language_background_other_than_english_yes", "language_background_other_than_english", "language background other than english", "lbote")
    average_icsea, _ = data_update_profile_lookup(row, "average_icsea_value", "average icsea value", "national_icsea_baseline")
    values = {
        "acara_school_id": str(acara_school_id or "").strip(),
        "myschool_school_id": str(myschool_school_id or "").strip(),
        "source_year": str(source_year or "").strip(),
        "school_icsea_value": data_update_profile_int(data_update_profile_lookup(row, "school_icsea_value", "school icsea value", "icsea_value", "icsea")[0]),
        "average_icsea_value": data_update_profile_int(average_icsea),
        "icsea_comparison_baseline": data_update_profile_int(average_icsea),
        "teaching_staff_headcount": data_update_profile_int(data_update_profile_lookup(row, "teaching_staff_headcount", "teaching staff", "teaching_staff")[0]),
        "teaching_staff_fte": data_update_profile_number(data_update_profile_lookup(row, "teaching_staff_fte", "full_time_equivalent_teaching_staff", "full-time equivalent teaching staff", "fte teaching staff")[0]),
        "non_teaching_staff_headcount": data_update_profile_int(data_update_profile_lookup(row, "non_teaching_staff_headcount", "non-teaching staff", "non teaching staff", "non_teaching_staff")[0]),
        "non_teaching_staff_fte": data_update_profile_number(data_update_profile_lookup(row, "non_teaching_staff_fte", "full_time_equivalent_non_teaching_staff", "full-time equivalent non-teaching staff", "fte non teaching staff")[0]),
        "total_enrolments": data_update_profile_int(data_update_profile_lookup(row, "total_enrolments", "total enrolments", "total enrolment", "enrolments")[0]),
        "boys_count": data_update_profile_int(data_update_profile_lookup(row, "boys_count", "boys", "boys enrolments", "boys enrolment", "male_enrolments", "male enrolments")[0]),
        "girls_count": data_update_profile_int(data_update_profile_lookup(row, "girls_count", "girls", "girls enrolments", "girls enrolment", "female_enrolments", "female enrolments")[0]),
        "boys_percentage": None,
        "girls_percentage": None,
        "gender_balance_score": None,
        "indigenous_students_value": data_update_profile_number(indigenous_value),
        "indigenous_students_value_type": "percentage" if "%" in indigenous_header or "percentage" in data_update_profile_normalize_key(indigenous_header) else "count",
        "indigenous_students_percentage": data_update_profile_percentage(indigenous_value) if ("%" in indigenous_header or "percentage" in data_update_profile_normalize_key(indigenous_header)) else None,
        "lbote_value": data_update_profile_number(lbote_value),
        "lbote_value_type": "percentage" if "%" in lbote_header or "percentage" in data_update_profile_normalize_key(lbote_header) else "count",
        "lbote_percentage": data_update_profile_percentage(lbote_value) if ("%" in lbote_header or "percentage" in data_update_profile_normalize_key(lbote_header)) else None,
        "student_to_teacher_ratio": None,
        "icsea_difference_from_baseline": None,
        "source_name": "ACARA School Profile Data",
        "source_url": source_url,
        "source_file_name": Path(source_file).name,
        "imported_at": imported_at,
        "last_updated": imported_at,
        "is_active": 0,
        "version_number": 1,
        "confidence_level": "low",
        "notes": "",
        "source_school_name": str(school_name or "").strip(),
        "source_state": str(state or "").strip().upper(),
        "source_suburb": str(suburb or "").strip(),
        "source_postcode": re.sub(r"[^0-9]", "", str(postcode or "")),
        "source_sector": str(sector or "").strip(),
    }
    return data_update_profile_calculated_values(values)

def data_update_profile_name_key(value):
    return re.sub(r"[^a-z0-9]+", "", str(value or "").lower())

def data_update_profile_multi_text_values(value):
    text = str(value or "").strip()
    if not text:
        return []
    parts = re.split(r"\s*(?:\||/|;|\n|\bor\b|\band\b)\s*", text, flags=re.I)
    values = []
    for part in parts:
        cleaned = re.sub(r"\s+", " ", part).strip(" ,")
        if cleaned and cleaned not in values:
            values.append(cleaned)
    return values or [text]

def data_update_profile_postcode_values(value):
    text = str(value or "")
    values = re.findall(r"\b\d{4}\b", text)
    if values:
        return list(dict.fromkeys(values))
    compact = re.sub(r"[^0-9]", "", text)
    return [compact] if compact else []

def data_update_school_profile_match_context(db_handle):
    schools = db_handle.all("SELECT * FROM schools ORDER BY school_name")
    schools_by_id = {row["id"]: row for row in schools}
    schools_by_state = {}
    schools_by_name = {}
    schools_by_state_name = {}
    schools_by_state_postcode = {}
    schools_by_state_suburb = {}
    school_name_keys = {}
    school_sector_keys = {}
    for school in schools:
        state = str(school["state"] if "state" in school.keys() and school["state"] else "").upper()
        name_key = data_update_profile_name_key(school["school_name"])
        suburb_keys = [
            key for key in (data_update_profile_name_key(item) for item in data_update_profile_multi_text_values(school["suburb"] if "suburb" in school.keys() else ""))
            if key
        ]
        postcode_values = data_update_profile_postcode_values(school["postcode"] if "postcode" in school.keys() and school["postcode"] else "")
        schools_by_state.setdefault(state, []).append(school)
        school_name_keys[school["id"]] = name_key
        school_sector_keys[school["id"]] = data_update_school_sector_key(school["sector_key"] if "sector_key" in school.keys() else school["school_type"])
        if name_key:
            schools_by_name.setdefault(name_key, []).append(school)
            schools_by_state_name.setdefault((state, name_key), []).append(school)
        for postcode in postcode_values:
            schools_by_state_postcode.setdefault((state, postcode), []).append(school)
        for suburb_key in suburb_keys:
            schools_by_state_suburb.setdefault((state, suburb_key), []).append(school)
    external_maps = {"ACARA": {}, "My School": {}, "My School / ACARA": {}}
    for row in db_handle.all(
        """SELECT source_name,external_school_id,school_id FROM school_external_ids
           WHERE source_name IN ('ACARA','My School','My School / ACARA')
             AND COALESCE(external_school_id,'')<>''"""
    ):
        external_maps.setdefault(row["source_name"], {})[str(row["external_school_id"])] = row["school_id"]
    return {
        "schools": schools,
        "schools_by_id": schools_by_id,
        "schools_by_state": schools_by_state,
        "schools_by_name": schools_by_name,
        "schools_by_state_name": schools_by_state_name,
        "schools_by_state_postcode": schools_by_state_postcode,
        "schools_by_state_suburb": schools_by_state_suburb,
        "school_name_keys": school_name_keys,
        "school_sector_keys": school_sector_keys,
        "external_maps": external_maps,
    }

def data_update_profile_match_school(db_handle, profile, match_context=None):
    if profile.get("acara_school_id"):
        school = None
        if match_context:
            school_id = match_context["external_maps"].get("ACARA", {}).get(profile["acara_school_id"])
            school = match_context["schools_by_id"].get(school_id)
        else:
            row = db_handle.one(
                "SELECT school_id FROM school_external_ids WHERE source_name='ACARA' AND external_school_id=? LIMIT 1",
                (profile["acara_school_id"],),
            )
            school = db_handle.one("SELECT * FROM schools WHERE id=?", (row["school_id"],)) if row else None
        if school:
            return school, "external_id", 100.0
    if profile.get("myschool_school_id"):
        school = None
        if match_context:
            school_id = (
                match_context["external_maps"].get("My School", {}).get(profile["myschool_school_id"])
                or match_context["external_maps"].get("My School / ACARA", {}).get(profile["myschool_school_id"])
            )
            school = match_context["schools_by_id"].get(school_id)
        else:
            row = db_handle.one(
                """SELECT school_id FROM school_external_ids
                   WHERE source_name IN ('My School','My School / ACARA') AND external_school_id=?
                   LIMIT 1""",
                (profile["myschool_school_id"],),
            )
            school = db_handle.one("SELECT * FROM schools WHERE id=?", (row["school_id"],)) if row else None
        if school:
            return school, "external_id", 100.0
    state = str(profile.get("source_state") or "").upper()
    source_name_key = data_update_profile_name_key(profile.get("source_school_name"))
    if not source_name_key:
        return None, "missing_school_name", 0.0
    source_postcode = str(profile.get("source_postcode") or "").strip()
    source_suburb_key = data_update_profile_name_key(profile.get("source_suburb"))
    if match_context:
        exact_candidates = match_context["schools_by_state_name"].get((state, source_name_key), []) if state else []
        if not exact_candidates:
            exact_candidates = match_context["schools_by_name"].get(source_name_key, []) if not state else []
        if exact_candidates:
            candidates = exact_candidates
        else:
            pool = []
            if state and source_postcode:
                pool.extend(match_context["schools_by_state_postcode"].get((state, source_postcode), []))
            if state and source_suburb_key:
                pool.extend(match_context["schools_by_state_suburb"].get((state, source_suburb_key), []))
            seen_ids = set()
            candidates = []
            for item in pool:
                if item["id"] in seen_ids:
                    continue
                seen_ids.add(item["id"])
                candidates.append(item)
            if not candidates:
                return None, "manual_review", 0.0
    else:
        candidates = db_handle.all(
            """SELECT * FROM schools
               WHERE (?='' OR UPPER(COALESCE(state,''))=?)
               ORDER BY school_name""",
            (state, state),
        )
    scored = []
    source_sector = data_update_school_sector_key(profile.get("source_sector"))
    for school in candidates:
        candidate_key = match_context["school_name_keys"].get(school["id"]) if match_context else data_update_profile_name_key(school["school_name"])
        if not candidate_key:
            continue
        name_ratio = SequenceMatcher(None, source_name_key, candidate_key).ratio()
        score = name_ratio * 70
        if source_name_key == candidate_key:
            score = 70
        if state and str(school["state"] or "").upper() == state:
            score += 5
        school_suburb_keys = {
            data_update_profile_name_key(item)
            for item in data_update_profile_multi_text_values(school["suburb"] if "suburb" in school.keys() else "")
        }
        school_postcodes = set(data_update_profile_postcode_values(school["postcode"] if "postcode" in school.keys() and school["postcode"] else ""))
        if profile.get("source_suburb") and data_update_profile_name_key(profile["source_suburb"]) in school_suburb_keys:
            score += 10
        if profile.get("source_postcode") and profile["source_postcode"] in school_postcodes:
            score += 15
        candidate_sector = match_context["school_sector_keys"].get(school["id"]) if match_context else data_update_school_sector_key(school["sector_key"] if "sector_key" in school.keys() else school["school_type"])
        if source_sector and source_sector == candidate_sector:
            score += 5
        if source_name_key == candidate_key and state and str(school["state"] or "").upper() == state:
            score = max(score, 95)
        if name_ratio >= 0.94 and profile.get("source_postcode") and school_postcodes and profile["source_postcode"] not in school_postcodes:
            score = min(score, 89)
        scored.append((min(round(score, 2), 100.0), school))
    if not scored:
        return None, "unmatched", 0.0
    scored.sort(key=lambda item: item[0], reverse=True)
    best_score, best_school = scored[0]
    if len(scored) > 1 and best_score >= 90 and scored[1][0] >= best_score - 3:
        return best_school, "ambiguous", best_score
    if best_score >= 90:
        return best_school, "fuzzy", best_score
    return best_school if best_score >= 70 else None, "manual_review", best_score

def data_update_stage_school_profile_data(db_handle, job_id, source_file, source_url=""):
    source_file = Path(source_file)
    source_rows = list(data_update_school_profile_rows(source_file))
    stamp = now_iso()
    created = updated = failed = matched = no_match = multiple_candidates = data_issue = 0
    periods = set()
    all_periods = set()
    comparison_rows = []
    match_context = data_update_school_profile_match_context(db_handle)
    existing_profiles = {
        (row["school_id"], str(row["source_year"])): row["id"]
        for row in db_handle.all("SELECT id,school_id,source_year FROM school_profile_data WHERE is_active=1")
    }
    columns = [
        "job_id", "school_id", "acara_school_id", "myschool_school_id", "source_year",
        "school_icsea_value", "average_icsea_value", "icsea_comparison_baseline",
        "teaching_staff_headcount", "teaching_staff_fte", "non_teaching_staff_headcount",
        "non_teaching_staff_fte", "total_enrolments", "boys_count", "girls_count",
        "boys_percentage", "girls_percentage", "gender_balance_score", "indigenous_students_value",
        "indigenous_students_value_type", "indigenous_students_percentage",
        "lbote_value", "lbote_value_type", "lbote_percentage", "student_to_teacher_ratio",
        "icsea_difference_from_baseline", "source_name", "source_url", "source_file_name",
        "imported_at", "last_updated", "is_active", "version_number", "confidence_level",
        "notes", "source_school_name", "source_state", "source_suburb", "source_postcode",
        "source_sector", "match_method", "match_confidence", "validation_status", "validation_error",
    ]
    candidates_by_school = {}
    for raw in source_rows:
        profile = data_update_profile_extract_row(raw, source_file, stamp, source_url=source_url)
        if profile.get("source_year"):
            all_periods.add(profile["source_year"])
        school, match_method, match_confidence = data_update_profile_match_school(db_handle, profile, match_context=match_context)
        if not school or match_confidence < 90 or match_method in {"ambiguous"}:
            continue
        profile["school_id"] = school["id"]
        profile["match_method"] = match_method
        profile["match_confidence"] = match_confidence
        profile["confidence_level"] = "high" if match_confidence >= 95 else "medium"
        candidates_by_school.setdefault(school["id"], []).append(profile)

    staged_records = []
    for school in match_context["schools"]:
        school_id = school["id"]
        candidates = sorted(
            candidates_by_school.get(school_id, []),
            key=lambda item: (float(item.get("match_confidence") or 0), str(item.get("source_year") or "")),
            reverse=True,
        )
        if candidates:
            profile = dict(candidates[0])
            if len(candidates) > 1:
                multiple_candidates += 1
                profile["match_method"] = "multiple_candidates"
                profile["notes"] = "Multiple ACARA candidate rows found for this CRM school; the highest-confidence current row was selected."
        else:
            profile = data_update_profile_calculated_values({
                "acara_school_id": "",
                "myschool_school_id": "",
                "source_year": sorted(all_periods)[-1] if all_periods else "",
                "school_icsea_value": None,
                "average_icsea_value": None,
                "icsea_comparison_baseline": None,
                "teaching_staff_headcount": None,
                "teaching_staff_fte": None,
                "non_teaching_staff_headcount": None,
                "non_teaching_staff_fte": None,
                "total_enrolments": None,
                "boys_count": None,
                "girls_count": None,
                "boys_percentage": None,
                "girls_percentage": None,
                "gender_balance_score": None,
                "indigenous_students_value": None,
                "indigenous_students_value_type": "count",
                "indigenous_students_percentage": None,
                "lbote_value": None,
                "lbote_value_type": "count",
                "lbote_percentage": None,
                "student_to_teacher_ratio": None,
                "icsea_difference_from_baseline": None,
                "source_name": "ACARA School Profile Data",
                "source_url": source_url,
                "source_file_name": source_file.name,
                "imported_at": stamp,
                "last_updated": stamp,
                "is_active": 0,
                "version_number": 1,
                "confidence_level": "low",
                "notes": "No reliable ACARA School Profile match found for this CRM school.",
                "source_school_name": school["school_name"],
                "source_state": str(school["state"] if "state" in school.keys() and school["state"] else "").upper(),
                "source_suburb": str(school["suburb"] if "suburb" in school.keys() and school["suburb"] else ""),
                "source_postcode": re.sub(r"[^0-9]", "", str(school["postcode"] if "postcode" in school.keys() and school["postcode"] else "")),
                "source_sector": str(school["sector_key"] if "sector_key" in school.keys() and school["sector_key"] else school["school_type"]),
                "school_id": school_id,
                "match_method": "no_match",
                "match_confidence": 0.0,
            })
        validation_errors = []
        if not profile["source_year"]:
            validation_errors.append("source_year missing")
        if not profile["source_school_name"]:
            validation_errors.append("school_name missing")
        if profile.get("boys_count") is not None and profile.get("girls_count") is not None and profile.get("total_enrolments") is not None:
            if int(profile["boys_count"] or 0) + int(profile["girls_count"] or 0) != int(profile["total_enrolments"] or 0):
                validation_errors.append("Boys + Girls does not equal Total enrolments")
        if profile.get("teaching_staff_fte") and profile.get("teaching_staff_headcount") and profile["teaching_staff_fte"] > profile["teaching_staff_headcount"]:
            validation_errors.append("Teaching staff FTE is greater than teaching staff headcount")
        if profile.get("teaching_staff_fte") in {0, 0.0}:
            validation_errors.append("Teaching staff FTE is 0 or missing")
        if profile["match_method"] == "no_match":
            validation_status = "No Match"
            validation_errors = ["No reliable ACARA match found for CRM school"]
        else:
            validation_status = "Valid" if not validation_errors else "Invalid"
        if validation_status == "Valid":
            matched += 1
            periods.add(profile["source_year"])
            if (profile["school_id"], str(profile["source_year"])) in existing_profiles:
                updated += 1
            else:
                created += 1
        elif validation_status == "No Match":
            no_match += 1
            failed += 1
        else:
            data_issue += 1
            failed += 1
        comparison_rows.append({
            "crm_school_id": school_id,
            "crm_school_name": school["school_name"],
            "status": validation_status,
            "acara_school_name": profile["source_school_name"],
            "state": profile["source_state"],
            "suburb": profile["source_suburb"],
            "postcode": profile["source_postcode"],
            "match_method": profile["match_method"],
            "match_confidence": profile["match_confidence"],
            "reason": "; ".join(validation_errors),
        })
        staged = {**profile, "job_id": job_id, "validation_status": validation_status, "validation_error": "; ".join(validation_errors)}
        staged_records.append(tuple(staged.get(column) for column in columns))
    with db_handle.transaction() as conn:
        conn.execute("DELETE FROM staging_school_profile_data WHERE job_id=?", (job_id,))
        conn.executemany(
            f"INSERT INTO staging_school_profile_data({','.join(columns)}) VALUES({','.join('?' for _ in columns)})",
            staged_records,
        )
    return {
        "source_name": "ACARA School Profile Data",
        "source_file": str(source_file),
        "source_url": source_url,
        "source_period": sorted(periods or all_periods)[-1] if (periods or all_periods) else "",
        "records_found": len(match_context["schools"]),
        "records_created": created,
        "records_updated": updated,
        "records_failed": failed,
        "unmatched_suburb_count": 0,
        "unmatched_postcode_count": 0,
        "unmatched_lga_sa2_count": 0,
        "needs_manual_confirmation_count": 0,
        "affected_school_count": matched,
        "recalculates_market_summary": False,
        "recalculates_crime_summary": False,
        "publish_requires_confirmation": True,
        "crm_school_count": len(match_context["schools"]),
        "acara_rows_found": len(source_rows),
        "crm_schools_matched": matched,
        "crm_schools_without_acara_match": no_match,
        "crm_schools_with_multiple_candidates": multiple_candidates,
        "crm_schools_with_data_issue": data_issue,
        "comparison_rows": comparison_rows[:100],
    }

def data_update_backfill_school_profile_calculated_fields(db_handle):
    updated = 0
    for table in ("school_profile_data", "staging_school_profile_data"):
        columns = {row["name"] for row in db_handle.all(f"PRAGMA table_info({table})")}
        required = {
            "id", "total_enrolments", "boys_count", "girls_count", "boys_percentage",
            "girls_percentage", "gender_balance_score", "lbote_value", "lbote_value_type",
            "lbote_percentage", "student_to_teacher_ratio", "teaching_staff_fte",
            "school_icsea_value", "average_icsea_value", "icsea_difference_from_baseline",
            "icsea_comparison_baseline", "notes",
        }
        if not required.issubset(columns):
            continue
        rows = db_handle.all(
            f"""SELECT id,total_enrolments,boys_count,girls_count,boys_percentage,girls_percentage,
                      gender_balance_score,lbote_value,lbote_value_type,lbote_percentage,
                      student_to_teacher_ratio,teaching_staff_fte,school_icsea_value,
                      average_icsea_value,icsea_comparison_baseline,icsea_difference_from_baseline,notes
               FROM {table}"""
        )
        with db_handle.transaction() as conn:
            for row in rows:
                values = dict(row)
                recalculated = data_update_profile_calculated_values(values)
                conn.execute(
                    f"""UPDATE {table}
                        SET boys_count=?,girls_count=?,boys_percentage=?,girls_percentage=?,gender_balance_score=?,
                            lbote_percentage=?,student_to_teacher_ratio=?,
                            average_icsea_value=?,icsea_comparison_baseline=?,
                            icsea_difference_from_baseline=?,notes=?
                        WHERE id=?""",
                    (
                        recalculated.get("boys_count"),
                        recalculated.get("girls_count"),
                        recalculated.get("boys_percentage"),
                        recalculated.get("girls_percentage"),
                        recalculated.get("gender_balance_score"),
                        recalculated.get("lbote_percentage"),
                        recalculated.get("student_to_teacher_ratio"),
                        recalculated.get("average_icsea_value"),
                        recalculated.get("icsea_comparison_baseline"),
                        recalculated.get("icsea_difference_from_baseline"),
                        recalculated.get("notes") or "",
                        row["id"],
                    ),
                )
                updated += 1
    return updated

def data_update_stage_school_zones(db_handle, job_id, source_file):
    source_file = Path(source_file)
    if source_file.suffix.lower() in {".json", ".geojson"}:
        payload = json.loads(source_file.read_text(encoding="utf-8"))
        rows = []
        for feature in payload.get("features", []) if isinstance(payload, dict) else []:
            props = dict(feature.get("properties") or {})
            props["geometry"] = json.dumps(feature.get("geometry") or {}, ensure_ascii=False)
            rows.append(props)
    else:
        rows = list(data_update_spreadsheet_rows(source_file))
    stamp = now_iso()
    db_handle.execute("DELETE FROM staging_school_zones WHERE job_id=?", (job_id,))
    created = updated = failed = 0
    periods = set()
    for row in rows:
        school_id = data_update_row_lookup(row, "school_id", "school id")
        school_name = str(data_update_row_lookup(row, "school_name", "school name", "school") or "").strip()
        state = str(data_update_row_lookup(row, "state") or "VIC").strip().upper()
        school = None
        if school_id:
            school = db_handle.one("SELECT * FROM schools WHERE id=?", (school_id,))
        if not school and school_name:
            school = db_handle.one("SELECT * FROM schools WHERE UPPER(COALESCE(state,''))=? AND school_name=?", (state, school_name))
        enrolment_year = str(data_update_row_lookup(row, "enrolment_year", "enrollment_year", "year") or "").strip()
        year_level = str(data_update_row_lookup(row, "year_level", "year level") or "").strip()
        zone_name = str(data_update_row_lookup(row, "zone_name", "zone", "name") or school_name or "").strip()
        geometry = data_update_row_lookup(row, "geometry", "polygon", "geojson")
        if not school or str(school["sector_key"] or "").lower() != "public" or not enrolment_year or not zone_name:
            failed += 1
            continue
        existing = db_handle.one(
            """SELECT id FROM school_zones
               WHERE school_id=? AND state=? AND enrolment_year=? AND COALESCE(year_level,'')=? AND COALESCE(zone_name,'')=?
               LIMIT 1""",
            (school["id"], state, enrolment_year, year_level, zone_name),
        )
        if existing:
            updated += 1
        else:
            created += 1
        periods.add(enrolment_year)
        db_handle.execute(
            """INSERT INTO staging_school_zones(
               job_id,school_id,state,enrolment_year,year_level,zone_name,geometry,source,source_file,
               last_updated,status,validation_status,validation_error
            ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)""",
            (
                job_id, school["id"], state, enrolment_year, year_level, zone_name,
                json.dumps(geometry, ensure_ascii=False) if isinstance(geometry, (dict, list)) else str(geometry or ""),
                "Victorian Government School Zones", str(source_file), stamp, "staged", "Valid", "",
            ),
        )
    return {
        "source_name": "Victorian Government School Zones",
        "source_file": str(source_file),
        "source_period": sorted(periods)[-1] if periods else "",
        "records_found": created + updated + failed,
        "records_created": created,
        "records_updated": updated,
        "records_failed": failed,
        "needs_manual_confirmation_count": created + updated,
        "affected_school_count": created + updated,
        "recalculates_market_summary": False,
        "recalculates_crime_summary": False,
        "publish_requires_confirmation": True,
    }

def data_update_crime_summary_categories(profile):
    categories = []
    for column, label in (
        ("crimes_against_person", "Crimes against the person"),
        ("property_and_deception_offences", "Property and deception offences"),
        ("drug_offences", "Drug offences"),
        ("public_order_and_security_offences", "Public order and security offences"),
        ("justice_procedures_offences", "Justice procedures offences"),
        ("other_offences", "Other offences"),
    ):
        value = profile[column] if column in profile.keys() else None
        if value is not None:
            categories.append({"category": label, "count": value})
    categories.sort(key=lambda item: item["count"] or 0, reverse=True)
    return json.dumps(categories[:3], ensure_ascii=False)

def data_update_upsert_school_area_crime_summary(db_handle, school_id, profile):
    confidence = "high" if profile["data_level"] in {"suburb", "postcode", "lga"} else "estimated"
    values = {
        "school_id": school_id,
        "area_type": profile["data_level"],
        "radius_km": 0,
        "suburb": profile["suburb"],
        "postcode": profile["postcode"],
        "lga_name": profile["lga_name"],
        "total_offence_count": profile["total_recorded_offences"],
        "offence_rate_per_100k": profile["offence_rate_per_100000"],
        "top_offence_categories": data_update_crime_summary_categories(profile),
        "year_on_year_change_percent": profile["trend_1_year_percent"],
        "source_period": profile["data_year_ending"],
        "confidence_level": confidence,
        "notes": "该数据为区域参考，不代表学校本身安全程度。",
        "last_calculated_at": now_iso(),
    }
    columns = list(values)
    assignments = ",".join(f"{column}=excluded.{column}" for column in columns if column != "school_id")
    db_handle.execute(
        f"""INSERT INTO school_area_crime_summary({','.join(columns)})
            VALUES({','.join('?' for _ in columns)})
            ON CONFLICT(school_id,area_type,radius_km,source_period) DO UPDATE SET {assignments}""",
        tuple(values[column] for column in columns),
    )

def data_update_crime_rows_for_area_link(db_handle, state, link):
    area_name = str(link["area_name"] or "").strip()
    area_type = str(link["area_type"] or "").strip().lower()
    keys = []
    if area_type == "postcode":
        keys = [csa_crime_area_key("postcode", postcode=area_name)]
        data_level = "postcode"
    elif area_type == "lga":
        keys = csa_crime_lga_area_keys(area_name)
        data_level = "lga"
    else:
        keys = [csa_crime_area_key("suburb", suburb=area_name)]
        data_level = "suburb"
    for key in keys:
        rows = choose_latest_csa_crime_rows(csa_crime_rows_for_key(db_handle, state, data_level, key))
        if rows:
            return rows
    return []

def data_update_upsert_radius_crime_summary(db_handle, school, radius):
    state = str(school["state"] if "state" in school.keys() and school["state"] else "VIC").strip().upper()
    links = db_handle.all(
        """SELECT * FROM school_radius_area_links
           WHERE school_id=? AND radius_km=?
           ORDER BY area_type,area_name""",
        (school["id"], radius),
    )
    merged_rows = []
    seen = set()
    for link in links:
        for row in data_update_crime_rows_for_area_link(db_handle, state, link):
            key = (row["state"], row["data_level"], row["normalized_area_key"], row["data_year_ending"], row["source_dataset"])
            if key in seen:
                continue
            seen.add(key)
            merged_rows.append(row)
    if not merged_rows:
        return False
    source_period = max((row["data_year_ending"] for row in merged_rows), key=csa_crime_year_ending_sort_key)
    latest_rows = [row for row in merged_rows if row["data_year_ending"] == source_period]
    total = sum(int(row["total_recorded_offences"] or 0) for row in latest_rows)
    rates = [row["offence_rate_per_100000"] for row in latest_rows if row["offence_rate_per_100000"] is not None]
    rate = round(sum(rates) / len(rates), 2) if rates else None
    confidence = "high" if len(latest_rows) == 1 else "estimated"
    categories = []
    for column, label in (
        ("crimes_against_person", "Crimes against the person"),
        ("property_and_deception_offences", "Property and deception offences"),
        ("drug_offences", "Drug offences"),
        ("public_order_and_security_offences", "Public order and security offences"),
        ("justice_procedures_offences", "Justice procedures offences"),
        ("other_offences", "Other offences"),
    ):
        count = sum(int(row[column] or 0) for row in merged_rows if column in row.keys() and row[column] is not None)
        if count:
            categories.append({"category": label, "count": count})
    categories.sort(key=lambda item: item["count"], reverse=True)
    values = {
        "school_id": school["id"],
        "area_type": "radius",
        "radius_km": radius,
        "suburb": school["suburb"] if "suburb" in school.keys() else "",
        "postcode": school["postcode"] if "postcode" in school.keys() else "",
        "lga_name": "",
        "total_offence_count": total,
        "offence_rate_per_100k": rate,
        "top_offence_categories": json.dumps(categories[:3], ensure_ascii=False),
        "year_on_year_change_percent": None,
        "source_period": source_period,
        "confidence_level": confidence,
        "notes": "该数据为区域参考，不代表学校本身安全程度。" + (" Multiple areas combined; estimated surrounding area safety reference." if confidence == "estimated" else ""),
        "last_calculated_at": now_iso(),
    }
    columns = list(values)
    assignments = ",".join(f"{column}=excluded.{column}" for column in columns if column != "school_id")
    db_handle.execute(
        f"""INSERT INTO school_area_crime_summary({','.join(columns)})
            VALUES({','.join('?' for _ in columns)})
            ON CONFLICT(school_id,area_type,radius_km,source_period) DO UPDATE SET {assignments}""",
        tuple(values[column] for column in columns),
    )
    return True

def data_update_refresh_crime_summaries(db_handle):
    rows = db_handle.all(
        """SELECT id FROM schools
           WHERE latitude IS NOT NULL
             AND longitude IS NOT NULL
             AND deleted_at IS NULL
           ORDER BY id"""
    )
    refreshed = 0
    failed = 0
    for row in rows:
        school = db_handle.one("SELECT * FROM schools WHERE id=?", (row["id"],))
        refresh_school_living_cost_summary(db_handle, row["id"])
        profile = None
        profile_id = refresh_school_area_crime_profile(db_handle, row["id"])
        if not profile_id:
            failed += 1
        else:
            profile = db_handle.one("SELECT * FROM school_area_crime_profiles WHERE id=?", (profile_id,))
            if profile:
                data_update_upsert_school_area_crime_summary(db_handle, row["id"], profile)
        if school:
            for radius in (5, 10, 15):
                data_update_upsert_radius_crime_summary(db_handle, school, radius)
            refreshed += 1
    return {
        "source_name": "School surrounding crime data summary",
        "source_period": now_iso()[:10],
        "records_found": len(rows),
        "records_created": 0,
        "records_updated": refreshed,
        "records_failed": failed,
        "needs_manual_confirmation_count": 0,
        "affected_school_count": refreshed,
        "recalculates_market_summary": False,
        "recalculates_crime_summary": True,
        "publish_requires_confirmation": False,
    }

