def data_update_placeholder_report(db_handle, action_key, source_file="", error_message=""):
    action = data_update_action_definition(action_key) or {}
    return {
        "source_name": action.get("source_name") or action_key,
        "source_file": source_file,
        "source_period": "",
        "records_found": 0,
        "records_created": 0,
        "records_updated": 0,
        "records_failed": 1 if error_message else 0,
        "needs_manual_confirmation_count": 0,
        "affected_school_count": 0,
        "recalculates_market_summary": action_key in {"school_radius_area_links"},
        "recalculates_crime_summary": action_key in {"crime_statistics", "school_area_crime_summary"},
        "publish_requires_confirmation": True,
        "message": error_message or "This data source is registered and logged. A confirmed source parser is required before production publish.",
    }

def run_data_update_action(db_handle, action_key, user_id=None, source_paths=None):
    source_paths = source_paths or {}
    source_state = str(source_paths.get("source_state") or "VIC").strip().upper() or "VIC"
    if source_state not in SCHOOL_DATA_IMPORT_STATES:
        raise ValueError(f"Unsupported data update state: {source_state}")
    job_id = data_update_create_job(db_handle, action_key, user_id=user_id)
    try:
        if action_key == "school_base":
            source_file = Path(source_paths["school_file"]) if source_paths.get("school_file") else data_update_latest_file(
                APP_DIR / "school_data_sources",
                ("*SchoolLocations*.csv", "*school*.csv", "*school*.xlsx"),
            )
            if not source_file:
                raise FileNotFoundError("No school base source file found in school_data_sources.")
            report = data_update_stage_school_base(db_handle, job_id, source_file)
            status = "Needs Confirmation" if report["records_created"] + report["records_updated"] else "Error"
        elif action_key == "rental_market":
            if source_paths.get("rental_file"):
                source_file = Path(source_paths["rental_file"])
            elif source_state == "VIC":
                source_file = data_update_latest_file(
                    APP_DIR / "school_data_sources" / "vic_living_costs",
                    ("tables-rental-report-*.xlsx", "*rental*.xlsx"),
                )
            else:
                source_file = None
            if not source_file:
                raise FileNotFoundError(f"No {source_state} rental source file found. Upload official CSV/XLSX in Data Update Centre.")
            if source_state == "VIC":
                report = data_update_stage_vic_rental_market(db_handle, job_id, source_file)
            elif source_state == "NSW":
                report = data_update_stage_nsw_rental_market(db_handle, job_id, source_file)
            elif source_state == "WA":
                report = data_update_stage_wa_rental_market(db_handle, job_id, source_file)
            else:
                report = data_update_stage_generic_rental_market(db_handle, job_id, source_file, state=source_state)
            status = "Needs Confirmation" if report["records_created"] + report["records_updated"] else "Error"
        elif action_key == "property_market":
            report = data_update_stage_vic_property_market(db_handle, job_id, source_paths=source_paths)
            status = "Needs Confirmation" if report["records_found"] and not report["records_failed"] else "Error"
        elif action_key == "crime_statistics":
            if source_paths.get("crime_file"):
                source_file = Path(source_paths["crime_file"])
            elif source_state == "VIC":
                source_file = data_update_latest_crime_file(APP_DIR / "school_data_sources" / "vic_crime")
            else:
                source_file = None
            if not source_file:
                raise FileNotFoundError(f"No {source_state} crime statistics source file found. Upload official CSV/XLSX in Data Update Centre.")
            if source_state == "NSW":
                report = data_update_stage_nsw_crime_statistics(db_handle, job_id, source_file)
            else:
                report = data_update_stage_vic_crime_statistics(db_handle, job_id, source_file, state=source_state)
            status = "Needs Confirmation" if report["records_found"] and not report["records_failed"] else "Error"
        elif action_key == "school_profile_data":
            source_url = ""
            if source_paths.get("school_profile_file"):
                source_file = Path(source_paths["school_profile_file"])
            else:
                download = data_update_download_acara_school_profile(source_paths=source_paths)
                source_file = Path(download["path"])
                source_url = download.get("source_url") or ""
            if not source_file:
                raise FileNotFoundError("No ACARA School Profile XLSX source file found.")
            report = data_update_stage_school_profile_data(db_handle, job_id, source_file, source_url=source_url)
            status = "Needs Confirmation" if report["affected_school_count"] else "Error"
        elif action_key == "private_international_fees":
            report = stage_private_international_fee_mvp(db_handle, job_id, user_id=user_id, scope_label="全库私校")
            status = "Needs Confirmation" if report["records_found"] else "Error"
        elif action_key == "official_school_zones":
            source_file = Path(source_paths["zone_file"]) if source_paths.get("zone_file") else data_update_latest_file(
                APP_DIR / "school_data_sources",
                ("*zone*.csv", "*zone*.xlsx", "*zone*.geojson", "*zone*.json"),
            )
            if not source_file:
                raise FileNotFoundError("No official school zone source file found in school_data_sources.")
            report = data_update_stage_school_zones(db_handle, job_id, source_file)
            status = "Needs Confirmation" if report["records_found"] and report["needs_manual_confirmation_count"] else "Error"
        elif action_key == "school_radius_area_links":
            report = data_update_refresh_radius_area_links(db_handle)
            status = "Success"
        elif action_key == "school_radius_market_summary":
            report = data_update_refresh_living_cost_summaries(db_handle)
            status = "Success"
        elif action_key == "school_area_crime_summary":
            report = data_update_refresh_crime_summaries(db_handle)
            status = "Success"
        else:
            report = data_update_placeholder_report(db_handle, action_key)
            status = "Needs Confirmation"
        data_update_write_preview(db_handle, job_id, report)
        data_update_finish_job(db_handle, job_id, status, report)
        data_update_log(db_handle, job_id, "info", f"{report.get('source_name', action_key)} update report generated. Status: {status}.")
        return job_id
    except Exception as exc:
        report = data_update_placeholder_report(db_handle, action_key, error_message=str(exc))
        data_update_write_preview(db_handle, job_id, report)
        data_update_finish_job(db_handle, job_id, "Error", report, error_message=str(exc))
        data_update_log(db_handle, job_id, "error", str(exc))
        return job_id

def run_data_update_auto_checks(db_handle, user_id=None, source_paths=None, action_keys=None):
    if SAFE_PRODUCTION_ACTIVE:
        return []
    source_paths = source_paths or {}
    created = []
    if action_keys is None or "academic_results" in action_keys:
        created.extend(run_academic_results_auto_checks(db_handle, user_id=user_id, source_paths=source_paths))
    enabled_sources = db_handle.all(
        """SELECT source_type FROM data_sources
           WHERE auto_check_enabled=1
           ORDER BY id"""
    )
    enabled_keys = [row["source_type"] for row in enabled_sources]
    selected = [
        key for key in (action_keys or enabled_keys)
        if key != "academic_results" and key in enabled_keys and data_update_action_definition(key)
    ]
    for key in selected:
        pending = db_handle.one(
            """SELECT id FROM data_update_jobs
               WHERE job_type=? AND status='Needs Confirmation'
               ORDER BY id DESC LIMIT 1""",
            (key,),
        )
        if pending:
            continue
        job_id = run_data_update_action(db_handle, key, user_id=user_id, source_paths=source_paths)
        db_handle.execute("UPDATE data_update_jobs SET trigger_type='auto',updated_at=? WHERE id=?", (now_iso(), job_id))
        data_update_log(db_handle, job_id, "info", "Automatic check generated a preview job. Admin confirmation is still required before publish.")
        created.append(job_id)
    return created

def start_data_update_auto_check_thread():
    global DATA_UPDATE_AUTO_CHECK_STARTED
    if SAFE_PRODUCTION_ACTIVE:
        return
    if DATA_UPDATE_AUTO_CHECK_STARTED:
        return
    DATA_UPDATE_AUTO_CHECK_STARTED = True

    def worker():
        while True:
            try:
                created = run_data_update_auto_checks(db, user_id=None)
                if created:
                    append_service_log("admin", "data_update_auto_check_jobs_created", count=len(created), jobs=",".join(str(item) for item in created))
            except Exception as exc:
                append_service_log("admin", "data_update_auto_check_error", repr(exc))
            time.sleep(21600)

    thread = threading.Thread(target=worker, name="aaie-data-update-auto-check", daemon=True)
    thread.start()

def confirm_data_update_job(db_handle, job_id, user_id=None):
    job = db_handle.one("SELECT * FROM data_update_jobs WHERE id=?", (job_id,))
    if not job:
        raise ValueError("Data update job not found.")
    stamp = now_iso()
    if job["job_type"] == "school_base":
        rows = db_handle.all("SELECT * FROM staging_schools WHERE job_id=? AND validation_status='Valid'", (job_id,))
        changed_school_ids = []
        for row in rows:
            sector_key = data_update_school_sector_key(row["sector"])
            if row["school_id"]:
                existing = db_handle.one("SELECT * FROM schools WHERE id=?", (row["school_id"],))
                if existing:
                    data_update_snapshot_row(db_handle, job_id, "schools", "replace", data_update_record_key("schools", existing), existing)
                db_handle.execute(
                    """UPDATE schools SET sector_key=?,school_type=?,address=COALESCE(NULLIF(?,''),address),
                       suburb=COALESCE(NULLIF(?,''),suburb),postcode=COALESCE(NULLIF(?,''),postcode),
                       latitude=COALESCE(?,latitude),longitude=COALESCE(?,longitude),
                       year_levels=COALESCE(NULLIF(?,''),year_levels),website_url=COALESCE(NULLIF(?,''),website_url),
                       school_data_source_url=?,school_data_updated_at=?,data_quality_status='Needs Review',
                       updated_at=?,last_updated_at=?
                       WHERE id=?""",
                    (
                        sector_key, row["school_type"] or ("Public" if sector_key == "public" else "Private"),
                        row["address"], row["suburb"], row["postcode"], row["latitude"], row["longitude"],
                        row["year_levels"], row["website"], row["source"], stamp, stamp, stamp, row["school_id"],
                    ),
                )
                changed_school_ids.append(row["school_id"])
            else:
                record_key = json.dumps({"state": row["state"], "school_name": row["school_name"]}, ensure_ascii=False, sort_keys=True)
                data_update_snapshot_row(db_handle, job_id, "schools", "created", record_key, None)
                new_id = db_handle.execute(
                    """INSERT INTO schools(
                       school_name,state,sector_key,school_type,address,suburb,postcode,latitude,longitude,
                       year_levels,website_url,school_data_source_url,school_data_updated_at,data_quality_status,
                       created_at,updated_at,last_updated_at
                    ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                    (
                        row["school_name"], row["state"], sector_key, row["school_type"] or ("Public" if sector_key == "public" else "Private"),
                        row["address"], row["suburb"], row["postcode"], row["latitude"], row["longitude"],
                        row["year_levels"], row["website"], row["source"], stamp, "Needs Review", stamp, stamp, stamp,
                    ),
                )
                changed_school_ids.append(new_id)
        changed = len(rows)
        for school_id in changed_school_ids:
            refresh_school_living_cost_summary(db_handle, school_id)
            refresh_school_area_crime_profile(db_handle, school_id)
        data_update_refresh_living_cost_summaries(db_handle)
        data_update_refresh_crime_summaries(db_handle)
    elif job["job_type"] == "rental_market":
        rows = db_handle.all("SELECT * FROM staging_rental_market WHERE job_id=? AND validation_status='Valid'", (job_id,))
        for row in rows:
            existing = db_handle.one(
                """SELECT * FROM rental_market
                   WHERE state=? AND lower(suburb)=lower(?) AND COALESCE(postcode,'')=?
                     AND COALESCE(property_type,'')=? AND COALESCE(bedrooms,'')=? AND quarter=? LIMIT 1""",
                (row["state"], row["suburb"], row["postcode"] or "", row["property_type"], row["bedrooms"] or "", row["quarter"]),
            )
            if existing:
                data_update_snapshot_row(db_handle, job_id, "rental_market", "replace", data_update_record_key("rental_market", existing), existing)
            else:
                data_update_snapshot_row(db_handle, job_id, "rental_market", "created", data_update_record_key("rental_market", row), None)
            db_handle.execute(
                """DELETE FROM rental_market
                   WHERE state=? AND lower(suburb)=lower(?) AND COALESCE(postcode,'')=?
                     AND COALESCE(property_type,'')=? AND COALESCE(bedrooms,'')=? AND quarter=?""",
                (row["state"], row["suburb"], row["postcode"] or "", row["property_type"], row["bedrooms"] or "", row["quarter"]),
            )
            db_handle.execute(
                """INSERT INTO rental_market(state,suburb,postcode,property_type,bedrooms,median_weekly_rent,quarter,source,last_updated)
                   VALUES(?,?,?,?,?,?,?,?,?)""",
                (
                    row["state"], row["suburb"], row["postcode"], row["property_type"], row["bedrooms"],
                    row["median_weekly_rent"], row["quarter"], row["source"], row["last_updated"] or stamp,
                ),
            )
        changed = len(rows)
        summary_report = data_update_refresh_living_cost_summaries(db_handle)
        data_update_log(db_handle, job_id, "info", f"school_radius_market_summary recalculated for {summary_report.get('affected_school_count', 0)} schools.")
    elif job["job_type"] == "property_market":
        rows = db_handle.all("SELECT * FROM staging_property_market WHERE job_id=? AND validation_status='Valid'", (job_id,))
        for row in rows:
            existing = db_handle.one(
                """SELECT * FROM property_market
                   WHERE state=? AND lower(suburb)=lower(?) AND COALESCE(property_type,'')=? AND period=? LIMIT 1""",
                (row["state"], row["suburb"], row["property_type"], row["period"]),
            )
            if existing:
                data_update_snapshot_row(db_handle, job_id, "property_market", "replace", data_update_record_key("property_market", existing), existing)
            else:
                data_update_snapshot_row(db_handle, job_id, "property_market", "created", data_update_record_key("property_market", row), None)
            db_handle.execute(
                """DELETE FROM property_market
                   WHERE state=? AND lower(suburb)=lower(?) AND COALESCE(property_type,'')=? AND period=?""",
                (row["state"], row["suburb"], row["property_type"], row["period"]),
            )
            db_handle.execute(
                """INSERT INTO property_market(state,suburb,postcode,property_type,median_sale_price,period,sales_count,source,last_updated)
                   VALUES(?,?,?,?,?,?,?,?,?)""",
                (row["state"], row["suburb"], row["postcode"], row["property_type"], row["median_sale_price"], row["period"], row["sales_count"], row["source"], stamp),
            )
        changed = len(rows)
        summary_report = data_update_refresh_living_cost_summaries(db_handle)
        data_update_log(db_handle, job_id, "info", f"school_radius_market_summary recalculated for {summary_report.get('affected_school_count', 0)} schools.")
    elif job["job_type"] == "crime_statistics":
        rows = db_handle.all("SELECT * FROM staging_crime_statistics WHERE job_id=? AND validation_status='Valid'", (job_id,))
        for row in rows:
            existing = db_handle.one(
                """SELECT * FROM crime_statistics
                   WHERE state=? AND area_type=? AND lower(area_name)=lower(?)
                     AND COALESCE(offence_category,'')=? AND COALESCE(source_period,'')=? LIMIT 1""",
                (row["state"], row["area_type"], row["area_name"], row["offence_category"], row["source_period"]),
            )
            if existing:
                data_update_snapshot_row(db_handle, job_id, "crime_statistics", "replace", data_update_record_key("crime_statistics", existing), existing)
            else:
                data_update_snapshot_row(db_handle, job_id, "crime_statistics", "created", data_update_record_key("crime_statistics", row), None)
            db_handle.execute(
                """DELETE FROM crime_statistics
                   WHERE state=? AND area_type=? AND lower(area_name)=lower(?)
                     AND COALESCE(offence_category,'')=? AND COALESCE(source_period,'')=?""",
                (row["state"], row["area_type"], row["area_name"], row["offence_category"], row["source_period"]),
            )
            db_handle.execute(
                """INSERT INTO crime_statistics(
                   state,area_type,area_name,suburb,postcode,lga_name,
                   offence_category,offence_subcategory,offence_count,offence_rate_per_100k,
                   period_start,period_end,source,source_period,last_updated
                ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                (
                    row["state"], row["area_type"], row["area_name"], row["suburb"], row["postcode"], row["lga_name"],
                    row["offence_category"], row["offence_subcategory"], row["offence_count"], row["offence_rate_per_100k"],
                    row["period_start"], row["period_end"], row["source"], row["source_period"], stamp,
                ),
            )
            stat = {
                "state": row["state"],
                "data_level": row["area_type"],
                "area_name": row["area_name"],
                "suburb": row["suburb"],
                "postcode": row["postcode"],
                "lga_name": row["lga_name"],
                "data_year_ending": row["source_period"] or row["period_end"],
                "source_dataset": row["offence_subcategory"] or "recorded_offences",
                "source": row["source"] or CSA_CRIME_SOURCE,
                "source_url": row["source"] or CSA_CRIME_SOURCE,
                "total_recorded_offences": row["offence_count"],
                "offence_rate_per_100000": row["offence_rate_per_100k"],
                "raw_json": {},
            }
            upsert_csa_crime_area_stat(db_handle, stat)
        changed = len(rows)
        data_update_refresh_crime_summaries(db_handle)
    elif job["job_type"] == "school_profile_data":
        rows = db_handle.all("SELECT * FROM staging_school_profile_data WHERE job_id=? AND validation_status='Valid'", (job_id,))
        profile_columns = [
            "school_id", "acara_school_id", "myschool_school_id", "source_year",
            "school_icsea_value", "average_icsea_value", "icsea_comparison_baseline",
            "teaching_staff_headcount", "teaching_staff_fte",
            "non_teaching_staff_headcount", "non_teaching_staff_fte",
            "total_enrolments", "boys_count", "girls_count", "boys_percentage",
            "girls_percentage", "gender_balance_score", "indigenous_students_value",
            "indigenous_students_value_type", "indigenous_students_percentage",
            "lbote_value", "lbote_value_type", "lbote_percentage",
            "student_to_teacher_ratio", "icsea_difference_from_baseline",
            "source_name", "source_url", "source_file_name", "imported_at",
            "last_updated", "is_active", "version_number", "confidence_level", "notes",
        ]
        for row in rows:
            active_rows = db_handle.all(
                "SELECT * FROM school_profile_data WHERE school_id=? AND source_year=? AND is_active=1",
                (row["school_id"], row["source_year"]),
            )
            for existing in active_rows:
                data_update_snapshot_row(db_handle, job_id, "school_profile_data", "replace", data_update_record_key("school_profile_data", existing), existing)
                db_handle.execute("UPDATE school_profile_data SET is_active=0,last_updated=? WHERE id=?", (stamp, existing["id"]))
            version_row = db_handle.one(
                "SELECT COALESCE(MAX(version_number),0) max_version FROM school_profile_data WHERE school_id=? AND source_year=?",
                (row["school_id"], row["source_year"]),
            )
            values = {column: row[column] if column in row.keys() else None for column in profile_columns}
            values["is_active"] = 1
            values["version_number"] = int(version_row["max_version"] or 0) + 1
            values["imported_at"] = stamp
            values["last_updated"] = stamp
            new_id = db_handle.execute(
                f"INSERT INTO school_profile_data({','.join(profile_columns)}) VALUES({','.join('?' for _ in profile_columns)})",
                tuple(values[column] for column in profile_columns),
            )
            data_update_snapshot_row(
                db_handle,
                job_id,
                "school_profile_data",
                "created",
                json.dumps({"id": new_id, "school_id": row["school_id"], "source_year": row["source_year"], "version_number": values["version_number"]}, ensure_ascii=False, sort_keys=True),
                None,
            )
            if row["acara_school_id"]:
                db_handle.execute(
                    """INSERT INTO school_external_ids(
                       school_id,source_name,external_school_id,external_school_name,state,suburb,postcode,sector,
                       match_method,match_confidence,verified_by_admin,verified_at,notes
                    ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)
                    ON CONFLICT(source_name,external_school_id) DO UPDATE SET
                      school_id=excluded.school_id,
                      external_school_name=excluded.external_school_name,
                      state=excluded.state,
                      suburb=excluded.suburb,
                      postcode=excluded.postcode,
                      sector=excluded.sector,
                      match_method=excluded.match_method,
                      match_confidence=excluded.match_confidence,
                      verified_by_admin=excluded.verified_by_admin,
                      verified_at=excluded.verified_at,
                      notes=excluded.notes""",
                    (
                        row["school_id"], "ACARA", row["acara_school_id"], row["source_school_name"],
                        row["source_state"], row["source_suburb"], row["source_postcode"], row["source_sector"],
                        row["match_method"], row["match_confidence"], 1, stamp, "Verified by ACARA School Profile publish.",
                    ),
                )
        changed = len(rows)
    elif job["job_type"] == "private_international_fees":
        changed = confirm_private_international_fee_job(db_handle, job, user_id=user_id)
    elif job["job_type"] == "official_school_zones":
        rows = db_handle.all("SELECT * FROM staging_school_zones WHERE job_id=? AND validation_status='Valid'", (job_id,))
        for row in rows:
            existing = db_handle.one(
                """SELECT * FROM school_zones
                   WHERE school_id=? AND state=? AND enrolment_year=? AND COALESCE(year_level,'')=? AND COALESCE(zone_name,'')=? LIMIT 1""",
                (row["school_id"], row["state"], row["enrolment_year"], row["year_level"] or "", row["zone_name"] or ""),
            )
            if existing:
                data_update_snapshot_row(db_handle, job_id, "school_zones", "replace", data_update_record_key("school_zones", existing), existing)
            else:
                data_update_snapshot_row(db_handle, job_id, "school_zones", "created", data_update_record_key("school_zones", row), None)
            db_handle.execute(
                """DELETE FROM school_zones
                   WHERE school_id=? AND state=? AND enrolment_year=? AND COALESCE(year_level,'')=? AND COALESCE(zone_name,'')=?""",
                (row["school_id"], row["state"], row["enrolment_year"], row["year_level"] or "", row["zone_name"] or ""),
            )
            db_handle.execute(
                """INSERT INTO school_zones(school_id,state,enrolment_year,year_level,zone_name,geometry,source,source_file,last_updated,status)
                   VALUES(?,?,?,?,?,?,?,?,?,?)""",
                (
                    row["school_id"], row["state"], row["enrolment_year"], row["year_level"], row["zone_name"],
                    row["geometry"], row["source"], row["source_file"], stamp, "active",
                ),
            )
        changed = len(rows)
    else:
        raise ValueError("This data update job does not support direct publish yet.")
    db_handle.execute(
        "UPDATE data_update_jobs SET status='Success',records_updated=?,needs_manual_confirmation_count=0,finished_at=?,updated_at=? WHERE id=?",
        (changed, stamp, stamp, job_id),
    )
    if job["source_id"]:
        db_handle.execute(
            "UPDATE data_sources SET status='Ready',last_successful_update_at=?,updated_at=? WHERE id=?",
            (stamp, stamp, job["source_id"]),
        )
    data_update_log(db_handle, job_id, "info", f"确认更新完成，已发布 {changed} 条正式数据。")
    return changed

def is_school_collection_url_payload(form):
    source_url = str(form.get("source_url", "") or "").strip()
    if not source_url:
        return False
    abs_field_names = ("abs_region_code", "abs_dataflow", "abs_state_code", "abs_year")
    return not any(str(form.get(name, "") or "").strip() for name in abs_field_names)

