def good_schools_activity_key(value):
    return re.sub(r"[^a-z0-9]+", " ", str(value or "").lower()).strip()


def good_schools_activity_count(text, category):
    match = re.search(rf"{re.escape(category)}\s*\((\d+)\)", text or "", re.I)
    return int(match.group(1)) if match else None


def good_schools_known_activity_items(text):
    normalized = good_schools_activity_key(text)
    items = []
    seen = set()
    for canonical, aliases in GOOD_SCHOOLS_ACTIVITY_ITEM_ALIASES.items():
        for alias in aliases:
            alias_key = good_schools_activity_key(alias)
            if alias_key and re.search(rf"\b{re.escape(alias_key)}\b", normalized):
                if canonical not in seen:
                    items.append(alias)
                    seen.add(canonical)
                break
    return items


def extract_good_schools_activities_from_text(text):
    compact = re.sub(r"\s+", " ", text or "").strip()
    activities = []
    for index, category in enumerate(GOOD_SCHOOLS_ACTIVITY_CATEGORIES):
        match = re.search(rf"{re.escape(category)}\s*(?:\(\d+\))?", compact, re.I)
        if not match:
            continue
        next_positions = [
            next_match.start()
            for next_category in GOOD_SCHOOLS_ACTIVITY_CATEGORIES[index + 1:]
            for next_match in [re.search(rf"{re.escape(next_category)}\s*(?:\(\d+\))?", compact[match.end():], re.I)]
            if next_match
        ]
        end = match.end() + min(next_positions) if next_positions else min(len(compact), match.end() + 500)
        detail = compact[match.end():end]
        items = good_schools_known_activity_items(detail)
        if not items:
            pieces = re.split(r"[,;•·|]+", detail)
            seen_items = set()
            for piece in pieces:
                value = re.sub(r"\(\d+\)", "", piece).strip()
                key = good_schools_activity_key(value)
                if value and 2 <= len(value) <= 80 and key not in seen_items:
                    items.append(value)
                    seen_items.add(key)
        count = good_schools_activity_count(compact, category)
        activities.append({"category": category, "count": count if count is not None else len(items), "items": items[:80]})
    return activities


def good_schools_activity_terms(category, item=""):
    terms = []
    item_key = good_schools_activity_key(item)
    has_specific_item = bool(item_key and item_key != good_schools_activity_key(category))
    if item:
        terms.insert(0, item)
    for canonical, aliases in GOOD_SCHOOLS_ACTIVITY_ITEM_ALIASES.items():
        canonical_key = good_schools_activity_key(canonical)
        alias_keys = {good_schools_activity_key(alias) for alias in aliases}
        if item_key and (item_key == canonical_key or item_key in alias_keys or canonical_key in item_key):
            terms = list(aliases) + terms
            break
    if not has_specific_item:
        terms.extend(GOOD_SCHOOLS_ACTIVITY_CATEGORY_HINTS.get(category, []))
    deduped = []
    seen = set()
    for term in terms:
        key = good_schools_activity_key(term)
        if key and key not in seen:
            deduped.append(str(term))
            seen.add(key)
    return deduped


def good_schools_activity_tag_terms(tag):
    terms = [tag.get("tag_name_cn") or "", tag.get("tag_name_en") or ""]
    keywords = tag.get("keywords") or []
    if isinstance(keywords, str):
        try:
            parsed = json.loads(keywords)
            keywords = parsed if isinstance(parsed, list) else [keywords]
        except Exception:
            keywords = re.split(r"[,，\n]+", keywords)
    terms.extend(keywords)
    return [str(term or "").strip() for term in terms if str(term or "").strip()]


def good_schools_activity_tag_score(tag, terms):
    tag_keys = [good_schools_activity_key(term) for term in good_schools_activity_tag_terms(tag)]
    tag_blob = " ".join(tag_keys)
    score = 0
    for term in terms:
        key = good_schools_activity_key(term)
        if not key:
            continue
        if key in tag_keys:
            score += 85
        elif re.search(rf"\b{re.escape(key)}\b", tag_blob):
            score += 65
        elif key in tag_blob:
            score += 42
    return score


def extract_good_schools_activity_feature_matches(text, tags=None, source_url=""):
    activities = extract_good_schools_activities_from_text(text)
    tag_definitions = normalize_school_feature_tags(tags)
    matches = []
    seen = set()
    for activity in activities:
        category = activity.get("category") or ""
        candidates = [category] + list(activity.get("items") or [])
        for item in candidates:
            terms = good_schools_activity_terms(category, item)
            best_tag = None
            best_score = 0
            for tag in tag_definitions:
                score = good_schools_activity_tag_score(tag, terms)
                if score > best_score:
                    best_tag = tag
                    best_score = score
            if not best_tag or best_score < 50 or best_tag["id"] in seen:
                continue
            seen.add(best_tag["id"])
            label = item if item != category else category
            matches.append(
                {
                    "tag_id": best_tag.get("id"),
                    "category_id": best_tag.get("category_id"),
                    "category_name_cn": best_tag.get("category_name_cn") or "",
                    "category_name_en": best_tag.get("category_name_en") or "",
                    "tag_name": best_tag["tag_name_cn"],
                    "tag_name_cn": best_tag["tag_name_cn"],
                    "tag_name_en": best_tag["tag_name_en"],
                    "description": f"GoodSchools Activities & Support Staff / {category}: {label}",
                    "confidence_rate": min(96, 62 + min(best_score, 120) // 4),
                    "source_url": source_url,
                    "source_title": GOOD_SCHOOLS_SOURCE_NAME,
                    "source_type": GOOD_SCHOOLS_SOURCE_NAME,
                    "source_excerpt": f"GoodSchools Activities & Support Staff / {category}: {label}",
                    "matched_keywords": terms[:8],
                }
            )
    return matches
