def bettereducation_compare_url_for_state(state):
    state_key = str(state or "VIC").strip().upper() or "VIC"
    return BETTER_EDUCATION_SECONDARY_COMPARE_URLS.get(state_key, BETTER_EDUCATION_VIC_SECONDARY_COMPARE_URL)


def bettereducation_fetch_raw_json(row):
    raw = row.get("raw_row_json", {}) if isinstance(row, dict) else {}
    if isinstance(raw, str):
        return raw if raw.strip() else "{}"
    return json.dumps(raw or {}, ensure_ascii=False)


def bettereducation_level_matches_secondary(school):
    text = " ".join(
        str(school[key] or "")
        for key in school.keys()
        if key in {"school_type", "year_levels", "accepted_international_year_levels", "accepted_international_year_level_pattern", "international_year_level_max", "state_senior_certificate"}
    ).lower()
    return any(token in text for token in ("secondary", "p-12", "p–12", "7-12", "year 12", '"12"', "vce", "12"))


def bettereducation_candidate_schools(db_handle, state="VIC", school_scope="missing", selected_school_ids=None, year_end=2025, limit=None):
    state = str(state or "VIC").strip().upper() or "VIC"
    selected_school_ids = [int(value) for value in (selected_school_ids or []) if str(value).strip().isdigit()]
    where = ["state=?"]
    params = [state]
    if selected_school_ids:
        where.append(f"id IN ({','.join('?' for _ in selected_school_ids)})")
        params.extend(selected_school_ids)
    if school_scope == "test_3":
        where.append(f"school_name IN ({','.join('?' for _ in BETTER_EDUCATION_TEST_SCHOOLS)})")
        params.extend(BETTER_EDUCATION_TEST_SCHOOLS)
    rows = db_handle.all(
        f"""SELECT *
            FROM schools
            WHERE {' AND '.join(where)}
            ORDER BY school_name""",
        tuple(params),
    )
    candidates = [row for row in rows if bettereducation_level_matches_secondary(row)]
    if school_scope in {"missing", "outdated"}:
        filtered = []
        for school in candidates:
            latest = db_handle.one(
                """SELECT MAX(CAST(data_year AS INTEGER)) latest_year
                   FROM school_academic_rankings
                   WHERE school_id=? AND source_name=? AND COALESCE(review_status,'') IN ('Confirmed','Approved','Needs Review')""",
                (school["id"], BETTER_EDUCATION_SOURCE_NAME),
            )
            latest_year = int(latest["latest_year"] or 0) if latest else 0
            if school_scope == "missing" and latest_year == 0:
                filtered.append(school)
            elif school_scope == "outdated" and latest_year < int(year_end or 0):
                filtered.append(school)
        candidates = filtered
    if limit:
        candidates = candidates[: int(limit)]
    return candidates


def bettereducation_create_fetch_job(db_handle, state="VIC", year_start=2016, year_end=2025, school_scope="missing", selected_school_ids=None, user_id=None, test_mode=False):
    state = str(state or "VIC").strip().upper() or "VIC"
    school_scope = "test_3" if test_mode else (str(school_scope or "missing").strip() or "missing")
    if school_scope not in BETTER_EDUCATION_SCOPE_LABELS:
        school_scope = "missing"
    year_start = int(year_start or 2016)
    year_end = int(year_end or 2025)
    stamp = now_iso()
    compare_url = bettereducation_compare_url_for_state(state)
    source = db_handle.one(
        "SELECT id FROM data_sources WHERE source_name=? AND state=? ORDER BY id LIMIT 1",
        (BETTER_EDUCATION_SOURCE_NAME, state),
    )
    if not source:
        db_handle.execute(
            """INSERT INTO data_sources(
               source_name,source_type,state,source_url,update_frequency,auto_check_enabled,
               requires_admin_confirmation,status,created_at,updated_at
            ) VALUES(?,?,?,?,?,?,?,?,?,?)""",
            (
                BETTER_EDUCATION_SOURCE_NAME, "academic_results", state,
                compare_url, "Yearly", 0, 1, "Ready", stamp, stamp,
            ),
        )
        source = db_handle.one(
            "SELECT id FROM data_sources WHERE source_name=? AND state=? ORDER BY id LIMIT 1",
            (BETTER_EDUCATION_SOURCE_NAME, state),
        )
    candidates = bettereducation_candidate_schools(
        db_handle,
        state=state,
        school_scope=school_scope,
        selected_school_ids=selected_school_ids,
        year_end=year_end,
        limit=3 if test_mode else None,
    )
    data_update_job_id = db_handle.execute(
        """INSERT INTO data_update_jobs(
           job_type,state,source_id,status,started_at,triggered_by,trigger_type,source_period,
           records_found,records_created,records_updated,records_failed,needs_manual_confirmation_count,
           preview_json,source_type,source_name,source_url,data_year,created_at,updated_at
        ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
        (
            "bettereducation_auto_fetch", state, source["id"] if source else None, "Queued", stamp,
            user_id, "manual", f"{year_start}-{year_end}", len(candidates), 0, 0, 0, 0, "{}",
            BETTER_EDUCATION_AUTO_FETCH_SOURCE_TYPE, BETTER_EDUCATION_SOURCE_NAME, compare_url,
            str(year_end), stamp, stamp,
        ),
    )
    fetch_job_id = db_handle.execute(
        """INSERT INTO bettereducation_fetch_jobs(
           data_update_job_id,state,source_name,year_start,year_end,school_scope,status,total_schools,
           started_by,settings_json,created_at,updated_at
        ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)""",
        (
            data_update_job_id, state, BETTER_EDUCATION_SOURCE_NAME, year_start, year_end, school_scope,
            "Queued", len(candidates), user_id,
            json.dumps({"test_mode": bool(test_mode), "require_review_before_sync": True}, ensure_ascii=False),
            stamp, stamp,
        ),
    )
    for school in candidates:
        db_handle.execute(
            """INSERT INTO bettereducation_fetch_queue(
               fetch_job_id,data_update_job_id,school_id,crm_school_name,suburb,state,sector,
               fetch_status,created_at,updated_at
            ) VALUES(?,?,?,?,?,?,?,?,?,?)""",
            (
                fetch_job_id, data_update_job_id, school["id"], school["school_name"], school["suburb"],
                school["state"], school["sector_key"], "pending", stamp, stamp,
            ),
        )
    preview = {
        "source_name": BETTER_EDUCATION_SOURCE_NAME,
        "source_type": "third_party",
        "school_scope": school_scope,
        "queued_count": len(candidates),
        "year_range": f"{year_start}-{year_end}",
        "require_review_before_sync": True,
        "message": "Better Education Auto Fetch queue created. Fetched records must be reviewed before CRM sync.",
    }
    db_handle.execute(
        "UPDATE data_update_jobs SET preview_json=?,updated_at=? WHERE id=?",
        (json.dumps(preview, ensure_ascii=False), stamp, data_update_job_id),
    )
    data_update_log(db_handle, data_update_job_id, "info", f"Better Education Auto Fetch queued {len(candidates)} schools for {state} {year_start}-{year_end}.")
    return {
        "data_update_job_id": data_update_job_id,
        "fetch_job_id": fetch_job_id,
        "queued_count": len(candidates),
    }


def bettereducation_playwright_command(payload_path, output_path, artifact_dir):
    node_bin = Path("/Users/faqiang/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/bin/node")
    node_modules = Path("/Users/faqiang/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules")
    if not node_bin.exists():
        node_bin = Path(shutil.which("node") or "")
    if not node_bin or not node_bin.exists():
        raise RuntimeError("Node.js runtime is not available for Better Education Playwright fetch.")
    script_path = SOURCE_DIR / "scripts" / "bettereducation_playwright_fetch.js"
    if not script_path.exists():
        raise RuntimeError("Better Education Playwright worker script is missing.")
    env = os.environ.copy()
    if node_modules.exists():
        env["NODE_PATH"] = str(node_modules)
    local_browsers = APP_DIR / "cache" / "ms-playwright"
    env["PLAYWRIGHT_BROWSERS_PATH"] = str(local_browsers)
    env.setdefault("BETTEREDUCATION_COMPARE_URL", BETTER_EDUCATION_VIC_SECONDARY_COMPARE_URL)
    return [str(node_bin), str(script_path), str(payload_path), str(output_path), str(artifact_dir)], env


class BetterEducationFetchError(RuntimeError):
    def __init__(self, error_type, error_message):
        self.error_type = str(error_type or "fetch_failed")
        self.error_message = str(error_message or "Better Education fetch failed.")
        super().__init__(f"{self.error_type}: {self.error_message}")


def bettereducation_worker_failure(output_path):
    path = Path(output_path)
    if not path.exists():
        return None
    try:
        output = json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return None
    if output.get("status") == "success":
        return None
    return BetterEducationFetchError(
        output.get("error_type") or "fetch_failed",
        output.get("error_message") or "Better Education fetch failed.",
    )


def bettereducation_run_queue_item(db_handle, queue_id, user_id=None):
    queue = db_handle.one("SELECT * FROM bettereducation_fetch_queue WHERE id=?", (queue_id,))
    if not queue:
        return {"status": "failed", "error_type": "queue_missing", "error_message": "Queue item not found."}
    fetch_job = db_handle.one("SELECT * FROM bettereducation_fetch_jobs WHERE id=?", (queue["fetch_job_id"],))
    if not fetch_job:
        return {"status": "failed", "error_type": "job_missing", "error_message": "Fetch job not found."}
    stamp = now_iso()
    artifact_dir = APP_DIR / "cache" / "bettereducation_auto_fetch" / f"job_{fetch_job['id']}" / f"queue_{queue_id}"
    artifact_dir.mkdir(parents=True, exist_ok=True)
    payload_path = artifact_dir / "payload.json"
    output_path = artifact_dir / "result.json"
    payload = {
        "school_id": queue["school_id"],
        "crm_school_name": queue["crm_school_name"],
        "suburb": queue["suburb"],
        "state": queue["state"],
        "year_start": fetch_job["year_start"],
        "year_end": fetch_job["year_end"],
        "source_url": bettereducation_compare_url_for_state(queue["state"]),
    }
    payload_path.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")
    db_handle.execute(
        "UPDATE bettereducation_fetch_queue SET fetch_status='running',last_attempt_at=?,retry_count=retry_count+1,updated_at=? WHERE id=?",
        (stamp, stamp, queue_id),
    )
    log_id = db_handle.execute(
        """INSERT INTO bettereducation_fetch_log(
           data_update_job_id,fetch_job_id,queue_id,school_id,crm_school_name,state,started_at,fetch_status,retry_count,created_at
        ) VALUES(?,?,?,?,?,?,?,?,?,?)""",
        (queue["data_update_job_id"], queue["fetch_job_id"], queue_id, queue["school_id"], queue["crm_school_name"], queue["state"], stamp, "running", queue["retry_count"] + 1, stamp),
    )
    try:
        command, env = bettereducation_playwright_command(payload_path, output_path, artifact_dir)
        result = subprocess.run(
            command,
            cwd=str(APP_DIR),
            env=env,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            timeout=180,
        )
        if result.returncode != 0:
            worker_error = bettereducation_worker_failure(output_path)
            if worker_error:
                raise worker_error
            raise RuntimeError((result.stderr or result.stdout or "Better Education Playwright fetch failed.").strip())
        if not output_path.exists():
            raise RuntimeError("Better Education Playwright worker did not write result JSON.")
        output = json.loads(output_path.read_text(encoding="utf-8"))
        if output.get("status") != "success":
            error_type = str(output.get("error_type") or "fetch_failed")
            error_message = str(output.get("error_message") or "Better Education fetch failed.")
            raise BetterEducationFetchError(error_type, error_message)
        records = output.get("records") or []
        if not records:
            raise RuntimeError("no_trend_data: Better Education trend data could not be loaded.")
        for record in records:
            record.setdefault("crm_school_id", queue["school_id"])
            record.setdefault("crm_school_name", queue["crm_school_name"])
            record.setdefault("state", queue["state"])
            record.setdefault("source_url", output.get("source_url") or payload["source_url"])
            record.setdefault("match_status", "Matched" if queue["school_id"] else "Unmatched")
            record.setdefault("confidence_score", 0.95 if queue["school_id"] else 0)
        stage_report = bettereducation_stage_fetch_results(
            db_handle,
            queue["data_update_job_id"],
            records,
            user_id=user_id,
            artifact_dir=artifact_dir,
        )
        done = now_iso()
        db_handle.execute(
            "UPDATE bettereducation_fetch_queue SET fetch_status='success',error_message='',updated_at=? WHERE id=?",
            (done, queue_id),
        )
        db_handle.execute(
            """UPDATE bettereducation_fetch_log
               SET completed_at=?,fetch_status='success',source_school_name=?,years_found=?,
                   records_found=?,records_saved_to_staging=?,match_status='Matched'
               WHERE id=?""",
            (
                done, output.get("source_school_name") or queue["crm_school_name"],
                ",".join(sorted({str(row.get("data_year", "")) for row in records if row.get("data_year")})),
                len(records), stage_report["records_saved_to_staging"], log_id,
            ),
        )
        return {"status": "success", "records": len(records)}
    except Exception as exc:
        done = now_iso()
        if isinstance(exc, BetterEducationFetchError):
            error_type = exc.error_type
            error_message = exc.error_message
        else:
            error_message = str(exc)
            error_type = "fetch_failed"
            lower = error_message.lower()
            if "captcha" in lower:
                error_type = "captcha_detected"
            elif "403" in lower or "access denied" in lower:
                error_type = "access_denied"
            elif "429" in lower or "rate" in lower:
                error_type = "rate_limited"
            elif "structure" in lower or "selector" in lower or "search box" in lower:
                error_type = "page_structure_changed"
        db_handle.execute(
            "UPDATE bettereducation_fetch_queue SET fetch_status=?,error_message=?,updated_at=? WHERE id=?",
            (error_type, error_message[:1000], done, queue_id),
        )
        db_handle.execute(
            """UPDATE bettereducation_fetch_log
               SET completed_at=?,fetch_status=?,error_type=?,error_message=?,screenshot_path=?,html_snapshot_path=?
               WHERE id=?""",
            (
                done, error_type, error_type, error_message[:1000],
                str(artifact_dir / "error.png") if (artifact_dir / "error.png").exists() else "",
                str(artifact_dir / "snapshot.html") if (artifact_dir / "snapshot.html").exists() else "",
                log_id,
            ),
        )
        return {"status": error_type, "error_type": error_type, "error_message": error_message}


def bettereducation_run_fetch_job(fetch_job_id, user_id=None, pause_between_schools=True):
    if fetch_job_id in BETTER_EDUCATION_FETCH_THREADS:
        return
    BETTER_EDUCATION_FETCH_THREADS.add(fetch_job_id)
    try:
        fetch_job = db.one("SELECT * FROM bettereducation_fetch_jobs WHERE id=?", (fetch_job_id,))
        if not fetch_job:
            return
        stamp = now_iso()
        db.execute("UPDATE bettereducation_fetch_jobs SET status='Running',started_at=COALESCE(started_at,?),updated_at=? WHERE id=?", (stamp, stamp, fetch_job_id))
        db.execute("UPDATE data_update_jobs SET status='Running',updated_at=? WHERE id=?", (stamp, fetch_job["data_update_job_id"]))
        consecutive_failures = 0
        processed = 0
        retryable_placeholders = ",".join("?" for _ in BETTER_EDUCATION_RETRYABLE_FETCH_STATUSES)
        retryable_params = (fetch_job_id, *BETTER_EDUCATION_RETRYABLE_FETCH_STATUSES)
        for queue in db.all(
            f"SELECT id FROM bettereducation_fetch_queue WHERE fetch_job_id=? AND fetch_status IN ({retryable_placeholders}) ORDER BY id",
            retryable_params,
        ):
            current = db.one("SELECT stop_requested FROM bettereducation_fetch_jobs WHERE id=?", (fetch_job_id,))
            if current and current["stop_requested"]:
                db.execute("UPDATE bettereducation_fetch_jobs SET status='stopped',updated_at=? WHERE id=?", (now_iso(), fetch_job_id))
                break
            result = bettereducation_run_queue_item(db, queue["id"], user_id=user_id)
            processed += 1
            if result["status"] == "success":
                consecutive_failures = 0
                db.execute("UPDATE bettereducation_fetch_jobs SET processed_schools=processed_schools+1,success_count=success_count+1,review_required_count=review_required_count+1,updated_at=? WHERE id=?", (now_iso(), fetch_job_id))
            else:
                consecutive_failures += 1
                db.execute("UPDATE bettereducation_fetch_jobs SET processed_schools=processed_schools+1,failed_count=failed_count+1,updated_at=? WHERE id=?", (now_iso(), fetch_job_id))
                if result.get("error_type") in {"captcha_detected", "access_denied", "rate_limited"} or consecutive_failures >= 5:
                    db.execute("UPDATE bettereducation_fetch_jobs SET status=?,completed_at=?,updated_at=? WHERE id=?", (result.get("error_type") or "stopped", now_iso(), now_iso(), fetch_job_id))
                    break
            if pause_between_schools and processed % 20 == 0:
                time.sleep(300 + int(time.time()) % 301)
            elif pause_between_schools:
                time.sleep(8 + int(time.time()) % 8)
        bettereducation_recount_fetch_job(db, fetch_job_id)
        latest = db.one("SELECT * FROM bettereducation_fetch_jobs WHERE id=?", (fetch_job_id,))
        if latest and latest["status"] == "Running":
            status = "Review required" if latest["review_required_count"] else ("Completed" if latest["success_count"] else "Error")
            done = now_iso()
            db.execute("UPDATE bettereducation_fetch_jobs SET status=?,completed_at=?,updated_at=? WHERE id=?", (status, done, done, fetch_job_id))
            db.execute("UPDATE data_update_jobs SET status=?,finished_at=?,needs_manual_confirmation_count=?,records_failed=?,updated_at=? WHERE id=?", (status, done, latest["review_required_count"], latest["failed_count"], done, latest["data_update_job_id"]))
    finally:
        BETTER_EDUCATION_FETCH_THREADS.discard(fetch_job_id)


def bettereducation_start_fetch_thread(fetch_job_id, user_id=None):
    from release_business_mode import start_business_thread
    thread = start_business_thread(
        bettereducation_run_fetch_job, lambda: APP_WRITE_GATE,
        kwargs={"fetch_job_id": fetch_job_id, "user_id": user_id},
        name=f"bettereducation-fetch-{fetch_job_id}",
    )
    return thread


def bettereducation_pending_fetch_job_ids(db_handle, fetch_job_id=None):
    placeholders = ",".join("?" for _ in BETTER_EDUCATION_RETRYABLE_FETCH_STATUSES)
    params = list(BETTER_EDUCATION_RETRYABLE_FETCH_STATUSES)
    where = f"q.fetch_status IN ({placeholders})"
    if fetch_job_id:
        where += " AND f.id=?"
        params.append(int(fetch_job_id))
    rows = db_handle.all(
        f"""SELECT DISTINCT f.id
            FROM bettereducation_fetch_jobs f
            JOIN bettereducation_fetch_queue q ON q.fetch_job_id=f.id
            WHERE {where}
            ORDER BY f.id""",
        tuple(params),
    )
    return [int(row["id"]) for row in rows]


def bettereducation_run_pending_fetch_jobs(db_handle, fetch_job_id=None, user_id=None, pause_between_schools=True):
    fetch_job_ids = bettereducation_pending_fetch_job_ids(db_handle, fetch_job_id=fetch_job_id)
    for job_id in fetch_job_ids:
        bettereducation_run_fetch_job(job_id, user_id=user_id, pause_between_schools=pause_between_schools)
    return {
        "status": "ok",
        "jobs_run": len(fetch_job_ids),
        "fetch_job_ids": fetch_job_ids,
    }


def bettereducation_recount_fetch_job(db_handle, fetch_job_id):
    rows = db_handle.all(
        "SELECT fetch_status,COUNT(*) count FROM bettereducation_fetch_queue WHERE fetch_job_id=? GROUP BY fetch_status",
        (fetch_job_id,),
    )
    counts = {str(row["fetch_status"] or ""): int(row["count"] or 0) for row in rows}
    success_count = counts.get("success", 0)
    pending_count = counts.get("pending", 0) + counts.get("running", 0)
    total_count = sum(counts.values())
    failed_count = max(total_count - success_count - pending_count, 0)
    processed_count = success_count + failed_count
    review_required_count = success_count
    stamp = now_iso()
    db_handle.execute(
        """UPDATE bettereducation_fetch_jobs
           SET processed_schools=?,success_count=?,failed_count=?,review_required_count=?,updated_at=?
           WHERE id=?""",
        (processed_count, success_count, failed_count, review_required_count, stamp, fetch_job_id),
    )
    fetch_job = db_handle.one("SELECT data_update_job_id FROM bettereducation_fetch_jobs WHERE id=?", (fetch_job_id,))
    if fetch_job and fetch_job["data_update_job_id"]:
        db_handle.execute(
            """UPDATE data_update_jobs
               SET records_failed=?,needs_manual_confirmation_count=?,updated_at=?
               WHERE id=?""",
            (failed_count, review_required_count, stamp, fetch_job["data_update_job_id"]),
        )
    return {
        "processed_schools": processed_count,
        "success_count": success_count,
        "failed_count": failed_count,
        "review_required_count": review_required_count,
    }


def bettereducation_stage_fetch_results(db_handle, data_update_job_id, fetch_rows, user_id=None, artifact_dir=None):
    """Save Playwright fetched Better Education rows to review staging only."""
    rows = [dict(row) for row in (fetch_rows or []) if dict(row).get("source_school_name") or dict(row).get("crm_school_name")]
    stamp = now_iso()
    artifact_dir = Path(artifact_dir) if artifact_dir else BETTER_EDUCATION_IMPORT_DIR / "auto_fetch" / date.today().strftime("%Y%m%d")
    artifact_dir.mkdir(parents=True, exist_ok=True)
    artifact_path = artifact_dir / f"BetterEducationAutoFetch_job_{data_update_job_id or 'manual'}_{int(time.time())}.json"
    artifact_path.write_text(json.dumps(rows, ensure_ascii=False, indent=2), encoding="utf-8")
    years = sorted({str(row.get("data_year", "")).strip() for row in rows if str(row.get("data_year", "")).strip()})
    data_year = years[-1] if len(years) == 1 else (f"{years[0]}-{years[-1]}" if years else str(local_year()))
    state = (next((str(row.get("state", "")).strip().upper() for row in rows if str(row.get("state", "")).strip()), "") or "VIC")
    source_url = next((str(row.get("source_url", "")).strip() for row in rows if str(row.get("source_url", "")).strip()), "")
    ranking_system = next(
        (str(row.get("ranking_system", "")).strip() for row in rows if str(row.get("ranking_system", "")).strip()),
        "Better Education Secondary",
    )
    import_id = db_handle.execute(
        """INSERT INTO school_ranking_imports(
           source_name,source_type,original_filename,stored_file_path,source_url,ranking_system,state,data_year,
           total_rows,matched_rows,possible_rows,unmatched_rows,import_status,review_status,imported_by,
           imported_at,updated_at,notes,data_update_job_id,update_policy
        ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
        (
            BETTER_EDUCATION_SOURCE_NAME, BETTER_EDUCATION_AUTO_FETCH_SOURCE_TYPE, artifact_path.name, str(artifact_path),
            source_url, ranking_system, state, data_year, len(rows), 0, 0, 0, "Needs Review", "Needs Review",
            user_id, stamp, stamp, BETTER_EDUCATION_THIRD_PARTY_NOTICE, data_update_job_id, "save_as_new_version",
        ),
    )
    counts = {"Matched": 0, "Possible Match": 0, "Unmatched": 0}
    for index, row in enumerate(rows, start=1):
        confidence = row.get("confidence_score")
        try:
            confidence_value = float(confidence) if confidence not in (None, "") else None
        except (TypeError, ValueError):
            confidence_value = None
        match_status = str(row.get("match_status") or "").strip()
        if not match_status:
            match_status = "Matched" if row.get("crm_school_id") and (confidence_value or 0) >= 0.9 else ("Possible Match" if row.get("crm_school_id") else "Unmatched")
        if match_status not in counts:
            match_status = "Unmatched"
        counts[match_status] += 1
        crm_school_id = row.get("crm_school_id")
        try:
            crm_school_id = int(crm_school_id) if crm_school_id not in (None, "") else None
        except (TypeError, ValueError):
            crm_school_id = None
        source_school_name = str(row.get("source_school_name") or row.get("crm_school_name") or "").strip()
        crm_school_name = str(row.get("crm_school_name") or "").strip()
        raw_json = bettereducation_fetch_raw_json(row)
        score_value = str(row.get("score") or "")
        result_metric_value = str(row.get("result_metric_value") or score_value)
        result_metric_name = str(row.get("result_metric_name") or "")
        if not result_metric_name and result_metric_value:
            result_metric_name = "Better Education VCE Compare/Trend Rank"
        db_handle.execute(
            """INSERT INTO school_ranking_import_rows(
               import_id,row_number,school_name_raw,suggested_school_id,suggested_school_name,confidence_score,
               match_status,ranking_system,state,data_year,rank,score,median_score,top_scores_percentage,
               percentile,result_metric_name,result_metric_value,raw_row_json,review_status,notes,created_at,updated_at
            ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
            (
                import_id, index, source_school_name, crm_school_id, crm_school_name, confidence_value,
                match_status, str(row.get("ranking_system") or ranking_system), str(row.get("state") or state), str(row.get("data_year") or data_year),
                str(row.get("bettereducation_rank") or row.get("rank") or ""),
                score_value,
                str(row.get("median_vce_score") or row.get("median_score") or ""),
                str(row.get("percentage_study_scores_40_plus") or row.get("top_scores_percentage") or ""),
                str(row.get("bettereducation_percentile") or row.get("percentile") or ""),
                result_metric_name or "Better Education VCE Academic Results",
                result_metric_value,
                raw_json, "Needs Review", BETTER_EDUCATION_THIRD_PARTY_NOTICE, stamp, stamp,
            ),
        )
        db_handle.execute(
            """INSERT INTO academic_results_import_staging(
               import_batch_id,data_update_job_id,state,source_type,source_name,source_url,crm_school_id,
               crm_school_name,source_school_name,data_year,bettereducation_rank,bettereducation_percentile,
               median_vce_score,percentage_study_scores_40_plus,students,exams_or_entries,raw_row_json,
               fetched_at,match_status,confidence_score,review_status,created_at,updated_at
            ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
            (
                import_id, data_update_job_id, str(row.get("state") or state), "third_party", BETTER_EDUCATION_SOURCE_NAME,
                str(row.get("source_url") or source_url), crm_school_id, crm_school_name, source_school_name,
                str(row.get("data_year") or data_year), str(row.get("bettereducation_rank") or row.get("rank") or ""),
                str(row.get("bettereducation_percentile") or row.get("percentile") or ""),
                str(row.get("median_vce_score") or row.get("median_score") or ""),
                str(row.get("percentage_study_scores_40_plus") or row.get("top_scores_percentage") or ""),
                str(row.get("students") or ""), str(row.get("exams_or_entries") or ""),
                raw_json, stamp, match_status, confidence_value, "Needs Review", stamp, stamp,
            ),
        )
    report = {
        "source_name": BETTER_EDUCATION_SOURCE_NAME,
        "source_type": "third_party",
        "import_id": import_id,
        "stored_file_path": str(artifact_path),
        "records_found": len(rows),
        "records_saved_to_staging": len(rows),
        "records_written_to_crm": 0,
        "matched_rows": counts["Matched"],
        "possible_rows": counts["Possible Match"],
        "unmatched_rows": counts["Unmatched"],
        "review_required": True,
        "notice": BETTER_EDUCATION_THIRD_PARTY_NOTICE,
    }
    db_handle.execute(
        """UPDATE school_ranking_imports
           SET matched_rows=?,possible_rows=?,unmatched_rows=?,report_json=?,updated_at=?
           WHERE id=?""",
        (counts["Matched"], counts["Possible Match"], counts["Unmatched"], json.dumps(report, ensure_ascii=False), stamp, import_id),
    )
    if data_update_job_id:
        db_handle.execute(
            """UPDATE data_update_jobs
               SET status='Review required',finished_at=?,records_found=?,records_created=0,records_updated=0,
                   records_failed=0,needs_manual_confirmation_count=?,preview_json=?,uploaded_file_reference=?,updated_at=?
               WHERE id=?""",
            (stamp, len(rows), len(rows), json.dumps(report, ensure_ascii=False), str(artifact_path), stamp, data_update_job_id),
        )
        data_update_log(db_handle, data_update_job_id, "info", f"Better Education Auto Fetch saved {len(rows)} records to staging review. No CRM ranking rows were published.")
    return report
