def content_script_docx_date(content_date=""):
    try:
        return date.fromisoformat(str(content_date or "")).strftime("%Y%m%d")
    except (TypeError, ValueError):
        return date.today().strftime("%Y%m%d")


def content_docx_filename_component(value):
    cleaned = re.sub(r"[\x00-\x1f/\\:*?\"<>|]+", "", str(value or "")).strip(" .")
    cleaned = re.sub(r"\s+", "_", cleaned)
    return cleaned[:120] or "UntitledScript"


def next_content_docx_path(title, content_date=""):
    REDBOOK_SCRIPT_DOC_DIR.mkdir(parents=True, exist_ok=True)
    clean_title = content_docx_filename_component(title)
    date_part = content_script_docx_date(content_date)
    base = f"{clean_title}_{date_part}"
    version = 1
    while True:
        candidate = REDBOOK_SCRIPT_DOC_DIR / f"{base}_V{version}.docx"
        if not candidate.exists():
            return candidate, version
        version += 1


def create_content_script_docx(title, body, *, category="", status="", tags=None, notes="", content_date="", planned_publish_date="", script_id=None):
    target, _version = next_content_docx_path(title or "Untitled Script", content_date)
    doc = Document()
    doc.add_heading(title or "Untitled Script", level=1)
    meta_rows = [
        ("Script ID", script_id or ""),
        ("文案日期", content_date or ""),
        ("计划发布日期", planned_publish_date or ""),
        ("状态", status or ""),
        ("主题", category or ""),
        ("标签", "，".join(tags or [])),
        ("备注", notes or ""),
    ]
    table = doc.add_table(rows=0, cols=2)
    for label, value in meta_rows:
        row = table.add_row().cells
        row[0].text = str(label)
        row[1].text = str(value or "")
    doc.add_paragraph("")
    doc.add_heading("完整口播正文", level=2)
    text = str(body or "").strip()
    if text:
        for block in text.splitlines():
            doc.add_paragraph(block)
    else:
        doc.add_paragraph("（暂无正文）")
    doc.add_paragraph("")
    footer = doc.add_paragraph()
    footer.add_run(f"Generated by AAIE CRM at {now_iso()}")
    doc.save(target)
    return target


