def content_extraction_progress_payload(job):
    status = str((job or {}).get("process_status") or "待处理")
    latest = str((job or {}).get("source_type") or "") == "v2"
    if latest and status == "待确认":
        status = "已完成"
    progress_steps = (
        CONTENT_EXTRACTION_LATEST_PROGRESS_STEPS
        if latest else CONTENT_EXTRACTION_PROGRESS_STEPS
    )
    status_index = (
        CONTENT_EXTRACTION_LATEST_STATUS_INDEX
        if latest else CONTENT_EXTRACTION_STATUS_INDEX
    )
    current_index = status_index.get(status, 0)
    if status in CONTENT_EXTRACTION_TERMINAL_STATUSES:
        current_index = len(progress_steps) - 1
    percent = int(round((current_index + 1) / len(progress_steps) * 100))
    steps = []
    for index, (key, label, statuses) in enumerate(progress_steps):
        state = "done" if index < current_index else "current" if index == current_index else "pending"
        if status in CONTENT_EXTRACTION_TERMINAL_STATUSES and index == current_index:
            state = "done" if status == "已完成" else "warning"
        steps.append({"key": key, "label": label, "state": state, "active": status in statuses})
    return {"status": status, "percent": percent, "steps": steps, "done": status in CONTENT_EXTRACTION_TERMINAL_STATUSES}


def content_extraction_parse_time(value):
    text = str(value or "").strip()
    if not text:
        return None
    try:
        parsed = datetime.fromisoformat(text.replace("Z", "+00:00"))
    except ValueError:
        try:
            parsed = datetime.strptime(text[:19], "%Y-%m-%d %H:%M:%S")
        except ValueError:
            return None
    if parsed.tzinfo:
        return parsed.astimezone().replace(tzinfo=None)
    return parsed


def recover_interrupted_content_extraction_jobs(now_text=None, stale_minutes=5):
    if SAFE_PRODUCTION_ACTIVE:
        return 0
    current = content_extraction_parse_time(now_text) if now_text else datetime.now()
    if not current:
        current = datetime.now()
    stale_before = current - timedelta(minutes=stale_minutes)
    rows = db.all(
        f"""SELECT id,process_status,updated_at FROM content_extraction_jobs
            WHERE process_status IN ({','.join('?' for _ in CONTENT_EXTRACTION_PROCESSING_STATUSES)})""",
        tuple(CONTENT_EXTRACTION_PROCESSING_STATUSES),
    )
    changed = 0
    for row in rows:
        updated = content_extraction_parse_time(row["updated_at"])
        if updated and updated > stale_before:
            continue
        db.execute(
            """UPDATE content_extraction_jobs
               SET process_status=?,error_message=?,updated_at=?
               WHERE id=?""",
            (
                "失败",
                f"上次处理被中断，停在“{row['process_status']}”。请点击“重新识别”继续处理。",
                now_iso(),
                row["id"],
            ),
        )
        changed += 1
    return changed


def content_extraction_status_label(status):
    return str(status or "待处理")


def normalize_xiaohongshu_url(raw_url):
    value = str(raw_url or "").strip()
    if not value:
        return "", ""
    try:
        url = normalize_local_input(value).extracted_url
    except ExtractionError as error:
        if error.code == ExtractionErrorCode.LINK_NOT_FOUND and re.fullmatch(
            r"[^\s/]+(?:/[^\s]*)?", value,
        ):
            try:
                url = validate_http_url("https://" + value)
            except ExtractionError:
                return "", "链接格式错误，请重新粘贴小红书公开链接。"
        elif error.code == ExtractionErrorCode.LINK_AMBIGUOUS:
            return "", error.user_message
        elif error.code == ExtractionErrorCode.LINK_NOT_FOUND:
            return "", "未发现有效链接，请重新粘贴小红书分享文本或公开链接。"
        else:
            return "", "链接格式错误，请重新粘贴小红书公开链接。"
    parsed = urlparse(url)
    host = (parsed.netloc or "").lower().split("@")[-1].split(":")[0]
    if host not in XIAOHONGSHU_ALLOWED_HOSTS:
        return "", "只支持小红书公开链接，不处理其他平台链接。"
    return parsed._replace(fragment="").geturl(), ""


def content_extraction_completed_cache(source_url):
    normalized_url, _error = normalize_xiaohongshu_url(source_url)
    candidates = [str(source_url or "").strip()]
    if normalized_url and normalized_url not in candidates:
        candidates.append(normalized_url)
    candidates = [value for value in candidates if value]
    if not candidates:
        return None
    placeholders = ",".join("?" for _ in candidates)
    return db.one(
        f"""SELECT * FROM content_extraction_jobs
            WHERE source_platform='Xiaohongshu'
              AND source_url IN ({placeholders})
              AND process_status='已完成'
              AND (
                COALESCE(speech_transcript,'')<>''
                OR COALESCE(subtitle_ocr_text,'')<>''
                OR COALESCE(merged_text,'')<>''
                OR COALESCE(final_script,'')<>''
              )
            ORDER BY updated_at DESC,id DESC LIMIT 1""",
        tuple(candidates),
    )


def content_extraction_decode_json_string(value):
    text = html.unescape(str(value or "").strip())
    try:
        decoded = json.loads(f'"{text}"')
    except Exception:
        decoded = text
    for _index in range(3):
        next_decoded = decoded.replace("\\/", "/")
        if next_decoded == decoded:
            break
        decoded = next_decoded
    return decoded


def content_extraction_extract_public_video_url(html_text):
    text = str(html_text or "")
    meta_match = re.search(r'<meta[^>]+property=["\']og:video(?::url)?["\'][^>]+content=["\']([^"\']+)["\']', text, flags=re.I | re.S)
    if meta_match:
        return html.unescape(meta_match.group(1)).strip()
    for pattern in (
        r'"(?:videoUrl|video_url|masterUrl|backupUrl|backupUrls|url)"\s*:\s*"([^"]+?\.(?:mp4|mov)(?:\?[^"]*)?)"',
        r'(https?:\\?/\\?/[^"\'<> ]+?\.(?:mp4|mov)(?:\?[^"\'<> ]*)?)',
    ):
        for match in re.finditer(pattern, text, flags=re.I | re.S):
            candidate = content_extraction_decode_json_string(match.group(1))
            if re.match(r"^https?://", candidate, flags=re.I) and Path(urlparse(candidate).path).suffix.lower() in CONTENT_EXTRACTION_VIDEO_SUFFIXES:
                return candidate
    return ""


def xiaohongshu_public_adapter(source_url):
    url, error = normalize_xiaohongshu_url(source_url)
    if error:
        return {"ok": False, "error": error}
    if not url:
        return {"ok": False, "error": ""}
    try:
        request = urllib.request.Request(url, headers={"Accept": "text/html,application/xhtml+xml"})
        with urllib.request.urlopen(request, timeout=8) as response:
            final_url = response.geturl()
            content_type = response.headers.get("Content-Type", "")
            raw = response.read(2 * 1024 * 1024)
        if "text/html" not in content_type and raw[:1] not in {b"<", b"{"}:
            return {"ok": False, "error": "公开链接返回的不是可解析文本页面，请上传录屏、视频、截图或粘贴文案继续。"}
        html_text = raw.decode("utf-8", errors="replace")
        title = ""
        for pattern in (
            r'<meta[^>]+property=["\']og:title["\'][^>]+content=["\']([^"\']+)["\']',
            r'<meta[^>]+name=["\']title["\'][^>]+content=["\']([^"\']+)["\']',
            r"<title[^>]*>(.*?)</title>",
        ):
            match = re.search(pattern, html_text, flags=re.I | re.S)
            if match:
                title = html.unescape(re.sub(r"\s+", " ", match.group(1))).strip()
                break
        description = ""
        for pattern in (
            r'<meta[^>]+property=["\']og:description["\'][^>]+content=["\']([^"\']+)["\']',
            r'<meta[^>]+name=["\']description["\'][^>]+content=["\']([^"\']+)["\']',
        ):
            match = re.search(pattern, html_text, flags=re.I | re.S)
            if match:
                description = html.unescape(re.sub(r"\s+", " ", match.group(1))).strip()
                break
        video_url = content_extraction_extract_public_video_url(html_text)
        author = ""
        match = re.search(r'"nickname"\s*:\s*"([^"]+)"', html_text)
        if match:
            author = html.unescape(match.group(1)).strip()
        if not (title or description or video_url):
            return {"ok": False, "source_url": final_url, "error": "公开页面没有暴露可识别文案，可能需要登录或被平台限制。请上传录屏、视频、截图或粘贴文案继续。"}
        return {
            "ok": True,
            "source_url": final_url,
            "note_title": title,
            "note_text": description,
            "author_name": author,
            "video_url": video_url,
        }
    except Exception as exc:
        return {"ok": False, "source_url": url, "error": f"链接公开解析失败：{exc}。请上传录屏、视频、截图或粘贴文案继续。"}


def run_paddle_ocr_on_image(image_path):
    if not optional_module_available("paddleocr"):
        return "", "PaddleOCR 未安装。"
    try:
        from paddleocr import PaddleOCR

        try:
            ocr = PaddleOCR(use_angle_cls=True, lang="ch", show_log=False)
        except TypeError:
            ocr = PaddleOCR(use_angle_cls=True, lang="ch")
        result = ocr.ocr(str(image_path), cls=True)
        texts = []
        for block in result or []:
            for line in block or []:
                if len(line) >= 2 and line[1]:
                    text = line[1][0] if isinstance(line[1], (list, tuple)) else ""
                    if text:
                        texts.append(str(text).strip())
        return "\n".join(dict.fromkeys(texts)), ""
    except Exception as exc:
        return "", f"PaddleOCR 执行失败：{exc}"


def content_extract_image_ocr(image_path):
    try:
        mac_text = ocr_image_text(Path(image_path).read_bytes(), Path(image_path).suffix.lower())
        if mac_text.strip():
            return mac_text, ""
    except Exception:
        pass
    paddle_text, paddle_error = run_paddle_ocr_on_image(image_path)
    if paddle_text.strip():
        return paddle_text, ""
    try:
        mac_text = ocr_image_text(Path(image_path).read_bytes(), Path(image_path).suffix.lower())
        if mac_text.strip():
            return mac_text, paddle_error
    except Exception:
        pass
    return "", paddle_error or "OCR 未识别到文字。"


def content_extract_video_frames(video_path, job_id, seconds=2):
    deps = content_extraction_dependency_status()
    ffmpeg_path = deps.get("ffmpeg_path")
    if not ffmpeg_path:
        return [], "ffmpeg 未安装，无法从视频抽帧。"
    frame_dir = content_extraction_job_dir(job_id) / "frames"
    frame_dir.mkdir(parents=True, exist_ok=True)
    pattern = frame_dir / "frame_%04d.jpg"
    result = subprocess.run(
        [ffmpeg_path, "-y", "-i", str(video_path), "-vf", f"fps=1/{seconds}", "-q:v", "3", str(pattern)],
        cwd=str(APP_DIR),
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
        timeout=120,
        check=False,
    )
    if result.returncode != 0:
        return [], f"ffmpeg 抽帧失败：{result.stderr[-500:]}"
    return sorted(frame_dir.glob("frame_*.jpg")), ""


def content_extract_video_ocr(video_path, job_id):
    frames, error = content_extract_video_frames(video_path, job_id)
    if error:
        return "", error, 0
    texts = []
    errors = []
    for frame in frames[:120]:
        text, frame_error = content_extract_image_ocr(frame)
        if text.strip():
            texts.extend(line.strip() for line in text.splitlines() if line.strip())
        elif frame_error:
            errors.append(frame_error)
    deduped = []
    for text in texts:
        if not deduped or SequenceMatcher(None, deduped[-1], text).ratio() < 0.85:
            deduped.append(text)
    return "\n".join(deduped), errors[0] if errors and not deduped else "", len(frames)


def content_extract_video_transcript(video_path, job_id):
    deps = content_extraction_dependency_status()
    ffmpeg_path = deps.get("ffmpeg_path")
    if not ffmpeg_path:
        return "", "[]", "ffmpeg 未安装，无法提取音频。"
    audio_path = content_extraction_job_dir(job_id) / "audio.wav"
    result = subprocess.run(
        [ffmpeg_path, "-y", "-i", str(video_path), "-vn", "-acodec", "pcm_s16le", "-ar", "16000", "-ac", "1", str(audio_path)],
        cwd=str(APP_DIR),
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
        timeout=180,
        check=False,
    )
    if result.returncode != 0:
        return "", "[]", f"ffmpeg 提取音频失败：{result.stderr[-500:]}"
    if optional_module_available("faster_whisper"):
        try:
            from faster_whisper import WhisperModel

            model_name = os.environ.get("AAIE_CRM_WHISPER_MODEL", "base")
            model = WhisperModel(model_name, device="cpu", compute_type="int8")
            segments, _info = model.transcribe(str(audio_path), language="zh", vad_filter=True)
            rows = []
            for segment in segments:
                text = str(segment.text or "").strip()
                if text:
                    rows.append({"start": round(float(segment.start or 0), 2), "end": round(float(segment.end or 0), 2), "text": text})
            return "\n".join(item["text"] for item in rows), json.dumps(rows, ensure_ascii=False), ""
        except Exception as exc:
            return "", "[]", f"faster-whisper 转写失败：{exc}"
    if optional_module_available("whisper"):
        try:
            import whisper

            model_name = os.environ.get("AAIE_CRM_WHISPER_MODEL", "base")
            model = whisper.load_model(model_name)
            result = model.transcribe(str(audio_path), language="zh")
            rows = [
                {"start": round(float(item.get("start") or 0), 2), "end": round(float(item.get("end") or 0), 2), "text": str(item.get("text") or "").strip()}
                for item in result.get("segments", [])
                if str(item.get("text") or "").strip()
            ]
            return "\n".join(item["text"] for item in rows), json.dumps(rows, ensure_ascii=False), ""
        except Exception as exc:
            return "", "[]", f"Whisper 转写失败：{exc}"
    return "", "[]", "Whisper / faster-whisper 未安装，无法自动转写。"


def content_extraction_timestamp_lines(timestamps_json):
    try:
        segments = json.loads(timestamps_json or "[]")
    except Exception:
        segments = []
    lines = []
    for item in segments or []:
        try:
            start = float(item.get("start") or 0)
            end = float(item.get("end") or 0)
        except Exception:
            start = 0
            end = 0
        text = str(item.get("text") or "").strip()
        if not text:
            continue
        start_label = f"{int(start // 60):02d}:{int(start % 60):02d}"
        end_label = f"{int(end // 60):02d}:{int(end % 60):02d}"
        lines.append(f"{start_label}-{end_label} {text}")
    return "\n".join(lines)


def merge_content_extraction_text(job):
    speech = str(job.get("speech_transcript") or job.get("video_transcript") or "").strip()
    speech_timestamps = str(job.get("speech_transcript_with_timestamps") or job.get("video_transcript_json") or "").strip()
    subtitle = str(job.get("subtitle_ocr_text") or job.get("ocr_text") or "").strip()
    note_text = str(job.get("note_text") or "").strip()
    note_title = str(job.get("note_title") or "").strip()
    pasted_text = str(job.get("pasted_text") or "").strip()
    parts = []
    if note_title:
        parts.append(f"【标题】\n{note_title}")
    if note_text:
        parts.append(f"【链接正文】\n{note_text}")
    if pasted_text:
        parts.append(f"【手动粘贴】\n{pasted_text}")
    if speech:
        parts.append(f"【口播版】\n{speech}")
    if subtitle:
        parts.append(f"【字幕版】\n{subtitle}")
    merged = "\n\n".join(parts).strip()
    cleaned = re.sub(r"\n{3,}", "\n\n", merged)
    cleaned = re.sub(r"[ \t]+", " ", cleaned).strip()
    confidence = 0.0
    if speech and subtitle:
        confidence = 0.86
    elif speech:
        confidence = 0.8
    elif subtitle:
        confidence = 0.62
    elif note_text or pasted_text:
        confidence = 0.48
    needs_review = 0
    review_reasons = []
    if not (speech or subtitle or note_text or pasted_text):
        needs_review = 1
        review_reasons.append("没有识别到链接正文、口播、字幕或手动文案。")
    if speech and subtitle:
        speech_compact = re.sub(r"\s+", "", speech)
        subtitle_compact = re.sub(r"\s+", "", subtitle)
        if len(speech_compact) >= 80 and len(subtitle_compact) >= 80 and SequenceMatcher(None, speech_compact[:800], subtitle_compact[:800]).ratio() < 0.18:
            needs_review = 1
            review_reasons.append("口播转写和字幕 OCR 差异较大，请人工确认。")
    return {
        "original_speech_text": speech,
        "speech_transcript_with_timestamps": speech_timestamps,
        "speech_transcript_timestamp_text": content_extraction_timestamp_lines(speech_timestamps),
        "original_subtitle_text": subtitle,
        "merged_original_text": merged,
        "cleaned_text": cleaned,
        "extraction_confidence": confidence,
        "needs_manual_review": needs_review,
        "manual_review_reason": "\n".join(review_reasons),
    }


def content_extraction_calibration_payload(job):
    row = rowdict(job)
    return content_calibrate_extraction_text(
        ocr_text=row.get("subtitle_ocr_text") or row.get("ocr_text") or "",
        asr_text=row.get("speech_transcript") or row.get("video_transcript") or "",
        note_text="\n".join(item for item in (row.get("note_title") or "", row.get("note_text") or "") if str(item or "").strip()),
        pasted_text=row.get("pasted_text") or "",
    )


def content_pick_lines(text, limit=3):
    lines = []
    for raw in re.split(r"[\n。！？!?]+", str(text or "")):
        line = raw.strip(" -•\t")
        if not line or re.fullmatch(r"【[^】]+】", line):
            continue
        lines.append(line)
    return lines[:limit]


def content_bullet_text(items):
    return "\n".join(f"- {item}" for item in items if str(item or "").strip())


def content_json_list(items):
    return json.dumps([str(item).strip() for item in items if str(item or "").strip()], ensure_ascii=False)


def content_detect_account_topics(text):
    lower = str(text or "").lower()
    if re.search(r"孤独|想家|文化冲击|语言障碍|听不懂|美高|宿舍|presentation|没人懂|自我蜕变|适应环境", lower, re.I):
        return ["低龄留学适应", "文化冲击", "孤独成长"]
    topic_rules = [
        ("590陪读签证", ["590", "陪读", "监护", "guardian"]),
        ("公校私校选择", ["公校", "私校", "public", "private"]),
        ("澳洲高中规划", ["高中", "vce", "hsc", "year 10", "year 11", "year 12"]),
        ("K-12申请规划", ["k-12", "中小学", "低龄", "year 7", "小学"]),
        ("语言班和英文支持", ["语言班", "英文", "eal", "esl", "intensive"]),
        ("签证风险提醒", ["拒签", "风险", "签证", "材料"]),
        ("陪读家长安排", ["家长", "父母", "陪读", "住宿"]),
        ("选校规划", ["选校", "排名", "地区", "校区"]),
    ]
    topics = []
    for topic, probes in topic_rules:
        if any(probe in lower for probe in probes):
            topics.append(topic)
    return topics or ["澳洲低龄留学", "K-12申请规划", "陪读家长安排"]


def content_source_text_for_analysis(text):
    cleaned = re.sub(r"\n{3,}", "\n\n", str(text or "").strip())
    cleaned = re.sub(r"[ \t]+", " ", cleaned)
    cleaned = re.sub(r"【(?:标题|链接正文|手动粘贴|口播版|字幕版)】", "\n", cleaned)
    cleaned = re.sub(r"\n{3,}", "\n\n", cleaned).strip()
    # Light OCR cleanup before source analysis. Keep this conservative so the source meaning is not rewritten.
    replacements = {
        "英浯": "英语",
        "单词和语汰": "单词和语法",
        "囗语": "口语",
        "听カ": "听力",
        "閲读": "阅读",
        "髙不可攀": "高不可攀",
        "专业合办": "中外合作办学",
        "中外合办": "中外合作办学",
        "高考成绩联400": "高考成绩连400",
        "联400": "连400",
        "偏车": "偏科",
        "二加二": "2+2",
        "一加三": "1+3",
        "莫纳什": "澳大利亚莫纳什大学",
    }
    for wrong, right in replacements.items():
        cleaned = cleaned.replace(wrong, right)
    return cleaned


