def content_source_field_has_unintroduced_migration_terms(value, source_text):
    value_text = str(value or "")
    source = str(source_text or "")
    return any(term in value_text and term not in source for term in SOURCE_ANALYSIS_FORBIDDEN_MIGRATION_TERMS)


def content_source_analysis_guard(result, source_text):
    guarded = dict(result)
    source_fields = [
        "main_topic",
        "hook",
        "pain_points",
        "conflict_points",
        "emotional_points",
        "contrarian_view",
        "content_structure",
        "viral_reason",
        "reusable_sentences",
        "reusable_structure",
    ]
    for field in source_fields:
        if content_source_field_has_unintroduced_migration_terms(guarded.get(field), source_text):
            guarded[field] = "该字段触发迁移内容校验，请重新基于原文拆解。"
    return guarded


def content_generic_source_topic(cleaned_text, first_line):
    lines = content_pick_lines(cleaned_text, 3)
    summary = "。".join(lines[:2]).strip("。")
    if summary:
        return f"这条内容主要围绕原文提出的问题展开：{summary}。"
    return f"这条内容主要围绕：{first_line}"


