def analyze_content_extraction_text(merged_text, transcript_text="", previous_final_script=""):
    cleaned = re.sub(r"\n{3,}", "\n\n", str(merged_text or "").strip())
    cleaned = re.sub(r"[ \t]+", " ", cleaned)
    sentences = [item.strip() for item in re.split(r"(?<=[。！？!?])\s*|\n+", cleaned) if item.strip()]
    first = sentences[0] if sentences else ""
    topic_source = first[:46] or "澳洲低龄留学内容"
    viral = content_extraction_viral_analysis(cleaned)
    rewrite = content_extraction_rewrite_for_fage(cleaned, viral, previous_final_script=previous_final_script)
    keywords = json.loads(rewrite["topic_tags"])
    selling = "\n".join(f"- {tag}：从家长决策角度提炼可讲的痛点和提醒。" for tag in keywords[:5])
    hook = f"当前开头：{first or '未识别到明确开头'}\n建议：{viral['hook']}\n改写钩子：{rewrite['rewritten_hook']}"
    return {
        "cleaned_original_text": cleaned,
        "transcript_text": transcript_text or cleaned,
        "hook_analysis": hook,
        "hook": viral["hook"],
        "pain_points": viral["pain_points"],
        "conflict_points": viral["conflict_points"],
        "emotional_points": viral["emotional_points"],
        "contrarian_view": viral["contrarian_view"],
        "case_usage": viral["case_usage"],
        "content_structure": viral["content_structure"],
        "viral_reason": viral["viral_reason"],
        "reusable_sentences": viral["reusable_sentences"],
        "reusable_structure": viral["reusable_structure"],
        "rewrite_direction": viral["rewrite_direction"],
        "structure_analysis": viral["content_structure"],
        "selling_points": selling,
        "topic_tags": rewrite["topic_tags"],
        "rewritten_titles": rewrite["rewritten_titles"],
        "rewritten_script": rewrite["rewritten_script"],
        "rewritten_hook": rewrite["rewritten_hook"],
        "suggested_tags": rewrite["suggested_tags"],
        "key_message": rewrite["key_message"],
        "rewrite_for_fage": rewrite["rewrite_for_fage"],
        "final_script": rewrite["final_script"],
        "main_topic": viral["main_topic"],
    }


def read_docx_text(path):
    document = Document(str(path))
    parts = []
    for paragraph in document.paragraphs:
        text = paragraph.text.strip()
        if text:
            parts.append(text)
    for table in document.tables:
        for row in table.rows:
            cells = [cell.text.strip() for cell in row.cells if cell.text.strip()]
            if cells:
                parts.append(" | ".join(cells))
    return "\n".join(parts).strip()


def read_gdoc_shortcut(path):
    try:
        data = json.loads(Path(path).read_text(encoding="utf-8"))
    except Exception:
        return "", ""
    return str(data.get("doc_id") or data.get("resource_id") or data.get("url") or ""), str(data.get("url") or "")


def read_content_source_file(path):
    path = Path(path)
    suffix = path.suffix.lower()
    source_url = ""
    if suffix == ".docx":
        body = read_docx_text(path)
    elif suffix in {".txt", ".md"}:
        body = path.read_text(encoding="utf-8", errors="replace").strip()
    elif suffix == ".gdoc":
        _doc_id, source_url = read_gdoc_shortcut(path)
        body = ""
    else:
        body = ""
    lines = [line.strip() for line in body.splitlines() if line.strip()]
    title = path.stem
    if lines and 4 <= len(lines[0]) <= 90:
        title = lines[0]
        body = "\n".join(lines[1:]).strip() or body
    return {"title": title, "body": body, "source_url": source_url}


def content_date_from_mtime(path):
    return datetime.fromtimestamp(Path(path).stat().st_mtime).astimezone().date().isoformat()


def content_sync_threshold(setting_key):
    raw = str(db.setting(setting_key, "") or "").strip()
    if raw:
        try:
            return datetime.fromisoformat(raw)
        except ValueError:
            pass
    return datetime.now().astimezone().replace(hour=0, minute=0, second=0, microsecond=0)


def content_file_candidates(folder, *, since=None, include_all=False):
    folder = Path(folder)
    if not folder.exists() or not folder.is_dir():
        return []
    candidates = []
    for path in sorted(folder.rglob("*")):
        if not path.is_file() or path.name.startswith("."):
            continue
        if path.suffix.lower() not in CONTENT_SCRIPT_SYNC_EXTENSIONS:
            continue
        modified = datetime.fromtimestamp(path.stat().st_mtime).astimezone()
        if not include_all and since and modified < since:
            continue
        candidates.append(path)
    return candidates


def discover_google_drive_video_folder():
    configured = str(db.setting(GOOGLE_DRIVE_VIDEO_FOLDER_SETTING, "") or "").strip()
    if configured and Path(configured).is_dir():
        return Path(configured), ""
    base = Path.home() / "Library" / "CloudStorage"
    candidate_parts = [
        ("My Drive", "小红书", "发哥脚本", "视频"),
        ("我的云端硬盘", "小红书", "发哥脚本", "视频"),
        ("Google Drive", "小红书", "发哥脚本", "视频"),
        ("Other computers", "My Mac", "小红书", "发哥脚本", "视频"),
    ]
    if base.is_dir():
        for drive_root in sorted(base.glob("GoogleDrive-*")):
            for parts in candidate_parts:
                candidate = drive_root.joinpath(*parts)
                if candidate.is_dir():
                    return candidate, ""
        for drive_root in sorted(base.glob("GoogleDrive-*")):
            matches = []
            for root, dirs, _files in os.walk(drive_root):
                root_path = Path(root)
                if root_path.name in {"node_modules", ".git", "__pycache__"}:
                    dirs[:] = []
                    continue
                if root_path.name == "视频" and root_path.parent.name == "发哥脚本":
                    matches.append(root_path)
                    break
                if len(root_path.relative_to(drive_root).parts) > 7:
                    dirs[:] = []
            if matches:
                return matches[0], ""
    return None, "未找到 Google Drive 同步盘中的 小红书/发哥脚本/视频 文件夹。请确认 Google Drive for Desktop 已同步，或在系统设置中配置 CONTENT_GOOGLE_DRIVE_VIDEO_FOLDER。"


