def wechat_oauth_scope():
    scope = wechat_setting_value(WECHAT_OAUTH_SCOPE_SETTING, WECHAT_DEFAULT_OAUTH_SCOPE)
    return scope if scope in {"snsapi_base", "snsapi_userinfo"} else WECHAT_DEFAULT_OAUTH_SCOPE


def wechat_oauth_configured():
    return bool(wechat_setting_value(WECHAT_APP_ID_SETTING) and wechat_setting_value(WECHAT_APP_SECRET_SETTING))


def wechat_oauth_startup_messages():
    messages = []
    app_id = wechat_setting_value(WECHAT_APP_ID_SETTING)
    app_secret = wechat_setting_value(WECHAT_APP_SECRET_SETTING)
    callback_url = wechat_setting_value(WECHAT_OAUTH_CALLBACK_URL_SETTING) or f"{parent_form_base_url()}{WECHAT_OAUTH_CALLBACK_PATH}"
    scope = wechat_oauth_scope()
    if not app_id:
        messages.append("WECHAT_APP_ID 未配置，微信网页授权暂不可用。")
    if not app_secret:
        messages.append("WECHAT_APP_SECRET 未配置，微信网页授权暂不可用。")
    if callback_url != WECHAT_EXPECTED_CALLBACK_URL:
        messages.append(f"WECHAT_OAUTH_CALLBACK_URL 当前为 {callback_url}，正式建议使用 {WECHAT_EXPECTED_CALLBACK_URL}。")
    if scope != "snsapi_userinfo":
        messages.append("WECHAT_OAUTH_SCOPE 当前不是 snsapi_userinfo，正式授权可能无法取得微信昵称和头像。")
    if not messages:
        messages.append(f"{WECHAT_SERVICE_ACCOUNT_NAME}服务号微信网页授权配置已加载。")
    return messages


def wechat_oauth_state_setting_key(state):
    return WECHAT_OAUTH_STATE_PREFIX + re.sub(r"[^A-Za-z0-9_\-]", "", str(state or ""))[:80]


def wechat_exchange_oauth_code(code):
    app_id = wechat_setting_value(WECHAT_APP_ID_SETTING)
    app_secret = wechat_setting_value(WECHAT_APP_SECRET_SETTING)
    if not (app_id and app_secret):
        raise RuntimeError("微信 OAuth AppID / AppSecret 未配置。")
    query = urlencode({
        "appid": app_id,
        "secret": app_secret,
        "code": code,
        "grant_type": "authorization_code",
    })
    request = urllib.request.Request(
        "https://api.weixin.qq.com/sns/oauth2/access_token?" + query,
        headers={"Accept": "application/json"},
        method="GET",
    )
    try:
        with urllib.request.urlopen(request, timeout=20) as response:
            data = json.loads(response.read().decode("utf-8"))
    except urllib.error.HTTPError as exc:
        detail = exc.read().decode("utf-8", errors="replace")[:600]
        raise RuntimeError(f"WeChat OAuth failed HTTP {exc.code}: {detail}") from exc
    except urllib.error.URLError as exc:
        raise RuntimeError(f"WeChat OAuth connection failed: {exc}") from exc
    if data.get("errcode"):
        raise RuntimeError(f"WeChat OAuth failed: {data.get('errmsg') or data.get('errcode')}")
    return data


def wechat_fetch_userinfo(access_token, openid):
    if not (access_token and openid):
        return {}
    request = urllib.request.Request(
        "https://api.weixin.qq.com/sns/userinfo?" + urlencode({
            "access_token": access_token,
            "openid": openid,
            "lang": "zh_CN",
        }),
        headers={"Accept": "application/json"},
        method="GET",
    )
    try:
        with urllib.request.urlopen(request, timeout=15) as response:
            data = json.loads(response.read().decode("utf-8"))
    except Exception:
        return {}
    return {} if data.get("errcode") else data


