def template_status_badge(row):
    if row["is_active"]:
        return '<span class="status ok template-management-template-status template-management-status-active">当前使用</span>'
    return '<span class="status template-management-template-status template-management-status-standby">备用版本</span>'


def validate_template_upload(upload):
    if not upload or not upload.filename:
        raise ValueError("请选择 Word 模板文件。")
    if Path(upload.filename).suffix.lower() != ".docx":
        raise ValueError("模板文件必须是 .docx。")
    if not zipfile.is_zipfile(io.BytesIO(upload.data)):
        raise ValueError("这个 .docx 文件无法读取，请重新导出 Word 文件后再上传。")
    with zipfile.ZipFile(io.BytesIO(upload.data)) as archive:
        if "word/document.xml" not in archive.namelist():
            raise ValueError("这个 Word 文件缺少正文内容，不能作为合同模板。")


def template_record_file_path(record):
    return ensure_within(record["file_path"], TEMPLATE_DIR)


def next_template_record_path(contract_type):
    MANAGED_TEMPLATE_DIR.mkdir(parents=True, exist_ok=True)
    stamp = datetime.now().astimezone().strftime("%Y%m%d")
    existing = db.one("SELECT MAX(version) AS version FROM template_records WHERE contract_type=?", (contract_type,))
    version_seed = int(existing["version"] or 0) + 1 if existing else 1
    return next_version_path(MANAGED_TEMPLATE_DIR, f"{contract_type}_{stamp}_V{version_seed}.docx")


def save_template_upload(upload, contract_type):
    validate_template_upload(upload)
    target, version = next_template_record_path(contract_type)
    target.write_bytes(upload.data)
    return target, version


def activate_template_record(record, user=None):
    source = template_record_file_path(record)
    if not source.is_file():
        raise ValueError("模板文件不存在。")
    info = CONTRACT_TEMPLATE_TYPES.get(record["contract_type"], {})
    target = info.get("target")
    if target:
        target = ensure_within(target, TEMPLATE_DIR)
        target.parent.mkdir(parents=True, exist_ok=True)
        if target.exists():
            stamp = datetime.now().astimezone().strftime("%Y%m%d%H%M%S")
            archived, _ = next_version_path(TEMPLATE_ARCHIVE_DIR, f"{target.stem}_{stamp}_V1{target.suffix}")
            shutil.copy2(target, archived)
        shutil.copy2(source, target)
    with db.transaction() as conn:
        conn.execute("UPDATE template_records SET is_active=0,updated_at=? WHERE contract_type=?", (now_iso(), record["contract_type"]))
        conn.execute("UPDATE template_records SET is_active=1,updated_by=?,updated_at=? WHERE id=?", (user["id"] if user else None, now_iso(), record["id"]))


def iter_template_paragraphs(document):
    for paragraph in document.paragraphs:
        yield "正文", paragraph
    for table_index, table in enumerate(document.tables, 1):
        yield from iter_table_paragraphs(table, f"表格 {table_index}")


def iter_table_paragraphs(table, label):
    for row_index, row in enumerate(table.rows, 1):
        for cell_index, cell in enumerate(row.cells, 1):
            cell_label = f"{label} R{row_index}C{cell_index}"
            for paragraph in cell.paragraphs:
                yield cell_label, paragraph
            for nested_index, nested_table in enumerate(cell.tables, 1):
                yield from iter_table_paragraphs(nested_table, f"{cell_label}.{nested_index}")


def template_editor_blocks(path):
    document = Document(str(path))
    blocks = []
    for index, (section, paragraph) in enumerate(iter_template_paragraphs(document)):
        text = paragraph.text
        if text.strip():
            blocks.append({"index": index, "section": section, "text": text})
    return blocks


def set_paragraph_text(paragraph, text):
    if paragraph.runs:
        paragraph.runs[0].text = text
        for run in paragraph.runs[1:]:
            run.text = ""
    else:
        paragraph.add_run(text)


