def contract_template_string(value):
    if value is None:
        return ""
    if isinstance(value, list):
        return "\n".join(str(item) for item in value)
    return str(value)


def contract_service_scope_text(payload):
    if payload.get("service_scope_override_text"):
        return str(payload.get("service_scope_override_text") or "")
    scopes = payload.get("service_scope_items") or []
    other_scope = str(payload.get("other_service_scope_text") or "").strip()
    lines = []
    if scopes:
        lines.extend(f"{index}. {item}" for index, item in enumerate(scopes, 1))
    if other_scope:
        lines.append(f"其他服务范围：{other_scope}")
    return "\n".join(lines)


def contract_template_context(payload):
    context = {key: contract_template_string(value) for key, value in payload.items()}
    context["intake_term"] = contract_intake_year_term_display(payload.get("intake_year") or payload.get("preferred_intake_year"), payload.get("intake_term"))
    context["intake_term_display"] = context["intake_term"]
    context["service_scope_text"] = contract_service_scope_text(payload)
    context["student_passport_or_id_number"] = context.get("student_id_or_passport_number", "")
    context["company_abn"] = context.get("company_abn_acn", "")
    context["contract_number"] = context.get("contract_uid", "")
    context["fee_final_amount"] = context.get("final_fee_amount", "")
    for alias, key in CONTRACT_TEMPLATE_VARIABLE_ALIASES.items():
        context[alias] = context.get(key, "")
    return context


def contract_template_section_override_map(payload):
    standard = payload.get("standard_clause_texts") or {}
    defaults = study_contract_standard_texts()
    configured_sections = payload.get("contract_sections") or {}
    if normalize_contract_type(payload.get("contract_type")) == DEFAULT_CONTRACT_TYPE and standard:
        configured_sections = {}
    groups = [
        ("二、服务项目及服务范围", (("service_scope", ""),)),
        ("三、服务费用与第三方费用", (
            ("standard", "fee_explanation"),
            ("standard", "third_party_fees"),
            ("standard", "third_party_decisions"),
        )),
        ("四、甲方权利义务", (("standard", "party_a_obligations"),)),
        ("五、乙方权利义务", (("standard", "party_b_obligations"),)),
        ("六、退费及违约责任", (
            ("standard", "refund_intro"),
            ("standard", "third_party_refund"),
            ("refund_policy", ""),
            ("standard", "termination_no_refund"),
            ("standard", "false_documents"),
        )),
        ("七、不可抗力、结果说明及免责", (
            ("standard", "result_disclaimer"),
            ("standard", "force_majeure"),
        )),
        ("八、适用法律及争议解决", (
            ("payload", "governing_law"),
            ("payload", "dispute_resolution"),
        )),
        ("九、合同补充、变更和生效", (
            ("standard", "contract_variation"),
            ("standard", "minor_guardian"),
            ("standard", "contract_effective"),
            ("standard", "personal_expenses"),
        )),
        ("十、特别条款", (("payload", "special_terms"),)),
    ]
    overrides = {}
    for heading, fields in groups:
        if heading in configured_sections:
            overrides[heading] = str(configured_sections.get(heading) or "").strip()
            continue
        changed = False
        lines = []
        for source, key in fields:
            text = ""
            if source == "service_scope":
                text = contract_service_scope_text(payload)
                changed = True
            elif source == "standard":
                text = str(standard.get(key) or "").strip()
                changed = changed or (text and text != str(defaults.get(key) or "").strip())
            elif source == "refund_policy":
                text = str(payload.get("refund_policy_text") or "").strip()
            elif source == "payload":
                text = str(payload.get(key) or "").strip()
                changed = changed or bool(text)
            if text:
                lines.extend(line.strip() for line in text.splitlines() if line.strip())
        if changed and lines:
            overrides[heading] = "\n".join(lines)
    for heading, content in configured_sections.items():
        if is_contract_template_numbered_heading(heading) and heading != "十一、签署":
            overrides[str(heading)] = str(content or "").strip()
    return overrides


def is_contract_template_numbered_heading(text):
    return bool(re.match(r"^[一二三四五六七八九十]+、", str(text or "").strip()))


def insert_paragraph_after(paragraph, text):
    from docx.oxml import OxmlElement
    from docx.text.paragraph import Paragraph

    new_element = OxmlElement("w:p")
    paragraph._p.addnext(new_element)
    new_paragraph = Paragraph(new_element, paragraph._parent)
    set_paragraph_text(new_paragraph, text)
    try:
        new_paragraph.style = paragraph.style
    except Exception:
        pass
    return new_paragraph


def remove_paragraph(paragraph):
    element = paragraph._element
    parent = element.getparent()
    if parent is not None:
        parent.remove(element)


def apply_contract_template_section_overrides(document, payload):
    overrides = contract_template_section_override_map(payload)
    if not overrides:
        return []
    applied = []
    index = 0
    while index < len(document.paragraphs):
        paragraph = document.paragraphs[index]
        heading = paragraph.text.strip()
        replacement = overrides.get(heading)
        if not replacement:
            index += 1
            continue
        paragraphs = document.paragraphs
        body_start = index + 1
        body_end = body_start
        while body_end < len(paragraphs) and not is_contract_template_numbered_heading(paragraphs[body_end].text):
            body_end += 1
        if body_start < body_end:
            set_paragraph_text(paragraphs[body_start], replacement)
            for extra in list(paragraphs[body_start + 1:body_end]):
                remove_paragraph(extra)
        else:
            insert_paragraph_after(paragraph, replacement)
        applied.append(heading)
        index += 2
    return applied


def replace_template_variables_in_text(text, context):
    def repl(match):
        key = match.group(1).strip()
        return context.get(key, "")

    return re.sub(r"\{\{\s*([A-Za-z0-9_.-]+)\s*\}\}", repl, text or "")


def replace_template_variables_in_document(document, payload):
    context = contract_template_context(payload)
    missing = set()

    def render_text(text):
        for key in re.findall(r"\{\{\s*([A-Za-z0-9_.-]+)\s*\}\}", text or ""):
            if key.strip() not in context:
                missing.add(key.strip())
        return replace_template_variables_in_text(text, context)

    for _section, paragraph in iter_template_paragraphs(document):
        if "{{" in paragraph.text and "}}" in paragraph.text:
            set_paragraph_text(paragraph, render_text(paragraph.text))
    for section in document.sections:
        for part in (section.header, section.footer):
            for paragraph in part.paragraphs:
                if "{{" in paragraph.text and "}}" in paragraph.text:
                    set_paragraph_text(paragraph, render_text(paragraph.text))
            for table in part.tables:
                for _label, paragraph in iter_table_paragraphs(table, "页眉页脚表格"):
                    if "{{" in paragraph.text and "}}" in paragraph.text:
                        set_paragraph_text(paragraph, render_text(paragraph.text))
    return sorted(missing)


def remove_contract_student_id_rows(document):
    removed = 0
    for table in document.tables:
        for row in list(table.rows):
            row_text = "\n".join(cell.text for cell in row.cells)
            if "学生护照号 / 学生 ID" in row_text:
                row._tr.getparent().remove(row._tr)
                removed += 1
    for _section, paragraph in list(iter_template_paragraphs(document)):
        text = paragraph.text
        if "学生护照号 / 学生 ID" in text:
            kept_lines = [
                line for line in text.splitlines()
                if "学生护照号 / 学生 ID" not in line
            ]
            if kept_lines:
                set_paragraph_text(paragraph, "\n".join(kept_lines))
            else:
                remove_paragraph(paragraph)
            removed += 1
    return removed


def active_contract_template_record(contract_type="StudyAbroadContract"):
    return db.one(
        "SELECT * FROM template_records WHERE contract_type=? AND is_active=1 ORDER BY updated_at DESC LIMIT 1",
        (contract_type,),
    )


def render_study_contract_from_active_template(payload, destination):
    record = active_contract_template_record("StudyAbroadContract")
    if not record:
        raise ValueError("当前没有启用的留学合同模板。")
    source = template_record_file_path(record)
    if not source.is_file():
        raise ValueError("当前启用的留学合同模板文件不存在。")
    contract_generation_missing_error(payload)
    destination = Path(destination)
    destination.parent.mkdir(parents=True, exist_ok=True)
    document = Document(str(source))
    missing_variables = replace_template_variables_in_document(document, payload)
    if missing_variables:
        raise ValueError("合同模板包含未支持变量：" + "、".join(missing_variables))
    remove_contract_student_id_rows(document)
    apply_contract_template_section_overrides(document, payload)
    remove_study_contract_duplicate_title_intro(document, payload)
    add_study_contract_cover_page(document, payload)
    document.core_properties.title = payload.get("contract_title") or STUDY_CONTRACT_TITLE
    document.core_properties.subject = f"AAIE CRM Study Abroad Contract from template V{record['version']}"
    document.save(destination)
    return destination


def generate_study_contract_document(payload, destination):
    if isinstance(payload, dict) and is_published_v2_snapshot(payload):
        rendered = render_bound_contract(payload)
        destination = Path(destination)
        destination.parent.mkdir(parents=True, exist_ok=True)
        destination.write_bytes(rendered.docx_bytes)
        return destination
    try:
        return render_study_contract_from_active_template(payload, destination)
    except ValueError as exc:
        if "当前没有启用" not in str(exc) and "模板文件不存在" not in str(exc):
            raise
    contract_generation_missing_error(payload)
    generated = generate_study_abroad_contract(payload, destination)
    document = Document(str(generated))
    apply_contract_template_section_overrides(document, payload)
    document.save(generated)
    return generated


def find_soffice_executable():
    candidates = [
        "/Applications/LibreOffice.app/Contents/MacOS/soffice",
        shutil.which("soffice"),
        shutil.which("libreoffice"),
        str(APP_DIR / ".local" / "bin" / "soffice"),
    ]
    for candidate in candidates:
        if candidate and Path(candidate).is_file():
            return candidate
    return ""


def pdf_text(path):
    reader = PdfReader(str(path))
    return "\n".join(page.extract_text() or "" for page in reader.pages)


