def duplicate_application_doc(student_id, filename):
    return db.one(
        """SELECT * FROM student_documents
           WHERE student_id=? AND folder_category='Applications' AND is_active=1 AND lower(original_name)=lower(?)
           ORDER BY version DESC, uploaded_at DESC LIMIT 1""",
        (student_id, filename),
    )


def replace_document(student, upload, existing, category, user, forced_type=None):
    folder = nas.student_folder(student)
    destination = ensure_within(existing["file_path"], folder)
    old_value = json.dumps(
        {
            "action": "replace_existing_file",
            "original_name": existing["original_name"],
            "stored_name": existing["stored_name"],
            "file_path": existing["file_path"],
            "version": existing["version"],
            "file_size": existing["file_size"],
        },
        ensure_ascii=False,
    )
    destination.parent.mkdir(parents=True, exist_ok=True)
    destination.write_bytes(upload.data)
    doc_type = forced_type or detect_document_type(upload.filename)
    preview = make_preview(existing["id"], destination.name, upload.data, upload.content_type)
    make_preview(existing["id"], destination.name, upload.data, upload.content_type, size="large")
    db.execute(
        """UPDATE student_documents
           SET document_type=?,original_name=?,stored_name=?,file_size=?,uploaded_by=?,uploaded_at=?,preview_path=?
           WHERE id=?""",
        (doc_type, upload.filename, destination.name, len(upload.data), user["id"], now_iso(), preview, existing["id"]),
    )
    new_value = json.dumps(
        {
            "action": "uploaded_file_replaced_previous_file",
            "original_name": upload.filename,
            "stored_name": destination.name,
            "file_path": str(destination),
            "version": existing["version"],
            "file_size": len(upload.data),
            "document_type": doc_type,
        },
        ensure_ascii=False,
    )
    db.audit(user, "replace", category, existing["id"], str(destination), old_value=old_value, new_value=new_value)
    return existing["id"]


def save_document(student, upload, category, user, forced_type=None, duplicate_action="version"):
    existing = duplicate_application_doc(student["student_id"], upload.filename) if category == "Applications" else None
    if existing and duplicate_action == "replace":
        return replace_document(student, upload, existing, category, user, forced_type)
    folder = nas.category_folder(student, category)
    destination, version = next_version_path(folder, upload.filename)
    destination.write_bytes(upload.data)
    doc_type = forced_type or detect_document_type(destination.name)
    document_id = db.execute(
        """INSERT INTO student_documents(student_id,folder_category,document_type,original_name,stored_name,
           file_path,version,file_size,uploaded_by,uploaded_at,is_active) VALUES(?,?,?,?,?,?,?,?,?,?,1)""",
        (
            student["student_id"], category, doc_type, upload.filename, destination.name,
            str(destination), version, len(upload.data), user["id"], now_iso(),
        ),
    )
    preview = make_preview(document_id, destination.name, upload.data, upload.content_type)
    make_preview(document_id, destination.name, upload.data, upload.content_type, size="large")
    db.execute("UPDATE student_documents SET preview_path=? WHERE id=?", (preview, document_id))
    db.audit(user, "upload", category, document_id, str(destination), new_value=doc_type)
    return document_id


def save_school_plan_pdf_application_document(student, pdf_path, user):
    target = Path(pdf_path)
