def upload_review_path(token):
    safe = re.sub(r"[^A-Za-z0-9_-]", "", token or "")
    if not safe:
        raise ValueError("Upload Review token 无效")
    UPLOAD_REVIEW_DIR.mkdir(parents=True, exist_ok=True)
    return ensure_within(UPLOAD_REVIEW_DIR / safe, UPLOAD_REVIEW_DIR)


def refresh_upload_session_counts(session_id):
    counts = {
        row["status"]: row["count"]
        for row in db.all(
            "SELECT status,COUNT(*) count FROM upload_review_items WHERE upload_session_id=? GROUP BY status",
            (session_id,),
        )
    }
    total = sum(counts.values())
    confirmed = counts.get("Confirmed", 0)
    cancelled = counts.get("Cancelled", 0)
    status = "Confirmed" if total and confirmed == total else "Cancelled" if total and cancelled == total else "NeedsReview"
    db.execute(
        "UPDATE upload_sessions SET status=?,total_files=?,confirmed_files=?,cancelled_files=? WHERE id=?",
        (status, total, confirmed, cancelled, session_id),
    )


def create_upload_review(student_id, module, uploads, user, form=None):
    if module not in MODULE_REVIEW_CONFIG:
        raise ValueError("未知上传模块")
    token = new_token(18).replace("-", "_")
    folder = upload_review_path(token)
    folder.mkdir(parents=False, exist_ok=False)
    files = []
    prepared_uploads = []
    for upload in uploads:
        if not upload.filename:
            continue
        if module == "Applications" and upload.filename.lower().endswith(".zip"):
            with tempfile.NamedTemporaryFile(suffix=".zip") as temp:
                temp.write(upload.data)
                temp.flush()
                members = nas.safe_zip_members(temp.name)
                with zipfile.ZipFile(temp.name) as archive:
                    for member in members:
                        filename = Path(member.filename).name
                        if filename.startswith("._") or not filename:
                            continue
                        data = archive.read(member)
                        prepared_uploads.append(
                            Upload("files", filename, mimetypes.guess_type(filename)[0] or "application/octet-stream", data)
                        )
        else:
            prepared_uploads.append(upload)
    if not prepared_uploads:
        raise ValueError("请选择文件")
    session_id = db.execute(
        """INSERT INTO upload_sessions(session_token,student_id,module_key,uploaded_by,uploaded_at,status,total_files,notes)
           VALUES(?,?,?,?,?,'NeedsReview',?,?)""",
        (token, str(student_id), module, user["id"], now_iso(), len(prepared_uploads), ""),
    )
    db.audit(
        user, "upload_session_created", "upload_review", session_id,
        new_value=json.dumps({"student_id": str(student_id), "module": module, "total_files": len(prepared_uploads)}, ensure_ascii=False),
        student_id=str(student_id),
    )
    for index, upload in enumerate(prepared_uploads):
        blob_name = f"{index}.bin"
        staging_path = ensure_within(folder / blob_name, folder)
        staging_path.write_bytes(upload.data)
        item_id = db.execute(
            """INSERT INTO upload_review_items(
               upload_session_id,student_id,module_key,original_file_name,staging_file_path,
               file_type,file_size,status,uploaded_by,uploaded_at
            ) VALUES(?,?,?,?,?,?,?,'NeedsReview',?,?)""",
            (
                session_id, str(student_id), module, upload.filename, str(staging_path),
                upload.content_type or mimetypes.guess_type(upload.filename)[0] or "application/octet-stream",
                len(upload.data), user["id"], now_iso(),
            ),
        )
        db.audit(
            user, "file_uploaded_to_staging", "upload_review", item_id, file_path=str(staging_path),
            new_value=json.dumps({"session_id": session_id, "original_file_name": upload.filename}, ensure_ascii=False),
            student_id=str(student_id),
        )
        files.append(
            {
                "index": index,
                "item_id": item_id,
                "blob": blob_name,
                "original_name": upload.filename,
                "content_type": upload.content_type or mimetypes.guess_type(upload.filename)[0] or "application/octet-stream",
                "size": len(upload.data),
            }
        )
    metadata = {
        "token": token,
        "session_id": session_id,
        "student_id": str(student_id),
        "module": module,
        "created_by": user["id"],
        "created_at": now_iso(),
        "form": dict(form or {}),
        "files": files,
    }
    ensure_within(folder / "review.json", folder).write_text(json.dumps(metadata, ensure_ascii=False), encoding="utf-8")
    return token


def load_upload_review(token):
    folder = upload_review_path(token)
    metadata_path = ensure_within(folder / "review.json", folder)
    if not metadata_path.exists():
        raise ValueError("Upload Review 已失效或不存在")
    return folder, json.loads(metadata_path.read_text(encoding="utf-8"))


def delete_upload_review(token):
    try:
        folder = upload_review_path(token)
        if folder.exists():
            shutil.rmtree(folder)
    except Exception:
        pass


def upload_from_review(folder, file_meta):
    blob = ensure_within(folder / file_meta["blob"], folder)
    data = blob.read_bytes()
    return Upload("file", file_meta["original_name"], file_meta.get("content_type") or "application/octet-stream", data)


def save_application_uploads(student, uploads, user, duplicate_action="version"):
    imported = []
    for upload in uploads:
        if not upload.filename:
            continue
        if upload.filename.lower().endswith(".zip"):
            with tempfile.NamedTemporaryFile(suffix=".zip") as temp:
                temp.write(upload.data)
                temp.flush()
                members = nas.safe_zip_members(temp.name)
                with zipfile.ZipFile(temp.name) as archive:
                    for member in members:
                        filename = Path(member.filename).name
                        if filename.startswith("._") or not filename:
                            continue
                        data = archive.read(member)
                        imported.append(save_document(student, Upload("files", filename, mimetypes.guess_type(filename)[0] or "application/octet-stream", data), "Applications", user, duplicate_action="version"))
        else:
            imported.append(save_document(student, upload, "Applications", user, duplicate_action="version"))
    return imported


def material_status(student_id):
    rows = db.all(
        "SELECT document_type,COUNT(*) count FROM student_documents WHERE student_id=? AND folder_category='Applications' AND is_active=1 GROUP BY document_type",
        (student_id,),
    )
    counts = {row["document_type"]: row["count"] for row in rows}
    if counts.get("Passport") and not counts.get("StudentPassport"):
        counts["StudentPassport"] = counts["Passport"]
    return [(kind, counts.get(kind, 0)) for kind in DOCUMENT_TYPES]


def normalize_offer_date(value):
    return parseAustralianDate(value)["normalized_date"]


def offer_dates_from_text(text):
    month = r"(?:Jan(?:uary)?|Feb(?:ruary)?|Mar(?:ch)?|Apr(?:il)?|May|Jun(?:e)?|Jul(?:y)?|Aug(?:ust)?|Sep(?:t(?:ember)?)?|Oct(?:ober)?|Nov(?:ember)?|Dec(?:ember)?)"
    patterns = [
        r"\b\d{4}\s*[-/.]\s*\d{1,2}\s*[-/.]\s*\d{1,2}\b",
        r"\b\d{1,2}\s*[-/.]\s*\d{1,2}\s*[-/.]\s*\d{2,4}\b",
        rf"\b\d{{1,2}}(?:st|nd|rd|th)?\s+{month},?\s+\d{{4}}\b",
        rf"\b\d{{1,2}}[-]{month}[-]\d{{4}}\b",
        rf"\b{month}\s+\d{{1,2}}(?:st|nd|rd|th)?,?\s+\d{{4}}\b",
    ]
    found = []
    for pattern in patterns:
        for match in re.finditer(pattern, text, flags=re.I):
            normalized = normalize_offer_date(match.group(0))
            if normalized:
                found.append((match.start(), normalized))
    return sorted(found, key=lambda item: item[0])


DOCUMENT_DATE_NEGATIVE_ANCHOR_RE = re.compile(
    r"\b("
    r"date\s+of\s+birth|dob|birth\s+date|issued\s+on|issue\s+date|issued\s+date|date\s+of\s+issue|"
    r"signed|signature\s+date|signed\s+date|payment\s+date|paid\s+date|invoice\s+date|invoice\s+due\s+date|"
    r"due\s+date|generated\s+date|created\s+date|printed\s+date|print\s+date|downloaded\s+date|"
    r"certificate\s+print\s+date|certificate\s+printed\s+date"
    r")\b",
    re.I,
)


def document_date_has_negative_anchor(line):
    return bool(DOCUMENT_DATE_NEGATIVE_ANCHOR_RE.search(str(line or "")))


def dates_from_safe_lines(lines):
    found = []
    position = 0
    for line in lines:
        if document_date_has_negative_anchor(line):
            position += len(line) + 1
            continue
        for _pos, value in offer_dates_from_text(line):
            found.append((position + _pos, value))
        position += len(line) + 1
    return sorted(found, key=lambda item: item[0])


def best_context_date(lines, keywords, date_index=0, allow_negative_anchor=False):
    for index, line in enumerate(lines):
        lower = line.lower()
        if any(keyword in lower for keyword in keywords):
            window_lines = [
                item for item in lines[index:index + 3]
                if allow_negative_anchor or not document_date_has_negative_anchor(item)
            ]
            dates = offer_dates_from_text(" ".join(window_lines))
            if dates:
                return dates[date_index][1]
    return ""


def best_regex_context_date(lines, patterns, date_index=0, window=4, allow_negative_anchor=False):
    compiled = [re.compile(pattern, re.I) for pattern in patterns]
    for index, line in enumerate(lines):
        if any(pattern.search(line) for pattern in compiled):
            dates = [] if (document_date_has_negative_anchor(line) and not allow_negative_anchor) else [date for _, date in offer_dates_from_text(line)]
            if dates:
                return dates[date_index]
            for candidate in lines[index + 1:index + window]:
                if document_date_has_negative_anchor(candidate) and not allow_negative_anchor:
                    continue
                dates = [date for _, date in offer_dates_from_text(candidate)]
                if dates:
                    return dates[date_index]
    return ""


def date_after_label(lines, patterns, date_index=0, window=4, allow_negative_anchor=False):
    compiled = [re.compile(pattern, re.I) for pattern in patterns]
    for index, line in enumerate(lines):
        for pattern in compiled:
            match = pattern.search(line)
            if not match:
                continue
            suffix = line[match.end():]
            dates = [] if (document_date_has_negative_anchor(line) and not allow_negative_anchor) else [date for _, date in offer_dates_from_text(suffix)]
            if dates:
                return dates[date_index]
            for candidate in lines[index + 1:index + window]:
                if document_date_has_negative_anchor(candidate) and not allow_negative_anchor:
                    continue
                dates = [date for _, date in offer_dates_from_text(candidate)]
                if dates:
                    return dates[date_index]
    return ""


def context_dates(lines, keywords, window=3):
    dates = []
    for index, line in enumerate(lines):
        lower = line.lower()
        if any(keyword in lower for keyword in keywords):
            for candidate in lines[index:index + window]:
                if document_date_has_negative_anchor(candidate):
                    continue
                dates.extend(date for _, date in offer_dates_from_text(candidate))
    return dates


def caaw_welfare_section_dates(lines):
    anchor_re = re.compile(r"\b(?:nominated|nominiated)\s+welfare\s+period\b|\bcaaw\s+welfare\b|\bwelfare\s+period\b", re.I)
    start_re = re.compile(r"\b(?:start|state|stat|star)\s+date\b|\bwelfare\s+(?:start|state|stat|star)\b", re.I)
    end_re = re.compile(r"\bend\s+date\b|\bwelfare\s+end\b|\bwelfare\s+expiry\b|\bwelfare\s+finish\b", re.I)

    anchor_index = None
    for index, line in enumerate(lines):
        if anchor_re.search(line):
            anchor_index = index
            break
    if anchor_index is None:
        return "", "", False

    section = []
    for line in lines[anchor_index:anchor_index + 40]:
        if re.search(r"^\s*(?:[F-Z]\.\s*)?(?:provider\s+details|provider\s+name|course\s+details|signed|signature)\b", line, re.I):
            break
        section.append(line)

    def dates_from_following(index, label_re, date_index=0):
        line = section[index]
        match = label_re.search(line)
        if not match:
            return ""
        suffix_dates = [date_value for _, date_value in offer_dates_from_text(line[match.end():])]
        if suffix_dates:
            return suffix_dates[date_index]
        for candidate in section[index + 1:index + 8]:
            if label_re is start_re and end_re.search(candidate):
                break
            if label_re is end_re and start_re.search(candidate):
                continue
            dates = [date_value for _, date_value in offer_dates_from_text(candidate)]
            if dates:
                return dates[date_index]
        return ""

    start = ""
    end = ""
    for index, line in enumerate(section):
        if start_re.search(line) and end_re.search(line):
            start_match = start_re.search(line)
            end_match = end_re.search(line)
            start_dates = offer_dates_from_text(line[start_match.end():end_match.start()])
            end_dates = offer_dates_from_text(line[end_match.end():])
            if start_dates and end_dates:
                start, end = start_dates[0][1], end_dates[0][1]
                break
            dates = []
            for candidate in section[index:index + 8]:
                dates.extend(date_value for _, date_value in offer_dates_from_text(candidate))
            if len(dates) >= 2:
                start, end = dates[0], dates[-1]
                break
        if not start and start_re.search(line):
            start = dates_from_following(index, start_re, 0)
        if not end and end_re.search(line):
            end = dates_from_following(index, end_re, -1)
    dates = []
    for line in section:
        if document_date_has_negative_anchor(line):
            continue
        dates.extend(date_value for _, date_value in offer_dates_from_text(line))
    if not start and dates:
        start = dates[0]
    if not end and len(dates) > 1:
        end = dates[-1]
    return start, end, True


def caaw_welfare_section_present(lines):
    return any(
        re.search(r"\b(?:nominated|nominiated)\s+welfare\s+period\b|\bcaaw\s+welfare\b|\bwelfare\s+period\b", line, flags=re.I)
        for line in lines
    )


def caaw_welfare_period_dates(lines):
    section_start, section_end, section_found = caaw_welfare_section_dates(lines)
    if section_found:
        return section_start, section_end
    context_keywords = (
        "nominated welfare period", "nominiated welfare period",
        "nominated welfare", "nominiated welfare", "welfare period",
        "welfare arrangements", "caaw",
    )
    start_keywords = (
        "welfare start", "caaw start", "nominated welfare period start",
        "nominiated welfare period start", "welfare period start",
        "welfare commencement", "welfare from",
    )
    end_keywords = (
        "welfare end", "caaw end", "nominated welfare period end",
        "nominiated welfare period end", "welfare period end",
        "welfare expiry", "welfare finish", "welfare to",
    )
    start = best_context_date(lines, start_keywords, 0)
    end = best_context_date(lines, end_keywords, -1)
    dates = context_dates(lines, context_keywords)
    wider_context_dates = context_dates(lines, context_keywords, 8)
    if not start and dates:
        start = dates[0]
    if not end and len(dates) > 1:
        end = dates[-1]
    if not end and start:
        for candidate in reversed(wider_context_dates):
            if candidate != start:
                end = candidate
                break
    return start, end


def plausible_caaw_welfare_end_date(start, end):
    if not start or not end:
        return False
    try:
        start_date = date.fromisoformat(str(start)[:10])
        end_date = date.fromisoformat(str(end)[:10])
    except ValueError:
        return False
    if end_date < start_date:
        return False
    return (end_date - start_date).days <= 365 * 8


def fallback_caaw_welfare_end_date(start, course_end="", all_dates=None):
    if plausible_caaw_welfare_end_date(start, course_end):
        return course_end
    candidates = []
    for _position, candidate in all_dates or []:
        if candidate != start and plausible_caaw_welfare_end_date(start, candidate):
            candidates.append(candidate)
    return candidates[-1] if candidates else ""


def normalized_search_text(text):
    return re.sub(r"\s+", " ", str(text or "")).strip().lower()


def is_sa_government_caaw(text):
    haystack = normalized_search_text(text)
    if not haystack:
        return False
    has_title = (
        "under 18 student visa applicant" in haystack
        and (
            "education provider's confirmation of appropriate accommodation/welfare arrangements" in haystack
            or "education providers confirmation of appropriate accommodation/welfare arrangements" in haystack
            or "confirmation of appropriate accommodation/welfare arrangements" in haystack
            or "accommodation/welfare arrangements" in haystack
        )
    )
    has_coe_code = "coe code" in haystack or "ce code" in haystack
    return (
        has_title
        and has_coe_code
        and "welfare details" in haystack
        and "provider details" in haystack
    )


def text_between_patterns(text, start_pattern, end_pattern):
    source = str(text or "")
    start_match = re.search(start_pattern, source, flags=re.I)
    if not start_match:
        return ""
    start = start_match.start()
    after_start = source[start_match.end():]
    end_match = re.search(end_pattern, after_start, flags=re.I)
    end = start_match.end() + end_match.start() if end_match else len(source)
    return source[start:end].strip()


def section_snippet(section, value="", label=""):
    compact = re.sub(r"\s+", " ", str(section or "")).strip()
    if not compact:
        return ""
    needle = str(value or label or "").strip()
    if needle:
        index = compact.lower().find(needle.lower())
        if index >= 0:
            return compact[max(0, index - 120):index + len(needle) + 180]
    return compact[:420]


def clean_sa_government_caaw_provider(provider):
    compact = re.sub(r"\s+", " ", str(provider or "")).strip(" -:;,.")
    if re.match(r"^Department\s+for\s+Education\b", compact, flags=re.I):
        return "Department for Education"
    return compact


def infer_sa_government_caaw_details(text):
    if not is_sa_government_caaw(text):
        return {}
    welfare_section = text_between_patterns(text, r"\bE\.\s*WELFARE\s+DETAILS\b", r"\bF\.\s*PROVIDER\s+DETAILS\b")
    provider_section = text_between_patterns(text, r"\bF\.\s*PROVIDER\s+DETAILS\b", r"\bG\.\s*INFORMATION\s+FOR\s+EDUCATION\s+PROVIDERS\b|$")
    start = ""
    end = ""
    start_match = re.search(r"\b(?:start|state|stat|star)\s+date\s*[:\-]?\s*(\d{1,2}[/-]\d{1,2}[/-]\d{4})", welfare_section, flags=re.I)
    end_match = re.search(r"(?:\bend|e\s*ds|eds)\s+date\s*[:\-]?\s*(\d{1,2}[/-]\d{1,2}[/-]\d{4})", welfare_section, flags=re.I)
    if start_match:
        start = normalize_offer_date(start_match.group(1))
    if end_match:
        end = normalize_offer_date(end_match.group(1))
    provider = ""
    provider_match = re.search(
        r"\b(?:Provider|Prvoser|Pr\w{1,8}ser)\s+Name\s*[:\-]?\s*([\s\S]*?)(?=\b(?:Provider|Prvoser|Pr\w{1,8}ser)\s+(?:Address|Assre\w*)\s*:?|\bTelephone\s*:|\bEmail\s*:|\bG\.\s*INFORMATION\b|$)",
        provider_section,
        flags=re.I,
    )
    if provider_match:
        provider = re.sub(r"\s+", " ", provider_match.group(1)).strip(" -:;,.")
    provider = clean_sa_government_caaw_provider(provider)
    result = {
        "document_type": "CAAW",
        "provider": provider,
        "caaw_welfare_start_date": start,
        "caaw_welfare_end_date": end,
        "welfare_section": welfare_section,
        "provider_section": provider_section,
    }
    return result


LABEL_VALUE_STOP_PREFIXES = (
    "start date", "state date", "stat date", "end date", "expiry date", "commencement date",
    "course start", "course end", "program start", "program end", "welfare start", "welfare end",
    "date", "details", "name", "number", "no", "level",
)


def value_after_label(line, label, max_length=140):
    raw = (line or "").strip(" \t-:;,.")
    label_text = re.sub(r"\s+", " ", str(label or "")).strip()
    if not raw or not label_text:
        return ""
    match = re.match(rf"^{re.escape(label_text)}\b\s*(?:name)?\s*(?::|-|–|—)?\s*(.*)$", raw, flags=re.I)
    if not match:
        return ""
    candidate = match.group(1).strip(" -:;,.")
    if not candidate:
        return ""
    lower = candidate.lower()
    if any(lower.startswith(prefix) for prefix in LABEL_VALUE_STOP_PREFIXES):
        return ""
    if offer_dates_from_text(candidate) and len(candidate) <= 32:
        return ""
    if 1 <= len(candidate) <= max_length:
        return candidate
    return ""


def labeled_value(lines, labels, max_length=140):
    sorted_labels = sorted(labels, key=len, reverse=True)
    label_pattern = "|".join(re.escape(label) for label in sorted_labels)
    pattern = re.compile(rf"\b(?:{label_pattern})\b\s*(?:name)?\s*[:\-]\s*(.+)", re.I)
    for line in lines:
        match = pattern.search(line)
        if match:
            candidate = match.group(1).strip(" -:;,.")
            if 1 <= len(candidate) <= max_length:
                return candidate
        for label in sorted_labels:
            candidate = value_after_label(line, label, max_length)
            if candidate:
                return candidate
    return ""


def labeled_value_or_next_line(lines, labels, max_length=140):
    value = labeled_value(lines, labels, max_length)
    if value:
        return value
    sorted_labels = sorted(labels, key=len, reverse=True)
    label_pattern = "|".join(re.escape(label) for label in sorted_labels)
    pattern = re.compile(rf"\b(?:{label_pattern})\b\s*(?:name)?\s*$", re.I)
    ignored = re.compile(r"^(?:see school website|details|date|start date|end date)$", re.I)
    for index, line in enumerate(lines):
        if not pattern.search(line.strip(" -:;,")):
            continue
        for candidate in lines[index + 1:index + 4]:
            candidate = candidate.strip(" -:;,.")
            if not candidate or ignored.search(candidate):
                continue
            if 1 <= len(candidate) <= max_length:
                return candidate
    return ""


LETTER_CONFIRMATION_NOTE_RE = re.compile(
    r"\bsee\s+school\s+website\b|\baddress\s+and\s+contact\b|^\(?\s*details\)?$",
    re.I,
)


LETTER_CONFIRMATION_FIELD_RE = re.compile(
    r"^(?:english\s+language\s+centre|english\s+language\s+center|language\s+centre|language\s+center|"
    r"english\s+language\s+program\s+(?:start|state|stat|end)\s+date|language\s+program\s+(?:start|state|stat|end)\s+date|"
    r"year\s+level|host\s+school|host\s+school\s+(?:start|state|stat|end)\s+date|"
    r"main\s+course|main\s+course\s+(?:start|state|stat|end)\s+date|principal\s+course|"
    r"principal\s+course\s+(?:start|state|stat|end)\s+date)$",
    re.I,
)


def clean_letter_confirmation_school_cell(value):
    text = re.sub(r"\s+", " ", str(value or "")).strip(" -:;,.")
    if not text:
        return ""
    text = re.sub(r"\(?\s*see\s+school\s+website\s+for\s+address\s+and\s+contact\s+details\s*\)?", " ", text, flags=re.I)
    text = re.sub(r"\(?\s*see\s+school\s+website\b.*", " ", text, flags=re.I).strip(" -:;,.")
    if not text or LETTER_CONFIRMATION_NOTE_RE.search(text) or LETTER_CONFIRMATION_FIELD_RE.fullmatch(text):
        return ""
    if offer_dates_from_text(text) and len(text) <= 32:
        return ""
    phrase_candidates = school_name_phrase_candidates(text)
    if phrase_candidates:
        return phrase_candidates[-1]
    return text[:160] if 2 <= len(text) <= 160 else ""


def letter_confirmation_school_value(lines, labels, max_length=160):
    sorted_labels = sorted(labels, key=len, reverse=True)
    label_pattern = "|".join(re.escape(label) for label in sorted_labels)
    inline_pattern = re.compile(rf"\b(?:{label_pattern})\b\s*(?:name)?\s*(?::|-|–|—)?\s*(.*)$", re.I)
    standalone_pattern = re.compile(rf"^(?:{label_pattern})\b\s*(?:name)?\s*$", re.I)

    for line in lines:
        clean_line = line.strip(" -:;,.")
        if LETTER_CONFIRMATION_FIELD_RE.fullmatch(clean_line):
            continue
        match = inline_pattern.search(clean_line)
        if not match:
            continue
        candidate = clean_letter_confirmation_school_cell(match.group(1))
        if candidate:
            return candidate[:max_length]

    for index, line in enumerate(lines):
        if not standalone_pattern.search(line.strip(" -:;,")):
            continue
        for candidate_line in lines[index + 1:index + 8]:
            candidate_text = candidate_line.strip(" -:;,.")
            if not candidate_text or LETTER_CONFIRMATION_NOTE_RE.search(candidate_text):
                continue
            if LETTER_CONFIRMATION_FIELD_RE.fullmatch(candidate_text):
                break
            candidate = clean_letter_confirmation_school_cell(candidate_text)
            if candidate:
                return candidate[:max_length]
    return ""


def compact_document_text(value):
    return re.sub(r"\s+", " ", str(value or "")).strip()


def is_sa_gov_letter_of_confirmation(text):
    compact = compact_document_text(text)
    lower = compact.lower()
    if "letter of confirmation" not in lower:
        return False
    has_sa_provider = any(
        keyword in lower
        for keyword in (
            "south australian government schools",
            "government of south australia",
            "department for education",
            "international education services",
        )
    )
    if not has_sa_provider:
        return False
    return bool(re.search(r"\bsection\s*2\b", lower) and re.search(r"\bprogram\s+summary\b", lower))


def sa_gov_program_summary_section(text):
    source = text or ""
    heading_re = re.compile(r"\bSECTION\s*2\b\s*(?:[-–—]\s*)?(?:Program\s+Summary)?\b", re.I)
    fallback = ""
    for match in heading_re.finditer(source):
        section = source[match.end():]
        next_match = re.search(r"\bSECTION\s*[3-9]\b\s*(?:[-–—]\s*)?", section, flags=re.I)
        if next_match:
            section = section[:next_match.start()]
        section = section.strip()
        if not fallback:
            fallback = section
        if re.search(r"\b(?:Primary|High)\s+School\s+Graduate\s+Program\b", section, flags=re.I):
            return section
    return fallback


def sa_program_block_lines(block_text):
    return [re.sub(r"\s+", " ", line).strip() for line in str(block_text or "").splitlines() if re.sub(r"\s+", " ", line).strip()]


def sa_program_block_value(lines, labels, max_length=180):
    value = labeled_value_or_next_line(lines, labels, max_length)
    if value:
        return value
    sorted_labels = sorted(labels, key=len, reverse=True)
    label_pattern = "|".join(re.escape(label) for label in sorted_labels)
    inline = re.compile(rf"\b(?:{label_pattern})\b\s*(?:name)?\s*(?::|-|–|—)?\s*(.+?)(?=\s+\b(?:Year Level|School|Start Date|End Date|Course Name|CRICOS Code|Tuition Fee)\b|$)", re.I)
    text = " ".join(lines)
    match = inline.search(text)
    if match:
        candidate = match.group(1).strip(" -:;,.")
        if 1 <= len(candidate) <= max_length:
            return candidate
    return ""


def sa_program_block_date(lines, label):
    patterns = (rf"\b{re.escape(label)}\b",)
    return date_after_label(lines, patterns) or best_regex_context_date(lines, patterns)


def split_sa_program_blocks(section_text):
    matches = list(re.finditer(r"\b(?:Primary|High)\s+School\s+Graduate\s+Program\b", section_text or "", flags=re.I))
    blocks = []
    for index, match in enumerate(matches):
        end = matches[index + 1].start() if index + 1 < len(matches) else len(section_text or "")
        raw = (section_text or "")[match.start():end].strip()
        if raw:
            blocks.append(raw)
    return blocks


def parse_sa_program_block(block_text):
    lines = sa_program_block_lines(block_text)
    program_match = re.search(r"\b(?:Primary|High)\s+School\s+Graduate\s+Program\b", block_text or "", flags=re.I)
    program_name = re.sub(r"\s+", " ", program_match.group(0)).strip() if program_match else ""
    if re.search(r"\bPrimary\s+School\b", program_name, flags=re.I):
        sector = "primary"
    elif re.search(r"\bHigh\s+School\b", program_name, flags=re.I):
        sector = "secondary"
    else:
        sector = "unknown"
    year_level = sa_program_block_value(lines, ("year level",), 80)
    course_name = sa_program_block_value(lines, ("course name",), 180)
    start_date = sa_program_block_date(lines, "Start Date")
    end_date = sa_program_block_date(lines, "End Date")
    is_language = year_level.strip().upper() == "ISEC" or re.search(r"\bISEC\b", course_name, flags=re.I)
    has_year = bool(re.search(r"\bYear\s*\d{1,2}\b", year_level, flags=re.I))
    block_type = "language" if is_language else "main" if has_year else "unknown"
    return {
        "type": block_type,
        "sector": sector,
        "programName": program_name or "Unknown Program",
        "yearLevel": year_level,
        "school": sa_program_block_value(lines, ("school",), 160),
        "startDate": display_date_value(start_date) if start_date else "",
        "endDate": display_date_value(end_date) if end_date else "",
        "startDateIso": start_date,
        "endDateIso": end_date,
        "courseName": course_name,
        "cricosCode": sa_program_block_value(lines, ("cricos code", "cricos"), 80),
        "tuitionFee": sa_program_block_value(lines, ("tuition fee",), 80),
        "sourcePage": 1,
        "rawText": compact_document_text(block_text),
    }


def merge_sa_year_levels(year_levels):
    numbers = []
    for value in year_levels:
        if re.search(r"\bISEC\b", str(value or ""), flags=re.I):
            continue
        numbers.extend(int(item) for item in re.findall(r"\bYear\s*(\d{1,2})\b", str(value or ""), flags=re.I))
    if not numbers:
        return "", "", []
    start = min(numbers)
    end = max(numbers)
    entry = f"Year {start}"
    full = entry if start == end else f"Year {start} - Year {end}"
    return entry, full, [str(item or "").strip() for item in year_levels if str(item or "").strip()]


def infer_sa_gov_letter_confirmation_details(text):
    section = sa_gov_program_summary_section(text)
    raw_blocks = [parse_sa_program_block(block) for block in split_sa_program_blocks(section)]
    language_blocks = [block for block in raw_blocks if block["type"] == "language"]
    main_blocks = [
        block for block in raw_blocks
        if block["type"] != "language" and re.search(r"\bYear\s*\d{1,2}\b", block.get("yearLevel") or "", flags=re.I)
    ]
    language = language_blocks[0] if language_blocks else {}
    main_schools = [block.get("school") or "" for block in main_blocks if block.get("school")]
    unique_main_schools = []
    for school in main_schools:
        if school not in unique_main_schools:
            unique_main_schools.append(school)
    primary_main_course_school = next((block.get("school") or "" for block in main_blocks if block.get("sector") == "primary" and block.get("school")), "")
    secondary_main_course_school = next((block.get("school") or "" for block in main_blocks if block.get("sector") == "secondary" and block.get("school")), "")
    if len(unique_main_schools) == 1:
        main_course_school = unique_main_schools[0]
    elif primary_main_course_school and secondary_main_course_school:
        main_course_school = " → ".join(unique_main_schools)
    elif len(unique_main_schools) > 1:
        main_course_school = "需人工确认"
    else:
        main_course_school = ""
    main_start_dates = [block.get("startDateIso") for block in main_blocks if block.get("startDateIso")]
    main_end_dates = [block.get("endDateIso") for block in main_blocks if block.get("endDateIso")]
    entry_year, full_year, raw_years = merge_sa_year_levels([block.get("yearLevel") for block in main_blocks])
    return {
        "document_kind": "LetterOfConfirmation",
        "document_type": "SA_GOV_LETTER_OF_CONFIRMATION",
        "letter_language_course_name": language.get("school") or "",
        "letter_language_start_date": language.get("startDateIso") or "",
        "letter_language_end_date": language.get("endDateIso") or "",
        "letter_year_level": full_year,
        "letter_main_course_name": main_course_school,
        "letter_main_start_date": min(main_start_dates) if main_start_dates else "",
        "letter_main_end_date": max(main_end_dates) if main_end_dates else "",
        "main_course_schools": unique_main_schools,
        "primary_main_course_school": primary_main_course_school,
        "secondary_main_course_school": secondary_main_course_school,
        "entry_year_level": entry_year,
        "full_year_level_range": full_year,
        "raw_main_year_levels": raw_years,
        "raw_program_blocks": [
            {key: value for key, value in block.items() if key not in {"startDateIso", "endDateIso"}}
            for block in raw_blocks
        ],
        "program_segments": [
            {
                "program_type": block.get("programName") or "",
                "year_level": block.get("yearLevel") or "",
                "school": block.get("school") or "",
                "start_date": block.get("startDate") or "",
                "end_date": block.get("endDate") or "",
                "course_name": block.get("courseName") or "",
                "cricos_code": block.get("cricosCode") or "",
                "tuition_fee": block.get("tuitionFee") or "",
                "currency": "AUD" if block.get("tuitionFee") else "",
                "is_language_course": block.get("type") == "language",
            }
            for block in raw_blocks
        ],
        "sa_program_summary_text": section,
    }


def valid_oshc_policy_number(value):
    candidate = str(value or "").strip(" -:;,.")
    if not candidate:
        return ""
    if re.search(r"\b(first|given|last|family|surname|name|date|birth|dob|student|provider|policy|membership|member)\b", candidate, flags=re.I):
        return ""
    compact = re.sub(r"[\s-]+", "", candidate)
    digit_count = len(re.findall(r"\d", compact))
    if digit_count >= 5 and re.fullmatch(r"[A-Z0-9]{5,24}", compact, flags=re.I):
        return candidate
    if re.fullmatch(r"[A-Z]{1,6}\d[A-Z0-9]{4,18}", compact, flags=re.I):
        return candidate
    return ""


def labeled_policy_number(lines):
    labels = ("policy number", "policy no", "membership number", "member number", "member no")
    value = valid_oshc_policy_number(labeled_value(lines, labels, 80))
    if value:
        return value
    sorted_labels = sorted(labels, key=len, reverse=True)
    label_pattern = "|".join(re.escape(label) for label in sorted_labels)
    standalone_label = re.compile(rf"\b(?:{label_pattern})\b\s*(?:name)?\s*$", re.I)
    for index, line in enumerate(lines):
        if standalone_label.search(line.strip(" -:;,.")):
            for candidate in lines[index + 1:index + 7]:
                value = valid_oshc_policy_number(candidate)
                if value:
                    return value
    for line in lines:
        if re.search(r"\b(policy|membership|member)\b", line, flags=re.I):
            match = re.search(r"\b[A-Z]{1,6}[- ]?\d[A-Z0-9-]{4,}\b", line, flags=re.I)
            if match:
                value = valid_oshc_policy_number(match.group(0))
                if value:
                    return value
    return ""


def iso_date_value(value):
    try:
        return date.fromisoformat(str(value or "")[:10])
    except ValueError:
        return None


def plausible_oshc_start_date(value, expiry=""):
    start = iso_date_value(value)
    if not start:
        return False
    end = iso_date_value(expiry)
    if end:
        if start > end:
            return False
        if (end - start).days > 365 * 8:
            return False
        return True
    return start.year >= 2018


def best_oshc_start_date(lines, expiry_date=""):
    specific_keywords = ("cover start", "policy start", "oshc start", "valid from", "from date", "start date")
    general_keywords = ("commencement date",)
    for keywords in (specific_keywords, general_keywords):
        for index, line in enumerate(lines):
            lower = line.lower()
            if not any(keyword in lower for keyword in keywords):
                continue
            for candidate_line in lines[index:index + 3]:
                if re.search(r"\b(date of birth|birth date|dob)\b", candidate_line, flags=re.I):
                    continue
                for _pos, candidate_date in offer_dates_from_text(candidate_line):
                    if plausible_oshc_start_date(candidate_date, expiry_date):
                        return candidate_date
    return ""


def fallback_oshc_start_date(all_dates, expiry_date=""):
    for _pos, candidate_date in all_dates:
        if candidate_date == expiry_date:
            continue
        if plausible_oshc_start_date(candidate_date, expiry_date):
            return candidate_date
    return ""


MEDIBANK_OSHC_LABELS = [
    ("your_cover", re.compile(r"^your\s+cover\s*:?\s*$", re.I)),
    ("membership_number", re.compile(r"^membership\s+number\s*:?\s*$", re.I)),
    ("first_name", re.compile(r"^first\s+name\s*:?\s*$", re.I)),
    ("last_name", re.compile(r"^last\s+name\s*:?\s*$", re.I)),
    ("date_of_birth", re.compile(r"^date\s+of\s+birth\s*:?\s*$", re.I)),
    ("scale", re.compile(r"^scale\s*:?\s*$", re.I)),
    ("start_date", re.compile(r"^start\s+date\s*:?\s*$", re.I)),
    ("valid_to", re.compile(r"^valid\s+to\s*:?\s*$", re.I)),
    ("passport_no", re.compile(r"^passport\s+no\s*:?\s*$", re.I)),
    ("dependants", re.compile(r"^dependants\s*:?\s*$", re.I)),
]


def is_medibank_oshc_policy_certificate(text):
    haystack = normalized_search_text(text)
    return (
        "medibank" in haystack
        and "oshc" in haystack
        and "your details" in haystack
        and "membership number" in haystack
        and "start date" in haystack
        and "valid to" in haystack
    )


def medibank_oshc_field_snippet(section, label, value):
    compact = re.sub(r"\s+", " ", str(section or "")).strip()
    if not compact:
        return ""
    label_pos = compact.lower().find(str(label or "").lower())
    value_pos = compact.lower().find(str(value or "").lower()) if value else -1
    if label_pos >= 0 and value_pos >= 0 and abs(value_pos - label_pos) > 260:
        return (
            compact[max(0, label_pos - 40):label_pos + 180]
            + " ... "
            + compact[max(0, value_pos - 80):value_pos + len(str(value)) + 120]
        )
    if label_pos >= 0:
        return compact[max(0, label_pos - 80):label_pos + 260]
    if value_pos >= 0:
        return compact[max(0, value_pos - 120):value_pos + len(str(value)) + 160]
    return compact[:420]


def medibank_direct_field(section, label_pattern, value_pattern):
    match = re.search(rf"\b{label_pattern}\s*:\s*({value_pattern})", section, flags=re.I)
    return match.group(1).strip() if match else ""


def medibank_ordered_values(lines):
    normalized = [re.sub(r"\s+", " ", line).strip() for line in lines if line.strip()]
    labels = []
    for index, line in enumerate(normalized):
        if len(labels) == len(MEDIBANK_OSHC_LABELS):
            break
        key = MEDIBANK_OSHC_LABELS[len(labels)][0]
        label = r"\s+".join(key.split("_"))
        match = re.match(rf"^{label}\b\s*:?\s*(.*)$", line, re.I)
        if match:
            labels.append((key, index, match.group(1).strip()))
    if len(labels) != len(MEDIBANK_OSHC_LABELS):
        return {}
    values = {}
    for pos, (key, index, inline) in enumerate(labels):
        if inline:
            values[key] = inline
        elif pos + 1 < len(labels) and labels[pos + 1][1] == index + 2:
            # A single value between successive labels is unambiguous.
            values[key] = normalized[index + 1]
    tail = normalized[labels[-1][1] + 1:]
    if "your_cover" not in values:
        cover = next((i for i, line in enumerate(tail)
                      if len(line) <= 80 and re.search(r"\bMedibank\b.*\bOSHC\b", line, re.I)
                      and not re.search(r"\b(policy|premium|subject|email|phone|web|gpo|privacy|benefits)\b", line, re.I)), None)
        if cover is None:
            return {}
        tail = tail[cover:]
    required = [key for key, _ in MEDIBANK_OSHC_LABELS[:8]]
    missing = [key for key in required if key not in values]
    if len(tail) < len(missing):
        return {}
    values.update(zip(missing, tail[:len(missing)]))
    # Optional empty Passport No/Dependants must not shift earlier fields.
    # Typed anchors reject ambiguous columns rather than using DOB as cover.
    if (not valid_oshc_policy_number(values.get("membership_number"))
            or not normalize_offer_date(values.get("date_of_birth"))
            or not normalize_offer_date(values.get("start_date"))
            or not normalize_offer_date(values.get("valid_to"))):
        return {}
    return {key: values[key] for key in required}


def infer_medibank_oshc_details(text):
    if not is_medibank_oshc_policy_certificate(text):
        return {}
    lines = [re.sub(r"\s+", " ", line).strip() for line in str(text or "").splitlines()]
    lines = [line for line in lines if line]
    section = text_between_patterns(text, r"\bYour\s+Details\b", r"\Z") or str(text or "")
    ordered = medibank_ordered_values(lines)
    membership = (
        medibank_direct_field(section, r"Membership\s+Number", r"\d{6,12}")
        or valid_oshc_policy_number(ordered.get("membership_number"))
    )
    start = (
        normalize_offer_date(medibank_direct_field(section, r"Start\s+date", r"\d{1,2}[/-]\d{1,2}[/-]\d{4}"))
        or normalize_offer_date(ordered.get("start_date"))
    )
    end = (
        normalize_offer_date(medibank_direct_field(section, r"Valid\s+to", r"\d{1,2}[/-]\d{1,2}[/-]\d{4}"))
        or normalize_offer_date(ordered.get("valid_to"))
    )
    return {
        "document_type": "OSHC",
        "oshc_company_name": "Medibank",
        "oshc_policy_number": membership,
        "oshc_commencement_date": start,
        "oshc_expiry_date": end,
        "details_section": section,
    }


def is_nib_oshc_confirmation(text):
    haystack = normalized_search_text(text)
    return (
        bool(re.search(r"\bnib\b", haystack))
        and "confirmation of health cover" in haystack
        and "policy information" in haystack
        and "policy number" in haystack
        and "cover details" in haystack
        and "policy start date" in haystack
        and "policy end date" in haystack
    )


def nib_policy_number_from_section(section):
    policy_section = str(section or "")
    match = re.search(r"\bPolicy\s+number\b\s*([A-Za-z]*\s*\d[\d\s-]{5,20})", policy_section, flags=re.I)
    if not match:
        match = re.search(r"\bPolicy\s+number\s*([0-9]{6,12})", policy_section, flags=re.I)
    if not match:
        for line in policy_section.splitlines():
            if re.fullmatch(r"\s*[0-9]{6,12}\s*", line):
                return re.sub(r"\D+", "", line)
        return ""
    digits = re.sub(r"\D+", "", match.group(1))
    return digits if 6 <= len(digits) <= 12 else ""


def nib_date_after_label(section, label):
    pattern = rf"\b{re.escape(label)}\b\s*(\d{{1,2}}[/-]\d{{1,2}}[/-]\d{{4}})"
    match = re.search(pattern, section or "", flags=re.I)
    return normalize_offer_date(match.group(1)) if match else ""


def infer_nib_oshc_details(text):
    if not is_nib_oshc_confirmation(text):
        return {}
    policy_section = text_between_patterns(text, r"\bPolicy\s+Information\b", r"\bCover\s+Details\b")
    cover_section = text_between_patterns(text, r"\bCover\s+Details\b", r"\bPayment\s+and\s+Duration\s+of\s+Cover\b|\bPeople\s+Covered\b|$")
    dates = [value for _pos, value in offer_dates_from_text(cover_section)]
    start = nib_date_after_label(cover_section, "Policy start date") or (dates[0] if dates else "")
    end = nib_date_after_label(cover_section, "Policy end date") or (dates[1] if len(dates) > 1 else "")
    return {
        "document_type": "OSHC",
        "oshc_company_name": "NIB",
        "oshc_policy_number": nib_policy_number_from_section(policy_section),
        "oshc_commencement_date": start,
        "oshc_expiry_date": end,
        "policy_section": policy_section,
        "cover_section": cover_section,
    }


def receipt_amount(lines):
    pattern = re.compile(r"(AUD|A\$|\$)\s*([0-9][0-9,]*(?:\.\d{1,2})?)|([0-9][0-9,]*(?:\.\d{1,2})?)\s*(AUD|AUD\$)", re.I)
    for line in lines:
        if re.search(r"\b(receipt|paid|payment|amount|total)\b", line, flags=re.I):
            match = pattern.search(line)
            if match:
                currency = match.group(1) or match.group(4) or "AUD"
                amount = match.group(2) or match.group(3)
                return f"{currency} {amount}".replace("A$", "AUD")
    return ""


def pdf_text_layer_is_usable(text):
    sample = str(text or "").strip()
    if not sample:
        return False
    sample = sample[:5000]
    words = re.findall(r"[A-Za-z]{3,}", sample)
    slash_code_tokens = re.findall(r"/i?\d+", sample)
    control_chars = sum(
        1 for char in sample
        if (ord(char) < 32 and char not in "\n\r\t") or ord(char) in {0xFFFE, 0xFFFF}
    )
    if len(sample) < 80:
        return bool(words)
    if len(slash_code_tokens) >= 12 and len(slash_code_tokens) > len(words):
        return False
    if control_chars > max(8, len(sample) * 0.02):
        return False
    alpha_count = sum(1 for char in sample if "a" <= char.lower() <= "z")
    if alpha_count / max(1, len(sample)) < 0.08 and len(words) < 10:
        return False
    return len(words) >= 6


