def decode_pdf_numeric_glyph_text_with_map(text, glyph_map):
    source = str(text or "")
    if len(re.findall(r"/(?:i255|\d+)", source)) < 12:
        return source

    def replace_token(match):
        return glyph_map.get(match.group(1), "")

    decoded = re.sub(r"/(i255|\d+)", replace_token, source)
    decoded = re.sub(r"[ \t]{2,}", " ", decoded)
    decoded = re.sub(r" *\n *", "\n", decoded)
    return decoded.strip()


def sa_caaw_numeric_pdf_variant_is_better(decoded):
    haystack = normalized_search_text(decoded)
    return (
        "welfare details" in haystack
        and "nominated welfare period" in haystack
        and "start date" in haystack
        and "end date" in haystack
        and "provider details" in haystack
        and "provider name" in haystack
        and "department for education" in haystack
    )


def decode_pdf_numeric_glyph_text(text):
    source = str(text or "")
    decoded = decode_pdf_numeric_glyph_text_with_map(source, PDF_NUMERIC_GLYPH_MAP)
    sa_decoded = decode_pdf_numeric_glyph_text_with_map(source, SA_CAAW_NUMERIC_GLYPH_MAP)
    sa_decoded = re.sub(r"\bDepartmen\s+for\s+Education\b", "Department for Education", sa_decoded)
    sa_decoded = re.sub(r"(\d{4})E\s+nd\s+Date", r"\1 End Date", sa_decoded)
    if sa_caaw_numeric_pdf_variant_is_better(sa_decoded):
        return sa_decoded
    return decoded


def mark_upload_text_extraction(upload, text, source="", ocr_fallback_used=False):
    try:
        setattr(upload, "_extracted_text_cache", text)
        setattr(upload, "_text_extraction_meta", {
            "source": source,
            "extracted_text_available": bool(str(text or "").strip()),
            "ocr_fallback_used": bool(ocr_fallback_used),
        })
    except Exception:
        pass
    return text


def upload_text_extraction_meta(upload):
    meta = getattr(upload, "_text_extraction_meta", None)
    return meta if isinstance(meta, dict) else {}


def extract_uploaded_text(upload):
    if hasattr(upload, "_extracted_text_cache"):
        return upload._extracted_text_cache
    suffix = Path(upload.filename or "").suffix.lower()
    # Explicit text uploads can retain a PDF-looking original filename. Keep
    # that supported path without treating real PDF bytes as plain text.
    if str(upload.content_type or "").startswith("text/") and not upload.data.lstrip().startswith(b"%PDF-"):
        for encoding in ("utf-8", "utf-16", "latin-1"):
            try:
                return mark_upload_text_extraction(upload, upload.data.decode(encoding), f"text_{encoding}", False)
            except UnicodeDecodeError:
                pass
    if suffix == ".pdf":
        try:
            from pypdf import PdfReader

            reader = PdfReader(io.BytesIO(upload.data))
            text = "\n".join(page.extract_text() or "" for page in reader.pages[:8])
            if pdf_text_layer_is_usable(text):
                return mark_upload_text_extraction(upload, text, "pdf_text_layer", False)
            decoded_text = decode_pdf_numeric_glyph_text(text)
            if pdf_text_layer_is_usable(decoded_text):
                return mark_upload_text_extraction(upload, decoded_text, "pdf_text_layer_decoded", False)
        except Exception:
            pass
        diagnostics = {}
        ocr_text = ocr_pdf_text(upload.data, diagnostics=diagnostics)
        result = mark_upload_text_extraction(upload, ocr_text, "pdf_ocr", True)
        upload_text_extraction_meta(upload).update({"ocr_status": diagnostics.get("status", "no_text"), **{k: v for k, v in diagnostics.items() if k != "status"}})
        return result
    if suffix in {".jpg", ".jpeg", ".png", ".webp", ".heic", ".tif", ".tiff"} or str(upload.content_type or "").startswith("image/"):
        diagnostics = {}
        ocr_text = ocr_image_text(upload.data, suffix, diagnostics=diagnostics)
        result = mark_upload_text_extraction(upload, ocr_text, "image_ocr", True)
        upload_text_extraction_meta(upload).update({"ocr_status": diagnostics.get("status", "no_text")})
        return result
    if suffix == ".docx":
        try:
            with zipfile.ZipFile(io.BytesIO(upload.data)) as archive:
                xml = archive.read("word/document.xml")
            root = ET.fromstring(xml)
            ns = {"w": "http://schemas.openxmlformats.org/wordprocessingml/2006/main"}
            text = "\n".join("".join(t.text or "" for t in paragraph.findall(".//w:t", ns)) for paragraph in root.findall(".//w:p", ns))
            return mark_upload_text_extraction(upload, text, "docx_text", False)
        except Exception:
            return mark_upload_text_extraction(upload, "", "docx_text", False)
    if suffix in {".txt", ".csv"} or str(upload.content_type or "").startswith("text/"):
        for encoding in ("utf-8", "utf-16", "latin-1"):
            try:
                return mark_upload_text_extraction(upload, upload.data.decode(encoding), f"text_{encoding}", False)
            except UnicodeDecodeError:
                pass
    if suffix in {".xlsx", ".xlsm"}:
        try:
            wb = load_workbook(io.BytesIO(upload.data), data_only=True, read_only=True)
            chunks = []
            for ws in wb.worksheets[:5]:
                chunks.append(f"Sheet: {ws.title}")
                for row in ws.iter_rows(max_row=120, values_only=True):
                    values = [str(cell).strip() for cell in row if cell is not None and str(cell).strip()]
                    if values:
                        chunks.append(" | ".join(values))
            return mark_upload_text_extraction(upload, "\n".join(chunks), "spreadsheet_text", False)
        except Exception:
            return mark_upload_text_extraction(upload, "", "spreadsheet_text", False)
    return mark_upload_text_extraction(upload, "", "", False)


def extract_school_feature_matches_from_upload(upload, source_reference="", tags=None):
    source_title = Path(upload.filename or "Uploaded file").name
    text = extract_uploaded_text(upload)
    result = {
        "status": "empty",
        "source_title": source_title,
        "source_reference": source_reference or source_title,
        "source_type": "Uploaded File",
        "text_length": len(text or ""),
        "features": [],
    }
    if not (text or "").strip():
        return result
    tag_definitions = normalize_school_feature_tags(tags)
    matches = match_school_feature_tags_from_text(
        text,
        tag_definitions,
        source_reference or source_title,
        "Uploaded File",
        source_title=source_title,
    )
    features = merge_school_feature_matches(matches)
    for feature in features:
        feature["review_status"] = "Suggested"
        feature["source_title"] = source_title
        feature["source_reference"] = source_reference or source_title
        feature["source_type"] = "Uploaded File"
    result["features"] = features
    result["status"] = "matched" if features else "no_feature"
    return result


