def school_name_phrase_candidates(value):
    text = re.sub(r"\s+", " ", str(value or "")).strip(" -:;,.")
    if not text:
        return []
    school_phrase = re.compile(
        r"\b(?:(?:[A-Z][A-Za-z'&.\-]*|[A-Z]{2,})(?:\s+|$)|(?:of|and|the|&)\s+){0,8}"
        r"(?:High\s+School|Primary\s+School|Grammar(?:\s+School)?|School|College|Academy|Institute|University|TAFE)\b"
    )
    bad_words = re.compile(
        r"\b(offer|application|admission|student|invoice|deposit|tuition|condition|accept|letter|welcome|welcoming|forward)\b",
        re.I,
    )
    candidates = []
    for match in school_phrase.finditer(text):
        candidate = match.group(0).strip(" -:;,.")
        prep_match = re.search(r"\b(?:to|at|from|for)\s+(.+)$", candidate, flags=re.I)
        if prep_match:
            candidate = prep_match.group(1).strip(" -:;,.")
        if len(candidate.split()) < 2:
            continue
        if not (3 <= len(candidate) <= 90):
            continue
        if bad_words.search(candidate):
            continue
        candidates.append(candidate)
    return candidates


def infer_school_name(lines, filename=""):
    label_pattern = re.compile(r"\b(?:school|college|institution|provider|campus)\s*(?:name)?\s*[:\-]\s*(.+)", re.I)
    school_words = re.compile(r"\b(School|College|Grammar|Academy|Institute|University|TAFE|High School|Primary School)\b", re.I)
    bad_words = re.compile(
        r"\b(offer|application|admission|student|invoice|deposit|tuition|condition|accept|letter|studies|preparatory|year\s*\d)\b",
        re.I,
    )
    standalone_label = re.compile(r"^(?:school|school name|college|college name|institution|institution name|provider|provider name|campus|campus name)$", re.I)
    for line in lines[:60]:
        match = label_pattern.search(line)
        if match:
            candidate = match.group(1).strip(" -:;,.")
            phrase_candidates = school_name_phrase_candidates(candidate)
            if phrase_candidates:
                return phrase_candidates[-1]
            if 3 <= len(candidate) <= 90 and not standalone_label.fullmatch(candidate) and not bad_words.search(candidate):
                return candidate
    labeled_candidate = labeled_value_or_next_line(
        lines[:80],
        ("school name", "school", "college name", "college", "institution name", "institution", "provider name", "provider", "campus name", "campus"),
        90,
    )
    if labeled_candidate:
        phrase_candidates = school_name_phrase_candidates(labeled_candidate)
        if phrase_candidates:
            return phrase_candidates[-1]
        candidate = labeled_candidate.strip(" -:;,.")
        if 3 <= len(candidate) <= 90 and school_words.search(candidate) and not standalone_label.fullmatch(candidate) and not bad_words.search(candidate):
            return candidate
    for line in lines[:80]:
        candidate = line.strip(" -:;,.")
        if standalone_label.fullmatch(candidate) or bad_words.search(candidate):
            continue
        phrase_candidates = school_name_phrase_candidates(candidate)
        if phrase_candidates:
            return phrase_candidates[-1]
        if 3 <= len(candidate) <= 90 and school_words.search(candidate) and not bad_words.search(candidate):
            return candidate
    stem = re.sub(r"[_-]+", " ", Path(filename or "").stem).strip()
    if school_words.search(stem):
        return stem[:90]
    return ""


def infer_offer_deposit(lines):
    amount_pattern = re.compile(r"(AUD|A\$|\$)\s*\$?\s*([0-9][0-9,]*(?:\.\d{1,2})?)|([0-9][0-9,]*(?:\.\d{1,2})?)\s*(AUD|AUD\$)", re.I)
    context = (
        "deposit", "acceptance fee", "acceptance payment", "initial payment",
        "initial fee", "initial fees", "fees due", "enrolment fee", "enrollment fee",
        "confirm your place", "deposit amount", "amount payable", "amount to pay",
        "payment required", "fees payable", "due now",
    )
    for line in lines:
        lower = line.lower()
        if not any(word in lower for word in context):
            continue
        match = amount_pattern.search(line)
        if not match:
            continue
        currency = match.group(1) or match.group(4) or "AUD"
        amount = match.group(2) or match.group(3)
        try:
            return float(amount.replace(",", "")), "AUD" if "$" in currency or currency.upper().startswith("AUD") else currency.upper()
        except ValueError:
            return None, ""
    return None, ""


def is_sa_gov_offer_tax_invoice(text):
    lower = compact_document_text(text).lower()
    if "south australian government schools" not in lower:
        return False
    if "letter of offer / tax invoice" not in lower and "letter of offer" not in lower:
        return False
    return bool(re.search(r"\bsection\s*2\b", lower) and "payment details" in lower and "tax invoice" in lower)


def sa_gov_offer_payment_section(text):
    source = text or ""
    heading_re = re.compile(r"\bSECTION\s*2\b\s*(?:[-–—]\s*)?Payment\s+Details\s*/\s*Tax\s+Invoice\b", re.I)
    fallback = ""
    for match in heading_re.finditer(source):
        section = source[match.end():]
        next_match = re.search(r"\bSECTION\s*[3-9]\b\s*(?:[-–—]\s*)?", section, flags=re.I)
        if next_match:
            section = section[:next_match.start()]
        section = section.strip()
        if not fallback:
            fallback = section
        if re.search(r"\bTOTAL\b", section, flags=re.I):
            return section
    return fallback or source


def normalized_money_float(value):
    match = re.search(r"[0-9][0-9,]*(?:\.\d{1,2})?", str(value or ""))
    if not match:
        return None
    try:
        return float(match.group(0).replace(",", ""))
    except ValueError:
        return None


def sa_gov_offer_total_deposit(text):
    section = sa_gov_offer_payment_section(text)
    money_re = re.compile(r"\$?\s*[0-9]{1,3}(?:,[0-9]{3})*\.\d{2}")
    best_snippet = ""
    for match in re.finditer(r"\bTOTAL\b", section or "", flags=re.I):
        snippet = section[match.start():match.start() + 380]
        if not re.search(r"Total\s+amount\s+inc\s+GST|required\s+to\s+be\s+paid", snippet, flags=re.I):
            continue
        amounts = money_re.findall(snippet)
        if amounts:
            amount = normalized_money_float(amounts[-1])
            if amount is not None:
                return amount, "AUD", compact_document_text(snippet)
        best_snippet = snippet
    if best_snippet:
        amounts = money_re.findall(best_snippet)
        if amounts:
            amount = normalized_money_float(amounts[-1])
            if amount is not None:
                return amount, "AUD", compact_document_text(best_snippet)
    return None, "", ""


def offer_pdf_page_texts(upload):
    if Path(upload.filename or "").suffix.lower() != ".pdf":
        return []
    try:
        from pypdf import PdfReader

        reader = PdfReader(io.BytesIO(upload.data))
        return [page.extract_text() or "" for page in reader.pages[:12]]
    except Exception:
        return []


def is_nsw_public_offer(text, filename=""):
    compact = compact_document_text(f"{filename or ''}\n{text or ''}")
    lower = compact.lower()
    has_provider = any(
        keyword in lower
        for keyword in (
            "nsw department of education",
            "nsw government schools",
            "de international",
            "cricos provider code: 00588m",
        )
    )
    return bool(has_provider and "course details" in lower and "program name" in lower)


def nsw_offer_amount_value(value):
    match = re.search(r"(AUD|A\$|\$)?\s*\$?\s*([0-9][0-9,]*(?:\.\d{1,2})?)|([0-9][0-9,]*(?:\.\d{1,2})?)\s*(AUD|AUD\$)", str(value or ""), flags=re.I)
    if not match:
        return None, ""
    amount = match.group(2) or match.group(3)
    currency = match.group(1) or match.group(4) or ""
    try:
        return float(amount.replace(",", "")), "AUD" if "$" in currency or currency.upper().startswith("AUD") else currency.upper()
    except ValueError:
        return None, ""


def nsw_offer_school_match(candidate):
    candidate = re.sub(r"\s+", " ", str(candidate or "")).strip(" -:;,.")
    if not candidate:
        return "", 0.0, "Unmatched"
    normalized = re.sub(r"[^a-z0-9]+", "", candidate.lower())
    if not normalized:
        return "", 0.0, "Unmatched"
    try:
        schools = db.all("SELECT school_name FROM schools WHERE UPPER(COALESCE(state,''))='NSW' AND deleted_at IS NULL")
    except Exception:
        schools = []
    if not schools:
        return candidate, 1.0, "Extracted"
    best_name = ""
    best_score = 0.0
    for school in schools:
        school_name = school["school_name"]
        school_key = re.sub(r"[^a-z0-9]+", "", str(school_name or "").lower())
        if not school_key:
            continue
        if school_key == normalized:
            return school_name, 1.0, "Matched"
        score = SequenceMatcher(None, normalized, school_key).ratio()
        if normalized in school_key or school_key in normalized:
            score = max(score, 0.92)
        if score > best_score:
            best_name = school_name
            best_score = score
    if best_score >= 0.96:
        return best_name, round(best_score, 3), "Matched"
    return "", round(best_score, 3), "Needs Review"


def nsw_offer_school_name(text):
    section = nsw_coe_cover_letter_course_section(text)
    blocks = split_nsw_coe_cover_letter_program_blocks(section)
    main_schools = []
    for block in blocks:
        if block.get("type") == "language":
            continue
        school = block.get("school") or ""
        if school and school not in main_schools:
            main_schools.append(school)
    if not main_schools:
        for block in blocks:
            school = block.get("school") or ""
            if school and school not in main_schools:
                main_schools.append(school)
    if len(main_schools) != 1:
        return "", 0.0, "Needs Review"
    return nsw_offer_school_match(main_schools[0])


def nsw_offer_page_texts(upload, text):
    pages = offer_pdf_page_texts(upload)
    if pages:
        return pages
    parts = re.split(r"(?=\bSCHEDULE\s+OF\s+FEES\b)", text or "", maxsplit=1, flags=re.I)
    if len(parts) == 2:
        return [parts[0], parts[1]]
    return [text or ""]


def nsw_offer_schedule_page_index(pages):
    for index, page_text in enumerate(pages):
        if re.search(r"\bSCHEDULE\s+OF\s+FEES\b", page_text or "", flags=re.I):
            return index
    return -1


def nsw_offer_expiry_date(lines):
    return (
        date_after_label(lines, (r"\bthis\s+offer\s+expires\s+on\b", r"\boffer\s+expires\s+on\b", r"\boffer\s+expiry\s+date\b"), allow_negative_anchor=True)
        or best_context_date(lines, ("this offer expires", "offer expires", "offer expiry"), allow_negative_anchor=True)
    )


def nsw_offer_letter_date(pages):
    schedule_index = nsw_offer_schedule_page_index(pages)
    candidate_indexes = []
    if schedule_index > 0:
        candidate_indexes.extend(range(max(0, schedule_index - 3), schedule_index))
    else:
        candidate_indexes.extend(range(min(len(pages), 4)))
    seen = set()
    for index in candidate_indexes:
        if index in seen or index >= len(pages):
            continue
        seen.add(index)
        page_text = pages[index] or ""
        lines = [re.sub(r"\s+", " ", line).strip() for line in page_text.splitlines()]
        lines = [line for line in lines if line]
        labeled = (
            date_after_label(lines, (r"\boffer\s+date\b", r"\bletter\s+date\b", r"\bissue\s+date\b", r"\bdate\s+of\s+issue\b"), allow_negative_anchor=True)
            or best_context_date(lines, ("offer date", "letter date", "issue date", "date of issue", "offer issued date"), allow_negative_anchor=True)
        )
        if labeled:
            return labeled
    if schedule_index > 0:
        search_indexes = list(range(max(0, schedule_index - 3), schedule_index))
    else:
        search_indexes = list(range(min(len(pages), 4)))
    for index in reversed(search_indexes):
        page_text = pages[index] or ""
        if re.search(r"\bSCHEDULE\s+OF\s+FEES\b", page_text, flags=re.I):
            continue
        lines = [re.sub(r"\s+", " ", line).strip() for line in page_text.splitlines()]
        lines = [line for line in lines if line]
        for line in reversed(lines):
            if re.search(r"\b(expir|start|finish|end|payment|payable|due|birth|dob|course|tuition|fee)\b", line, flags=re.I):
                continue
            dates = offer_dates_from_text(line)
            if dates:
                return dates[0][1]
    return ""


def nsw_offer_deposit_from_schedule(pages):
    schedule_index = nsw_offer_schedule_page_index(pages)
    indexes = [schedule_index] if schedule_index >= 0 else []
    indexes.extend(index for index, page in enumerate(pages) if index != schedule_index and re.search(r"\b(deposit|amount payable|payment required|initial payment|due now)\b", page or "", flags=re.I))
    for index in indexes:
        page_text = pages[index] or ""
        lines = [re.sub(r"\s+", " ", line).strip() for line in page_text.splitlines()]
        lines = [line for line in lines if line]
        for line in lines:
            if re.search(r"\b(deposit|deposit amount|payment required|initial payment|due now)\b", line, flags=re.I):
                amount, currency = nsw_offer_amount_value(line)
                if amount is not None:
                    return amount, currency or ("AUD" if re.search(r"\bAUD\b|\$", page_text, flags=re.I) else "")
        if index == schedule_index:
            total_lines = [line for line in lines if re.search(r"^Total\b", line, flags=re.I)]
            for line in reversed(total_lines):
                amounts = re.findall(r"\$?\s*[0-9][0-9,]*(?:\.\d{1,2})?", line)
                parsed = [nsw_offer_amount_value(item)[0] for item in amounts]
                parsed = [item for item in parsed if item is not None]
                if parsed:
                    return parsed[-1], "AUD" if re.search(r"\bAUD\b|\$", page_text, flags=re.I) else ""
    return None, ""


def infer_nsw_public_offer_details(upload, text, lines):
    pages = nsw_offer_page_texts(upload, text)
    school_name, school_score, school_status = nsw_offer_school_name(text)
    offer_date = nsw_offer_letter_date(pages)
    offer_expiry_date = nsw_offer_expiry_date(lines)
    deposit_amount, deposit_currency = nsw_offer_deposit_from_schedule(pages)
    field_confidence = {}
    if school_name:
        field_confidence["school_name"] = "explicit" if school_status in {"Matched", "Extracted"} and school_score >= 0.96 else "uncertain"
    if offer_date:
        field_confidence["offer_date"] = "explicit"
    if offer_expiry_date:
        field_confidence["offer_expiry_date"] = "explicit"
    if deposit_amount is not None:
        field_confidence["deposit_amount"] = "explicit"
    if deposit_currency:
        field_confidence["deposit_currency"] = "explicit"
    return {
        "school_name": school_name,
        "offer_date": offer_date,
        "offer_expiry_date": offer_expiry_date,
        "deposit_amount": deposit_amount,
        "deposit_currency": deposit_currency,
        "document_type": "NSW_PUBLIC_SCHOOL_OFFER",
        "school_match_status": school_status,
        "school_match_score": school_score,
        "_field_confidence": field_confidence,
    }


def offer_course_details_schools(text):
    """Prefer explicit Course Details cells over incidental earlier school names."""
    section = text_between_patterns(
        text, r"\bCourse\s+Details\b",
        r"\b(?:Accommodation\s+and\s+Welfare|Conditions\s*/\s*Pre-requisites)\b|\Z",
    )
    if not section:
        return {}
    result = {}
    for field, label in (("school_name", r"School"),
                         ("language_school_name", r"English\s+Language\s+Cent(?:re|er)")):
        match = re.search(rf"(?:^|\n)[ \t]*{label}[ \t]*:[ ]*([^\n]*(?:\n[^\n]*){{0,8}})", section, re.I)
        if not match:
            continue
        value = ""
        for line in match.group(1).splitlines():
            candidate = line.strip()
            if not candidate:
                continue
            if re.match(r"(?:School|English\s+Language\s+Cent(?:re|er)|Address|Year\s+Level)\s*:", candidate, re.I):
                break
            phrases = school_name_phrase_candidates(candidate)
            if phrases:
                value = phrases[0]
                break
        result[field] = value
    return result


def infer_offer_details(upload):
    text = extract_uploaded_text(upload)
    lines = [re.sub(r"\s+", " ", line).strip() for line in text.splitlines()]
    lines = [line for line in lines if line]
    course_start_date = date_after_label(
        lines,
        (
            r"\bcourse\s+commencement\s+date\b",
            r"\bcourse\s+start\s+date\b",
            r"\bcommencement\s+date\b",
            r"\bprogram\s+start\s+date\b",
        ),
        allow_negative_anchor=True,
    )
    if is_nsw_public_offer(text, upload.filename):
        details = infer_nsw_public_offer_details(upload, text, lines)
        details["course_start_date"] = course_start_date
        if course_start_date:
            details.setdefault("_field_confidence", {})["course_start_date"] = "explicit"
        details["extracted_text_found"] = bool(text.strip())
        return details
    sa_offer = is_sa_gov_offer_tax_invoice(text)
    sa_deposit_amount, sa_deposit_currency, sa_deposit_snippet = sa_gov_offer_total_deposit(text) if sa_offer else (None, "", "")
    deposit_amount, deposit_currency = infer_offer_deposit(lines)
    if sa_deposit_amount is not None:
        deposit_amount = sa_deposit_amount
        deposit_currency = sa_deposit_currency or "AUD"
    all_dates = offer_dates_from_text(text)
    offer_date = (
        date_after_label(lines, (r"\boffer\s+date\b", r"\bdate\s+of\s+offer\b"), allow_negative_anchor=True)
        or best_context_date(lines, ("offer date", "date of offer", "letter date"))
        or best_context_date(lines, ("date of issue", "issued"), allow_negative_anchor=True)
        or (all_dates[0][1] if all_dates else "")
    )
    offer_expiry_date = (
        date_after_label(lines, (
            r"\boffer\s+due\s+date\b", r"\baccept\s+by\b", r"\bacceptance\s+due\b",
            r"\bexpiry\b", r"\bexpires\b", r"\bvalid\s+until\b", r"\bdeadline\b",
            r"\bdue\s+date\b", r"\bmust\s+accept\b",
        ), allow_negative_anchor=True)
        or best_context_date(lines, ("accept by", "acceptance due", "offer due date", "expiry", "expires", "valid until", "deadline", "due date", "must accept"), allow_negative_anchor=True)
    )
    course_schools = offer_course_details_schools(text)
    details = {
        "school_name": course_schools.get("school_name", infer_school_name(lines, upload.filename)),
        "language_school_name": course_schools.get("language_school_name", ""),
        "offer_date": offer_date,
        "course_start_date": course_start_date,
        "offer_expiry_date": offer_expiry_date,
        "deposit_amount": deposit_amount,
        "deposit_currency": deposit_currency or "AUD",
        "extracted_text_found": bool(text.strip()),
    }
    if sa_offer:
        details["document_type"] = "SA_GOV_OFFER_TAX_INVOICE"
        details["_field_confidence"] = {"deposit_amount": "explicit", "deposit_currency": "explicit"}
        details["_field_snippets"] = {"deposit_amount": sa_deposit_snippet, "deposit_currency": sa_deposit_snippet}
    for field, value in course_schools.items():
        if value:
            details.setdefault("_field_confidence", {})[field] = "explicit"
            details.setdefault("_field_snippets", {})[field] = section_snippet(text, value)
    return details


def is_nsw_coe_cover_letter(text, filename=""):
    filename_compact = re.sub(r"[^a-z0-9]", "", filename or "", flags=re.I).lower()
    compact = compact_document_text(text)
    lower = compact.lower()
    if "coecoverletter" in filename_compact:
        return True
    if "course details" not in lower or "program name" not in lower:
        return False
    return any(
        keyword in lower
        for keyword in (
            "nsw department of education",
            "nsw government schools",
            "de international",
            "cricos provider code: 00588m",
        )
    )


def nsw_coe_cover_letter_course_section(text):
    match = re.search(r"\bCOURSE\s+DETAILS\b", text or "", flags=re.I)
    if not match:
        return ""
    section = (text or "")[match.end():]
    end_match = re.search(r"\n\s*(?:CONDITIONS|Page\s+\d+\s+of\s+\d+)\b", section, flags=re.I)
    if end_match:
        section = section[:end_match.start()]
    return section.strip()


def nsw_coe_cover_letter_school_name(program_text):
    compact = compact_document_text(program_text)
    compact = re.sub(r"\s+-\s+Year\s+\d{1,2}\s+(?:to|-|and)\s+\d{1,2}\b.*", "", compact, flags=re.I)
    compact = re.sub(r"\bYear\s+\d{1,2}\s+(?:to|-|and)\s+\d{1,2}\b.*", "", compact, flags=re.I)
    candidates = school_name_phrase_candidates(compact_document_text(program_text))
    if candidates:
        return candidates[-1]
    candidates = school_name_phrase_candidates(compact)
    if candidates:
        return candidates[-1]
    return compact[:160] if compact else ""


def nsw_coe_cover_letter_program_year_range(program_text, cricos_text=""):
    for source in (program_text, cricos_text):
        match = re.search(r"\bYears?\s*(\d{1,2})\s*(?:to|-|and)\s*(\d{1,2})\b", source or "", flags=re.I)
        if match:
            return int(match.group(1)), int(match.group(2))
        match = re.search(r"\bYear\s*(\d{1,2})\b", source or "", flags=re.I)
        if match:
            year = int(match.group(1))
            return year, year
    return None


def nsw_coe_cover_letter_first_date(value):
    dates = offer_dates_from_text(value or "")
    return dates[0][1] if dates else ""


def split_nsw_coe_cover_letter_program_blocks(section_text):
    lines = [re.sub(r"\s+", " ", line).strip() for line in str(section_text or "").splitlines()]
    lines = [line for line in lines if line]
    blocks = []
    current_cricos = ""
    index = 0
    while index < len(lines):
        line = lines[index]
        if re.match(r"^CRICOS\s+course\b", line, flags=re.I):
            current_cricos = line
            index += 1
            continue
        if re.match(r"^Program\s+name\s+and\s+location\b", line, flags=re.I):
            remainder = re.sub(r"^Program\s+name\s+and\s+location\s*", "", line, flags=re.I).strip()
            index += 1
        elif re.match(r"^Program\s+name\b", line, flags=re.I) and index + 1 < len(lines) and re.match(r"^and\s+location\b", lines[index + 1], flags=re.I):
            remainder = ""
            index += 2
        else:
            index += 1
            continue
        program_lines = [remainder] if remainder else []
        while index < len(lines) and not re.match(r"^Start\s+date\b", lines[index], flags=re.I):
            if re.match(r"^(?:CRICOS\s+course|Program\s+name)\b", lines[index], flags=re.I):
                break
            program_lines.append(lines[index])
            index += 1
        date_line = lines[index] if index < len(lines) and re.match(r"^Start\s+date\b", lines[index], flags=re.I) else ""
        start_match = re.search(r"\bStart\s+date\s+(.+?)\s+Finish\s+date\b", date_line, flags=re.I)
        finish_match = re.search(r"\bFinish\s+date\s+(.+?)(?:\s+Term\(s\)|\s+Tuition\s+fees|$)", date_line, flags=re.I)
        program_text = compact_document_text(" ".join(program_lines))
        school_name = nsw_coe_cover_letter_school_name(program_text)
        year_range = nsw_coe_cover_letter_program_year_range(program_text, current_cricos)
        is_language = bool(re.search(r"\b(?:High\s+School\s+Preparation|Intensive\s+English|English\s+High\s+School)\b", program_text, flags=re.I))
        blocks.append({
            "type": "language" if is_language else "main",
            "school": school_name,
            "startDateIso": nsw_coe_cover_letter_first_date(start_match.group(1) if start_match else date_line),
            "endDateIso": nsw_coe_cover_letter_first_date(finish_match.group(1) if finish_match else date_line),
            "yearRange": year_range,
            "cricosCourse": current_cricos,
            "programText": program_text,
            "rawDateLine": date_line,
        })
        index += 1
    return [block for block in blocks if block.get("school") or block.get("startDateIso") or block.get("endDateIso")]


def merge_nsw_year_levels(year_ranges):
    pairs = [pair for pair in year_ranges if pair]
    if not pairs:
        return "", ""
    start = min(pair[0] for pair in pairs)
    end = max(pair[1] for pair in pairs)
    entry = f"Year {start}"
    full = entry if start == end else f"Year {start} - Year {end}"
    return entry, full


def infer_nsw_coe_cover_letter_details(text, filename=""):
    if not is_nsw_coe_cover_letter(text, filename):
        return {}
    section = nsw_coe_cover_letter_course_section(text)
    blocks = split_nsw_coe_cover_letter_program_blocks(section)
    language_blocks = [block for block in blocks if block["type"] == "language"]
    main_blocks = [block for block in blocks if block["type"] != "language"]
    language = language_blocks[0] if language_blocks else {}
    main_schools = []
    for block in main_blocks:
        school = block.get("school") or ""
        if school and school not in main_schools:
            main_schools.append(school)
    main_start_dates = [block.get("startDateIso") for block in main_blocks if block.get("startDateIso")]
    main_end_dates = [block.get("endDateIso") for block in main_blocks if block.get("endDateIso")]
    entry_year, full_year = merge_nsw_year_levels([block.get("yearRange") for block in main_blocks])
    return {
        "document_kind": "LetterOfConfirmation",
        "document_type": "NSW_GOV_COE_COVER_LETTER",
        "letter_language_course_name": language.get("school") or "",
        "letter_language_start_date": language.get("startDateIso") or "",
        "letter_language_end_date": language.get("endDateIso") or "",
        "letter_year_level": full_year,
        "letter_main_course_name": main_schools[0] if len(main_schools) == 1 else " → ".join(main_schools),
        "letter_main_start_date": min(main_start_dates) if main_start_dates else "",
        "letter_main_end_date": max(main_end_dates) if main_end_dates else "",
        "main_course_schools": main_schools,
        "entry_year_level": entry_year,
        "full_year_level_range": full_year,
        "raw_program_blocks": [
            {
                "type": block.get("type"),
                "school": block.get("school"),
                "startDate": display_date_value(block.get("startDateIso") or ""),
                "endDate": display_date_value(block.get("endDateIso") or ""),
                "yearRange": block.get("yearRange"),
                "cricosCourse": block.get("cricosCourse"),
                "programText": block.get("programText"),
            }
            for block in blocks
        ],
        "nsw_course_details_text": section,
    }


def infer_document_kind(filename, text):
    filename_compact = re.sub(r"[^a-z0-9]", "", filename or "", flags=re.I).lower()
    haystack = f"{filename or ''}\n{text or ''}".lower()
    lines = [line.strip() for line in str(text or "").splitlines() if line.strip()]
    if is_nsw_coe_cover_letter(text, filename):
        return "LetterOfConfirmation"
    if is_sa_gov_letter_of_confirmation(text):
        return "LetterOfConfirmation"
    has_letter_confirmation = (
        "letterofconfirmation" in filename_compact
        or any(re.fullmatch(r"letter\s+of\s+confirmation", line, flags=re.I) for line in lines[:20])
        or "english language program start date" in haystack
        or "host school start date" in haystack
    )
    if has_letter_confirmation:
        return "LetterOfConfirmation"
    if is_sa_government_caaw(text):
        return "CAAW"
    has_coe = "coe" in haystack or "confirmation of enrolment" in haystack or "confirmation of enrollment" in haystack
    has_caaw = "caaw" in haystack or "confirmation of appropriate accommodation" in haystack or "nominated welfare period" in haystack
    if has_coe and has_caaw:
        return "COE_CAAW"
    if has_caaw:
        return "CAAW"
    if has_coe:
        return "COE"
    if "oshc receipt" in haystack or ("receipt" in haystack and "oshc" in haystack):
        return "OSHCReceipt"
    if "oshc" in haystack or "overseas student health cover" in haystack or "policy" in haystack:
        return "OSHC"
    return ""


def infer_oshc_provider(lines, filename=""):
    providers = ("Bupa", "Allianz", "Medibank", "nib", "NIB", "ahm", "AHM", "CBHS", "UniHealth")
    label_pattern = re.compile(r"\b(?:oshc provider|provider|insurer|health cover provider)\s*[:\-]\s*(.+)", re.I)
    for line in lines[:80]:
        match = label_pattern.search(line)
        if match:
            candidate = match.group(1).strip(" -:;,.")
            if 2 <= len(candidate) <= 80:
                return candidate
        for provider in providers:
            if re.search(rf"\b{re.escape(provider)}\b", line, flags=re.I):
                return provider.upper() if provider.lower() in {"nib", "ahm"} else provider
    stem = re.sub(r"[_-]+", " ", Path(filename or "").stem)
    for provider in providers:
        if re.search(rf"\b{re.escape(provider)}\b", stem, flags=re.I):
            return provider.upper() if provider.lower() in {"nib", "ahm"} else provider
    return ""


def infer_coe_oshc_details(upload, forced_kind=None):
    text = extract_uploaded_text(upload)
    lines = [re.sub(r"\s+", " ", line).strip() for line in text.splitlines()]
    lines = [line for line in lines if line]
    kind = forced_kind or infer_document_kind(upload.filename, text)
    nsw_letter = infer_nsw_coe_cover_letter_details(text, upload.filename) if kind == "LetterOfConfirmation" and is_nsw_coe_cover_letter(text, upload.filename) else {}
    sa_letter = infer_sa_gov_letter_confirmation_details(text) if kind == "LetterOfConfirmation" and is_sa_gov_letter_of_confirmation(text) else {}
    sa_caaw = infer_sa_government_caaw_details(text) if kind == "CAAW" and is_sa_government_caaw(text) else {}
    medibank_oshc = infer_medibank_oshc_details(text) if kind == "OSHC" and is_medibank_oshc_policy_certificate(text) else {}
    nib_oshc = infer_nib_oshc_details(text) if kind == "OSHC" and is_nib_oshc_confirmation(text) else {}
    letter_language_start = best_regex_context_date(lines, (
        r"\benglish\s+language\s+program\s+(?:start|state|stat)\s+date\b",
        r"\blanguage\s+program\s+(?:start|state|stat)\s+date\b",
        r"\benglish\s+program\s+(?:start|state|stat)\s+date\b",
    )) or best_context_date(lines, ("english language program start", "language program start", "english program start"))
    letter_language_end = best_regex_context_date(lines, (
        r"\benglish\s+language\s+program\s+end\s+date\b",
        r"\blanguage\s+program\s+end\s+date\b",
        r"\benglish\s+program\s+end\s+date\b",
    ), -1) or best_context_date(lines, ("english language program end", "language program end", "english program end"), -1)
    letter_main_start = best_regex_context_date(lines, (
        r"\bhost\s+school\s+(?:start|state|stat)\s+date\b",
        r"\bmain\s+course\s+(?:start|state|stat)\s+date\b",
        r"\bprincipal\s+course\s+(?:start|state|stat)\s+date\b",
    )) or best_context_date(lines, ("host school start", "main course start", "principal course start"))
    letter_main_end = best_regex_context_date(lines, (
        r"\bhost\s+school\s+end\s+date\b",
        r"\bmain\s+course\s+end\s+date\b",
        r"\bprincipal\s+course\s+end\s+date\b",
    ), -1) or best_context_date(lines, ("host school end", "main course end", "principal course end"), -1)
    course_start_patterns = (
        r"\bcours(?:e)?\s+(?:start|state|stat)\s+date\b",
        r"\bcours(?:e)?\s+commencement\s+date\b",
        r"\bcommencement\s+date\b",
    )
    course_end_patterns = (
        r"\bcours(?:e)?\s+end\s+date\b",
        r"\bcours(?:e)?\s+(?:finish|completion)\s+date\b",
        r"\bcompletion\s+date\b",
    )
    coe_start = date_after_label(lines, course_start_patterns) or best_regex_context_date(lines, course_start_patterns)
    coe_end = date_after_label(lines, course_end_patterns, -1) or best_regex_context_date(lines, course_end_patterns, -1)
    if not coe_start:
        coe_start = best_context_date(lines, ("course start", "course commencement", "start date", "commencement date"))
    if not coe_end:
        coe_end = best_context_date(lines, ("course end", "course finish", "end date", "finish date", "completion date"), -1)
    caaw_start, caaw_end = caaw_welfare_period_dates(lines)
    oshc_end = best_context_date(lines, ("expiry date", "cover end", "policy end", "valid to"), -1)
    oshc_start = best_oshc_start_date(lines, oshc_end)
    issue_date = best_context_date(lines, ("policy issue date", "issue date", "issued date", "date of issue"), allow_negative_anchor=True)
