def extraction_snippet(text, value, labels=()):
    compact = re.sub(r"\s+", " ", text or "").strip()
    if not compact:
        return "未读取到文字层/OCR文字，请人工核对原文件。"
    value = str(value or "").strip()
    if value:
        pos = compact.lower().find(value.lower())
        if pos >= 0:
            return compact[max(0, pos - 90):pos + len(value) + 90]
    for label in labels:
        pos = compact.lower().find(str(label).lower())
        if pos >= 0:
            return compact[max(0, pos - 60):pos + 180]
    return compact[:240]


def extraction_confidence(text_found, value, field_name="", source_confidence=""):
    if not value:
        return "needs_review", "需人工填写"
    if str(value).strip() == "需人工确认":
        return "needs_review", "需人工确认"
    if not text_found:
        return "needs_review", "扫描件/图片识别不稳定，请人工确认"
    if source_confidence == "explicit":
        return "high", "已自动识别，请确认"
    if source_confidence == "uncertain":
        return "needs_review", "文字层识别，仍需确认"
    if field_name in EXTRACTION_DATE_FIELDS and not re.match(r"^\d{4}-\d{2}-\d{2}$", str(value)):
        return "needs_review", "日期格式需人工确认"
    return "high", "文字层识别，仍需确认"


def extraction_review_data(upload, module, doc_type=""):
    text = extract_uploaded_text(upload)
    if module == "Offer":
        details = infer_offer_details(upload)
        fields = OFFER_EXTRACTION_FIELDS
    elif module == "COE + OSHC":
        kind = coe_kind_from_review(doc_type) if doc_type else None
        details = infer_coe_oshc_details(upload, kind)
        fields = COE_OSHC_EXTRACTION_FIELDS
    else:
        return None
    text_found = bool((details.get("extracted_text_found") if isinstance(details, dict) else False) or text.strip())
    field_confidence = details.get("_field_confidence") or {}
    field_snippets = details.get("_field_snippets") or {}
    values = {}
    for field in fields:
        value = details.get(field)
        if value is None:
            value = ""
        if isinstance(value, float):
            value = f"{value:.2f}" if field in {"deposit_amount", "receipt_amount"} else str(value).rstrip("0").rstrip(".")
        status, message = extraction_confidence(text_found, value, field, field_confidence.get(field, ""))
        values[field] = {
            "value": str(value or ""),
            "status": status,
            "message": message,
            "snippet": field_snippets.get(field) or extraction_snippet(text, value, (EXTRACTION_FIELD_LABELS.get(field, field), field.replace("_", " "))),
        }
    return {
        "text_found": text_found,
        "source": ("本地 OCR 识别，请核对" if upload_text_extraction_meta(upload).get("ocr_fallback_used") else "PDF/Word 文字层") if text_found else {
            "engine_unavailable": "本地 OCR 未就绪，请联系管理员",
            "renderer_unavailable": "PDF 扫描组件未就绪，请联系管理员",
            "engine_failed": "本地 OCR 执行失败，请重试或人工填写",
            "timeout": "本地 OCR 超时，请重试或人工填写",
            "pdf_failed": "PDF 无法读取，请检查文件是否损坏或加密",
            "image_failed": "图片无法读取，请检查文件",
        }.get(upload_text_extraction_meta(upload).get("ocr_status"), "未读取到可用文字"),
        "document_type": details.get("document_kind") or doc_type or "",
        "detected_document_type": details.get("document_type") or details.get("document_kind") or "",
        "text_extraction": upload_text_extraction_meta(upload),
        "matched_keywords": document_type_detection_matched_keywords(text, upload.filename),
        "fields": values,
        "program_segments": details.get("program_segments") or [],
    }


