def offer_module_conflicting_document_type(text, filename=""):
    haystack = normalized_search_text(f"{filename or ''}\n{text or ''}")
    if not haystack:
        return ""
    if is_sa_government_caaw(text):
        return "CAAW"
    if (
        "under 18 student visa applicant" in haystack
        and "welfare details" in haystack
        and "provider details" in haystack
        and "accommodation/welfare arrangements" in haystack
    ):
        return "CAAW"
    if is_medibank_oshc_policy_certificate(text) or is_nib_oshc_confirmation(text):
        return "OSHC"
    if (
        "medibank oshc" in haystack
        and "your policy certificate" in haystack
        and "membership number" in haystack
        and "valid to" in haystack
    ):
        return "OSHC"
    if (
        re.search(r"\bnib\b", haystack)
        and "confirmation of health cover" in haystack
        and "policy number" in haystack
        and "policy start date" in haystack
        and "policy end date" in haystack
    ):
        return "OSHC"
    if is_sa_gov_letter_of_confirmation(text) or is_nsw_coe_cover_letter(text, filename):
        return "LetterOfConfirmation"
    if (
        "letter of confirmation" in haystack
        and ("program summary" in haystack or "section 2" in haystack)
    ):
        return "LetterOfConfirmation"
    if "confirmation of enrolment" in haystack or "confirmation of enrollment" in haystack:
        return "COE"
    if "visa grant notification" in haystack or "visa grant date" in haystack:
        return "VisaGrant"
    if "passport no" in haystack and "date of birth" in haystack and "nationality" in haystack:
        return "Passport"
    return ""


def document_type_detection_matched_keywords(text, filename=""):
    haystack = normalized_search_text(f"{filename or ''}\n{text or ''}")
    keywords = (
        "letter of offer", "letter of offer / tax invoice", "offer", "tax invoice",
        "offer expiry date", "deposit amount", "initial payment", "payment details / tax invoice",
        "tuition fee", "course fee", "south australian government schools", "department for education",
        "letter of confirmation", "section 2", "program summary", "high school graduate program",
        "under 18 student visa applicant", "welfare details", "provider details",
        "medibank oshc", "your policy certificate", "membership number", "valid to",
        "confirmation of health cover", "policy number", "policy start date", "policy end date",
        "confirmation of enrolment", "confirmation of enrollment",
    )
    return [keyword for keyword in keywords if keyword in haystack]


def offer_filename_document_type(filename):
    return classify_offer_filename(filename)


def offer_record_value(offer, key, default=""):
    try:
        return offer[key] if key in offer.keys() else default
    except AttributeError:
        return offer.get(key, default) if isinstance(offer, dict) else default


def save_offer_language_school(connection, offer_id, student_id, value):
    value = str(value or "").strip()
    available = any(str(row[1]) == "language_school_name" for row in connection.execute("PRAGMA table_info('offers')"))
    if not available:
        if value:
            raise ValueError("Offer 语言学校字段尚未完成数据库升级，请联系管理员。")
        return
    connection.execute("UPDATE offers SET language_school_name=? WHERE id=? AND student_id=?",
                       (value, offer_id, student_id))


def offer_course_start_date_available(connection=None):
    if connection is not None:
        rows = connection.execute("PRAGMA table_info('offers')").fetchall()
        return any(str(row[1]) == "course_start_date" for row in rows)
    return any(str(row["name"]) == "course_start_date" for row in db.all("PRAGMA table_info('offers')"))


def offer_record_document_type(offer):
    document_type = (offer_record_value(offer, "document_type") or "").strip()
    if document_type in module_document_types("Offer"):
        return document_type
    signed_path = offer_record_value(offer, "signed_offer_file_path") or ""
    status = (offer_record_value(offer, "offer_status") or "").strip()
    if signed_path and status == "accepted":
        return "OfferAcceptance"
    if signed_path:
        return "SignedOffer"
    return "Offer"


def offer_record_file_path(offer):
    document_type = offer_record_document_type(offer)
    signed_path = offer_record_value(offer, "signed_offer_file_path") or ""
    offer_path = offer_record_value(offer, "offer_file_path") or ""
    if document_type in {"SignedOffer", "OfferAcceptance"} and signed_path:
        return signed_path
    return offer_path


def suggested_review_document_type(upload, module, extracted_text=None):
    if module == "Offer":
        filename_document_type = offer_filename_document_type(upload.filename)
        if filename_document_type in module_document_types(module):
            return filename_document_type
        text = extracted_text if extracted_text is not None else extract_uploaded_text(upload)
        if offer_module_conflicting_document_type(text, upload.filename):
            return ""
        details = infer_offer_details(upload)
        document_type = details.get("document_type") or "Offer"
        return document_type if document_type in module_document_types(module) else "Offer"
    if module == "COE + OSHC":
        details = infer_coe_oshc_details(upload)
        kind = details.get("document_kind") or ""
        return kind if kind in module_document_types(module) else ""
    return detect_document_type(upload.filename)


def log_upload_review_document_detection(file_meta, module, final_document_type, options, extraction_data):
    extraction_data = extraction_data or {}
    text_meta = extraction_data.get("text_extraction") or {}
    matched_keywords = extraction_data.get("matched_keywords") or []
    append_service_log(
        "admin",
        "upload_review_document_type_detected",
        upload_file_name=file_meta.get("original_name") or file_meta.get("stored_name") or "",
        current_module=module,
        extracted_text_available=text_meta.get("extracted_text_available"),
        ocr_fallback_used=text_meta.get("ocr_fallback_used"),
        detected_document_type=extraction_data.get("detected_document_type") or "",
        confidence="high" if final_document_type else "needs_review",
        matched_keywords=",".join(matched_keywords[:12]),
        final_document_type=final_document_type or "",
        extraction_schema_loaded=bool(final_document_type and final_document_type in options),
    )


def extraction_review_html(index, module, data):
    if not data:
        return ""
    rows = []
    segment_cards = []
    selected_type = str(data.get("document_type") or "").strip()
    visible_count = 0
    for field, info in data["fields"].items():
        value = info["value"]
        is_date_field = field in EXTRACTION_DATE_FIELDS
        input_value = display_date_value(value) if is_date_field else value
        date_attrs = (
            ' placeholder="dd/mm/yyyy" pattern="\\d{2}/\\d{2}/\\d{4}" inputmode="numeric" maxlength="10" '
            'data-date-input title="请按 dd/mm/yyyy 格式填写有效日期，例如 31/01/1980" autocomplete="off"'
            if is_date_field else ""
        )
        status = info["status"]
        field_id = f"extract_{field}_{index}"
        allowed_types = sorted(EXTRACTION_FIELD_DOCUMENT_TYPES.get(field, []))
        document_types = " ".join(allowed_types)
        initially_visible = not allowed_types or (selected_type and selected_type in allowed_types)
        if initially_visible:
            visible_count += 1
        hidden_attr = "" if initially_visible else " hidden"
        copy_button = (
            '<button type="button" class="ghost mini" data-extraction-copy>复制原文</button>'
            if data["text_found"] else '<button type="button" class="ghost mini" disabled>无原文</button>'
        )
        rows.append(
            f"""<div class="extraction-field extraction-{esc(status)}" data-extraction-field-row{hidden_attr} data-extraction-for="{esc(document_types)}" data-source-page="1" data-source-snippet="{esc(info["snippet"])}">
              <label class="extraction-label" for="{esc(field_id)}">{esc(EXTRACTION_FIELD_LABELS.get(field, field))}</label>
              <input id="{esc(field_id)}" type="text" name="extract_{esc(field)}_{index}" value="{esc(input_value)}" data-extraction-field{date_attrs}>
              <span class="extraction-status">{esc(info["message"])}</span>
              <div class="extraction-tools">
                {copy_button}
              </div>
              <details class="extraction-source"><summary>查看原文片段</summary><blockquote>{esc(info["snippet"])}</blockquote></details>
            </div>"""
        )
    for segment in data.get("program_segments") or []:
        items = [
            ("Program Type", segment.get("program_type") or ""),
            ("Year Level", segment.get("year_level") or ""),
            ("School", segment.get("school") or ""),
            ("Start Date", segment.get("start_date") or ""),
            ("End Date", segment.get("end_date") or ""),
            ("Course Name", segment.get("course_name") or ""),
            ("CRICOS Code", segment.get("cricos_code") or ""),
            ("Tuition Fee", segment.get("tuition_fee") or ""),
            ("Currency", segment.get("currency") or ""),
            ("Language Course", "Yes" if segment.get("is_language_course") else "No"),
        ]
        segment_cards.append(
            '<article class="program-segment-card">'
            + "".join(f'<div><span>{esc(label)}</span><strong>{esc(value)}</strong></div>' for label, value in items)
            + "</article>"
        )
    segment_section = (
        f"""<div class="program-segments-review" data-extraction-program-segments>
          <h3>Program Summary / 课程明细</h3>
          <div class="program-segment-grid">{"".join(segment_cards)}</div>
        </div>"""
        if segment_cards else ""
    )
    return f"""
    <section class="extraction-review-box extraction-review-compact" data-extraction-review>
      <div class="extraction-review-head">
        <div><strong>自动提取审核</strong><small>最终以这里确认/修改后的字段写入 CRM；不确定字段请人工改正。</small></div>
        <span class="status {'ok' if data['text_found'] else 'warn'}">{esc(data['source'])}</span>
      </div>
      <p class="extraction-hint" data-extraction-empty-hint{" hidden" if selected_type and visible_count else ""}>{"Letter of Confirmation 是可选文件，不需要自动提取 CAAW/OSHC 字段。确认保存即可。" if selected_type == "LetterOfConfirmation" and not visible_count else "请选择 DocumentType，系统只显示需要审核的字段。"}</p>
      <div class="extraction-grid">{"".join(rows)}</div>
      {segment_section}
    </section>
    """


def extraction_form_value(form, field, index):
    value = (form.get(f"extract_{field}_{index}") or "").strip()
    if field not in EXTRACTION_DATE_FIELDS:
        return value
    if not is_valid_date_value(value):
        return ""
    return normalize_date_value(value)


def crm_display_date_input(name, value="", form_id="", required=False):
    form_attr = f' form="{esc(form_id)}"' if form_id else ""
    required_attr = " required" if required else ""
    input_value = display_date_value(value)
    return (
        f'<input{form_attr} type="text" name="{esc(name)}" value="{esc(input_value)}" '
        f'placeholder="dd/mm/yyyy" pattern="\\d{{2}}/\\d{{2}}/\\d{{4}}" inputmode="numeric" '
        f'maxlength="10" data-date-input title="请按 dd/mm/yyyy 格式填写有效日期，例如 31/01/1980" '
        f'autocomplete="off"{required_attr}>'
    )


def crm_normalized_date_form_value(form, field, label="日期", fallback="", blank_uses_fallback=False):
    if field in form:
        value = form.get(field)
        if blank_uses_fallback and not str(value or "").strip():
            value = fallback
    else:
        value = fallback
    value = value or ""
    value = str(value).strip()
    if not value:
        return ""
    if not is_valid_date_value(value):
        raise ValueError(f"{label} 请按 dd/mm/yyyy 格式填写有效日期")
    return normalize_date_value(value)


COE_OSHC_DATE_FIELDS = {
    "coe_start_date", "coe_end_date",
    "letter_language_start_date", "letter_language_end_date",
    "letter_main_start_date", "letter_main_end_date",
    "caaw_welfare_start_date", "caaw_welfare_end_date",
    "oshc_policy_issue_date", "oshc_commencement_date", "oshc_expiry_date",
    "oshc_start_date", "oshc_end_date", "receipt_date",
}


def coe_date_form_value(form, field, record=None, fallback=None):
    if field in form:
        value = (form.get(field) or "").strip()
    elif fallback and fallback in form:
        value = (form.get(fallback) or "").strip()
    elif record and field in record.keys():
        value = record[field] or ""
    elif record and fallback and fallback in record.keys():
        value = record[fallback] or ""
    else:
        value = ""
    if not value:
        return ""
    if not is_valid_date_value(value):
        return ""
    return normalize_date_value(value)


def extraction_money_value(value):
    value = str(value or "").strip()
    if not value:
        return None
    match = re.search(r"[0-9][0-9,]*(?:\.\d{1,2})?", value)
    if not match:
        return None
    try:
        return float(match.group(0).replace(",", ""))
    except ValueError:
        return None


def backup_storage_dir():
    BACKUP_DIR.mkdir(parents=True, exist_ok=True)
    return BACKUP_DIR.resolve()


def backup_stamp():
    return datetime.now().astimezone().strftime("%Y%m%d_%H%M%S")


def bool_setting(key, default=False):
    value = str(db.setting(key, "true" if default else "false")).strip().lower()
    return value in {"1", "true", "yes", "on", "是", "启用"}


def export_system_settings():
    return [
        {
            "key": row["key"],
            "value": row["value"],
            "updated_by": row["updated_by"],
            "updated_at": row["updated_at"],
        }
        for row in db.all("SELECT key,value,updated_by,updated_at FROM system_settings ORDER BY key")
    ]


def sqlite_backup_to(target):
    target.parent.mkdir(parents=True, exist_ok=True)
    source = sqlite3.connect(DB_PATH)
    dest = sqlite3.connect(target)
    try:
        source.backup(dest)
    finally:
        dest.close()
        source.close()


def add_directory_to_zip(zip_file, source_dir, archive_prefix):
    source_dir = Path(source_dir)
    if not source_dir.exists():
        return
    for path in sorted(source_dir.rglob("*")):
        if path.is_file():
            zip_file.write(path, f"{archive_prefix}/{path.relative_to(source_dir).as_posix()}")


def backup_manifest(backup_id, created_at, user, notes, included_items, excluded_items):
    return {
        "backup_id": backup_id,
        "created_at": created_at,
        "created_by": user["username"] if user else "system",
        "app_version": VERSION,
        "database_type": "sqlite",
        "backup_notes": notes,
        "included_items": included_items,
        "excluded_items": excluded_items,
        "system_mode": db.setting("mode", "test"),
        "production_enabled": db.setting("production_enabled", "false"),
    }


def write_backup_record(path, manifest, user):
    db.execute(
        """INSERT INTO backup_records(
             backup_id,file_name,file_path,file_size,backup_notes,created_by,created_by_username,
             created_at,app_version,database_type,manifest_json,deleted_at
           ) VALUES(?,?,?,?,?,?,?,?,?,?,?,NULL)
           ON CONFLICT(file_name) DO UPDATE SET
             file_path=excluded.file_path,file_size=excluded.file_size,backup_notes=excluded.backup_notes,
             manifest_json=excluded.manifest_json,deleted_at=NULL""",
        (
            manifest["backup_id"],
            path.name,
            str(path),
            path.stat().st_size,
            manifest["backup_notes"],
            user["id"] if user else None,
            user["username"] if user else "system",
            manifest["created_at"],
            manifest["app_version"],
            manifest["database_type"],
            json.dumps(manifest, ensure_ascii=False),
        ),
    )


def create_system_backup(user=None, notes="", prefix="AAIE_CRM_Backup", audit=True):
    backup_dir = backup_storage_dir()
    created_at = now_iso()
    stamp = backup_stamp()
    backup_id = f"{prefix}_{stamp}"
    target = backup_dir / f"{backup_id}.zip"
    if target.exists():
        target = backup_dir / f"{backup_id}_{os.getpid()}.zip"
        backup_id = target.stem
    included_items = [
        "database/aaie_crm.db",
        "config/",
        "exports/system_settings.json",
        "backup_manifest.json",
        "SQLite tables: system_settings, users, roles, modules, user_module_permissions, parent_form_tokens, workflow_status, students, student_change_logs, student_documents, offers, coe_oshc, visas, payments, reminders, audit_logs",
    ]
    excluded_items = [
        "/Volumes/Server/Students/2024",
        "/Volumes/Server/Students/2025",
        "/Volumes/Server/Students/2026",
        "/Volumes/Server/Students/CRM_TEST student files",
        "All real student file folders and uploaded document binaries outside the CRM database metadata",
    ]
    manifest = backup_manifest(backup_id, created_at, user, notes, included_items, excluded_items)
    with tempfile.TemporaryDirectory(prefix="aaie-crm-backup-") as temp_folder:
        temp_root = Path(temp_folder)
        snapshot = temp_root / "aaie_crm.db"
        sqlite_backup_to(snapshot)
        settings_export = temp_root / "system_settings.json"
        settings_export.write_text(json.dumps(export_system_settings(), ensure_ascii=False, indent=2), encoding="utf-8")
        manifest_path = temp_root / "backup_manifest.json"
        manifest_path.write_text(json.dumps(manifest, ensure_ascii=False, indent=2), encoding="utf-8")
        temp_zip = target.with_suffix(".zip.tmp")
        with zipfile.ZipFile(temp_zip, "w", compression=zipfile.ZIP_DEFLATED) as zf:
            zf.write(snapshot, "database/aaie_crm.db")
            zf.write(settings_export, "exports/system_settings.json")
            add_directory_to_zip(zf, SECRET_PATH.parent, "config")
            zf.write(manifest_path, "backup_manifest.json")
        temp_zip.replace(target)
    write_backup_record(target, manifest, user)
    if audit:
        db.audit(user, "backup", "system_backup", manifest["backup_id"], file_path=str(target), new_value=notes)
    cleanup_old_backups_if_enabled()
    return target, manifest


def backup_database(user=None):
    target, _ = create_system_backup(user, notes="Manual database backup")
    return target


def validate_backup_zip(path):
    path = Path(path)
    if path.suffix.lower() != ".zip" or not path.is_file():
        raise ValueError("备份文件不存在或格式不正确")
    with zipfile.ZipFile(path) as zf:
        names = zf.namelist()
        for name in names:
            normalized = Path(name)
            if name.startswith("/") or ".." in normalized.parts:
                raise ValueError("备份文件包含不安全路径")
        if "backup_manifest.json" not in names:
            raise ValueError("备份文件缺少 backup_manifest.json")
        if "database/aaie_crm.db" not in names:
            raise ValueError("备份文件缺少 SQLite 数据库")
        manifest = json.loads(zf.read("backup_manifest.json").decode("utf-8"))
    return manifest


def backup_path_from_name(file_name):
    safe_name = Path(file_name).name
    if safe_name != file_name or not safe_name.endswith(".zip"):
        raise ValueError("备份文件名不安全")
    backup_dir = backup_storage_dir()
    path = (backup_dir / safe_name).resolve()
    ensure_within(path, backup_dir)
    return path


def backup_history():
    try:
        backup_dir = backup_storage_dir()
    except OSError:
        return []
    rows = {row["file_name"]: row for row in db.all("SELECT * FROM backup_records WHERE deleted_at IS NULL")}
    items = []
    for path in sorted(backup_dir.glob("*.zip"), key=lambda item: item.stat().st_mtime, reverse=True):
        manifest = {}
        try:
            manifest = validate_backup_zip(path)
        except Exception as exc:
            manifest = {"backup_id": path.stem, "created_at": "", "backup_notes": f"Invalid backup: {exc}", "created_by": ""}
        record = rows.get(path.name)
        items.append({
            "file_name": path.name,
            "file_path": str(path),
            "file_size": path.stat().st_size,
            "created_at": (record["created_at"] if record else manifest.get("created_at", "")) or datetime.fromtimestamp(path.stat().st_mtime).astimezone().isoformat(timespec="seconds"),
            "created_by": (record["created_by_username"] if record else manifest.get("created_by", "")) or "system",
            "notes": (record["backup_notes"] if record else manifest.get("backup_notes", "")) or "",
            "backup_id": manifest.get("backup_id", path.stem),
            "valid": "Invalid backup:" not in str(manifest.get("backup_notes", "")),
        })
    return items


def format_bytes(size):
    size = float(size or 0)
    for unit in ("B", "KB", "MB", "GB"):
        if size < 1024 or unit == "GB":
            return f"{size:.1f} {unit}" if unit != "B" else f"{int(size)} B"
        size /= 1024
    return f"{size:.1f} GB"


def restore_system_backup(file_name, user):
    path = backup_path_from_name(file_name)
    manifest = validate_backup_zip(path)
    pre_restore, pre_manifest = create_system_backup(
        user,
        notes=f"Pre-restore backup before restoring {path.name}",
        prefix="AAIE_CRM_PreRestore_Backup",
    )
    with tempfile.TemporaryDirectory(prefix="aaie-crm-restore-") as temp_folder:
        temp_root = Path(temp_folder)
        with zipfile.ZipFile(path) as zf:
            zf.extract("database/aaie_crm.db", temp_root)
            config_names = [
                name for name in zf.namelist()
                if name.startswith("config/") and not name.endswith("/")
            ]
            for name in config_names:
                zf.extract(name, temp_root)
        restored_db = temp_root / "database" / "aaie_crm.db"
        if not restored_db.is_file():
            raise ValueError("备份中的数据库文件无效")
        with DB_LOCK:
            DB_PATH.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(restored_db, DB_PATH)
            restored_config = temp_root / "config"
            if restored_config.exists():
                SECRET_PATH.parent.mkdir(parents=True, exist_ok=True)
                for source in restored_config.rglob("*"):
                    if source.is_file():
                        relative = source.relative_to(restored_config)
                        destination = SECRET_PATH.parent / relative
                        destination.parent.mkdir(parents=True, exist_ok=True)
                        shutil.copy2(source, destination)
    db.initialize()
    ensure_template_management_seed()
    db.audit(
        user,
        "restore",
        "system_backup",
        manifest.get("backup_id", path.stem),
        file_path=str(path),
        old_value=pre_manifest["backup_id"],
        new_value="restored",
    )
    return pre_restore, manifest


def delete_system_backup(file_name, user):
    path = backup_path_from_name(file_name)
    manifest = validate_backup_zip(path)
    path.unlink()
    db.execute("UPDATE backup_records SET deleted_at=? WHERE file_name=?", (now_iso(), path.name))
    db.audit(user, "delete", "system_backup", manifest.get("backup_id", path.stem), file_path=str(path))
    return path


def cleanup_old_backups_if_enabled():
    if not bool_setting("auto_cleanup_enabled", False):
        return
    try:
        keep = max(1, int(db.setting("backup_retention_count", "30") or 30))
    except ValueError:
        keep = 30
    try:
        backup_dir = backup_storage_dir()
    except OSError:
        return
    regular_backups = sorted(
        backup_dir.glob("AAIE_CRM_Backup_*.zip"),
        key=lambda item: item.stat().st_mtime,
        reverse=True,
    )
    for path in regular_backups[keep:]:
        try:
            path.unlink()
            db.execute("UPDATE backup_records SET deleted_at=? WHERE file_name=?", (now_iso(), path.name))
        except OSError:
            continue


def maybe_run_auto_backup():
    if SAFE_PRODUCTION_ACTIVE:
        return None
    if not bool_setting("auto_backup_enabled", True):
        return
    now = datetime.now().astimezone()
    backup_time = str(db.setting("auto_backup_time", "23:30") or "23:30")
    try:
        hour, minute = [int(part) for part in backup_time.split(":", 1)]
    except ValueError:
        hour, minute = 23, 30
    today = now.strftime("%Y-%m-%d")
    if db.setting("last_auto_backup_date", "") == today:
        return
    if (now.hour, now.minute) < (hour, minute):
        return
    create_system_backup(None, notes="Automatic daily backup", audit=True)
    db.set_setting("last_auto_backup_date", today)


def content_hash(value):
    return hashlib.sha256(str(value or "").encode("utf-8")).hexdigest()


def normalized_title(value):
    return re.sub(r"\s+", " ", str(value or "").strip().lower())


def maybe_int(value):
    if value in (None, ""):
        return None
    try:
        return int(value)
    except (TypeError, ValueError):
        return None


def suggest_content_year(row):
    candidates = [
        row.get("written_date"),
        row.get("publish_date"),
        row.get("created_at"),
        row.get("updated_at"),
        row.get("source_path"),
    ]
    for value in candidates:
        match = re.search(r"\b(20\d{2})\b", str(value or ""))
        if match:
            return int(match.group(1))
    return None


def content_issue_labels(flags):
    labels = {
        "has_empty_body": "空正文 / 旧 gdoc 占位",
        "missing_gdoc_source": "缺少 Google Doc 来源",
        "duplicate_title": "标题重复",
        "pending_manual_category": "待人工分类",
        "missing_year": "缺少年份",
        "needs_review": "需要人工复核",
    }
    return [label for key, label in labels.items() if flags.get(key)]


