    def send_html(
        self, content, status=200, headers=None, *, presentation_surface=None
    ):
        if self.user and '<div class="app-shell">' in content and "</body>" in content:
            content = content.replace("</body>", self.global_reminder_popup_html() + self.assistant_widget_html() + "</body>", 1)
        content = self.prepare_html_content(
            content, presentation_surface=presentation_surface
        )
        header_items = list(headers or [])
        header_keys = {str(key).lower() for key, _value in header_items}
        payload = content.encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "text/html; charset=utf-8")
        self.send_header("Content-Length", str(len(payload)))
        self.send_header("X-Content-Type-Options", "nosniff")
        self.send_header("X-Frame-Options", "DENY")
        self.send_header("Referrer-Policy", "same-origin")
        if "content-security-policy" not in header_keys:
            self.send_header("Content-Security-Policy", "default-src 'self'; style-src 'self' 'unsafe-inline'; script-src 'self' 'unsafe-inline'; img-src 'self' data: blob:; connect-src 'self'; form-action 'self'; frame-src 'self'")
        for key, value in header_items:
            self.send_header(key, value)
        self.end_headers()
        self.wfile.write(payload)

    def prepare_html_content(self, content, *, presentation_surface=None):
        """Apply the shared Mobile navigation only to authenticated CRM shell pages."""
        if presentation_surface == "desktop":
            return content
        if not self.user or getattr(self, "headers", None) is None:
            return content
        if self.request_view_mode() != MOBILE_MODE:
            return content
        if '<div class="app-shell">' not in content:
            return content
        current_path = getattr(getattr(self, "parsed", None), "path", "/") or "/"
        return mobile_business_page(
            content,
            active_navigation_for_path(current_path),
            bottom_actions(self.user, can_access_module),
            plus_actions(self.user, can_access_module),
        )

    def text(self, value, status=200):
        payload = str(value).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "text/plain; charset=utf-8")
        self.send_header("Content-Length", str(len(payload)))
        self.end_headers()
        self.wfile.write(payload)

    def json_response(self, value, status=200):
        payload = json.dumps(value, ensure_ascii=False).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Cache-Control", "no-store")
        self.send_header("Content-Length", str(len(payload)))
        self.end_headers()
        self.wfile.write(payload)

    def redirect(self, location, cookie=None):
        self.send_response(303)
        self.send_header("Location", location)
        if cookie:
            self.send_header("Set-Cookie", cookie)
        self.end_headers()

    def error_page(self, message, status=400):
        if re.fullmatch(
            r"/higher-education/(plans/create|plans/\d+/(items|confirm)|plan-items/\d+/(submit|remove))",
            getattr(getattr(self, "parsed", None), "path", ""),
        ):
            message = application_error_display(message)
        message = "不支持此请求方式" if message == "Method Not Allowed" else message
        body = f'<div class="error-page"><div class="brand-mark large-mark">A</div><h1>无法完成操作</h1><p>{esc(message)}</p><a class="primary button-link" href="/">返回 CRM</a></div>'
        self.send_html(page("操作失败", body, self.user, self.csrf, nas=nas.status()), status)

    def flash_redirect(self, location, message, kind="success"):
        fragment = ""
        if "#" in location:
            location, fragment = location.split("#", 1)
            fragment = "#" + fragment
        join = "&" if "?" in location else "?"
        self.redirect(f"{location}{join}message={quote(message)}&kind={quote(kind)}{fragment}")

    def toast_redirect(
        self, location, message, kind="success", title="", copy_text="", href="",
        copy_success_message="",
    ):
        fragment = ""
        if "#" in location:
            location, fragment = location.split("#", 1)
            fragment = "#" + fragment
        params = {
            "toast_message": message,
            "toast_kind": kind,
        }
        if title:
            params["toast_title"] = title
        if copy_text:
            params["toast_copy"] = copy_text
        if copy_success_message:
            params["toast_copy_success"] = copy_success_message
        if href:
            params["toast_href"] = href
        join = "&" if "?" in location else "?"
        self.redirect(f"{location}{join}{urlencode(params)}{fragment}")

    def message(self):
        return (self.query.get("message") or [""])[0], (self.query.get("kind") or ["success"])[0]

    def serve_asset(self):
        relative = self.parsed.path.removeprefix("/assets/")
        target = (ASSET_DIR / relative).resolve()
        if ASSET_DIR.resolve() not in target.parents or not target.is_file():
            return self.text("Not found", 404)
        stat = target.stat()
        etag = f'"{stat.st_mtime_ns:x}-{stat.st_size:x}"'
        requested_version = str((self.query.get("v") or [""])[0])
        cache_control = (
            "public, max-age=31536000, immutable"
            if requested_version == ASSET_VERSION
            else "no-cache"
        )
        if self.headers.get("If-None-Match") == etag:
            self.send_response(HTTPStatus.NOT_MODIFIED)
            self.send_header("Cache-Control", cache_control)
            self.send_header("ETag", etag)
            self.end_headers()
            return
        payload = target.read_bytes()
        self.send_response(200)
        self.send_header("Content-Type", mimetypes.guess_type(target.name)[0] or "application/octet-stream")
        self.send_header("Content-Length", str(len(payload)))
        self.send_header("Cache-Control", cache_control)
        self.send_header("ETag", etag)
        self.end_headers()
        self.wfile.write(payload)

    def serve_wechat_verify_file(self):
        filename = Path(self.parsed.path).name
        if not re.fullmatch(r"MP_verify[A-Za-z0-9_-]+\.txt", filename):
            return self.text("Not found", 404)
        target = (WECHAT_VERIFY_DIR / filename).resolve()
        if WECHAT_VERIFY_DIR.resolve() not in target.parents or not target.is_file():
            return self.text("Not found", 404)
        payload = target.read_bytes()
        self.send_response(200)
        self.send_header("Content-Type", "text/plain; charset=utf-8")
        self.send_header("Content-Length", str(len(payload)))
        self.send_header("Cache-Control", "no-cache")
        self.end_headers()
        self.wfile.write(payload)

    def login(self, method):
        if method == "GET":
            message, kind = self.message()
            notice = f'<div class="notice {esc(kind)}">{esc(message)}</div>' if message else ""
            environment_notice = "内部系统 · 正式生产环境" if getattr(STAGING, "mode", None) == "production" else "内部系统 · 员工专用"
            body = f"""
            <div class="login-layout"><div class="login-brand"><div class="brand-mark large-mark">A</div>
              <h1>AAIE CRM</h1><p>留学服务学生流程管理</p><div class="security-note">{environment_notice}</div></div>
              <form class="login-card" method="post" action="/login"><h2>员工登录</h2>{notice}
                <label>用户名<input name="username" autocomplete="username" required autofocus></label>
                <label>密码<input type="password" name="password" autocomplete="current-password" required></label>
                <button class="primary full" type="submit">登录</button>
              </form></div>"""
            return self.send_html(page("登录", body))
        form, _ = parse_request_body(self)
        username = str(form.get("username", "")).strip().lower()
        user = db.one(
            """SELECT u.*,r.name role_name,r.permissions_json FROM users u JOIN roles r ON r.id=u.role_id
               WHERE lower(u.username)=? AND u.deleted_at IS NULL""",
            (username,),
        )
        failure_reason = ""
        if user and not user["is_active"]:
            failure_reason = "user_disabled"
        elif not user:
            failure_reason = "unknown_username"
        elif not password_verify(str(form.get("password", "")), user["password_hash"]):
            failure_reason = "invalid_password"
        if failure_reason:
            db.audit(user, "login_failed", "auth", record_id=username, ip=self.client_address[0], device=self.headers.get("User-Agent"), status="failed", error_message=failure_reason)
            return self.send_html(page("登录", '<div class="error-page"><h1>登录失败</h1><p>用户名或密码不正确。</p><a class="primary button-link" href="/login">重新登录</a></div>'), 401)
        token, csrf = new_token(), new_token(20)
        db.execute(
            "INSERT INTO sessions(token,user_id,csrf_token,expires_at,created_at,last_seen_at) VALUES(?,?,?,?,?,?)",
            (token, user["id"], csrf, expiry_iso(1), now_iso(), now_iso()),
        )
        db.execute("UPDATE users SET last_login_at=?,last_login_ip=? WHERE id=?", (now_iso(), self.client_address[0], user["id"]))
        db.audit(user, "login_success", "auth", ip=self.client_address[0], device=self.headers.get("User-Agent"), status="success")
        return self.redirect("/", f"aaie_session={token}; Path=/; HttpOnly; SameSite=Strict; Max-Age=86400")

    def logout(self, method):
        if method != "POST":
            return self.redirect("/")
        cookie = SimpleCookie(self.headers.get("Cookie", ""))
        token = cookie.get("aaie_session")
        if token:
            db.execute("DELETE FROM sessions WHERE token=?", (token.value,))
        db.audit(self.user, "logout", "auth", ip=self.client_address[0], device=self.headers.get("User-Agent"), status="success")
        return self.redirect("/login", "aaie_session=; Path=/; HttpOnly; SameSite=Strict; Max-Age=0")

    def account_password(self, method):
        if method == "POST":
            current_password = str(self.form.get("current_password", ""))
            new_password = str(self.form.get("new_password", ""))
            confirm_password = str(self.form.get("confirm_password", ""))
            if not password_verify(current_password, self.user["password_hash"]):
                db.audit(
                    self.user, "password_change_failed", "auth", self.user["id"],
                    ip=self.client_address[0], device=self.headers.get("User-Agent"),
                    status="failure", error_message="current password incorrect",
                )
                return self.flash_redirect("/account/password", "当前密码不正确。", "error")
            if len(new_password) < 10:
                return self.flash_redirect("/account/password", "新密码至少需要 10 个字符。", "error")
            if new_password != confirm_password:
                return self.flash_redirect("/account/password", "两次输入的新密码不一致。", "error")
            db.execute(
                "UPDATE users SET password_hash=?,must_change_password=0 WHERE id=?",
                (password_hash(new_password), self.user["id"]),
            )
            db.audit(
                self.user, "password_changed", "auth", self.user["id"],
                ip=self.client_address[0], device=self.headers.get("User-Agent"), status="success",
            )
            return self.flash_redirect("/account/password", "密码已更新。")
        if method != "GET":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        body = f"""
        <div class="account-password-page">
          <section class="panel account-password-panel account-password-card">
            <div class="panel-head account-password-header"><div><h2>修改密码</h2><p class="account-password-intro">每个用户可以在这里修改自己的登录密码。</p></div></div>
            <form class="stack-form narrow-form account-password-form" method="post" action="/account/password">
              <input type="hidden" name="csrf" value="{esc(self.csrf)}">
              <label class="account-password-field">当前密码<input type="password" name="current_password" autocomplete="current-password" required></label>
              <label class="account-password-field">新密码<input type="password" name="new_password" autocomplete="new-password" minlength="10" required><small class="account-password-guidance">至少 10 个字符</small></label>
              <label class="account-password-field">确认新密码<input type="password" name="confirm_password" autocomplete="new-password" minlength="10" required></label>
              <div class="form-submit account-password-actions"><a class="ghost button-link account-password-secondary-action" href="/">取消</a><button class="primary account-password-primary-action">保存新密码</button></div>
            </form>
          </section>
        </div>"""
        message, kind = self.message()
        self.send_html(page("修改密码", body, self.user, self.csrf, "", nas.status(), message, kind))

