    def view_mode_switch(self, method, mode):
        if method != "GET":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        target = safe_return_path((self.query.get("return_to") or ["/"])[0])
        if mode == MOBILE_MODE and target == "/":
            target = "/mobile"
        elif mode == "desktop" and target == "/mobile":
            target = "/"
        return self.redirect(target, view_mode_cookie(mode))

