    def revenue_action(self, method, action_name, scoped_case_uid=None):
        if not can_access_revenue(self.user):
            return self.error_page("无权限访问该功能。", HTTPStatus.FORBIDDEN)
        if method != "POST":
            return self.error_page("不支持此请求方式。", HTTPStatus.METHOD_NOT_ALLOWED)
        if self.request_view_mode() == MOBILE_MODE:
            return self.error_page("移动端仅提供查看与筛选。", HTTPStatus.FORBIDDEN)
        if not can_perform_revenue_action(self.user, action_name):
            return self.error_page("无权限执行该操作。", HTTPStatus.FORBIDDEN)
        headers = getattr(self, "headers", {})
        payment_json = action_name == "billing/payment" and (
            "application/json" in str(headers.get("Accept", "") or "").lower()
            or str(headers.get("X-Requested-With", "") or "").lower() == "fetch"
        )
        try:
            if scoped_case_uid is None:
                return self._execute_revenue_action(action_name)
            return self._execute_revenue_action(action_name, scoped_case_uid=scoped_case_uid)
        except StorageUnavailable:
            if payment_json:
                return self.json_response({"ok": False, "message": StorageUnavailable.message}, HTTPStatus.SERVICE_UNAVAILABLE)
            return self.error_page(StorageUnavailable.message, HTTPStatus.SERVICE_UNAVAILABLE)
        except ValueError as error:
            detail = str(error)
            if payment_json:
                if "allocation exceeds Fee Item final base" in detail:
                    message = "本次服务费不能超过当前未收金额。"
                elif any(token in detail.lower() for token in (
                    "evidence", "upload", "文件", "png", "jpeg", "pdf",
                    "符号链接", "哈希",
                )):
                    message = "付款凭证无效或上传失败，请选择 PNG、JPG/JPEG 或 PDF 后重试。"
                elif "actual_amount_cents" in detail:
                    message = "请输入有效的实际到账金额。"
                elif "actual AUD amount must equal" in detail:
                    message = "实际到账澳元金额必须等于本次服务费与 GST 合计。"
                elif "actual currency must be" in detail:
                    message = "实际到账币种与付款方式不一致。"
                elif "allocated_base_cents" in detail:
                    message = "请输入有效的本次服务费金额。"
                else:
                    message = "收款未保存，请检查输入后重试。"
                return self.json_response({"ok": False, "message": message}, HTTPStatus.BAD_REQUEST)
            if "Fee Item rule snapshot Contract" in detail or "Fee Item already has a conflicting Contract" in detail:
                return self.error_page(
                    "该收费项目缺少一致的 FullyExecuted 合同关联，请管理员先处理合同权威信息。",
                    HTTPStatus.BAD_REQUEST,
                )
            return self.error_page(
                "操作未完成，请检查输入或当前状态。", HTTPStatus.BAD_REQUEST
            )
        except (LookupError, sqlite3.Error, OSError):
            if payment_json:
                return self.json_response(
                    {"ok": False, "message": "收款未保存，请检查输入或付款凭证后重试。"},
                    HTTPStatus.BAD_REQUEST,
                )
            return self.error_page(
                "操作未完成，请检查输入或当前状态。", HTTPStatus.BAD_REQUEST
            )

    def _execute_revenue_action(self, action_name, scoped_case_uid=None):
        upload_fields = {
            "contracts/upload": "contract_file",
            "master-agent/import": "statement_file",
        }
        upload = None
        if action_name in upload_fields:
            field_name = upload_fields[action_name]
            upload = next(
                (item for item in self.files if item.field_name == field_name and item.filename),
                None,
            )
            if upload is None:
                raise ValueError("请选择需要上传的文件。")
        if action_name == "billing/payment":
            upload = next(
                (
                    item for item in self.files
                    if item.field_name == "payment_evidence" and item.filename
                ),
                None,
            )
        connection = db.connect()
        try:
            if scoped_case_uid:
                scoped_case = connection.execute(
                    """SELECT c.uid,c.student_id
                         FROM revenue_commercial_cases c
                        WHERE c.uid=?""",
                    (scoped_case_uid,),
                ).fetchone()
                if not scoped_case:
                    raise LookupError("Revenue Commercial Case not found")
                if action_name == "billing/payment":
                    owned = connection.execute(
                        """SELECT 1
                             FROM revenue_fee_items f
                             JOIN revenue_commercial_cases c
                               ON c.id=f.commercial_case_id
                            WHERE f.uid=? AND c.uid=? AND f.status!='cancelled'""",
                        (str(self.form.get("fee_item_uid") or ""), scoped_case_uid),
                    ).fetchone()
                elif action_name == "billing/receipt":
                    owned = connection.execute(
                        """SELECT 1
                             FROM revenue_payments p
                             JOIN revenue_client_payment_allocations a
                               ON a.payment_id=p.id
                             JOIN revenue_fee_items f ON f.id=a.fee_item_id
                             JOIN revenue_commercial_cases c
                               ON c.id=f.commercial_case_id
                            WHERE p.uid=? AND c.uid=?""",
                        (str(self.form.get("payment_uid") or ""), scoped_case_uid),
                    ).fetchone()
                else:
                    raise ValueError("scoped Revenue action is not supported")
                if not owned:
                    raise LookupError("Revenue action does not belong to this case")
            message_kind = "success"
            actions = RevenueUIActions(
                connection,
                None,
                int(self.user["id"]),
                str(self.user["role_name"]),
                actor_has_revenue_access=can_access_revenue(self.user),
                legacy_document_root=Path(db.path).parent / "revenue_documents",
            )
            if action_name == "contracts/upload":
                actions.upload_contract(self.form, upload)
                destination, message = "/revenue/contracts", "合同已登记；智能提取不可用时已安全转入管理员人工审核。"
            elif action_name == "contracts/manual-extraction":
                actions.add_manual_contract_extraction(self.form)
                destination, message = "/revenue/contracts?filter=under_review", "人工提取建议已登记，等待管理员确认。"
            elif action_name == "contracts/extraction/review":
                actions.review_contract_extraction(self.form)
                destination, message = "/revenue/contracts?filter=under_review", "合同提取建议已完成审核。"
            elif action_name == "contracts/activate":
                actions.activate_contract(self.form)
                destination, message = "/revenue/contracts?filter=active", "合同版本已由管理员确认激活。"
            elif action_name == "master-agent/import":
                actions.import_master_agent_statement(self.form, upload)
                destination, message = "/revenue/master-agent", "对账单已导入，匹配建议仍需确认。"
            elif action_name == "direct-commission/claim":
                claim_result = actions.issue_direct_claim(self.form)
                destination = "/revenue/direct-commission"
                if claim_result.get("eligibility_status") == "NOT_READY":
                    reason_labels = {
                        "missing_actual_commencement": "尚未确认实际入学",
                        "claim_trigger_not_satisfied": "申领触发条件尚未满足",
                    }
                    reasons = [
                        reason_labels.get(
                            str(item.get("code") or ""),
                            "缺少申领所需文件" if str(item.get("code") or "").startswith("missing_required_document:")
                            else "申领条件尚未满足",
                        )
                        for item in claim_result.get("reasons") or []
                    ]
                    message = "尚不可申领：" + "；".join(dict.fromkeys(reasons))
                    message_kind = "warning"
                else:
                    message = "佣金申领已签发。"
            elif action_name == "direct-commission/invoice":
                actions.issue_direct_commission_invoice(self.form)
                destination, message = "/revenue/direct-commission", "直接佣金发票已签发。"
            elif action_name == "direct-commission/payment":
                actions.record_direct_commission_payment(self.form)
                destination, message = "/revenue/direct-commission", "机构佣金收款已确认并对账。"
            elif action_name == "master-agent/match/confirm":
                actions.confirm_master_agent_match(self.form)
                destination, message = "/revenue/master-agent", "一级代理匹配已确认。"
            elif action_name == "master-agent/invoice":
                actions.issue_master_agent_invoice(self.form)
                destination, message = "/revenue/master-agent", "一级代理发票已签发。"
            elif action_name == "master-agent/payment":
                actions.record_master_agent_payment(self.form)
                destination, message = "/revenue/master-agent", "一级代理收款已确认并对账。"
            elif action_name == "billing/payment":
                actions.record_client_payment(self.form, upload)
                destination = (
                    desktop_case_url(scoped_case_uid)
                    if scoped_case_uid else "/revenue/billing"
                )
                message = "客户收款已确认并分配。"
            elif action_name == "billing/receipt":
                company = contract_company_payload()
                actions.issue_client_receipt(
                    self.form,
                    issuer_name=str(company["company_legal_name"]),
                    issuer_abn=str(company["company_abn_acn"]),
                )
                destination = (
                    desktop_case_url(scoped_case_uid)
                    if scoped_case_uid else "/revenue/billing"
                )
                message = "客户收据已正式签发。"
            elif action_name == "cases/tuition":
                result = actions.record_structured_tuition(self.form)
                destination = desktop_case_url(result["commercial_case_uid"])
                message = "结构化学费已确认。"
            elif action_name == "cases/commencement":
                result = actions.confirm_actual_commencement(self.form)
                destination = desktop_case_url(result["commercial_case_uid"])
                message = "实际入学日期已确认。"
            else:
                raise ValueError("unknown Revenue action")
            connection.commit()
        except Exception:
            connection.rollback()
            raise
        finally:
            db._release_connection(connection)
        headers = getattr(self, "headers", {})
        payment_json = action_name == "billing/payment" and (
            "application/json" in str(headers.get("Accept", "") or "").lower()
            or str(headers.get("X-Requested-With", "") or "").lower() == "fetch"
        )
        if payment_json:
            return self.json_response({
                "ok": True,
                "message": message,
                "redirect": destination,
            })
        return self.flash_redirect(destination, message, message_kind)

    def revenue_document(self, method, document_uid, disposition):
        """Serve immutable Revenue evidence without exposing its filesystem path."""
        if not can_access_revenue(self.user):
            return self.error_page("无权限访问该功能。", HTTPStatus.FORBIDDEN)
        if method != "GET":
            return self.error_page("不支持此请求方式。", HTTPStatus.METHOD_NOT_ALLOWED)
        document = db.one("SELECT * FROM revenue_documents WHERE uid=?", (document_uid,))
        if not document:
            return self.error_page("Revenue 文件不存在。", HTTPStatus.NOT_FOUND)
        allowed_mime_types = {"application/pdf", "image/png", "image/jpeg"}
        mime_type = str(document["mime_type"] or "")
        if mime_type not in allowed_mime_types:
            return self.error_page("Revenue 文件类型不允许查看。", HTTPStatus.NOT_FOUND)
        from revenue.secure_storage import read_reference, StorageUnavailable
        from revenue.storage_locations import resolve_location
        try:
            payload = read_reference(
                Path(db.path).parent / "revenue_documents",
                resolve_location(document, db.all),
                str(document["sha256"]), int(document["size_bytes"]),
                secure_root=os.environ.get("REVENUE_SECURE_STORAGE_ROOT") or None,
            )
        except (StorageUnavailable, OSError, ValueError, TypeError):
            return self.error_page("Revenue 文件不可用。", HTTPStatus.NOT_FOUND)
        extension = {"application/pdf": ".pdf", "image/png": ".png", "image/jpeg": ".jpg"}[mime_type]
        filename = f"{document['document_kind']}-{document_uid}{extension}"
        self.send_response(HTTPStatus.OK)
        self.send_header("Content-Type", mime_type)
        self.send_header("Content-Length", str(len(payload)))
        self.send_header("Cache-Control", "private, no-store")
        self.send_header("X-Content-Type-Options", "nosniff")
        response_disposition = "attachment" if disposition == "download" else "inline"
        self.send_header(
            "Content-Disposition",
            f"{response_disposition}; filename*=UTF-8''{quote(filename)}",
        )
        self.end_headers()
        self.wfile.write(payload)

