    def dashboard(self, method):
        request_headers = getattr(self, "headers", {})
        cookie_header = request_headers.get("Cookie", "")
        user_agent = request_headers.get("User-Agent", "")
        if (
            resolve_view_mode(cookie_header, user_agent, "/") != MOBILE_MODE
            and resolve_view_mode(cookie_header, user_agent, "/mobile") == MOBILE_MODE
        ):
            return self.redirect("/", view_mode_cookie("desktop"))
        if self.request_view_mode() == MOBILE_MODE:
            return self.mobile_dashboard(method)
        from dashboard_read_context import DashboardReadContext

        with DashboardReadContext(db) as read_context:
            return self._dashboard_read_snapshot(method, read_context)

    def _dashboard_read_snapshot(self, method, read_context):
        melbourne_today = datetime.now(ZoneInfo("Australia/Melbourne")).date()
        final_workflow_stage = WORKFLOW_STAGES[-1][0]
        kpi_connection = db.connect()
        try:
            dashboard_kpis = load_dashboard_kpis(
                kpi_connection,
                melbourne_today,
                final_workflow_stage=final_workflow_stage,
                workflow_stage_aliases=WORKFLOW_STAGE_ALIASES,
                read_context=read_context,
            )
        finally:
            db._release_connection(kpi_connection)
        kpi_cards_html = dashboard_kpi_cards_html(dashboard_kpis)
        stage_connection = db.connect()
        try:
            application_stage_students = load_application_stage_distribution(stage_connection, read_context=read_context)
        finally:
            db._release_connection(stage_connection)
        stage_chart_html = dashboard_workflow_distribution_chart_html(application_stage_students)
        transfer_v2_stage_cards_html = dashboard_transfer_v2_stage_cards_html(
            application_stage_students
        )
        recent = db.all(
            """SELECT s.student_id,s.passport_first_name,s.passport_last_name,s.created_date
               FROM students s
               WHERE s.deleted_at IS NULL
               ORDER BY s.created_date DESC LIMIT 8"""
        )
        recent_summary_connection = db.connect()
        try:
            recent_summaries = load_student_management_summary_map(
                recent_summary_connection,
                (row["student_id"] for row in recent),
                read_context=read_context,
            )
        finally:
            db._release_connection(recent_summary_connection)

        def recent_student_row_html(row):
            student_id = str(row["student_id"])
            summary = recent_summaries.get(student_id)
            name = (
                summary.student_name
                if summary is not None
                else " ".join(
                    part for part in (row["passport_first_name"], row["passport_last_name"])
                    if part
                ) or student_id
            )
            stage_key = summary.stage_key if summary is not None else "not-recorded"
            stage_label = summary.stage_label if summary is not None else "未记录"
            final_school_name = summary.final_school_name if summary is not None else ""
            applying_year_level = summary.applying_year_level if summary is not None else ""
            created_at = summary.created_at if summary is not None and summary.created_at else row["created_date"]
            created_date = dashboard_recent_created_date(created_at)
            return (
                f'<tr><td><a href="/students/{esc(student_id)}">{esc(student_id)}</a></td>'
                f'<td><a href="/students/{esc(student_id)}"><strong>{esc(name)}</strong></a></td>'
                f'<td><span class="status application-stage-{esc(stage_key or "not-recorded")}">{esc(stage_label or "未记录")}</span></td>'
                f'<td>{esc(final_school_name or "待确认")}</td>'
                f'<td>{esc(applying_year_level or "未记录")}</td>'
                f'<td class="dashboard-recent-created-date">{esc(created_date)}</td></tr>'
            )

        rows = "".join(recent_student_row_html(row) for row in recent) or '<tr><td colspan="6" class="empty">尚无学生记录</td></tr>'
        signed_institution_structure = dashboard_signed_institution_structure_data()
        signed_institution_structure_html = dashboard_signed_institution_structure_chart_html(signed_institution_structure)
        dashboard_workflow_chart_css = '<link rel="stylesheet" href="/assets/dashboard-workflow-distribution-chart-v1.css?v=10">'
        dashboard_signed_institution_css = '<link rel="stylesheet" href="/assets/dashboard-signed-institution-structure-chart-v1.css?v=4">'
        body = f"""
        {dashboard_workflow_chart_css}
        {dashboard_signed_institution_css}
        <section class="dashboard-hero panel">
          <div><span class="eyebrow">AAIE Operations</span><h2>工作台</h2><p>集中查看学生建档、材料审核、家长表单和签证提醒。</p></div>
          <div class="dashboard-actions"><a class="primary button-link" href="/students/new">新建学生</a><a class="parent-link-action button-link" href="/parent-links">生成家长表单</a></div>
        </section>
        {kpi_cards_html}
        {signed_institution_structure_html}
        {transfer_v2_stage_cards_html}
        <div class="dashboard-chart-grid">
          <section class="panel dashboard-recent-panel"><div class="panel-head"><div><h2>最近学生</h2><p>按建档时间显示</p></div><a class="secondary button-link" href="/students">查看全部</a></div>
          <div class="table-wrap"><table class="dashboard-recent-table"><thead><tr><th>Student ID</th><th>学生</th><th>申请阶段</th><th>最终确认学校</th><th>申请年级</th><th>创建日期</th></tr></thead><tbody>{rows}</tbody></table></div></section>
          {stage_chart_html}
        </div>"""
        message, kind = self.message()
        self.send_html(page("工作概览", body, self.user, self.csrf, "dashboard", nas.status(), message, kind))

    def api_topbar_status(self, method):
        if method != "GET":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        health = STAGING.health_snapshot() if STAGING else cached_system_health_snapshot()
        active = active_users_snapshot()
        overall_ok = bool(health.get("overall_ok"))
        data_mode = health.get("data_mode") or {}
        return self.json_response({
            "health": {
                "headline": health["headline"],
                "overall_ok": overall_ok,
                "core_ok": bool(health.get("core_ok", overall_ok)),
                "services_ok": bool(health.get("services_ok", overall_ok)),
                "monitor_ok": bool(health.get("monitor_ok", overall_ok)),
                "external_link_ok": bool(health.get("external_link_ok", overall_ok)),
                "data_mode": data_mode.get("key", "UNKNOWN"),
                "state": health.get("state", "ok" if overall_ok else "warning"),
                "symbol": health.get("symbol", "OK" if overall_ok else "!"),
            },
            "active_users": active,
        })

    def parent_activity_latest_cursor(self):
        row = db.one(
            """SELECT MAX(latest_at) latest_at FROM (
                 SELECT MAX(event_at) latest_at FROM contract_signing_logs
                  WHERE event_type IN ('link_opened','wechat_bound','wechat_login','signed')
                 UNION ALL
                 SELECT MAX(viewed_at) latest_at FROM school_plan_report_view_logs
                  WHERE event_type IN ('link_opened','viewer_opened','wechat_bound','wechat_login','confirmed')
                 UNION ALL
                 SELECT MAX(submitted_at) latest_at FROM visa_form_assignments
                  WHERE status='Submitted' AND submitted_at IS NOT NULL
                 UNION ALL
                 SELECT MAX(created_at) latest_at FROM reminders
                  WHERE source_type LIKE 'business_event:%'
               )"""
        )
        latest_candidates = [
            (row["latest_at"] if row else "") or "",
            latest_parent_form_activity_at(db),
        ]
        return max(latest_candidates) or now_iso()

    def parent_activity_student_name(self, row):
        name = " ".join(part for part in [row["passport_first_name"], row["passport_last_name"]] if part)
        return name or row["student_id"] or "未关联学生"

    def parent_activity_contract_events(self, since):
        rows = db.all(
            """SELECT l.id log_id,l.event_at,l.event_type,l.wechat_nickname,
                      c.id contract_id,c.contract_uid,c.contract_title,c.contract_status,c.student_id,
                      s.passport_first_name,s.passport_last_name
               FROM contract_signing_logs l
               JOIN contracts c ON c.id=l.contract_id
               LEFT JOIN students s ON s.student_id=c.student_id
               WHERE l.event_type IN ('wechat_bound','wechat_login')
                 AND l.event_at>?
               ORDER BY l.event_at ASC,l.id ASC
               LIMIT 60""",
            (since,),
        )
        events = []
        for row in rows:
            student_name = self.parent_activity_student_name(row)
            uid = row["contract_uid"] or f"CONTRACT-{row['contract_id']}"
            event_type = row["event_type"] or ""
            if event_type == "link_opened":
                title = "家长已打开合同签署链接"
                kind = "info"
            elif event_type in {"wechat_bound", "wechat_login"}:
                title = "家长已微信登录"
                kind = "success"
            else:
                title = "家长已签署合同"
                kind = "success"
            href = f"/students/{quote(str(row['student_id']))}?tab=contracts#contracts-section" if row["student_id"] else "/contracts?view=list#contracts-section"
            events.append({
                "id": f"contract:{row['log_id']}",
                "type": f"parent_contract_{event_type}",
                "kind": kind,
                "title": title,
                "message": f"{title}：{student_name} / {uid}",
                "student_id": row["student_id"] or "",
                "student_name": student_name,
                "reference": uid,
                "entry_type": "合同在线签署",
                "event_at": row["event_at"],
                "href": href,
                "refresh": ["contracts"],
            })
        return events

    def parent_activity_school_plan_events(self, since):
        rows = db.all(
            """SELECT l.id log_id,l.viewed_at event_at,l.event_type,l.wechat_nickname,
                      r.id report_id,r.report_title,r.report_version,r.status,r.student_id,
                      s.passport_first_name,s.passport_last_name,
                      v.viewer_role,v.viewer_name
               FROM school_plan_report_view_logs l
               JOIN school_plan_reports r ON r.id=l.report_id
               LEFT JOIN students s ON s.student_id=r.student_id
               LEFT JOIN school_plan_report_viewers v ON v.id=l.viewer_id
               WHERE l.event_type IN ('link_opened','viewer_opened','wechat_bound','wechat_login','confirmed')
                 AND l.viewed_at>?
               ORDER BY l.viewed_at ASC,l.id ASC
               LIMIT 60""",
            (since,),
        )
        events = []
        for row in rows:
            student_name = self.parent_activity_student_name(row)
            label = f"School Plan v{row['report_version'] or ''}".strip()
            event_type = row["event_type"] or ""
            if event_type in {"link_opened", "viewer_opened"}:
                title = "家长正在查看学校计划"
                kind = "info"
            elif event_type in {"wechat_bound", "wechat_login"}:
                title = "家长已微信登录"
                kind = "success"
            else:
                title = "家长已同意学习计划"
                kind = "success"
            events.append({
                "id": f"school_plan:{row['log_id']}",
                "type": f"parent_plan_{event_type}",
                "kind": kind,
                "title": title,
                "message": f"{title}：{student_name} / {label}",
                "student_id": row["student_id"] or "",
                "student_name": student_name,
                "reference": label,
                "entry_type": "学校计划",
                "event_at": row["event_at"],
                "href": f"/school-plan-reports/{quote(str(row['report_id']))}",
                "refresh": ["school_plan"],
            })
        return events

    def parent_activity_visa_information_events(self, since):
        rows = db.all(
            """SELECT a.id assignment_id,a.submitted_at event_at,a.form_type,a.visa_case_id,
                      r.id respondent_id,r.respondent_type,r.respondent_name,
                      vc.student_id,
                      s.passport_first_name,s.passport_last_name
               FROM visa_form_assignments a
               JOIN visa_information_collection_respondents r ON r.id=a.respondent_id
               JOIN visa_cases vc ON vc.id=a.visa_case_id
               LEFT JOIN students s ON s.student_id=vc.student_id
               WHERE a.status='Submitted'
                 AND a.submitted_at IS NOT NULL
                 AND a.submitted_at>?
               ORDER BY a.submitted_at ASC,a.id ASC
               LIMIT 60""",
            (since,),
        )
        events = []
        for row in rows:
            form_label = self.visa_information_collection_form_type_label(row["form_type"])
            respondent_type_label = self.visa_information_collection_respondent_type_label(row["respondent_type"])
            respondent_label = row["respondent_name"] or respondent_type_label
            student_name = self.parent_activity_student_name(row)
            href = (
                f"/students/{quote(str(row['student_id']))}/visa-cases/{quote(str(row['visa_case_id']))}"
                f"/information-collection/respondents/{quote(str(row['respondent_id']))}/content"
            )
            events.append({
                "id": f"visa_information:{row['assignment_id']}:{row['event_at']}",
                "type": "visa_information_collection_submitted",
                "kind": "success",
                "title": f"家长已提交 {form_label}",
                "message": f"家长已提交 {form_label}：{student_name} / {respondent_type_label} {respondent_label}",
                "student_id": row["student_id"] or "",
                "student_name": student_name,
                "reference": form_label,
                "entry_type": "申请人信息采集",
                "event_at": row["event_at"],
                "href": href,
                "refresh": ["visa_information_collection"],
            })
        return events

    def api_parent_activity_notifications(self, method):
        if method != "GET":
            return self.json_response({"ok": False, "error": "method_not_allowed"}, HTTPStatus.METHOD_NOT_ALLOWED)
        if not self.user:
            return self.json_response({"ok": False, "error": "login_required"}, HTTPStatus.UNAUTHORIZED)
        since = str((self.query.get("since") or [""])[0]).strip()
        latest = self.parent_activity_latest_cursor()
        if not since:
            return self.json_response({"ok": True, "events": [], "cursor": latest})
        events = (
            self.parent_activity_contract_events(since)
            + self.parent_activity_school_plan_events(since)
            + self.parent_activity_visa_information_events(since)
            + parent_form_activity_notifications(db, since)
            + business_event_notifications(db, since)
        )
        events.sort(key=lambda item: (item.get("event_at") or "", item.get("id") or ""))
        events = events[:40]
        cursor = max([latest] + [event.get("event_at") or "" for event in events])
        return self.json_response({"ok": True, "events": events, "cursor": cursor})

