    def api_assistant_query(self, method):
        if method not in {"GET", "POST"}:
            return self.json_response({"ok": False, "error": "Method Not Allowed", "readonly": True}, HTTPStatus.METHOD_NOT_ALLOWED)
        if not any(can_access_module(self.user, key) for key in ("dashboard", "students", "applications", "offer", "coe_oshc", "data_update_centre")):
            return self.json_response({"ok": False, "error": "Access Denied", "readonly": True}, HTTPStatus.FORBIDDEN)
        if method == "GET":
            question = (self.query.get("q") or self.query.get("question") or [""])[0]
        else:
            form = getattr(self, "form", None)
            if form is None:
                form, _files = parse_request_body(self)
            question = form.get("q") or form.get("question") or form.get("query") or ""
            if isinstance(question, list):
                question = question[0] if question else ""
        from assistant_readonly import query_assistant

        result = query_assistant(db, question)
        status = HTTPStatus.OK if result.get("ok") else HTTPStatus.BAD_REQUEST
        return self.json_response(result, status)

    def can_use_state_fee_api(self):
        return any(
            can_access_module(self.user, module_key)
            for module_key in ("school_library", "students", "contract_management_center", "system_settings")
        )

    def api_state_fee_schedule_active(self, method):
        if method != "GET":
            return self.json_response({"ok": False, "error": "Method Not Allowed"}, HTTPStatus.METHOD_NOT_ALLOWED)
        if not self.can_use_state_fee_api():
            db.audit(self.user, "state_fee_schedule_api_access_denied", "system_settings", ip=self.client_address[0], device=self.headers.get("User-Agent"), status="failed")
            return self.json_response({"ok": False, "error": "Access Denied"}, HTTPStatus.FORBIDDEN)
        state = (self.query.get("state") or ["VIC"])[0]
        sector = (self.query.get("sector") or ["Government"])[0]
        year = (self.query.get("effective_year") or [""])[0]
        schedule = active_state_fee_schedule(state, sector, int(year) if str(year).isdigit() else None)
        payload = state_fee_schedule_payload(schedule, include_items=True)
        db.audit(self.user, "state_fee_schedule_api_read", "system_settings", record_id=schedule["id"] if schedule else "", new_value=json.dumps({"state": state, "sector": sector, "effective_year": year}, ensure_ascii=False), ip=self.client_address[0], device=self.headers.get("User-Agent"))
        return self.json_response({"ok": bool(payload), "schedule": payload})

    def api_state_fee_estimate(self, method):
        if method != "GET":
            return self.json_response({"ok": False, "error": "Method Not Allowed"}, HTTPStatus.METHOD_NOT_ALLOWED)
        if not self.can_use_state_fee_api():
            db.audit(self.user, "state_fee_estimate_api_access_denied", "system_settings", ip=self.client_address[0], device=self.headers.get("User-Agent"), status="failed")
            return self.json_response({"ok": False, "error": "Access Denied"}, HTTPStatus.FORBIDDEN)
        state = (self.query.get("state") or ["VIC"])[0]
        sector = (self.query.get("sector") or ["Government"])[0]
        year_level = (self.query.get("year_level") or ["Year 9"])[0]
        yes_values = {"yes", "true", "1", "是", "y"}
        need_homestay = str((self.query.get("need_homestay") or ["No"])[0]).strip().lower() in yes_values
        need_arrival_support = str((self.query.get("need_arrival_support") or ["No"])[0]).strip().lower() in yes_values
        need_accommodation_placement = str((self.query.get("need_accommodation_placement") or ["No"])[0]).strip().lower() in yes_values
        payload = state_fee_estimate_payload(state, sector, year_level, need_homestay, need_arrival_support, need_accommodation_placement)
        db.audit(self.user, "state_fee_estimate_api_read", "system_settings", new_value=json.dumps(payload["input"], ensure_ascii=False), ip=self.client_address[0], device=self.headers.get("User-Agent"))
        return self.json_response({"ok": bool(payload["schedule"]), "estimate": payload})

