    def school_feature_tags_html(self, tags_json):
        try:
            raw_tags = json.loads(tags_json or "[]")
        except json.JSONDecodeError:
            raw_tags = []
        tags = []
        seen = set()
        for tag in raw_tags:
            display_tag = school_feature_tag_display_zh(tag)
            key = display_tag.casefold()
            if display_tag and key not in seen:
                tags.append(display_tag)
                seen.add(key)
        if not tags:
            return '<span class="muted-line">暂无标签</span>'
        return '<div class="school-feature-tags">' + "".join(f"<span>{esc(tag)}</span>" for tag in tags) + "</div>"

