        if self.school_is_private_school(school) or not school_uses_state_fee_schedule(school):
            return ""
        schedule = active_state_fee_schedule(school["state"], school_state_fee_sector(school))
        if not schedule:
            return ""
        items = state_fee_items(schedule["id"])
        matched_tuition_items = state_fee_tuition_items_for_school(items, school)
        if not matched_tuition_items:
            return ""
        rows = "".join(
            f"""<tr><td><strong>{esc(item['fee_name'])}</strong><small>{esc(item['school_level'] or '')} · {esc(item['year_level_from'] or '')}{' - ' + esc(item['year_level_to']) if item['year_level_to'] else ''}</small></td><td>{esc(state_fee_amount_text(item))}</td></tr>"""
            for item in matched_tuition_items
        )
        return f"""<div class="wide public-school-fee-display">
          <h4>学费</h4>
          <div class="table-wrap state-fee-compact-table"><table><thead><tr><th>费用项目</th><th>金额</th></tr></thead><tbody>{rows}</tbody></table></div>
        </div>"""

