    def school_option_tags(self, options, selected=""):
        return "".join(
            f'<option value="{esc(value)}" {"selected" if selected == value else ""}>{esc(label)}</option>'
            for value, label in options
        )

    def school_filter_option_tags(self, options, selected="", empty_label="全部"):
        return f'<option value="">{esc(empty_label)}</option>' + self.school_option_tags(options, selected)

    def school_filter_options_without(self, options, excluded_values):
        excluded_values = {str(value) for value in excluded_values}
        return [(value, label) for value, label in options if str(value) not in excluded_values]

    def school_year_pattern_filter_option_tags(self, selected="", empty_label="全部模式"):
        tags = [f'<option value="" data-default-label="{esc(empty_label)}">{esc(empty_label)}</option>']
        rendered_values = set()
        for value, label in SCHOOL_YEAR_PATTERN_OPTIONS:
            rendered_values.add(value)
            act_label = SCHOOL_ACT_YEAR_PATTERN_FILTER_LABELS.get(value, "")
            tags.append(
                f'<option value="{esc(value)}" data-default-label="{esc(label)}" data-act-year-pattern="{"true" if value in SCHOOL_ACT_YEAR_PATTERN_FILTER_VALUES else "false"}" data-act-label="{esc(act_label)}" {"selected" if selected == value else ""}>{esc(label)}</option>'
            )
        for value, act_label in SCHOOL_ACT_YEAR_PATTERN_FILTER_LABELS.items():
            if value in rendered_values:
                continue
            tags.append(
                f'<option value="{esc(value)}" data-default-label="{esc(act_label)}" data-act-year-pattern="true" data-act-label="{esc(act_label)}" {"selected" if selected == value else ""}>{esc(act_label)}</option>'
            )
        return "".join(tags)

    def school_year_pattern_filter_sql(self, alias, year_pattern):
        pattern = str(year_pattern or "").strip()
        alias = alias or "s"
        if not pattern:
            return "", []
        if pattern == "Unknown":
            return f"COALESCE({alias}.accepted_international_year_level_pattern,'Unknown') IN ('','Unknown')", []

        if pattern == "PrimaryOnly":
            target_numbers = list(range(1, 7))
            pattern_values = ["PrimaryOnly", "AllYears", "PrepToYear12", "Year1ToYear12"]
        elif pattern == "Custom":
            target_numbers = [7, 8, 9, 10]
            pattern_values = ["Custom"]
        else:
            target = {
                "Year7Plus": 7,
                "Year8Plus": 8,
                "Year9Plus": 9,
                "Year10Plus": 10,
                "Year11Plus": 11,
            }.get(pattern)
            if target is None:
                target = year_level_number(pattern)
            if target is None:
                return f"{alias}.accepted_international_year_level_pattern=?", [pattern]
            target_numbers = [target]
            pattern_values = [
                value
                for value, levels in SCHOOL_YEAR_PATTERN_LEVELS.items()
                if any(f"Year {target}" == level for level in levels)
            ]
            if pattern not in pattern_values:
                pattern_values.append(pattern)

        clauses = []
        params = []
        if pattern_values:
            placeholders = ",".join("?" for _ in pattern_values)
            clauses.append(f"{alias}.accepted_international_year_level_pattern IN ({placeholders})")
            params.extend(pattern_values)

        for target in target_numbers:
            clauses.append(f"COALESCE({alias}.accepted_international_year_levels,'') LIKE ?")
            params.append(f'%"Year {target}"%')

            min_labels = [
                value
                for value in SCHOOL_YEAR_VALUES
                if value != "Unknown"
                and year_level_number(value) is not None
                and year_level_number(value) <= target
            ]
            max_labels = [
                value
                for value in SCHOOL_YEAR_VALUES
                if value != "Unknown"
                and year_level_number(value) is not None
                and year_level_number(value) >= target
            ]
            if min_labels and max_labels:
                min_placeholders = ",".join("?" for _ in min_labels)
                max_placeholders = ",".join("?" for _ in max_labels)
                clauses.append(
                    f"({alias}.international_year_level_min IN ({min_placeholders}) "
                    f"AND {alias}.international_year_level_max IN ({max_placeholders}))"
                )
                params.extend(min_labels)
                params.extend(max_labels)

        return " OR ".join(f"({clause})" for clause in clauses), params

    def school_multi_values(self, value):
        if isinstance(value, list):
            return [str(item) for item in value]
        try:
            parsed = json.loads(value or "[]")
            if isinstance(parsed, list):
                return [str(item) for item in parsed]
        except (TypeError, json.JSONDecodeError):
            pass
        return []

