    def school_select_options(self, selected=""):
        rows = db.all("SELECT id,school_name,suburb FROM schools ORDER BY school_name")
        return '<option value="">选择学校</option>' + "".join(
            f'<option value="{row["id"]}" {"selected" if str(selected) == str(row["id"]) else ""}>{esc(row["school_name"])} · {esc(row["suburb"] or "")}</option>'
            for row in rows
        )

    def school_datalist_html(self, list_id):
        rows = db.all("SELECT id,school_name,suburb,state FROM schools ORDER BY school_name")
        options = "".join(
            f'<option value="{row["id"]}" label="{esc(row["school_name"])} · {esc(row["suburb"] or "")} {esc(row["state"] or "")}"></option>'
            for row in rows
        )
        return f'<datalist id="{esc(list_id)}">{options}</datalist>'

    def school_library_name_datalist_html(self, list_id):
        rows = db.all("SELECT id,school_name,suburb,state FROM schools WHERE COALESCE(school_name,'')<>'' ORDER BY school_name")
        options = "".join(
            f'<option value="{esc(row["school_name"])}" label="{esc(row["suburb"] or "")} {esc(row["state"] or "")}" data-school-url="/schools/{row["id"]}" data-school-state="{esc(row["state"] or "")}" data-school-id="{row["id"]}"></option>'
            for row in rows
        )
        return f'<datalist id="{esc(list_id)}">{options}</datalist>'

    def school_card_structured_tags_html(self, row):
        hidden_values = {"", "unknown", "not started", "suburb not started", "approved"}
        values = []
        if "distance_text" in row.keys() and row["distance_text"]:
            values.append(f'{row["distance_text"]} 到输入位置')
        values.extend([
            row["school_gender_type"] if "school_gender_type" in row.keys() else "",
            row["accommodation_type"] if "accommodation_type" in row.keys() else "",
            row["state_senior_certificate"] if "state_senior_certificate" in row.keys() else "",
            row["accepted_international_year_level_pattern"] if "accepted_international_year_level_pattern" in row.keys() else "",
            (row["suburb_data_status"] or row["suburb_reviewed_status"]) if "suburb_data_status" in row.keys() and "suburb_reviewed_status" in row.keys() else "",
        ])
        tags = [
            f"<span>{esc(value)}</span>"
            for value in values
            if str(value or "").strip().lower() not in hidden_values
        ]
        if "offers_ib" in row.keys() and (row["offers_ib"] or "").lower() == "yes":
            tags.append("<span>IB</span>")
        return f'<div class="school-structured-tags">{"".join(tags)}</div>' if tags else ""

    def student_name_suggestions_html(self, list_id):
        rows = db.all(
            """SELECT student_id,passport_first_name,passport_last_name
               FROM students
               WHERE deleted_at IS NULL
                 AND (COALESCE(passport_first_name,'')<>'' OR COALESCE(passport_last_name,'')<>'')
               ORDER BY passport_first_name,passport_last_name,student_id"""
        )
        suggestions = [
            {
                "value": student_display_name(row),
                "student_id": str(row["student_id"] or ""),
                "search": f"{student_display_name(row)} {row['student_id']}".lower(),
            }
            for row in rows
        ]
        payload = (
            json.dumps(suggestions, ensure_ascii=False)
            .replace("&", "\\u0026")
            .replace("<", "\\u003c")
            .replace(">", "\\u003e")
        )
        return f'<script type="application/json" id="{esc(list_id)}">{payload}</script>'

    def school_radius_normalize_query(self, value):
        return re.sub(r"[^a-z0-9]+", "", str(value or "").lower())

    def school_radius_state_from_input(self, value):
        match = re.search(r"\b(VIC|NSW|QLD|SA|WA|ACT|TAS|NT)\b", str(value or ""), flags=re.I)
        return match.group(1).upper() if match else ""

    def school_radius_suburb_lookup_input(self, value, state=""):
        text = re.sub(r"\s+", " ", str(value or "").strip())
        if state:
            text = re.sub(rf"\b{re.escape(str(state).upper())}\b", " ", text, flags=re.I)
        text = re.sub(r"\bAustralia\b", " ", text, flags=re.I)
        text = re.sub(r"\b\d{4}\b", " ", text)
        return re.sub(r"\s+", " ", text.replace(",", " ")).strip()

    def school_radius_detect_input_type(self, value):
        text = str(value or "").strip()
        if re.search(r"\d+\s+\w+", text) or "," in text or re.search(r"\b(street|st|road|rd|avenue|ave|drive|dr|boulevard|blvd|lane|ln|court|ct|parade|pde|highway|hwy)\b", text, flags=re.I):
            return "address"
        return "suburb"

    def school_radius_haversine_km(self, lat1, lng1, lat2, lng2):
        radius = 6371.0088
        phi1 = math.radians(float(lat1))
        phi2 = math.radians(float(lat2))
        d_phi = math.radians(float(lat2) - float(lat1))
        d_lambda = math.radians(float(lng2) - float(lng1))
        a = math.sin(d_phi / 2) ** 2 + math.cos(phi1) * math.cos(phi2) * math.sin(d_lambda / 2) ** 2
        return radius * 2 * math.atan2(math.sqrt(a), math.sqrt(1 - a))

    def school_radius_distance_text(self, km):
        try:
            value = float(km)
        except (TypeError, ValueError):
            return ""
        return f"{value:.1f} km"

    def school_radius_bearing_degrees(self, lat1, lng1, lat2, lng2):
        phi1 = math.radians(float(lat1))
        phi2 = math.radians(float(lat2))
        delta_lng = math.radians(float(lng2) - float(lng1))
        y = math.sin(delta_lng) * math.cos(phi2)
        x = math.cos(phi1) * math.sin(phi2) - math.sin(phi1) * math.cos(phi2) * math.cos(delta_lng)
        return round((math.degrees(math.atan2(y, x)) + 360) % 360, 1)

    def school_radius_direction_label(self, bearing_degrees):
        try:
            degrees = float(bearing_degrees) % 360
        except (TypeError, ValueError):
            return ""
        directions = [
            (22.5, "North"),
            (67.5, "North East"),
            (112.5, "East"),
            (157.5, "South East"),
            (202.5, "South"),
            (247.5, "South West"),
            (292.5, "West"),
            (337.5, "North West"),
            (360.0, "North"),
        ]
        for limit, label in directions:
            if degrees < limit:
                return label
        return "North"

    def school_radius_direction_short(self, direction_label):
        return {
            "North": "N",
            "North East": "NE",
            "East": "E",
            "South East": "SE",
            "South": "S",
            "South West": "SW",
            "West": "W",
            "North West": "NW",
        }.get(str(direction_label or ""), "")

    def school_radius_row_value(self, row, key, default=""):
        try:
            return row[key] if key in row.keys() else default
        except AttributeError:
            return row.get(key, default) if isinstance(row, dict) else default

    def school_radius_row_effective_sector(self, row):
        sector_key = str(self.school_radius_row_value(row, "effective_sector_key") or self.school_radius_row_value(row, "sector_key") or "").strip().lower()
        school_type = str(self.school_radius_row_value(row, "school_type") or "").strip().lower()
        if sector_key in {"public", "government"} or "public" in school_type or "公立" in school_type:
            return "public"
        if sector_key in {"private", "independent"} or "private" in school_type or "independent" in school_type or "私立" in school_type:
            return "private"
        return sector_key

    def school_radius_row_matches_sector(self, row, sector):
        sector = self.school_normalize_sector_filter(sector, "")
        return not sector or self.school_radius_row_effective_sector(row) == sector

    def school_radius_row_matches_year(self, row, year_level):
        year_level = str(year_level or "").strip()
        if not year_level:
            return True
        target = year_level_number(year_level)
        if target is None:
            return True
        min_number = year_level_number(self.school_radius_row_value(row, "international_year_level_min", ""))
        max_number = year_level_number(self.school_radius_row_value(row, "international_year_level_max", ""))
        if min_number is not None and max_number is not None:
            if min_number > max_number:
                min_number, max_number = max_number, min_number
            return min_number <= target <= max_number
        accepted_levels = school_accepted_fee_year_levels(row)
        if accepted_levels:
            accepted_numbers = [year_level_number(level) for level in accepted_levels]
            return target in accepted_numbers
        return True

    def school_radius_cache_row_dict(self, row):
        return {
            "raw_input_text": row["raw_input_text"],
            "normalized_query": row["normalized_query"],
            "input_type": row["input_type"],
            "state": row["state"],
            "formatted_address": row["formatted_address"] or row["raw_input_text"],
            "suburb": row["suburb"] or "",
            "postcode": row["postcode"] or "",
            "latitude": float(row["latitude"]) if row["latitude"] is not None else None,
            "longitude": float(row["longitude"]) if row["longitude"] is not None else None,
            "geocode_source": row["geocode_source"] or "cache",
            "geocoded_at": row["geocoded_at"] or "",
            "geocode_status": row["geocode_status"] or "Resolved",
            "warning_message": row["warning_message"] or "",
        }

    def school_radius_google_api_key(self):
        return os.environ.get("GOOGLE_GEOCODING_API_KEY") or db.setting("google_geocoding_api_key", "")

    def school_radius_geocoding_provider(self):
        provider = (os.environ.get("AAIE_GEOCODING_PROVIDER") or db.setting("geocoding_provider", "osm_nominatim") or "osm_nominatim").strip().lower()
        aliases = {
            "osm": "osm_nominatim",
            "openstreetmap": "osm_nominatim",
            "nominatim": "osm_nominatim",
            "google_geocoding": "google",
        }
        return aliases.get(provider, provider if provider in {"osm_nominatim", "google"} else "osm_nominatim")

    def school_radius_nominatim_user_agent(self):
        return db.setting("nominatim_user_agent", "AAIE-CRM-School-Geocoder/1.0")

    def school_radius_wait_for_nominatim_slot(self):
        global SCHOOL_RADIUS_NOMINATIM_LAST_REQUEST_AT
        with SCHOOL_RADIUS_NOMINATIM_LOCK:
            elapsed = time.monotonic() - SCHOOL_RADIUS_NOMINATIM_LAST_REQUEST_AT
            if elapsed < 1.1:
                time.sleep(1.1 - elapsed)
            SCHOOL_RADIUS_NOMINATIM_LAST_REQUEST_AT = time.monotonic()

    def school_radius_state_code(self, value):
        text = str(value or "").strip()
        if not text:
            return ""
        compact = re.sub(r"[^a-z]+", " ", text.lower()).strip()
        state_names = {
            "new south wales": "NSW",
            "victoria": "VIC",
            "queensland": "QLD",
            "south australia": "SA",
            "western australia": "WA",
            "australian capital territory": "ACT",
            "tasmania": "TAS",
            "northern territory": "NT",
        }
        upper = text.upper()
        if upper in SCHOOL_STATE_CERTIFICATE_BY_STATE:
            return upper
        return state_names.get(compact, upper if upper in SCHOOL_STATE_CERTIFICATE_BY_STATE else "")

    def school_radius_google_candidate(self, item, selected_state):
        components = item.get("address_components", []) if isinstance(item, dict) else []
        state = ""
        suburb = ""
        postcode = ""
        for component in components:
            types = set(component.get("types", []))
            if "administrative_area_level_1" in types:
                state = component.get("short_name") or component.get("long_name") or ""
            if not suburb and ({"locality", "postal_town", "sublocality", "administrative_area_level_2"} & types):
                suburb = component.get("long_name") or component.get("short_name") or ""
            if "postal_code" in types:
                postcode = component.get("long_name") or ""
        location = ((item.get("geometry") or {}).get("location") or {}) if isinstance(item, dict) else {}
        try:
            lat = float(location.get("lat"))
            lng = float(location.get("lng"))
        except (TypeError, ValueError):
            lat = None
            lng = None
        return {
            "formatted_address": item.get("formatted_address", ""),
            "state": self.school_radius_state_code(state) or str(selected_state or "").upper(),
            "suburb": suburb,
            "postcode": postcode,
            "latitude": lat,
            "longitude": lng,
        }

    def school_radius_nominatim_candidate(self, item, selected_state):
        address = item.get("address", {}) if isinstance(item, dict) else {}
        state = self.school_radius_state_code(address.get("state") or address.get("state_district") or selected_state)
        suburb = (
            address.get("suburb")
            or address.get("town")
            or address.get("city")
            or address.get("municipality")
            or address.get("village")
            or address.get("locality")
            or ""
        )
        try:
            lat = float(item.get("lat"))
            lng = float(item.get("lon"))
        except (TypeError, ValueError):
            lat = None
            lng = None
        return {
            "formatted_address": item.get("display_name", ""),
            "state": state or str(selected_state or "").upper(),
            "suburb": suburb,
            "postcode": address.get("postcode", ""),
            "latitude": lat,
            "longitude": lng,
        }

    def school_radius_store_geocode_cache(self, raw_input, state, input_type, candidate, status="Resolved", candidates_json="", warning_message="", source="Google Geocoding API"):
        lookup_input = self.school_radius_suburb_lookup_input(raw_input, state) if input_type == "suburb" else raw_input
        normalized = self.school_radius_normalize_query(lookup_input)
        cache_state = str(candidate.get("state") or state or "").upper()
        now = now_iso()
        db.execute(
            """INSERT INTO school_geocode_cache(raw_input_text,normalized_query,input_type,state,formatted_address,suburb,postcode,
               latitude,longitude,geocode_source,geocoded_at,geocode_status,candidates_json,warning_message,created_at,updated_at)
               VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
               ON CONFLICT(normalized_query,state,input_type) DO UPDATE SET
                 raw_input_text=excluded.raw_input_text,
                 formatted_address=excluded.formatted_address,
                 suburb=excluded.suburb,
                 postcode=excluded.postcode,
                 latitude=excluded.latitude,
                 longitude=excluded.longitude,
                 geocode_source=excluded.geocode_source,
                 geocoded_at=excluded.geocoded_at,
                 geocode_status=excluded.geocode_status,
                 candidates_json=excluded.candidates_json,
                 warning_message=excluded.warning_message,
                 updated_at=excluded.updated_at""",
            (
                raw_input,
                normalized,
                input_type,
                cache_state,
                candidate.get("formatted_address", ""),
                candidate.get("suburb", ""),
                candidate.get("postcode", ""),
                candidate.get("latitude"),
                candidate.get("longitude"),
                source,
                now,
                status,
                candidates_json,
                warning_message,
                now,
                now,
            ),
        )
        return db.one(
            """SELECT * FROM school_geocode_cache
               WHERE normalized_query=? AND state=? AND input_type=?
               ORDER BY updated_at DESC,id DESC LIMIT 1""",
            (normalized, cache_state, input_type),
        )

    def school_radius_fetch_google_geocode(self, raw_input, state, input_type):
        api_key = self.school_radius_google_api_key()
        if not api_key:
            return None, "如果已有缓存经纬度，可以继续使用；如果没有缓存，需要配置 Geocoding API 或手动输入经纬度。"
        query = raw_input if input_type == "address" else f"{raw_input}, {state}, Australia"
        url = "https://maps.googleapis.com/maps/api/geocode/json?" + urlencode({"address": query, "region": "au", "key": api_key})
        try:
            with urllib.request.urlopen(url, timeout=8) as response:
                payload = json.loads(response.read().decode("utf-8", errors="replace"))
        except Exception as exc:
            return None, f"Geocoding API 暂时无法完成识别：{exc}"
        results = payload.get("results") or []
        if payload.get("status") != "OK" or not results:
            return None, "无法识别该区名或地址，请输入更完整的信息，例如 suburb + state，或完整街道地址。"
        candidates = [self.school_radius_google_candidate(item, state) for item in results]
        candidates = [item for item in candidates if item.get("latitude") is not None and item.get("longitude") is not None]
        if not candidates:
            return None, "Geocoding API 返回了地址，但没有可用经纬度。"
        if len(candidates) > 1:
            chosen_state_candidates = [item for item in candidates if item.get("state") == state]
            if len(chosen_state_candidates) != 1:
                self.school_radius_store_geocode_cache(raw_input, state, input_type, candidates[0], status="Ambiguous", candidates_json=json.dumps(candidates, ensure_ascii=False), warning_message="识别到多个可能地址，请选择正确的地址。")
                return None, "识别到多个可能地址，请选择正确的地址。"
            candidates = chosen_state_candidates
        return self.school_radius_store_geocode_cache(raw_input, state, input_type, candidates[0]), ""

    def school_radius_fetch_nominatim_geocode(self, raw_input, state, input_type):
        query = raw_input if input_type == "address" else f"{raw_input}, {state}, Australia"
        params = {
            "q": query,
            "format": "jsonv2",
            "addressdetails": 1,
            "limit": 5,
            "countrycodes": "au",
        }
        url = "https://nominatim.openstreetmap.org/search?" + urlencode(params)
        request = urllib.request.Request(
            url,
            headers={
                "User-Agent": self.school_radius_nominatim_user_agent(),
                "Accept": "application/json",
            },
        )
        try:
            self.school_radius_wait_for_nominatim_slot()
            with urllib.request.urlopen(request, timeout=12) as response:
                payload = json.loads(response.read().decode("utf-8", errors="replace"))
        except Exception as exc:
            return None, f"OpenStreetMap Nominatim 暂时无法完成识别：{exc}"
        if not isinstance(payload, list) or not payload:
            return None, "无法识别该区名或地址，请输入更完整的信息，例如 suburb + state，或完整街道地址。"
        candidates = [self.school_radius_nominatim_candidate(item, state) for item in payload]
        candidates = [item for item in candidates if item.get("latitude") is not None and item.get("longitude") is not None]
        if not candidates:
            return None, "OpenStreetMap Nominatim 返回了地址，但没有可用经纬度。"
        state_candidates = [item for item in candidates if item.get("state") == state]
        if not state_candidates:
            return None, f"OpenStreetMap Nominatim 没有返回 {state} 内的匹配结果，请输入更完整地址。"
        return self.school_radius_store_geocode_cache(
            raw_input,
            state,
            input_type,
            state_candidates[0],
            candidates_json=json.dumps(candidates, ensure_ascii=False),
            source="OpenStreetMap Nominatim",
        ), ""

    def school_radius_fetch_external_geocode(self, raw_input, state, input_type):
        provider = self.school_radius_geocoding_provider()
        if provider == "google":
            return self.school_radius_fetch_google_geocode(raw_input, state, input_type)
        return self.school_radius_fetch_nominatim_geocode(raw_input, state, input_type)

    def school_radius_ambiguous_candidates(self, raw_input, state, input_type):
        text = re.sub(r"\s+", " ", str(raw_input or "").strip())
        if not text:
            return []
        rows = db.all(
            """SELECT * FROM school_geocode_cache
               WHERE state=? AND input_type=? AND raw_input_text LIKE ? AND geocode_status='Resolved'
               ORDER BY raw_input_text LIMIT 8""",
            (state, input_type, f"%{text}%"),
        )
        return [self.school_radius_cache_row_dict(row) for row in rows]

    def school_radius_exact_school_matches(self, raw_input, state=""):
        normalized = self.school_radius_normalize_query(raw_input)
        state = str(state or "").strip().upper()
        if not normalized:
            return []
        state_sql = "AND UPPER(COALESCE(state,''))=?" if state else ""
        params = [state] if state else []
        rows = db.all(
            f"""SELECT * FROM schools
                WHERE deleted_at IS NULL
                  AND COALESCE(school_name,'')<>''
                  {state_sql}
                ORDER BY school_name""",
            params,
        )
        exact_matches = []
        for row in rows:
            possible_names = (
                row["school_name"] if "school_name" in row.keys() else "",
                row["school_name_display"] if "school_name_display" in row.keys() else "",
                row["school_name_english"] if "school_name_english" in row.keys() else "",
            )
            if normalized not in {self.school_radius_normalize_query(name) for name in possible_names if name}:
                continue
            exact_matches.append(row)
        return exact_matches

    def school_radius_infer_school_state(self, raw_input):
        exact_matches = self.school_radius_exact_school_matches(raw_input)
        states = [str(row["state"] or "").strip().upper() for row in exact_matches if str(row["state"] or "").strip()]
        unique_states = sorted(set(states))
        if len(unique_states) == 1:
            return unique_states[0]
        for row in exact_matches:
            lat, lng, _source = self.school_radius_row_coordinates(row)
            state = str(row["state"] or "").strip().upper()
            if lat is not None and lng is not None and state:
                return state
        return unique_states[0] if unique_states else ""

    def school_radius_matching_school_center(self, raw_input, state):
        normalized = self.school_radius_normalize_query(raw_input)
        state = str(state or "").strip().upper()
        if not normalized or not state:
            return None
        exact_matches = self.school_radius_exact_school_matches(raw_input, state)
        for row in exact_matches:
            lat, lng, source = self.school_radius_row_coordinates(row)
            if lat is None or lng is None:
                continue
            school_name = row["school_name"] or raw_input
            suburb = row["suburb"] or ""
            postcode = row["postcode"] or ""
            formatted_address = row["address"] or suburb or school_name
            return {
                "raw_input_text": raw_input,
                "normalized_query": normalized,
                "input_type": "school",
                "state": str(row["state"] or state).strip().upper(),
                "formatted_address": formatted_address,
                "suburb": suburb,
                "postcode": postcode,
                "latitude": lat,
                "longitude": lng,
                "geocode_source": f"CRM school {source or 'coordinates'}",
                "geocoded_at": "",
                "geocode_status": "Resolved",
                "warning_message": "",
                "matched_school_id": row["id"],
                "matched_school_name": school_name,
                "display_label": f"搜索中心：{school_name} 学校位置",
            }
        if exact_matches:
            school_names = "、".join(str(row["school_name"] or raw_input) for row in exact_matches[:3])
            return {
                "geocode_status": "Failed",
                "review_required": True,
                "warning_message": f"已找到学校 {school_names}，但缺少可用坐标，暂时不能作为半径圆心。",
            }
        return None

    def school_radius_resolve_center(self, raw_input, state):
        raw_input = re.sub(r"\s+", " ", str(raw_input or "").strip())
        state = str(state or "").strip().upper()
        input_type = self.school_radius_detect_input_type(raw_input)
        lookup_input = self.school_radius_suburb_lookup_input(raw_input, state) if input_type == "suburb" else raw_input
        normalized = self.school_radius_normalize_query(lookup_input)
        base = {
            "raw_input_text": raw_input,
            "normalized_query": normalized,
            "input_type": input_type,
            "state": state,
            "geocode_status": "Failed",
            "review_required": False,
            "candidates": [],
            "warning_message": "",
            "display_label": "",
            "cbd_label": "",
            "cbd_distance_km": None,
            "cbd_distance_text": "",
            "latitude": None,
            "longitude": None,
        }
        if not raw_input or not state:
            base.update({
                "geocode_status": "Failed",
                "review_required": True,
                "warning_message": "无法识别该区名或地址，请输入更完整的信息，例如 suburb + state，或完整街道地址。",
            })
            return base
        school_center = self.school_radius_matching_school_center(raw_input, state)
        if school_center:
            resolved = {**base, **school_center}
            cbd = SCHOOL_CBD_COORDS.get(state)
            if resolved.get("geocode_status") == "Resolved" and cbd and resolved["latitude"] is not None and resolved["longitude"] is not None:
                cbd_distance = self.school_radius_haversine_km(resolved["latitude"], resolved["longitude"], cbd["latitude"], cbd["longitude"])
                resolved["cbd_label"] = cbd["label"]
                resolved["cbd_distance_km"] = round(cbd_distance, 1)
                resolved["cbd_distance_text"] = f"距 {cbd['label']} 约 {resolved['cbd_distance_km']:.1f} km（以学校位置计算，直线距离）"
            return resolved
        row = db.one(
            """SELECT * FROM school_geocode_cache
               WHERE normalized_query=? AND state=? AND input_type=? AND geocode_status='Resolved'
               ORDER BY updated_at DESC,id DESC LIMIT 1""",
            (normalized, state, input_type),
        )
        if not row and input_type == "suburb":
            row = db.one(
                """SELECT * FROM school_geocode_cache
                   WHERE normalized_query=? AND state=? AND input_type='suburb' AND geocode_status='Resolved'
                   ORDER BY updated_at DESC,id DESC LIMIT 1""",
                (normalized, state),
            )
        mismatch_row = None
        if not row and input_type == "address":
            mismatch_row = db.one(
                """SELECT * FROM school_geocode_cache
                   WHERE normalized_query=? AND input_type=? AND geocode_status='Resolved'
                   ORDER BY updated_at DESC,id DESC LIMIT 1""",
                (normalized, input_type),
            )
            row = mismatch_row
        if not row and input_type == "address" and not re.search(r"^\d+\s+", raw_input):
            candidates = self.school_radius_ambiguous_candidates(raw_input, state, input_type)
            if len(candidates) >= 2:
                base.update({
                    "geocode_status": "Ambiguous",
                    "review_required": True,
                    "candidates": candidates,
                    "warning_message": "识别到多个可能地址，请选择正确的地址。",
                })
                return base
        if not row:
            row, geocode_error = self.school_radius_fetch_external_geocode(lookup_input, state, input_type)
        if not row:
            needs_google_key = self.school_radius_geocoding_provider() == "google" and not self.school_radius_google_api_key()
            base.update({
                "geocode_status": "Needs API Key" if needs_google_key else "Failed",
                "review_required": True,
                "warning_message": geocode_error if not needs_google_key else "如果已有缓存经纬度，可以继续使用；如果没有缓存，需要配置 Geocoding API 或手动输入经纬度。",
            })
            return base
        matched_state = str(row["state"] or "").upper()
        resolved = {**base, **self.school_radius_cache_row_dict(row)}
        resolved["matched_state"] = matched_state
        resolved["state"] = state
        resolved["review_required"] = False
        if mismatch_row and matched_state != state:
            resolved["warning_message"] = f"选择的 State 是 {state}，但地址识别到 {matched_state}。请确认后再使用该结果。"
        if resolved["input_type"] == "suburb":
            if self.school_radius_state_from_input(raw_input) and resolved["formatted_address"]:
                resolved["display_label"] = f"搜索中心：{resolved['formatted_address']}"
            else:
                name = resolved["suburb"] or lookup_input or raw_input
                resolved["display_label"] = f"搜索中心：{name} suburb centre"
        else:
            resolved["display_label"] = f"搜索中心：{raw_input}"
        cbd = SCHOOL_CBD_COORDS.get(state)
        if cbd and resolved["latitude"] is not None and resolved["longitude"] is not None:
            cbd_distance = self.school_radius_haversine_km(resolved["latitude"], resolved["longitude"], cbd["latitude"], cbd["longitude"])
            resolved["cbd_label"] = cbd["label"]
            resolved["cbd_distance_km"] = round(cbd_distance, 1)
            basis = f"以 {resolved['suburb'] or raw_input} 区中心计算" if resolved["input_type"] == "suburb" else "以输入地址计算"
            resolved["cbd_distance_text"] = f"距 {cbd['label']} 约 {resolved['cbd_distance_km']:.1f} km（{basis}，直线距离）"
        return resolved

    def school_radius_row_coordinates(self, row):
        try:
            lat = row["latitude"] if "latitude" in row.keys() else None
            lng = row["longitude"] if "longitude" in row.keys() else None
        except AttributeError:
            lat = row.get("latitude")
            lng = row.get("longitude")
        if lat is not None and lng is not None and str(lat) != "" and str(lng) != "":
            return float(lat), float(lng), "school"
        state = str((row["state"] if "state" in row.keys() else row.get("state", "")) or "").strip().upper()
        for raw_value, input_type in (
            ((row["address"] if "address" in row.keys() else row.get("address", "")), "address"),
            ((row["suburb"] if "suburb" in row.keys() else row.get("suburb", "")), "suburb"),
        ):
            normalized = self.school_radius_normalize_query(raw_value)
            if not normalized or not state:
                continue
            cached = db.one(
                """SELECT * FROM school_geocode_cache
                   WHERE normalized_query=? AND state=? AND input_type=? AND geocode_status='Resolved'
                   ORDER BY updated_at DESC,id DESC LIMIT 1""",
                (normalized, state, input_type),
            )
            if cached and cached["latitude"] is not None and cached["longitude"] is not None:
                return float(cached["latitude"]), float(cached["longitude"]), input_type
        return None, None, ""

    def school_radius_coordinate_source_label(self, source):
        return {
            "school": "School exact coordinates",
            "address": "Address cache fallback",
            "suburb": "Suburb centre fallback",
        }.get(str(source or ""), "")

    def school_radius_project_point(self, center, lat, lng, scale):
        lat_km = (float(lat) - center["latitude"]) * 111.32
        lng_km = (float(lng) - center["longitude"]) * 111.32 * math.cos(math.radians(center["latitude"]))
        return 240 + lng_km * scale, 240 - lat_km * scale

    def school_radius_map_svg(self, center, schools, selected_school_id=""):
        if center.get("geocode_status") != "Resolved":
            return ""
        max_radius = max(SCHOOL_RADIUS_VALUES_KM)
        scale = 190 / max_radius
        cbd = SCHOOL_CBD_COORDS.get(center["state"])
        selected_line = ""
        cbd_node = ""
        school_nodes = []
        if cbd:
            cbd_x, cbd_y = self.school_radius_project_point(center, cbd["latitude"], cbd["longitude"], scale)
            selected_line = f'<line class="school-map-direction-line" x1="240" y1="240" x2="{cbd_x:.1f}" y2="{cbd_y:.1f}"></line>'
            cbd_node = f'<g class="school-map-cbd"><circle cx="{cbd_x:.1f}" cy="{cbd_y:.1f}" r="6"></circle><text x="{cbd_x + 8:.1f}" y="{cbd_y - 8:.1f}">{esc(cbd["label"])}</text></g>'
        for school in schools:
            if school.get("latitude") is None or school.get("longitude") is None:
                continue
            x, y = self.school_radius_project_point(center, school["latitude"], school["longitude"], scale)
            if x < -20 or x > 500 or y < -20 or y > 500:
                continue
            sector_class = "private" if self.school_is_private_school(school) else "public"
            selected_class = " school-map-school-selected" if str(school.get("id") or "") == str(selected_school_id or "") else ""
            label = esc(school.get("school_name") or "School")
            school_nodes.append(
                f'<g class="school-map-school-node school-map-school-{sector_class}{selected_class}">'
                f'<circle cx="{x:.1f}" cy="{y:.1f}" r="5"></circle>'
                f'<text x="{x + 7:.1f}" y="{y - 7:.1f}">{label}</text></g>'
            )
        return f"""<svg class="school-radius-map-svg school-radius-search-map-panel" viewBox="0 0 480 480" role="img" aria-label="学校所在区与 CBD 地图">
          <rect x="0" y="0" width="480" height="480" rx="8"></rect>
          <g class="school-map-compass" aria-label="Compass"><text x="426" y="34">N</text><path d="M432 44 L442 72 L432 66 L422 72 Z"></path><text x="445" y="70">E</text><text x="426" y="96">S</text><text x="402" y="70">W</text></g>
          {cbd_node}
          {selected_line}
          <g class="school-map-center"><circle cx="240" cy="240" r="7"></circle><text x="250" y="226">学校所在区</text></g>
          {''.join(school_nodes)}
        </svg>"""

    def school_radius_leaflet_map_payload(self, center, schools, selected_school_id="", radius_km=None):
        cbd = SCHOOL_CBD_COORDS.get(center.get("state"))
        cbd_payload = None
        if cbd and center.get("cbd_distance_km") is not None:
            cbd_payload = {
                "label": cbd.get("label") or "CBD",
                "latitude": cbd.get("latitude"),
                "longitude": cbd.get("longitude"),
                "distance_km": center.get("cbd_distance_km"),
                "distance_text": center.get("cbd_distance_text") or "",
            }
        return {
            "center": {
                "label": center.get("display_label") or "Search centre",
                "latitude": center.get("latitude"),
                "longitude": center.get("longitude"),
            },
            "cbd": cbd_payload,
            "radius_km": radius_km or max(SCHOOL_RADIUS_VALUES_KM),
            "circle_radii_km": [],
            "schools": [],
        }

    def school_radius_leaflet_map_html(self, center, schools, selected_school_id="", radius_km=None):
        if center.get("geocode_status") != "Resolved":
            return ""
        payload = self.school_radius_leaflet_map_payload(center, schools, selected_school_id, radius_km)
        payload_json = json.dumps(payload, ensure_ascii=False).replace("<", "\\u003c").replace("&", "\\u0026")
        return f"""<div class="school-radius-leaflet-shell school-radius-search-map-panel" data-school-radius-leaflet>
          <link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css">
          <div id="school-radius-leaflet-map" class="school-radius-leaflet-map" data-school-radius-leaflet-map role="img" aria-label="OpenStreetMap radius school search map"></div>
          <script type="application/json" id="school-radius-leaflet-data">{payload_json}</script>
          <script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script>
          <small class="school-radius-map-credit">Leaflet + OpenStreetMap 贡献者</small>
        </div>"""

    def school_radius_map_visual_html(self, context):
        leaflet = context.get("school_radius_leaflet_map_html") or ""
        svg = context.get("school_radius_map_svg") or ""
        if not leaflet:
            return svg
        return f"""{leaflet}
          <details class="school-radius-static-fallback school-radius-search-static-fallback" open><summary>Static radius diagram</summary>{svg}</details>"""

    def school_radius_map_context(self, raw_input, state, rows, radius_km=None, sector="", year_level="", selected_school_id=""):
        center = self.school_radius_resolve_center(raw_input, state)
        try:
            selected_radius = int(radius_km or max(SCHOOL_RADIUS_VALUES_KM))
        except (TypeError, ValueError):
            selected_radius = max(SCHOOL_RADIUS_VALUES_KM)
        if selected_radius not in SCHOOL_RADIUS_VALUES_KM:
            selected_radius = max(SCHOOL_RADIUS_VALUES_KM)
        context = {
            "center": center,
            "circle_radii_km": list(SCHOOL_RADIUS_VALUES_KM),
            "schools_with_distance": [],
            "school_radius_map_svg": "",
            "school_radius_leaflet_map_html": "",
            "radius_km": selected_radius,
            "sector": self.school_normalize_sector_filter(sector, ""),
            "year_level": str(year_level or "").strip(),
            "missing_coordinates_count": 0,
            "approximate_coordinate_count": 0,
            "total_candidate_count": 0,
            "radius_counts": {},
        }
        if center.get("geocode_status") != "Resolved":
            return context
        schools = []
        for row in rows:
            row_data = dict(row)
            if str(row_data.get("state") or "").strip().upper() != str(state or "").strip().upper():
                continue
            if not self.school_radius_row_matches_sector(row_data, context["sector"]):
                continue
            if not self.school_radius_row_matches_year(row_data, context["year_level"]):
                continue
            context["total_candidate_count"] += 1
            lat, lng, source = self.school_radius_row_coordinates(row)
            if lat is None or lng is None:
                context["missing_coordinates_count"] += 1
                continue
            if source != "school":
                context["approximate_coordinate_count"] += 1
            distance = self.school_radius_haversine_km(center["latitude"], center["longitude"], lat, lng)
            bearing = self.school_radius_bearing_degrees(center["latitude"], center["longitude"], lat, lng)
            direction = self.school_radius_direction_label(bearing)
            row_data.update({
                "latitude": lat,
                "longitude": lng,
                "geocode_source": source,
                "coordinate_source_label": self.school_radius_coordinate_source_label(source),
                "distance_km": round(distance, 2),
                "distance_text": self.school_radius_distance_text(distance),
                "direction_label": direction,
                "direction_short": self.school_radius_direction_short(direction),
                "bearing_degrees": bearing,
                "radius_band": next((f"{radius}km" for radius in SCHOOL_RADIUS_VALUES_KM if distance <= radius), "Outside"),
            })
            if distance <= selected_radius:
                schools.append(row_data)
        schools.sort(key=lambda item: (item["distance_km"], item["school_name"]))
        context["schools_with_distance"] = schools
        context["radius_counts"] = {radius: sum(1 for school in schools if school["distance_km"] <= radius) for radius in SCHOOL_RADIUS_VALUES_KM}
        context["school_radius_map_svg"] = self.school_radius_map_svg(center, schools, selected_school_id)
        context["school_radius_leaflet_map_html"] = self.school_radius_leaflet_map_html(center, schools, selected_school_id, selected_radius)
        return context

    def school_radius_filter_panel(self, context):
        if not context:
            return ""
        center = context["center"]
        status = center.get("geocode_status")
        if status != "Resolved":
            candidates = center.get("candidates") or []
            candidate_html = ""
            if candidates:
                candidate_html = "<div class=\"school-radius-candidates\">" + "".join(
                    f'<a class="secondary button-link compact" href="/schools/library?state={esc(center["state"])}&map_center={quote(candidate["formatted_address"])}">{esc(candidate["formatted_address"])}</a>'
                    for candidate in candidates
                ) + "</div>"
            return f"""<section class="panel school-radius-panel">
              <div class="notice warn"><strong>{esc(center.get('warning_message') or '无法识别该区名或地址，请输入更完整的信息，例如 suburb + state，或完整街道地址。')}</strong>{candidate_html}</div>
            </section>"""
        counts = {radius: sum(1 for school in context["schools_with_distance"] if school["distance_km"] <= radius) for radius in SCHOOL_RADIUS_VALUES_KM}
        warning = f'<div class="notice warn">{esc(center["warning_message"])}</div>' if center.get("warning_message") else ""
        school_rows = "".join(
            f"<tr><td>{esc(school['school_name'])}</td><td>{esc(school.get('suburb') or '')}</td><td>{esc(school['distance_text'])}</td><td>{esc(school['radius_band'])}</td></tr>"
            for school in context["schools_with_distance"][:12]
        ) or '<tr><td colspan="4" class="empty">20km 内暂无带坐标学校</td></tr>'
        return f"""<section class="panel school-radius-panel">
          <div class="panel-head"><div><h2>学校地图半径筛选</h2><p>{esc(center['display_label'])}</p><p>{esc(center['cbd_distance_text'])}</p></div></div>
          {warning}
          <div class="school-radius-summary">
            <span>5km 内 <b>{counts[5]}</b></span>
            <span>10km 内 <b>{counts[10]}</b></span>
            <span>15km 内 <b>{counts[15]}</b></span>
            <span>20km 内 <b>{counts[20]}</b></span>
          </div>
          <div class="school-radius-layout">
            {self.school_radius_map_visual_html(context)}
            <div class="table-wrap"><table><thead><tr><th>学校</th><th>Suburb</th><th>到输入位置</th><th>范围</th></tr></thead><tbody>{school_rows}</tbody></table></div>
          </div>
        </section>"""

    def school_radius_candidate_rows(self, state):
        state = str(state or "").strip().upper()
        effective_sector_sql = self.school_effective_sector_sql("s")
        excluded_ids = sorted(SCHOOL_RADIUS_EXCLUDED_SCHOOL_IDS)
        exclusion_sql = ""
        params = [state]
        if excluded_ids:
            placeholders = ",".join("?" for _ in excluded_ids)
            exclusion_sql = f" AND s.id NOT IN ({placeholders})"
            params.extend(excluded_ids)
        return db.all(
            f"""SELECT s.*,c.city_name,c.state city_state,sec.sector_name_zh,
                       {effective_sector_sql} effective_sector_key
                FROM schools s
                LEFT JOIN school_cities c ON c.id=s.city_id
                LEFT JOIN school_sectors sec ON sec.sector_key={effective_sector_sql}
                WHERE UPPER(COALESCE(s.state,''))=?
                  AND s.deleted_at IS NULL
                  {exclusion_sql}
                ORDER BY s.school_name""",
            params,
        )

    def school_radius_query_context(self):
        search_input = (self.query.get("search_input") or self.query.get("map_center") or ["Doncaster"])[0].strip() or "Doncaster"
        submitted_state = (self.query.get("state") or [""])[0].strip().upper()
        input_state = self.school_radius_state_from_input(search_input)
        school_state = self.school_radius_infer_school_state(search_input)
        state = school_state or input_state or submitted_state or "VIC"
        sector = self.school_normalize_sector_filter((self.query.get("sector") or [""])[0].strip(), "")
        year_level = (self.query.get("year_level") or [""])[0].strip()
        selected_school_id = (self.query.get("selected_school_id") or [""])[0].strip()
        try:
            radius_km = int((self.query.get("radius_km") or ["10"])[0])
        except ValueError:
            radius_km = 10
        if radius_km not in SCHOOL_RADIUS_VALUES_KM:
            radius_km = 10
        rows = self.school_radius_candidate_rows(state)
        context = self.school_radius_map_context(search_input, state, rows, radius_km=radius_km, sector=sector, year_level=year_level, selected_school_id=selected_school_id)
        context.update({
            "search_input": search_input,
            "state": state,
            "selected_school_id": selected_school_id,
        })
        return context

    def school_radius_search_controls(self, context):
        state_rows = db.all("SELECT DISTINCT state FROM schools WHERE COALESCE(state,'')<>'' ORDER BY state")
        state_values = list(SCHOOL_STATE_CERTIFICATE_BY_STATE.keys())
        for row in state_rows:
            value = str(row["state"] or "").strip().upper()
            if value and value not in state_values:
                state_values.append(value)
        state_options = "".join(f'<option value="{esc(value)}" {"selected" if context["state"] == value else ""}>{esc(value)}</option>' for value in state_values)
        radius_options = "".join(f'<option value="{radius}" {"selected" if context["radius_km"] == radius else ""}>{radius} km</option>' for radius in SCHOOL_RADIUS_VALUES_KM)
        sector_options = '<option value="">All 全部</option>' + self.school_sector_options(context.get("sector", ""))
        year_options = '<option value="">All Year Levels</option>' + self.school_option_tags(SCHOOL_YEAR_LEVEL_OPTIONS, context.get("year_level", ""))
        school_radius_name_datalist_id = "school-radius-name-suggestions"
        school_radius_name_datalist = self.school_library_name_datalist_html(school_radius_name_datalist_id)
        return f"""<section class="panel school-radius-search-panel school-radius-search-header">
          <div class="panel-head school-radius-search-heading"><div><h2>区域半径找学校 / Radius School Search</h2><p>输入具体地址、suburb 或学校名，按直线距离筛选附近学校。不要把此功能当作 school zone / catchment 查询。</p></div><a class="secondary button-link school-radius-search-secondary-action" href="/schools/library">返回学校资料库</a></div>
          <form class="filter-bar school-radius-search-form school-radius-search-toolbar" method="get" action="/schools/radius-search">
            <label class="wide school-radius-search-field school-radius-search-field-primary">Suburb / 地址 / 学校<input name="search_input" list="{school_radius_name_datalist_id}" value="{esc(context['search_input'])}" placeholder="输入 suburb、具体地址或学校名，例如 Doncaster、36 Somerville Street 或 Balwyn High School" data-school-radius-name-input>{school_radius_name_datalist}</label>
            <label class="school-radius-search-field">State<select name="state" data-school-radius-state-input>{state_options}</select></label>
            <label class="school-radius-search-field">Radius<select name="radius_km">{radius_options}</select></label>
            <label class="school-radius-search-field">学校类型<select name="sector">{sector_options}</select></label>
            <label class="school-radius-search-field">Year Level<select name="year_level">{year_options}</select></label>
            <button class="primary school-radius-search-actions school-radius-search-primary-action">搜索</button>
            <a class="ghost button-link school-radius-search-actions school-radius-search-secondary-action" href="/schools/radius-search">清除筛选</a>
          </form>
        </section>"""

    def school_radius_accepts_international_label(self, school):
        return "Yes"

    def school_radius_result_rows_html(self, context):
        selected_school_id = str(context.get("selected_school_id") or "")
        rows = []
        for school in context["schools_with_distance"]:
            selected_class = " selected" if selected_school_id and selected_school_id == str(school.get("id") or "") else ""
            min_year = school.get("international_year_level_min") or "待补充"
            max_year = school.get("international_year_level_max") or "待补充"
            rows.append(f"""<article class="school-radius-result-card school-radius-search-card{selected_class}">
              <a class="school-radius-result-name school-radius-search-card-name" href="/schools/{school['id']}">{esc(school['school_name'])}</a>
              <div class="school-radius-result-facts school-radius-search-card-facts">
                <span><small>距离</small><b>{school['distance_km']:.2f} km</b></span>
                <span><small>最低年级</small><b>{esc(min_year)}</b></span>
                <span><small>最高年级</small><b>{esc(max_year)}</b></span>
              </div>
            </article>""")
        return "".join(rows) or '<div class="empty compact school-radius-search-empty-state">当前半径和筛选条件内暂无带坐标学校。</div>'

    def school_radius_search(self, method):
        if method != "GET":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        if not can_access_module(self.user, "school_library"):
            return self.school_action_denied("view")
        context = self.school_radius_query_context()
        center = context["center"]
        controls = self.school_radius_search_controls(context)
        export_query = urlencode({
            "search_input": context["search_input"],
            "state": context["state"],
            "radius_km": context["radius_km"],
            "sector": context.get("sector", ""),
            "year_level": context.get("year_level", ""),
        })
        if center.get("geocode_status") != "Resolved":
            body = f"""<div class="school-radius-search-page">{controls}<section class="panel school-radius-results-panel school-radius-search-results">
              <div class="notice warn school-radius-search-warning"><strong>{esc(center.get('warning_message') or '无法识别该区名或地址，请输入更完整的信息。')}</strong></div>
            </section></div>"""
            message, kind = self.message()
            return self.send_html(page("区域半径找学校", body, self.user, self.csrf, "schools", nas.status(), message, kind))
        counts = context.get("radius_counts") or {}
        summary = "".join(f"<span>{radius}km 内 <b>{counts.get(radius, 0)}</b></span>" for radius in SCHOOL_RADIUS_VALUES_KM)
        warning = f'<div class="notice warn school-radius-search-warning">{esc(center["warning_message"])}</div>' if center.get("warning_message") else ""
        missing_note = f"""<div class="notice warn school-radius-search-warning school-radius-search-coordinate-note">有 {context['missing_coordinates_count']} 所符合州/类型/年级条件的学校缺少可用坐标，暂不显示在地图结果中；另有 {context.get('approximate_coordinate_count', 0)} 所使用地址或 suburb 中心点 fallback，不是学校精确位置。距离按直线距离计算，不代表实际开车路线或通勤时间；如果输入 suburb，中心点是 suburb centroid，不代表具体住宅地址。</div>"""
        body = f"""<div class="school-radius-search-page">{controls}
        <section class="panel school-radius-results-panel school-radius-search-results">
          <div class="panel-head school-radius-search-results-header"><div><h2>搜索结果</h2><p>{esc(center['display_label'])}</p><p>{esc(center['cbd_distance_text'])}</p></div><div class="dashboard-actions"><a class="secondary button-link school-radius-search-secondary-action" href="/schools/radius-search/export?{esc(export_query)}">下载 CSV</a></div></div>
          {warning}
          <div class="school-radius-summary school-radius-search-summary">{summary}<span>当前半径 <b>{context['radius_km']}km</b></span><span>结果 <b>{len(context['schools_with_distance'])}</b></span></div>
          <div class="school-radius-layout school-radius-search-layout">
            {self.school_radius_map_visual_html(context)}
            <div class="school-radius-result-list school-radius-search-results-list">{self.school_radius_result_rows_html(context)}</div>
          </div>
          {missing_note}
        </section></div>"""
        db.audit(self.user, "school_radius_search_opened", "school_library", record_id=context["search_input"], new_value=json.dumps({"state": context["state"], "radius_km": context["radius_km"], "sector": context.get("sector", ""), "year_level": context.get("year_level", ""), "results": len(context["schools_with_distance"])}, ensure_ascii=False), ip=self.client_address[0], device=self.headers.get("User-Agent"))
        message, kind = self.message()
        self.send_html(page("区域半径找学校", body, self.user, self.csrf, "schools", nas.status(), message, kind))

    def school_radius_search_export(self, method):
        if method != "GET":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        if not can_access_module(self.user, "school_library"):
            return self.school_action_denied("view")
        context = self.school_radius_query_context()
        output = io.StringIO()
        writer = csv.writer(output)
        writer.writerow([
            "School Name",
            "Distance km",
            "Min Year Level",
            "Max Year Level",
        ])
        for school in context["schools_with_distance"]:
            writer.writerow([
                school.get("school_name") or "",
                f"{school['distance_km']:.2f}",
                school.get("international_year_level_min") or "",
                school.get("international_year_level_max") or "",
            ])
        payload = output.getvalue().encode("utf-8-sig")
        filename = f"radius-school-search-{context['state'].lower()}-{context['radius_km']}km.csv"
        db.audit(self.user, "school_radius_search_exported", "school_library", record_id=context["search_input"], new_value=json.dumps({"rows": len(context["schools_with_distance"]), "state": context["state"], "radius_km": context["radius_km"]}, ensure_ascii=False), ip=self.client_address[0], device=self.headers.get("User-Agent"))
        self.send_response(200)
        self.send_header("Content-Type", "text/csv; charset=utf-8")
        self.send_header("Content-Disposition", f"attachment; filename*=UTF-8''{quote(filename)}")
        self.send_header("Content-Length", str(len(payload)))
        self.end_headers()
        self.wfile.write(payload)

    def school_feature_center_url(self, school_id):
        return f"/schools/collection?feature_school_id={quote(str(school_id))}#features"

    def school_collection_field_checkboxes(self, selected=None):
        selected = set(selected or [])
        return "".join(
            f'<label class="choice"><input type="checkbox" name="selected_fields" value="{esc(value)}" {"checked" if value in selected else ""}><span>{esc(label)}</span></label>'
            for value, label in SCHOOL_COLLECTION_FIELD_OPTIONS
        )

    def data_update_action_by_key(self, action_key):
        for key, label, source_name, description in DATA_UPDATE_ACTIONS:
            if key == action_key:
                return {"key": key, "label": label, "source_name": source_name, "description": description}
        return None

    def data_update_source_for_action(self, action_key):
        action = self.data_update_action_by_key(action_key)
        if not action or not action["source_name"]:
            return None
        return db.one("SELECT * FROM data_sources WHERE source_name=? ORDER BY id LIMIT 1", (action["source_name"],))

    def data_update_status_class(self, status):
        text = str(status or "").lower()
        if "error" in text or "fail" in text:
            return "error"
        if "confirm" in text or "review" in text:
            return "warn"
        if "ready" in text or "success" in text or "manual" in text:
            return "ok"
        return "neutral"

