    def data_update_source_field(self, row, key, default=""):
        try:
            if row and key in row.keys():
                return row[key]
        except Exception:
            pass
        return default

    def data_update_health_risk(self, source, job):
        status = str((job["status"] if job and job["status"] else source["status"]) or "").strip()
        latest_success = self.data_update_source_field(source, "last_successful_update_at")
        needs_confirmation = bool(self.data_update_source_field(source, "requires_admin_confirmation"))
        lowered = status.lower()
        if "error" in lowered or "fail" in lowered:
            return "High", "最近任务失败，需要查看日志。", "error"
        if "confirm" in lowered or "review" in lowered:
            return "Medium", "有结果等待人工确认或复核。", "warn"
        if "running" in lowered:
            return "Medium", "当前有任务处理中。", "warn"
        if not latest_success and needs_confirmation:
            return "Medium", "需要人工确认，尚未记录成功更新时间。", "warn"
        if latest_success or "ready" in lowered or "success" in lowered:
            return "Low", "当前没有阻塞风险。", "ok"
        return "Medium", "暂无足够健康记录，请按现有日志判断。", "neutral"

    def data_update_health_panel(self, sources, latest_jobs, latest_logs):
        cards = []
        summary = {
            "total": 0,
            "needs_confirmation": 0,
            "auto_enabled": 0,
            "medium_or_high_risk": 0,
        }
        for source in sources:
            source_id = source["id"]
            job = latest_jobs.get(source_id)
            status = job["status"] if job and job["status"] else source["status"]
            risk_label, risk_note, risk_class = self.data_update_health_risk(source, job)
            summary["total"] += 1
            summary["needs_confirmation"] += 1 if source["requires_admin_confirmation"] else 0
            summary["auto_enabled"] += 1 if source["auto_check_enabled"] else 0
            summary["medium_or_high_risk"] += 1 if risk_class == "warn" else 0
            source_name = self.data_update_display_text(source["source_name"])
            source_type = self.data_update_display_text(source["source_type"])
            latest_period = source["latest_period"] or (job["source_period"] if job else "") or "待检查"
            last_checked = (source["last_checked_at"] or "")[:19] or "未检查"
            last_success = (source["last_successful_update_at"] or "")[:19] or "未成功更新"
            log_text = latest_logs.get(job["id"], "") if job else "暂无日志"
            source_url = self.data_update_display_text(source["source_url"] or "Manual / internal")
            cards.append(f"""
            <article class="data-update-health-card">
              <div class="data-update-health-card-head">
                <div>
                  <strong>{esc(source_name)}</strong>
                  <small>{esc(source_type)}</small>
                </div>
                <span class="status {self.data_update_status_class(status)}">{esc(self.data_update_display_text(status))}</span>
              </div>
              <dl class="data-update-health-meta">
                <div><dt>来源</dt><dd>{esc(source_url)}</dd></div>
                <div><dt>更新方式</dt><dd>{esc(self.data_update_display_text(source["update_frequency"]))}</dd></div>
                <div><dt>覆盖范围</dt><dd>{esc(source["state"] or source_type or "全系统")}</dd></div>
                <div><dt>最后更新时间</dt><dd>{esc(last_success)}</dd></div>
                <div><dt>最近检查</dt><dd>{esc(last_checked)}</dd></div>
                <div><dt>数据周期</dt><dd>{esc(latest_period)}</dd></div>
                <div><dt>人工确认</dt><dd>{'需要' if source["requires_admin_confirmation"] else '不需要'}</dd></div>
                <div><dt>自动检查</dt><dd>{'开启' if source["auto_check_enabled"] else '关闭'}</dd></div>
              </dl>
              <div class="data-update-health-risk">
                <span class="status {risk_class}">风险 {esc(risk_label)}</span>
                <p>{esc(risk_note)}</p>
              </div>
              <p class="data-update-health-log">{esc(log_text or '暂无日志')}</p>
              <a class="button-link ghost compact" href="/data-updates/logs">查看日志</a>
            </article>""")
        cards_html = "".join(cards) or '<div class="empty">暂无数据源健康记录。</div>'
        summary_html = f"""
          <div class="data-update-health-summary" aria-label="Data Update Centre health summary">
            <span class="data-update-health-summary-card data-update-health-summary-card--sources">数据源 <b>{esc(summary['total'])}</b></span>
            <span class="data-update-health-summary-card data-update-health-summary-card--review">需要确认 <b>{esc(summary['needs_confirmation'])}</b></span>
            <span class="data-update-health-summary-card data-update-health-summary-card--auto">自动检查 <b>{esc(summary['auto_enabled'])}</b></span>
            <span class="data-update-health-summary-card data-update-health-summary-card--risk">中高风险 <b>{esc(summary['medium_or_high_risk'])}</b></span>
          </div>"""
        return f"""
        <section class="panel data-update-health-panel" aria-label="Data Update Centre readonly health panel">
          <div class="panel-head"><div><span class="eyebrow">只读摘要</span><h2>数据源健康状态</h2><p>基于现有 Data Sources、最近任务和日志生成；这里只展示状态，不创建更新任务，也不写入数据库。</p></div><a class="secondary button-link" href="/data-updates/logs">查看全部日志</a></div>
          {summary_html}
          <div class="data-update-health-grid">{cards_html}</div>
        </section>"""

