    def data_update_run(self, method):
        if method != "POST":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        if not can_access_module(self.user, "data_update_centre"):
            return self.error_page("你没有访问数据更新中心的权限。", HTTPStatus.FORBIDDEN)
        action_key = str(self.form.get("action_key", "")).strip()
        selected_actions = [key for key, *_ in DATA_UPDATE_ACTIONS if key != "all"] if action_key == "all" else [action_key]
        created_job_ids = []

        def store_area_update_upload(field_name, action_name, source_state):
            upload = next((file for file in self.files if file.field_name == field_name and file.filename), None)
            if not upload:
                return None
            suffix = Path(upload.filename or "").suffix.lower()
            allowed = {part.strip() for part in AREA_DATA_UPLOAD_ACCEPT.split(",")}
            if suffix not in allowed:
                raise ValueError(f"{field_name} 只支持 {AREA_DATA_UPLOAD_ACCEPT} 文件。")
            folder = APP_DIR / "upload_staging" / "area_data" / action_name / source_state.lower()
            folder.mkdir(parents=True, exist_ok=True)
            stored_path, _ = next_version_path(folder, upload.filename)
            stored_path.write_bytes(upload.data)
            return stored_path

        for key in selected_actions:
            if not data_update_action_definition(key):
                continue
            source_paths = {}
            source_state = str(self.form.get("source_state", "VIC")).strip().upper() or "VIC"
            if source_state not in SCHOOL_DATA_IMPORT_STATES:
                return self.flash_redirect("/data-updates", f"不支持的 State：{source_state}", "error")
            if key in {"rental_market", "crime_statistics"}:
                source_paths["source_state"] = source_state
                try:
                    uploaded = store_area_update_upload(
                        "rental_file" if key == "rental_market" else "crime_file",
                        key,
                        source_state,
                    )
                except ValueError as exc:
                    return self.flash_redirect("/data-updates", str(exc), "error")
                if uploaded:
                    source_paths["rental_file" if key == "rental_market" else "crime_file"] = uploaded
            if key == "school_profile_data":
                upload = next((file for file in self.files if file.field_name == "school_profile_file" and file.filename), None)
                if upload:
                    suffix = Path(upload.filename or "").suffix.lower()
                    if suffix not in {".xlsx", ".xlsm", ".csv"}:
                        return self.flash_redirect("/data-updates", "ACARA School Profile 只支持 XLSX / XLSM / CSV 文件。", "error")
                    folder = APP_DIR / "upload_staging" / "acara_school_profile"
                    folder.mkdir(parents=True, exist_ok=True)
                    stored_path, _ = next_version_path(folder, upload.filename)
                    stored_path.write_bytes(upload.data)
                    source_paths["school_profile_file"] = stored_path
            created_job_ids.append(run_data_update_action(db, key, user_id=self.user["id"], source_paths=source_paths))
        db.audit(self.user, "data_update_job_created", "data_update_centre", record_id=action_key, new_value=json.dumps({"jobs": created_job_ids}, ensure_ascii=False), ip=self.client_address[0], device=self.headers.get("User-Agent"))
        return self.flash_redirect("/data-updates", f"已生成 {len(created_job_ids)} 个更新报告。需要确认的数据必须点击确认更新后才发布。")

    def data_update_logs(self, method):
        if method != "GET":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        if not can_access_module(self.user, "data_update_centre"):
            return self.error_page("你没有访问数据更新中心的权限。", HTTPStatus.FORBIDDEN)
        rows = db.all(
            """SELECT j.id job_id,j.job_type,j.status,j.started_at,j.finished_at,j.records_found,
                      j.records_created,j.records_updated,j.records_failed,j.error_message,
                      ds.source_name,l.level,l.message,l.created_at
               FROM data_update_jobs j
               LEFT JOIN data_sources ds ON ds.id=j.source_id
               LEFT JOIN data_update_logs l ON l.job_id=j.id
               ORDER BY COALESCE(l.id,j.id) DESC LIMIT 200"""
        )
        table_rows = "".join(
            f"""<tr><td>{esc(row['job_id'])}</td><td>{esc(self.data_update_display_text(row['source_name'] or row['job_type']))}</td><td><span class="status {self.data_update_status_class(row['status'])}">{esc(self.data_update_display_text(row['status']))}</span></td><td>{esc((row['created_at'] or row['started_at'] or '')[:19])}</td><td>{esc(self.data_update_display_text(row['level'] or ''))}</td><td>{esc(self.data_update_display_text(row['message'] or ''))}</td><td>{esc(self.data_update_display_text(row['error_message'] or ''))}</td></tr>"""
            for row in rows
        ) or '<tr><td colspan="7" class="empty">暂无更新日志</td></tr>'
        body = f"""<div class="data-update-logs-page">
        <a class="back-link" href="/data-updates">← 返回数据更新中心</a>
        <section class="panel"><div class="panel-head"><div><h2>查看更新日志</h2><p>所有数据更新任务都会写入日志。</p></div></div>
        <div class="table-wrap"><table><thead><tr><th>任务编号</th><th>数据</th><th>状态</th><th>时间</th><th>级别</th><th>日志</th><th>错误信息</th></tr></thead><tbody>{table_rows}</tbody></table></div></section>
        </div>"""
        message, kind = self.message()
        self.send_html(page("数据更新日志", body, self.user, self.csrf, "data_update_centre", nas.status(), message, kind))

    def private_international_fees_review(self, method):
        if method != "GET":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        if not can_access_module(self.user, "data_update_centre"):
            return self.error_page("你没有访问数据更新中心的权限。", HTTPStatus.FORBIDDEN)
        latest_private_international_fee_job_id = db.one(
            """SELECT id
               FROM data_update_jobs
               WHERE job_type='private_international_fees' AND status='Needs Confirmation'
               ORDER BY id DESC LIMIT 1"""
        )
        latest_job_id = latest_private_international_fee_job_id["id"] if latest_private_international_fee_job_id else None
        if latest_job_id:
            records = db.all(
                """SELECT r.*,j.status job_status
                   FROM school_international_fee_records r
                   LEFT JOIN data_update_jobs j ON j.id=r.data_update_job_id
                   WHERE r.data_update_job_id=?
                   ORDER BY r.created_at DESC,r.id DESC""",
                (latest_job_id,),
            )
        else:
            records = db.all(
                """SELECT r.*,j.status job_status
                   FROM school_international_fee_records r
                   LEFT JOIN data_update_jobs j ON j.id=r.data_update_job_id
                   ORDER BY r.created_at DESC,r.id DESC LIMIT 300"""
            )
        cards = []
        for record in records:
            items = db.all("SELECT * FROM school_international_fee_items WHERE fee_record_id=? ORDER BY fee_category,year_level,id", (record["id"],))
            item_rows = "".join(
                f"""<tr><td>{esc(item['fee_category'])}</td><td>{esc(item['year_level'] or 'Unknown')}</td><td>{esc(item['currency'] or 'AUD')} {esc(item['amount_text'] or item['amount'] or '')}</td><td>{esc(item['amount_period'] or '')}</td><td>{esc(item['raw_text'] or '')}</td></tr>"""
                for item in items
            ) or '<tr><td colspan="5" class="empty">未识别到结构化费用项。</td></tr>'
            confirm_hint = (
                f"""<form method="post" action="/data-updates/jobs/{record['data_update_job_id']}/confirm"><input type="hidden" name="csrf" value="{esc(self.csrf)}"><button class="primary compact">确认并写入学校资料</button></form>"""
                if record["job_status"] == "Needs Confirmation" and record['data_update_job_id'] == latest_job_id
                else '<button class="ghost compact" disabled>等待可确认任务</button>'
            )
            cards.append(f"""<article class="private-fee-review-card">
              <div class="data-update-preview-main">
                <div><span class="eyebrow">Private International Fees</span><h3>{esc(record['school_name'])}</h3><p>{esc(record['state'])} · 年份 {esc(record['fee_year'] or '待确认')} · 来源 <a href="{esc(record['source_url'] or '#')}" target="_blank">{esc(record['source_url'] or '未记录')}</a></p></div>
                <div class="data-update-preview-action"><span class="status {self.data_update_status_class(record['verification_status'])}">{esc(record['verification_status'])}</span>{confirm_hint}</div>
              </div>
              <div class="data-update-preview-metrics"><span>置信度 {esc(record['confidence_score'])}</span><span>任务 #{esc(record['data_update_job_id'] or '')}</span><span>{esc(record['source_type'])}</span></div>
              <div class="table-wrap"><table><thead><tr><th>类别</th><th>年级</th><th>金额</th><th>周期</th><th>原文</th></tr></thead><tbody>{item_rows}</tbody></table></div>
              <details><summary>原始文本</summary><pre class="raw-text-preview">{esc((record['raw_text'] or '')[:3000])}</pre></details>
            </article>""")
        body = f"""<a class="back-link" href="/data-updates">← 返回数据更新中心</a>
        <section class="panel">
          <div class="panel-head"><div><span class="eyebrow">全库私校批量采集</span><h2>私校国际生学费 · 待确认</h2><p>所有官网采集结果先进入这里。确认前不会写入正式学校费用。</p></div></div>
          <div class="data-update-preview-list">{''.join(cards) or '<div class="empty">暂无私校国际生学费待确认记录。</div>'}</div>
        </section>"""
        message, kind = self.message()
        self.send_html(page("私校国际生学费待确认", body, self.user, self.csrf, "data_update_centre", nas.status(), message, kind))

    def data_update_rollback(self, method):
        if method != "POST":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        if not can_access_module(self.user, "data_update_centre"):
            return self.error_page("你没有访问数据更新中心的权限。", HTTPStatus.FORBIDDEN)
        job_id = rollback_latest_data_update(db, user_id=self.user["id"])
        job = db.one("SELECT * FROM data_update_jobs WHERE id=?", (job_id,))
        db.audit(self.user, "data_update_rollback_requested", "data_update_centre", record_id=job_id, ip=self.client_address[0], device=self.headers.get("User-Agent"))
        if job and job["status"] == "Success":
            return self.flash_redirect("/data-updates", "已回滚到上一版本。")
        return self.flash_redirect("/data-updates", f"回滚失败：{job['error_message'] if job else '未知错误'}", "error")

    def data_update_confirm(self, method, job_id):
        if method != "POST":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        if not can_access_module(self.user, "data_update_centre"):
            return self.error_page("你没有访问数据更新中心的权限。", HTTPStatus.FORBIDDEN)
        try:
            changed = confirm_data_update_job(db, int(job_id), user_id=self.user["id"])
        except Exception as exc:
            return self.flash_redirect("/data-updates", f"确认更新失败：{exc}", "error")
        db.audit(self.user, "data_update_job_confirmed", "data_update_centre", record_id=job_id, new_value=json.dumps({"published": changed}, ensure_ascii=False), ip=self.client_address[0], device=self.headers.get("User-Agent"))
        return self.flash_redirect("/data-updates", f"确认更新完成，已发布 {changed} 条正式数据。")

