    def school_plan_map_font(self, size=24):
        font_paths = [
            "/System/Library/Fonts/PingFang.ttc",
            "/System/Library/Fonts/Supplemental/Arial Unicode.ttf",
            "/System/Library/Fonts/STHeiti Medium.ttc",
            "/System/Library/Fonts/Supplemental/Arial.ttf",
        ]
        for path in font_paths:
            try:
                if Path(path).exists():
                    return ImageFont.truetype(path, size=size)
            except Exception:
                continue
        return ImageFont.load_default()

    def school_plan_validate_map_image_bytes(self, image_bytes, min_width=1200, min_height=800):
        try:
            image = Image.open(io.BytesIO(image_bytes)).convert("RGB")
        except Exception:
            return False
        if image.width < min_width or image.height < min_height:
            return False
        probe = image.resize((24, 16))
        pixels = list(probe.getdata())
        if not pixels:
            return False
        average = tuple(sum(pixel[idx] for pixel in pixels) / len(pixels) for idx in range(3))
        if max(average) < 18:
            return False
        unique_sample = {pixel for pixel in pixels[:120]}
        return len(unique_sample) > 3

    def school_plan_snapshot_static_map_data_uri(self, school, _area_profile=None):
        width, height = 1200, 800
        tile_size = 256

        def lat_lng_to_world(point_lat, point_lng, zoom):
            sin_lat = math.sin(math.radians(max(-85.05112878, min(85.05112878, point_lat))))
            world = tile_size * (2 ** zoom)
            x = (point_lng + 180.0) / 360.0 * world
            y = (0.5 - math.log((1 + sin_lat) / (1 - sin_lat)) / (4 * math.pi)) * world
            return x, y

        def fetch_tile(zoom, tile_x, tile_y):
            max_tile = 2 ** zoom
            tile_x = tile_x % max_tile
            tile_y = max(0, min(max_tile - 1, tile_y))
            return load_school_map_tile(
                APP_DIR, zoom, tile_x, tile_y,
                relay_port=STAGING.admin_port + 13 if STAGING else None,
            )

        def text_size(draw_obj, text, font):
            box = draw_obj.textbbox((0, 0), text, font=font)
            return box[2] - box[0], box[3] - box[1]

        def draw_label(draw_obj, anchor, title, subtitle, color, font_title, font_subtitle, prefer="right"):
            x, y = anchor
            title_w, title_h = text_size(draw_obj, title, font_title)
            sub_w, sub_h = text_size(draw_obj, subtitle, font_subtitle) if subtitle else (0, 0)
            box_w = max(title_w, sub_w) + 28
            box_h = title_h + sub_h + (24 if subtitle else 16)
            if prefer == "left":
                left = x - box_w - 18
            else:
                left = x + 18
            top = y - box_h / 2
            left = max(18, min(width - box_w - 18, left))
            top = max(18, min(height - box_h - 18, top))
            draw_obj.rounded_rectangle((left, top, left + box_w, top + box_h), radius=12, fill=(255, 255, 255), outline="#d8e0ea", width=2)
            draw_obj.rectangle((left, top, left + 7, top + box_h), fill=color)
            draw_obj.text((left + 16, top + 8), title, fill="#0f172a", font=font_title, anchor="lt")
            if subtitle:
                draw_obj.text((left + 16, top + 14 + title_h), subtitle, fill="#475569", font=font_subtitle, anchor="lt")

        try:
            lat = float(school["latitude"])
            lng = float(school["longitude"])
        except (TypeError, ValueError, KeyError):
            return ""
        state = str(school["state"] if "state" in school.keys() else "").strip().upper()
        cbd = SCHOOL_CBD_COORDS.get(state)
        if not cbd:
            return ""
        points = [
            ("school", lat, lng),
            ("cbd", float(cbd["latitude"]), float(cbd["longitude"])),
        ]
        chosen_zoom = 12
        for zoom in range(14, 9, -1):
            pixel_points = [lat_lng_to_world(point_lat, point_lng, zoom) for _name, point_lat, point_lng in points]
            xs = [item[0] for item in pixel_points]
            ys = [item[1] for item in pixel_points]
            if max(xs) - min(xs) <= width * 0.58 and max(ys) - min(ys) <= height * 0.42:
                chosen_zoom = zoom
                break
        world_points = {name: lat_lng_to_world(point_lat, point_lng, chosen_zoom) for name, point_lat, point_lng in points}
        center_x = (min(item[0] for item in world_points.values()) + max(item[0] for item in world_points.values())) / 2
        center_y = (min(item[1] for item in world_points.values()) + max(item[1] for item in world_points.values())) / 2
        top_left_x = center_x - width / 2
        top_left_y = center_y - height / 2
        first_tile_x = math.floor(top_left_x / tile_size)
        first_tile_y = math.floor(top_left_y / tile_size)
        last_tile_x = math.floor((top_left_x + width - 1) / tile_size)
        last_tile_y = math.floor((top_left_y + height - 1) / tile_size)
        map_canvas = Image.new("RGB", (width, height), "#e8edf2")
        for tile_x in range(first_tile_x, last_tile_x + 1):
            for tile_y in range(first_tile_y, last_tile_y + 1):
                tile = fetch_tile(chosen_zoom, tile_x, tile_y)
                paste_x = int(tile_x * tile_size - top_left_x)
                paste_y = int(tile_y * tile_size - top_left_y)
                map_canvas.paste(tile, (paste_x, paste_y))
        overlay = Image.new("RGBA", (width, height), (255, 255, 255, 0))
        overlay_draw = ImageDraw.Draw(overlay)
        overlay_draw.rounded_rectangle((0, 0, width - 1, height - 1), radius=28, outline="#d8e0ea", width=4)
        image = Image.alpha_composite(map_canvas.convert("RGBA"), overlay).convert("RGB")
        draw = ImageDraw.Draw(image)
        label_font = self.school_plan_map_font(25)
        small_font = self.school_plan_map_font(19)
        title_font = self.school_plan_map_font(28)

        def screen_point(name):
            world_x, world_y = world_points[name]
            return int(round(world_x - top_left_x)), int(round(world_y - top_left_y))

        school_xy = screen_point("school")
        cbd_xy = screen_point("cbd")
        school_distance = living_cost_haversine_km(lat, lng, cbd["latitude"], cbd["longitude"])
        school_label = school_fee_row_value(school, "school_name", "") or "学校"
        draw.line((cbd_xy[0], cbd_xy[1], school_xy[0], school_xy[1]), fill="#2563eb", width=7)
        dash_count = 26
        for idx in range(dash_count):
            if idx % 2:
                continue
            t1 = idx / dash_count
            t2 = min(1, (idx + 1) / dash_count)
            draw.line(
                (
                    cbd_xy[0] + (school_xy[0] - cbd_xy[0]) * t1,
                    cbd_xy[1] + (school_xy[1] - cbd_xy[1]) * t1,
                    cbd_xy[0] + (school_xy[0] - cbd_xy[0]) * t2,
                    cbd_xy[1] + (school_xy[1] - cbd_xy[1]) * t2,
                ),
                fill="#ffffff",
                width=3,
            )
        for point, color, outline in (
            (cbd_xy, "#334155", "#0f172a"),
            (school_xy, "#dc2626", "#7f1d1d"),
        ):
            x, y = point
            draw.ellipse((x - 18, y - 18, x + 18, y + 18), fill=outline)
            draw.ellipse((x - 14, y - 14, x + 14, y + 14), fill=color, outline="#ffffff", width=3)
        draw_label(draw, cbd_xy, cbd["label"], "CBD", "#334155", label_font, small_font, prefer="left")
        draw_label(draw, school_xy, str(school_label)[:34], f"学校 · 距 CBD 约 {school_distance:.1f} km", "#dc2626", label_font, small_font, prefer="right")
        footer_h = 58
        draw.rounded_rectangle((24, height - footer_h - 20, width - 24, height - 20), radius=18, fill="#ffffff", outline="#d8e0ea", width=2)
        draw.text((50, height - footer_h - 4), "城市 CBD 地图照片", fill="#334155", font=small_font)
        draw.text((365, height - footer_h - 4), f"学校到 {cbd['label']}：{school_distance:.1f} km · 直线距离", fill="#0f172a", font=small_font)
        attribution = "© OpenStreetMap contributors"
        attribution_font = self.school_plan_map_font(15)
        attribution_width, _ = text_size(draw, attribution, attribution_font)
        draw.text((width - 42 - attribution_width, height - footer_h), attribution, fill="#64748b", font=attribution_font)
        map_title = f"学校到 {cbd['label']} 地图照片"
        title_width, title_height = text_size(draw, map_title, title_font)
        draw.rounded_rectangle((22, 22, min(width - 22, title_width + 66), 44 + title_height), radius=16, fill="#ffffff", outline="#d8e0ea", width=2)
        draw.text((44, 33), map_title, fill="#10233f", font=title_font, anchor="lt")
        buffer = io.BytesIO()
        image.save(buffer, format="PNG", optimize=True)
        image_bytes = buffer.getvalue()
        if not self.school_plan_validate_map_image_bytes(image_bytes):
            return ""
        return "data:image/png;base64," + base64.b64encode(image_bytes).decode("ascii")

    def school_plan_build_snapshot(self, student, school_ids, module_keys, report_version):
        qmarks = ",".join("?" for _ in school_ids)
        school_rows = db.all(f"SELECT * FROM schools WHERE id IN ({qmarks})", tuple(school_ids)) if school_ids else []
        school_by_id = {str(row["id"]): row for row in school_rows}
        ordered_schools = [school_by_id[str(school_id)] for school_id in school_ids if str(school_id) in school_by_id]
        school_snapshots = []
        for school in ordered_schools:
            school_id = school["id"]
            fees = db.all(
                """SELECT fee_type,year_level,amount,currency,fee_year,source_name,source_url,review_status,updated_at
                   FROM school_fees WHERE school_id=? ORDER BY COALESCE(fee_year,'') DESC,updated_at DESC LIMIT 12""",
                (school_id,),
            )
            profile = db.one(
                """SELECT * FROM school_profile_data WHERE school_id=? AND is_active=1
                   ORDER BY source_year DESC,version_number DESC,id DESC LIMIT 1""",
                (school_id,),
            )
            market = db.all(
                """SELECT radius_km,median_weekly_rent_all,median_weekly_rent_house,median_weekly_rent_unit,median_house_price,median_unit_price,
                          source_period_rent,source_period_sale,confidence_level,last_calculated_at
                   FROM school_radius_market_summary WHERE school_id=? ORDER BY radius_km""",
                (school_id,),
            )
            rankings = self.school_ranking_rows_for_school(school, limit=6)
            crime = db.all(
                """SELECT area_type,radius_km,suburb,postcode,lga_name,total_offence_count,offence_rate_per_100k,
                          top_offence_categories,source_period,confidence_level,last_calculated_at
                   FROM school_area_crime_summary WHERE school_id=? ORDER BY source_period DESC,radius_km LIMIT 6""",
                (school_id,),
            )
            documents = db.all(
                """SELECT document_type,original_filename,stored_filename,file_path,source_url,notes,uploaded_at,updated_at
                   FROM school_documents WHERE school_id=? ORDER BY uploaded_at DESC LIMIT 8""",
                (school_id,),
            )
            public_state_fees = []
            if not self.school_is_private_school(school) and school_uses_state_fee_schedule(school):
                schedule = active_state_fee_schedule(school["state"], school_state_fee_sector(school))
                if schedule:
                    items = state_fee_items(schedule["id"])
                    for item in state_fee_tuition_items_for_school(items, school):
                        item_snapshot = rowdict(item)
                        item_snapshot["amount_text"] = state_fee_amount_text(item)
                        item_snapshot["schedule_name"] = schedule["schedule_name"] if "schedule_name" in schedule.keys() else ""
                        item_snapshot["effective_year"] = schedule["effective_year"] if "effective_year" in schedule.keys() else ""
                        item_snapshot["source_url"] = schedule["source_url"] if "source_url" in schedule.keys() else ""
                        item_snapshot["last_updated"] = schedule["updated_at"] if "updated_at" in schedule.keys() else schedule["created_at"] if "created_at" in schedule.keys() else ""
                        public_state_fees.append(item_snapshot)
            area_profile = self.school_latest_area_profile(school_id)
            area_profile_metrics = self.school_area_profile_metric_rows(area_profile["id"] if area_profile else None)
            suburb_data = self.school_latest_suburb_data(school)
            crime_profile = self.school_latest_area_crime_profile(school_id)
            try:
                map_snapshot_svg = self.school_living_cost_map_svg(school)
            except Exception:
                map_snapshot_svg = ""
            try:
                map_snapshot_image_data_uri = self.school_plan_snapshot_static_map_data_uri(school, area_profile)
            except Exception as exc:
                map_snapshot_image_data_uri = ""
                append_service_log("admin", "map_snapshot_failed", repr(exc), school_id=school_id)
            school_snapshots.append({
                "basic_info": rowdict(school),
                "fees": [rowdict(row) for row in fees],
                "public_state_fee_snapshot": public_state_fees,
                "school_profile_data": rowdict(profile),
                "market_cost": [rowdict(row) for row in market],
                "rankings": [rowdict(row) for row in rankings],
                "crime_snapshot": [rowdict(row) for row in crime],
                "area_safety_reference": [rowdict(row) for row in crime],
                "area_crime_profile_snapshot": rowdict(crime_profile),
                "area_profile_snapshot": rowdict(area_profile),
                "area_profile_metrics_snapshot": [rowdict(row) for row in area_profile_metrics],
                "suburb_data_snapshot": rowdict(suburb_data),
                "uploaded_pdf_summary_snapshot": [rowdict(row) for row in documents],
                "uploaded_documents": [rowdict(row) for row in documents],
                "map_snapshot_svg": map_snapshot_svg,
                "map_snapshot_image_data_uri": map_snapshot_image_data_uri,
            })
        module_labels = dict(self.school_plan_module_options())
        return {
            "selected_school_ids": school_ids,
            "selected_modules": [{"key": key, "label": module_labels.get(key, key)} for key in module_keys],
            "student": rowdict(student),
            "schools": school_snapshots,
            "report_version": report_version,
            "generated_at": now_iso(),
            "generated_by": {"id": self.user["id"], "name": self.user["display_name"]},
            "notes": "Generated from CRM snapshot data. Existing reports do not change when source school data is updated.",
        }

    def school_plan_snapshot(self, report):
        try:
            snapshot = json.loads(report["snapshot_json"] or "{}")
        except Exception:
            snapshot = {}
        return snapshot if isinstance(snapshot, dict) else {}

    def school_plan_first(self, rows, **filters):
        for row in rows or []:
            if all(str(row.get(key) or "") == str(value) for key, value in filters.items()):
                return row
        return (rows or [{}])[0] if rows else {}

    def school_plan_living_cost_report_rows(self, rows):
        visible = []
        for row in rows or []:
            try:
                raw_radius = row.get("radius_km")
                radius = float(str(raw_radius).strip()) if raw_radius is not None else None
            except (TypeError, ValueError):
                radius = None
            if radius == 0:
                continue
            visible.append(row)
        return visible

