    def school_plan_report_date(self, value):
        text = str(value or "").strip()
        if not text:
            return self.school_plan_report_text("not_recorded")
        cleaned = text.replace("T", " ")
        if "+" in cleaned:
            cleaned = cleaned.split("+", 1)[0]
        candidates = [
            (cleaned[:19], "%Y-%m-%d %H:%M:%S"),
            (cleaned[:16], "%Y-%m-%d %H:%M"),
            (cleaned[:10], "%Y-%m-%d"),
        ]
        for candidate, fmt in candidates:
            try:
                parsed = datetime.strptime(candidate, fmt)
                return parsed.strftime("%d/%m/%Y")
            except ValueError:
                continue
        iso_match = re.match(r"^(\d{4})-(\d{2})-(\d{2})", cleaned)
        if iso_match:
            year, month, day = iso_match.groups()
            return f"{day}/{month}/{year}"
        return text[:10]

    def school_plan_recent_academic_result_rows(self, rows, max_years=3):
        valid_rows = [row for row in (rows or []) if str(row.get("data_year") or "").strip()]
        recent_years = []
        for year in sorted({str(row.get("data_year") or "").strip() for row in valid_rows}, key=self.school_ranking_year_sort, reverse=True):
            if len(recent_years) >= max_years:
                break
            recent_years.append(year)
        recent_year_set = set(recent_years)

        def source_priority(row):
            if self.school_ranking_is_bettereducation_row(row):
                return 0
            if self.school_ranking_is_official_result_row(row):
                return 1
            return 2

        return sorted(
            [row for row in valid_rows if str(row.get("data_year") or "").strip() in recent_year_set],
            key=lambda row: (
                -self.school_ranking_year_sort(row.get("data_year")),
                source_priority(row),
                str(row.get("source_name") or "").lower(),
                str(row.get("imported_at") or ""),
            ),
        )

    def school_plan_academic_results_context(self, school=None, rows=None):
        school = school or {}
        raw_rows = list(rows or school.get("rankings") or [])
        basic = school.get("basic_info") or {}
        state = str(basic.get("state") or school.get("state") or "").strip().upper()
        for row in raw_rows:
            state = state or str(row.get("state") or "").strip().upper()
        system = ""
        for row in raw_rows:
            candidate = str(row.get("ranking_system") or "").strip().upper()
            if candidate:
                system = candidate
                break
        by_state = {
            "VIC": ("VCE", "VCE 中位分", "40分以上比例", "VCAA SSCAI", "学校整体 VCE 表现"),
            "NSW": ("HSC", "HSC 成绩指标", "HSC 高分记录", "NESA HSC", "学校整体 HSC 表现"),
            "QLD": ("QCE", "QCE 成绩指标", "高分记录", "QLD senior academic results", "学校整体 QCE 表现"),
            "WA": ("WACE", "WACE 成绩指标", "高分记录", "SCSA", "学校整体 WACE 表现"),
            "SA": ("SACE", "SACE 成绩指标", "高分记录", "SACE", "学校整体 SACE 表现"),
            "TAS": ("TCE", "TCE 成绩指标", "高分记录", "TASC", "学校整体 TCE 表现"),
            "ACT": ("ATAR", "ATAR 成绩指标", "高分记录", "ACT senior academic results", "学校整体学术表现"),
            "NT": ("NTCET", "NTCET 成绩指标", "高分记录", "NT senior academic results", "学校整体学术表现"),
        }
        label, median_label, top_label, official_source, performance_label = by_state.get(state, ("Academic Results", "学术成绩指标", "高分记录", "官方学术成绩", "学校整体学术表现"))
        for key in ("HSC", "VCE", "QCE", "WACE", "SACE", "TCE", "ATAR", "NTCET"):
            if key in system and key != label:
                label = key
                if key == "HSC":
                    median_label, top_label, official_source, performance_label = "HSC 成绩指标", "HSC 高分记录", "NESA HSC", "学校整体 HSC 表现"
                elif key == "VCE":
                    median_label, top_label, official_source, performance_label = "VCE 中位分", "40分以上比例", "VCAA SSCAI", "学校整体 VCE 表现"
                break
        return {
            "state": state,
            "system": label,
            "median_label": median_label,
            "top_scores_label": top_label,
            "official_source_label": official_source,
            "performance_label": performance_label,
        }

    def school_plan_academic_result_chart_number(self, value):
        text = str(value or "").strip().replace(",", "")
        if not text:
            return None
        try:
            return float(text)
        except (TypeError, ValueError):
            return None

    def school_plan_academic_results_charts_html(self, rows, academic_context=None):
        academic_context = academic_context or self.school_plan_academic_results_context(rows=rows)
        median_label = academic_context["median_label"]
        year_data = {}
        for row in rows or []:
            year = str(row.get("data_year") or "").strip()
            if not year:
                continue
            bucket = year_data.setdefault(year, {"rank": None, "median": None})
            rank_value = self.school_plan_academic_result_chart_number(row.get("rank"))
            if rank_value is not None and bucket["rank"] is None:
                bucket["rank"] = rank_value
            median_value = self.school_plan_academic_result_chart_number(row.get("median_score"))
            if median_value is not None and bucket["median"] is None:
                bucket["median"] = median_value
        years = sorted(year_data, key=self.school_ranking_year_sort)[-3:]
        if not years:
            return ""

        def fmt(value):
            if value is None:
                return ""
            return str(int(value)) if float(value).is_integer() else f"{value:.1f}".rstrip("0").rstrip(".")

        def x_for(index, total, left=44, right=326):
            if total <= 1:
                return (left + right) / 2
            return left + (right - left) * index / (total - 1)

        def rank_chart():
            points = [(year, year_data[year]["rank"]) for year in years if year_data[year]["rank"] is not None]
            if not points:
                return '<div class="report-empty">暂未收录 Better Education 排名图表数据，需进一步确认</div>'
            values = [value for _year, value in points]
            min_value, max_value = min(values), max(values)
            span = max(max_value - min_value, 1)
            top, bottom = 38, 132
            coords = []
            labels = []
            for index, (year, value) in enumerate(points):
                x = x_for(index, len(points))
                y = top + ((value - min_value) / span) * (bottom - top)
                coords.append((x, y, year, value))
                labels.append(
                    f"""<g><circle class="report-academic-rank-dot" cx="{x:.1f}" cy="{y:.1f}" r="5"></circle><text class="value" x="{x:.1f}" y="{y - 11:.1f}" text-anchor="middle">{esc(fmt(value))}</text><text class="year" x="{x:.1f}" y="160" text-anchor="middle">{esc(year)}</text></g>"""
                )
            line_points = " ".join(f"{x:.1f},{y:.1f}" for x, y, _year, _value in coords)
            return f"""<svg viewBox="0 0 370 178" role="img" aria-label="Better Education 排名近 3 年趋势">
              <line class="report-academic-axis" x1="34" y1="140" x2="340" y2="140"></line>
              <polyline class="report-academic-rank-line" points="{line_points}"></polyline>
              {''.join(labels)}
            </svg>"""

        def median_chart():
            points = [(year, year_data[year]["median"]) for year in years if year_data[year]["median"] is not None]
            if not points:
                return f'<div class="report-empty">暂未收录 {esc(median_label)} 图表数据，需进一步确认</div>'
            max_value = max(value for _year, value in points) or 1
            bar_width = 42 if len(points) >= 3 else 54
            top, bottom = 34, 140
            bars = []
            for index, (year, value) in enumerate(points):
                x = x_for(index, len(points)) - bar_width / 2
                height = max(8, (value / max_value) * (bottom - top))
                y = bottom - height
                bars.append(
                    f"""<g><rect class="report-academic-vce-bar" x="{x:.1f}" y="{y:.1f}" width="{bar_width}" height="{height:.1f}" rx="8"></rect><text class="value" x="{x + bar_width / 2:.1f}" y="{y - 9:.1f}" text-anchor="middle">{esc(fmt(value))}</text><text class="year" x="{x + bar_width / 2:.1f}" y="160" text-anchor="middle">{esc(year)}</text></g>"""
                )
            return f"""<svg viewBox="0 0 370 178" role="img" aria-label="{esc(median_label)}近 3 年趋势">
              <line class="report-academic-axis" x1="34" y1="140" x2="340" y2="140"></line>
              {''.join(bars)}
            </svg>"""

        return f"""<div class="report-academic-results-charts">
          <article class="report-academic-chart report-academic-rank-chart"><h4>Better Education 排名近 3 年趋势</h4><p>排名越靠前越好，数字越小代表排名越高。</p>{rank_chart()}</article>
          <article class="report-academic-chart report-academic-vce-chart"><h4>{esc(median_label)}近 3 年趋势</h4><p>已记录的最近 3 年 {esc(median_label)}。</p>{median_chart()}</article>
        </div>"""

    def school_plan_overview_academic_results_text(self, school):
        rows = self.school_plan_recent_academic_result_rows((school or {}).get("rankings") or [])
        if not rows:
            return ""
        academic_context = self.school_plan_academic_results_context(school, rows)
        latest_year = str(self.school_ranking_row_get(rows[0], "data_year") or "").strip()
        latest_rows = [
            row for row in rows
            if str(self.school_ranking_row_get(row, "data_year") or "").strip() == latest_year
        ]

        def row_text(row, key):
            return str(self.school_ranking_row_get(row, key) or "").strip()

        def first_matching(predicate):
            for item in latest_rows:
                if predicate(item):
                    return item
            return None

        bettereducation_row = first_matching(
            lambda item: row_text(item, "rank") and self.school_ranking_is_bettereducation_row(item)
        ) or first_matching(lambda item: row_text(item, "rank"))
        official_row = first_matching(
            lambda item: self.school_ranking_is_official_result_row(item)
            and (row_text(item, "median_score") or row_text(item, "top_scores_percentage") or row_text(item, "result_metric_value"))
        ) or first_matching(
            lambda item: row_text(item, "median_score") or row_text(item, "top_scores_percentage") or row_text(item, "result_metric_value")
        )

        parts = []
        if bettereducation_row is not None:
            rank = row_text(bettereducation_row, "rank")
            percentile = row_text(bettereducation_row, "percentile")
            text = f"Better Education：{latest_year} 排名 {rank}"
            if percentile:
                text += f"，Percentile {percentile}"
            parts.append(text)
        if official_row is not None:
            median = row_text(official_row, "median_score") or row_text(official_row, "result_metric_value")
            top_scores = row_text(official_row, "top_scores_percentage")
            source_name = row_text(official_row, "source_name") or academic_context["official_source_label"]
            text = f"{source_name}：{latest_year}"
            if median:
                text += f" {academic_context['median_label']} {median}"
            if top_scores:
                text += f"；{academic_context['top_scores_label']} {top_scores}"
            parts.append(text)
        return " | ".join(parts)

    def school_plan_overview_area_safety_text(self, school):
        safety = self.school_plan_first(self.school_plan_report_safety_rows(school or {}))
        if not safety:
            return ""
        offence_count = safety.get("total_offence_count") or safety.get("total_recorded_offences")
        if offence_count in (None, ""):
            return ""
        return f"记录犯罪总数：{self.school_plan_report_number(offence_count)}"

    def school_plan_report_money(self, value, suffix=""):
        amount = money_decimal(value)
        if amount is None:
            return self.school_plan_report_value(value, "no_data")
        if amount == amount.to_integral_value():
            text = f"{int(amount):,}"
        else:
            text = f"{float(amount):,.2f}".rstrip("0").rstrip(".")
        return f"AU${text}{suffix}"

    def school_plan_report_percent(self, value):
        if value is None or str(value).strip() == "":
            return self.school_plan_report_text("no_data")
        try:
            return f"{float(value):.1f}%"
        except (TypeError, ValueError):
            return str(value)

    def school_plan_report_number(self, value):
        if value is None or str(value).strip() == "":
            return self.school_plan_report_text("no_data")
        try:
            number = float(value)
            return f"{int(number):,}" if number.is_integer() else f"{number:,.1f}"
        except (TypeError, ValueError):
            return str(value)

