    def school_plan_public_fee_summary(self, school):
        public_rows = school.get("public_state_fee_snapshot") or []
        if public_rows:
            row = public_rows[0]
            return self.school_plan_report_money(row.get("amount") or row.get("amount_text"), " / 年")
        fee = self.school_plan_first(school.get("fees") or [])
        if fee:
            suffix = " / 年" if str(fee.get("fee_type") or "").lower().find("tuition") >= 0 else ""
            return self.school_plan_report_money(fee.get("amount"), suffix)
        basic = school.get("basic_info") or {}
        if basic.get("international_tuition_fee_amount"):
            return self.school_plan_report_money(basic.get("international_tuition_fee_amount"), " / 年")
        return self.school_plan_report_text("no_data")

