    def school_plan_area_safety_context(self, school, crime_rows=None):
        school = school or {}
        basic = school.get("basic_info") or {}
        profile = school.get("area_crime_profile_snapshot") or {}
        rows = crime_rows if crime_rows is not None else self.school_plan_report_safety_rows(school)
        first = rows[0] if rows else {}
        data_level = profile.get("data_level") or first.get("area_type") or first.get("data_level") or ""
        data_level_label = self.school_plan_area_safety_data_level_label(data_level)
        state = profile.get("state") or basic.get("state") or school.get("state") or ""
        suburb = profile.get("suburb") or first.get("suburb") or basic.get("suburb") or school.get("suburb") or ""
        postcode = profile.get("postcode") or first.get("postcode") or basic.get("postcode") or school.get("postcode") or ""
        lga_name = profile.get("lga_name") or first.get("lga_name") or ""
        matched_area = lga_name or suburb or postcode or state or "待匹配"
        area_label = {
            "suburb": "匹配区域",
            "postcode": "匹配区域",
            "lga": "地方政府区域",
            "police_district": "警务辖区",
            "police_region": "警务区域",
            "state": "州级范围",
        }.get(str(data_level or "").strip().lower(), "匹配区域")
        period = profile.get("data_year_ending") or first.get("source_period") or ""
        checked_at = profile.get("last_checked_at") or profile.get("updated_at") or first.get("last_calculated_at") or ""
        lga_supplemented = "LGA-level official crime data" in str(profile.get("notes") or "")
        return {
            "has_data": bool(profile or first),
            "suburb": suburb,
            "state": state,
            "postcode": postcode,
            "matched_area": matched_area,
            "area_label": area_label,
            "data_level_label": data_level_label,
            "period": self.school_area_crime_period_display(period),
            "checked_at": self.school_area_crime_checked_display(checked_at),
            "lga_supplemented": lga_supplemented,
            "metrics": [
                ("记录犯罪总数", self.school_plan_area_safety_display_value(profile.get("total_recorded_offences"), first.get("total_offence_count"), first.get("total_recorded_offences"))),
                ("每10万人犯罪率", self.school_plan_area_safety_display_value(profile.get("offence_rate_per_100000"), first.get("offence_rate_per_100k"), first.get("offence_rate_per_100000"))),
                ("刑事事件", self.school_plan_area_safety_display_value(profile.get("criminal_incidents_total"))),
                ("财产及欺诈类犯罪", self.school_plan_area_safety_display_value(profile.get("property_and_deception_offences"))),
                ("人身类犯罪", self.school_plan_area_safety_display_value(profile.get("crimes_against_person"))),
                ("住宅入室盗窃", self.school_plan_area_safety_display_value(profile.get("residential_burglary_count"))),
                ("机动车盗窃", self.school_plan_area_safety_display_value(profile.get("motor_vehicle_theft_count"))),
                ("车内盗窃", self.school_plan_area_safety_display_value(profile.get("theft_from_motor_vehicle_count"))),
                ("家庭事件", self.school_plan_area_safety_display_value(profile.get("family_incidents_total"))),
            ],
        }

    def school_plan_area_safety_report_html(self, school, crime_rows=None):
        context = self.school_plan_area_safety_context(school, crime_rows)
        if not context["has_data"]:
            return '<div class="report-empty">暂未收录区域安全数据，需顾问确认</div>'
        visible_metrics = [
            (label, value)
            for label, value in context["metrics"]
            if str(value or "").strip() and str(value or "").strip() != "未提供"
        ]
        metric_lookup = {label: value for label, value in visible_metrics}
        total_label = "记录犯罪总数"
        total_value = metric_lookup.get(total_label) or "暂未收录，需进一步确认"
        core_card_labels = ["记录犯罪总数", "每10万人犯罪率", "刑事事件", "家庭事件"]
        core_card_html = "".join(
            f"""<div class="report-safety-core-card"><span>{esc(label)}</span><strong>{esc(metric_lookup[label])}</strong></div>"""
            for label in core_card_labels
            if metric_lookup.get(label)
        )
        core_grid_html = f"""<div class="report-safety-core-grid">{core_card_html}</div>""" if core_card_html else ""
        bar_labels = ["财产及欺诈类犯罪", "人身类犯罪", "住宅入室盗窃", "机动车盗窃", "车内盗窃"]
        bar_items = []
        for label in bar_labels:
            value = metric_lookup.get(label)
            number = self.school_plan_report_numeric_value(value)
            if value and number is not None:
                bar_items.append((label, value, number))
        max_bar_value = max((item[2] for item in bar_items), default=1) or 1
        bar_html = "".join(
            f"""<div class="report-safety-bar">
              <div class="report-safety-bar-head"><span>{esc(label)}</span><strong>{esc(value)}</strong></div>
              <div class="report-safety-bar-track"><i style="width:{max(4, min(100, number / max_bar_value * 100)):.1f}%"></i></div>
            </div>"""
            for label, value, number in bar_items
        )
        bar_section_html = f'<div class="report-safety-bars">{bar_html}</div>' if bar_html else ""
        return f"""<div class="report-safety-panel">
          <div class="report-safety-secondary">{core_grid_html}{bar_section_html}</div>
        </div>"""

    def school_plan_suburb_snapshot_value(self, suburb_data, field_name):
        if not suburb_data or field_name not in suburb_data:
            return ""
        value = suburb_data.get(field_name)
        if value is None or str(value).strip() == "":
            return ""
        if field_name.endswith("_json"):
            try:
                parsed = json.loads(str(value))
            except Exception:
                parsed = value
            if isinstance(parsed, dict):
                parts = []
                for key, item_value in parsed.items():
                    if item_value in (None, ""):
                        continue
                    parts.append(f"{key}: {item_value}")
                return "；".join(parts[:4])
            if isinstance(parsed, list):
                parts = []
                for item in parsed:
                    if isinstance(item, dict):
                        label = item.get("name") or item.get("label") or item.get("country") or item.get("language") or ""
                        amount = item.get("value") or item.get("percent") or item.get("percentage") or item.get("count") or ""
                        text = " ".join(str(part) for part in (label, amount) if str(part).strip())
                        if text:
                            parts.append(text)
                    elif str(item).strip():
                        parts.append(str(item).strip())
                return "；".join(parts[:4])
        text = str(value).strip()
        if field_name.endswith("_percentage"):
            return text if text.endswith("%") else f"{text} %"
        if field_name in {"median_personal_income_weekly", "median_family_income_weekly", "median_household_income_weekly"}:
            return f"{text} 澳元/周"
        if field_name == "median_age":
            return text if text.endswith("年") else f"{text} 年"
        return text

    def school_plan_area_profile_report_html(self, area_profile, area_metrics, suburb_data):
        group_titles = {
            "population": "人口数据",
            "family": "家庭结构",
            "income": "收入水平",
            "language": "语言背景",
            "education": "教育背景",
            "migration": "移民 / 文化背景",
            "housing": "住房结构",
        }

        def cleaned_items(items):
            cleaned = []
            for label, value in items:
                if value is None or str(value).strip() == "":
                    continue
                cleaned.append((label, value))
            return cleaned

        def section_rows(title, items):
            items = cleaned_items(items)
            if not items:
                return ""
            rows = [f"""<tr class="report-area-profile-group"><th colspan="4">{esc(title)}</th></tr>"""]
            for index in range(0, len(items), 2):
                first = items[index]
                second = items[index + 1] if index + 1 < len(items) else ("", "")
                rows.append(
                    f"""<tr><td>{esc(first[0])}</td><td><strong>{esc(first[1])}</strong></td><td>{esc(second[0])}</td><td>{f'<strong>{esc(second[1])}</strong>' if second[0] else ''}</td></tr>"""
                )
            return "".join(rows)

        meta_items = [
            ("城区", " ".join(part for part in [area_profile.get("suburb"), area_profile.get("state"), area_profile.get("postcode")] if part)),
            ("LGA", area_profile.get("lga_name") or area_profile.get("lga_code")),
        ]

        group_sections = []
        for group, title in group_titles.items():
            group_items = []
            for field_name, label, field_group in SCHOOL_SUBURB_DATA_FIELDS:
                if field_group != group:
                    continue
                value = self.school_plan_suburb_snapshot_value(suburb_data, field_name)
                group_items.append((label, value))
            group_sections.append(section_rows(title, group_items))
        table_body = "".join([
            section_rows("区域概览", meta_items),
            *group_sections,
        ])
        if not table_body:
            return '<div class="report-empty">暂未收录学校所在区域资料，需顾问确认</div>'
        return f"""
          <table class="report-area-profile-table"><tbody>{table_body}</tbody></table>
        """

    def school_plan_school_nature_label(self, *values):
        text_values = [str(value or "").strip() for value in values if str(value or "").strip()]
        text = " ".join(text_values).lower()
        if any(token in text for token in ("public", "government", "公立", "公校")):
            return "公校"
        if any(token in text for token in ("private", "independent", "catholic", "私立", "私校")):
            return "私校"
        return text_values[0] if text_values else self.school_plan_report_text("not_recorded")

    def school_plan_full_school_address(self, basic, row=None):
        basic = basic or {}
        row = row or {}
        address = str(basic.get("address") or basic.get("campus_locations") or row.get("address") or "").strip()
        suburb = str(basic.get("suburb") or row.get("suburb") or "").strip()
        state = str(basic.get("state") or row.get("state") or "").strip()
        postcode = str(basic.get("postcode") or row.get("postcode") or "").strip()
        address_key = address.lower()
        location_parts = []
        if suburb and suburb.lower() not in address_key:
            location_parts.append(suburb)
        if state and state.lower() not in address_key:
            location_parts.append(state)
        if postcode and postcode not in address:
            location_parts.append(postcode)
        if address and location_parts:
            return f"{address}, {' '.join(location_parts)}"
        return address or " ".join(part for part in [suburb, state, postcode] if part)

    def school_plan_comparison_rows(self, snapshot):
        rows = []
