    def school_plan_application_year_range_display(self, basic, row=None):
        data = {}
        if row:
            data.update(row)
        data.update(basic or {})
        if school_report_prep_to_year12_fallback(data):
            return "Prep-Year 12 / 全年级"
        year_pattern = (basic or {}).get("accepted_international_year_level_pattern") or (basic or {}).get("year_levels") or (row or {}).get("year_levels")
        raw_year_range, raw_start, _raw_end = school_report_year_range_from_raw_levels(data.get("year_levels"))
        pattern_start = {
            "Year7Plus": 7,
            "Year8Plus": 8,
            "Year9Plus": 9,
            "Year10Plus": 10,
            "Year11Plus": 11,
        }.get(str(year_pattern or "").strip())
        if raw_year_range and pattern_start is not None and raw_start is not None and raw_start < pattern_start:
            return raw_year_range
        return self.school_plan_report_display_text(year_pattern)

