    def school_plan_table_rows_html(self, rows, empty_text, cells):
        if not rows:
            return f'<tr><td colspan="{len(cells)}" class="empty">{esc(empty_text)}</td></tr>'
        rendered = []
        for row in rows:
            rendered.append("<tr>" + "".join(cell(row) for _label, cell in cells) + "</tr>")
        return "".join(rendered)

