    def school_plan_snapshot_area_safety_html(self, school):
        rows = self.school_plan_report_safety_rows(school)
        context = self.school_plan_area_safety_context(school, rows)
        zone_cards = [
            ("所在城区", context["suburb"] or "待识别", f"{context['state']} {context['postcode']}".strip()),
            (context["area_label"], context["matched_area"], f"统计口径：{context['data_level_label']}"),
            ("最新统计周期", context["period"], f"更新时间：{context['checked_at']}"),
        ]
        metric_items = zone_cards + [(label, value, "") for label, value in context["metrics"]]
        metric_cards = "".join(
            self.school_plan_snapshot_metric(label, value, note)
            for label, value, note in metric_items
        )
        row_html = "".join(
            f"<tr><td>{esc(row.get('area_type') or row.get('data_level') or 'radius')}</td><td>{esc(row.get('suburb') or row.get('postcode') or row.get('lga_name') or '')}</td><td>{esc(row.get('total_offence_count') or '')}</td><td>{esc(row.get('offence_rate_per_100k') or '')}</td><td>{esc(row.get('source_period') or '')}</td><td>{esc(row.get('confidence_level') or '')}</td><td>{esc(display_datetime(row.get('last_calculated_at')))}</td></tr>"
            for row in rows
        ) or '<tr><td colspan="7"><div class="pdf-placeholder">Area safety data not available in CRM</div></td></tr>'
        return f"""<div class="pdf-module">
          <div class="pdf-section-title"><h3>学校所在区域安全数据</h3><p>该数据为学校所在区域的官方统计参考，不代表学校本身安全程度。</p></div>
          <div class="pdf-kpi-grid">{metric_cards}</div>
          <table class="pdf-table"><thead><tr><th>Area type</th><th>Area</th><th>Total offences</th><th>Rate / 100k</th><th>Source period</th><th>Confidence</th><th>Last updated</th></tr></thead><tbody>{row_html}</tbody></table>
        </div>"""

    def school_plan_snapshot_area_profile_html(self, school):
        profile = school.get("area_profile_snapshot") or {}
        metrics = {row.get("metric_key"): row for row in (school.get("area_profile_metrics_snapshot") or [])}
        labels = dict((key, label) for key, label, _unit in SCHOOL_AREA_PROFILE_METRICS)

        def metric_value(key):
            return self.school_area_profile_display_value(metrics.get(key)) or "Data not available in CRM"

        metric_cards = "".join([
            self.school_plan_snapshot_metric("Suburb", profile.get("suburb"), f"{profile.get('state') or ''} {profile.get('postcode') or ''}"),
            self.school_plan_snapshot_metric("LGA", profile.get("lga_name") or profile.get("lga_code"), "ABS / ASGS"),
            self.school_plan_snapshot_metric("SA2", profile.get("sa2_name") or profile.get("sa2_code"), f"Source year {profile.get('data_year') or 'Not recorded'}"),
            self.school_plan_snapshot_metric("Population", metric_value("total_population"), labels.get("total_population", "")),
            self.school_plan_snapshot_metric("Median income", metric_value("median_household_income"), "Household weekly income"),
            self.school_plan_snapshot_metric("中国背景人数", metric_value("chinese_ancestry_count"), "ABS Ancestry count"),
            self.school_plan_snapshot_metric("澳洲背景人数", metric_value("australian_ancestry_count"), "ABS Ancestry count"),
            self.school_plan_snapshot_metric("Mandarin / Cantonese", f"{metric_value('mandarin_home_percent')} / {metric_value('cantonese_home_percent')}", "Language spoken at home"),
        ])
        return f"""<div class="pdf-module">
          <div class="pdf-section-title"><h3>学校所在区域资料</h3><p>Source: {esc(profile.get('source') or 'ABS Data API')} · Year: {esc(profile.get('data_year') or 'Not recorded')} · Last checked: {esc(display_datetime(profile.get('last_checked_at')))}</p></div>
          <div class="pdf-kpi-grid">{metric_cards}</div>
          <table class="pdf-table"><thead><tr><th>Theme</th><th>CRM value</th><th>Family living reference</th></tr></thead><tbody>
            <tr><td>Family composition</td><td>{esc(metric_value('family_household_percent'))} family households; {esc(metric_value('couple_family_with_children_percent'))} couples with children</td><td>Family living reference</td></tr>
            <tr><td>Housing type</td><td>Rent {esc(metric_value('rented_percent'))}; owned with mortgage {esc(metric_value('owned_with_mortgage_percent'))}; owned outright {esc(metric_value('owned_outright_percent'))}</td><td>Housing profile reference</td></tr>
            <tr><td>Education</td><td>{esc(metric_value('bachelor_degree_or_above_percent'))} bachelor degree or above</td><td>Demographic summary</td></tr>
          </tbody></table>
          {'' if profile else '<div class="pdf-placeholder">Area profile data not available in CRM</div>'}
        </div>"""

