    def school_plan_professional_report_html(self, snapshot, report=None):
        report = report or {}
        student = snapshot.get("student") or {}
        student_name = self.school_plan_student_name(student)
        version = snapshot.get("report_version") or report.get("report_version") or 1
        generated = display_datetime(snapshot.get("generated_at") or report.get("created_at"))
        consultant = (snapshot.get("generated_by") or {}).get("name") or report.get("created_by_name") or ""
        schools = snapshot.get("schools") or []
        comparison = self.school_plan_enrich_comparison_context(self.school_plan_comparison_rows(snapshot))
        school_cards = []
        for index, row in enumerate(comparison, 1):
            school = row["raw"]
            basic = school.get("basic_info") or {}
            profile = school.get("school_profile_data") or {}
            market5 = self.school_plan_first(school.get("market_cost") or [], radius_km=5) or {}
            safety = self.school_plan_first(school.get("crime_snapshot") or school.get("area_safety_reference") or []) or {}
            gender = self.school_plan_option_label(SCHOOL_GENDER_TYPE_OPTIONS, basic.get("school_gender_type") or "Coeducational")
            interview = self.school_plan_option_label(SCHOOL_INTERVIEW_REQUIRED_OPTIONS, self.school_effective_interview_required({**row, **basic}))
            school_cards.append(f"""<div class="pdf-card">
              <div class="pdf-section-title"><h3>{esc(index)}. {esc(row['name'])}</h3><p>{esc(row['suburb'])} {esc(row['state'])} {esc(row['postcode'])}</p></div>
              <div class="pdf-kpi-grid">
                {self.school_plan_snapshot_metric('学校性质', row.get('nature') or self.school_plan_school_nature_label(basic.get('sector_key'), basic.get('school_type')), '公校 / 私校')}
                {self.school_plan_snapshot_metric('Year levels', self.school_plan_application_year_range_display(basic, row), 'International student range')}
                {self.school_plan_snapshot_metric('Gender type', gender, '学校性别类型')}
                {self.school_plan_snapshot_metric('Interview', interview, '是否要求面试')}
                {self.school_plan_snapshot_metric('ICSEA', profile.get('school_icsea_value') or row.get('icsea'), 'ACARA')}
                {self.school_plan_snapshot_metric('Living cost', self.school_plan_snapshot_money(market5.get('median_weekly_rent_house'), suffix='/week'), '5km house rent')}
                {self.school_plan_snapshot_metric('Area safety', safety.get('total_offence_count'), '区域犯罪数据参考')}
              </div>
              <p><strong>Recommendation reason:</strong> Suitable option for comparison based on CRM school profile, fees, school data, living cost and area reference data.</p>
            </div>""")
        overview_html = "".join(school_cards) or '<div class="pdf-placeholder">No selected schools in this report snapshot.</div>'
        icsea_max = max([data_update_profile_number((school.get("school_profile_data") or {}).get("school_icsea_value")) or 0 for school in schools] + [1200])
        rent_max = max([market_number((self.school_plan_first(school.get("market_cost") or [], radius_km=5) or {}).get("median_weekly_rent_house")) or 0 for school in schools] + [1])
        dashboard_rows = "".join(
            f"<tr><td>{esc(row['name'])}</td><td>{esc(row['nature'])}</td><td>{esc(self.school_plan_value(row['icsea']))}</td><td>{esc(self.school_plan_value(row['enrolments']))}</td><td>{esc(self.school_plan_value(row['lbote']))}</td><td>{esc(self.school_plan_value(row['student_teacher_ratio']))}</td><td>{esc(self.school_plan_value(row['house_rent']))}</td><td>{esc(self.school_plan_value(row['safety']))}</td></tr>"
            for row in comparison
        )
        dashboard_charts = "".join(
            f"{self.school_plan_snapshot_bar(row['name'] + ' ICSEA', row['icsea'], icsea_max, 'blue')}{self.school_plan_snapshot_bar(row['name'] + ' 5km rent', (self.school_plan_first(row['raw'].get('market_cost') or [], radius_km=5) or {}).get('median_weekly_rent_house'), rent_max, 'teal')}"
            for row in comparison
        )
        school_sections = []
        for index, row in enumerate(comparison, 1):
            school = row["raw"]
            basic = school.get("basic_info") or {}
            year_pattern = basic.get("accepted_international_year_level_pattern") or "Unknown"
            accommodation = self.school_plan_option_label(SCHOOL_ACCOMMODATION_OPTIONS, self.school_default_accommodation_type(year_pattern, basic.get("accommodation_type") or "Unknown", basic.get("sector_key") or "", basic.get("school_type") or row.get("type") or ""))
            gender = self.school_plan_option_label(SCHOOL_GENDER_TYPE_OPTIONS, basic.get("school_gender_type") or "Coeducational")
            interview = self.school_plan_option_label(SCHOOL_INTERVIEW_REQUIRED_OPTIONS, self.school_effective_interview_required({**row, **basic}))
            basic_cards = "".join([
                self.school_plan_snapshot_metric("School name", basic.get("school_name") or row["name"], f"Campus: {basic.get('campus_name') or 'Not recorded in CRM'}"),
                self.school_plan_snapshot_metric("Address", self.school_plan_full_school_address(basic, row), "完整地址"),
                self.school_plan_snapshot_metric("学校性质", row.get("nature") or self.school_plan_school_nature_label(basic.get("sector_key"), basic.get("school_type") or row["type"]), "公校 / 私校"),
                self.school_plan_snapshot_metric("Website", basic.get("website_url") or row["website"], "Official website"),
                self.school_plan_snapshot_metric("学校性别类型", gender, "Gender type"),
                self.school_plan_snapshot_metric("是否要求面试", interview, "Interview requirement"),
                self.school_plan_snapshot_metric("学校类型", basic.get("school_type"), "CRM school type"),
                self.school_plan_snapshot_metric("年级范围", year_pattern, "Accepted international years"),
                self.school_plan_snapshot_metric("CRICOS code", basic.get("cricos_code"), "如有"),
                self.school_plan_snapshot_metric("International students", basic.get("accepts_international_students") or "Not recorded in CRM", "是否接受国际学生"),
            ])
            fee_table = self.school_plan_snapshot_public_fee_rows_html(school)
            school_sections.append(f"""<section class="pdf-school-section">
              <div class="pdf-card pdf-school-header"><div class="pdf-section-title"><h2>{esc(index)}. {esc(row['name'])}</h2><p>{esc(row['suburb'])} · {esc(row['state'])} {esc(row['postcode'])}</p></div><p>{esc(row['address'])}</p></div>
              <div class="pdf-module"><div class="pdf-section-title"><h3>School overview & basic information</h3><p>Data source: CRM school basic information snapshot</p></div><div class="pdf-kpi-grid">{basic_cards}</div><h4>兴趣标签 / school features</h4>{self.school_plan_snapshot_tags_html(basic)}<p><strong>学校简介:</strong> {esc(self.school_plan_snapshot_value(basic.get('school_description') or basic.get('profile_summary'), 'Not recorded in CRM'))}</p></div>
              <div class="pdf-module"><div class="pdf-section-title"><h3>学费</h3><p>Fee year, source and last updated are included when recorded in CRM.</p></div><table class="pdf-table"><thead><tr><th>Fee item</th><th>Amount</th><th>Fee year</th><th>Source</th><th>Last updated</th></tr></thead><tbody>{fee_table}</tbody></table></div>
              <div class="pdf-module"><div class="pdf-section-title"><h3>住宿与福利</h3><p>Under 18 accommodation and welfare reference from CRM school basic information.</p></div><div class="pdf-kpi-grid">
                {self.school_plan_snapshot_metric('Homestay available', 'Unknown' if accommodation == '未确认' else accommodation, 'Homestay available / not available / unknown')}
                {self.school_plan_snapshot_metric('Boarding available', accommodation, 'Boarding available / not available / unknown')}
                {self.school_plan_snapshot_metric('Welfare arrangement', basic.get('welfare_arrangement') or basic.get('caaw_welfare_notes') or 'Not recorded in CRM', 'CAAW / welfare notes')}
                {self.school_plan_snapshot_metric('Accommodation notes', basic.get('accommodation_notes') or 'Not recorded in CRM', 'School accommodation notes')}
              </div></div>
              {self.school_plan_snapshot_school_profile_html(school.get('school_profile_data') or {})}
              {self.school_plan_snapshot_living_html(school, basic)}
              {self.school_plan_snapshot_rankings_html(school)}
              {self.school_plan_snapshot_area_safety_html(school)}
              {self.school_plan_snapshot_area_profile_html(school)}
              <div class="pdf-module"><div class="pdf-section-title"><h3>Consultant notes</h3><p>For adviser use</p></div><div class="pdf-placeholder">Consultant notes not recorded in this CRM report version.</div></div>
            </section>""")
        modules = ", ".join(item.get("label") or item.get("key") or "" for item in (snapshot.get("selected_modules") or []))
        html_doc = f"""<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><title>AAIE School Plan Report</title><style>{self.school_plan_professional_report_css()}</style></head><body>
          <div class="pdf-header"><div><span class="brand-mark">A</span><strong>School Plan Report</strong></div><div>Student: {esc(student_name)} · Application Year Level: {esc(student.get('applying_year_level') or student.get('current_year_level') or 'Not set')} · Intake Year: {esc(student.get('preferred_intake_year') or 'Not set')}</div></div>
          <div class="pdf-footer"><div>AAIE · Confidential report</div><div>Report Version v{esc(version)} · Generated {esc(generated)} · Page <span class="page-number"></span></div></div>
          <div class="pdf-watermark">AAIE</div>
          <main>
            <section class="cover"><span class="brand-mark">A</span><h1>School Plan Report</h1><p>Professional school recommendation plan prepared from CRM snapshot data.</p><div class="cover-grid">
              <div class="cover-card"><span>Student</span><strong>{esc(student_name)}</strong></div>
              <div class="cover-card"><span>Application ID</span><strong>{esc(student.get('student_id') or '')}</strong></div>
              <div class="cover-card"><span>Year Level</span><strong>{esc(student.get('applying_year_level') or student.get('current_year_level') or 'Not set')}</strong></div>
              <div class="cover-card"><span>Intake Year</span><strong>{esc(student.get('preferred_intake_year') or 'Not set')}</strong></div>
              <div class="cover-card"><span>Consultant</span><strong>{esc(consultant or 'Not recorded')}</strong></div>
              <div class="cover-card"><span>Report Version</span><strong>v{esc(version)}</strong></div>
              <div class="cover-card"><span>Generated</span><strong>{esc(generated)}</strong></div>
              <div class="cover-card"><span>Company</span><strong>AAIE</strong></div>
            </div></section>
            <section class="pdf-page"><div class="pdf-section-title"><h2>Executive Summary</h2><p>Generated from CRM snapshot data. Existing reports keep their saved data.</p></div><div class="pdf-kpi-grid">
              {self.school_plan_snapshot_metric('Student', student_name, student.get('student_id') or '')}
              {self.school_plan_snapshot_metric('Recommended schools', len(schools), '本次推荐学校数量')}
              {self.school_plan_snapshot_metric('Selected modules', len(snapshot.get('selected_modules') or []), modules)}
              {self.school_plan_snapshot_metric('Recommendation logic', 'Profile + fees + data + living cost + area reference', '主要对比维度')}
            </div><div class="pdf-card"><h3>方案重点</h3><p>本报告按学生申请信息，对推荐学校的基础资料、费用、住宿福利、ACARA 学校数据、居住成本、区域犯罪数据参考、区域资料、排名和上传学校资料进行统一对比。</p></div>
            <div class="pdf-section-title"><h2>School Recommendation Overview</h2><p>Professional summary cards</p></div><div class="overview-grid">{overview_html}</div></section>
            <section class="pdf-page"><div class="pdf-section-title"><h2>School Comparison Dashboard</h2><p>综合对比表 + charts</p></div><table class="pdf-table"><thead><tr><th>School</th><th>学校性质</th><th>ICSEA</th><th>Enrolments</th><th>英语以外的语言背景</th><th>Student-teacher ratio</th><th>Living cost</th><th>Area safety reference</th></tr></thead><tbody>{dashboard_rows}</tbody></table><div class="pdf-chart-grid"><div class="pdf-chart"><h4>ICSEA / living cost comparison</h4>{dashboard_charts}</div><div class="pdf-chart"><h4>Dashboard dimensions</h4><div class="recommendation-list"><div>ICSEA comparison chart</div><div>Student enrolment / 英语以外的语言背景 / ratio comparison</div><div>Living cost and area safety data comparison</div></div></div></div></section>
            <section><div class="pdf-section-title"><h2>Individual School Detailed Pages</h2><p>Each school has a complete independent section.</p></div>{''.join(school_sections)}</section>
            <section class="pdf-page"><div class="pdf-section-title"><h2>Final Recommendation</h2><p>Recommended order and next steps</p></div><div class="recommendation-list">{''.join(f'<div><strong>{esc(idx)}. {esc(row["name"])}</strong><br>适合原因：结合学校资料、学费、学校数据、居住成本和区域资料作为申请比较选项。<br>注意事项：请顾问在提交申请前复核费用、名额、面试和住宿福利要求。<br>下一步：确认申请年级、入学年份、材料清单和学校申请截止日期。</div>' for idx, row in enumerate(comparison, 1))}</div></section>
          </main></body></html>"""
        return html_doc

    def school_plan_render_html(self, snapshot):
        return self.school_plan_snapshot_report_html(snapshot, {
            "student_id": (snapshot.get("student") or {}).get("student_id", ""),
            "status": "generated",
            "confirmed_at": "",
            "confirmed_by_name": "",
            "report_version": snapshot.get("report_version") or 1,
        })

    def school_plan_snapshot_crm_metric(self, label, value, note=""):
        return f"""<div><span>{esc(label)}</span><strong>{esc(self.school_plan_report_value(value, 'no_data'))}</strong><small>{esc(self.school_plan_report_display_text(note or ''))}</small></div>"""

    def school_plan_snapshot_profile_bar_html(self, label, value, max_value, klass=""):
        try:
            number = float(value)
            maximum = max(float(max_value or 0), number, 1)
            width = max(0, min(100, number / maximum * 100))
            display = self.school_plan_snapshot_number(value)
        except (TypeError, ValueError):
            width = 0
            display = "Data not available in CRM"
        zero_class = " is-zero" if width <= 0 else ""
        return f"""<div class="school-profile-bar {esc(klass)}{zero_class}"><span>{esc(label)}</span><div class="school-profile-value-track"><svg viewBox="0 0 100 10" preserveAspectRatio="none" role="img" aria-label="{esc(label)} {esc(display)}"><rect class="school-profile-value-bg" width="100" height="10" x="0" y="0" rx="5"></rect><rect class="school-profile-value-fill" width="{width:.1f}" height="10" x="0" y="0" rx="5"></rect></svg></div><strong>{esc(display)}</strong></div>"""

    def school_plan_snapshot_percent_bar_html(self, label, value, klass=""):
        try:
            width = max(0, min(100, float(value)))
            display = self.school_plan_snapshot_percent(value)
        except (TypeError, ValueError):
            width = 0
            display = "Data not available in CRM"
        zero_class = " is-zero" if width <= 0 else ""
        return f"""<div class="school-profile-bar {esc(klass)}{zero_class}"><span>{esc(label)}</span><div class="school-profile-percent-track"><svg viewBox="0 0 100 10" preserveAspectRatio="none" role="img" aria-label="{esc(label)} {esc(display)}"><rect class="school-profile-percent-bg" width="100" height="10" x="0" y="0" rx="5"></rect><rect class="school-profile-percent-fill" width="{width:.1f}" height="10" x="0" y="0" rx="5"></rect></svg></div><strong>{esc(display)}</strong></div>"""

    def school_plan_report_numeric_value(self, value):
        if value in (None, ""):
            return None
        match = re.search(r"-?\d+(?:,\d{3})*(?:\.\d+)?|-?\d+(?:\.\d+)?", str(value))
        if not match:
            return None
        try:
            return float(match.group(0).replace(",", ""))
        except ValueError:
            return None

    def school_plan_comparison_visuals_html(self, comparison):
        def metric_rows(value_getter, display_getter, name_getter=None):
            rows = []
            for row in comparison:
                number = value_getter(row)
                if number is None:
                    continue
                rows.append({
                    "name": (name_getter(row) if name_getter else row.get("name")) or "学校",
                    "number": number,
                    "display": display_getter(number),
                })
            return rows

        def vertical_chart(key, title, note, rows, baseline=None):
            if not rows:
                return ""
            baseline_value = baseline.get("value") if baseline else None
            baseline_label = baseline.get("label") if baseline else ""
            max_candidates = [item["number"] for item in rows]
            if baseline_value is not None:
                max_candidates.append(baseline_value)
            max_value = max(max_candidates) or 1
            baseline_note = ""
            columns = []
            for index, item in enumerate(rows):
                height = max(6, min(100, item["number"] / max_value * 100))
                baseline_line = ""
                if baseline_value is not None:
                    baseline_position = max(0, min(100, baseline_value / max_value * 100))
                    baseline_line = f"""<em class="report-comparison-standard-line" style="bottom:{baseline_position:.1f}%"></em>"""
                columns.append(f"""<div class="report-comparison-column">
                  <strong>{esc(item['display'])}</strong>
                  <div class="report-comparison-column-track">{baseline_line}<i style="height:{height:.1f}%"></i><b class="report-comparison-column-inside-label">{esc(item['name'])}</b></div>
                  <span>{esc(item['name'])}</span>
                </div>""")
            return f"""<article class="report-comparison-chart report-comparison-vertical-chart report-comparison-chart-{esc(key)}">
              <h3>{esc(title)}</h3>
              <p>{esc(note)}</p>
              {baseline_note}
              <div class="report-comparison-column-grid" style="grid-template-columns:repeat({len(rows)}, minmax(0, 1fr));">{''.join(columns)}</div>
            </article>"""

        def horizontal_chart(key, title, note, rows, max_value=None):
            if not rows:
                return ""
            max_value = max_value or max(item["number"] for item in rows) or 1
            bar_rows = []
            for item in rows:
                width = max(4, min(100, item["number"] / max_value * 100))
                bar_rows.append(f"""<div class="report-comparison-bar">
                  <div class="report-comparison-bar-head"><span>{esc(item['name'])}</span><strong>{esc(item['display'])}</strong></div>
                  <div class="report-comparison-track"><i style="width:{width:.1f}%"></i></div>
                </div>""")
            return f"""<article class="report-comparison-chart report-comparison-horizontal-chart report-comparison-chart-{esc(key)}">
              <h3>{esc(title)}</h3>
              <p>{esc(note)}</p>
              <div class="report-comparison-bars">{''.join(bar_rows)}</div>
            </article>"""

        def chinese_ancestry_rows():
            rows = []
            for row in comparison:
                count = self.school_plan_report_numeric_value(row.get("chinese_ancestry_count"))
                total = self.school_plan_report_numeric_value(row.get("area_total_population"))
                if count is None or total is None or total <= 0:
                    continue
                percent = count / total * 100
                rows.append({
                    "name": row.get("area_profile_label") or row.get("suburb") or "学校所在区域",
                    "number": percent,
                    "display": f"{self.school_plan_report_percent(percent)} · {self.school_plan_report_number(count)} / {self.school_plan_report_number(total)} 人",
                })
            return rows

        def pie_chart(key, title, note, rows):
            if not rows:
                return ""
            palette = ["#7c3aed", "#0891b2", "#f59e0b", "#16a34a", "#dc2626", "#2563eb"]
            pies = []
            for index, item in enumerate(rows):
                percent = max(0, min(100, item["number"]))
                remaining = max(0, 100 - percent)
                color = palette[index % len(palette)]
                pies.append(f"""<div class="report-comparison-pie">
                  <svg class="report-comparison-pie-svg" viewBox="0 0 42 42" role="img" aria-label="{esc(item['name'])} {esc(item['display'])}">
                    <circle class="report-comparison-pie-bg" cx="21" cy="21" r="15.9" pathLength="100"></circle>
                    <circle class="report-comparison-pie-fill" cx="21" cy="21" r="15.9" pathLength="100" stroke="{esc(color)}" stroke-dasharray="{percent:.1f} {remaining:.1f}" transform="rotate(-90 21 21)"></circle>
                    <circle class="report-comparison-pie-hole" cx="21" cy="21" r="10.7"></circle>
                    <text x="21" y="22.5" text-anchor="middle">{esc(item['display'])}</text>
                  </svg>
                  <strong>{esc(item['name'])}</strong>
                </div>""")
            return f"""<article class="report-comparison-chart report-comparison-pie-chart report-comparison-chart-{esc(key)}">
              <h3>{esc(title)}</h3>
              <p>{esc(note)}</p>
              <div class="report-comparison-pies">{''.join(pies)}</div>
            </article>"""

        def ratio_pie_chart(key, title, note, rows):
            if not rows:
                return ""
            palette = ["#f59e0b", "#dc2626", "#0891b2", "#7c3aed", "#16a34a", "#2563eb"]
            max_value = max(item["number"] for item in rows) or 1
            pies = []
            for index, item in enumerate(rows):
                percent = max(0, min(100, item["number"] / max_value * 100))
                remaining = max(0, 100 - percent)
                color = palette[index % len(palette)]
                display = f"{item['display']}:1"
                pies.append(f"""<div class="report-comparison-pie">
                  <svg class="report-comparison-pie-svg" viewBox="0 0 42 42" role="img" aria-label="{esc(item['name'])} {esc(display)}">
                    <circle class="report-comparison-pie-bg" cx="21" cy="21" r="15.9" pathLength="100"></circle>
                    <circle class="report-comparison-pie-fill" cx="21" cy="21" r="15.9" pathLength="100" stroke="{esc(color)}" stroke-dasharray="{percent:.1f} {remaining:.1f}" transform="rotate(-90 21 21)"></circle>
                    <circle class="report-comparison-pie-hole" cx="21" cy="21" r="10.7"></circle>
                    <text x="21" y="22.5" text-anchor="middle">{esc(display)}</text>
                  </svg>
                  <strong>{esc(item['name'])}</strong>
                </div>""")
            return f"""<article class="report-comparison-chart report-comparison-pie-chart report-comparison-ratio-pie-chart report-comparison-chart-{esc(key)}">
              <h3>{esc(title)}</h3>
              <p>{esc(note)}</p>
              <div class="report-comparison-pies">{''.join(pies)}</div>
            </article>"""

        def gender_pie_chart():
            rows = []
            for row in comparison:
                boys_count = self.school_plan_report_numeric_value(row.get("boys_count"))
                girls_count = self.school_plan_report_numeric_value(row.get("girls_count"))
                boys_percent = self.school_plan_report_numeric_value(row.get("boys_percentage"))
                girls_percent = self.school_plan_report_numeric_value(row.get("girls_percentage"))
                if boys_count is not None and girls_count is not None and boys_count + girls_count > 0:
                    total = boys_count + girls_count
                    boys_percent = boys_count / total * 100
                    girls_percent = girls_count / total * 100
                elif boys_percent is not None and girls_percent is None:
                    girls_percent = max(0, 100 - boys_percent)
                elif girls_percent is not None and boys_percent is None:
                    boys_percent = max(0, 100 - girls_percent)
                if boys_percent is None or girls_percent is None:
                    continue
                boys_percent = max(0, min(100, boys_percent))
                girls_percent = max(0, min(100, girls_percent))
                rows.append({
                    "name": row.get("name") or "学校",
                    "boys_count": boys_count,
                    "girls_count": girls_count,
                    "boys_percent": boys_percent,
                    "girls_percent": girls_percent,
                })
            if not rows:
                return ""
            pies = []
            for item in rows:
                boys_label = self.school_plan_report_percent(item["boys_percent"])
                girls_label = self.school_plan_report_percent(item["girls_percent"])
                boys_count_label = self.school_plan_report_number(item["boys_count"]) if item["boys_count"] is not None else "未记录"
                girls_count_label = self.school_plan_report_number(item["girls_count"]) if item["girls_count"] is not None else "未记录"
                pies.append(f"""<div class="report-comparison-pie report-comparison-gender-pie">
                  <svg class="report-comparison-pie-svg" viewBox="0 0 42 42" role="img" aria-label="{esc(item['name'])} 男生 {esc(boys_label)} 女生 {esc(girls_label)}">
                    <circle class="report-comparison-pie-bg report-comparison-gender-girls" cx="21" cy="21" r="15.9" pathLength="100"></circle>
                    <circle class="report-comparison-pie-fill report-comparison-gender-boys" cx="21" cy="21" r="15.9" pathLength="100" stroke="#2563eb" stroke-dasharray="{item['boys_percent']:.1f} {item['girls_percent']:.1f}" transform="rotate(-90 21 21)"></circle>
                    <circle class="report-comparison-gender-hole" cx="21" cy="21" r="10.7"></circle>
                    <g class="report-comparison-gender-center-label">
                      <text x="21" y="19.7" text-anchor="middle">男 {esc(boys_label)}</text>
                      <text x="21" y="24.2" text-anchor="middle">女 {esc(girls_label)}</text>
                    </g>
                  </svg>
                  <strong>{esc(item['name'])}</strong>
                  <span><i class="boys"></i>男生 {esc(boys_count_label)} · <i class="girls"></i>女生 {esc(girls_count_label)}</span>
                </div>""")
            return f"""<article class="report-comparison-chart report-comparison-pie-chart report-comparison-gender-chart report-comparison-chart-gender">
              <h3>男女生对比</h3>
              <p>每所学校一个饼图，蓝色为男生，粉色为女生；数据来源：当前学校资料库及 ACARA 学校数据。</p>
              <div class="report-comparison-pies">{''.join(pies)}</div>
            </article>"""

        chart_cards = [
            vertical_chart(
                "icsea",
                "ICSEA 对比",
                "ICSEA 高于 1000，说明学校学生背景整体高于全国参考值。",
                metric_rows(lambda row: self.school_plan_report_numeric_value(row.get("icsea")), self.school_plan_report_number),
                {"value": 1000, "label": ""},
            ),
            vertical_chart(
                "enrolments",
                "学生人数对比",
                "学生人数用于参考学校规模、课程覆盖和同伴群体。",
                metric_rows(lambda row: self.school_plan_report_numeric_value(row.get("enrolments")), self.school_plan_report_number),
            ),
            pie_chart(
                "lbote",
                "英语以外的语言背景对比",
                "每个圆环显示该校英语以外语言背景学生占比。",
                metric_rows(lambda row: self.school_plan_report_numeric_value(row.get("lbote")), self.school_plan_report_percent),
            ),
            gender_pie_chart(),
            ratio_pie_chart(
                "student_teacher_ratio",
                "师生比对比",
                "数值越低，通常代表每名教师覆盖的学生更少。",
                metric_rows(lambda row: self.school_plan_report_numeric_value(row.get("student_teacher_ratio")), self.school_plan_report_value),
            ),
            horizontal_chart(
                "house_rent",
                "居住成本对比",
                "学校周边 5km 独立屋租金中位数；满格按 AU$3000 / 周计算。",
                metric_rows(lambda row: self.school_plan_report_numeric_value(row.get("house_rent")), lambda value: self.school_plan_report_money(value, " / 周")),
                max_value=3000,
            ),
            horizontal_chart(
                "safety",
                "区域安全参考对比",
                "区域官方记录犯罪总数参考；满格按 10000 宗计算，不代表学校本身安全程度。",
                metric_rows(
                    lambda row: self.school_plan_report_numeric_value(row.get("safety")),
                    self.school_plan_report_number,
                    lambda row: row.get("safety_area_label") or row.get("suburb") or "学校所在区域",
                ),
                max_value=10000,
            ),
            horizontal_chart(
                "chinese_ancestry_count",
                "中国背景人数对比",
                "分母为该学校所在区域总人口；条形长度按中国背景人数占区域总人口比例显示。",
                chinese_ancestry_rows(),
                max_value=100,
            ),
        ]
        chart_cards = [card for card in chart_cards if card]
        if not chart_cards:
            return ""
        return f"""<div class="report-comparison-visuals">{''.join(chart_cards)}</div>"""

    def school_plan_cbd_relative_map_html(self, basic, row, area_profile, school=None):
        basic = basic or {}
        row = row or {}
        area_profile = area_profile or {}
        school = school or {}
        state = str(area_profile.get("state") or basic.get("state") or row.get("state") or "").strip().upper()
        suburb = area_profile.get("suburb") or basic.get("suburb") or row.get("suburb") or ""
        postcode = area_profile.get("postcode") or basic.get("postcode") or row.get("postcode") or ""
        location_label = " · ".join(part for part in [suburb, " ".join(part for part in [state, postcode] if part)] if part) or self.school_plan_report_text("no_data")
        cbd = SCHOOL_CBD_COORDS.get(state)
        try:
            lat = float(basic.get("latitude"))
            lng = float(basic.get("longitude"))
        except (TypeError, ValueError):
            lat = None
            lng = None
        if not cbd or lat is None or lng is None:
            summary_html = f"""<div><span>学校到 CBD</span><strong>{esc(location_label)}</strong><small>学校缺少可用坐标，暂不能计算 CBD 距离</small></div>"""
            return summary_html, f"""<div class="report-empty">{esc(self.school_plan_report_text('map_unavailable'))}</div>"""
        def relative_point(point_lat, point_lng):
            distance_km = living_cost_haversine_km(point_lat, point_lng, cbd["latitude"], cbd["longitude"])
            avg_lat = math.radians((point_lat + float(cbd["latitude"])) / 2)
            dx_km = (point_lng - float(cbd["longitude"])) * 111.320 * math.cos(avg_lat)
            dy_km = (point_lat - float(cbd["latitude"])) * 110.574
            direction_parts = []
            if abs(dy_km) >= 1:
                direction_parts.append("北" if dy_km > 0 else "南")
            if abs(dx_km) >= 1:
                direction_parts.append("东" if dx_km > 0 else "西")
            return {
                "distance_km": distance_km,
                "distance_text": f"距 {cbd['label']} 约 {distance_km:.1f} km",
                "direction": "".join(direction_parts) or "附近",
                "dx_km": dx_km,
                "dy_km": dy_km,
            }

        school_point = relative_point(lat, lng)
        summary_html = f"""<div><span>学校到 CBD</span><strong>学校到 {esc(cbd['label'])}：约 {school_point['distance_km']:.1f} km</strong><small>{esc(school_point['distance_text'])} · {esc(school_point['direction'])}方向 · 直线距离</small></div>"""
        map_data_uri = str(school.get("map_snapshot_image_data_uri") or "").strip()
        if map_data_uri.startswith("data:image/") and len(map_data_uri) > 2000:
            school_name = basic.get("school_name") or row.get("name") or "学校"
            map_alt = f"{school_name} · {location_label} 到 {cbd['label']} 的地图照片"
            map_html = f"""<div class="report-city-cbd-map-photo-frame"><img class="report-city-cbd-map-photo" src="{esc(map_data_uri)}" alt="{esc(map_alt)}" loading="lazy"></div>"""
        else:
            map_html = f"""<div class="report-empty">地图截图暂时无法生成。请以学校到 {esc(cbd['label'])} 的直线距离说明为准。</div>"""
        return summary_html, map_html

    def school_plan_pdf_font_face_css(self):
        if all(path.is_file() for path in SCHOOL_PLAN_REPORT_FONT_FILES.values()):
            regular = SCHOOL_PLAN_REPORT_FONT_FILES[400].as_uri()
            medium = SCHOOL_PLAN_REPORT_FONT_FILES[500].as_uri()
            bold = SCHOOL_PLAN_REPORT_FONT_FILES[700].as_uri()
            return f"""
        @font-face {{ font-family: "Noto Sans CJK SC"; src: url("{regular}") format("truetype"); font-weight: 400; font-style: normal; font-display: block; }}
        @font-face {{ font-family: "Noto Sans CJK SC"; src: url("{medium}") format("truetype"); font-weight: 500 600; font-style: normal; font-display: block; }}
        @font-face {{ font-family: "Noto Sans CJK SC"; src: url("{bold}") format("truetype"); font-weight: 700 800; font-style: normal; font-display: block; }}
        """
        for font_path in (
            Path("/Library/Fonts/SourceHanSansSC-Regular.otf"),
            Path("/Library/Fonts/Source Han Sans SC Regular.otf"),
            Path("/Library/Fonts/NotoSansCJKsc-Medium.otf"),
            Path("/Library/Fonts/NotoSansCJKsc-Regular.otf"),
            Path("/Library/Fonts/Noto Sans CJK SC.ttc"),
            Path("/Library/Fonts/NotoSansSC-Regular.ttf"),
            Path("/Library/Fonts/AlibabaPuHuiTi-3-55-Regular.ttf"),
            Path("/Library/Fonts/Alibaba PuHuiTi 3.0.ttf"),
            Path("/Library/Fonts/HarmonyOS_Sans_SC_Regular.ttf"),
            Path("/Library/Fonts/HarmonyOS Sans SC.ttf"),
            Path("/Library/Fonts/MiSans-Regular.ttf"),
            Path("/Library/Fonts/MiSans.ttf"),
            Path("/System/Library/Fonts/STHeiti Medium.ttc"),
        ):
            if font_path.is_file():
                font_format = "truetype" if font_path.suffix.lower() in {".ttf", ".ttc"} else "opentype"
                return f"""@font-face {{ font-family: "Noto Sans CJK SC"; src: url("{font_path.as_uri()}") format("{font_format}"); font-weight: 400 800; font-style: normal; font-display: block; }}"""
        return ""

