        styles = {
            "title": ParagraphStyle("SchoolPlanTitle", fontName=bold_font, fontSize=24, leading=29, textColor=colors.HexColor("#10233f"), spaceAfter=10),
            "h1": ParagraphStyle("SchoolPlanH1", fontName=bold_font, fontSize=16, leading=20, textColor=colors.HexColor("#10233f"), spaceBefore=8, spaceAfter=8),
            "h2": ParagraphStyle("SchoolPlanH2", fontName=font, fontSize=12.8, leading=16.5, textColor=colors.HexColor("#145cc8"), spaceBefore=7, spaceAfter=6),
            "body": ParagraphStyle("SchoolPlanBody", fontName=regular_font, fontSize=9, leading=12.4, textColor=colors.HexColor("#172033")),
            "small": ParagraphStyle("SchoolPlanSmall", fontName=regular_font, fontSize=7.4, leading=9.8, textColor=colors.HexColor("#4B5563")),
            "center": ParagraphStyle("SchoolPlanCenter", fontName=regular_font, fontSize=10, leading=13, alignment=TA_CENTER),
            "brand_zh": ParagraphStyle("SchoolPlanBrandZh", fontName=bold_font, fontSize=12.5, leading=16, alignment=TA_CENTER, textColor=colors.HexColor("#10233f")),
            "brand_zh_subtitle": ParagraphStyle("SchoolPlanBrandZhSubtitle", fontName=font, fontSize=9.2, leading=12.2, alignment=TA_CENTER, textColor=colors.HexColor("#334155")),
            "brand_en": ParagraphStyle("SchoolPlanBrandEn", fontName=font, fontSize=8.2, leading=10.8, alignment=TA_CENTER, textColor=colors.HexColor("#475569")),
            "brand_en_subtitle": ParagraphStyle("SchoolPlanBrandEnSubtitle", fontName=regular_font, fontSize=7.4, leading=9.8, alignment=TA_CENTER, textColor=colors.HexColor("#64748b")),
        }

        def p(text, style="body"):
            return Paragraph(str(text or ""), styles[style])

        def zh_display(value):
            text = str(value or "").strip()
            replacements = {
                "Yes": "是",
                "No": "否",
                "Unknown": "暂未收录，需进一步确认",
                "Homestay": "寄宿家庭",
                "Boarding": "校内住宿",
                "Junior Secondary Tuition": "初中阶段学费",
                "Senior Secondary Tuition": "高中阶段学费",
                "Primary Tuition": "小学阶段学费",
                "Tuition": "学费",
                "Secondary": "中学",
                "Coeducational": "混校",
                "Boys": "男校",
                "Girls": "女校",
            }
            if text in replacements:
                return replacements[text]
            phrase_replacements = {
                "Homestay": "寄宿家庭",
                "Boarding": "校内住宿",
                "Junior Secondary Tuition": "初中阶段学费",
                "Senior Secondary Tuition": "高中阶段学费",
                "Primary Tuition": "小学阶段学费",
                "Tuition": "学费",
                "Secondary": "中学",
                "Coeducational": "混校",
            }
            for source, target in phrase_replacements.items():
                text = text.replace(f" / {source}", f" / {target}").replace(source, target)
            return text

        def section_title(text, note=""):
            items = [p(text, "h1")]
            if note:
                items.append(p(note, "small"))
            return items

        def table(data, widths=None, header=True, font_size=7.8):
            converted = [[cell if hasattr(cell, "wrap") else p(cell, "small") for cell in row] for row in data]
            tbl = Table(converted, colWidths=widths, repeatRows=1 if header else 0, hAlign="LEFT")
            tbl.setStyle(TableStyle([
                ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#edf2f7") if header else colors.white),
                ("TEXTCOLOR", (0, 0), (-1, 0), colors.HexColor("#39465a")),
                ("FONTNAME", (0, 0), (-1, -1), regular_font),
                ("FONTNAME", (0, 0), (-1, 0), font if header else regular_font),
                ("FONTSIZE", (0, 0), (-1, -1), font_size),
                ("LEADING", (0, 0), (-1, -1), font_size + 2.2),
                ("GRID", (0, 0), (-1, -1), 0.3, colors.HexColor("#d9e0ea")),
                ("VALIGN", (0, 0), (-1, -1), "TOP"),
                ("LEFTPADDING", (0, 0), (-1, -1), 5),
                ("RIGHTPADDING", (0, 0), (-1, -1), 5),
                ("TOPPADDING", (0, 0), (-1, -1), 5),
                ("BOTTOMPADDING", (0, 0), (-1, -1), 5),
            ]))
            return tbl

        def kpi_grid(items):
            cells = []
            for label, value, note in items:
                cells.append([p(label, "small"), p(f"<b>{self.school_plan_report_value(zh_display(value))}</b>", "body"), p(note or "", "small")])
            rows = [cells[i:i + 3] for i in range(0, len(cells), 3)]
            for row in rows:
                while len(row) < 3:
                    row.append("")
            tbl = Table(rows, colWidths=[55 * mm, 55 * mm, 55 * mm], hAlign="LEFT")
            tbl.setStyle(TableStyle([
                ("BACKGROUND", (0, 0), (-1, -1), colors.HexColor("#f8fafc")),
                ("BOX", (0, 0), (-1, -1), 0.4, colors.HexColor("#d9e0ea")),
                ("INNERGRID", (0, 0), (-1, -1), 0.3, colors.HexColor("#e3e8ef")),
                ("VALIGN", (0, 0), (-1, -1), "TOP"),
                ("LEFTPADDING", (0, 0), (-1, -1), 7),
                ("RIGHTPADDING", (0, 0), (-1, -1), 7),
                ("TOPPADDING", (0, 0), (-1, -1), 7),
                ("BOTTOMPADDING", (0, 0), (-1, -1), 7),
            ]))
            return tbl

        class BrandLogoFlowable(Flowable):
            def __init__(self):
                super().__init__()
                self.logo_path = school_plan_brand_logo_path()
                self.width = 166 * mm
                self.height = 30 * mm

            def draw(self):
                c = self.canv
                c.saveState()
                try:
                    if not self.logo_path:
                        raise ValueError("missing logo")
                    reader = ImageReader(str(self.logo_path))
                    image_width, image_height = reader.getSize()
                    logo_w = 41 * mm
                    logo_h = 28 * mm
                    scale = min(logo_w / image_width, logo_h / image_height)
                    draw_width = image_width * scale
                    draw_height = image_height * scale
                    c.drawImage(reader, 0, 0, draw_width, draw_height, preserveAspectRatio=True, mask="auto")
                except Exception:
                    c.setFillColor(colors.HexColor("#475569"))
                    c.setFont(bold_font, 9)
                    c.drawString(0, 11 * mm, "AOYA")
                c.setFillColor(colors.HexColor("#10233f"))
                c.setFont(bold_font, 25)
                c.drawString(43 * mm, 10.5 * mm, "AAIE")
                c.setFillColor(colors.HexColor("#475569"))
                c.setFont(font, 7.6)
                c.drawString(43.5 * mm, 6 * mm, "Australian K-12 Education Advisory")
                c.restoreState()

        def brand_slogan_block():
            tbl = Table([
                [p(SCHOOL_PLAN_BRAND_SLOGAN["zh_slogan"], "brand_zh")],
                [p(SCHOOL_PLAN_BRAND_SLOGAN["zh_subtitle"], "brand_zh_subtitle")],
                [p(SCHOOL_PLAN_BRAND_SLOGAN["en_slogan"], "brand_en")],
                [p(SCHOOL_PLAN_BRAND_SLOGAN["en_subtitle"], "brand_en_subtitle")],
            ], colWidths=[166 * mm], hAlign="CENTER")
            tbl.setStyle(TableStyle([
                ("BACKGROUND", (0, 0), (-1, -1), colors.HexColor("#f8fafc")),
                ("BOX", (0, 0), (-1, -1), 0.4, colors.HexColor("#d9e0ea")),
                ("LEFTPADDING", (0, 0), (-1, -1), 8),
                ("RIGHTPADDING", (0, 0), (-1, -1), 8),
                ("TOPPADDING", (0, 0), (-1, 0), 8),
                ("BOTTOMPADDING", (0, 0), (-1, -1), 2),
                ("BOTTOMPADDING", (0, 3), (-1, 3), 8),
            ]))
            return tbl

        def bar_table(items):
            data = [["指标", "数值", "对比图"]]
            maximum = max([float(value or 0) for _label, value in items if str(value or "").replace(".", "", 1).isdigit()] + [1])
            for label, value in items:
                try:
                    number = float(value)
                    width_units = max(1, int(number / maximum * 20))
                    bar = "█" * width_units
                    display = self.school_plan_snapshot_number(value)
                except Exception:
                    bar = self.school_plan_report_text("no_data")
                    display = self.school_plan_report_text("no_data")
                data.append([label, display, bar])
            return table(data, widths=[52 * mm, 32 * mm, 82 * mm])

        class RadiusMapFlowable(Flowable):
            def __init__(self, image_data_uri=""):
                super().__init__()
                self.width = 160 * mm
                self.height = 82 * mm
                self.image_data_uri = str(image_data_uri or "")

            def draw(self):
                c = self.canv
                c.saveState()
                c.setStrokeColor(colors.HexColor("#9fb3ce"))
                c.setFillColor(colors.HexColor("#f8fafc"))
                c.roundRect(0, 0, self.width, self.height, 8, stroke=1, fill=1)
                try:
                    if not self.image_data_uri.startswith("data:image/"):
                        raise ValueError("missing map image")
                    payload = base64.b64decode(self.image_data_uri.split(",", 1)[1])
                    reader = ImageReader(io.BytesIO(payload))
                    image_width, image_height = reader.getSize()
                    scale = min(self.width / image_width, self.height / image_height)
                    draw_width = image_width * scale
                    draw_height = image_height * scale
                    c.drawImage(reader, (self.width - draw_width) / 2, (self.height - draw_height) / 2, draw_width, draw_height, preserveAspectRatio=True, mask="auto")
                except Exception:
                    c.setFillColor(colors.HexColor("#66758a"))
                    c.setFont(font, 10)
                    c.drawCentredString(self.width / 2, self.height / 2 + 8, "地图截图暂时无法生成")
                    c.setFont(font, 8)
                    c.drawCentredString(self.width / 2, self.height / 2 - 8, "请在 CRM 地图模块重新生成")
                c.restoreState()

        class ReportLabComparisonChartsFlowable(Flowable):
            def __init__(self, rows, font_name):
                super().__init__()
                self.rows = rows
                self.font_name = font_name
                self.width = 174 * mm
                self.height = 174 * mm

            def _short(self, text, limit=19):
                text = str(text or "")
                return text if len(text) <= limit else text[:limit - 1] + "…"

            def _panel(self, x, y, w, h, title, note=""):
                c = self.canv
                c.setStrokeColor(colors.HexColor("#d8e0ea"))
                c.setFillColor(colors.white)
                c.roundRect(x, y, w, h, 5, stroke=1, fill=1)
                c.setFillColor(colors.HexColor("#10233f"))
                c.setFont(bold_font, 8.2)
                c.drawString(x + 5 * mm, y + h - 8 * mm, title)
                if note:
                    c.setFillColor(colors.HexColor("#64748b"))
                    c.setFont(self.font_name, 5.9)
                    c.drawString(x + 5 * mm, y + h - 12 * mm, note)

            def _available(self, key):
                return [row for row in self.rows if row.get(key) is not None]

            def draw_vertical_chart(self, x, y, w, h, key, title, color="#2563eb", baseline=None, baseline_label=""):
                rows = self._available(key)
                self._panel(x, y, w, h, title, "竖向柱状图")
                if not rows:
                    self._empty(x, y, w, h)
                    return
                c = self.canv
                values = [row[key] for row in rows]
                if baseline is not None:
                    values.append(float(baseline))
                max_value = max(values) or 1
                plot_x = x + 9 * mm
                plot_y = y + 9 * mm
                plot_w = w - 18 * mm
                plot_h = h - 26 * mm
                if baseline is not None:
                    base_y = plot_y + max(0, min(1, float(baseline) / max_value)) * plot_h
                    c.setStrokeColor(colors.HexColor("#f97316"))
                    c.setDash(2, 2)
                    c.line(plot_x, base_y, plot_x + plot_w, base_y)
                    c.setDash()
                gap = 3 * mm
                bar_w = max(5 * mm, (plot_w - gap * (len(rows) - 1)) / max(1, len(rows)))
                for index, row in enumerate(rows):
                    bar_h = max(3 * mm, row[key] / max_value * plot_h)
                    bx = plot_x + index * (bar_w + gap)
                    c.setFillColor(colors.HexColor("#eef2f7"))
                    c.roundRect(bx, plot_y, bar_w, plot_h, 4, stroke=0, fill=1)
                    c.setFillColor(colors.HexColor(color))
                    c.roundRect(bx, plot_y, bar_w, bar_h, 4, stroke=0, fill=1)
                    c.setFillColor(colors.HexColor("#0f172a"))
                    c.setFont(self.font_name, 6.2)
                    c.drawCentredString(bx + bar_w / 2, plot_y + plot_h + 2 * mm, row.get(f"{key}_display") or self._format_number(row[key]))
                    c.setFillColor(colors.HexColor("#334155"))
                    c.setFont(self.font_name, 5.5)
                    c.drawCentredString(bx + bar_w / 2, y + 3.5 * mm, self._short(row["name"], 10))

            def draw_horizontal_chart(self, x, y, w, h, key, title, color="#0f766e", label_key="name", max_value=None):
                rows = self._available(key)
                self._panel(x, y, w, h, title, "横向条形图")
                if not rows:
                    self._empty(x, y, w, h)
                    return
                c = self.canv
                max_value = max_value or max(row[key] for row in rows) or 1
                start_y = y + h - 19 * mm
                row_gap = 8 * mm
                track_x = x + 32 * mm
                track_w = w - 47 * mm
                for index, row in enumerate(rows[:4]):
                    cy = start_y - index * row_gap
                    c.setFillColor(colors.HexColor("#334155"))
                    c.setFont(self.font_name, 5.8)
                    c.drawString(x + 5 * mm, cy + 1.2 * mm, self._short(row.get(label_key) or row["name"], 12))
                    c.setFillColor(colors.HexColor("#e2e8f0"))
                    c.roundRect(track_x, cy, track_w, 3.2 * mm, 1.6 * mm, stroke=0, fill=1)
                    c.setFillColor(colors.HexColor(color))
                    c.roundRect(track_x, cy, max(3 * mm, min(1, row[key] / max_value) * track_w), 3.2 * mm, 1.6 * mm, stroke=0, fill=1)
                    c.setFillColor(colors.HexColor("#0f172a"))
                    c.setFont(self.font_name, 5.8)
                    c.drawRightString(x + w - 5 * mm, cy + 1.2 * mm, row.get(f"{key}_display") or self._format_number(row[key]))

            def draw_pie_chart(self, x, y, w, h, key, title, note, colors_list):
                rows = self._available(key)
                self._panel(x, y, w, h, title, note)
                if not rows:
                    self._empty(x, y, w, h)
                    return
                c = self.canv
                radius = 9 * mm
                gap = (w - 12 * mm) / max(1, len(rows))
                for index, row in enumerate(rows[:4]):
                    cx = x + 6 * mm + gap * index + gap / 2
                    cy = y + h / 2 - 1 * mm
                    pct = max(0, min(100, row[key]))
                    color = colors.HexColor(colors_list[index % len(colors_list)])
                    c.setFillColor(colors.HexColor("#e2e8f0"))
                    c.circle(cx, cy, radius, stroke=0, fill=1)
                    c.setFillColor(color)
                    c.wedge(cx - radius, cy - radius, cx + radius, cy + radius, 90, -pct * 3.6, stroke=0, fill=1)
                    c.setFillColor(colors.white)
                    c.circle(cx, cy, radius * 0.55, stroke=0, fill=1)
                    c.setFillColor(colors.HexColor("#0f172a"))
                    c.setFont(self.font_name, 6.2)
                    c.drawCentredString(cx, cy - 1.8, row.get(f"{key}_display") or self._format_number(row[key]))
                    c.setFillColor(colors.HexColor("#334155"))
                    c.setFont(self.font_name, 5.4)
                    c.drawCentredString(cx, y + 4 * mm, self._short(row["name"], 9))

            def _format_number(self, value):
                if value is None:
                    return "暂未收录"
                if abs(value - round(value)) < 0.01:
                    return f"{int(round(value)):,}"
                return f"{value:.1f}"

            def _empty(self, x, y, w, h):
                c = self.canv
                c.setFillColor(colors.HexColor("#64748b"))
                c.setFont(self.font_name, 7)
                c.drawCentredString(x + w / 2, y + h / 2, "暂未收录")

            def draw(self):
                c = self.canv
                c.saveState()
                c.setFont(self.font_name, 7)
                gap = 5 * mm
                panel_w = (self.width - gap) / 2
                panel_h = (self.height - 3 * gap) / 4
                x1 = 0
                x2 = panel_w + gap
                y3 = 0
                y2 = panel_h + gap
                y1 = (panel_h + gap) * 2
                y0 = (panel_h + gap) * 3
                self.draw_vertical_chart(x1, y0, panel_w, panel_h, "icsea", "ICSEA 对比", "#2563eb", baseline=1000, baseline_label="")
                self.draw_vertical_chart(x2, y0, panel_w, panel_h, "enrolments", "学生人数对比", "#16a34a")
                self.draw_pie_chart(x1, y1, panel_w, panel_h, "lbote", "英语以外的语言背景对比", "每校不同颜色", ["#7c3aed", "#0891b2", "#f59e0b", "#16a34a"])
                self.draw_pie_chart(x2, y1, panel_w, panel_h, "ratio_percent", "师生比对比", "按最高师生比归一", ["#f59e0b", "#dc2626", "#0891b2", "#7c3aed"])
                self.draw_horizontal_chart(x1, y2, panel_w, panel_h, "rent", "居住成本对比", "#0f766e", max_value=3000)
                self.draw_horizontal_chart(x2, y2, panel_w, panel_h, "safety", "区域安全参考", "#f97316", label_key="safety_area_label", max_value=10000)
                self.draw_horizontal_chart(x1, y3, panel_w, panel_h, "chinese_ancestry_count", "中国背景人数对比", "#7c3aed", label_key="area_profile_label", max_value=100)
                c.restoreState()

        def header_footer(canvas_obj, doc):
            width, height = A4
            canvas_obj.saveState()
            header_logo = school_plan_brand_logo_path()
            if header_logo:
                try:
                    canvas_obj.drawImage(ImageReader(str(header_logo)), 12 * mm, height - 15 * mm, width=10 * mm, height=7 * mm, preserveAspectRatio=True, mask="auto")
                except Exception:
                    header_logo = None
            canvas_obj.setFillColor(colors.HexColor("#94a3b8"))
            canvas_obj.setFont(regular_font, 6.8)
            canvas_obj.drawString(24 * mm if header_logo else 12 * mm, height - 11.5 * mm, "AAIE School Advisory Report")
            canvas_obj.drawRightString(width - 12 * mm, height - 11.5 * mm, f"{student_name} · v{version} · {generated}")
            canvas_obj.setStrokeColor(colors.HexColor("#d9e0ea"))
            canvas_obj.line(12 * mm, height - 17 * mm, width - 12 * mm, height - 17 * mm)
            canvas_obj.setFillColor(colors.HexColor("#145cc8"), alpha=0.08)
            canvas_obj.setFont(regular_font, 54)
            canvas_obj.translate(width / 2, height / 2)
            canvas_obj.rotate(32)
            canvas_obj.drawCentredString(0, 0, "AAIE")
            canvas_obj.setFont(regular_font, 12)
            canvas_obj.drawCentredString(0, -16 * mm, f"Confidential · {student_name} · v{version}")
            canvas_obj.drawCentredString(0, -23 * mm, generated)
