        max_ratio = max([item["ratio"] for item in chart_rows if item.get("ratio") is not None] + [1])
        for item in chart_rows:
            if item.get("ratio") is not None:
                item["ratio_percent"] = item["ratio"] / max_ratio * 100
                item["ratio_percent_display"] = f"{item['ratio_display']}:1"
