    def higher_education_plan_item_create(self, method, plan_id):
        if method != "POST":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        university_id = int(self.form.get("provider_id"))
        pathway_id = int(self.form.get("pathway_combination_id"))
        course_level = self.form.get("course_level")
        with db.transaction() as conn:
            repo = HigherEducationRepository(conn)
            pathway = conn.execute(
                """SELECT c.pathway_code,c.display_name,c.final_course_level,
                          (SELECT count(*) FROM higher_education_pathway_segments s WHERE s.pathway_combination_id=c.id) segment_count
                   FROM higher_education_pathway_combinations c
                   WHERE c.id=? AND c.university_id=? AND c.active_status='Active'""",
                (pathway_id, university_id),
            ).fetchone()
            if not pathway:
                raise HigherEducationValidationError("所选大学不支持此升学路径")
            if course_level != pathway["final_course_level"]:
                raise HigherEducationValidationError("课程层级必须与所选升学路径的最终层级一致")
            course_id, _created = repo.create_or_get_course(
                university_id, self.form.get("course_name"), course_level,
                self.user["id"], now_iso(),
            )
            course_type = course_type_for_pathway(
                pathway["pathway_code"], pathway["segment_count"], pathway["final_course_level"]
            )
            item_id = repo.add_plan_item(
                int(plan_id), university_id, course_type, self.form.get("course_name"),
                self.form.get("intake"), self.user["id"], now_iso(),
                pathway_combination_id=pathway_id, course_id=course_id,
            )
        db.audit(self.user, "higher_education_plan_item_created", "higher_education", str(item_id))
        return self.flash_redirect("/higher-education", "大学申请已添加；课程库已同步。")

