    def australian_universities(self, method):
        if method != "GET":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        if not can_access_module(self.user, "school_library"):
            return self.school_action_denied("view")
        q = str((self.query.get("q") or [""])[0]).strip()[:120]
        state = str((self.query.get("state") or [""])[0]).strip().upper()
        status = str((self.query.get("status") or [""])[0]).strip().title()
        state = state if state in SCHOOL_DATA_IMPORT_STATES else ""
        status = status if status in {"Active", "Inactive"} else ""
        try:
            requested_page = max(1, int((self.query.get("page") or ["1"])[0]))
        except (TypeError, ValueError):
            requested_page = 1
        where = ["u.provider_type='University'"]
        params = []
        if q:
            where.append("(u.provider_name LIKE ? OR COALESCE(u.short_name,'') LIKE ? OR COALESCE(u.city,'') LIKE ?)")
            params.extend([f"%{q}%", f"%{q}%", f"%{q}%"])
        if state:
            where.append("UPPER(COALESCE(u.state,''))=?")
            params.append(state)
        if status:
            where.append("u.active_status=?")
            params.append(status)
        where_sql = " AND ".join(where)
        total_row = db.one(f"SELECT COUNT(*) total FROM higher_education_providers u WHERE {where_sql}", params)
        total = int(total_row["total"] or 0) if total_row else 0
        page_size = 12
        pages = max(1, (total + page_size - 1) // page_size)
        current_page = min(requested_page, pages)
        universities = db.all(
            f"""SELECT u.*,(SELECT count(*) FROM higher_education_pathway_combinations p
                             WHERE p.university_id=u.id AND p.active_status='Active') pathway_count
                FROM higher_education_providers u WHERE {where_sql}
                ORDER BY CASE u.active_status WHEN 'Active' THEN 0 ELSE 1 END,u.provider_name,u.id
                LIMIT ? OFFSET ?""",
            [*params, page_size, (current_page - 1) * page_size],
        )
        body = render_australian_universities_list(
            universities,
            can_manage=self.user.get("role_name") in {"Admin", "Manager"},
            csrf=self.csrf,
            filters={"q": q, "state": state, "status": status},
            pagination={"page": current_page, "page_size": page_size, "total": total, "pages": pages},
        )
        message, kind = self.message()
        self.send_html(page("Universities", body, self.user, self.csrf, "schools", nas.status(), message, kind))

    def australian_university_detail(self, method, university_id):
        if method != "GET":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        if not can_access_module(self.user, "school_library"):
            return self.school_action_denied("view")
        university = db.one(
            "SELECT * FROM higher_education_providers WHERE id=? AND provider_type='University'",
            (university_id,),
        )
        if not university:
            return self.error_page("University not found", HTTPStatus.NOT_FOUND)
        pathways = db.all(
            "SELECT * FROM higher_education_pathway_combinations WHERE university_id=? ORDER BY active_status DESC,display_name",
            (university_id,),
        )
        segments = db.all(
            """SELECT s.*,p.provider_name FROM higher_education_pathway_segments s
               JOIN higher_education_pathway_combinations c ON c.id=s.pathway_combination_id
               JOIN higher_education_providers p ON p.id=s.provider_id
               WHERE c.university_id=? ORDER BY c.id,s.segment_order""",
            (university_id,),
        )
        course_query = str((self.query.get("cq") or [""])[0]).strip()[:120]
        try:
            requested_course_page = max(1, int((self.query.get("cp") or ["1"])[0]))
        except (TypeError, ValueError):
            requested_course_page = 1
        course_where = ["university_id=?"]
        course_params = [university_id]
        if course_query:
            course_where.append("(course_name LIKE ? OR COALESCE(specialisation,'') LIKE ? OR course_level LIKE ?)")
            like_query = f"%{course_query}%"
            course_params.extend([like_query, like_query, like_query])
        course_where_sql = " AND ".join(course_where)
        course_total_row = db.one(
            f"SELECT COUNT(*) total FROM higher_education_courses WHERE {course_where_sql}",
            course_params,
        )
        course_total = int(course_total_row["total"] or 0) if course_total_row else 0
        course_page_size = 20
        course_pages = max(1, (course_total + course_page_size - 1) // course_page_size)
        course_page = min(requested_course_page, course_pages)
        courses = db.all(
            f"""SELECT * FROM higher_education_courses WHERE {course_where_sql}
                 ORDER BY active_status DESC,course_level,course_name,id LIMIT ? OFFSET ?""",
            [*course_params, course_page_size, (course_page - 1) * course_page_size],
        )
        providers = db.all(
            """SELECT DISTINCT p.id,p.provider_name FROM higher_education_providers p
               LEFT JOIN higher_education_provider_relationships r ON r.pathway_provider_id=p.id AND r.university_id=?
               WHERE p.active_status='Active' AND p.review_status='Approved'
                 AND (p.id=? OR r.id IS NOT NULL) ORDER BY p.provider_type,p.provider_name""",
            (university_id, university_id),
        )
        relationships = db.all(
            "SELECT * FROM higher_education_provider_relationships WHERE university_id=? ORDER BY id",
            (university_id,),
        )
        body = render_university_detail(
            university=university, pathways=pathways, segments=segments, courses=courses,
            providers=providers, relationships=relationships, csrf=self.csrf,
            can_manage=self.user.get("role_name") in {"Admin", "Manager"},
            list_context=(self.query.get("return_to") or [""])[0],
            course_filters={"cq": course_query},
            course_pagination={"page": course_page, "pages": course_pages, "total": course_total},
        )
        message, kind = self.message()
        self.send_html(page(university["provider_name"], body, self.user, self.csrf, "schools", nas.status(), message, kind))

