    def school_trusted_source_add(self, method, school_id):
        if method != "POST":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        if not self.require_school_action("edit"):
            return
        school = db.one("SELECT id FROM schools WHERE id=?", (school_id,))
        if not school:
            return self.error_page("学校不存在", HTTPStatus.NOT_FOUND)
        source_url = str(self.form.get("source_url", "")).strip()
        source_type = str(self.form.get("source_type", "Official Website")).strip() or "Official Website"
        source_notes = str(self.form.get("source_notes", "")).strip()
        if not source_url:
            return self.flash_redirect(f"/schools/{school_id}#trusted-sources", "Source URL 为必填项。", "error")
        source_id = db.execute(
            "INSERT INTO school_trusted_sources(school_id,source_url,source_type,source_notes,added_by,added_at,is_active) VALUES(?,?,?,?,?,?,1)",
            (school_id, source_url, source_type, source_notes, self.user["id"], now_iso()),
        )
        db.audit(self.user, "school_trusted_source_added", "school_library", record_id=source_id, new_value=source_url, ip=self.client_address[0], device=self.headers.get("User-Agent"))
        self.school_record_source(school_id, "trusted_sources", source_type, source_url, "", None, source_notes)
        return self.flash_redirect(f"/schools/{school_id}#trusted-sources", "可信来源已添加。")

    def school_collection_latest_source(self, school_id, source_name):
        return db.one(
            """SELECT ds.*,u.display_name added_name
               FROM school_data_sources ds
               LEFT JOIN users u ON u.id=ds.added_by
               WHERE ds.school_id=? AND ds.source_name=?
               ORDER BY ds.updated_at DESC,ds.id DESC LIMIT 1""",
            (school_id, source_name),
        )

    def school_collection_source_card_status(self, school, card, source):
        source_url = source["source_url"] if source else ""
        status = source["source_status"] if source else "Not Started"
        last_time = source["updated_at"] if source else ""
        review_status = "Needs Review" if source and source["source_status"] not in {"Approved", "Disabled", "Error"} else status
        error = ""
        if card["key"] == "official_website" and not source_url:
            source_url = school["website_url"] or ""
            status = "URL Added" if source_url else "Not Started"
            last_time = school["updated_at"] if source_url and "updated_at" in school.keys() else last_time
        if card["key"] == "bettereducation":
            rank = db.one("SELECT COUNT(*) count,MAX(imported_at) latest FROM school_academic_rankings WHERE school_id=?", (school["id"],))
            if rank and rank["count"]:
                status = "Imported"
                review_status = "Needs Review"
                last_time = rank["latest"] or last_time
        if card["key"] == "abs_suburb":
            status = school["suburb_data_status"] if "suburb_data_status" in school.keys() and school["suburb_data_status"] else status
            last_time = school["suburb_data_last_updated"] if "suburb_data_last_updated" in school.keys() and school["suburb_data_last_updated"] else last_time
        if source and source["notes"] and "error:" in source["notes"].lower():
            error = source["notes"]
        return source_url, status, review_status, last_time, error

    def school_information_collection_panel(self, school):
        if not can_school_action(self.user, "view_collection_center"):
            return ""
        cards = []
        can_manage = can_school_action(self.user, "manage_source_urls")
        can_manual = can_school_action(self.user, "review_collected_data") or can_school_action(self.user, "manage_source_urls")
        for card in SCHOOL_COLLECTION_SOURCE_CARDS:
            source = self.school_collection_latest_source(school["id"], card["source_name"])
            source_url, status, review_status, last_time, error = self.school_collection_source_card_status(school, card, source)
            status_class = "ok" if status in {"Approved", "Fetched", "Imported", "URL Added", "Active"} else ("bad" if status == "Error" else "warn")
            fetch_label = "Fetch / Import"
            if card["key"] == "bettereducation":
                fetch_label = "打开排名导入"
            elif card["key"] == "abs_suburb":
                fetch_label = "打开学区数据"
            fetch_action = (
                '<a class="secondary button-link compact" href="/schools/rankings">打开排名导入</a>' if card["key"] == "bettereducation"
                else f'<a class="secondary button-link compact" href="/schools/{school["id"]}#suburb-data">打开学区数据</a>' if card["key"] == "abs_suburb"
                else '<button class="secondary compact" type="button" disabled>Fetch 后续接入</button>'
            )
            source_form = ""
            if can_manage:
                source_form = f"""<form class="collection-source-form" method="post" action="/schools/{school['id']}/collection/source">
                  <input type="hidden" name="csrf" value="{esc(self.csrf)}">
                  <input type="hidden" name="source_key" value="{esc(card['key'])}">
                  <input type="hidden" name="source_name" value="{esc(card['source_name'])}">
                  <input type="hidden" name="source_type" value="{esc(card['source_type'])}">
                  <label>Source URL<input name="source_url" value="{esc(source_url)}" placeholder="https://..."></label>
                  <label>Status<select name="source_status">{self.school_option_tags([(key, value) for key, value in SCHOOL_COLLECTION_STATUS_LABELS.items()], status)}</select></label>
                  <label class="wide">Notes<input name="notes" value="{esc(source['notes'] if source else '')}" placeholder="来源说明、错误信息或人工备注"></label>
                  <button class="secondary compact">保存来源</button>
                </form>"""
            manual_form = ""
            if can_manual:
                manual_form = f"""<details class="collection-manual-import"><summary>Manual Paste / Manual Upload</summary>
                  <form class="stack-form compact-form" method="post" action="/schools/{school['id']}/collection/manual-import">
                    <input type="hidden" name="csrf" value="{esc(self.csrf)}">
                    <input type="hidden" name="source_key" value="{esc(card['key'])}">
                    <input type="hidden" name="source_name" value="{esc(card['source_name'])}">
                    <input type="hidden" name="source_type" value="{esc(card['source_type'])}">
                    <label>Field / 内容类型<input name="field_name" value="{esc(card['key'])}_summary"></label>
                    <label>Manual text<textarea name="manual_text" placeholder="粘贴来自该来源的文字，系统保存为 Needs Review 草稿，不自动写入正式学校库。"></textarea></label>
                    <label>Confidence Rate<input name="confidence_score" value="100" inputmode="decimal"></label>
                    <button class="primary compact">保存为待审核草稿</button>
                  </form>
                </details>"""
            cards.append(f"""<article class="collection-source-card">
              <div class="collection-source-head">
                <div><h3>{esc(card['name'])}</h3><p>{esc(card['description'])}</p></div>
                <span class="status {status_class}">{esc(SCHOOL_COLLECTION_STATUS_LABELS.get(status, status))}</span>
              </div>
              <div class="collection-source-meta">
                <span>URL</span><strong>{esc(source_url or '未配置')}</strong>
                <span>Last fetched/imported</span><strong>{esc((last_time or '暂无')[:19])}</strong>
                <span>Review status</span><strong>{esc(SCHOOL_COLLECTION_STATUS_LABELS.get(review_status, review_status))}</strong>
                <span>Error</span><strong>{esc(error or '无')}</strong>
              </div>
              <div class="row-actions compact-actions">{fetch_action}<a class="secondary button-link compact" href="/schools/drafts">View Extracted Data</a></div>
              {source_form}
              {manual_form}
            </article>""")
        return f"""<section class="panel school-collection-panel" id="collection-center">
          <div class="panel-head"><div><h2>信息采集中心</h2><p>所有来源数据先保存为 Suggested / Needs Review，人工确认后才能用于家长报告；不会随机抓取未知网站。</p></div><a class="secondary button-link" href="/schools/collection">打开全局采集中心</a></div>
          <div class="collection-source-grid">{''.join(cards)}</div>
        </section>"""

    def school_collection_source_save(self, method, school_id):
        if method != "POST":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        if not can_school_action(self.user, "manage_source_urls"):
            db.audit(self.user, "school_collection_access_denied", "school_library", record_id=school_id, ip=self.client_address[0], device=self.headers.get("User-Agent"), status="denied", error_message="missing manage_source_urls")
            return self.school_action_denied("manage_source_urls")
        school = db.one("SELECT * FROM schools WHERE id=?", (school_id,))
        if not school:
            return self.error_page("学校不存在", HTTPStatus.NOT_FOUND)
        source_key = str(self.form.get("source_key", "")).strip()
        card = next((item for item in SCHOOL_COLLECTION_SOURCE_CARDS if item["key"] == source_key), None)
        if not card:
            return self.flash_redirect(f"/schools/{school_id}#collection-center", "来源类型无效。", "error")
        source_url = str(self.form.get("source_url", "")).strip()
        source_status = str(self.form.get("source_status", "URL Added")).strip() or "URL Added"
        notes = str(self.form.get("notes", "")).strip()
        existing = self.school_collection_latest_source(school_id, card["source_name"])
        if existing:
            db.execute(
                "UPDATE school_data_sources SET source_type=?,source_url=?,source_status=?,notes=?,updated_at=? WHERE id=?",
                (card["source_type"], source_url, source_status, notes, now_iso(), existing["id"]),
            )
            record_id = existing["id"]
            action = "school_source_url_added"
        else:
            record_id = db.execute(
                """INSERT INTO school_data_sources(school_id,source_name,source_type,source_url,source_status,notes,added_by,added_at,updated_at)
                   VALUES(?,?,?,?,?,?,?,?,?)""",
                (school_id, card["source_name"], card["source_type"], source_url, source_status, notes, self.user["id"], now_iso(), now_iso()),
            )
            action = "school_source_url_added"
        if card["key"] == "official_website" and source_url:
            db.execute("UPDATE schools SET website_url=?,updated_at=?,updated_by=? WHERE id=?", (source_url, now_iso(), self.user["id"], school_id))
        self.school_record_source(school_id, "collection_center", card["source_name"], source_url, "", None, f"{source_status}; {notes}".strip())
        db.audit(self.user, action, "school_library", record_id=record_id, new_value=json.dumps({"school_id": school_id, "source": card["source_name"], "url": source_url, "status": source_status}, ensure_ascii=False), ip=self.client_address[0], device=self.headers.get("User-Agent"))
        return self.flash_redirect(f"/schools/{school_id}#collection-center", "来源已保存。")

    def soft_delete_school_record(self, school_id):
        school = db.one("SELECT id,deleted_at FROM schools WHERE id=?", (school_id,))
        if not school or school["deleted_at"]:
            return False
        stamp = now_iso()
        db.execute(
            "UPDATE schools SET deleted_at=?,deleted_by=?,updated_at=?,updated_by=? WHERE id=?",
            (stamp, self.user["id"], stamp, self.user["id"], school_id),
        )
        db.audit(
            self.user, "school_deleted", "school_library", record_id=school_id,
            new_value=json.dumps({"deleted_at": stamp}, ensure_ascii=False),
            ip=self.client_address[0], device=self.headers.get("User-Agent"),
        )
        return True

    def bulk_soft_delete_school_records(self, school_ids):
        changed = []
        seen = set()
        for value in school_ids or []:
            school_id = str(value or "").strip()
            if not school_id.isdigit() or school_id in seen:
                continue
            seen.add(school_id)
            if self.soft_delete_school_record(school_id):
                changed.append(school_id)
        if changed:
            db.audit(
                self.user, "schools_bulk_deleted", "school_library", record_id="bulk-delete",
                new_value=json.dumps({"count": len(changed), "school_ids": changed}, ensure_ascii=False),
                ip=self.client_address[0], device=self.headers.get("User-Agent"),
            )
        return changed

    def restore_school_record(self, school_id):
        school = db.one("SELECT id,deleted_at FROM schools WHERE id=?", (school_id,))
        if not school or not school["deleted_at"]:
            return False
        stamp = now_iso()
        db.execute(
            "UPDATE schools SET deleted_at=NULL,deleted_by=NULL,updated_at=?,updated_by=? WHERE id=?",
            (stamp, self.user["id"], school_id),
        )
        db.audit(
            self.user, "school_restored", "school_library", record_id=school_id,
            new_value=json.dumps({"restored_at": stamp}, ensure_ascii=False),
            ip=self.client_address[0], device=self.headers.get("User-Agent"),
        )
        return True

    def school_delete_restore(self, method, school_id, action):
        if method != "POST":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        if not can_delete_school_record(self.user):
            return self.school_action_denied(action)
        if action == "delete":
            ok = self.soft_delete_school_record(school_id)
            return self.flash_redirect("/schools/library", "学校已删除，可在已删除学校中恢复。" if ok else "学校不存在或已经删除。", "ok" if ok else "error")
        ok = self.restore_school_record(school_id)
        return self.flash_redirect("/schools/deleted", "学校已恢复。" if ok else "学校不存在或未处于删除状态。", "ok" if ok else "error")

    def schools_bulk_delete(self, method):
        if method != "POST":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        if not can_delete_school_record(self.user):
            return self.school_action_denied("delete")
        school_ids = split_multi(self.form, "school_ids")
        if not school_ids:
            return self.flash_redirect("/schools/library", "请选择要删除的学校。", "error")
        changed = self.bulk_soft_delete_school_records(school_ids)
        if not changed:
            return self.flash_redirect("/schools/library", "没有可删除的学校；可能已被删除或记录不存在。", "error")
        return self.flash_redirect("/schools/library", f"已批量删除 {len(changed)} 所学校，可在已删除学校中恢复。")

    def deleted_schools(self, method):
        if method != "GET":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        if not can_delete_school_record(self.user):
            return self.school_action_denied("restore")
        rows = db.all(
            """SELECT s.*,deleter.display_name deleted_by_name
               FROM schools s
               LEFT JOIN users deleter ON deleter.id=s.deleted_by
               WHERE s.deleted_at IS NOT NULL
               ORDER BY s.deleted_at DESC"""
        )
        table_rows = "".join(
            f"""<tr>
              <td>{esc(row['school_name'])}</td>
              <td>{esc(row['state'] or '')}</td>
              <td>{esc(row['suburb'] or '')}</td>
              <td>{esc(display_datetime(row['deleted_at']))}</td>
              <td>{esc(row['deleted_by_name'] or '')}</td>
              <td><form class="inline-form school-deleted-records-restore-form" method="post" action="/schools/{row['id']}/restore" onsubmit="return confirm('确认恢复这个学校？');"><input type="hidden" name="csrf" value="{esc(self.csrf)}"><button class="secondary compact">恢复</button></form></td>
            </tr>"""
            for row in rows
        ) or '<tr><td colspan="6" class="empty">没有已删除学校</td></tr>'
        body = f"""
        <div class="school-deleted-records-page">
        <section class="panel school-deleted-records-panel">
          <div class="panel-head"><div><h2>已删除学校</h2><p>这里显示软删除的学校记录。恢复后会重新回到学校资料库。</p></div><a class="secondary button-link" href="/schools/library">返回学校资料库</a></div>
          <div class="table-wrap school-deleted-records-table-wrap"><table><thead><tr><th>学校</th><th>State</th><th>Suburb</th><th>删除时间</th><th>删除人</th><th>操作</th></tr></thead><tbody>{table_rows}</tbody></table></div>
        </section>
        </div>"""
        message, kind = self.message()
        self.send_html(page("已删除学校", body, self.user, self.csrf, "schools", nas.status(), message, kind))

    def school_collection_manual_import(self, method, school_id):
        if method != "POST":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        if not (can_school_action(self.user, "review_collected_data") or can_school_action(self.user, "manage_source_urls")):
            db.audit(self.user, "school_collection_access_denied", "school_library", record_id=school_id, ip=self.client_address[0], device=self.headers.get("User-Agent"), status="denied", error_message="missing review_collected_data")
            return self.school_action_denied("review_collected_data")
        school = db.one("SELECT * FROM schools WHERE id=?", (school_id,))
        if not school:
            return self.error_page("学校不存在", HTTPStatus.NOT_FOUND)
        source_key = str(self.form.get("source_key", "")).strip()
        card = next((item for item in SCHOOL_COLLECTION_SOURCE_CARDS if item["key"] == source_key), None)
        if not card:
            return self.flash_redirect(f"/schools/{school_id}#collection-center", "来源类型无效。", "error")
        manual_text = str(self.form.get("manual_text", "")).strip()
        field_name = str(self.form.get("field_name", f"{source_key}_summary")).strip() or f"{source_key}_summary"
        if not manual_text:
            return self.flash_redirect(f"/schools/{school_id}#collection-center", "请先粘贴需要保存的内容。", "error")
        source = self.school_collection_latest_source(school_id, card["source_name"])
        source_url = source["source_url"] if source else ""
        try:
            confidence = float(str(self.form.get("confidence_score", "100")).strip() or "100")
        except ValueError:
            confidence = 100.0
        db.audit(self.user, "school_source_manual_import_started", "school_library", record_id=school_id, file_path=source_url, ip=self.client_address[0], device=self.headers.get("User-Agent"))
        job_id = db.execute(
            """INSERT INTO school_collection_jobs(school_id,selected_fields_json,source_ids_json,status,request_notes,created_by,created_at,updated_at)
               VALUES(?,?,?,?,?,?,?,?)""",
            (school_id, json.dumps([field_name], ensure_ascii=False), json.dumps([source["id"]] if source else []), "Needs Review", f"Manual paste from {card['source_name']}", self.user["id"], now_iso(), now_iso()),
        )
        draft_id = db.execute(
            """INSERT INTO school_collection_drafts(job_id,school_id,field_name,extracted_value,editable_value,source_url,collected_at,confidence_score,review_status,notes,created_at,updated_at)
               VALUES(?,?,?,?,?,?,?,?,?,?,?,?)""",
            (job_id, school_id, field_name, manual_text, manual_text, source_url, now_iso(), confidence, "Needs Review", f"Manual import from {card['source_name']}; source_type={card['source_type']}", now_iso(), now_iso()),
        )
        self.school_record_source(school_id, "collection_manual_import", field_name, source_url, "", confidence, f"{card['source_name']}; Needs Review")
        db.audit(self.user, "school_source_manual_import_completed", "school_library", record_id=draft_id, file_path=source_url, new_value=json.dumps({"field_name": field_name, "source": card["source_name"], "confidence": confidence}, ensure_ascii=False), ip=self.client_address[0], device=self.headers.get("User-Agent"))
        return self.flash_redirect("/schools/drafts", "人工导入内容已保存为 Needs Review 草稿。")

    def school_collection_store_source_file(self, upload, source_group="uploads"):
        folder = APP_DIR / "school_data_sources" / "collection_uploads" / source_group / date.today().strftime("%Y%m%d")
        folder.mkdir(parents=True, exist_ok=True)
        target, _ = next_version_path(folder, Path(upload.filename or "source_file").name)
        target.write_bytes(upload.data)
        return target

    def school_collection_clean_html(self, raw):
        text = raw.decode("utf-8", errors="ignore") if isinstance(raw, (bytes, bytearray)) else str(raw or "")
        text = re.sub(r"(?is)<(script|style|noscript).*?>.*?</\\1>", " ", text)
        text = re.sub(r"(?s)<[^>]+>", " ", text)
        return re.sub(r"\s+", " ", html.unescape(text)).strip()

    def school_collection_excerpt_for_field(self, field, text):
        text = re.sub(r"\s+", " ", str(text or "")).strip()
        if not text:
            return ""
        keyword_map = {
            "ranking_information": ["rank", "ranking", "better education", "vce", "hsc", "median", "score", "高考", "排名"],
            "international_fee_information": ["tuition", "fee", "application fee", "international student", "AUD", "$", "学费", "申请费", "费用"],
            "entry_requirements": ["AEAS", "IDAT", "IELTS", "interview", "entry requirement", "admission", "面试", "考试"],
            "accepted_international_year_levels": ["year 7", "year 8", "year 9", "year 10", "year 11", "international", "年级"],
            "language_program": ["language", "EAL", "ELICOS", "English", "语言"],
            "features": ["program", "sport", "music", "robotics", "boarding", "outdoor", "特色"],
            "zone_data": ["population", "income", "language background", "education", "suburb", "ABS", "人口", "收入"],
            "academic_information": ["ICSEA", "NAPLAN", "enrolment", "teaching staff", "academic", "学术"],
            "basic_information": ["address", "website", "school type", "co-ed", "public", "private", "地址"],
        }
        snippets = []
        lowered = text.lower()
        for keyword in keyword_map.get(field, []):
            pos = lowered.find(keyword.lower())
            if pos >= 0:
                start = max(0, pos - 180)
                end = min(len(text), pos + 620)
                snippet = text[start:end].strip()
                if snippet and snippet not in snippets:
                    snippets.append(snippet)
            if len(snippets) >= 3:
                break
        if not snippets:
            snippets = [text[:1200]]
        return "\n\n---\n\n".join(snippets)[:5000]

    def school_collection_create_drafts_from_text(self, school_id, selected_fields, source_name, source_url, text, *, request_notes="", source_file_path="", confidence=70.0):
        selected_fields = selected_fields or ["basic_information"]
        notes = request_notes.strip()
        if source_file_path:
            notes = f"{notes}\nSource file: {source_file_path}".strip()
        job_id = db.execute(
            """INSERT INTO school_collection_jobs(school_id,selected_fields_json,source_ids_json,status,request_notes,created_by,created_at,updated_at)
               VALUES(?,?,?,?,?,?,?,?)""",
            (school_id, json.dumps(selected_fields, ensure_ascii=False), json.dumps([]), "Needs Review", notes, self.user["id"], now_iso(), now_iso()),
        )
        created = 0
        for field in selected_fields:
            value = self.school_collection_excerpt_for_field(field, text)
            field_notes = notes or f"Extracted from {source_name}; staff must compare source text/file before approval."
            if not value:
                value = ""
                field_notes = f"{field_notes}\n未自动识别到可用文字，请人工核对原文件或网页。".strip()
            db.execute(
                """INSERT INTO school_collection_drafts(job_id,school_id,field_name,extracted_value,editable_value,source_url,collected_at,confidence_score,review_status,notes,created_at,updated_at)
                   VALUES(?,?,?,?,?,?,?,?,?,?,?,?)""",
                (job_id, school_id, field, value, value, source_url, now_iso(), confidence if value else 20.0, "Needs Review", field_notes, now_iso(), now_iso()),
            )
            created += 1
        return job_id, created

    def school_collection_url_fetch(self, method):
        if method != "POST":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        if not can_school_action(self.user, "manage_source_urls"):
            return self.school_action_denied("manage_source_urls")
        school_id = str(self.form.get("school_id", "")).strip()
        school = db.one("SELECT * FROM schools WHERE id=?", (school_id,))
        if not school:
            return self.flash_redirect("/schools/collection", "请选择有效学校。", "error")
        source_url = str(self.form.get("source_url", "")).strip()
        parsed = urlparse(source_url)
        if parsed.scheme not in {"http", "https"}:
            return self.flash_redirect("/schools/collection", "请输入有效 URL。", "error")
        selected_fields = split_multi(self.form, "selected_fields") or ["basic_information"]
        source_name = str(self.form.get("source_name", "URL Source")).strip() or "URL Source"
        notes = str(self.form.get("request_notes", "")).strip()
        try:
            request = urllib.request.Request(source_url, headers={"User-Agent": "AAIE-CRM-SchoolCollection/1.0", "Accept": "text/html,text/plain,application/pdf,*/*"})
            with urllib.request.urlopen(request, timeout=18) as response:
                raw = response.read(3_000_000)
                content_type = response.headers.get("Content-Type", "")
            cache_upload = Upload("source_file", Path(parsed.path).name or "source.html", content_type or "text/html", raw)
            cache_path = self.school_collection_store_source_file(cache_upload, "url")
            if "pdf" in content_type.lower() or source_url.lower().endswith(".pdf"):
                text = extract_uploaded_text(Upload("source_file", cache_path.name, "application/pdf", raw))
            else:
                text = self.school_collection_clean_html(raw)
            job_id, created = self.school_collection_create_drafts_from_text(school_id, selected_fields, source_name, source_url, text, request_notes=f"{notes}\n自动 URL 采集；请对比原网页/缓存文件后确认。", source_file_path=str(cache_path), confidence=65.0)
            self.school_record_source(school_id, "collection_url_fetch", source_name, source_url, str(cache_path), 65.0, "Needs Review")
            db.audit(self.user, "school_collection_url_fetched", "school_library", record_id=job_id, file_path=source_url, new_value=json.dumps({"drafts": created, "source_file": str(cache_path)}, ensure_ascii=False), ip=self.client_address[0], device=self.headers.get("User-Agent"))
            return self.flash_redirect("/schools/drafts", f"URL 已采集，生成 {created} 条待确认资料。")
        except Exception as exc:
            db.audit(self.user, "school_collection_url_fetch_failed", "school_library", record_id=school_id, file_path=source_url, status="failed", error_message=str(exc), ip=self.client_address[0], device=self.headers.get("User-Agent"))
            return self.flash_redirect("/schools/collection", f"URL 采集失败：{exc}", "error")

    def school_collection_file_upload(self, method):
        if method != "POST":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        if not (can_school_action(self.user, "upload_documents") or can_school_action(self.user, "manage_source_urls")):
            return self.school_action_denied("upload_documents")
        school_id = str(self.form.get("school_id", "")).strip()
        school = db.one("SELECT * FROM schools WHERE id=?", (school_id,))
        if not school:
            return self.flash_redirect("/schools/collection", "请选择有效学校。", "error")
        selected_fields = split_multi(self.form, "selected_fields") or ["ranking_information"]
        source_name = str(self.form.get("source_name", "Uploaded Document")).strip() or "Uploaded Document"
        notes = str(self.form.get("request_notes", "")).strip()
        uploads = [file for file in self.files if file.filename and file.field_name in {"source_files", "source_file"}]
        if not uploads:
            return self.flash_redirect("/schools/collection", "请选择 PDF、Excel、CSV、Word 或网页截图。", "error")
        total = 0
        for upload in uploads:
            stored_path = self.school_collection_store_source_file(upload, "files")
            text = extract_uploaded_text(upload)
            if not text and Path(upload.filename).suffix.lower() in {".html", ".htm"}:
                text = self.school_collection_clean_html(upload.data)
            job_id, created = self.school_collection_create_drafts_from_text(school_id, selected_fields, source_name, "", text, request_notes=f"{notes}\n上传文件采集；请对比原文件/截图后确认。Original filename: {upload.filename}", source_file_path=str(stored_path), confidence=75.0 if text else 20.0)
            self.school_record_source(school_id, "collection_file_upload", source_name, "", str(stored_path), 75.0 if text else 20.0, "Needs Review")
            db.audit(self.user, "school_collection_file_uploaded_for_extraction", "school_library", record_id=job_id, file_path=str(stored_path), new_value=json.dumps({"drafts": created, "filename": upload.filename}, ensure_ascii=False), ip=self.client_address[0], device=self.headers.get("User-Agent"))
            total += created
        return self.flash_redirect("/schools/drafts", f"文件已上传并生成 {total} 条待确认资料。")

    def school_collection_abs_fetch(self, method):
        if method != "POST":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        if not (can_school_action(self.user, "fetch_abs_data") or can_school_action(self.user, "manage_source_urls")):
            return self.school_action_denied("fetch_abs_data")
        if is_school_collection_url_payload(self.form):
            school_id = str(self.form.get("school_id", "")).strip()
            source_url = str(self.form.get("source_url", "")).strip()
            db.audit(
                self.user,
                "school_collection_abs_route_mismatch_corrected",
                "school_library",
                record_id=school_id,
                file_path=source_url,
                status="redirected",
                error_message="URL collection payload reached ABS endpoint; routed to URL fetch.",
                ip=self.client_address[0],
                device=self.headers.get("User-Agent"),
            )
            return self.school_collection_url_fetch(method)
        school_id = str(self.form.get("school_id", "")).strip()
        school = db.one("SELECT * FROM schools WHERE id=?", (school_id,))
        if not school:
            return self.flash_redirect("/schools/collection", "请选择有效学校。", "error")
        dataflow = str(self.form.get("abs_dataflow", "C21_G02_SAL")).strip() or "C21_G02_SAL"
        region_code = re.sub(r"[^0-9]", "", str(self.form.get("abs_region_code", "")).strip())
        state_code = re.sub(r"[^0-9]", "", str(self.form.get("abs_state_code", "2")).strip()) or "2"
        year = re.sub(r"[^0-9]", "", str(self.form.get("abs_year", "") or self.form.get("data_year", "2021")).strip()) or "2021"
        selected_fields = split_multi(self.form, "selected_fields") or ["zone_data"]
        auto_resolved = None
        if not region_code:
            auto_resolved = resolve_abs_sal_code(school["suburb"], school["state"], school["postcode"])
            if auto_resolved:
                region_code = auto_resolved["code"]
                state_code = auto_resolved["state_code"]
                db.audit(
                    self.user,
                    "school_collection_abs_sal_code_auto_resolved",
                    "school_library",
                    record_id=school_id,
                    new_value=json.dumps(auto_resolved, ensure_ascii=False),
                    ip=self.client_address[0],
                    device=self.headers.get("User-Agent"),
                )
        code_issue = abs_region_code_issue(region_code, year, "SAL")
        if code_issue:
            text = f"ABS API 未调用：{code_issue} School suburb={school['suburb'] or ''}, state={school['state'] or ''}, postcode={school['postcode'] or ''}. 请先确认 ABS SAL/SA2 geography code 后再下载官方数据。"
            job_id, created = self.school_collection_create_drafts_from_text(school_id, selected_fields, "ABS Data API", "https://data.api.abs.gov.au/rest/", text, request_notes="ABS geography code missing; Needs Review", confidence=30.0)
            db.audit(self.user, "school_collection_abs_code_required", "school_library", record_id=job_id, new_value=text, ip=self.client_address[0], device=self.headers.get("User-Agent"), error_message=code_issue)
            return self.flash_redirect("/schools/drafts", f"已生成 ABS 待确认任务：{code_issue}", "warning")
        if dataflow != "C21_G02_SAL":
            return self.flash_redirect("/schools/collection", "MVP 当前先支持 C21_G02_SAL。其他 ABS dataflow 后续按字段映射扩展。", "error")
        api_url = f"https://data.api.abs.gov.au/rest/data/{dataflow}/.{region_code}.SAL.{state_code}?startPeriod={year}&format=csv"
        try:
            request = urllib.request.Request(api_url, headers={"User-Agent": "AAIE-CRM-ABS-MVP/1.0", "Accept": "text/csv"})
            with urllib.request.urlopen(request, timeout=25) as response:
                raw = response.read(1_000_000)
            text = raw.decode("utf-8", errors="replace")
            rows = list(csv.DictReader(io.StringIO(text)))
            summary = "\n".join(
                f"ABS {dataflow} MEDAVG {row.get('MEDAVG')} | REGION {row.get('REGION')} | STATE {row.get('STATE')} | {row.get('TIME_PERIOD')} = {row.get('OBS_VALUE')}"
                for row in rows[:80]
            )
            if not summary:
                summary = text[:3000]
            auto_note = f" Auto-resolved SAL from {auto_resolved['suburb']} {auto_resolved['postcode']} via {auto_resolved['source']}." if auto_resolved else ""
            job_id, created = self.school_collection_create_drafts_from_text(school_id, selected_fields, "ABS Data API", api_url, summary, request_notes=f"ABS official API result; region_code={region_code}; state_code={state_code}; year={year}.{auto_note} Staff must map ABS MEDAVG codes before approval.", confidence=85.0)
            self.school_record_source(school_id, "collection_abs_api", "ABS Data API", api_url, "", 85.0, "Needs Review")
            db.audit(self.user, "school_collection_abs_api_fetched", "school_library", record_id=job_id, file_path=api_url, new_value=json.dumps({"rows": len(rows), "drafts": created, "region_code": region_code}, ensure_ascii=False), ip=self.client_address[0], device=self.headers.get("User-Agent"))
            return self.flash_redirect("/schools/drafts", f"ABS 官方数据已下载，生成 {created} 条待确认资料。")
        except urllib.error.HTTPError as exc:
            if exc.code == 404:
                message = f"ABS API 返回 404：未找到这个 dataflow / SAL code / state code 组合。请核对 SAL Code={region_code}、State Code={state_code}、Year={year}。请求地址：{api_url}"
            else:
                message = f"ABS API HTTP {exc.code}: {exc.reason}。请求地址：{api_url}"
            db.audit(self.user, "school_collection_abs_api_failed", "school_library", record_id=school_id, file_path=api_url, status="failed", error_message=message, ip=self.client_address[0], device=self.headers.get("User-Agent"))
            return self.flash_redirect("/schools/collection", message, "error")
        except Exception as exc:
            db.audit(self.user, "school_collection_abs_api_failed", "school_library", record_id=school_id, file_path=api_url, status="failed", error_message=str(exc), ip=self.client_address[0], device=self.headers.get("User-Agent"))
            return self.flash_redirect("/schools/collection", f"ABS API 采集失败：{exc}", "error")

    def school_collection_feature_workspace(self):
        if not can_school_action(self.user, "view_collection_center"):
            return ""
        feature_school = self.school_collection_selected_school()
        if not feature_school:
            return """<section class="panel school-feature-workspace-shell" id="features"><div class="panel-head"><div><h2>School Feature Tag System / 学校特色标签</h2><p>请先建立学校，再上传文件扫描特色标签。</p></div></div><div class="empty">暂无学校。</div></section>"""
        school_selector = f"""
          <form class="inline-form school-feature-selector-form" method="get" action="/schools/collection#features">
            <label>选择学校<select name="feature_school_id" required>{self.school_select_options(feature_school["id"])}</select></label>
            <button class="primary compact">打开学校特色标签</button>
            <a class="secondary button-link compact" href="/schools/{feature_school['id']}">查看学校资料</a>
          </form>
        """
        pending_feature_rows = self.school_feature_assignment_grouped(feature_school["id"], "Suggested")
        pending_feature_tags = [
            school_feature_tag_display_zh(row["tag_name_cn"] or row["tag_name_en"] or "")
            for row in pending_feature_rows
        ]
        pending_feature_tags = [tag for tag in pending_feature_tags if tag]
        pending_feature_summary = ""
        if pending_feature_tags:
            pending_chips = "".join(f"<span>{esc(tag)}</span>" for tag in pending_feature_tags[:20])
            pending_confirm_form = ""
            if can_school_action(self.user, "confirm_feature_tags") or can_school_action(self.user, "review_feature_suggestions"):
                pending_confirm_form = f"""<form class="inline-form" method="post" action="/schools/{feature_school['id']}/feature-tags/confirm-all" onsubmit="return confirm('确认把 {esc(feature_school['school_name'])} 当前所有待确认特色标签一次性入库？');">
                  <input type="hidden" name="csrf" value="{esc(self.csrf)}">
                  <button class="primary compact">全部确认入库</button>
                </form>"""
            pending_feature_summary = f"""<div class="school-feature-pending-summary">
              <div><strong>{esc(feature_school['school_name'])} 待确认标签 {len(pending_feature_rows)} 个</strong><p class="muted-line">这些标签已经抓到，但还没有进入正式学校资料库；确认后才会显示在学校卡片和学校详情顶部。</p><div class="school-feature-tags">{pending_chips}</div></div>
              {pending_confirm_form}
            </div>"""
        return f"""<section class="panel school-feature-workspace-shell" id="features">
          <div class="school-feature-workspace-bg">
            <div class="panel-head"><div><h2>School Feature Tag System / 学校特色标签</h2><p><strong>School Features / 学校特色</strong>：一级分类 + 二级标签；自动建议必须人工确认后才进入正式学校资料库。</p></div></div>
            {school_selector}
            {pending_feature_summary}
            {self.school_features_panel(feature_school, embedded=True)}
          </div>
        </section>"""

    def school_collection_selected_school(self):
        requested_id = (self.query.get("school_id") or self.query.get("feature_school_id") or [""])[0]
        if requested_id:
            school = db.one("SELECT * FROM schools WHERE id=?", (requested_id,))
            if school:
                return school
        return db.one("SELECT * FROM schools ORDER BY school_name LIMIT 1")

    def school_collection_data_review_panel(self):
        if not can_school_action(self.user, "view_collection_center"):
            return ""
        school = self.school_collection_selected_school()
        if not school:
            return """<section class="panel" id="data-review"><div class="panel-head"><div><h2>数据来源与复核</h2><p>请先建立学校，再查看来源、复核和第三方比对记录。</p></div></div><div class="empty">暂无学校。</div></section>"""
        school_selector = f"""
          <form class="inline-form school-feature-selector-form" method="get" action="/schools/collection#data-review">
            <label>选择学校<select name="school_id" required>{self.school_select_options(school["id"])}</select></label>
            <button class="primary compact">查看数据复核</button>
            <a class="secondary button-link compact" href="/schools/{school['id']}">查看学校资料</a>
          </form>
        """
        return f"""<section class="school-data-review-workspace school-collection-data-review" id="data-review">
          <div class="panel">
            <div class="panel-head"><div><h2>数据来源与复核</h2><p>来源记录、复核状态和第三方交叉比对集中在这里维护，不显示在学校资料页。</p></div></div>
            {school_selector}
          </div>
          {self.school_area_source_review_panel(school)}
          {self.school_area_third_party_cross_check_panel(school)}
        </section>"""

    def school_collection_center(self, method):
        if method != "GET":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        if not can_school_action(self.user, "view_collection_center"):
            db.audit(self.user, "school_collection_access_denied", "school_library", record_id="collection", ip=self.client_address[0], device=self.headers.get("User-Agent"), status="denied", error_message="missing view_collection_center")
            return self.school_action_denied("view_collection_center")
        state_fee_manage_action = (
            '<a class="primary button-link" href="/schools/collection/state-fee-schedules">管理费用表</a>'
            if allowed(self.user, "*")
            else '<span class="button-link disabled">仅 Admin 可管理费用表</span>'
        )
        data_review_workspace = self.school_collection_data_review_panel()
        feature_workspace = self.school_collection_feature_workspace()
        body = f"""
        <div class="school-collection-page">
        <a class="back-link" href="/schools">← 返回学校管理</a>
        <section class="dashboard-hero panel school-collection-header">
          <div><span class="eyebrow">Collection Framework</span><h2>信息采集中心</h2><p>给 URL、上传文件/截图、或调用 ABS 官方 API。所有结果先进入待确认资料，人工确认后才进入正式学校资料。</p></div>
          <span class="status warn">No random scraping</span>
        </section>
        <section class="school-collection-action-grid school-collection-actions">
          <article class="panel school-collection-action-card">
            <div class="panel-head"><div><h2>03 ABS 官方数据 API</h2><p>用于学区/社区数据。MVP 先支持 ABS 2021 Census SAL 数据；需要确认 SAL code 后再下载。</p></div></div>
            <form class="stack-form" method="post" action="/schools/collection/abs-fetch" data-school-collection-form="abs">
              <input type="hidden" name="csrf" value="{esc(self.csrf)}">
              <div class="form-grid two-col">
                <label>学校<select name="school_id" required>{self.school_select_options()}</select></label>
                <label>ABS Dataflow<select name="abs_dataflow"><option value="C21_G02_SAL">C21_G02_SAL - Selected medians and averages</option></select></label>
                <label>ABS SAL Code<input name="abs_region_code" placeholder="例如 20727；不要填写年份"><small>这是 ABS geography code，不是 2021 这种年份；不确定可留空生成待确认任务。</small></label>
                <label>State Code<input name="abs_state_code" value="2"><small>ABS Census 中 VIC 通常为 2；最终以 ABS 返回为准。</small></label>
                <label>Year<input name="abs_year" value="2021"></label>
                <div class="wide"><strong>采集字段</strong><div class="choice-grid">{self.school_collection_field_checkboxes(['zone_data'])}</div></div>
                <label class="wide">备注<textarea name="request_notes" placeholder="例如：先确认学校地址对应的 SAL/SA2，再下载 ABS 官方数据。"></textarea></label>
              </div>
              <button class="secondary" type="submit" data-school-collection-submit="abs">调用 ABS API / 生成待确认资料</button>
            </form>
          </article>
          <article class="panel school-collection-action-card">
            <div class="panel-head"><div><h2>04 州统一费用表</h2><p>管理 International Student Fees - VIC / NSW / SA / ACT / QLD / TAS / WA Government Schools；公校通过 State + Sector 自动引用 active 版本。</p></div></div>
            <div class="collection-fee-schedule-summary">
              <div><span>当前 MVP</span><strong>VIC + NSW + SA + ACT + QLD + TAS + WA Government School Fees 2026</strong></div>
              <div><span>调用方式</span><strong>School Profile / Student Plan / Quote 共用</strong></div>
              <p>这里管理的是学校信息来源和费用版本，不把费用复制到每所学校。以后更新年度费用表，只需要在这里更新一次。</p>
            </div>
            {state_fee_manage_action}
          </article>
        </section>
        {data_review_workspace}
        {feature_workspace}
        </div>
        """
        db.audit(self.user, "school_collection_center_opened", "school_library", record_id="collection", ip=self.client_address[0], device=self.headers.get("User-Agent"))
        message, kind = self.message()
        self.send_html(page("信息采集中心", body, self.user, self.csrf, "schools", nas.status(), message, kind))

    def school_collection_create(self, method):
        if method != "POST":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        if not self.require_school_action("manage_source_urls"):
            return
        school_id = str(self.form.get("school_id", "")).strip()
        school = db.one("SELECT * FROM schools WHERE id=?", (school_id,))
        if not school:
            return self.flash_redirect("/schools/collection", "请选择有效学校。", "error")
        selected_fields = split_multi(self.form, "selected_fields") or ["basic_information"]
        source_ids = []
        source_url = str(self.form.get("source_url", "")).strip()
        source_type = str(self.form.get("source_type", "Official Website")).strip() or "Official Website"
        source_notes = str(self.form.get("source_notes", "")).strip()
        if source_url:
            source_id = db.execute(
                "INSERT INTO school_trusted_sources(school_id,source_url,source_type,source_notes,added_by,added_at,is_active) VALUES(?,?,?,?,?,?,1)",
                (school_id, source_url, source_type, source_notes, self.user["id"], now_iso()),
            )
            source_ids.append(source_id)
            db.audit(self.user, "school_trusted_source_added", "school_library", record_id=source_id, new_value=source_url, ip=self.client_address[0], device=self.headers.get("User-Agent"))
            db.audit(self.user, "school_source_url_added", "school_library", record_id=source_id, new_value=source_url, ip=self.client_address[0], device=self.headers.get("User-Agent"))
        job_id = db.execute(
            """INSERT INTO school_collection_jobs(school_id,selected_fields_json,source_ids_json,status,request_notes,created_by,created_at,updated_at)
               VALUES(?,?,?,?,?,?,?,?)""",
            (school_id, json.dumps(selected_fields, ensure_ascii=False), json.dumps(source_ids), "Draft", str(self.form.get("request_notes", "")).strip(), self.user["id"], now_iso(), now_iso()),
        )
        for field in selected_fields:
            db.execute(
                """INSERT INTO school_collection_drafts(job_id,school_id,field_name,extracted_value,editable_value,source_url,collected_at,confidence_score,review_status,notes,created_at,updated_at)
                   VALUES(?,?,?,?,?,?,?,?,?,?,?,?)""",
                (job_id, school_id, field, "", "", source_url, "", None, "Pending", "等待采集/人工补充；未写入正式学校库", now_iso(), now_iso()),
            )
        db.audit(self.user, "school_collection_job_created", "school_library", record_id=job_id, new_value=json.dumps({"school_id": school_id, "fields": selected_fields}, ensure_ascii=False), ip=self.client_address[0], device=self.headers.get("User-Agent"))
        return self.flash_redirect("/schools/drafts", "采集任务已创建，待确认草稿已生成。")

    def school_draft_review(self, method):
        if method != "GET":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        if not can_school_action(self.user, "view_collection_center"):
            return self.school_action_denied("view")
        rows = db.all(
            """SELECT d.*,s.school_name,j.status job_status,u.display_name created_name
               FROM school_collection_drafts d
               LEFT JOIN schools s ON s.id=d.school_id
               LEFT JOIN school_collection_jobs j ON j.id=d.job_id
               LEFT JOIN users u ON u.id=j.created_by
               ORDER BY d.created_at DESC LIMIT 100"""
        )
        body_rows = "".join(
            f"""<tr><td>{esc(row['school_name'] or '')}<small>Job #{esc(row['job_id'])} · {esc(row['job_status'] or '')}</small></td><td>{esc(row['field_name'])}</td><td class="wrap-cell">{esc(row['editable_value'] or row['extracted_value'] or '待采集/待填写')}</td><td class="wrap-cell">{esc(row['source_url'] or '无')}<small>{esc(row['notes'] or '')}</small></td><td><span class="status {'ok' if row['review_status']=='Approved' else 'warn'}">{esc(row['review_status'])}</span><small>{esc(row['created_at'][:19])}</small></td><td>{self.school_collection_draft_actions(row)}</td></tr>"""
            for row in rows
        ) or '<tr><td colspan="6" class="empty">暂无待确认学校资料</td></tr>'
        body = f"""
        <div class="school-drafts-page">
        <a class="back-link" href="/schools">← 返回学校管理</a>
        <section class="dashboard-hero panel school-drafts-header">
          <div><span class="eyebrow">Review Queue</span><h2>待确认学校资料</h2><p>这里先显示采集或人工补充的草稿。系统采集的信息不会自动写入正式学校库。</p></div>
          <a class="secondary button-link" href="/schools/collection">创建采集任务</a>
        </section>
        <section class="panel school-drafts-table-panel"><div class="table-wrap school-drafts-table-wrap"><table><thead><tr><th>School</th><th>Field</th><th>Draft Value</th><th>Source</th><th>Status</th><th>Review</th></tr></thead><tbody>{body_rows}</tbody></table></div></section>
        </div>
        """
        db.audit(self.user, "school_draft_review_opened", "school_library", record_id="drafts", ip=self.client_address[0], device=self.headers.get("User-Agent"))
        message, kind = self.message()
        self.send_html(page("待确认学校资料", body, self.user, self.csrf, "schools", nas.status(), message, kind))

    def school_collection_draft_actions(self, row):
        if not can_school_action(self.user, "review_collected_data"):
            return '<span class="muted-line">无审核权限</span>'
        options = [("Needs Review", "需要人工确认"), ("Approved", "已确认"), ("Rejected", "已拒绝")]
        return f"""<form class="inline-form compact-actions school-drafts-review-form" method="post" action="/schools/drafts/{row['id']}/review">
          <input type="hidden" name="csrf" value="{esc(self.csrf)}">
          <select name="review_status">{self.school_option_tags(options, row['review_status'] or 'Needs Review')}</select>
          <input name="notes" placeholder="审核备注" value="{esc(row['notes'] or '')}">
          <button class="secondary compact">保存</button>
        </form>"""

    def school_collection_draft_review(self, method, draft_id):
        if method != "POST":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        if not can_school_action(self.user, "review_collected_data"):
            db.audit(self.user, "school_collection_access_denied", "school_library", record_id=draft_id, ip=self.client_address[0], device=self.headers.get("User-Agent"), status="denied", error_message="missing review_collected_data")
            return self.school_action_denied("review_collected_data")
        row = db.one("SELECT * FROM school_collection_drafts WHERE id=?", (draft_id,))
        if not row:
            return self.error_page("采集草稿不存在", HTTPStatus.NOT_FOUND)
        review_status = str(self.form.get("review_status", "Needs Review")).strip()
        if review_status not in {"Needs Review", "Approved", "Rejected"}:
            review_status = "Needs Review"
        notes = str(self.form.get("notes", "")).strip()
        db.execute(
            "UPDATE school_collection_drafts SET review_status=?,confirmed_by=?,confirmed_at=?,notes=?,updated_at=? WHERE id=?",
            (review_status, self.user["id"] if review_status == "Approved" else None, now_iso() if review_status == "Approved" else None, notes, now_iso(), draft_id),
        )
        db.audit(self.user, "school_collected_data_reviewed", "school_library", record_id=draft_id, old_value=row["review_status"], new_value=review_status, ip=self.client_address[0], device=self.headers.get("User-Agent"))
        if review_status == "Approved":
            db.audit(self.user, "school_collected_data_approved", "school_library", record_id=draft_id, student_id=None, new_value=row["field_name"], ip=self.client_address[0], device=self.headers.get("User-Agent"))
        return self.flash_redirect("/schools/drafts", "采集资料审核状态已更新。")

    def school_data_import_panel(self):
        batches = db.all(
            """SELECT b.*,u.display_name imported_name
               FROM school_data_import_batches b
               LEFT JOIN users u ON u.id=b.imported_by
               WHERE NOT (b.import_status='Imported' AND b.review_status='Confirmed')
                 AND (
                  b.total_rows=0
                  OR NOT EXISTS (SELECT 1 FROM school_data_import_rows r0 WHERE r0.batch_id=b.id)
                  OR EXISTS (
                    SELECT 1 FROM school_data_import_rows r
                    WHERE r.batch_id=b.id AND r.import_status NOT IN ('Imported','Merged','Skipped')
                  )
                 )
               ORDER BY b.imported_at DESC LIMIT 20"""
        )
        selected_batch_id = str(self.query.get("school_import_id", [""])[0]).strip()
        selected_batch = db.one(
            """SELECT * FROM school_data_import_batches b
               WHERE b.id=? AND (
                 NOT (b.import_status='Imported' AND b.review_status='Confirmed')
                 AND (
                  b.total_rows=0
                  OR NOT EXISTS (SELECT 1 FROM school_data_import_rows r0 WHERE r0.batch_id=b.id)
                  OR EXISTS (
                   SELECT 1 FROM school_data_import_rows r
                   WHERE r.batch_id=b.id AND r.import_status NOT IN ('Imported','Merged','Skipped')
                  )
                 )
               )""",
            (selected_batch_id,),
        ) if selected_batch_id else None
        if not selected_batch and batches:
            selected_batch = batches[0]
            selected_batch_id = str(selected_batch["id"])
        rows = []
        if selected_batch:
            rows = db.all(
                """SELECT r.*,s.school_name official_school_name
                   FROM school_data_import_rows r
                   LEFT JOIN schools s ON s.id=r.suggested_school_id
                   WHERE r.batch_id=? AND r.import_status NOT IN ('Imported','Merged','Skipped')
                   ORDER BY CASE r.import_status WHEN 'Needs Review' THEN 0 WHEN 'Error' THEN 1 ELSE 2 END,r.row_number LIMIT 300""",
                (selected_batch["id"],),
            )
        school_data_datalist_id = "school-data-import-school-options"
        school_data_datalist = self.school_datalist_html(school_data_datalist_id) if rows else ""
        batch_cards = "".join(
            f"""<a class="ranking-import-card {'active' if str(row['id']) == selected_batch_id else ''}" href="/schools/rankings?school_import_id={esc(row['id'])}">
              <strong>{esc(row['original_filename'])}</strong>
              <span>{esc(row['source_state'])} · {esc(row['file_type'] or '')}</span>
              <small>{esc(row['import_status'])} · Rows {esc(row['total_rows'])} · 新增 {esc(row['new_rows'])} · 已存在 {esc(row['existing_rows'])} · 需确认 {esc(row['review_required_rows'])}</small>
            </a>"""
            for row in batches
        ) or '<div class="empty compact">暂无待确认的学校数据导入记录</div>'
        history_batches = db.all(
            """SELECT b.*,u.display_name imported_name
               FROM school_data_import_batches b
               LEFT JOIN users u ON u.id=b.imported_by
               ORDER BY b.imported_at DESC,b.id DESC LIMIT 80"""
        )
        selected_history_id = str(self.query.get("school_import_history_id", [""])[0]).strip()
        selected_history = db.one(
            """SELECT b.*,u.display_name imported_name
               FROM school_data_import_batches b
               LEFT JOIN users u ON u.id=b.imported_by
               WHERE b.id=?""",
            (selected_history_id,),
        ) if selected_history_id else None
        history_rows = []
        if selected_history:
            history_rows = db.all(
                """SELECT r.*,COALESCE(s.school_name,fs.school_name) linked_school_name
                   FROM school_data_import_rows r
                   LEFT JOIN schools s ON s.id=r.suggested_school_id
                   LEFT JOIN schools fs ON fs.id=r.final_school_id
                   WHERE r.batch_id=?
                   ORDER BY r.row_number LIMIT 500""",
                (selected_history["id"],),
            )
        upload_panel = ""
        if can_school_action(self.user, "upload_ranking_source") and can_school_action(self.user, "import_rankings"):
            upload_panel = f"""<section class="panel school-data-import-upload">
              <div class="panel-head"><div><h2>学校数据导入</h2><p><strong>步骤 1：上传并解析。</strong>没有错误的学校会自动导入；只有需要确认、错误或匹配不清楚的行会进入步骤 2。</p></div></div>
              <form class="stack-form" method="post" action="/schools/data-import/upload" enctype="multipart/form-data">
                <input type="hidden" name="csrf" value="{esc(self.csrf)}">
                <div class="form-grid two-col">
                  <label>State<select name="source_state" required><option value="">选择 State</option>{self.school_data_state_options('VIC')}</select></label>
                  <label>公立 / 私立<select name="source_sector" required><option value="">选择公立 / 私立</option>{self.school_data_import_sector_options('public')}</select></label>
                  <label>Source File<input type="file" name="school_data_file" accept="{SCHOOL_DATA_IMPORT_ACCEPT}" required></label>
                  <label class="wide">Notes<input name="notes" placeholder="例如：VIC government school list 2026"></label>
                </div>
                <small class="muted-line">字段识别：Secondary (or P-9 / P-12) Schools、Campus location/s、Year Levels、Website。无错误行会直接新增或补充缺失字段；有问题的行会留在步骤 2 处理。</small>
                <button class="primary">上传并自动导入</button>
              </form>
            </section>"""
        row_table = ""
        for row in rows:
            status = row["import_status"] or ""
            status_class = "ok" if status in {"Imported", "Merged", "Existing", "Importable"} else ("danger" if status == "Error" else "warn")
            range_text = f"{row['year_level_min'] or 'Unknown'} - {row['year_level_max'] or 'Unknown'}"
            suggested_school_id = row["suggested_school_id"] or ""
            raw_payload = self.school_data_row_raw(row)
            raw_mapping = self.school_data_column_map(raw_payload.keys())
            source_sector = self.school_data_import_sector_key(raw_payload.get("_source_sector", ""), "public")
            address_parts = self.school_data_address_parts(
                row["campus_locations_raw"] or "",
                row["source_state"] or (selected_batch["source_state"] if selected_batch else ""),
                self.school_data_mapped_value(raw_payload, raw_mapping, "suburb", "Suburb"),
                self.school_data_mapped_value(raw_payload, raw_mapping, "postcode", "Postcode"),
            )
            row_table += f"""<tr>
              <td><input type="hidden" name="school_data_row_ids" value="{row['id']}"><select name="source_state_{row['id']}">{self.school_data_state_options(row['source_state'])}</select></td>
              <td><select name="source_sector_{row['id']}">{self.school_data_import_sector_options(source_sector)}</select></td>
              <td><input name="school_name_{row['id']}" value="{esc(row['school_name'] or row['school_name_raw'] or '')}" placeholder="学校名称"></td>
              <td><textarea name="campus_locations_{row['id']}" rows="2" placeholder="Campus location/s">{esc(row['campus_locations_raw'] or '')}</textarea></td>
              <td><input name="region_{row['id']}" value="{esc(row['region_raw'] or self.school_data_mapped_value(raw_payload, raw_mapping, 'region', 'REGION'))}" placeholder="REGION"></td>
              <td><input name="suburb_{row['id']}" value="{esc(address_parts['suburb'])}" placeholder="Suburb"></td>
              <td><input name="postcode_{row['id']}" value="{esc(address_parts['postcode'])}" placeholder="Postcode"></td>
              <td><input name="website_{row['id']}" value="{esc(row['website_raw'] or '')}" placeholder="Website"></td>
              <td><input name="year_levels_{row['id']}" value="{esc(row['year_levels_raw'] or '')}" placeholder="7-12 / K-9 / P-12"></td>
              <td><span>{esc(range_text)}</span><small>{esc(row['year_levels_list_json'] or '[]')}</small></td>
              <td><input list="{school_data_datalist_id}" name="school_id_{row['id']}" value="{esc(suggested_school_id)}" placeholder="留空自动新增/匹配"><small>建议：{esc(row['suggested_school_name'] or row['match_status'] or 'New')}</small></td>
              <td><span class="status {status_class}">{esc(status)}</span><small>{esc(row['error_reason'] or '')}</small></td>
              <td class="compact-actions"><input name="notes_{row['id']}" value="{esc(row['notes'] or '')}" placeholder="备注"><button class="secondary compact" formaction="/schools/data-import/rows/{row['id']}/confirm">确认/合并</button><button class="secondary compact" formaction="/schools/data-import/rows/{row['id']}/skip">跳过</button></td>
            </tr>"""
        if selected_batch:
            summary = f"""<div class="ranking-import-summary">
              <span>可导入 <b>{esc(selected_batch['importable_rows'])}</b></span>
              <span>需确认 <b>{esc(selected_batch['review_required_rows'])}</b></span>
              <span>已存在 <b>{esc(selected_batch['existing_rows'])}</b></span>
              <span>新增 <b>{esc(selected_batch['new_rows'])}</b></span>
              <span>错误 <b>{esc(selected_batch['error_rows'])}</b></span>
            </div>"""
            table_or_empty = f"""{school_data_datalist}<div class="table-wrap school-data-preview-table"><table><thead><tr><th>State</th><th>公立 / 私立</th><th>学校名称</th><th>Campus Address</th><th>Region</th><th>Suburb</th><th>Postcode</th><th>Website</th><th>Year Levels 原文</th><th>解析后年级</th><th>匹配学校</th><th>状态</th><th>操作</th></tr></thead><tbody>{row_table}</tbody></table></div>""" if rows else '<div class="empty compact">该上传批次暂无解析数据；可以重新上传，或删除这个上传批次。</div>'
            confirm_button = '<button class="primary" onclick="return confirm(\'确认导入当前这些需要人工处理的学校数据？\');">导入已修改的问题行</button>' if rows else ""
            preview = f"""<form method="post" action="/schools/data-import/batches/{selected_batch['id']}/confirm-all" onsubmit="return true;">
              <input type="hidden" name="csrf" value="{esc(self.csrf)}">
              {summary}
              {table_or_empty}
              <div class="form-actions">
                {confirm_button}
                <button class="secondary" formaction="/schools/data-import/batches/{selected_batch['id']}/clear-rows" onclick="return confirm('确认清除当前批次的解析数据？上传文件会保留，已写入学校库的数据不会删除。');">清除解析数据</button>
                <button class="danger" formaction="/schools/data-import/batches/{selected_batch['id']}/delete" onclick="return confirm('确认删除这个上传数据批次？系统会删除该批次、解析数据和项目内保存的源文件，但不会删除已写入学校库的学校。');">删除上传数据</button>
                <a class="secondary button-link" href="/schools/rankings?school_import_id={esc(selected_batch['id'])}">查看错误详情</a>
              </div>
            </form>"""
        else:
            preview = '<div class="empty compact">上传学校数据文件后，这里会显示解析结果预览表。</div>'
        history_list_rows = "".join(
            f"""<tr>
              <td>{esc(display_datetime(row['imported_at']) or row['imported_at'])}</td>
              <td><strong>{esc(row['original_filename'])}</strong><small>{esc(row['stored_file_path'] or '')}</small></td>
              <td>{esc(row['source_state'])}</td>
              <td>{esc(row['file_type'] or '')}</td>
              <td><span class="status {'ok' if row['review_status'] == 'Confirmed' else 'warn'}">{esc(row['import_status'])}</span><small>{esc(row['review_status'])}</small></td>
              <td>{esc(row['total_rows'])}</td>
              <td>{esc(row['imported_rows'])}</td>
              <td>{esc(row['review_required_rows'])}</td>
              <td>{esc(row['error_rows'])}</td>
              <td>{esc(row['imported_name'] or '')}</td>
              <td class="row-actions"><a class="secondary button-link" href="/schools/rankings?school_import_history_id={esc(row['id'])}#school-data-import-history">查看</a><a class="ghost button-link" href="/schools/data-import/batches/{esc(row['id'])}/download">下载</a></td>
            </tr>"""
            for row in history_batches
        ) or '<tr><td colspan="11" class="empty">暂无历史上传记录。</td></tr>'
        history_detail = ""
        if selected_history:
            history_row_table = "".join(
                f"""<tr>
                  <td>{esc(row['row_number'])}</td>
                  <td>{esc(row['source_state'])}</td>
                  <td>{esc(row['school_name'] or row['school_name_raw'] or '')}</td>
                  <td class="wrap-cell">{esc(row['campus_locations_raw'] or '')}</td>
                  <td>{esc(row['year_levels_raw'] or '')}</td>
                  <td>{esc(row['linked_school_name'] or '')}</td>
                  <td><span class="status {'danger' if row['import_status'] == 'Error' else ('ok' if row['import_status'] in {'Imported','Merged','Skipped'} else 'warn')}">{esc(row['import_status'] or '')}</span><small>{esc(row['review_status'] or '')}</small></td>
                  <td class="wrap-cell">{esc(row['error_reason'] or row['notes'] or '')}</td>
                </tr>"""
                for row in history_rows
            ) or '<tr><td colspan="8" class="empty">这个批次没有解析行记录，可能解析数据已被清除；源文件仍可下载。</td></tr>'
            history_detail = f"""
            <section class="panel inner-panel">
              <div class="panel-head"><div><h2>历史批次详情</h2><p>{esc(selected_history['original_filename'])} · 上传日期：{esc(display_datetime(selected_history['imported_at']) or selected_history['imported_at'])}</p></div><a class="secondary button-link" href="/schools/data-import/batches/{esc(selected_history['id'])}/download">下载源文件</a></div>
              <div class="ranking-import-summary">
                <span>State <b>{esc(selected_history['source_state'])}</b></span>
                <span>总行数 <b>{esc(selected_history['total_rows'])}</b></span>
                <span>已导入 <b>{esc(selected_history['imported_rows'])}</b></span>
                <span>需确认 <b>{esc(selected_history['review_required_rows'])}</b></span>
                <span>错误 <b>{esc(selected_history['error_rows'])}</b></span>
              </div>
              <div class="table-wrap school-data-preview-table"><table><thead><tr><th>#</th><th>State</th><th>学校</th><th>地址</th><th>年级</th><th>关联学校</th><th>状态</th><th>备注/错误</th></tr></thead><tbody>{history_row_table}</tbody></table></div>
            </section>"""
        history_panel = f"""
        <section id="school-data-import-history" class="panel school-data-import-history">
          <div class="panel-head"><div><h2>历史上传记录</h2><p>保存每次学校数据上传记录，已完成导入的批次不会再出现在步骤 2，但可以在这里查看和下载源文件。</p></div></div>
          {history_detail}
          <div class="table-wrap"><table><thead><tr><th>上传日期</th><th>文件</th><th>State</th><th>类型</th><th>状态</th><th>总行</th><th>已导入</th><th>需确认</th><th>错误</th><th>上传人</th><th>操作</th></tr></thead><tbody>{history_list_rows}</tbody></table></div>
        </section>"""
        return f"""
        {upload_panel}
        <section class="ranking-import-layout school-data-import-layout">
          <div class="panel ranking-import-list"><div class="panel-head"><div><h2>学校数据批次</h2><p>记录每次上传、解析、导入状态和错误详情。</p></div></div>{batch_cards}</div>
          <div class="panel ranking-import-review"><div class="panel-head"><div><h2>步骤 2：处理需要人工确认的数据</h2><p>无错误行已经自动导入；这里只显示有错误、需修改、匹配不确定的部分。修改后再导入，已存在学校只补充缺失字段。</p></div></div>{preview}</div>
        </section>
        {history_panel}
        """

    def school_ranking_normalize_text(self, value):
        return re.sub(r"[^a-z0-9]+", "", str(value or "").lower())

    def school_ranking_detect_system(self, filename, source_url, rows):
        haystack = " ".join([filename or "", source_url or ""] + [str(v) for row in rows[:10] for v in row.values()])
        upper = haystack.upper()
        for system in BETTER_EDUCATION_SYSTEMS:
            if system.upper() in upper:
                return system
        return "VCE"

    def school_ranking_detect_year(self, filename, rows, source_url=""):
        explicit_sources = [filename or "", source_url or ""]
        explicit_year_keys = {"year", "datayear", "rankingyear", "resultyear", "schoolyear", "排名年份", "年份"}
        for row in rows[:20]:
            raw = row.get("raw", row) if isinstance(row, dict) else {}
            if not isinstance(raw, dict):
                continue
            for key, value in raw.items():
                normalized_key = self.school_ranking_normalize_text(key)
                if normalized_key in explicit_year_keys or ("year" in normalized_key and "school" not in normalized_key):
                    explicit_sources.append(str(value or ""))
        haystack = " ".join(explicit_sources)
        years = [int(match) for match in re.findall(r"\b(20\d{2})\b", haystack)]
        current = int(local_year())
        plausible = [year for year in years if 2000 <= year <= current + 1]
        return str(plausible[0]) if plausible else str(current)

    def school_ranking_detect_state(self, filename, rows):
        haystack = " ".join([filename or ""] + [str(v) for row in rows[:10] for v in row.values()]).upper()
        for state in ("VIC", "NSW", "QLD", "WA", "SA", "TAS", "ACT", "NT"):
            if re.search(rf"\b{state}\b", haystack):
                return state
        system = self.school_ranking_detect_system(filename, "", rows)
        return {"VCE": "VIC", "HSC": "NSW", "WACE": "WA", "QCE": "QLD"}.get(system, "")

    def school_ranking_column_map(self, headers):
        normalized = {self.school_ranking_normalize_text(header): header for header in headers}
        mapping = {}
        for field, aliases in BETTER_EDUCATION_COLUMN_ALIASES.items():
            for alias in aliases:
                key = self.school_ranking_normalize_text(alias)
                if key in normalized:
                    mapping[field] = normalized[key]
                    break
        return mapping

    def school_ranking_is_bettereducation_header(self, value):
        normalized = self.school_ranking_normalize_text(value)
        return all(token in normalized for token in ("better", "education", "rank", "school", "percentile", "locality"))

    def school_ranking_clean_locality(self, value):
        text = re.sub(r"\s+", " ", str(value or "")).strip(" \t\r\n|,;")
        if not text:
            return ""
        state_codes = r"NSW|VIC|QLD|SA|WA|ACT|TAS|NT"
        text = re.sub(rf",?\s*(?:{state_codes}),?\s*\d{{4}}\b.*$", "", text, flags=re.I).strip(" ,;")
        if self.school_ranking_normalize_text(text) in {"metro", "country", "government", "nongovernment"}:
            return ""
        return text

    def school_ranking_clean_school_name(self, value):
        text = re.sub(r"\s+", " ", str(value or "")).strip(" \t\r\n|,;")
        if not text:
            return ""
        junk_words = re.compile(
            r"\b(prepaid|recharge|sim|compare|trend|naplan|plenty of easy ways|years 10 and 11)\b",
            re.I,
        )
        if junk_words.search(text):
            return ""
        state_codes = r"NSW|VIC|QLD|SA|WA|ACT|TAS|NT"
        if re.fullmatch(rf"[A-Za-z][A-Za-z .'-]+,\s*(?:{state_codes}),?\s*\d{{4}}", text, flags=re.I):
            return ""
        text = re.sub(rf",\s*[A-Za-z][A-Za-z .'-]+,\s*(?:{state_codes}),?\s*\d{{4}}\b.*$", "", text, flags=re.I).strip(" ,;")
        text = re.sub(rf"\s*,\s*(?:{state_codes}),?\s*\d{{4}}\b.*$", "", text, flags=re.I).strip(" ,;")
        if text.lower() in {"school", "compare", "trend", "trend / compare"}:
            return ""
        if len(self.school_ranking_normalize_text(text)) < 4:
            return ""
        return text

    def school_ranking_canonical_row(self, row):
        mapping = self.school_ranking_column_map(row.keys())
        data = {field: str(row.get(column, "") or "").strip() for field, column in mapping.items()}
        data.setdefault("school_name_raw", "")
        data.setdefault("locality", "")
        if data.get("result_metric_value") and not data.get("result_metric_name"):
            normalized_columns = {self.school_ranking_normalize_text(column): column for column in row.keys()}
            if self.school_ranking_normalize_text("Percentage of satisfactory VCE completions") in normalized_columns:
                data["result_metric_name"] = "Percentage of satisfactory VCE completions"
        school_name = self.school_ranking_clean_school_name(data.get("school_name_raw", ""))
        locality = self.school_ranking_clean_locality(data.get("locality", ""))
        recovered = self.school_ranking_recover_bettereducation_row(row, school_name, locality)
        if recovered:
            school_name = recovered.get("school_name_raw") or school_name
            locality = recovered.get("locality") or locality
            data["rank"] = recovered.get("rank") or data.get("rank", "")
            data["category"] = recovered.get("category") or data.get("category", "")
            data["region"] = recovered.get("region") or data.get("region", "")
        return {
            "school_name_raw": school_name,
            "locality": locality,
            "matching_name": f"{school_name}, {locality}" if school_name and locality else school_name,
            "rank": data.get("rank", ""),
            "category": data.get("category", ""),
            "region": data.get("region", ""),
            "score": data.get("score", ""),
            "median_score": data.get("median_score", ""),
            "top_scores_percentage": data.get("top_scores_percentage", ""),
            "percentile": data.get("percentile", ""),
            "result_metric_name": data.get("result_metric_name", ""),
            "result_metric_value": data.get("result_metric_value", ""),
        }

    def school_ranking_recover_bettereducation_row(self, row, school_name="", locality=""):
        raw_text = ""
        for key in ("Raw Text", "raw_text", "_raw_text", "Text"):
            if key in row and str(row.get(key) or "").strip():
                raw_text = str(row.get(key) or "").strip()
                break
        if not raw_text:
            return None
        if school_name and locality:
            return None
        cells = [cell.strip() for cell in re.split(r"\s*\|\s*|\t+|\s{2,}", raw_text) if cell.strip()]
        recovered = self.school_ranking_row_from_bettereducation_cells(cells)
        if not recovered:
            return None
        recovered_canonical = self.school_ranking_canonical_row_without_recovery(recovered)
        if not recovered_canonical.get("school_name_raw"):
            return None
        return recovered_canonical

    def school_ranking_canonical_row_without_recovery(self, row):
        mapping = self.school_ranking_column_map(row.keys())
        data = {field: str(row.get(column, "") or "").strip() for field, column in mapping.items()}
        school_name = self.school_ranking_clean_school_name(data.get("school_name_raw", ""))
        locality = self.school_ranking_clean_locality(data.get("locality", ""))
        return {
            "school_name_raw": school_name,
            "locality": locality,
            "matching_name": f"{school_name}, {locality}" if school_name and locality else school_name,
            "rank": data.get("rank", ""),
            "category": data.get("category", ""),
            "region": data.get("region", ""),
            "score": data.get("score", ""),
            "median_score": data.get("median_score", ""),
            "top_scores_percentage": data.get("top_scores_percentage", ""),
            "percentile": data.get("percentile", ""),
            "result_metric_name": data.get("result_metric_name", ""),
            "result_metric_value": data.get("result_metric_value", ""),
        }

    def school_ranking_plausible_school_cell(self, cell):
        text = re.sub(r"\s+", " ", str(cell or "")).strip()
        if not text:
            return ""
        normalized = self.school_ranking_normalize_text(text)
        if normalized in {"trendcompare", "trend", "compare", "metro", "country", "regional", "government", "nongovernment", "non-government"}:
            return ""
        if re.fullmatch(r"#?\d{1,4}", text) or re.fullmatch(r"\d+(?:\.\d+)?%?", text):
            return ""
        if re.search(r"\b(NSW|VIC|QLD|SA|WA|ACT|TAS|NT)\b,?\s*\d{4}\b", text, re.I):
            return ""
        return self.school_ranking_clean_school_name(text)

    def school_ranking_row_from_bettereducation_cells(self, cells):
        cleaned = [re.sub(r"\s+", " ", str(cell or "")).strip() for cell in cells]
        if len(cleaned) < 8:
            return None
        rank_values = []
        for index in range(min(4, len(cleaned))):
            match = re.fullmatch(r"#?\s*(\d{1,4})", cleaned[index] or "")
            if match:
                rank_values.append((index, match.group(1)))
        if not rank_values:
            return None
        rank = rank_values[0][1]
        school_index = None
        school_words = re.compile(r"\b(school|college|grammar|academy|institute|primary|secondary|high)\b", re.I)
        for index, cell in enumerate(cleaned[1:8], start=1):
            if school_words.search(cell):
                school_index = index
                break
        if school_index is None:
            rank_indexes = {index for index, _rank in rank_values}
            for index, cell in enumerate(cleaned[1:8], start=1):
                if index in rank_indexes:
                    continue
                if self.school_ranking_plausible_school_cell(cell):
                    school_index = index
                    break
        school_name = self.school_ranking_clean_school_name(cleaned[school_index] if school_index is not None and school_index < len(cleaned) else "")
        if not school_name:
            return None
        locality = ""
        locality_pattern = re.compile(r"\b(NSW|VIC|QLD|SA|WA|ACT|TAS|NT)\b,?\s*\d{4}\b", re.I)
        for cell in reversed(cleaned):
            if locality_pattern.search(cell):
                locality = self.school_ranking_clean_locality(cell)
                break
        category = next((cell for cell in cleaned if self.school_ranking_normalize_text(cell) in {"government", "nongovernment", "non-government"}), "")
        region = next((cell for cell in cleaned if self.school_ranking_normalize_text(cell) in {"metro", "country", "regional"}), "")
        return {
            "Better Education Rank": rank,
            "School": school_name,
            "Locality": locality,
            "Category": category,
            "Region": region,
            "Raw Text": " | ".join(cell for cell in cleaned if cell),
        }

    def school_ranking_row_from_cells(self, cells):
        cleaned = [re.sub(r"\s+", " ", str(cell or "")).strip() for cell in cells]
        cleaned = [cell for cell in cleaned if cell]
        if len(cleaned) < 2:
            return None
        rank_pattern = re.compile(r"^\s*#?\s*(\d{1,4})(?:st|nd|rd|th)?\s*$", re.I)
        rank = ""
        rank_index = None
        for index, cell in enumerate(cleaned):
            match = rank_pattern.match(cell)
            if match:
                value = int(match.group(1))
                if 1 <= value <= 5000:
                    rank = match.group(1)
                    rank_index = index
                    break
        if not rank:
            return None
        school_candidates = [cell for index, cell in enumerate(cleaned) if index != rank_index]
        school_words = re.compile(r"\b(school|college|grammar|academy|institute|primary|secondary|high)\b", re.I)
        school_name = ""
        for candidate in school_candidates:
            if school_words.search(candidate):
                school_name = candidate
                break
        if not school_name and school_candidates:
            school_name = max(school_candidates, key=len)
        school_name = self.school_ranking_clean_school_name(school_name)
        if not school_name or len(school_name) < 3:
            return None
        return {"Rank": rank, "School Name": school_name, "Raw Text": " | ".join(cleaned)}

    def school_ranking_parse_text_rows(self, text):
        lines = [re.sub(r"\s+", " ", line).strip(" \t\r\n|") for line in str(text or "").splitlines()]
        lines = [line for line in lines if line]
        if not lines:
            return []
        bettereducation_header_index = next((index for index, line in enumerate(lines) if self.school_ranking_is_bettereducation_header(line)), None)
        if bettereducation_header_index is not None:
            lines = lines[bettereducation_header_index + 1:]
        parsed = []
        table_rows = []
        pending_rank = ""
        rank_prefix = re.compile(r"^\s*#?\s*(\d{1,4})(?:st|nd|rd|th)?[\).\-\s]+(.{3,})$", re.I)
        rank_suffix = re.compile(r"^(.{3,}?)\s+(\d{1,4})(?:st|nd|rd|th)?\s*$", re.I)
        rank_only = re.compile(r"^\s*#?\s*(\d{1,4})(?:st|nd|rd|th)?\s*$", re.I)
        school_words = re.compile(r"\b(school|college|grammar|academy|institute|primary|secondary|high)\b", re.I)
        for line in lines:
            if self.school_ranking_is_bettereducation_header(line):
                table_rows = []
                pending_rank = ""
                continue
            if "|" in line or "\t" in line or re.search(r"\s{2,}", line):
                cells = [cell.strip() for cell in re.split(r"\s*\|\s*|\t+|\s{2,}", line) if cell.strip()]
                if len(cells) >= 2:
                    table_rows.append(cells)
                    pending_rank = ""
                    continue
            match = rank_prefix.match(line)
            if match:
                value = int(match.group(1))
                if 1 <= value <= 5000:
                    parsed.append({"Rank": match.group(1), "School Name": match.group(2).strip(), "Raw Text": line})
                    pending_rank = ""
                    continue
            match = rank_only.match(line)
            if match and 1 <= int(match.group(1)) <= 5000:
                pending_rank = match.group(1)
                continue
            if pending_rank and school_words.search(line):
                parsed.append({"Rank": pending_rank, "School Name": line.strip(), "Raw Text": f"{pending_rank} {line.strip()}"})
                pending_rank = ""
                continue
            match = rank_suffix.match(line)
            if match and school_words.search(match.group(1)):
                value = int(match.group(2))
                if 1 <= value <= 5000:
                    parsed.append({"Rank": match.group(2), "School Name": match.group(1).strip(), "Raw Text": line})
                    pending_rank = ""
                    continue
            pending_rank = ""
        if table_rows:
            header_index = None
            for index, cells in enumerate(table_rows[:8]):
                normalized = [self.school_ranking_normalize_text(cell) for cell in cells]
                has_rank = any(cell in {"rank", "ranking", "position", "no"} or "rank" in cell for cell in normalized)
                has_school = any("school" in cell or "college" in cell for cell in normalized)
                if has_rank and has_school:
                    header_index = index
                    break
            if header_index is not None:
                headers = table_rows[header_index]
                for values in table_rows[header_index + 1:]:
                    if not any(values):
                        continue
                    parsed.append({headers[i] if i < len(headers) and headers[i] else f"Column {i+1}": values[i] if i < len(values) else "" for i in range(max(len(headers), len(values)))})
            else:
                for cells in table_rows:
                    row = self.school_ranking_row_from_bettereducation_cells(cells) or self.school_ranking_row_from_cells(cells)
                    if row:
                        parsed.append(row)
        return parsed

    def school_ranking_parse_csv(self, upload):
        text = upload.data.decode("utf-8-sig", errors="replace")
        sample = text[:4096]
        try:
            dialect = csv.Sniffer().sniff(sample)
        except csv.Error:
            dialect = csv.excel
        return [dict(row) for row in csv.DictReader(io.StringIO(text), dialect=dialect)]

    def school_ranking_act_school_code_map(self, workbook):
        code_map = {}
        school_type = re.compile(r"\b(school|college|grammar|academy|campus|centre|pathways)\b", re.I)
        for sheet in workbook.worksheets:
            if "dictionary" not in sheet.title.lower():
                continue
            text = " ".join(str(cell or "") for row in sheet.iter_rows(values_only=True) for cell in row if cell)
            for code, name in re.findall(r"\b([A-Z0-9]{3,5})\s*-\s*([^.;]+?)(?=\.?\s+[A-Z0-9]{3,5}\s*-|\.|$)", text):
                clean_name = re.sub(r"\s+", " ", name).strip(" .")
                if clean_name and school_type.search(clean_name):
                    code_map[code.strip().upper()] = clean_name
        return code_map

    def school_ranking_parse_act_certification_excel(self, workbook):
        code_map = self.school_ranking_act_school_code_map(workbook)
        if not code_map:
            return []
        target = next((sheet for sheet in workbook.worksheets if "cert stats" in sheet.title.lower()), None)
        if target is None:
            return []
        rows = list(target.iter_rows(values_only=True))
        if not rows:
            return []
        headers = [str(cell or "").strip() for cell in rows[0]]
        normalized = [self.school_ranking_normalize_text(header) for header in headers]
        if "homeschoolcode" not in normalized or "ssctotal" not in normalized:
            return []
        parsed = []
        for values in rows[1:]:
            row = {headers[i] if i < len(headers) and headers[i] else f"Column {i + 1}": values[i] if i < len(values) else "" for i in range(max(len(headers), len(values)))}
            code = str(row.get("homeschoolcode") or row.get("HomeSchoolCode") or "").strip().upper()
            if not code or code == "ALL" or code not in code_map:
                continue
            if str(row.get("Gender") or row.get("gender") or "").strip().lower() != "all":
                continue
            if str(row.get("Package") or row.get("package") or "").strip().lower() != "standard":
                continue
            if str(row.get("TES") or row.get("tes") or "").strip().lower() != "yes":
                continue
            parsed.append({
                "School Name": code_map[code],
                "HomeSchoolCode": code,
                "Result Metric Name": "ACT students awarded a Senior Secondary Certificate with TES",
                "Result Metric Value": row.get("SSCTotal") or row.get("ssctotal") or "",
                "Raw Text": json.dumps(row, ensure_ascii=False),
            })
        return parsed

    def school_ranking_parse_excel(self, upload):
        wb = load_workbook(io.BytesIO(upload.data), data_only=True, read_only=True)
        try:
            act_rows = self.school_ranking_parse_act_certification_excel(wb)
            if act_rows:
                return act_rows
            parsed = []
            for ws in wb.worksheets:
                rows = list(ws.iter_rows(values_only=True))
                if not rows:
                    continue
                header_index = None
                headers = []
                for index, raw in enumerate(rows[:80]):
                    cleaned = [str(cell or "").strip() for cell in raw]
                    mapping = self.school_ranking_column_map(cleaned)
                    normalized = {self.school_ranking_normalize_text(item) for item in cleaned if item}
                    if "school_name_raw" in mapping and (
                        {"rank", "locality", "score", "median_score", "top_scores_percentage", "result_metric_value"}.intersection(mapping)
                        or normalized.intersection({"smallschool", "schoolprogram", "studentcohort"})
                    ):
                        header_index = index
                        headers = cleaned
                        break
                if header_index is None:
                    continue
                for values in rows[header_index + 1:]:
                    if not any(values):
                        continue
                    row = {headers[i] if i < len(headers) and headers[i] else f"Column {i + 1}": values[i] if i < len(values) else "" for i in range(max(len(headers), len(values)))}
                    if str(row.get("School") or row.get("School Name") or "").strip():
                        parsed.append(row)
                if parsed:
                    return parsed
            ws = wb.active
            rows = list(ws.iter_rows(values_only=True))
            if not rows:
                return []
            headers = [str(cell or "").strip() for cell in rows[0]]
            parsed = []
            for values in rows[1:]:
                if not any(values):
                    continue
                parsed.append({headers[i] if i < len(headers) and headers[i] else f"Column {i+1}": values[i] if i < len(values) else "" for i in range(max(len(headers), len(values)))})
            return parsed
        finally:
            wb.close()

    def school_ranking_html_tables(self, html_text):
        tables = []
        for table in re.findall(r"<table[\s\S]*?</table>", html_text or "", flags=re.I):
            rows = []
            for tr in re.findall(r"<tr[\s\S]*?</tr>", table, flags=re.I):
                cells = re.findall(r"<t[dh][^>]*>([\s\S]*?)</t[dh]>", tr, flags=re.I)
                clean = [
                    html.unescape(re.sub(r"\s+", " ", re.sub(r"<[^>]+>", " ", cell)).strip())
                    for cell in cells
                ]
                if clean:
                    rows.append(clean)
            if rows:
                tables.append(rows)
        return tables

    def school_ranking_parse_nsw_merit_html(self, html_text):
        school_counts = {}
        raw_by_school = {}
        for table in self.school_ranking_html_tables(html_text):
            if len(table) < 2:
                continue
            headers = table[0]
            normalized = [self.school_ranking_normalize_text(header) for header in headers]
            school_index = next((index for index, key in enumerate(normalized) if key in {"school", "schoolname"} or key.endswith("school")), None)
            if school_index is None:
                continue
            for values in table[1:]:
                if school_index >= len(values):
                    continue
                school_name = self.school_ranking_clean_school_name(values[school_index])
                if not school_name:
                    continue
                school_counts[school_name] = school_counts.get(school_name, 0) + 1
                raw_by_school.setdefault(school_name, []).append({headers[i] if i < len(headers) else f"Column {i + 1}": values[i] for i in range(min(len(headers), len(values)))})
        return [
            {
                "School Name": school_name,
                "Result Metric Name": "NSW HSC Merit List entries",
                "Result Metric Value": count,
                "Raw Text": json.dumps(raw_by_school.get(school_name, []), ensure_ascii=False),
            }
            for school_name, count in sorted(school_counts.items())
        ]

    def school_ranking_parse_sa_public_html(self, html_text):
        text = html.unescape(re.sub(r"\s+", " ", re.sub(r"<[^>]+>", " ", html_text or " "))).strip()
        lower = text.lower()
        if "sace data" not in lower and "south australian certificate of education" not in lower:
            return []
        sections = set()
        for href, label in re.findall(r"<a\b[^>]*href=[\"']([^\"']+)[\"'][^>]*>(.*?)</a>", html_text or "", flags=re.I | re.S):
            combined = f"{href} {re.sub(r'<[^>]+>', ' ', label)}".lower()
            if "subject-results" in combined or "subject results" in combined:
                sections.add("Subject results")
            if "completion" in combined:
                sections.add("Completion")
            if "pathways" in combined:
                sections.add("Pathways")
        if not sections:
            sections.add("SACE Data")
        return [{
            "School Name": "South Australia SACE Public Data Benchmark",
            "Result Metric Name": "SACE public data sections monitored",
            "Result Metric Value": len(sections),
            "Raw Text": "; ".join(sorted(sections)),
        }]

    def school_ranking_parse_academic_html(self, html_text):
        state = str(getattr(self, "form", {}).get("state", "") if getattr(self, "form", None) is not None else "").strip().upper()
        source_name = str(getattr(self, "form", {}).get("source_name", "") if getattr(self, "form", None) is not None else "").strip().lower()
        source_type = str(getattr(self, "form", {}).get("source_type", "") if getattr(self, "form", None) is not None else "").strip().lower()
        if source_type != "official_academic_results" and "academic" not in source_name and "sace" not in source_name and "hsc" not in source_name:
            return []
        if state == "NSW" or "hsc merit" in source_name:
            rows = self.school_ranking_parse_nsw_merit_html(html_text)
            if rows:
                return rows
        if state == "SA" or "sace" in source_name:
            return self.school_ranking_parse_sa_public_html(html_text)
        return []

    def school_ranking_parse_html(self, upload):
        html = upload.data.decode("utf-8", errors="replace")
        academic_rows = self.school_ranking_parse_academic_html(html)
        if academic_rows:
            return academic_rows
        tables = self.school_ranking_html_tables(html)
        if not tables:
            return []
        rows = tables[0]
        if len(rows) < 2:
            return []
        headers = rows[0]
        return [{headers[i] if i < len(headers) and headers[i] else f"Column {i+1}": value for i, value in enumerate(row)} for row in rows[1:]]

    def school_ranking_parse_pdf(self, upload):
        parsed = []
        found_bettereducation_header = False
        fallback_rows = []
        try:
            import pdfplumber
        except Exception:
            parsed = []
        else:
            with pdfplumber.open(io.BytesIO(upload.data)) as pdf:
                for page_obj in pdf.pages[:10]:
                    page_text = page_obj.extract_text() if hasattr(page_obj, "extract_text") else ""
                    page_text = page_text or ""
                    if self.school_ranking_is_bettereducation_header(page_text):
                        found_bettereducation_header = True
                    for table in page_obj.extract_tables() or []:
                        if not table:
                            continue
                        first_row = [str(cell or "").strip() for cell in table[0]]
                        if self.school_ranking_is_bettereducation_header(" ".join(first_row)):
                            found_bettereducation_header = True
                        normalized = [self.school_ranking_normalize_text(cell) for cell in first_row]
                        has_rank = any(cell in {"rank", "ranking", "position", "no"} or "rank" in cell for cell in normalized)
                        has_school = any("school" in cell or "college" in cell for cell in normalized)
                        if len(table) >= 2 and has_rank and has_school:
                            headers = first_row
                            for values in table[1:]:
                                if not any(values):
                                    continue
                                row = {headers[i] if i < len(headers) and headers[i] else f"Column {i+1}": values[i] if i < len(values) else "" for i in range(max(len(headers), len(values)))}
                                if found_bettereducation_header:
                                    parsed.append(row)
                                else:
                                    fallback_rows.append(row)
                            continue
                        for values in table:
                            row = self.school_ranking_row_from_bettereducation_cells(values) if found_bettereducation_header else None
                            row = row or (self.school_ranking_row_from_cells(values) if not found_bettereducation_header else None)
                            if row:
                                if found_bettereducation_header:
                                    parsed.append(row)
                                else:
                                    fallback_rows.append(row)
        if parsed:
            return parsed
        if fallback_rows:
            return fallback_rows
        text = extract_uploaded_text(upload)
        return self.school_ranking_parse_text_rows(text)

    def school_ranking_parse_word(self, upload):
        suffix = Path(upload.filename or "").suffix.lower()
        if suffix == ".docx":
            try:
                document = Document(io.BytesIO(upload.data))
                parts = []
                for paragraph in document.paragraphs:
                    text = paragraph.text.strip()
                    if text:
                        parts.append(text)
                for table in document.tables:
                    for row in table.rows:
                        cells = [cell.text.strip() for cell in row.cells if cell.text.strip()]
                        if cells:
                            parts.append(" | ".join(cells))
                return self.school_ranking_parse_text_rows("\n".join(parts))
            except Exception as exc:
                raise ValueError(f"Word 文件无法读取：{exc}") from exc
        with tempfile.NamedTemporaryFile(prefix="aaie_ranking_doc_", suffix=suffix or ".doc") as temp:
            temp.write(upload.data)
            temp.flush()
            result = subprocess.run(
                ["/usr/bin/textutil", "-convert", "txt", "-stdout", temp.name],
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                text=True,
                timeout=30,
                check=False,
            )
        if result.returncode != 0 or not result.stdout.strip():
            raise ValueError("旧版 Word .doc 文件未能读取，请另存为 .docx 后再导入。")
        return self.school_ranking_parse_text_rows(result.stdout)

    def school_ranking_parse_image(self, upload):
        text = extract_uploaded_text(upload)
        if not text.strip():
            raise ValueError("图片文件已支持上传，但未读取到文字。请确认图片清晰、包含学校名和排名，或先转为 Word/Excel/PDF 后再导入。")
        return self.school_ranking_parse_text_rows(text)

    def school_ranking_parse_upload(self, upload):
        suffix = Path(upload.filename or "").suffix.lower()
        if suffix in {".csv", ".txt"}:
            return self.school_ranking_parse_csv(upload)
        if suffix in {".xlsx", ".xlsm"}:
            return self.school_ranking_parse_excel(upload)
        if suffix in {".html", ".htm"}:
            return self.school_ranking_parse_html(upload)
        if suffix == ".pdf":
            return self.school_ranking_parse_pdf(upload)
        if suffix in {".docx", ".doc"}:
            return self.school_ranking_parse_word(upload)
        if suffix in {".jpg", ".jpeg", ".png", ".webp", ".heic", ".tif", ".tiff"} or str(upload.content_type or "").startswith("image/"):
            return self.school_ranking_parse_image(upload)
        raise ValueError("仅支持 CSV、Excel、HTML、PDF、Word 和图片。图片会尝试 OCR，识别不到时请换清晰图片或转成 Word/Excel。")

    def school_data_state_options(self, selected=""):
        selected = str(selected or "").strip().upper()
        return "".join(f'<option value="{state}" {"selected" if state == selected else ""}>{state}</option>' for state in SCHOOL_DATA_IMPORT_STATES)

    def school_data_header_key(self, value):
        return self.school_ranking_normalize_text(value)

    def school_data_column_map(self, headers):
        normalized = {self.school_data_header_key(header): header for header in headers}
        mapping = {}
        for field, aliases in SCHOOL_DATA_COLUMN_ALIASES.items():
            for alias in aliases:
                key = self.school_data_header_key(alias)
                if key in normalized:
                    mapping[field] = normalized[key]
                    break
        return mapping

    def school_data_mapped_value(self, row, mapping, field, *fallbacks):
        column = mapping.get(field, "")
        for key in (column, field, *fallbacks):
            if key and key in row:
                value = str(row.get(key, "") or "").strip()
                if value:
                    return value
        return ""

    def school_data_address_parts(self, campus_locations, source_state="", suburb="", postcode=""):
        address = str(campus_locations or "").strip()
        state = str(source_state or "").strip().upper()
        suburb = str(suburb or "").strip()
        postcode = str(postcode or "").strip()
        if not postcode:
            match = re.search(r"\b(\d{4})\b", address)
            if match:
                postcode = match.group(1)
        if not suburb and address:
            state_pattern = re.escape(state) if state else r"VIC|NSW|QLD|SA|WA|ACT|TAS|NT"
            if postcode:
                match = re.search(rf"([A-Za-z][A-Za-z .'-]+?)\s+(?:{state_pattern})\s+{re.escape(postcode)}\b", address, re.I)
            else:
                match = re.search(rf"([A-Za-z][A-Za-z .'-]+?)\s+(?:{state_pattern})\b", address, re.I)
            if match:
                suburb = re.sub(r"\s+", " ", match.group(1)).strip().split(",")[-1].strip()
        return {"address": address, "suburb": suburb, "postcode": postcode}

    def school_data_level_label(self, value):
        if value == 0:
            return "Prep / Foundation"
        if 1 <= value <= 12:
            return f"Year {value}"
        return "Unknown"

    def school_data_level_number(self, value):
        text = str(value or "").strip().lower()
        text = text.replace("foundation", "prep")
        if text in {"k", "kg", "kindergarten", "prep", "p", "preparatory"}:
            return 0
        match = re.search(r"\b(?:year|yr|y)?\s*(\d{1,2})\b", text)
        if match:
            number = int(match.group(1))
            if 1 <= number <= 12:
                return number
        return None

    def school_data_gender_type(self, value):
        return self.school_normalize_gender_type_filter(value, "Coeducational")

    def school_data_year_pattern(self, minimum, maximum, levels):
        if not levels:
            return "Unknown"
        if minimum in {0, 1} and maximum == 12:
            return "AllYears"
        if maximum <= 6:
            return "PrimaryOnly"
        if minimum in {7, 8, 9, 10, 11} and maximum == 12:
            return f"Year{minimum}Plus"
        return "Custom"

    def school_data_parse_year_levels(self, raw):
        text = re.sub(r"\s+", " ", str(raw or "").strip())
        if not text:
            return {"raw": "", "min_level": "Unknown", "max_level": "Unknown", "levels": [], "pattern": "Unknown", "review_required": True, "error": "Year Levels 为空"}
        normalized = text.replace("–", "-").replace("—", "-")
        normalized_key = self.school_data_header_key(normalized)
        if normalized_key in {"primaryonly", "primary", "primaryschool", "primaryschools", "xiaoxue"} or normalized in {"小学", "小學"}:
            levels = self.school_levels_for_pattern("PrimaryOnly")
            return {
                "raw": text,
                "min_level": "Year 1",
                "max_level": "Year 6",
                "levels": levels,
                "pattern": "PrimaryOnly",
                "review_required": False,
                "error": "",
            }
        if (
            normalized_key in {"secondary", "secondaryschool", "secondaryschools", "highschool", "highschools", "zhongxue"}
            or "secondary" in normalized_key
            or normalized in {"中学", "中學"}
        ):
            levels = self.school_levels_for_pattern("Year7Plus")
            return {
                "raw": text,
                "min_level": "Year 7",
                "max_level": "Year 12",
                "levels": levels,
                "pattern": "Year7Plus",
                "review_required": False,
                "error": "",
            }
        values = []
        range_match = re.search(r"\b(K|P|Prep|Foundation|Kindergarten|\d{1,2})\s*-\s*(K|P|Prep|Foundation|Kindergarten|\d{1,2})\b", normalized, flags=re.I)
        if range_match:
            start = self.school_data_level_number(range_match.group(1))
            end = self.school_data_level_number(range_match.group(2))
            if start is not None and end is not None and start <= end:
                values = list(range(start, end + 1))
        if not values:
            tokens = re.findall(r"\b(?:K|P|Prep|Foundation|Kindergarten|\d{1,2})\b", normalized, flags=re.I)
            parsed = []
            for token in tokens:
                number = self.school_data_level_number(token)
                if number is not None and number not in parsed:
                    parsed.append(number)
            if len(parsed) >= 1:
                values = sorted(parsed)
        values = [value for value in values if 0 <= value <= 12]
        if not values:
            return {"raw": text, "min_level": "Unknown", "max_level": "Unknown", "levels": [], "pattern": "Unknown", "review_required": True, "error": "Year Levels 无法解析"}
        levels = [self.school_data_level_label(value) for value in values]
        return {
            "raw": text,
            "min_level": self.school_data_level_label(min(values)),
            "max_level": self.school_data_level_label(max(values)),
            "levels": levels,
            "pattern": self.school_data_year_pattern(min(values), max(values), levels),
            "review_required": False,
            "error": "",
        }

    def school_data_parse_year_bounds(self, min_level, max_level, fallback_raw=""):
        fallback_key = self.school_data_header_key(fallback_raw)
        if fallback_key in {"primaryonly", "primary", "primaryschool", "primaryschools", "xiaoxue"} or str(fallback_raw or "").strip() in {"小学", "小學"}:
            return self.school_data_parse_year_levels(fallback_raw)
        minimum = self.school_data_level_number(min_level)
        maximum = self.school_data_level_number(max_level)
        if minimum is None or maximum is None or minimum > maximum:
            return self.school_data_parse_year_levels(fallback_raw)
        values = list(range(minimum, maximum + 1))
        levels = [self.school_data_level_label(value) for value in values]
        raw = str(fallback_raw or "").strip() or f"{min_level}-{max_level}"
        return {
            "raw": raw,
            "min_level": self.school_data_level_label(minimum),
            "max_level": self.school_data_level_label(maximum),
            "levels": levels,
            "pattern": self.school_data_year_pattern(minimum, maximum, levels),
            "review_required": False,
            "error": "",
        }

    def school_data_rows_from_table(self, rows):
        rows = [[re.sub(r"\s+", " ", str(cell or "")).strip() for cell in row] for row in rows]
        rows = [[cell for cell in row] for row in rows if any(cell for cell in row)]
        if not rows:
            return []
        header_index = None
        for index, cells in enumerate(rows[:12]):
            mapping = self.school_data_column_map(cells)
            if "school_name" in mapping or ("campus_locations" in mapping and "year_levels" in mapping):
                header_index = index
                break
        if header_index is None:
            return []
        headers = rows[header_index]
        parsed = []
        for values in rows[header_index + 1:]:
            if not any(values):
                continue
            parsed.append({headers[i] if i < len(headers) and headers[i] else f"Column {i + 1}": values[i] if i < len(values) else "" for i in range(max(len(headers), len(values)))})
        return parsed

    def school_data_parse_text_rows(self, text):
        lines = [re.sub(r"\s+", " ", line).strip(" \t\r\n|") for line in str(text or "").splitlines()]
        lines = [line for line in lines if line]
        table_rows = []
        for line in lines:
            if "|" in line:
                cells = [cell.strip() for cell in line.split("|")]
            elif "\t" in line:
                cells = [cell.strip() for cell in line.split("\t")]
            elif re.search(r"\s{2,}", line):
                cells = [cell.strip() for cell in re.split(r"\s{2,}", line)]
            else:
                cells = [line]
            table_rows.append(cells)
        return self.school_data_rows_from_table(table_rows)

    def school_data_parse_csv(self, upload):
        text = upload.data.decode("utf-8-sig", errors="replace")
        sample = text[:4096]
        try:
            dialect = csv.Sniffer().sniff(sample)
        except csv.Error:
            dialect = csv.excel
        return [dict(row) for row in csv.DictReader(io.StringIO(text), dialect=dialect)]

    def school_data_parse_excel_workbook(self, data):
        wb = load_workbook(io.BytesIO(data), data_only=True, read_only=True)
        preferred_names = ["CRM_Import", "School_Level"]
        sheets = [wb[name] for name in preferred_names if name in wb.sheetnames]
        sheets.extend(ws for ws in wb.worksheets if ws.title not in preferred_names)
        for ws in sheets[:5]:
            parsed = self.school_data_rows_from_table(list(ws.iter_rows(values_only=True)))
            if parsed:
                return parsed
        return []

    def school_data_convert_xls_to_xlsx(self, upload):
        soffice = shutil.which("soffice")
        bundled = Path.home() / ".cache/codex-runtimes/codex-primary-runtime/dependencies/bin/soffice"
        if not soffice and bundled.exists():
            soffice = str(bundled)
        if not soffice:
            raise ValueError("旧版 Excel .xls 无法自动转换：未找到 soffice。")
        temp_root = APP_DIR / "cache" / "school_data_import_work" / datetime.now().strftime("%Y%m%d_%H%M%S_%f")
        temp_root.mkdir(parents=True, exist_ok=True)
        source = temp_root / (sanitize_component(Path(upload.filename or "schools.xls").name) or "schools.xls")
        source.write_bytes(upload.data)
        result = subprocess.run(
            [soffice, "--headless", "--convert-to", "xlsx", "--outdir", str(temp_root), str(source)],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            timeout=45,
            check=False,
        )
        converted = source.with_suffix(".xlsx")
        if result.returncode != 0 or not converted.exists():
            raise ValueError(f"旧版 Excel .xls 转换失败：{(result.stderr or result.stdout or '').strip()}")
        return converted.read_bytes()

    def school_data_parse_excel(self, upload):
        suffix = Path(upload.filename or "").suffix.lower()
        if suffix == ".xls":
            try:
                return self.school_data_parse_excel_workbook(self.school_data_convert_xls_to_xlsx(upload))
            except Exception as exc:
                return [{"_parse_error": f"旧版 Excel .xls 已支持上传，但当前转换依赖不可用，无法自动解析：{exc}", "_raw_text": ""}]
        return self.school_data_parse_excel_workbook(upload.data)

    def school_data_parse_pdf(self, upload):
        parsed = []
        try:
            import pdfplumber
        except Exception:
            parsed = []
        else:
            with pdfplumber.open(io.BytesIO(upload.data)) as pdf:
                for page_obj in pdf.pages[:12]:
                    for table in page_obj.extract_tables() or []:
                        parsed.extend(self.school_data_rows_from_table(table))
        if parsed:
            return parsed
        text = extract_uploaded_text(upload)
        rows = self.school_data_parse_text_rows(text)
        if rows:
            return rows
        return [{"_parse_error": "PDF 未读取到可识别学校数据；如果是扫描件，OCR 未能识别出表格内容。", "_raw_text": text or ""}]

    def school_data_parse_word(self, upload):
        suffix = Path(upload.filename or "").suffix.lower()
        if suffix == ".docx":
            try:
                document = Document(io.BytesIO(upload.data))
                parsed = []
                for table in document.tables:
                    parsed.extend(self.school_data_rows_from_table([[cell.text for cell in row.cells] for row in table.rows]))
                if parsed:
                    return parsed
                parts = [paragraph.text.strip() for paragraph in document.paragraphs if paragraph.text.strip()]
                return self.school_data_parse_text_rows("\n".join(parts))
            except Exception as exc:
                raise ValueError(f"Word 文件无法读取：{exc}") from exc
        temp_root = APP_DIR / "cache" / "school_data_import_work" / datetime.now().strftime("%Y%m%d_%H%M%S_%f")
        temp_root.mkdir(parents=True, exist_ok=True)
        source = temp_root / (sanitize_component(Path(upload.filename or "schools.doc").name) or "schools.doc")
        source.write_bytes(upload.data)
        result = subprocess.run(
            ["/usr/bin/textutil", "-convert", "txt", "-stdout", str(source)],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            timeout=30,
            check=False,
        )
        if result.returncode != 0 or not result.stdout.strip():
            return [{"_parse_error": "旧版 Word .doc 未能自动读取，请人工确认或另存为 .docx。", "_raw_text": result.stderr or ""}]
        rows = self.school_data_parse_text_rows(result.stdout)
        return rows or [{"_parse_error": "旧版 Word .doc 已读取文本，但未识别到学校数据表头。", "_raw_text": result.stdout[:4000]}]

    def school_data_parse_image(self, upload):
        text = extract_uploaded_text(upload)
        rows = self.school_data_parse_text_rows(text)
        if rows:
            return rows
        return [{"_parse_error": "图片已上传，但 OCR 未读取到可识别学校数据。", "_raw_text": text or ""}]

    def school_data_parse_upload(self, upload):
        suffix = Path(upload.filename or "").suffix.lower()
        if suffix == ".csv":
            return self.school_data_parse_csv(upload)
        if suffix in {".xlsx", ".xlsm", ".xls"}:
            return self.school_data_parse_excel(upload)
        if suffix == ".pdf":
            return self.school_data_parse_pdf(upload)
        if suffix in {".docx", ".doc"}:
            return self.school_data_parse_word(upload)
        if suffix in {".jpg", ".jpeg", ".png", ".webp"} or str(upload.content_type or "").startswith("image/"):
            return self.school_data_parse_image(upload)
        raise ValueError("学校数据导入仅支持 Word、PDF、图片、CSV、Excel。")

    def school_data_canonical_row(self, row, source_state, source_file="", source_sector=""):
        mapping = self.school_data_column_map(row.keys())
        state = str(source_state or "").strip().upper()
        sector_key = self.school_data_import_sector_key(source_sector or row.get("_source_sector", ""), "public")
        school_name = self.school_data_mapped_value(row, mapping, "school_name", "School Name")
        campus_locations = self.school_data_mapped_value(row, mapping, "campus_locations", "Address")
        suburb = self.school_data_mapped_value(row, mapping, "suburb", "Suburb")
        postcode = self.school_data_mapped_value(row, mapping, "postcode", "Postcode")
        address_parts = self.school_data_address_parts(campus_locations, state, suburb, postcode)
        campus_locations = address_parts["address"]
        suburb = address_parts["suburb"]
        postcode = address_parts["postcode"]
        website_url = self.school_data_mapped_value(row, mapping, "website_url", "Website")
        region = self.school_data_mapped_value(row, mapping, "region", "REGION")
        gender_type = self.school_data_gender_type(self.school_data_mapped_value(row, mapping, "gender_type", "Gender"))
        year_levels_raw = self.school_data_mapped_value(row, mapping, "year_levels", "Year Levels")
        min_level_raw = self.school_data_mapped_value(row, mapping, "min_level", "Min Level")
        max_level_raw = self.school_data_mapped_value(row, mapping, "max_level", "Max Level")
        parse_error = str(row.get("_parse_error", "") or "").strip()
        parsed_levels = self.school_data_parse_year_bounds(min_level_raw, max_level_raw, year_levels_raw) if (min_level_raw or max_level_raw) else self.school_data_parse_year_levels(year_levels_raw)
        year_levels_raw = parsed_levels["raw"]
        errors = []
        if parse_error:
            errors.append(parse_error)
        if not school_name:
            errors.append("学校名为空或未识别")
        if not campus_locations:
            errors.append("Campus location/s 为空或未识别")
        if parsed_levels["review_required"]:
            errors.append(parsed_levels["error"])
        status = "Error" if parse_error and not school_name else ("Needs Review" if errors else "Importable")
        confidence = 0.95 if status == "Importable" else (0.45 if school_name else 0.1)
        raw_payload = dict(row)
        raw_payload["_source_sector"] = sector_key
        return {
            "source_state": state,
            "source_sector": sector_key,
            "school_name_raw": school_name,
            "school_name": school_name,
            "school_name_normalized": self.school_data_header_key(school_name),
            "campus_locations": campus_locations,
            "region": region,
            "suburb": suburb,
            "postcode": postcode,
            "gender_type": gender_type,
            "website_url": website_url,
            "year_levels_raw": year_levels_raw,
            "year_level_min": parsed_levels["min_level"],
            "year_level_max": parsed_levels["max_level"],
            "year_levels": parsed_levels["levels"],
            "year_level_pattern": parsed_levels["pattern"],
            "status": status,
            "review_required": 0 if status == "Importable" else 1,
            "error_reason": "; ".join(error for error in errors if error),
            "confidence_score": confidence,
            "source_file": source_file,
            "raw": raw_payload,
        }

    def school_data_match_candidates(self, state):
        school_filter = " AND deleted_at IS NULL" if self.school_deleted_filter_sql() else ""
        candidates = db.all(
            f"SELECT id,school_name,state,address,suburb,postcode,website_url FROM schools WHERE UPPER(COALESCE(state,''))=?{school_filter}",
            (str(state or "").strip().upper(),),
        )
        prepared = []
        for row in candidates:
            website_value = str(row["website_url"] or "")
            prepared.append({
                "id": row["id"],
                "school_name": row["school_name"],
                "state": row["state"],
                "address": row["address"],
                "suburb": row["suburb"],
                "postcode": row["postcode"],
                "website_url": row["website_url"],
                "_normalized_name": self.school_data_header_key(row["school_name"]),
                "_website_key": self.school_data_header_key(urlparse(website_value).netloc or website_value),
            })
        return prepared

    def school_data_fuzzy_location_matches(self, campus_locations, state, candidate):
        campus_text = str(campus_locations or "").strip()
        if not campus_text:
            return False
        candidate_address = str(candidate.get("address") if isinstance(candidate, dict) else candidate["address"] or "").strip()
        candidate_suburb = str(candidate.get("suburb") if isinstance(candidate, dict) else candidate["suburb"] or "").strip()
        candidate_postcode = str(candidate.get("postcode") if isinstance(candidate, dict) else candidate["postcode"] or "").strip()
        source_parts = self.school_data_address_parts(campus_text, state)
        candidate_parts = self.school_data_address_parts(candidate_address, state, candidate_suburb, candidate_postcode)
        if source_parts["postcode"] and candidate_parts["postcode"]:
            return source_parts["postcode"] == candidate_parts["postcode"]
        source_suburb = self.school_data_header_key(source_parts["suburb"])
        target_suburb = self.school_data_header_key(candidate_parts["suburb"])
        if source_suburb and target_suburb:
            return source_suburb == target_suburb
        return False

    def school_data_match_school(self, school_name, state, campus_locations="", website_url="", candidates=None):
        normalized_name = self.school_data_header_key(school_name)
        if not normalized_name:
            return None, "", 0.0, "Unmatched"
        candidates = candidates if candidates is not None else self.school_data_match_candidates(state)
        exact = [row for row in candidates if (row.get("_normalized_name") if isinstance(row, dict) else self.school_data_header_key(row["school_name"])) == normalized_name]
        if len(exact) == 1:
            return exact[0]["id"], exact[0]["school_name"], 0.98, "Existing"
        if len(exact) > 1:
            return None, "", 0.55, "Possible Match"
        website_key = self.school_data_header_key(urlparse(str(website_url or "")).netloc or website_url)
        if website_key:
            website_matches = [row for row in candidates if website_key and website_key == (row.get("_website_key") if isinstance(row, dict) else self.school_data_header_key(urlparse(str(row["website_url"] or "")).netloc or row["website_url"]))]
            if len(website_matches) == 1:
                return website_matches[0]["id"], website_matches[0]["school_name"], 0.86, "Existing"
        possible = []
        for row in candidates:
            candidate_name = row.get("_normalized_name") if isinstance(row, dict) else self.school_data_header_key(row["school_name"])
            ratio = SequenceMatcher(None, normalized_name, candidate_name).ratio()
            if ratio >= 0.88 and self.school_data_fuzzy_location_matches(campus_locations, state, row):
                possible.append((ratio, row))
        if len(possible) == 1:
            ratio, row = possible[0]
            return row["id"], row["school_name"], round(ratio, 2), "Possible Match"
        if len(possible) > 1:
            return None, "", round(max(score for score, _row in possible), 2), "Possible Match"
        return None, "", 0.9, "New"

    def school_data_batch_counts(self, batch_id):
        rows = db.all("SELECT import_status,match_status,review_required FROM school_data_import_rows WHERE batch_id=?", (batch_id,))
        processed_statuses = {"Imported", "Merged", "Skipped"}
        active_rows = [row for row in rows if row["import_status"] not in processed_statuses]
        return {
            "total_rows": len(rows),
            "importable_rows": sum(1 for row in active_rows if row["import_status"] in {"Importable", "Existing"}),
            "existing_rows": sum(1 for row in active_rows if row["match_status"] == "Existing"),
            "new_rows": sum(1 for row in active_rows if row["match_status"] == "New"),
            "review_required_rows": sum(1 for row in active_rows if row["review_required"]),
            "error_rows": sum(1 for row in active_rows if row["import_status"] == "Error"),
            "imported_rows": sum(1 for row in rows if row["import_status"] in {"Imported", "Merged"}),
            "skipped_rows": sum(1 for row in rows if row["import_status"] == "Skipped"),
        }

    def school_data_update_batch_counts(self, batch_id):
        counts = self.school_data_batch_counts(batch_id)
        status = "Imported" if counts["total_rows"] and counts["imported_rows"] + counts["skipped_rows"] == counts["total_rows"] else ("Needs Confirmation" if counts["total_rows"] else "Uploaded")
        review_status = "Confirmed" if status == "Imported" else "Needs Review"
        db.execute(
            """UPDATE school_data_import_batches
               SET total_rows=?,importable_rows=?,existing_rows=?,new_rows=?,review_required_rows=?,error_rows=?,imported_rows=?,skipped_rows=?,import_status=?,review_status=?,updated_at=?
               WHERE id=?""",
            (counts["total_rows"], counts["importable_rows"], counts["existing_rows"], counts["new_rows"], counts["review_required_rows"], counts["error_rows"], counts["imported_rows"], counts["skipped_rows"], status, review_status, now_iso(), batch_id),
        )
        return counts

    def school_data_auto_import_clean_rows(self, batch_id):
        batch = db.one("SELECT * FROM school_data_import_batches WHERE id=?", (batch_id,))
        if not batch:
            raise ValueError("学校数据导入批次不存在")
        rows = db.all(
            """SELECT id
               FROM school_data_import_rows
               WHERE batch_id=?
                 AND import_status IN ('Importable','Existing')
                 AND COALESCE(review_required,0)=0
                 AND COALESCE(error_reason,'')='' 
               ORDER BY row_number,id""",
            (batch_id,),
        )
        imported = 0
        failed = 0
        match_cache = {}
        for row in rows:
            try:
                result = self.school_data_apply_row(row["id"], None, batch=batch, match_cache=match_cache, update_batch_counts=False, audit_row=False)
                imported += 1 if result == "Imported" else 0
            except Exception as exc:
                failed += 1
                db.execute(
                    "UPDATE school_data_import_rows SET import_status='Error',review_required=1,error_reason=?,updated_at=? WHERE id=?",
                    (str(exc), now_iso(), row["id"]),
                )
        counts = self.school_data_update_batch_counts(batch_id)
        summary = {
            "attempted": len(rows),
            "imported": imported,
            "failed": failed,
            "remaining_review": counts["review_required_rows"],
            "remaining_error": counts["error_rows"],
            **counts,
        }
        db.audit(
            self.user if getattr(self, "user", None) and "username" in self.user else None,
            "school_data_import_clean_rows_auto_imported",
            "school_library",
            record_id=batch_id,
            new_value=json.dumps(summary, ensure_ascii=False),
            ip=getattr(self, "client_address", [""])[0] if getattr(self, "client_address", None) else "",
            device=getattr(self, "headers", {}).get("User-Agent") if getattr(self, "headers", None) else "",
        )
        return summary

    def school_data_clear_batch_rows(self, batch_id):
        batch = db.one("SELECT * FROM school_data_import_batches WHERE id=?", (batch_id,))
        if not batch:
            raise ValueError("学校数据导入批次不存在")
        rows_deleted = db.one("SELECT COUNT(*) count FROM school_data_import_rows WHERE batch_id=?", (batch_id,))["count"]
        db.execute("DELETE FROM school_data_import_rows WHERE batch_id=?", (batch_id,))
        report = {
            "cleared_at": now_iso(),
            "cleared_by": self.user["id"] if getattr(self, "user", None) and "id" in self.user else None,
            "rows_deleted": rows_deleted,
            "stored_file_path": batch["stored_file_path"],
        }
        db.execute(
            """UPDATE school_data_import_batches
               SET total_rows=0,importable_rows=0,existing_rows=0,new_rows=0,review_required_rows=0,error_rows=0,
                   imported_rows=0,skipped_rows=0,import_status='Uploaded',review_status='Needs Review',report_json=?,updated_at=?
               WHERE id=?""",
            (json.dumps(report, ensure_ascii=False), now_iso(), batch_id),
        )
        db.audit(
            self.user if getattr(self, "user", None) and "username" in self.user else None,
            "school_data_import_rows_cleared",
            "school_library",
            record_id=batch_id,
            new_value=json.dumps(report, ensure_ascii=False),
            ip=getattr(self, "client_address", [""])[0] if getattr(self, "client_address", None) else "",
            device=getattr(self, "headers", {}).get("User-Agent") if getattr(self, "headers", None) else "",
        )
        return rows_deleted

    def school_data_delete_batch(self, batch_id):
        batch = db.one("SELECT * FROM school_data_import_batches WHERE id=?", (batch_id,))
        if not batch:
            raise ValueError("学校数据导入批次不存在")
        rows_deleted = db.one("SELECT COUNT(*) count FROM school_data_import_rows WHERE batch_id=?", (batch_id,))["count"]
        file_deleted = False
        file_error = ""
        stored_path = str(batch["stored_file_path"] or "").strip()
        if stored_path:
            try:
                target = ensure_within(Path(stored_path), SCHOOL_DATA_IMPORT_DIR)
                if target.is_file():
                    target.unlink()
                    file_deleted = True
            except Exception as exc:
                file_error = str(exc)
        db.execute("DELETE FROM school_data_import_rows WHERE batch_id=?", (batch_id,))
        db.execute("DELETE FROM school_data_import_batches WHERE id=?", (batch_id,))
        result = {
            "batch_id": batch_id,
            "rows_deleted": rows_deleted,
            "file_deleted": file_deleted,
            "file_error": file_error,
            "original_filename": batch["original_filename"],
        }
        db.audit(
            self.user if getattr(self, "user", None) and "username" in self.user else None,
            "school_data_import_batch_deleted",
            "school_library",
            record_id=batch_id,
            file_path=stored_path,
            new_value=json.dumps(result, ensure_ascii=False),
            ip=getattr(self, "client_address", [""])[0] if getattr(self, "client_address", None) else "",
            device=getattr(self, "headers", {}).get("User-Agent") if getattr(self, "headers", None) else "",
        )
        return result

    def school_data_insert_preview_rows(self, batch_id, canonical_rows):
        now = now_iso()
        match_cache = {}
        insert_values = []
        for index, row in enumerate(canonical_rows, start=1):
            cache_key = str(row["source_state"] or "").strip().upper()
            candidates = match_cache.setdefault(cache_key, self.school_data_match_candidates(cache_key))
            school_id, school_name, match_confidence, match_status = self.school_data_match_school(row["school_name"], row["source_state"], row["campus_locations"], row["website_url"], candidates)
            import_status = row["status"]
            review_required = row["review_required"]
            if import_status == "Importable" and match_status == "Existing":
                import_status = "Existing"
            if match_status == "Possible Match":
                import_status = "Needs Review"
                review_required = 1
            insert_values.append((
                batch_id, index, row["source_state"], row["school_name_raw"], row["school_name"], row["school_name_normalized"],
                row["campus_locations"], row.get("region", ""), row["website_url"], row["year_levels_raw"], row["year_level_min"], row["year_level_max"],
                json.dumps(row["year_levels"], ensure_ascii=False), school_id, school_name, max(row["confidence_score"], match_confidence),
                match_status, import_status, "Needs Review", review_required, row["error_reason"], json.dumps(row["raw"], ensure_ascii=False), now, now,
            ))
        with db.transaction() as conn:
            conn.executemany(
                """INSERT INTO school_data_import_rows(batch_id,row_number,source_state,school_name_raw,school_name,school_name_normalized,campus_locations_raw,region_raw,website_raw,year_levels_raw,year_level_min,year_level_max,year_levels_list_json,suggested_school_id,suggested_school_name,confidence_score,match_status,import_status,review_status,review_required,error_reason,raw_row_json,created_at,updated_at)
                   VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                insert_values,
            )
        return self.school_data_update_batch_counts(batch_id)

    def school_data_form_value(self, form, key, default=""):
        value = form.get(key, default) if form else default
        if isinstance(value, list):
            value = value[-1] if value else default
        return str(value if value is not None else default).strip()

    def school_data_row_raw(self, row):
        try:
            payload = json.loads(row["raw_row_json"] or "{}")
        except Exception:
            payload = {}
        return payload if isinstance(payload, dict) else {}

    def school_data_apply_row(self, row_id, form=None, batch=None, match_cache=None, update_batch_counts=True, audit_row=True):
        row = db.one("SELECT * FROM school_data_import_rows WHERE id=?", (row_id,))
        if not row:
            raise ValueError("学校导入行不存在")
        batch = batch or db.one("SELECT * FROM school_data_import_batches WHERE id=?", (row["batch_id"],))
        if not batch:
            raise ValueError("学校导入批次不存在")
        school_name = self.school_data_form_value(form, f"school_name_{row_id}", row["school_name"] or row["school_name_raw"] or "")
        source_state = self.school_data_form_value(form, f"source_state_{row_id}", row["source_state"] or batch["source_state"]).upper()
        campus_locations = self.school_data_form_value(form, f"campus_locations_{row_id}", row["campus_locations_raw"] or "")
        raw_payload = self.school_data_row_raw(row)
        raw_mapping = self.school_data_column_map(raw_payload.keys())
        source_sector = self.school_data_import_sector_key(self.school_data_form_value(form, f"source_sector_{row_id}", raw_payload.get("_source_sector", "")), "public")
        school_type_value = self.school_data_import_sector_type(source_sector)
        raw_suburb = self.school_data_mapped_value(raw_payload, raw_mapping, "suburb", "Suburb")
        raw_postcode = self.school_data_mapped_value(raw_payload, raw_mapping, "postcode", "Postcode")
        raw_region = self.school_data_mapped_value(raw_payload, raw_mapping, "region", "REGION")
        raw_gender = self.school_data_mapped_value(raw_payload, raw_mapping, "gender_type", "Gender")
        raw_accommodation = self.school_data_mapped_value(raw_payload, raw_mapping, "accommodation_type")
        address_parts = self.school_data_address_parts(campus_locations, source_state, raw_suburb, raw_postcode)
        region = self.school_data_form_value(form, f"region_{row_id}", row["region_raw"] or raw_region)
        suburb = self.school_data_form_value(form, f"suburb_{row_id}", address_parts["suburb"])
        postcode = self.school_data_form_value(form, f"postcode_{row_id}", address_parts["postcode"])
        gender_type = self.school_data_gender_type(raw_gender)
        website_url = self.school_data_form_value(form, f"website_{row_id}", row["website_raw"] or "")
        year_levels_raw = self.school_data_form_value(form, f"year_levels_{row_id}", row["year_levels_raw"] or "")
        selected_school_id = self.school_data_form_value(form, f"school_id_{row_id}", row["suggested_school_id"] or "")
        notes = self.school_data_form_value(form, f"notes_{row_id}", row["notes"] or "")
        if source_state not in SCHOOL_DATA_IMPORT_STATES:
            source_state = batch["source_state"]
        address_parts = self.school_data_address_parts(campus_locations, source_state, suburb, postcode)
        campus_locations = address_parts["address"]
        suburb = address_parts["suburb"]
        postcode = address_parts["postcode"]
        parsed_levels = self.school_data_parse_year_levels(year_levels_raw)
        if not school_name:
            db.execute("UPDATE school_data_import_rows SET import_status='Needs Review',review_required=1,error_reason=?,updated_at=? WHERE id=?", ("学校名为空，不能导入", now_iso(), row_id))
            return "Needs Review"
        now = now_iso()
        city_id = self.school_default_city_id_for_state(source_state)
        school = db.one("SELECT * FROM schools WHERE id=?", (selected_school_id,)) if selected_school_id else None
        if not school:
            candidates = None
            if match_cache is not None:
                cache_key = str(source_state or "").strip().upper()
                candidates = match_cache.setdefault(cache_key, self.school_data_match_candidates(cache_key))
            school_id, _suggested_name, _confidence, match_status = self.school_data_match_school(school_name, source_state, campus_locations, website_url, candidates)
            school = db.one("SELECT * FROM schools WHERE id=?", (school_id,)) if school_id else None
        else:
            match_status = "Existing"
        year_levels_json = json.dumps(parsed_levels["levels"], ensure_ascii=False)
        accommodation_type = self.school_data_accommodation_type_from_source(raw_accommodation, parsed_levels["pattern"], "", source_sector, school_type_value)
        if school:
            updates = []
            params = []
            def set_if_empty(column, value):
                if value and not str(school[column] or "").strip():
                    updates.append(f"{column}=?")
                    params.append(value)
            if city_id and self.school_needs_city_state_update(school, source_state):
                updates.append("city_id=?")
                params.append(city_id)
            set_if_empty("address", campus_locations)
            set_if_empty("region", region)
            set_if_empty("suburb", suburb)
            set_if_empty("postcode", postcode)
            set_if_empty("website_url", website_url)
            set_if_empty("year_levels", year_levels_raw)
            if str(school["sector_key"] or "").strip() in {"", "unknown"}:
                updates.append("sector_key=?")
                params.append(source_sector)
            if str(school["school_type"] or "").strip() in {"", "Unknown"}:
                updates.append("school_type=?")
                params.append(school_type_value)
            if parsed_levels["levels"]:
                if str(school["international_year_level_min"] or "Unknown") in {"", "Unknown"}:
                    updates.append("international_year_level_min=?")
                    params.append(parsed_levels["min_level"])
                if str(school["international_year_level_max"] or "Unknown") in {"", "Unknown"}:
                    updates.append("international_year_level_max=?")
                    params.append(parsed_levels["max_level"])
                existing_levels = self.school_multi_values(school["accepted_international_year_levels"] if "accepted_international_year_levels" in school.keys() else "[]")
                if not existing_levels:
                    updates.append("accepted_international_year_levels=?")
                    params.append(year_levels_json)
                if str(school["accepted_international_year_level_pattern"] or "Unknown") in {"", "Unknown"}:
                    updates.append("accepted_international_year_level_pattern=?")
                    params.append(parsed_levels["pattern"])
                if parsed_levels["pattern"] == "PrimaryOnly" and str(school["accommodation_type"] or "") != "ParentOrGuardianOnly":
                    updates.append("accommodation_type=?")
                    params.append("ParentOrGuardianOnly")
                elif self.school_is_public_sector_value(source_sector, school_type_value) and str(school["accommodation_type"] or "") != "HomestayAndParentGuardian":
                    updates.append("accommodation_type=?")
                    params.append("HomestayAndParentGuardian")
                elif str(school["accommodation_type"] or "Unknown") in {"", "Unknown"} and accommodation_type != "Unknown":
                    updates.append("accommodation_type=?")
                    params.append(accommodation_type)
            updates.extend(["state=?", "source_file=?", "extracted_at=?", "last_updated_by=?", "last_updated_at=?", "updated_at=?"])
            params.extend([source_state or school["state"], batch["stored_file_path"], now, self.user["id"] if getattr(self, "user", None) else None, now, now, school["id"]])
            db.execute(f"UPDATE schools SET {','.join(updates)} WHERE id=?", tuple(params))
            final_school_id = school["id"]
            final_status = "Merged" if selected_school_id else "Imported"
        else:
            final_school_id = db.execute(
                """INSERT INTO schools(school_name,city_id,state,sector_key,school_type,address,region,suburb,postcode,website_url,year_levels,international_year_level_min,international_year_level_max,accepted_international_year_levels,accepted_international_year_level_pattern,accommodation_type,school_gender_type,source_file,extracted_at,created_at,updated_at,last_updated_by,last_updated_at,data_quality_status)
                   VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                (
                    school_name, city_id, source_state, source_sector, school_type_value, campus_locations, region, suburb, postcode, website_url, year_levels_raw,
                    parsed_levels["min_level"], parsed_levels["max_level"], year_levels_json, parsed_levels["pattern"], accommodation_type, gender_type,
                    batch["stored_file_path"], now, now, now, self.user["id"] if getattr(self, "user", None) else None, now, "Needs Review",
                ),
            )
            if match_cache is not None:
                cache_key = str(source_state or "").strip().upper()
                website_key = self.school_data_header_key(urlparse(str(website_url or "")).netloc or website_url)
                match_cache.setdefault(cache_key, []).append({
                    "id": final_school_id,
                    "school_name": school_name,
                    "state": source_state,
                    "address": campus_locations,
                    "website_url": website_url,
                    "_normalized_name": self.school_data_header_key(school_name),
                    "_website_key": website_key,
                })
            match_status = "New"
            final_status = "Imported"
        review_required = 1 if parsed_levels["review_required"] or not campus_locations else 0
        error_reason = parsed_levels["error"] if parsed_levels["review_required"] else ("" if campus_locations else "Campus location/s 为空或未识别")
        db.execute(
            """UPDATE school_data_import_rows
               SET source_state=?,school_name=?,school_name_raw=?,school_name_normalized=?,campus_locations_raw=?,region_raw=?,website_raw=?,year_levels_raw=?,year_level_min=?,year_level_max=?,year_levels_list_json=?,suggested_school_id=?,suggested_school_name=?,match_status=?,import_status=?,review_status='Confirmed',review_required=?,error_reason=?,edited_row_json=?,final_school_id=?,reviewed_by=?,reviewed_at=?,imported_by=?,imported_at=?,notes=?,updated_at=?
               WHERE id=?""",
            (
                source_state, school_name, school_name, self.school_data_header_key(school_name), campus_locations, region, website_url, year_levels_raw,
                parsed_levels["min_level"], parsed_levels["max_level"], year_levels_json, final_school_id, school_name,
                match_status, final_status, review_required, error_reason,
                json.dumps({"school_name": school_name, "state": source_state, "source_sector": source_sector, "school_type": school_type_value, "campus_locations": campus_locations, "region": region, "suburb": suburb, "postcode": postcode, "gender_type": gender_type, "website_url": website_url, "year_levels": year_levels_raw}, ensure_ascii=False),
                final_school_id, self.user["id"] if getattr(self, "user", None) else None, now, self.user["id"] if getattr(self, "user", None) else None, now, notes, now, row_id,
            ),
        )
        if update_batch_counts:
            self.school_data_update_batch_counts(row["batch_id"])
        if audit_row:
            audit_user = self.user if getattr(self, "user", None) and "username" in self.user else None
            db.audit(audit_user, "school_data_import_row_confirmed", "school_library", record_id=row_id, new_value=json.dumps({"school_id": final_school_id, "school_name": school_name}, ensure_ascii=False), ip=getattr(self, "client_address", [""])[0] if getattr(self, "client_address", None) else "", device=getattr(self, "headers", {}).get("User-Agent") if getattr(self, "headers", None) else "")
        return "Imported"

    def school_data_upload(self, method):
        if method != "POST":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        if not (can_school_action(self.user, "upload_ranking_source") and can_school_action(self.user, "import_rankings")):
            db.audit(self.user, "school_data_import_access_denied", "school_library", record_id="upload_school_data", ip=self.client_address[0], device=self.headers.get("User-Agent"), status="denied", error_message="missing school data import permission")
            return self.school_action_denied("upload_school_data")
        source_state = str(self.form.get("source_state", "")).strip().upper()
        if source_state not in SCHOOL_DATA_IMPORT_STATES:
            return self.flash_redirect("/schools/rankings", "请选择有效 State 后再上传学校数据。", "error")
        source_sector = self.school_data_import_sector_key(self.form.get("source_sector", ""), "")
        if source_sector not in {"public", "private"}:
            return self.flash_redirect("/schools/rankings", "请选择公立 / 私立后再上传学校数据。", "error")
        upload = next((f for f in self.files if f.field_name == "school_data_file" and f.filename), None)
        if not upload:
            return self.flash_redirect("/schools/rankings", "请选择学校数据文件。", "error")
        suffix = Path(upload.filename or "").suffix.lower()
        folder = SCHOOL_DATA_IMPORT_DIR / date.today().strftime("%Y%m%d")
        folder.mkdir(parents=True, exist_ok=True)
        stored_path, _ = next_version_path(folder, upload.filename)
        stored_path.write_bytes(upload.data)
        notes = str(self.form.get("notes", "")).strip()
        now = now_iso()
        batch_id = db.execute(
            """INSERT INTO school_data_import_batches(source_name,original_filename,stored_file_path,source_state,file_type,total_rows,import_status,review_status,imported_by,imported_at,updated_at,notes)
               VALUES(?,?,?,?,?,?,?,?,?,?,?,?)""",
            (SCHOOL_DATA_IMPORT_SOURCE_NAME, upload.filename, str(stored_path), source_state, suffix, 0, "Uploaded", "Needs Review", self.user["id"], now, now, notes),
        )
        try:
            raw_rows = self.school_data_parse_upload(upload)
            canonical_rows = [self.school_data_canonical_row(row, source_state, upload.filename, source_sector) for row in raw_rows]
            if not canonical_rows:
                canonical_rows = [self.school_data_canonical_row({"_parse_error": "未找到可识别学校数据行。请确认文件包含学校名称、Campus location/s、Year Levels、Website 等表头。"}, source_state, upload.filename, source_sector)]
            counts = self.school_data_insert_preview_rows(batch_id, canonical_rows)
            auto_summary = self.school_data_auto_import_clean_rows(batch_id)
            counts = self.school_data_batch_counts(batch_id)
            report = {"source_name": SCHOOL_DATA_IMPORT_SOURCE_NAME, "filename": upload.filename, "stored_file_path": str(stored_path), "source_state": source_state, "source_sector": source_sector, "auto_import": auto_summary, **counts}
            db.execute("UPDATE school_data_import_batches SET report_json=?,updated_at=? WHERE id=?", (json.dumps(report, ensure_ascii=False), now_iso(), batch_id))
            db.audit(self.user, "school_data_import_parsed", "school_library", record_id=batch_id, file_path=str(stored_path), new_value=json.dumps(report, ensure_ascii=False), ip=self.client_address[0], device=self.headers.get("User-Agent"))
            if counts["review_required_rows"] or counts["error_rows"]:
                return self.flash_redirect(f"/schools/rankings?school_import_id={batch_id}", f"学校数据已自动导入 {auto_summary['imported']} 行；仍需处理 {counts['review_required_rows']} 行，错误 {counts['error_rows']} 行。")
            return self.flash_redirect("/schools/rankings", f"学校数据已自动导入完成：{auto_summary['imported']} 行，无需人工确认。")
        except Exception as exc:
            db.execute("UPDATE school_data_import_batches SET import_status='Failed',review_status='Needs Review',report_json=?,updated_at=? WHERE id=?", (json.dumps({"error": str(exc)}, ensure_ascii=False), now_iso(), batch_id))
            db.audit(self.user, "school_data_import_failed", "school_library", record_id=batch_id, file_path=str(stored_path), status="failed", error_message=str(exc), ip=self.client_address[0], device=self.headers.get("User-Agent"))
            return self.flash_redirect("/schools/rankings", f"学校数据导入失败：{exc}", "error")

    def school_data_confirm_all(self, method, batch_id):
        if method != "POST":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        if not (can_school_action(self.user, "review_ranking_matches") and can_school_action(self.user, "edit_ranking_data")):
            return self.school_action_denied("review_school_data_import")
        row_ids = []
        for raw_id in split_multi(self.form, "school_data_row_ids"):
            try:
                row_ids.append(int(raw_id))
            except (TypeError, ValueError):
                continue
        imported = 0
        review = 0
        failed = 0
        batch = db.one("SELECT * FROM school_data_import_batches WHERE id=?", (batch_id,))
        match_cache = {}
        for row_id in row_ids:
            try:
                result = self.school_data_apply_row(row_id, self.form, batch=batch, match_cache=match_cache, update_batch_counts=False, audit_row=False)
                imported += 1 if result == "Imported" else 0
                review += 1 if result != "Imported" else 0
            except Exception as exc:
                failed += 1
                db.execute("UPDATE school_data_import_rows SET import_status='Error',review_required=1,error_reason=?,updated_at=? WHERE id=?", (str(exc), now_iso(), row_id))
        self.school_data_update_batch_counts(batch_id)
        updated_batch = db.one("SELECT import_status,review_status FROM school_data_import_batches WHERE id=?", (batch_id,))
        db.audit(
            self.user,
            "school_data_import_batch_confirmed",
            "school_library",
            record_id=batch_id,
            new_value=json.dumps({"imported": imported, "review": review, "failed": failed}, ensure_ascii=False),
            ip=self.client_address[0],
            device=self.headers.get("User-Agent"),
        )
        if updated_batch and updated_batch["import_status"] == "Imported" and updated_batch["review_status"] == "Confirmed":
            return self.flash_redirect("/schools/rankings", f"学校数据确认完成：导入/合并 {imported} 条，仍需确认 {review} 条，失败 {failed} 条。已确认批次不再显示在导入页面。")
        return self.flash_redirect(f"/schools/rankings?school_import_id={batch_id}", f"学校数据确认完成：导入/合并 {imported} 条，仍需确认 {review} 条，失败 {failed} 条。")

