            result = self.school_data_delete_batch(batch_id)
            file_note = "源文件已删除。" if result["file_deleted"] else ("源文件未删除：" + result["file_error"] if result["file_error"] else "没有找到需要删除的源文件。")
            return self.flash_redirect("/schools/rankings", f"已删除上传数据：{result['original_filename']}；解析数据 {result['rows_deleted']} 行已清除。{file_note}")
