    def school_data_batch_download(self, method, batch_id):
        if method != "GET":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        if not can_school_action(self.user, "view_rankings"):
            return self.school_action_denied("view_school_data_import")
        batch = db.one("SELECT * FROM school_data_import_batches WHERE id=?", (batch_id,))
        if not batch:
            return self.error_page("学校数据上传记录不存在", HTTPStatus.NOT_FOUND)
        stored_path = str(batch["stored_file_path"] or "").strip()
        if not stored_path:
            return self.error_page("这个上传记录没有保存源文件路径", HTTPStatus.NOT_FOUND)
        raw_path = Path(stored_path)
        if not raw_path.is_absolute():
            raw_path = APP_DIR / raw_path
        try:
            target = ensure_within(raw_path, SCHOOL_DATA_IMPORT_DIR)
        except Exception as exc:
            return self.error_page(f"源文件路径不安全或不在项目导入目录内：{exc}", HTTPStatus.NOT_FOUND)
        if not target.is_file():
            return self.error_page("源文件不存在，可能已经被删除", HTTPStatus.NOT_FOUND)
        payload = target.read_bytes()
        filename = str(batch["original_filename"] or target.name).strip() or target.name
        db.audit(self.user, "school_data_import_source_downloaded", "school_library", record_id=batch_id, file_path=str(target), new_value=filename, ip=self.client_address[0], device=self.headers.get("User-Agent"))
        self.send_response(HTTPStatus.OK)
        self.send_header("Content-Type", mimetypes.guess_type(target.name)[0] or "application/octet-stream")
        self.send_header("Content-Disposition", f"attachment; filename*=UTF-8''{quote(filename)}")
        self.send_header("Content-Length", str(len(payload)))
        self.end_headers()
        self.wfile.write(payload)

