    def school_ranking_import_report_paths(self, folder, import_id):
        stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        json_path, _ = next_version_path(folder, f"{BETTER_EDUCATION_REPORT_PREFIX}_{stamp}_{import_id}.json")
        md_path, _ = next_version_path(folder, f"{BETTER_EDUCATION_REPORT_PREFIX}_{stamp}_{import_id}.md")
        return md_path, json_path

    def school_deleted_filter_sql(self, table_alias=""):
        table = "schools"
        prefix = f"{table_alias}." if table_alias else ""
        try:
            columns = {row["name"] for row in db.all(f"PRAGMA table_info({table})")}
        except Exception:
            columns = set()
        return f" WHERE {prefix}deleted_at IS NULL" if "deleted_at" in columns else ""

    def school_ranking_write_import_report(self, folder, import_id, report):
        md_path, json_path = self.school_ranking_import_report_paths(folder, import_id)
        payload = dict(report)
        payload.update({
            "import_id": import_id,
            "report_generated_at": now_iso(),
            "report_md_path": str(md_path),
            "report_json_path": str(json_path),
            "large_scale_scraping_performed": False,
            "official_academic_data_overwritten": False,
        })
        json_path.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")
        md_lines = [
            "# Better Education Import Report",
            "",
            f"- import_id: {import_id}",
            f"- source_name: {BETTER_EDUCATION_SOURCE_NAME}",
            f"- source_type: {BETTER_EDUCATION_SOURCE_TYPE}",
            f"- generated_at: {payload['report_generated_at']}",
            f"- original_file: {payload.get('filename', '')}",
            f"- stored_file_path: {payload.get('stored_file_path', '')}",
            f"- source_url: {payload.get('source_url', '') or 'Not provided'}",
            f"- ranking_system: {payload.get('ranking_system', '')}",
            f"- state: {payload.get('state', '')}",
            f"- data_year: {payload.get('data_year', '')}",
            f"- total_rows: {payload.get('total_rows', 0)}",
            f"- matched_rows: {payload.get('matched_rows', 0)}",
            f"- possible_rows: {payload.get('possible_rows', 0)}",
            f"- unmatched_rows: {payload.get('unmatched_rows', 0)}",
            f"- review_status: Needs Review",
            f"- large_scale_scraping_performed: false",
            f"- official_academic_data_overwritten: false",
            "",
            "Notes:",
            "- Better Education is stored as third-party ranking reference only.",
            "- Ranking rows require staff review/confirmation before they become official CRM school ranking records.",
            "- This import does not overwrite My School / ACARA, official school, or manually approved academic data.",
        ]
        md_path.write_text("\n".join(md_lines) + "\n", encoding="utf-8")
        return md_path, json_path, payload

    def school_ranking_match_school(self, school_name_raw, state="", locality=""):
        name = self.school_ranking_clean_school_name(school_name_raw)
        if not name:
            return None, "", 0.0, "Unmatched"
        locality = self.school_ranking_clean_locality(locality)
        state = str(state or "").strip().upper()
        deleted_filter = self.school_deleted_filter_sql()
        params = []
        if state:
            where = "WHERE UPPER(COALESCE(state,''))=?"
            params.append(state)
            if deleted_filter:
                where += " AND deleted_at IS NULL"
        else:
            where = deleted_filter
        schools = db.all(f"SELECT id,school_name,state,suburb,address FROM schools {where}".rstrip(), tuple(params))
        normalized = self.school_ranking_normalize_text(name)
        normalized_locality = self.school_ranking_normalize_text(locality)
        exact_name_candidates = [
            school for school in schools
            if self.school_ranking_normalize_text(school["school_name"]) == normalized
        ]
        if exact_name_candidates:
            if normalized_locality:
                exact_locality_candidates = [
                    school for school in exact_name_candidates
                    if self.school_ranking_normalize_text(school["suburb"]) == normalized_locality
                    or normalized_locality in self.school_ranking_normalize_text(school["address"])
                ]
                if exact_locality_candidates:
                    best = exact_locality_candidates[0]
                    return best["id"], best["school_name"], 1.0, "Matched"
                if len(exact_name_candidates) > 1:
                    best = exact_name_candidates[0]
                    return None, best["school_name"], 0.94, "Possible Match"
            best = exact_name_candidates[0]
            return best["id"], best["school_name"], 1.0, "Matched"
        best = None
        best_score = 0.0
        for school in schools:
            candidate = self.school_ranking_normalize_text(school["school_name"])
            score = SequenceMatcher(None, normalized, candidate).ratio()
            if normalized and candidate and (normalized in candidate or candidate in normalized):
                score = max(score, 0.9)
            if normalized_locality:
                candidate_suburb = self.school_ranking_normalize_text(school["suburb"])
                candidate_address = self.school_ranking_normalize_text(school["address"])
                if candidate_suburb == normalized_locality or normalized_locality in candidate_address:
                    score = min(1.0, score + 0.04)
                    if normalized and candidate and (normalized in candidate or candidate in normalized):
                        score = max(score, 0.97)
                elif score < 0.96:
                    score = max(0.0, score - 0.03)
            if score > best_score:
                best_score = score
                best = school
        if not best:
            return None, "", 0.0, "Unmatched"
        best_name = best["school_name"]
        best_normalized = self.school_ranking_normalize_text(best_name)
        if normalized == best_normalized:
            return best["id"], best_name, 1.0, "Matched"
        if best_score >= 0.96:
            return best["id"], best["school_name"], round(best_score, 3), "Matched"
        if best_score >= 0.84:
            return None, best["school_name"], round(best_score, 3), "Possible Match"
        return None, "", round(best_score, 3), "Unmatched"

    def school_ranking_refresh_import_counts(self, import_id):
        rows = db.all("SELECT match_status,suggested_school_id,review_status FROM school_ranking_import_rows WHERE import_id=?", (import_id,))
        matched = sum(1 for row in rows if row["suggested_school_id"] and row["match_status"] in {"Matched", "Confirmed"})
        possible = sum(1 for row in rows if row["match_status"] == "Possible Match")
        unmatched = sum(1 for row in rows if row["match_status"] == "Unmatched")
        db.execute(
            "UPDATE school_ranking_imports SET matched_rows=?,possible_rows=?,unmatched_rows=?,updated_at=? WHERE id=?",
            (matched, possible, unmatched, now_iso(), import_id),
        )
        return {"matched_rows": matched, "possible_rows": possible, "unmatched_rows": unmatched}

    def school_ranking_rematch_pending_rows(self, states=("NSW", "VIC"), import_ids=None):
        state_values = [str(state or "").strip().upper() for state in states if str(state or "").strip()]
        params = []
        clauses = ["review_status='Needs Review'"]
        if state_values:
            clauses.append("UPPER(COALESCE(state,'')) IN (" + ",".join("?" for _ in state_values) + ")")
            params.extend(state_values)
        if import_ids:
            ids = [int(value) for value in import_ids]
            clauses.append("import_id IN (" + ",".join("?" for _ in ids) + ")")
            params.extend(ids)
        rows = db.all(
            f"""SELECT * FROM school_ranking_import_rows
                WHERE {' AND '.join(clauses)}
                ORDER BY import_id,row_number""",
            tuple(params),
        )
        summary = {"checked": 0, "matched": 0, "possible": 0, "unmatched": 0, "renamed": 0, "imports": set()}
        for row in rows:
            summary["checked"] += 1
            try:
                raw_payload = json.loads(row["raw_row_json"] or "{}")
            except Exception:
                raw_payload = {}
            if not isinstance(raw_payload, dict):
                raw_payload = {}
            canonical = self.school_ranking_canonical_row(raw_payload) if raw_payload else {
                "school_name_raw": self.school_ranking_clean_school_name(row["school_name_raw"]),
                "locality": "",
                "rank": row["rank"] or "",
            }
            school_name_raw = canonical.get("school_name_raw") or self.school_ranking_clean_school_name(row["school_name_raw"])
            locality = canonical.get("locality", "")
            rank = canonical.get("rank") or row["rank"] or ""
            state = str(row["state"] or "").strip().upper()
            school_id, school_name, confidence, match_status = self.school_ranking_match_school(school_name_raw, state, locality)
            if school_name_raw and school_name_raw != (row["school_name_raw"] or ""):
                summary["renamed"] += 1
            if match_status == "Matched":
                summary["matched"] += 1
            elif match_status == "Possible Match":
                summary["possible"] += 1
            else:
                summary["unmatched"] += 1
            notes = row["notes"] or ""
            if locality and "Locality:" not in notes:
                notes = (notes + ("; " if notes else "") + f"Locality: {locality}").strip()
            db.execute(
                """UPDATE school_ranking_import_rows
                   SET school_name_raw=?,rank=?,suggested_school_id=?,suggested_school_name=?,confidence_score=?,match_status=?,notes=?,updated_at=?
                   WHERE id=?""",
                (school_name_raw, rank, school_id, school_name, confidence, match_status, notes, now_iso(), row["id"]),
            )
            summary["imports"].add(row["import_id"])
        for import_id in sorted(summary["imports"]):
            self.school_ranking_refresh_import_counts(import_id)
        summary["imports"] = sorted(summary["imports"])
        return summary

