    def school_documents_batch_upload(self, method):
        if not can_access_module(self.user, "school_library"):
            return self.school_action_denied("view")
        if method == "GET":
            message, kind = self.message()
            return self.school_documents_batch_upload_page(message=message, kind=kind)
        if method != "POST":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        if not (can_school_action(self.user, "upload_documents") or can_school_action(self.user, "upload")):
            return self.school_action_denied("upload_documents")
        try:
            if str(self.form.get("action", "")).strip() == "scan_folder":
                summary = self.scan_school_bulk_document_folder(
                    self.form.get("state", ""),
                    self.form.get("year", ""),
                    self.form.get("document_type", ""),
                )
            else:
                uploads = [f for f in self.files if f.field_name in {"files", "file"} and f.filename]
                summary = self.save_school_bulk_document_uploads(
                    self.form.get("state", ""),
                    self.form.get("year", ""),
                    self.form.get("document_type", ""),
                    uploads,
                )
        except Exception as exc:
            return self.school_documents_batch_upload_page(message=f"批量上传失败：{exc}", kind="error")
        message = f"处理完成：已关联 {summary.get('linked', 0)} 个文件，已跳过 {summary.get('skipped', 0)} 个，未匹配 {summary.get('unmatched', 0)} 个，失败 {summary.get('failed', 0)} 个。"
        kind = "success" if summary["linked"] else "warning"
        return self.school_documents_batch_upload_page(summary=summary, message=message, kind=kind)

    def school_documents_panel(self, school):
        rows = db.all("SELECT d.*,u.display_name uploaded_name FROM school_documents d LEFT JOIN users u ON u.id=d.uploaded_by WHERE d.school_id=? ORDER BY d.uploaded_at DESC", (school["id"],))
        row_html = []
        can_delete_document = self.can_edit_school_detail("upload_documents") or self.can_edit_school_detail("upload")
        can_update_document = self.can_edit_school_detail("upload_documents")
        bulk_form_id = f"school-documents-bulk-{school['id']}"
        bulk_action = f"/schools/{school['id']}/documents/bulk-update"
