    def school_logo_candidates_panel(self, school):
        rows = db.all(
            """SELECT * FROM school_logo_candidates
               WHERE school_id=? AND review_status='Pending Review'
               ORDER BY confidence_score DESC,id DESC LIMIT 8""",
            (school["id"],),
        )
        if not rows:
            can_manage = is_school_manager_user(self.user) and can_access_module(self.user, "school_library")
            if self.can_edit_school_detail("upload_logo") or self.can_edit_school_detail("upload"):
                message = "暂无待确认 Logo。点击“查找 Logo”后，系统会显示推荐结果。"
            elif can_manage:
                message = "暂无待确认 Logo。请先点击上方“查找 Logo”进入编辑模式。"
            else:
                message = "暂无待确认 Logo。当前账号没有 Logo 查找或上传权限。"
            return f'<div class="empty compact">{esc(message)}</div>'
        cards = []
        can_update = self.can_edit_school_detail("upload_logo") or self.can_edit_school_detail("upload")
        for row in rows:
            image = ""
            if row["candidate_file_path"]:
                url = self.school_file_url(row["candidate_file_path"])
                if url:
                    image = f'<img class="school-logo-image" src="{esc(url)}" alt="Logo candidate">'
            if not image and row["source_url"]:
                image = f'<img class="school-logo-image" src="{esc(row["source_url"])}" alt="Logo candidate">'
            if not image:
                image = '<div class="school-logo-placeholder">?</div>'
            approve = reject = ""
            if can_update:
                approve = f"""<form method="post" action="/schools/{school['id']}/logo/candidates/{row['id']}/approve"><input type="hidden" name="csrf" value="{esc(self.csrf)}"><button class="primary compact">确认使用这个 Logo</button></form>"""
                reject = f"""<form method="post" action="/schools/{school['id']}/logo/candidates/{row['id']}/reject"><input type="hidden" name="csrf" value="{esc(self.csrf)}"><button class="ghost compact">换一个 / 拒绝</button></form>"""
            cards.append(
                f"""<article class="school-logo-candidate-card">
                  <div class="school-logo-preview">{image}</div>
                  <div><h3>推荐 Logo</h3>
                    <p>来源：{esc(row['source_type'] or '')}</p>
                    <p>状态：{esc(row['logo_status'] or '')}</p>
                    <p>置信度：{esc(row['confidence_score'] if row['confidence_score'] is not None else '')}</p>
                    <p>Google：{esc(row['google_cross_check_status'] or 'not_configured')}</p>
                    <p class="muted-line">{esc(row['notes'] or '')}</p>
                    <a href="{esc(row['source_url'] or '#')}" target="_blank">来源网址</a>
                    <div class="row-actions compact-actions">{approve}{reject}</div>
                  </div>
                </article>"""
            )
        return f'<div class="school-logo-candidate-grid">{"".join(cards)}</div>'

