    def school_extract_myschool_data(self, text):
        clean = re.sub(r"\s+", " ", text or "").strip()
        patterns = {
            "teaching_staff": r"Teaching staff\s*([0-9,]+(?:\.\d+)?)",
            "fte_teaching_staff": r"Full[- ]time equivalent teaching staff\s*([0-9,]+(?:\.\d+)?)",
            "non_teaching_staff": r"Non[- ]teaching staff\s*([0-9,]+(?:\.\d+)?)",
            "fte_non_teaching_staff": r"Full[- ]time equivalent non[- ]teaching staff\s*([0-9,]+(?:\.\d+)?)",
            "icsea_value": r"ICSEA[^0-9]{0,40}([0-9]{3,4})",
            "icsea_percentile": r"ICSEA percentile[^0-9]{0,40}([0-9]+(?:\.\d+)?)",
            "total_enrolments": r"(?:Total enrolments|Total enroll?ments|Enrolments)\s*([0-9,]+)",
            "fte_students": r"Full[- ]time equivalent students\s*([0-9,]+(?:\.\d+)?)",
            "male_enrolments": r"(?:Boys|Male students|Male enrolments)\s*([0-9,]+)",
            "female_enrolments": r"(?:Girls|Female students|Female enrolments)\s*([0-9,]+)",
            "language_background_other_than_english_pct": r"(?:Language background other than English|LBOTE)\s*([0-9]+(?:\.\d+)?)\s*%",
            "indigenous_student_percentage": r"Indigenous students?\s*([0-9]+(?:\.\d+)?)\s*%",
            "attendance_percentage": r"Attendance\s*([0-9]+(?:\.\d+)?)\s*%",
        }
        data = {}
        for key, pattern in patterns.items():
            match = re.search(pattern, clean, re.I)
            if match:
                data[key] = match.group(1).replace(",", "")
        profile_patterns = {
            "school_name_from_myschool": r"(?:School name|Name)\s*[:\-]?\s*([A-Z][A-Za-z0-9 '&.\-]{3,120})",
            "sector": r"(?:School sector|Sector)\s*[:\-]?\s*(Government|Independent|Catholic|Public|Private)",
            "school_type": r"(?:School type|Type)\s*[:\-]?\s*([A-Za-z /-]{3,80})",
            "year_range": r"(?:Year range|Year levels|Years)\s*[:\-]?\s*([A-Za-z0-9, /-]{3,80})",
            "gender_type": r"(?:Gender|School gender)\s*[:\-]?\s*(Coeducational|Co-ed|Boys|Girls)",
        }
        for key, pattern in profile_patterns.items():
            match = re.search(pattern, clean, re.I)
            if match:
                data[key] = re.sub(r"\s+", " ", match.group(1)).strip()
        address_match = re.search(r"([A-Za-z0-9 ,.'/-]{8,120}?\b(VIC|NSW|QLD|WA|SA|TAS|ACT|NT)\s+(\d{4})\b)", clean, re.I)
        if address_match:
            data["address"] = address_match.group(1).strip(" ,")
            data["state"] = address_match.group(2).upper()
            data["postcode"] = address_match.group(3)
            suburb_match = re.search(r"\b([A-Za-z][A-Za-z .'-]+)\s+" + re.escape(data["state"]) + r"\s+" + re.escape(data["postcode"]), data["address"], re.I)
            if suburb_match:
                data["suburb"] = re.sub(r"\s+", " ", suburb_match.group(1)).strip().split(",")[-1].strip()
        website_match = re.search(r"(https?://(?:www\.)?(?!myschool\.edu\.au)[A-Za-z0-9./?&_%#=-]*\.[A-Za-z]{2,}[A-Za-z0-9./?&_%#=-]*)", clean)
        if website_match:
            data["school_website"] = website_match.group(1)
        year_match = re.search(r"\b(20\d{2})\b", clean)
        if year_match:
            data["data_year"] = year_match.group(1)
        if data.get("icsea_value") and not data.get("icsea_average"):
            data["icsea_average"] = "1000"
        return data

    def school_myschool_validate_url(self, source_url):
        source_url = str(source_url or "").strip()
        if not source_url:
            return ""
        parsed = urlparse(source_url)
        if parsed.scheme not in {"http", "https"} or MYSCHOOL_BASE_DOMAIN not in parsed.netloc.lower():
            raise ValueError("请输入有效的 My School / ACARA 页面链接。")
        return source_url

    def school_myschool_extract_academic_indicators(self, text):
        clean = re.sub(r"\s+", " ", text or "").strip()
        rows = []
        for indicator in ["reading", "writing", "spelling", "grammar", "punctuation", "numeracy", "naplan"]:
            pattern = rf"(.{{0,90}}{indicator}.{{0,140}})"
            for match in re.finditer(pattern, clean, re.I):
                raw = match.group(1).strip()
                year_level = re.search(r"\b(Year\s*\d{1,2})\b", raw, re.I)
                data_year = re.search(r"\b(20\d{2})\b", raw)
                value = re.search(r"\b(\d{2,4}(?:\.\d+)?)\b", raw)
                rows.append({
                    "indicator_name": "NAPLAN " + indicator.title(),
                    "year_level": year_level.group(1) if year_level else "",
                    "data_year": data_year.group(1) if data_year else "",
                    "indicator_value": value.group(1) if value else "",
                    "comparison_notes": raw,
                    "raw_text": raw,
                })
        return rows[:24]

    def school_myschool_record_conflicts(self, school, source_url, extracted):
        field_map = {
            "school_name_from_myschool": "school_name",
            "address": "address",
            "sector": "sector_key",
            "school_type": "school_type",
            "year_range": "year_levels",
            "gender_type": "school_gender_type",
            "total_enrolment": "total_enrolments",
            "icsea_value": "icsea_value",
        }
        for extracted_field, school_field in field_map.items():
            acara_value = str(extracted.get(extracted_field) or "").strip()
            existing_value = str(school[school_field] if school_field in school.keys() and school[school_field] else "").strip()
            if not acara_value or not existing_value or acara_value.lower() == existing_value.lower():
                continue
            db.execute(
                """INSERT INTO school_data_conflicts(school_id,source_name,source_url,field_name,official_value,third_party_value,conflict_status,review_status,notes,created_at,updated_at)
                   VALUES(?,?,?,?,?,?,?,?,?,?,?)""",
                (school["id"], MYSCHOOL_SOURCE_NAME, source_url, extracted_field, existing_value, acara_value, "Needs Review", "Needs Review", "My School / ACARA reference differs from existing CRM value", now_iso(), now_iso()),
            )
            db.audit(self.user, "school_myschool_conflict_detected", "school_library", record_id=school["id"], file_path=source_url, old_value=existing_value, new_value=acara_value, ip=self.client_address[0], device=self.headers.get("User-Agent"), status="Needs Review")

    def school_feature_source_excerpt(self, text, keyword="", limit=260):
        clean = re.sub(r"\s+", " ", text or "").strip()
        if not clean:
            return ""
        lower = clean.lower()
        needle = str(keyword or "").lower().strip()
        index = lower.find(needle) if needle else -1
        if index < 0:
            return clean[:limit]
        start = max(0, index - 90)
        end = min(len(clean), index + len(needle) + 150)
        prefix = "..." if start else ""
        suffix = "..." if end < len(clean) else ""
        return prefix + clean[start:end] + suffix

    def school_feature_fetch_source_text(self, source_url):
        parsed = urlparse(source_url)
        if parsed.scheme not in {"http", "https"}:
            raise ValueError("source_url 必须存在，且只能是 http/https。")
        request = urllib.request.Request(source_url, headers={"User-Agent": "AAIE-CRM-SchoolFeatureMVP/1.0"})
        with urllib.request.urlopen(request, timeout=12) as response:
            raw = response.read(1_500_000)
            content_type = response.headers.get("Content-Type", "")
        if "pdf" in content_type.lower() or source_url.lower().endswith(".pdf"):
            raise ValueError("MVP 暂不直接采集远程 PDF，请先上传 PDF 到学校资料后人工确认。")
        text = raw.decode("utf-8", errors="ignore")
        title_match = re.search(r"<title[^>]*>(.*?)</title>", text, re.I | re.S)
        source_title = re.sub(r"\s+", " ", title_match.group(1)).strip() if title_match else parsed.netloc
        text = re.sub(r"(?is)<(script|style).*?>.*?</\\1>", " ", text)
        text = re.sub(r"(?s)<[^>]+>", " ", text)
        text = re.sub(r"\s+", " ", text).strip()
        return source_title, text

    def school_feature_collect_candidates(self, school_id, source_url, source_title, source_text, selected_category_ids):
        category_filter = {str(value) for value in selected_category_ids if str(value).strip()}
        rows = db.all(
            """SELECT t.*,c.category_name_cn,c.category_name_en
               FROM school_feature_tags t
               LEFT JOIN school_feature_categories c ON c.id=t.category_id
               WHERE t.is_active=1 AND c.is_active=1
               ORDER BY c.sort_order,t.sort_order"""
        )
        inserted = 0
        lower_text = (source_text or "").lower()
        for row in rows:
            if category_filter and str(row["category_id"]) not in category_filter:
                continue
            keywords = []
            try:
                keywords = json.loads(row["keywords"] or "[]")
            except Exception:
                keywords = []
            keywords.extend([row["tag_name_cn"] or "", row["tag_name_en"] or ""])
            best_keyword = ""
            hits = 0
            for keyword in keywords:
                kw = str(keyword or "").strip()
                if not kw:
                    continue
                count = lower_text.count(kw.lower())
                if count > hits:
                    hits = count
                    best_keyword = kw
            if hits <= 0:
                continue
            confidence = min(98, 58 + hits * 8 + (8 if row["tag_name_en"] and row["tag_name_en"].lower() in lower_text else 0))
            if confidence < 50:
                continue
            exists = db.one(
                """SELECT id FROM school_feature_tag_assignments
                   WHERE school_id=? AND tag_id=? AND source_url=? AND status IN ('Suggested','NeedsReview','Confirmed')""",
                (school_id, row["id"], source_url),
            )
            if exists:
                continue
            excerpt = self.school_feature_source_excerpt(source_text, best_keyword)
            assignment_id = db.execute(
                """INSERT INTO school_feature_tag_assignments(
                    school_id,category_id,tag_id,assignment_type,status,confidence_rate,
                    source_url,source_title,source_type,source_excerpt,collected_at,collected_by_system,notes,created_by,created_at
                   ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                (
                    school_id, row["category_id"], row["id"], "AutoSuggested", "Suggested", confidence,
                    source_url, source_title, "Provided URL", excerpt, now_iso(), 1,
                    f"Matched keyword: {best_keyword}", self.user["id"], now_iso(),
                ),
            )
            inserted += 1
            db.audit(self.user, "school_feature_tag_suggested", "school_library", record_id=assignment_id, student_id=school_id, new_value=json.dumps({"tag_id": row["id"], "confidence_rate": confidence, "source_url": source_url}, ensure_ascii=False), ip=self.client_address[0], device=self.headers.get("User-Agent"))
        return inserted

    def school_feature_assignment_grouped(self, school_id, status):
        return db.all(
            """SELECT a.*,c.category_name_cn,c.category_name_en,t.tag_name_cn,t.tag_name_en,u.display_name reviewer_name
               FROM school_feature_tag_assignments a
               LEFT JOIN school_feature_categories c ON c.id=a.category_id
               LEFT JOIN school_feature_tags t ON t.id=a.tag_id
               LEFT JOIN users u ON u.id=COALESCE(a.confirmed_by,a.rejected_by)
               WHERE a.school_id=? AND a.status=?
               ORDER BY c.sort_order,t.sort_order,a.created_at DESC""",
            (school_id, status),
        )

    def school_features_panel(self, school, embedded=False):
        confirmed = self.school_feature_assignment_grouped(school["id"], "Confirmed")
