            if review:
                review_form = f"""<form class="inline-form" method="post" action="/schools/{school['id']}/feature-tags/{row['id']}/review"><input type="hidden" name="csrf" value="{esc(self.csrf)}"><button class="primary compact" name="review_action" value="confirm">确认入库</button><button class="ghost compact" name="review_action" value="reject">拒绝</button></form>"""
            notes_form = f"""<form class="inline-form" method="post" action="/schools/{school['id']}/feature-tags/{row['id']}/notes"><input type="hidden" name="csrf" value="{esc(self.csrf)}"><input name="notes" value="{esc(row['notes'] or '')}" placeholder="Notes"><button class="secondary compact">保存备注</button></form>"""
