    def school_normalized_suburb_name(self, suburb):
        return re.sub(r"\s+", " ", str(suburb or "").strip()).lower()

    def school_detect_suburb_from_address(self, address):
        raw = str(address or "").strip()
        match = re.search(r",\s*([A-Za-z][A-Za-z .'-]+?)\s+(VIC|NSW|QLD|WA|SA|TAS|ACT|NT)\s+(\d{4})\b", raw, re.I)
        if match:
            return {
                "suburb": re.sub(r"\s+", " ", match.group(1)).strip(),
                "state": match.group(2).upper(),
                "postcode": match.group(3),
                "confidence": 85,
            }
        match = re.search(r"\b([A-Za-z][A-Za-z .'-]+?)\s+(VIC|NSW|QLD|WA|SA|TAS|ACT|NT)\s+(\d{4})\b", raw, re.I)
        if match:
            return {
                "suburb": re.sub(r"\s+", " ", match.group(1)).strip(),
                "state": match.group(2).upper(),
                "postcode": match.group(3),
                "confidence": 70,
            }
        return {"suburb": "", "state": "", "postcode": "", "confidence": 0}

    def school_ensure_suburb_record(self, suburb, state, postcode, country="Australia"):
        suburb = re.sub(r"\s+", " ", str(suburb or "").strip())
        state = str(state or "").strip().upper()
        postcode = str(postcode or "").strip()
        country = str(country or "Australia").strip() or "Australia"
        if not suburb or not state:
            return None
        normalized = self.school_normalized_suburb_name(suburb)
        row = db.one(
            "SELECT id FROM school_suburbs WHERE normalized_suburb_name=? AND state=? AND COALESCE(postcode,'')=?",
            (normalized, state, postcode),
        )
        if row:
            db.execute("UPDATE school_suburbs SET suburb=?,country=?,updated_at=? WHERE id=?", (suburb, country, now_iso(), row["id"]))
            return row["id"]
        return db.execute(
            """INSERT INTO school_suburbs(suburb,state,postcode,country,normalized_suburb_name,created_at,updated_at)
               VALUES(?,?,?,?,?,?,?)""",
            (suburb, state, postcode, country, normalized, now_iso(), now_iso()),
        )

    def school_latest_suburb_data(self, school):
        suburb_id = school["suburb_id"] if "suburb_id" in school.keys() else None
        zone_payload = {}
        if "zone_data_json" in school.keys() and school["zone_data_json"]:
            try:
                parsed = json.loads(school["zone_data_json"])
                if isinstance(parsed, dict):
                    zone_payload = parsed
            except Exception:
                zone_payload = {}
        suburb_data_id = maybe_int(zone_payload.get("suburb_data_id"))
        if suburb_data_id:
            row = db.one(
                """SELECT d.*,s.suburb,s.state,s.postcode,s.country
                   FROM school_suburb_data d
                   JOIN school_suburbs s ON s.id=d.suburb_id
                   WHERE d.id=?""",
                (suburb_data_id,),
            )
            if row:
                return row
        profile_id = maybe_int(zone_payload.get("school_area_profile_id"))
        if profile_id:
            row = db.one(
                """SELECT d.*,s.suburb,s.state,s.postcode,s.country
                   FROM school_suburb_data d
                   JOIN school_suburbs s ON s.id=d.suburb_id
                   WHERE json_valid(d.other_indicators_json)=1
                     AND json_extract(d.other_indicators_json,'$.school_area_profile_id')=?
                   ORDER BY d.updated_at DESC,d.id DESC
                   LIMIT 1""",
                (profile_id,),
            )
            if row:
                return row
        if not suburb_id:
            return None
        return db.one(
            """SELECT d.*,s.suburb,s.state,s.postcode,s.country
               FROM school_suburb_data d
               JOIN school_suburbs s ON s.id=d.suburb_id
               WHERE d.suburb_id=?
               ORDER BY d.updated_at DESC,d.id DESC LIMIT 1""",
            (suburb_id,),
        )

    def school_suburb_data_input(self, current, name, label, disabled=""):
        value = current[name] if current and name in current.keys() and current[name] is not None else ""
        textarea_fields = {"top_languages_json", "education_summary", "top_birth_countries_json", "ancestry_summary", "other_indicators_json"}
        if name in textarea_fields:
            return f'<label>{esc(label)}<textarea name="{esc(name)}" rows="3"{disabled}>{esc(value)}</textarea></label>'
        return f'<label>{esc(label)}<input name="{esc(name)}" value="{esc(value)}"{disabled}></label>'

    def school_suburb_data_has_value(self, current, name):
        if not current or name not in current.keys():
            return False
        value = current[name]
        if value is None:
            return False
        return str(value).strip() != ""

    def school_suburb_source_options(self, selected=""):
        rows = db.all("SELECT source_name,source_type FROM school_suburb_data_sources WHERE enabled=1 ORDER BY source_type,source_name")
        options = []
        seen = set()
        for row in rows:
            value = row["source_name"]
            if value in seen:
                continue
            seen.add(value)
            options.append((value, f"{row['source_name']} / {row['source_type']}"))
        if selected and selected not in seen:
            options.append((selected, selected))
        return self.school_option_tags(options or [("Manual AAIE Entry", "Manual AAIE Entry")], selected)

    def school_suburb_group_html(self, current, group, title, disabled="", source_badge=""):
        fields = [
            (name, label)
            for name, label, field_group in SCHOOL_SUBURB_DATA_FIELDS
            if field_group == group and self.school_suburb_data_has_value(current, name)
        ]
        if not fields:
            return ""
        inputs = "".join(self.school_suburb_data_input(current, name, label, disabled) for name, label in fields)
        return f'<details class="school-zone-group" open><summary><span>{esc(title)}</span>{source_badge}</summary><div class="form-grid two-col">{inputs}</div></details>'

