    def school_area_profile_display_value(self, row):
        value = row["metric_value"] if row and "metric_value" in row.keys() else None
        if value is None:
            return ""
        if str(value).strip() == "":
            return ""
        try:
            number = float(value)
            text = f"{number:.1f}" if not number.is_integer() else str(int(number))
        except (TypeError, ValueError):
            text = str(value)
        unit = row["metric_unit"] if row and "metric_unit" in row.keys() and row["metric_unit"] else ""
        unit = {
            "years": "年",
            "percent": "%",
            "AUD/week": "澳元/周",
            "AUD/month": "澳元/月",
        }.get(unit, unit)
        return f"{text}{' ' + unit if unit and unit != 'count' else ''}"

