        geography_type = current["geography_type"] if current and "geography_type" in current.keys() and current["geography_type"] else "SA2"
        geography_code = current["geography_code"] if current and "geography_code" in current.keys() and current["geography_code"] else (profile["sa2_code"] if profile and profile["sa2_code"] else "")
        retrieved_at = current["retrieved_at"] if current and "retrieved_at" in current.keys() and current["retrieved_at"] else fetched_at
        source_link = f'<a href="{esc(source_url)}" target="_blank" rel="noopener">source</a>' if source_url else "未记录来源 URL"
