    def school_area_third_party_cross_check_panel(self, school):
        if not can_school_action(self.user, "view_suburb_data"):
            return ""
        profile = self.school_latest_area_profile(school["id"])
        comparison_rows = db.all(
            """SELECT *
               FROM school_comparison_sources
               WHERE school_id=? AND source_type='area_third_party_cross_check'
               ORDER BY updated_at DESC,id DESC""",
            (school["id"],),
        )
        latest_by_source = {}
        for row in comparison_rows:
            latest_by_source.setdefault(row["source_name"], row)
        conflicts = db.all(
            """SELECT *
               FROM school_data_conflicts
               WHERE school_id=?
                 AND source_name IN ('profile.id','Australian Urban Observatory','AURIN')
               ORDER BY updated_at DESC,id DESC
               LIMIT 8""",
            (school["id"],),
        )
        conflict_count = len(conflicts)
        overall_status_key = "conflict" if conflict_count else (
            "source_available" if latest_by_source else "not_checked"
        )
        overall_status = SCHOOL_AREA_THIRD_PARTY_STATUS_LABELS[overall_status_key]
        status_class = "bad" if conflict_count else ("warn" if latest_by_source else "neutral")
        source_cards = []
        for source in AREA_THIRD_PARTY_CROSS_CHECK_SOURCES:
            row = latest_by_source.get(source["source_name"])
            status = row["review_status"] if row and row["review_status"] else "Not Checked"
            status_label = SCHOOL_AREA_THIRD_PARTY_REVIEW_LABELS.get(status, status)
            fetched = (row["fetched_at"] if row and row["fetched_at"] else "")[:19]
            notes = row["notes"] if row and row["notes"] else source["notes"]
            source_url = row["source_url"] if row and row["source_url"] else source["source_url"]
            source_cards.append(
                f"""<article class="school-area-third-party-card">
                  <div><span>{esc(source['scope'])}</span><strong>{esc(source['source_name'])}</strong></div>
                  <p>{esc(notes)}</p>
                  <small>内部核查状态：{esc(status_label)}{(' · 检查时间 ' + esc(fetched)) if fetched else ''}</small>
                  <a class="secondary button-link compact" href="{esc(source_url)}" target="_blank" rel="noopener">打开来源</a>
                </article>"""
            )
        conflict_rows = "".join(
            f"""<tr><td>{esc(row['source_name'])}</td><td>{esc(row['field_name'])}</td><td>{esc(row['official_value'] or '')}</td><td>{esc(row['third_party_value'] or '')}</td><td>{esc(SCHOOL_AREA_THIRD_PARTY_STATUS_LABELS['conflict'])}</td></tr>"""
            for row in conflicts
        ) or '<tr><td colspan="5" class="empty">暂无第三方冲突记录</td></tr>'
        area_text = "待匹配"
        if profile:
            area_bits = [profile["sa2_name"] or profile["sa2_code"] or "", profile["lga_name"] or profile["lga_code"] or ""]
            area_text = " / ".join(bit for bit in area_bits if bit) or "待匹配"
        return f"""<section class="panel school-area-third-party-panel" id="area-third-party-cross-check">
          <div class="panel-head"><div><h2>第三方交叉比对 / Third-party Cross Check</h2><p>{esc(SCHOOL_AREA_PARENT_SOURCE_NOTE)}</p></div><span class="status {status_class}">{esc(overall_status)}</span></div>
          <div class="school-zone-summary">
            <div><span>ABS 主区域</span><strong>{esc(area_text)}</strong><small>{esc(profile['data_year'] if profile and profile['data_year'] else '待确认')}</small></div>
            <div><span>第三方来源</span><strong>{esc(len(AREA_THIRD_PARTY_CROSS_CHECK_SOURCES))}</strong><small>profile.id / AUO / AURIN</small></div>
            <div><span>冲突记录</span><strong>{esc(conflict_count)}</strong><small>只标记，不自动覆盖</small></div>
          </div>
          <div class="school-area-third-party-grid">{''.join(source_cards)}</div>
          <details class="school-zone-sources"><summary>第三方冲突记录 / Third-party Conflict Log</summary><div class="table-wrap"><table><thead><tr><th>Source</th><th>Field</th><th>ABS / CRM</th><th>Third-party</th><th>Status</th></tr></thead><tbody>{conflict_rows}</tbody></table></div></details>
        </section>"""

