    def school_document_update(self, method, school_id, document_id):
        if method != "POST":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        if not self.require_school_action("upload_documents"):
            return
        row = db.one("SELECT * FROM school_documents WHERE id=? AND school_id=?", (document_id, school_id))
        if not row:
            return self.error_page("资料不存在", HTTPStatus.NOT_FOUND)
        old_value = json.dumps({"document_type": row["document_type"], "notes": row["notes"]}, ensure_ascii=False)
        document_type = str(self.form.get("document_type", "")).strip() or row["document_type"]
        notes = str(self.form.get("notes", "")).strip()
        db.execute("UPDATE school_documents SET document_type=?,notes=?,updated_by=?,updated_at=? WHERE id=?", (document_type, notes, self.user["id"], now_iso(), document_id))
        db.audit(self.user, "school_document_updated", "school_library", record_id=document_id, file_path=row["file_path"], old_value=old_value, new_value=json.dumps({"document_type": document_type, "notes": notes}, ensure_ascii=False), ip=self.client_address[0], device=self.headers.get("User-Agent"))
        return self.flash_redirect(f"/schools/{school_id}#documents", "学校资料已更新。")

    def school_documents_bulk_update(self, method, school_id):
        if method != "POST":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        if not self.require_school_action("upload_documents"):
            return
        school = db.one("SELECT id FROM schools WHERE id=?", (school_id,))
        if not school:
            return self.error_page("学校不存在", HTTPStatus.NOT_FOUND)
        document_ids = []
        for raw_id in split_multi(self.form, "document_ids"):
            try:
                document_ids.append(int(raw_id))
            except (TypeError, ValueError):
                continue
        if not document_ids:
            return self.flash_redirect(f"/schools/{school_id}#documents", "没有可保存的学校资料。", "error")
        changed = 0
        changed_ids = []
        for document_id in document_ids:
            row = db.one("SELECT * FROM school_documents WHERE id=? AND school_id=?", (document_id, school_id))
            if not row:
                continue
            document_type = str(self.form.get(f"document_type_{document_id}", "")).strip() or row["document_type"]
            notes = str(self.form.get(f"notes_{document_id}", "")).strip()
            if document_type == row["document_type"] and notes == (row["notes"] or ""):
                continue
            old_value = json.dumps({"document_type": row["document_type"], "notes": row["notes"]}, ensure_ascii=False)
            new_value = json.dumps({"document_type": document_type, "notes": notes}, ensure_ascii=False)
            db.execute(
                "UPDATE school_documents SET document_type=?,notes=?,updated_by=?,updated_at=? WHERE id=?",
                (document_type, notes, self.user["id"], now_iso(), document_id),
            )
            db.audit(self.user, "school_document_updated", "school_library", record_id=document_id, file_path=row["file_path"], old_value=old_value, new_value=new_value, ip=self.client_address[0], device=self.headers.get("User-Agent"))
            changed += 1
            changed_ids.append(document_id)
        db.audit(
            self.user,
            "school_document_bulk_updated",
            "school_library",
            record_id=school_id,
            new_value=json.dumps({"document_ids": changed_ids, "changed_count": changed}, ensure_ascii=False),
            ip=self.client_address[0],
            device=self.headers.get("User-Agent"),
        )
        return self.flash_redirect(f"/schools/{school_id}#documents", f"学校资料已保存：{changed} 个文件。")

    def school_document_delete(self, method, school_id, document_id):
        if method != "POST":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        if not (can_school_action(self.user, "upload_documents") or can_school_action(self.user, "upload")):
            return self.school_action_denied("upload_documents")
        row = db.one("SELECT * FROM school_documents WHERE id=? AND school_id=?", (document_id, school_id))
        if not row:
            return self.error_page("资料不存在", HTTPStatus.NOT_FOUND)
        old_value = json.dumps({
            "document_type": row["document_type"],
            "original_filename": row["original_filename"],
            "stored_filename": row["stored_filename"],
            "notes": row["notes"],
        }, ensure_ascii=False)
        deleted_file = False
        file_path = row["file_path"] or ""
        if file_path:
            try:
                target = ensure_within(Path(file_path), SCHOOL_LIBRARY_FILE_DIR)
                if target.exists():
                    if not target.is_file():
                        return self.flash_redirect(f"/schools/{school_id}#documents", "无法删除：目标不是文件。", "error")
                    target.unlink()
                    deleted_file = True
            except Exception as exc:
                return self.flash_redirect(f"/schools/{school_id}#documents", f"无法删除学校资料文件：{exc}", "error")
        db.execute("DELETE FROM school_documents WHERE id=?", (document_id,))
        db.audit(
            self.user, "school_document_deleted", "school_library", record_id=document_id,
            file_path=file_path, old_value=old_value,
            new_value=json.dumps({"deleted_file": deleted_file}, ensure_ascii=False),
            ip=self.client_address[0], device=self.headers.get("User-Agent"),
        )
        wants_json = "application/json" in (self.headers.get("Accept") or "") or self.headers.get("X-Requested-With") == "fetch"
        if wants_json:
            return self.json_response({"ok": True, "message": "学校资料文件已删除。", "document_id": document_id})
        return self.flash_redirect(f"/schools/{school_id}#documents", "学校资料文件已删除。")

    def school_feature_category_create(self, method):
        if method != "POST":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        if not (can_school_action(self.user, "manage_feature_categories") or self.user.get("role_name") == "Admin"):
            return self.school_action_denied("manage_feature_categories")
        name_cn = str(self.form.get("category_name_cn", "")).strip()
        name_en = str(self.form.get("category_name_en", "")).strip()
        if not name_cn:
            return self.flash_redirect("/schools/library", "一级分类中文名称为必填项。", "error")
        key_base = name_en or name_cn
        category_key = re.sub(r"[^a-z0-9]+", "_", key_base.lower()).strip("_") or f"category_{new_token(3)}"
        existing = db.one("SELECT id FROM school_feature_categories WHERE category_key=?", (category_key,))
        if existing:
            category_key = f"{category_key}_{new_token(3).lower()}"
        sort_row = db.one("SELECT COALESCE(MAX(sort_order),0)+10 next_sort FROM school_feature_categories")
        category_id = db.execute(
            """INSERT INTO school_feature_categories(category_key,category_name_cn,category_name_en,description,sort_order,is_active,created_by,created_at)
               VALUES(?,?,?,?,?,?,?,?)""",
            (category_key, name_cn, name_en, str(self.form.get("description", "")).strip(), sort_row["next_sort"], 1, self.user["id"], now_iso()),
        )
        db.audit(self.user, "school_feature_category_created", "school_library", record_id=category_id, new_value=name_cn, ip=self.client_address[0], device=self.headers.get("User-Agent"))
        return self.flash_redirect(self.headers.get("Referer") or "/schools/library", "一级特色分类已创建。")

