    def school_feature_tag_create(self, method):
        if method != "POST":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        if not (can_school_action(self.user, "manage_feature_tags") or self.user.get("role_name") == "Admin"):
            return self.school_action_denied("manage_feature_tags")
        category_id = str(self.form.get("category_id", "")).strip()
        tag_cn = str(self.form.get("tag_name_cn", "")).strip()
        tag_en = str(self.form.get("tag_name_en", "")).strip()
        if not category_id or not tag_cn:
            return self.flash_redirect(self.headers.get("Referer") or "/schools/library", "一级分类和二级标签名称为必填项。", "error")
        category = db.one("SELECT * FROM school_feature_categories WHERE id=? AND is_active=1", (category_id,))
        if not category:
            return self.flash_redirect(self.headers.get("Referer") or "/schools/library", "一级分类不存在。", "error")
        keywords_raw = str(self.form.get("keywords", "")).strip()
        keywords = [item.strip() for item in re.split(r"[,，;；\n]+", keywords_raw) if item.strip()]
        keywords.extend([tag_cn, tag_en])
        sort_row = db.one("SELECT COALESCE(MAX(sort_order),0)+10 next_sort FROM school_feature_tags WHERE category_id=?", (category_id,))
        tag_id = db.execute(
            """INSERT INTO school_feature_tags(category_id,tag_name_zh,tag_name_cn,tag_name_en,tag_group,description,keywords,sort_order,is_active,created_by,created_at)
               VALUES(?,?,?,?,?,?,?,?,?,?,?)""",
            (category_id, tag_cn, tag_cn, tag_en, category["category_name_cn"], str(self.form.get("description", "")).strip(), json.dumps(sorted(set(keywords)), ensure_ascii=False), sort_row["next_sort"], 1, self.user["id"], now_iso()),
        )
        db.audit(self.user, "school_feature_tag_created", "school_library", record_id=tag_id, new_value=json.dumps({"category_id": category_id, "tag_name_cn": tag_cn}, ensure_ascii=False), ip=self.client_address[0], device=self.headers.get("User-Agent"))
        return self.flash_redirect(self.headers.get("Referer") or "/schools/library", "二级特色标签已创建。")

