    def school_feature_tag_manual_add(self, method, school_id):
        if method != "POST":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        if not (can_school_action(self.user, "add_manual_feature_tags") or can_school_action(self.user, "review_features")):
            return self.school_action_denied("add_manual_feature_tags")
        school = db.one("SELECT id FROM schools WHERE id=?", (school_id,))
        if not school:
            return self.error_page("学校不存在", HTTPStatus.NOT_FOUND)
        category_id = str(self.form.get("category_id", "")).strip()
        tag_id = str(self.form.get("tag_id", "")).strip()
        source_url = str(self.form.get("source_url", "")).strip()
        notes = str(self.form.get("notes", "")).strip()
        if not source_url and not notes:
            return self.flash_redirect(self.school_feature_center_url(school_id), "请填写手动添加该特色的原因或依据。", "error")
        tag = db.one("SELECT * FROM school_feature_tags WHERE id=? AND category_id=? AND is_active=1", (tag_id, category_id))
        if not tag:
            return self.flash_redirect(self.school_feature_center_url(school_id), "请选择有效的一级分类和二级标签。", "error")
        exists = db.one("SELECT id FROM school_feature_tag_assignments WHERE school_id=? AND tag_id=? AND status='Confirmed'", (school_id, tag_id))
        if exists:
            return self.flash_redirect(self.school_feature_center_url(school_id), "这个特色标签已经确认过。", "error")
        assignment_id = db.execute(
            """INSERT INTO school_feature_tag_assignments(
                school_id,category_id,tag_id,assignment_type,status,confidence_rate,source_url,source_title,source_type,
                source_excerpt,collected_at,confirmed_by,confirmed_at,notes,created_by,created_at
               ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
            (school_id, category_id, tag_id, "ManualAdded", "Confirmed", 100, source_url, source_url, "Manual", notes, now_iso(), self.user["id"], now_iso(), notes, self.user["id"], now_iso()),
        )
        self.refresh_school_dynamic_tags(school_id)
        db.audit(self.user, "school_feature_tag_manual_added", "school_library", record_id=assignment_id, new_value=json.dumps({"tag_id": tag_id, "source_url": source_url}, ensure_ascii=False), ip=self.client_address[0], device=self.headers.get("User-Agent"))
        return self.flash_redirect(self.school_feature_center_url(school_id), "学校特色标签已手动确认。")

    def school_feature_tag_collect(self, method, school_id):
        if method != "POST":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        if not (can_school_action(self.user, "collect_feature_tags") or can_school_action(self.user, "run_scraper")):
            return self.school_action_denied("collect_feature_tags")
        school = db.one("SELECT id FROM schools WHERE id=?", (school_id,))
        if not school:
            return self.error_page("学校不存在", HTTPStatus.NOT_FOUND)
        raw_urls = str(self.form.get("source_urls", "")).strip()
        urls = [line.strip() for line in raw_urls.splitlines() if line.strip()]
        trusted_ids = self.form.get("trusted_source_ids", [])
        if isinstance(trusted_ids, str):
            trusted_ids = [trusted_ids]
        for source_id in trusted_ids:
            row = db.one("SELECT source_url FROM school_trusted_sources WHERE id=? AND school_id=? AND is_active=1", (source_id, school_id))
            if row and row["source_url"]:
                urls.append(row["source_url"])
        urls = list(dict.fromkeys(urls))
        if not urls:
            return self.flash_redirect(self.school_feature_center_url(school_id), "请先提供或选择至少一个来源网址。source_url 必须存在。", "error")
        category_ids = self.form.get("category_ids", [])
        if isinstance(category_ids, str):
            category_ids = [category_ids]
        db.audit(self.user, "school_feature_collection_started", "school_library", record_id=school_id, new_value=json.dumps({"source_urls": urls, "category_ids": category_ids}, ensure_ascii=False), ip=self.client_address[0], device=self.headers.get("User-Agent"))
        inserted = 0
        failures = []
        for source_url in urls:
            try:
                title, text = self.school_feature_fetch_source_text(source_url)
                inserted += self.school_feature_collect_candidates(school_id, source_url, title, text, category_ids)
            except Exception as exc:
                failures.append(f"{source_url}: {exc}")
                db.audit(self.user, "school_feature_collection_failed", "school_library", record_id=school_id, file_path=source_url, error_message=str(exc), ip=self.client_address[0], device=self.headers.get("User-Agent"), status="failed")
        db.audit(self.user, "school_feature_collection_completed", "school_library", record_id=school_id, new_value=json.dumps({"suggestions_created": inserted, "failed": len(failures)}, ensure_ascii=False), ip=self.client_address[0], device=self.headers.get("User-Agent"))
        if failures and not inserted:
            return self.flash_redirect(self.school_feature_center_url(school_id), "采集未完成：" + "；".join(failures[:2]), "error")
        return self.flash_redirect(self.school_feature_center_url(school_id), f"采集完成，新增待审核建议 {inserted} 条。")

    def school_feature_tag_file_scan(self, method, school_id):
        if method != "POST":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        if not (can_school_action(self.user, "collect_feature_tags") or can_school_action(self.user, "run_scraper")):
            return self.school_action_denied("collect_feature_tags")
        school = db.one("SELECT * FROM schools WHERE id=?", (school_id,))
        if not school:
            return self.error_page("学校不存在", HTTPStatus.NOT_FOUND)
        uploads = [f for f in self.files if f.field_name == "feature_source_files" and f.filename]
        if not uploads:
            return self.flash_redirect(self.school_feature_center_url(school_id), "请选择要扫描的学校资料文件。", "error")
        tag_rows = db.all(
            """SELECT t.*,c.category_name_cn,c.category_name_en
               FROM school_feature_tags t
               LEFT JOIN school_feature_categories c ON c.id=t.category_id
               WHERE t.is_active=1 AND c.is_active=1
               ORDER BY c.sort_order,t.sort_order"""
        )
        db.audit(
            self.user,
            "school_feature_file_scan_started",
            "school_library",
            record_id=school_id,
            new_value=json.dumps({"file_count": len(uploads)}, ensure_ascii=False),
            ip=self.client_address[0],
            device=self.headers.get("User-Agent"),
        )
        folder = self.school_document_folder(school, "FeatureSource")
        inserted = 0
        empty_count = 0
        no_feature_count = 0
        failed = []
        scanned_files = []
        for upload in uploads:
            try:
                suffix = Path(upload.filename).suffix
                target, _ = next_version_path(folder, f"FeatureSource_{date.today().strftime('%Y%m%d')}_V1{suffix}")
                target.write_bytes(upload.data)
                doc_id = db.execute(
                    """INSERT INTO school_documents(school_id,document_type,original_filename,stored_filename,file_path,file_size,source_url,notes,uploaded_by,uploaded_at)
                       VALUES(?,?,?,?,?,?,?,?,?,?)""",
                    (
                        school_id,
                        "FeatureSource",
                        upload.filename,
                        target.name,
                        str(target),
                        len(upload.data),
                        "",
                        "学校特色标签文件扫描来源；扫描结果需人工确认后才进入正式特色库。",
                        self.user["id"],
                        now_iso(),
                    ),
                )
                self.school_record_source(school_id, "school_feature_tags", "FeatureSource", "", str(target), None, "uploaded file scan; suggestions only")
                result = extract_school_feature_matches_from_upload(upload, source_reference=str(target), tags=tag_rows)
                scanned_files.append({"filename": upload.filename, "stored_path": str(target), "status": result["status"], "matches": len(result["features"])})
                if result["status"] == "empty":
                    empty_count += 1
                elif result["status"] == "no_feature":
                    no_feature_count += 1
                for feature in result["features"]:
                    tag_id = feature.get("tag_id")
                    if not tag_id:
                        continue
                    exists = db.one(
                        """SELECT id FROM school_feature_tag_assignments
                           WHERE school_id=? AND tag_id=? AND source_title=? AND source_type='Uploaded File'
                             AND status IN ('Suggested','NeedsReview','Confirmed')""",
                        (school_id, tag_id, upload.filename),
                    )
                    if exists:
                        continue
                    notes = {
                        "source_file": str(target),
                        "matched_keywords": feature.get("matched_keywords") or [],
                        "document_id": doc_id,
                    }
                    assignment_id = db.execute(
                        """INSERT INTO school_feature_tag_assignments(
                            school_id,category_id,tag_id,assignment_type,status,confidence_rate,
                            source_url,source_title,source_type,source_excerpt,collected_at,collected_by_system,notes,created_by,created_at
                           ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                        (
                            school_id,
                            feature.get("category_id"),
                            tag_id,
                            "FileScan",
                            "Suggested",
                            feature.get("confidence_rate"),
                            "",
                            upload.filename,
                            "Uploaded File",
                            feature.get("source_excerpt") or feature.get("description") or "",
                            now_iso(),
                            1,
                            json.dumps(notes, ensure_ascii=False),
                            self.user["id"],
                            now_iso(),
                        ),
                    )
                    inserted += 1
                    db.audit(
                        self.user,
                        "school_feature_tag_suggested",
                        "school_library",
                        record_id=assignment_id,
                        student_id=school_id,
                        file_path=str(target),
                        new_value=json.dumps(
                            {"tag_id": tag_id, "confidence_rate": feature.get("confidence_rate"), "source_file": upload.filename, "review_status": "Suggested"},
                            ensure_ascii=False,
                        ),
                        ip=self.client_address[0],
                        device=self.headers.get("User-Agent"),
                    )
            except Exception as exc:
                failed.append(f"{upload.filename}: {exc}")
                db.audit(
                    self.user,
                    "school_feature_file_scan_failed",
                    "school_library",
                    record_id=school_id,
                    file_path=upload.filename,
                    error_message=str(exc),
                    ip=self.client_address[0],
                    device=self.headers.get("User-Agent"),
                    status="failed",
                )
        db.audit(
            self.user,
            "school_feature_file_scan_completed",
            "school_library",
            record_id=school_id,
            new_value=json.dumps(
                {
                    "files": len(uploads),
                    "suggestions_created": inserted,
                    "empty_files": empty_count,
                    "no_feature_files": no_feature_count,
                    "failed": len(failed),
                    "scanned_files": scanned_files,
                },
                ensure_ascii=False,
            ),
            ip=self.client_address[0],
            device=self.headers.get("User-Agent"),
            status="completed" if not failed else "partial",
        )
        if failed and not inserted:
            return self.flash_redirect(self.school_feature_center_url(school_id), "文件扫描失败：" + "；".join(failed[:2]), "error")
        message = f"文件扫描完成，新增待确认建议 {inserted} 条。"
        if empty_count or no_feature_count:
            message += f" 未识别内容/特色文件 {empty_count + no_feature_count} 个。"
        if failed:
            message += f" 失败 {len(failed)} 个。"
        return self.flash_redirect(self.school_feature_center_url(school_id), message, "warning" if failed else "")

    def school_feature_tag_confirm_all(self, method, school_id):
        if method != "POST":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        if not (can_school_action(self.user, "confirm_feature_tags") or can_school_action(self.user, "review_feature_suggestions")):
            return self.school_action_denied("confirm_feature_tags")
        school = db.one("SELECT id FROM schools WHERE id=?", (school_id,))
        if not school:
            return self.error_page("学校不存在", HTTPStatus.NOT_FOUND)
        rows = db.all(
            """SELECT id,tag_id,category_id,status
               FROM school_feature_tag_assignments
               WHERE school_id=? AND status='Suggested'
               ORDER BY id""",
            (school_id,),
        )
        if not rows:
            return self.flash_redirect(self.school_feature_center_url(school_id), "没有待确认的特色标签。", "warning")
        row_ids = [row["id"] for row in rows]
        now = now_iso()
        placeholders = ",".join("?" for _ in row_ids)
        db.execute(
            f"""UPDATE school_feature_tag_assignments
                   SET status='Confirmed',confirmed_by=?,confirmed_at=?,updated_by=?,updated_at=?
                 WHERE school_id=? AND status='Suggested' AND id IN ({placeholders})""",
            (self.user["id"], now, self.user["id"], now, school_id, *row_ids),
        )
        self.refresh_school_dynamic_tags(school_id)
        db.audit(
            self.user,
            "school_feature_tag_confirm_all",
            "school_library",
            record_id=school_id,
            old_value="Suggested",
            new_value=json.dumps(
                {
                    "new_status": "Confirmed",
                    "confirmed_count": len(row_ids),
                    "assignment_ids": row_ids[:200],
                },
                ensure_ascii=False,
            ),
            ip=self.client_address[0],
            device=self.headers.get("User-Agent"),
            status="completed",
        )
        return self.flash_redirect(self.school_feature_center_url(school_id), f"已全部确认 {len(row_ids)} 个学校特色标签。")

    def school_feature_tag_assignment_review(self, method, school_id, assignment_id):
        if method != "POST":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        action = str(self.form.get("review_action", "")).strip()
        if action == "confirm" and not (can_school_action(self.user, "confirm_feature_tags") or can_school_action(self.user, "review_feature_suggestions")):
            return self.school_action_denied("confirm_feature_tags")
        if action == "reject" and not (can_school_action(self.user, "reject_feature_tags") or can_school_action(self.user, "review_feature_suggestions")):
            return self.school_action_denied("reject_feature_tags")
        row = db.one("SELECT * FROM school_feature_tag_assignments WHERE id=? AND school_id=?", (assignment_id, school_id))
        if not row:
            return self.error_page("特色标签记录不存在", HTTPStatus.NOT_FOUND)
        if action == "confirm":
            db.execute("UPDATE school_feature_tag_assignments SET status='Confirmed',confirmed_by=?,confirmed_at=?,updated_by=?,updated_at=? WHERE id=?", (self.user["id"], now_iso(), self.user["id"], now_iso(), assignment_id))
            audit_action = "school_feature_tag_confirmed"
            msg = "特色标签已确认入库。"
        elif action == "reject":
            db.execute("UPDATE school_feature_tag_assignments SET status='Rejected',rejected_by=?,rejected_at=?,updated_by=?,updated_at=? WHERE id=?", (self.user["id"], now_iso(), self.user["id"], now_iso(), assignment_id))
            audit_action = "school_feature_tag_rejected"
            msg = "特色标签建议已拒绝。"
        else:
            return self.flash_redirect(self.school_feature_center_url(school_id), "未知审核动作。", "error")
        self.refresh_school_dynamic_tags(school_id)
        db.audit(self.user, audit_action, "school_library", record_id=assignment_id, old_value=row["status"], new_value=action, ip=self.client_address[0], device=self.headers.get("User-Agent"))
        return self.flash_redirect(self.school_feature_center_url(school_id), msg)

    def school_feature_tag_assignment_notes(self, method, school_id, assignment_id):
        if method != "POST":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        if not (can_school_action(self.user, "review_feature_suggestions") or can_school_action(self.user, "add_manual_feature_tags")):
            return self.school_action_denied("review_feature_suggestions")
        row = db.one("SELECT * FROM school_feature_tag_assignments WHERE id=? AND school_id=?", (assignment_id, school_id))
        if not row:
            return self.error_page("特色标签记录不存在", HTTPStatus.NOT_FOUND)
        notes = str(self.form.get("notes", "")).strip()
        db.execute("UPDATE school_feature_tag_assignments SET notes=?,updated_by=?,updated_at=? WHERE id=?", (notes, self.user["id"], now_iso(), assignment_id))
        db.audit(self.user, "school_feature_tag_notes_updated", "school_library", record_id=assignment_id, old_value=row["notes"], new_value=notes, ip=self.client_address[0], device=self.headers.get("User-Agent"))
        return self.flash_redirect(self.school_feature_center_url(school_id), "特色标签备注已保存。")

    def school_feature_add(self, method, school_id):
        if method != "POST":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        if not (can_school_action(self.user, "review_features") or can_school_action(self.user, "edit")):
            return self.school_action_denied("review_features")
        name = str(self.form.get("feature_name", "")).strip()
        if not name:
            return self.flash_redirect(self.school_feature_center_url(school_id), "Feature Name 为必填项。", "error")
        status = "Suggested" if str(self.form.get("source_type", "Manual")).strip().lower() != "manual" else "Approved"
        feature_id = db.execute(
            """INSERT INTO school_features(school_id,feature_category,feature_name,feature_description,source_type,source_url,confidence_score,review_status,approved_by,approved_at,notes,created_by,created_at)
               VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)""",
            (
                school_id, str(self.form.get("feature_category", "")).strip(), name,
                str(self.form.get("feature_description", "")).strip(), str(self.form.get("source_type", "Manual")).strip() or "Manual",
                str(self.form.get("source_url", "")).strip(), str(self.form.get("confidence_score", "")).strip() or None,
                status, self.user["id"] if status == "Approved" else None, now_iso() if status == "Approved" else None,
                str(self.form.get("notes", "")).strip(), self.user["id"], now_iso(),
            ),
        )
        self.refresh_school_dynamic_tags(school_id)
        db.audit(self.user, "school_feature_added", "school_library", record_id=feature_id, new_value=name, ip=self.client_address[0], device=self.headers.get("User-Agent"))
        return self.flash_redirect(self.school_feature_center_url(school_id), "学校特色已添加。")

    def school_feature_update(self, method, school_id, feature_id):
        if method != "POST":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        if not self.require_school_action("review_features"):
            return
        row = db.one("SELECT * FROM school_features WHERE id=? AND school_id=?", (feature_id, school_id))
        if not row:
            return self.error_page("特色不存在", HTTPStatus.NOT_FOUND)
        old_value = json.dumps(dict(row), ensure_ascii=False, default=str)
        db.execute(
            """UPDATE school_features SET feature_category=?,feature_name=?,feature_description=?,source_url=?,confidence_score=?,notes=?,updated_by=?,updated_at=? WHERE id=?""",
            (
                str(self.form.get("feature_category", "")).strip(), str(self.form.get("feature_name", "")).strip(),
                str(self.form.get("feature_description", "")).strip(), str(self.form.get("source_url", "")).strip(),
                str(self.form.get("confidence_score", "")).strip() or None, str(self.form.get("notes", "")).strip(),
                self.user["id"], now_iso(), feature_id,
            ),
        )
        self.refresh_school_dynamic_tags(school_id)
        db.audit(self.user, "school_feature_updated", "school_library", record_id=feature_id, old_value=old_value, new_value=str(self.form.get("feature_name", "")).strip(), ip=self.client_address[0], device=self.headers.get("User-Agent"))
        return self.flash_redirect(self.school_feature_center_url(school_id), "学校特色已保存。")

    def school_feature_review(self, method, school_id, feature_id):
        if method != "POST":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        if not self.require_school_action("review_features"):
            return
        status = str(self.form.get("review_status", "")).strip()
        if status not in {"Approved", "Rejected", "Suggested", "Merged"}:
            return self.flash_redirect(self.school_feature_center_url(school_id), "未知审核状态。", "error")
        db.execute("UPDATE school_features SET review_status=?,approved_by=?,approved_at=?,updated_by=?,updated_at=? WHERE id=? AND school_id=?", (status, self.user["id"] if status == "Approved" else None, now_iso() if status == "Approved" else None, self.user["id"], now_iso(), feature_id, school_id))
        self.refresh_school_dynamic_tags(school_id)
        db.audit(self.user, "school_feature_reviewed", "school_library", record_id=feature_id, new_value=status, ip=self.client_address[0], device=self.headers.get("User-Agent"))
        return self.flash_redirect(self.school_feature_center_url(school_id), f"特色已标记为 {status}。")

    def school_feature_merge(self, method, school_id):
        if method != "POST":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        if not self.require_school_action("review_features"):
            return
        source = str(self.form.get("source_feature_id", "")).strip()
        target = str(self.form.get("target_feature_id", "")).strip()
        if not source or not target or source == target:
            return self.flash_redirect(self.school_feature_center_url(school_id), "请输入正确的 merge feature ID。", "error")
        db.execute("UPDATE school_features SET review_status='Merged',merged_into_feature_id=?,updated_by=?,updated_at=? WHERE id=? AND school_id=?", (target, self.user["id"], now_iso(), source, school_id))
        self.refresh_school_dynamic_tags(school_id)
        db.audit(self.user, "school_feature_merged", "school_library", record_id=source, new_value=f"merged_into:{target}", ip=self.client_address[0], device=self.headers.get("User-Agent"))
        return self.flash_redirect(self.school_feature_center_url(school_id), "特色已合并。")

    def refresh_school_dynamic_tags(self, school_id):
        tags = [
            school_feature_tag_display_zh(row["tag_name"])
            for row in db.all(
                """SELECT COALESCE(t.tag_name_cn,t.tag_name_en,t.tag_name_zh) tag_name
                   FROM school_feature_tag_assignments a
                   JOIN school_feature_tags t ON t.id=a.tag_id
                   JOIN school_feature_categories c ON c.id=a.category_id
                   WHERE a.school_id=? AND a.status='Confirmed'
                   ORDER BY c.sort_order,t.sort_order LIMIT 30""",
                (school_id,),
            )
            if school_feature_tag_display_zh(row["tag_name"])
        ]
        legacy_tags = [row["feature_name"] for row in db.all("SELECT feature_name FROM school_features WHERE school_id=? AND review_status='Approved' ORDER BY feature_category,feature_name LIMIT 30", (school_id,))]
        for tag in legacy_tags:
            cleaned_tag = school_feature_tag_display_zh(tag)
            if cleaned_tag and cleaned_tag not in tags:
                tags.append(cleaned_tag)
        if tags:
            db.execute("UPDATE schools SET dynamic_tags_json=?,updated_at=? WHERE id=?", (json.dumps(tags, ensure_ascii=False), now_iso(), school_id))

    def school_area_profile_fetch(self, method, school_id):
        if method != "POST":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        if not (can_school_action(self.user, "fetch_abs_data") or can_school_action(self.user, "fetch_suburb_data")):
            return self.school_action_denied("fetch_abs_data")
        school = db.one("SELECT * FROM schools WHERE id=?", (school_id,))
        if not school:
            return self.error_page("学校不存在", HTTPStatus.NOT_FOUND)
        resolved_geo = self.school_area_profile_resolve_coordinates(school)
        detected = self.school_detect_suburb_from_address(school["address"] if "address" in school.keys() else "")
        suburb = str(self.form.get("suburb", "")).strip() or resolved_geo.get("suburb") or school["suburb"] or detected["suburb"]
        state = (str(self.form.get("state", "")).strip() or resolved_geo.get("state") or school["state"] or detected["state"]).upper()
        postcode = str(self.form.get("postcode", "")).strip() or resolved_geo.get("postcode") or school["postcode"] or detected["postcode"]
        latitude = school_area_metric_number(str(self.form.get("latitude", "")).strip()) if str(self.form.get("latitude", "")).strip() else resolved_geo.get("latitude")
        longitude = school_area_metric_number(str(self.form.get("longitude", "")).strip()) if str(self.form.get("longitude", "")).strip() else resolved_geo.get("longitude")
        data_year = abs_census_supported_year(str(self.form.get("data_year", "2021")).strip())
        state_code = ABS_STATE_CODE_BY_STATE.get(state, "")
        asgs_area = resolve_asgs_school_area(suburb, state, postcode)
        explicit_sa2 = re.sub(r"[^0-9]", "", str(self.form.get("sa2_code", "")).strip())
        if asgs_area:
            resolved_sa2 = {
                "code": asgs_area.get("sa2_code", ""),
                "state_code": state_code,
                "confidence": asgs_area.get("confidence", 92),
                "source": asgs_area.get("source", "ABS ASGS Edition 3 allocation files"),
            }
        elif explicit_sa2:
            resolved_sa2 = {"code": explicit_sa2, "state_code": state_code, "confidence": 90, "source": "Manual SA2 code"}
        else:
            resolved_sa2 = resolve_abs_sa2_code(suburb, state, postcode)
        if not resolved_sa2 or not resolved_sa2.get("code"):
            message = "尚未匹配 SA2，无法调用 ABS Data API。请先填写 SA2 Code，或补充更完整的学校地址/Suburb/Postcode。"
            db.audit(self.user, "school_area_profile_sa2_lookup_failed", "school_library", record_id=school_id, status="failed", error_message=message, ip=self.client_address[0], device=self.headers.get("User-Agent"))
            return self.flash_redirect(f"/schools/{school_id}#zone", message, "warning")
        dataflow = str(self.form.get("abs_dataflow", "ABS,C21_G02_SA2,1.0.0")).strip() or "ABS,C21_G02_SA2,1.0.0"
        data_key = str(self.form.get("abs_data_key", "")).strip()
        checked_at = now_iso()
        raw_payload = {}
        error_message = ""
        if data_key:
            try:
                api_url = build_abs_data_api_url(dataflow, data_key, start_period=data_year)
            except ValueError as exc:
                return self.flash_redirect(f"/schools/{school_id}#zone", f"ABS API 参数不完整：{exc}", "error")
            try:
                request = urllib.request.Request(
                    api_url,
                    headers={"User-Agent": "AAIE-CRM-School-Area-Profile/1.0", "Accept": "application/json"},
                )
                with urllib.request.urlopen(request, timeout=30) as response:
                    body = response.read(8_000_000).decode("utf-8", errors="replace")
                raw_payload = json.loads(body) if body.strip() else {}
            except urllib.error.HTTPError as exc:
                error_message = f"ABS API HTTP {exc.code}: {exc.reason}"
                raw_payload = {"error": error_message, "url": api_url}
            except Exception as exc:
                error_message = f"ABS API 采集失败：{exc}"
                raw_payload = {"error": error_message, "url": api_url}
            metrics = normalize_school_area_profile_metrics(raw_payload)
        else:
            census_result = fetch_abs_census_sa2_profile(resolved_sa2["code"], data_year)
            api_url = census_result["source_url"]
            error_message = census_result["error_message"]
            raw_payload = {
                "source": "ABS Census 2021 SA2 Data API",
                "urls": census_result["urls"],
                "errors": census_result["errors"],
                "flows": census_result["payloads"],
            }
            metrics = normalize_school_area_profile_metrics(census_result["profile"])
        metrics["notes"] = str(self.form.get("notes", "")).strip()
        profile = {
            "suburb": suburb,
            "postcode": postcode,
            "state": state,
            "latitude": latitude,
            "longitude": longitude,
            "sa1_code": asgs_area.get("sa1_code", "") if asgs_area else re.sub(r"[^0-9]", "", str(self.form.get("sa1_code", "")).strip()),
            "sa2_code": resolved_sa2["code"],
            "sa2_name": (asgs_area.get("sa2_name", "") if asgs_area else "") or str(self.form.get("sa2_name", "")).strip() or suburb,
            "sa3_code": (asgs_area.get("sa3_code", "") if asgs_area else "") or re.sub(r"[^0-9]", "", str(self.form.get("sa3_code", "")).strip()),
            "sa3_name": (asgs_area.get("sa3_name", "") if asgs_area else "") or str(self.form.get("sa3_name", "")).strip(),
            "sa4_code": (asgs_area.get("sa4_code", "") if asgs_area else "") or re.sub(r"[^0-9]", "", str(self.form.get("sa4_code", "")).strip()),
            "sa4_name": (asgs_area.get("sa4_name", "") if asgs_area else "") or str(self.form.get("sa4_name", "")).strip(),
            "lga_code": (asgs_area.get("lga_code", "") if asgs_area else "") or re.sub(r"[^0-9]", "", str(self.form.get("lga_code", "")).strip()),
            "lga_name": (asgs_area.get("lga_name", "") if asgs_area else "") or str(self.form.get("lga_name", "")).strip(),
            "data_year": data_year,
            "source": "ABS Data API",
            "source_url": api_url,
            "last_checked_at": checked_at,
            "review_status": "Needs Review",
            "confidence_score": resolved_sa2.get("confidence"),
            "raw_json": raw_payload,
            "notes": f"ASGS match source: {resolved_sa2.get('source','')}. ABS indicators without confirmed mapping remain blank.",
            "error_message": error_message,
        }
        profile_id = upsert_school_area_profile(db, school_id, profile, metrics, user_id=self.user["id"])
        suburb_data_id = sync_school_suburb_data_from_area_profile(db, school_id, profile_id, user_id=self.user["id"])
        self.school_record_source(school_id, "area_profile", "ABS Data API", api_url, "", resolved_sa2.get("confidence"), f"SA2 {resolved_sa2['code']} / Needs Review")
        db.audit(
            self.user,
            "school_area_profile_fetch_failed" if error_message else "school_area_profile_fetched",
            "school_library",
            record_id=school_id,
            file_path=api_url,
            new_value=json.dumps({"profile_id": profile_id, "suburb_data_id": suburb_data_id, "sa2_code": resolved_sa2["code"], "data_year": data_year}, ensure_ascii=False),
            error_message=error_message,
            status="failed" if error_message else "success",
            ip=self.client_address[0],
            device=self.headers.get("User-Agent"),
        )
        if error_message:
            return self.flash_redirect(f"/schools/{school_id}#zone", f"区域概况记录已保存，但 ABS 抓取失败：{error_message}", "error")
        return self.flash_redirect(f"/schools/{school_id}#zone", "所在区域概况已抓取并保存为待人工确认。")

    def school_area_profile_approve(self, method, school_id):
        if method != "POST":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        if not (can_school_action(self.user, "edit_suburb_data") or can_school_action(self.user, "edit_zone_data") or can_school_action(self.user, "edit")):
            return self.school_action_denied("edit_suburb_data")
        school = db.one("SELECT * FROM schools WHERE id=?", (school_id,))
        if not school:
            return self.error_page("学校不存在", HTTPStatus.NOT_FOUND)
        old_profile = self.school_latest_area_profile(school_id)
        try:
            result = approve_school_area_profile(db, school_id, user_id=self.user["id"])
        except ValueError:
            return self.flash_redirect(f"/schools/{school_id}#zone", "该学校还没有可确认的所在区域概况。", "warning")
        db.audit(
            self.user,
            "school_area_profile_approved",
            "school_library",
            record_id=school_id,
            old_value=old_profile["review_status"] if old_profile and "review_status" in old_profile.keys() else "",
            new_value=json.dumps(result, ensure_ascii=False),
            ip=self.client_address[0],
            device=self.headers.get("User-Agent"),
        )
        self.school_record_source(school_id, "area_profile", "School Area Profile", old_profile["source_url"] if old_profile and "source_url" in old_profile.keys() else "", "", old_profile["confidence_score"] if old_profile and "confidence_score" in old_profile.keys() else None, "Approved")
        return self.flash_redirect(f"/schools/{school_id}#zone", "所在区域数据已确认。")

    def school_zone_abs_fetch(self, method, school_id):
        if method != "POST":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        if not (can_school_action(self.user, "fetch_abs_data") or can_school_action(self.user, "fetch_suburb_data")):
            return self.school_action_denied("fetch_abs_data")
        school = db.one("SELECT * FROM schools WHERE id=?", (school_id,))
        if not school:
            return self.error_page("学校不存在", HTTPStatus.NOT_FOUND)
        detected = self.school_detect_suburb_from_address(school["address"] if "address" in school.keys() else "")
        suburb = str(self.form.get("suburb", "")).strip() or school["suburb"] or detected["suburb"]
        state = str(self.form.get("state", "")).strip().upper() or school["state"] or detected["state"]
        postcode = str(self.form.get("postcode", "")).strip() or school["postcode"] or detected["postcode"]
        explicit_sa2 = re.sub(r"[^0-9]", "", str(self.form.get("sa2_code", "")).strip())
        resolved = None
        if explicit_sa2:
            resolved = {
                "code": explicit_sa2,
                "geography_type": "SA2",
                "state_code": ABS_STATE_CODE_BY_STATE.get(state, ""),
                "suburb": suburb,
                "postcode": postcode,
                "source": "Manual SA2 code",
                "confidence": 75,
            }
        else:
            resolved = resolve_abs_sa2_code(suburb, state, postcode)
        if not resolved:
            message = f"ABS API 未调用：尚未匹配 SA2。School suburb={suburb or ''}, state={state or ''}, postcode={postcode or ''}。请先填写 SA2 Code 或确认 suburb/postcode。"
            db.audit(self.user, "abs_sa2_lookup_failed", "school_library", record_id=school_id, status="failed", error_message=message, ip=self.client_address[0], device=self.headers.get("User-Agent"))
            return self.flash_redirect(f"/schools/{school_id}#zone", message, "warning")
        suburb_id = self.school_ensure_suburb_record(suburb, state, postcode)
        if not suburb_id:
            return self.flash_redirect(f"/schools/{school_id}#zone", "无法建立 Suburb 记录，请检查输入。", "error")
        dataflow = str(self.form.get("abs_dataflow", "ABS,C21_G02_SA2,1.0.0")).strip() or "ABS,C21_G02_SA2,1.0.0"
        year = abs_census_supported_year(str(self.form.get("abs_year", "") or self.form.get("data_year", "2021")).strip())
        data_key = str(self.form.get("abs_data_key", "")).strip()
        retrieved_at = now_iso()
        error_message = ""
        raw_payload = {}
        if data_key:
            try:
                api_url = build_abs_data_api_url(dataflow, data_key, start_period=year)
            except ValueError as exc:
                return self.flash_redirect(f"/schools/{school_id}#zone", f"ABS API 参数不完整：{exc}", "error")
            try:
                request = urllib.request.Request(
                    api_url,
                    headers={"User-Agent": "AAIE-CRM-ABS-MVP/1.0", "Accept": "application/json"},
                )
                with urllib.request.urlopen(request, timeout=30) as response:
                    body = response.read(8_000_000).decode("utf-8", errors="replace")
                raw_payload = json.loads(body) if body.strip() else {}
                profile = normalize_abs_school_zone_profile(
                    raw_payload,
                    source_url=api_url,
                    geography_type="SA2",
                    geography_code=resolved["code"],
                    retrieved_at=retrieved_at,
                )
                review_status = "Needs Review"
                school_status = "Needs Review"
                audit_action = "abs_school_zone_data_fetched"
                flash_message = "ABS 学区数据已抓取并保存为待人工确认。"
                flash_kind = "success"
            except urllib.error.HTTPError as exc:
                error_message = f"ABS API HTTP {exc.code}: {exc.reason}"
                raw_payload = {"error": error_message, "url": api_url}
                profile = normalize_abs_school_zone_profile(raw_payload, source_url=api_url, geography_type="SA2", geography_code=resolved["code"], retrieved_at=retrieved_at)
                review_status = "Needs Review"
                school_status = "Error"
                audit_action = "abs_school_zone_data_fetch_failed"
                flash_message = f"ABS API 采集失败：{error_message}"
                flash_kind = "error"
        else:
            census_result = fetch_abs_census_sa2_profile(resolved["code"], year)
            api_url = census_result["source_url"]
            error_message = census_result["error_message"]
            raw_payload = {
                "source": "ABS Census 2021 SA2 Data API",
                "urls": census_result["urls"],
                "errors": census_result["errors"],
                "flows": census_result["payloads"],
            }
            profile = census_result["profile"]
            profile["source_url"] = api_url
            profile["geography_type"] = "SA2"
            profile["geography_code"] = resolved["code"]
            profile["retrieved_at"] = retrieved_at
            review_status = "Needs Review"
            school_status = "Error" if error_message else "Needs Review"
            audit_action = "abs_school_zone_data_fetch_failed" if error_message else "abs_school_zone_data_fetched"
            flash_message = f"ABS API 采集失败：{error_message}" if error_message else "ABS 学区数据已抓取并保存为待人工确认。"
            flash_kind = "error" if error_message else "success"
        existing = db.one(
            """SELECT * FROM school_suburb_data
               WHERE suburb_id=? AND source_name='ABS Data API' AND geography_type='SA2' AND geography_code=?
               ORDER BY updated_at DESC,id DESC LIMIT 1""",
            (suburb_id, resolved["code"]),
        )
        values = {
            "suburb_id": suburb_id,
            "data_year": year,
            "source_name": "ABS Data API",
            "source_url": api_url,
            "source_type": "Official",
            "fetched_at": retrieved_at,
            "fetched_by": self.user["id"],
            "reviewed_status": review_status,
            "reviewed_by": None,
            "reviewed_at": None,
            "confidence_score": resolved.get("confidence", 80),
            "population_total": profile.get("population_total"),
            "population_male": profile.get("population_male"),
            "population_female": profile.get("population_female"),
            "median_age": profile.get("median_age"),
            "family_count": profile.get("family_count"),
            "household_count": profile.get("household_count"),
            "average_household_size": profile.get("average_household_size"),
            "median_personal_income_weekly": profile.get("median_personal_income_weekly"),
            "median_family_income_weekly": profile.get("median_family_income_weekly"),
            "median_household_income_weekly": profile.get("median_household_income_weekly"),
            "english_only_percentage": profile.get("english_only_percentage"),
            "non_english_language_percentage": profile.get("non_english_language_percentage"),
            "year_12_completion_percentage": profile.get("year_12_completion_percentage"),
            "born_overseas_percentage": profile.get("overseas_born_percent"),
            "education_summary": profile.get("education_summary", ""),
            "top_languages_json": profile.get("top_languages_json", ""),
            "top_birth_countries_json": profile.get("top_birth_countries_json", ""),
            "other_indicators_json": profile.get("other_indicators_json") or json.dumps(
                {
                    "median_rent": profile.get("median_rent"),
                    "median_mortgage_repayment": profile.get("median_mortgage_repayment"),
                    "school_age_children_count": profile.get("school_age_children_count"),
                    "family_household_percent": profile.get("family_household_percent"),
                    "abs_census_flow_urls": raw_payload.get("urls", {}) if isinstance(raw_payload, dict) else {},
                },
                ensure_ascii=False,
            ),
            "geography_type": "SA2",
            "geography_code": resolved["code"],
            "retrieved_at": retrieved_at,
            "raw_json": profile.get("raw_json", json.dumps(raw_payload, ensure_ascii=False)[:200000]),
            "notes": f"ABS official Data API. Suburb/postcode mapped to SA2; mapping source: {resolved.get('source','')}. Human review required before reports.",
            "error_message": error_message,
            "updated_at": now_iso(),
            "updated_by": self.user["id"],
        }
        if existing:
            columns = [column for column in values if column != "suburb_id"]
            db.execute(
                f"UPDATE school_suburb_data SET {','.join(f'{column}=?' for column in columns)} WHERE id=?",
                tuple(values[column] for column in columns) + (existing["id"],),
            )
            data_id = existing["id"]
        else:
            values["created_at"] = now_iso()
            columns = list(values)
            data_id = db.execute(
                f"INSERT INTO school_suburb_data({','.join(columns)}) VALUES({','.join('?' for _ in columns)})",
                tuple(values[column] for column in columns),
            )
        db.execute(
            """UPDATE schools SET suburb=?,state=?,postcode=?,suburb_id=?,suburb_data_status=?,
               suburb_data_last_updated=?,zone_data_json=?,updated_at=?,updated_by=?,last_updated_by=?,last_updated_at=?
               WHERE id=?""",
            (
                suburb, state, postcode, suburb_id, school_status, retrieved_at,
                json.dumps({"suburb_id": suburb_id, "suburb_data_id": data_id, "geography_type": "SA2", "geography_code": resolved["code"], "source_url": api_url}, ensure_ascii=False),
                now_iso(), self.user["id"], self.user["id"], now_iso(), school_id,
            ),
        )
        self.school_record_source(school_id, "zone_data", "ABS Data API", api_url, "", resolved.get("confidence", 80), f"SA2 {resolved['code']} / {review_status}")
        db.audit(
            self.user,
            audit_action,
            "school_library",
            record_id=school_id,
            file_path=api_url,
            new_value=json.dumps({"suburb_data_id": data_id, "geography_type": "SA2", "geography_code": resolved["code"], "dataflow": dataflow, "data_key": data_key, "year": year}, ensure_ascii=False),
            error_message=error_message,
            status="failed" if error_message else "success",
            ip=self.client_address[0],
            device=self.headers.get("User-Agent"),
        )
        return self.flash_redirect(f"/schools/{school_id}#zone", flash_message, flash_kind)

    def school_zone_update(self, method, school_id):
        if method != "POST":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        if not (can_school_action(self.user, "edit_suburb_data") or can_school_action(self.user, "edit_zone_data") or can_school_action(self.user, "edit")):
            return self.school_action_denied("edit_suburb_data")
        school = db.one("SELECT * FROM schools WHERE id=?", (school_id,))
        if not school:
            return self.error_page("学校不存在", HTTPStatus.NOT_FOUND)
        detected = self.school_detect_suburb_from_address(school["address"] if "address" in school.keys() else "")
        suburb = str(self.form.get("suburb", "")).strip() or detected["suburb"] or school["suburb"] or ""
        state = str(self.form.get("state", "")).strip().upper() or detected["state"] or school["state"] or ""
        postcode = str(self.form.get("postcode", "")).strip() or detected["postcode"] or school["postcode"] or ""
        country = str(self.form.get("country", "")).strip() or "Australia"
        if not suburb or not state:
            db.audit(self.user, "suburb_data_fetch_failed", "school_library", record_id=school_id, error_message="suburb/state missing", ip=self.client_address[0], device=self.headers.get("User-Agent"), status="failed")
            return self.flash_redirect(f"/schools/{school_id}#zone", "Suburb 和 State 为必填项；如果地址无法自动识别，请手动填写。", "error")
        old_suburb_value = json.dumps({
            "suburb_id": school["suburb_id"] if "suburb_id" in school.keys() else "",
            "suburb": school["suburb"] if "suburb" in school.keys() else "",
            "state": school["state"] if "state" in school.keys() else "",
            "postcode": school["postcode"] if "postcode" in school.keys() else "",
        }, ensure_ascii=False)
        suburb_id = self.school_ensure_suburb_record(suburb, state, postcode, country)
        if not suburb_id:
            return self.flash_redirect(f"/schools/{school_id}#zone", "无法建立 Suburb 记录，请检查输入。", "error")
        if str(school["suburb_id"] if "suburb_id" in school.keys() and school["suburb_id"] else "") != str(suburb_id):
            db.audit(self.user, "school_suburb_detected", "school_library", record_id=school_id, old_value=old_suburb_value, new_value=json.dumps({"suburb_id": suburb_id, "suburb": suburb, "state": state, "postcode": postcode}, ensure_ascii=False), ip=self.client_address[0], device=self.headers.get("User-Agent"))
        elif (school["suburb"] or "") != suburb or (school["postcode"] or "") != postcode or (school["state"] or "") != state:
            db.audit(self.user, "school_suburb_corrected", "school_library", record_id=school_id, old_value=old_suburb_value, new_value=json.dumps({"suburb_id": suburb_id, "suburb": suburb, "state": state, "postcode": postcode}, ensure_ascii=False), ip=self.client_address[0], device=self.headers.get("User-Agent"))
        data = {name: str(self.form.get(name, "")).strip() for name, _label, _group in SCHOOL_SUBURB_DATA_FIELDS}
        meta = {
            "data_year": str(self.form.get("data_year", "")).strip() or str(current_year()),
            "source_name": str(self.form.get("source_name", "")).strip() or "Manual AAIE Entry",
            "source_url": str(self.form.get("source_url", "")).strip(),
            "source_type": str(self.form.get("source_type", "")).strip() or "Manual",
            "reviewed_status": str(self.form.get("reviewed_status", "")).strip() or "Needs Review",
            "confidence_score": str(self.form.get("confidence_score", "")).strip() or None,
            "notes": str(self.form.get("notes", "")).strip(),
            "error_message": str(self.form.get("error_message", "")).strip(),
        }
        if meta["reviewed_status"] not in {value for value, _label in SCHOOL_SUBURB_REVIEW_STATUS_OPTIONS}:
            meta["reviewed_status"] = "Needs Review"
        numeric_fields = {
            "population_total", "population_male", "population_female", "family_count", "couple_family_count",
            "single_parent_family_count", "household_count", "median_personal_income_weekly",
            "median_family_income_weekly", "median_household_income_weekly",
        }
        decimal_fields = {
            "median_age", "average_household_size", "english_only_percentage", "non_english_language_percentage",
            "bachelor_or_above_percentage", "year_12_completion_percentage", "born_overseas_percentage",
            "separate_house_percentage", "apartment_percentage", "rented_percentage", "owned_percentage",
        }
        clean_data = {}
        try:
            for key, value in data.items():
                if key in numeric_fields:
                    clean_data[key] = int(float(value)) if value else None
                elif key in decimal_fields:
                    clean_data[key] = float(value) if value else None
                else:
                    clean_data[key] = value
        except ValueError:
            return self.flash_redirect(f"/schools/{school_id}#zone", "学区数据中的人口、收入、比例字段只能填写数字。", "error")
        try:
            confidence_score = float(meta["confidence_score"]) if meta["confidence_score"] not in {None, ""} else None
        except ValueError:
            confidence_score = None
        geography_type = str(self.form.get("geography_type", "")).strip() or "SA2"
        sa1_code = re.sub(r"[^0-9]", "", str(self.form.get("sa1_code", "")).strip())
        sa2_code = re.sub(r"[^0-9]", "", str(self.form.get("sa2_code", "")).strip())
        sa3_code = re.sub(r"[^0-9]", "", str(self.form.get("sa3_code", "")).strip())
        sa4_code = re.sub(r"[^0-9]", "", str(self.form.get("sa4_code", "")).strip())
        lga_code = re.sub(r"[^0-9]", "", str(self.form.get("lga_code", "")).strip())
        geography_code = sa2_code if geography_type.upper() == "SA2" else re.sub(r"[^0-9]", "", str(self.form.get("geography_code", "")).strip())
        area_meta = {
            "sa1_code": sa1_code,
            "sa2_code": sa2_code,
            "sa2_name": str(self.form.get("sa2_name", "")).strip(),
            "sa3_code": sa3_code,
            "sa3_name": str(self.form.get("sa3_name", "")).strip(),
            "sa4_code": sa4_code,
            "sa4_name": str(self.form.get("sa4_name", "")).strip(),
            "lga_code": lga_code,
            "lga_name": str(self.form.get("lga_name", "")).strip(),
        }
        other_indicators = {}
        raw_other_indicators = clean_data.get("other_indicators_json", "")
        if raw_other_indicators:
            try:
                parsed_other = json.loads(raw_other_indicators)
                if isinstance(parsed_other, dict):
                    other_indicators = parsed_other
                else:
                    other_indicators = {"manual_other_indicators": parsed_other}
            except Exception:
                other_indicators = {"manual_other_indicators_note": raw_other_indicators}
        for key, value in area_meta.items():
            if value not in {None, ""}:
                other_indicators[key] = value
        if other_indicators:
            clean_data["other_indicators_json"] = json.dumps(other_indicators, ensure_ascii=False)
        latitude_value = school_area_metric_number(str(self.form.get("latitude", "")).strip())
        longitude_value = school_area_metric_number(str(self.form.get("longitude", "")).strip())
        if latitude_value is None and "latitude" in school.keys():
            latitude_value = school["latitude"]
        if longitude_value is None and "longitude" in school.keys():
            longitude_value = school["longitude"]
        old_data = None
        data_id = str(self.form.get("data_id", "")).strip()
        if data_id:
            old_data = db.one("SELECT * FROM school_suburb_data WHERE id=? AND suburb_id=?", (data_id, suburb_id))
        if not old_data:
            old_data = db.one(
                "SELECT * FROM school_suburb_data WHERE suburb_id=? AND data_year=? AND source_name=? ORDER BY updated_at DESC,id DESC LIMIT 1",
                (suburb_id, meta["data_year"], meta["source_name"]),
            )
        reviewed_by = self.user["id"] if meta["reviewed_status"] in {"Approved", "Rejected", "Updated"} else None
        reviewed_at = now_iso() if reviewed_by else None
        values = {
            "suburb_id": suburb_id,
            "data_year": meta["data_year"],
            "source_name": meta["source_name"],
            "source_url": meta["source_url"],
            "source_type": meta["source_type"],
            "fetched_at": old_data["fetched_at"] if old_data and old_data["fetched_at"] else now_iso(),
            "fetched_by": old_data["fetched_by"] if old_data and "fetched_by" in old_data.keys() else self.user["id"],
            "reviewed_status": meta["reviewed_status"],
            "reviewed_by": reviewed_by,
            "reviewed_at": reviewed_at,
            "confidence_score": confidence_score,
            "geography_type": geography_type,
            "geography_code": geography_code,
            "retrieved_at": old_data["retrieved_at"] if old_data and "retrieved_at" in old_data.keys() and old_data["retrieved_at"] else None,
            "raw_json": old_data["raw_json"] if old_data and "raw_json" in old_data.keys() and old_data["raw_json"] else "",
            **clean_data,
            "notes": meta["notes"],
            "error_message": meta["error_message"],
            "updated_at": now_iso(),
            "updated_by": self.user["id"],
        }
        if old_data:
            update_columns = [column for column in values.keys() if column != "suburb_id"]
            db.execute(
                f"UPDATE school_suburb_data SET {','.join(f'{column}=?' for column in update_columns)} WHERE id=?",
                tuple(values[column] for column in update_columns) + (old_data["id"],),
            )
            suburb_data_id = old_data["id"]
            audit_action = "suburb_data_updated"
        else:
            values["created_at"] = now_iso()
            columns = list(values.keys())
            suburb_data_id = db.execute(
                f"INSERT INTO school_suburb_data({','.join(columns)}) VALUES({','.join('?' for _ in columns)})",
                tuple(values[column] for column in columns),
            )
            audit_action = "suburb_data_fetch_completed" if meta["source_type"] != "Manual" else "suburb_data_updated"
        school_status = "Reviewed" if meta["reviewed_status"] in {"Approved", "Updated"} else ("Error" if meta["error_message"] else meta["reviewed_status"])
        zone_data_payload = {
            "suburb_id": suburb_id,
            "suburb_data_id": suburb_data_id,
            "reviewed_status": meta["reviewed_status"],
            "source_name": meta["source_name"],
            "source_url": meta["source_url"],
            "geography_type": geography_type,
            "geography_code": geography_code,
            **{key: value for key, value in area_meta.items() if value not in {None, ""}},
        }
        db.execute(
            """UPDATE schools SET suburb=?,state=?,postcode=?,suburb_id=?,suburb_data_status=?,
               suburb_data_last_updated=?,zone_data_json=?,latitude=?,longitude=?,updated_at=?,updated_by=?,last_updated_by=?,last_updated_at=?
               WHERE id=?""",
            (
                suburb, state, postcode, suburb_id, school_status, now_iso(),
                json.dumps(zone_data_payload, ensure_ascii=False), latitude_value, longitude_value,
                now_iso(), self.user["id"], self.user["id"], now_iso(), school_id,
            ),
        )
        db.audit(self.user, audit_action, "school_library", record_id=school_id, old_value=json.dumps(dict(old_data) if old_data else {}, ensure_ascii=False, default=str), new_value=json.dumps({"suburb_id": suburb_id, "suburb_data_id": suburb_data_id, **meta}, ensure_ascii=False), file_path=meta["source_url"], ip=self.client_address[0], device=self.headers.get("User-Agent"))
        db.audit(self.user, "school_zone_data_updated", "school_library", record_id=school_id, old_value=json.dumps(dict(old_data) if old_data else {}, ensure_ascii=False, default=str), new_value=json.dumps({"suburb_id": suburb_id, "suburb_data_id": suburb_data_id, **meta}, ensure_ascii=False), file_path=meta["source_url"], ip=self.client_address[0], device=self.headers.get("User-Agent"))
        if meta["reviewed_status"] in {"Approved", "Rejected", "Updated"}:
            db.audit(self.user, "suburb_data_reviewed", "school_library", record_id=school_id, old_value=old_data["reviewed_status"] if old_data else "", new_value=meta["reviewed_status"], ip=self.client_address[0], device=self.headers.get("User-Agent"))
        self.school_record_source(school_id, "zone_data", "school_suburb_data", meta["source_url"], "", confidence_score, f"{meta['source_name']} / {meta['reviewed_status']}")
        return self.flash_redirect(f"/schools/{school_id}#zone", "学区数据已保存。")

    def school_good_schools_validate_url(self, url):
        url = str(url or "").strip()
        if not url:
            return ""
        parsed = urlparse(url)
        if parsed.scheme not in {"http", "https"}:
            raise ValueError("Good Schools URL 必须是 http/https。")
        host = parsed.netloc.lower()
        if GOOD_SCHOOLS_BASE_DOMAIN not in host:
            raise ValueError("MVP 只允许 goodschools.com.au 页面作为 Good Schools Guide 来源。")
        return url

    def school_good_schools_fetch_page(self, url):
        self.school_good_schools_validate_url(url)
        request = urllib.request.Request(
            url,
            headers={
                "User-Agent": "AAIE-CRM-SchoolModule/1.0 (+internal-testing)",
                "Accept": "text/html,application/xhtml+xml,text/plain",
            },
        )
        with urllib.request.urlopen(request, timeout=10) as response:
            status = getattr(response, "status", 200)
            raw = response.read(900_000)
            content_type = response.headers.get("Content-Type", "")
        if status >= 400:
            raise urllib.error.HTTPError(url, status, f"HTTP {status}", {}, None)
        if "html" not in content_type.lower() and "text" not in content_type.lower():
            raise ValueError(f"Unsupported Good Schools content type: {content_type}")
        text = raw.decode("utf-8", errors="ignore")
        cache_dir = APP_DIR / "cache" / "good_schools"
        cache_dir.mkdir(parents=True, exist_ok=True)
        cache_name = hashlib.sha256(url.encode("utf-8")).hexdigest()[:16] + ".html"
        (cache_dir / cache_name).write_text(text, encoding="utf-8")
        return text

    def school_good_schools_text(self, raw):
        raw = raw or ""
        title = ""
        title_match = re.search(r"<title[^>]*>(.*?)</title>", raw, re.I | re.S)
        if title_match:
            title = html.unescape(re.sub(r"\s+", " ", title_match.group(1))).strip()
        meta_match = re.search(r"""<meta[^>]+name=["']description["'][^>]+content=["']([^"']+)["']""", raw, re.I)
        description = html.unescape(meta_match.group(1)).strip() if meta_match else ""
        text = re.sub(r"(?is)<(script|style).*?>.*?</\1>", " ", raw)
        text = re.sub(r"(?s)<[^>]+>", " ", text)
        text = html.unescape(re.sub(r"\s+", " ", text)).strip()
        return title, description, text

    def school_good_schools_extract(self, combined_text, title, description, urls):
        compact = re.sub(r"\s+", " ", combined_text or "").strip()
        data = {field: "" for field, _label in GOOD_SCHOOLS_PROFILE_FIELDS}
        data["third_party_description"] = description or compact[:900]
        data["third_party_summary"] = compact[:420]
        title_name = re.sub(r"\s*\|\s*.*$", "", title or "").strip()
        if title_name and len(title_name) < 120:
            data["school_name"] = title_name
        address_match = re.search(r"([A-Za-z0-9 ,.'/-]{8,120}?\b(VIC|NSW|QLD|WA|SA|TAS|ACT|NT)\s+(\d{4})\b)", compact, re.I)
        if address_match:
            data["address"] = address_match.group(1).strip(" ,")
            data["state"] = address_match.group(2).upper()
            data["postcode"] = address_match.group(3)
            suburb_match = re.search(r"\b([A-Za-z][A-Za-z .'-]+)\s+" + re.escape(data["state"]) + r"\s+" + re.escape(data["postcode"]), data["address"], re.I)
            if suburb_match:
                data["suburb"] = re.sub(r"\s+", " ", suburb_match.group(1)).strip().split(",")[-1].strip()
        website_match = re.search(r"(https?://(?:www\.)?(?!goodschools\.com\.au)[A-Za-z0-9./?&_%#=-]*\.[A-Za-z]{2,}[A-Za-z0-9./?&_%#=-]*)", compact)
        if website_match:
            data["website"] = website_match.group(1)
        for label, patterns in {
            "sector": ["Independent", "Catholic", "Government", "Public", "Private"],
            "gender": ["Co-ed", "Coeducational", "Boys", "Girls"],
            "school_type": ["Primary", "Secondary", "Combined", "Grammar", "College"],
        }.items():
            found = [value for value in patterns if re.search(rf"\b{re.escape(value)}\b", compact, re.I)]
            if found:
                data[label] = ", ".join(dict.fromkeys(found))
        years = sorted(set(re.findall(r"\bYear\s*(?:[PK]|\d{1,2})\b", compact, re.I)), key=lambda item: item.lower())
        if years:
            data["year_levels"] = ", ".join(years[:16])
        religion_match = re.search(r"\b(Anglican|Catholic|Uniting Church|Christian|Jewish|Baptist|Presbyterian|Lutheran)\b", compact, re.I)
        if religion_match:
            data["religion"] = religion_match.group(1)
        phone_match = re.search(r"(\+?61\s?\d\s?\d{4}\s?\d{4}|\(?0\d\)?\s?\d{4}\s?\d{4})", compact)
        email_match = re.search(r"[\w.+-]+@[\w.-]+\.[A-Za-z]{2,}", compact)
        contact = []
        if phone_match:
            contact.append(phone_match.group(1))
        if email_match:
            contact.append(email_match.group(0))
        data["contact_details"] = " · ".join(contact)
        data["location_page_url"] = urls.get("location_url", "")
        strengths = []
        for keyword in ["boarding", "scholarship", "music", "sport", "leadership", "international", "academic", "wellbeing", "STEM", "outdoor"]:
            if re.search(rf"\b{keyword}\b", compact, re.I):
                strengths.append(keyword)
        data["strengths_json"] = json.dumps(strengths[:12], ensure_ascii=False)
        return data

    def school_good_schools_extract_fees(self, text):
        rows = []
        for keyword in ["application fee", "enrolment fee", "tuition", "boarding", "international"]:
            pattern = rf"(.{{0,80}}{keyword}.{{0,120}}?(?:AUD|\$)\s?[\d,]+(?:\.\d+)?.{{0,80}})"
            for match in re.finditer(pattern, text or "", re.I):
                raw = re.sub(r"\s+", " ", match.group(1)).strip()
                amount = re.search(r"(?:AUD|\$)\s?([\d,]+(?:\.\d+)?)", raw, re.I)
                year_level = re.search(r"\b(Year\s*\d{1,2}|Prep|Foundation)\b", raw, re.I)
                fee_year = re.search(r"\b(20\d{2})\b", raw)
                rows.append({
                    "fee_type": keyword.title(),
                    "year_level": year_level.group(1) if year_level else "",
                    "amount": amount.group(1) if amount else "",
                    "fee_year": fee_year.group(1) if fee_year else str(current_year()),
                    "raw_text": raw,
                })
        return rows[:20]

    def school_good_schools_extract_academic(self, text):
        rows = []
        for indicator in ["reading", "writing", "spelling", "grammar", "numeracy", "naplan"]:
            pattern = rf"(.{{0,80}}{indicator}.{{0,120}})"
            for match in re.finditer(pattern, text or "", re.I):
                raw = re.sub(r"\s+", " ", match.group(1)).strip()
                year_level = re.search(r"\b(Year\s*\d{1,2})\b", raw, re.I)
                data_year = re.search(r"\b(20\d{2})\b", raw)
                value = re.search(r"\b(\d{2,4}(?:\.\d+)?)\b", raw)
                rows.append({
                    "indicator_name": indicator.upper() if indicator == "naplan" else f"NAPLAN {indicator.title()}",
                    "year_level": year_level.group(1) if year_level else "",
                    "data_year": data_year.group(1) if data_year else "",
                    "indicator_value": value.group(1) if value else "",
                    "comparison_notes": raw,
                    "raw_text": raw,
                })
        return rows[:20]

    def school_good_schools_extract_comparisons(self, text):
        rows = []
        for match in re.finditer(r"([A-Z][A-Za-z'&.\- ]{3,80}\s+(?:School|College|Grammar))", text or ""):
            name = re.sub(r"\s+", " ", match.group(1)).strip()
            if len(name.split()) < 2:
                continue
            rows.append({"nearby_school_name": name, "comparison_notes": "Good Schools nearby/comparison text", "raw_text": name})
        deduped = []
        seen = set()
        for row in rows:
            key = row["nearby_school_name"].lower()
            if key not in seen:
                seen.add(key)
                deduped.append(row)
        return deduped[:20]

    def school_good_schools_record_conflicts(self, school, source_url, extracted):
        field_map = {
            "school_name": "school_name",
            "address": "address",
            "website": "website_url",
            "school_type": "school_type",
            "gender": "school_gender_type",
            "year_levels": "year_levels",
            "suburb": "suburb",
            "postcode": "postcode",
            "state": "state",
        }
        for extracted_field, school_field in field_map.items():
            third_value = str(extracted.get(extracted_field) or "").strip()
            official_value = str(school[school_field] if school_field in school.keys() and school[school_field] else "").strip()
            if not third_value or not official_value or third_value.lower() == official_value.lower():
                continue
            db.execute(
                """INSERT INTO school_data_conflicts(school_id,source_name,source_url,field_name,official_value,third_party_value,notes,created_at,updated_at)
                   VALUES(?,?,?,?,?,?,?,?,?)""",
                (school["id"], GOOD_SCHOOLS_SOURCE_NAME, source_url, extracted_field, official_value, third_value, "third_party_profile", now_iso(), now_iso()),
            )

    def school_good_schools_update(self, method, school_id):
        if method != "POST":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        if not (can_school_action(self.user, "run_scraper") or can_school_action(self.user, "edit")):
            return self.school_action_denied("run_scraper")
        school = db.one("SELECT * FROM schools WHERE id=?", (school_id,))
        if not school:
            return self.error_page("学校不存在", HTTPStatus.NOT_FOUND)
        urls = {
            "profile_url": str(self.form.get("profile_url", "")).strip(),
            "about_url": str(self.form.get("about_url", "")).strip(),
            "fees_url": str(self.form.get("fees_url", "")).strip(),
            "naplan_url": str(self.form.get("naplan_url", "")).strip(),
            "location_url": str(self.form.get("location_url", "")).strip(),
        }
        try:
            urls = {key: self.school_good_schools_validate_url(value) for key, value in urls.items()}
        except ValueError as exc:
            return self.flash_redirect(f"/schools/{school_id}#good-schools", str(exc), "error")
        if not urls["profile_url"]:
            return self.flash_redirect(f"/schools/{school_id}#good-schools", "Good Schools Profile URL 为必填项。", "error")
        action_type = str(self.form.get("action_type", "fetch")).strip()
        manual_text = str(self.form.get("manual_text", "")).strip()
        notes = str(self.form.get("notes", "")).strip()
        review_status = str(self.form.get("review_status", "Needs Review")).strip() or "Needs Review"
        if review_status not in {value for value, _label in SCHOOL_SUBURB_REVIEW_STATUS_OPTIONS}:
            review_status = "Needs Review"
        raw_parts = []
        errors = []
        if action_type == "manual" and manual_text:
            raw_parts.append(manual_text)
            fetch_status = "manual_paste"
        else:
            fetch_status = "success"
            for source_url in [value for value in urls.values() if value]:
                try:
                    raw_parts.append(self.school_good_schools_fetch_page(source_url))
                    time.sleep(0.6)
                except Exception as exc:
                    errors.append(f"{source_url}: {exc}")
            if not raw_parts and manual_text:
                raw_parts.append(manual_text)
                fetch_status = "manual_paste_after_fetch_failed"
            elif errors:
                fetch_status = "partial_error" if raw_parts else "fetch_error"
        stamp = now_iso()
        raw_combined = "\n".join(raw_parts)
        if not raw_combined:
            db.execute(
                """INSERT INTO school_third_party_profiles(
                   school_id,source_name,source_url,profile_url,about_url,fees_url,naplan_url,location_url,
                   fetched_at,review_status,fetch_status,error_message,notes,created_at,updated_at,updated_by
                ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                (school_id, GOOD_SCHOOLS_SOURCE_NAME, urls["profile_url"], urls["profile_url"], urls["about_url"], urls["fees_url"], urls["naplan_url"], urls["location_url"], stamp, "Needs Review", "fetch_error", "; ".join(errors), notes, stamp, stamp, self.user["id"]),
            )
            db.audit(self.user, "good_schools_fetch_failed", "school_library", record_id=school_id, file_path=urls["profile_url"], error_message="; ".join(errors), ip=self.client_address[0], device=self.headers.get("User-Agent"), status="failed")
            self.school_record_source(school_id, "third_party_profile", GOOD_SCHOOLS_SOURCE_NAME, urls["profile_url"], "", 0, "fetch_error")
            return self.flash_redirect(f"/schools/{school_id}#good-schools", "Good Schools 抓取失败，已记录错误。可以使用手动粘贴 fallback。", "error")
        title, description, plain_text = self.school_good_schools_text(raw_combined)
        extracted = self.school_good_schools_extract(plain_text, title, description, urls)
        good_schools_activities = extract_good_schools_activities_from_text(plain_text)
        raw_extract = json.dumps({"urls": urls, "errors": errors, "title": title, "activity_categories": good_schools_activities}, ensure_ascii=False)
        columns = [
            "school_id", "source_name", "source_url", "profile_url", "about_url", "fees_url", "naplan_url", "location_url",
            "fetched_at", "review_status", "school_name", "address", "suburb", "postcode", "state", "website", "school_type",
            "sector", "gender", "year_levels", "religion", "contact_details", "location_page_url", "third_party_description",
            "third_party_summary", "strengths_json", "raw_extract_json", "manual_paste", "fetch_status", "error_message",
            "notes", "created_at", "updated_at", "updated_by",
        ]
        values = {
            "school_id": school_id,
            "source_name": GOOD_SCHOOLS_SOURCE_NAME,
            "source_url": urls["profile_url"],
            "profile_url": urls["profile_url"],
            "about_url": urls["about_url"],
            "fees_url": urls["fees_url"],
            "naplan_url": urls["naplan_url"],
            "location_url": urls["location_url"],
            "fetched_at": stamp,
            "review_status": review_status,
            **extracted,
            "raw_extract_json": raw_extract,
            "manual_paste": manual_text,
            "fetch_status": fetch_status,
            "error_message": "; ".join(errors),
            "notes": notes,
            "created_at": stamp,
            "updated_at": stamp,
            "updated_by": self.user["id"],
        }
        db.execute(
            f"INSERT INTO school_third_party_profiles({','.join(columns)}) VALUES({','.join('?' for _ in columns)})",
            tuple(values[column] for column in columns),
        )
        feature_tag_rows = db.all(
            """SELECT t.id,t.category_id,t.tag_name_cn,t.tag_name_en,t.keywords,
                      c.category_name_cn,c.category_name_en
               FROM school_feature_tags t
               LEFT JOIN school_feature_categories c ON c.id=t.category_id
               WHERE t.is_active=1 AND COALESCE(c.is_active,1)=1
               ORDER BY c.sort_order,t.sort_order"""
        )
        good_schools_feature_matches = extract_good_schools_activity_feature_matches(plain_text, feature_tag_rows, urls["profile_url"])
        inserted_activity_tags = 0
        for feature in good_schools_feature_matches:
            tag_id = feature.get("tag_id")
            if not tag_id:
                continue
            exists = db.one(
                """SELECT id FROM school_feature_tag_assignments
                   WHERE school_id=? AND tag_id=? AND source_type=? AND source_url=?
                     AND status IN ('Suggested','NeedsReview','Confirmed')""",
                (school_id, tag_id, GOOD_SCHOOLS_SOURCE_NAME, urls["profile_url"]),
            )
            if exists:
                continue
            assignment_id = db.execute(
                """INSERT INTO school_feature_tag_assignments(
                    school_id,category_id,tag_id,assignment_type,status,confidence_rate,
                    source_url,source_title,source_type,source_excerpt,collected_at,collected_by_system,notes,created_by,created_at
                   ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                (
                    school_id,
                    feature.get("category_id"),
                    tag_id,
                    "AutoSuggested",
                    "Suggested",
                    feature.get("confidence_rate"),
                    urls["profile_url"],
                    GOOD_SCHOOLS_SOURCE_NAME,
                    GOOD_SCHOOLS_SOURCE_NAME,
                    feature.get("source_excerpt") or "",
                    stamp,
                    1,
                    "GoodSchools Activities: " + ", ".join(map(str, feature.get("matched_keywords") or [])),
                    self.user["id"],
                    stamp,
                ),
            )
            inserted_activity_tags += 1
            db.audit(self.user, "school_feature_tag_suggested", "school_library", record_id=assignment_id, student_id=school_id, new_value=json.dumps({"tag_id": tag_id, "confidence_rate": feature.get("confidence_rate"), "source_url": urls["profile_url"], "source_type": GOOD_SCHOOLS_SOURCE_NAME}, ensure_ascii=False), ip=self.client_address[0], device=self.headers.get("User-Agent"))
        self.school_good_schools_record_conflicts(school, urls["profile_url"], extracted)
        for fee in self.school_good_schools_extract_fees(plain_text):
            db.execute(
                """INSERT INTO school_fees(school_id,source_name,source_url,fetched_at,review_status,fee_type,year_level,amount,currency,fee_year,raw_text,notes,created_at,updated_at,updated_by)
                   VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                (school_id, GOOD_SCHOOLS_SOURCE_NAME, urls["fees_url"] or urls["profile_url"], stamp, "Needs Review", fee["fee_type"], fee["year_level"], fee["amount"], "AUD", fee["fee_year"], fee["raw_text"], "Good Schools extraction", stamp, stamp, self.user["id"]),
            )
        for indicator in self.school_good_schools_extract_academic(plain_text):
            db.execute(
                """INSERT INTO school_academic_indicators(school_id,source_name,source_url,fetched_at,review_status,indicator_name,year_level,data_year,indicator_value,comparison_notes,raw_text,notes,created_at,updated_at,updated_by)
                   VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                (school_id, GOOD_SCHOOLS_SOURCE_NAME, urls["naplan_url"] or urls["profile_url"], stamp, "Needs Review", indicator["indicator_name"], indicator["year_level"], indicator["data_year"], indicator["indicator_value"], indicator["comparison_notes"], indicator["raw_text"], "Good Schools extraction", stamp, stamp, self.user["id"]),
            )
        for item in self.school_good_schools_extract_comparisons(plain_text):
            db.execute(
                """INSERT INTO school_comparison_sources(school_id,source_name,source_url,fetched_at,review_status,nearby_school_name,comparison_notes,raw_text,notes,created_at,updated_at,updated_by)
                   VALUES(?,?,?,?,?,?,?,?,?,?,?,?)""",
                (school_id, GOOD_SCHOOLS_SOURCE_NAME, urls["location_url"] or urls["profile_url"], stamp, "Needs Review", item["nearby_school_name"], item["comparison_notes"], item["raw_text"], "Good Schools extraction", stamp, stamp, self.user["id"]),
            )
        db.audit(self.user, "good_schools_fetch_completed", "school_library", record_id=school_id, new_value=json.dumps({"fetch_status": fetch_status, "errors": errors, "activity_feature_tags": inserted_activity_tags}, ensure_ascii=False), file_path=urls["profile_url"], ip=self.client_address[0], device=self.headers.get("User-Agent"))
        self.school_record_source(school_id, "third_party_profile", GOOD_SCHOOLS_SOURCE_NAME, urls["profile_url"], "", 70 if not errors else 45, f"{fetch_status}; Needs Review; activity_feature_tags={inserted_activity_tags}")
        return self.flash_redirect(f"/schools/{school_id}#good-schools", f"Good Schools Guide 资料已提取为 Needs Review，并生成 {inserted_activity_tags} 个学校特色标签建议。正式学校资料未被覆盖。")

