    def content_sync_panel(self):
        can_update = can_module_action(self.user, "content_center", "import_old_data") or is_content_center_allowed_user(self.user)
        preview = None
        report = None
        scan_job = None
        scan_id = (self.query.get("scan_id") or [""])[0]
        if scan_id:
            try:
                candidate = google_drive_runtime_store.load_preview_for_confirmation(scan_id)
                if int(candidate.get("actor_user_id") or 0) == int(self.user.get("id") or 0):
                    preview = candidate
                    report = candidate.get("replay_report") or None
            except Exception:
                preview = None
        scan_job_id = (self.query.get("scan_job_id") or [""])[0]
        if scan_job_id:
            try:
                scan_job = build_google_drive_scan_coordinator().get_for_actor(
                    scan_job_id, int(self.user.get("id") or 0)
                )
                if scan_job.get("state") == "completed" and scan_job.get("scan_id"):
                    candidate = google_drive_runtime_store.load_preview_for_confirmation(scan_job["scan_id"])
                    if int(candidate.get("actor_user_id") or 0) == int(self.user.get("id") or 0):
                        preview = candidate
                        report = candidate.get("replay_report") or None
                        scan_job = None
            except Exception:
                scan_job = None
        return render_google_drive_workspace(
            status=google_drive_workspace_status(),
            preview=preview,
            report=report,
            logs=google_drive_runtime_store.list_logs(limit=50),
            csrf=self.csrf,
            permissions={"can_control": can_update, "can_scan": can_update, "can_confirm": can_update},
            scan_job=scan_job,
        )

