    def content_analysis_report_panel(self):
        totals = db.one(
            """SELECT COUNT(DISTINCT s.id) scripts,
                      COUNT(DISTINCT pp.id) posts,
                      COALESCE(SUM(m.views),0) views,
                      COALESCE(SUM(m.likes),0) likes,
                      COALESCE(SUM(m.saves),0) saves,
                      COALESCE(SUM(m.comments),0) comments,
                      COALESCE(SUM(m.shares),0) shares
               FROM content_scripts s
               LEFT JOIN content_published_posts pp ON pp.script_id=s.id
               LEFT JOIN content_performance_metrics m ON m.script_id=s.id"""
        )
        category_rows = db.all(
            """SELECT COALESCE(s.category,'未分类') category,
                      COUNT(DISTINCT s.id) scripts,
                      COUNT(DISTINCT pp.id) posts,
                      COALESCE(SUM(m.views),0) views,
                      COALESCE(SUM(m.likes),0) likes,
                      COALESCE(SUM(m.saves),0) saves,
                      COALESCE(SUM(m.comments),0) comments,
                      COALESCE(SUM(m.shares),0) shares
               FROM content_scripts s
               LEFT JOIN content_published_posts pp ON pp.script_id=s.id
               LEFT JOIN content_performance_metrics m ON m.script_id=s.id
               GROUP BY COALESCE(s.category,'未分类')
               ORDER BY views DESC, likes DESC
               LIMIT 30"""
        )
        category_table = "".join(
            f"""<tr>
              <td><strong>{esc(row['category'])}</strong></td>
              <td>{row['scripts']}</td><td>{row['posts']}</td><td>{row['views']}</td><td>{row['likes']}</td><td>{row['saves']}</td><td>{row['comments']}</td><td>{row['shares']}</td>
            </tr>"""
            for row in category_rows
        ) or '<tr><td colspan="8" class="empty content-analysis-empty-state">暂无可分析数据。</td></tr>'
        top_rows = db.all(
            """SELECT s.id,s.title,s.category,
                      COALESCE(m.views,0) views,COALESCE(m.likes,0) likes,COALESCE(m.saves,0) saves,
                      COALESCE(m.comments,0) comments,COALESCE(m.shares,0) shares
               FROM content_scripts s
               LEFT JOIN content_performance_metrics m ON m.script_id=s.id
               ORDER BY COALESCE(m.views,0) DESC,COALESCE(m.likes,0) DESC
               LIMIT 20"""
        )
        top_table = "".join(
            f"""<tr>
              <td><a href="/content/scripts/{row['id']}"><strong>{esc(row['title'])}</strong></a><small>{esc(row['category'] or '未分类')}</small></td>
              <td>{row['views']}</td><td>{row['likes']}</td><td>{row['saves']}</td><td>{row['comments']}</td><td>{row['shares']}</td>
            </tr>"""
            for row in top_rows
        ) or '<tr><td colspan="6" class="empty content-analysis-empty-state">暂无文案表现数据。</td></tr>'
        return f"""
        <section class="content-workspace content-worktab-workspace">
          <div class="content-workspace-title content-worktab-header">
            <div><span class="eyebrow">Content Report</span><h2>内容分析报告</h2><p>按分类和发布表现汇总，帮助判断哪些主题带来更多线索。</p></div>
          </div>
          <section class="metrics content-metrics content-workbench-metrics content-analysis-kpi-grid">
            <div class="metric content-metric"><span>文案总数</span><strong>{esc(totals['scripts'])}</strong><small>内容库</small></div>
            <div class="metric content-metric"><span>已发布</span><strong>{esc(totals['posts'])}</strong><small>发布记录</small></div>
            <div class="metric content-metric"><span>观看数</span><strong>{esc(totals['views'])}</strong><small>发布表现</small></div>
            <div class="metric content-metric"><span>收藏</span><strong>{esc(totals['saves'])}</strong><small>内容价值</small></div>
            <div class="metric content-metric"><span>评论</span><strong>{esc(totals['comments'])}</strong><small>互动反馈</small></div>
          </section>
          <section class="panel content-worktab-section">
            <div class="panel-head content-worktab-summary"><div><h2>按分类分析</h2><p>用于后续选题和月度报告。</p></div></div>
            <div class="table-wrap content-analysis-table"><table><thead><tr><th>分类</th><th>文案</th><th>发布</th><th>观看</th><th>赞</th><th>藏</th><th>评</th><th>转发</th></tr></thead><tbody>{category_table}</tbody></table></div>
          </section>
          <section class="panel content-worktab-section">
            <div class="panel-head content-worktab-summary"><div><h2>表现较好的文案</h2><p>按观看和互动综合排序。</p></div></div>
            <div class="table-wrap content-analysis-table"><table><thead><tr><th>文案</th><th>观看</th><th>赞</th><th>藏</th><th>评</th><th>转发</th></tr></thead><tbody>{top_table}</tbody></table></div>
          </section>
        </section>"""

