    def content_extraction_recent_jobs(self, status_filter=""):
        try:
            if status_filter:
                rows = db.all(
                    "SELECT * FROM content_extraction_jobs WHERE status=? ORDER BY created_at DESC,id DESC LIMIT 50",
                    (status_filter,),
                )
            else:
                rows = db.all("SELECT * FROM content_extraction_jobs ORDER BY created_at DESC,id DESC LIMIT 50")
            return [rowdict(row) for row in rows]
        except sqlite3.OperationalError:
            return []

