        confirmed_title = job.get("confirmed_title") or job.get("note_title") or "澳洲低龄留学口播稿"
        confirmed_hook = job.get("confirmed_hook") or job.get("rewritten_hook") or job.get("hook") or ""
        confirmed_script = job.get("confirmed_script") or job.get("rewritten_script") or job.get("final_script") or job.get("rewrite_for_fage") or ""
        confirmed_tags = job.get("confirmed_tags") or job.get("suggested_tags") or job.get("topic_tags") or ""
