        uploaded_note = job.get("uploaded_file_path") or job.get("local_video_path") or ""
        created_script = f'<a class="secondary button-link" href="/content/scripts/{job["created_script_id"]}">打开已保存文案</a>' if job.get("created_script_id") else ""
        published = f'<span class="status ok">已发布记录 #{esc(job["published_post_id"])}</span>' if job.get("published_post_id") else ""
