            confirmed_script=str(self.form.get("confirmed_script", row.get("confirmed_script") or row.get("rewritten_script") or row.get("final_script") or "")).strip(),
            confirmed_tags=str(self.form.get("confirmed_tags", row.get("confirmed_tags") or row.get("suggested_tags") or "")).strip(),
            category=str(self.form.get("category", row.get("category") or "澳洲低龄留学")).strip(),
