    def content_placeholder_panel(self, title):
        return f"""
        <section class="panel">
          <div class="panel-head"><div><h2>{esc(title)}</h2><p>暂无记录，可以从文案草稿或新建文案开始。</p></div></div>
          <div class="empty">暂无内容。</div>
        </section>"""

    def can_create_content(self):
        return (
            can_module_action(self.user, "content_center", "create_topics")
            or can_module_action(self.user, "content_center", "generate_scripts")
            or can_module_action(self.user, "content_center", "edit_scripts")
            or is_content_center_allowed_user(self.user)
        )

    def content_center(self, method):
        if method != "GET":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        tab = (self.query.get("tab") or ["dashboard"])[0]
        panels = {
            "dashboard": self.content_dashboard_panel,
            "create": self.content_create_panel,
            "extract": self.content_extraction_panel,
            "sync": self.content_sync_panel,
            "tracking": self.content_tracking_panel,
            "analysis": self.content_analysis_report_panel,
        }
        tab = tab if tab in panels else "dashboard"
        panel_html = panels[tab]()
        page_roots = {
            "create": "content-create-page",
            "extract": "content-extract-page",
            "sync": "content-sync-page",
            "tracking": "content-tracking-page",
            "analysis": "content-analysis-page",
        }
        if tab == "dashboard":
            body = f"""<div class="content-centre-page">
            <nav class="link-status-tabs content-tabs content-centre-tabs">{self.content_tabs(tab)}</nav>
            {panel_html}
            </div>"""
        elif tab in page_roots:
            page_root = page_roots[tab]
            page_tabs_class = "content-extract-sync-tabs" if tab in {"extract", "sync"} else "content-worktab-tabs"
            body = f"""<div class="{page_root}">
            <nav class="link-status-tabs content-tabs {page_tabs_class}">{self.content_tabs(tab)}</nav>
            {panel_html}
            </div>"""
        else:
            body = f"""
            <nav class="link-status-tabs content-tabs">{self.content_tabs(tab)}</nav>
            {panel_html}"""
        db.audit(self.user, "content_module_opened", "content_center", record_id=tab, ip=self.client_address[0], device=self.headers.get("User-Agent"))
        message, kind = self.message()
        return self.send_html(page("内容管理中心", body, self.user, self.csrf, "content", nas.status(), message, kind))

    def content_create(self, method):
        if method != "POST":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        if not self.can_create_content():
            db.audit(self.user, "content_access_denied", "content_center", record_id="create", ip=self.client_address[0], device=self.headers.get("User-Agent"), status="denied")
            return self.deny_module_access("content_center")
        title = str(self.form.get("title", "")).strip()
        if not title:
            return self.flash_redirect("/content?tab=create", "标题为必填项。", "error")
        body = str(self.form.get("body", "")).strip()
        category = str(self.form.get("category", "")).strip() or "自动识别"
        status = content_status_value(self.form.get("status", "Draft"))
        if status not in {value for value, _label in CONTENT_STATUS_OPTIONS}:
            status = "Draft"
        tags = [tag.strip() for tag in re.split(r"[,，]", str(self.form.get("tags", ""))) if tag.strip()]
        notes = str(self.form.get("notes", "")).strip()
        content_date = str(self.form.get("content_date", "")).strip()
        planned_publish_date = str(self.form.get("planned_publish_date", "")).strip()
        content_year = content_month = content_week = None
        if content_date:
            try:
                parsed_date = date.fromisoformat(content_date)
                content_year = parsed_date.year
                content_month = parsed_date.month
                content_week = parsed_date.isocalendar().week
            except ValueError:
                return self.flash_redirect("/content?tab=create", "文案日期格式无效。", "error")
        if planned_publish_date:
            try:
                date.fromisoformat(planned_publish_date)
            except ValueError:
                return self.flash_redirect("/content?tab=create", "计划发布日期格式无效。", "error")
        stamp = now_iso()
        tags_json = json.dumps(tags, ensure_ascii=False)
        with db.transaction() as conn:
            topic_id = conn.execute(
                """INSERT INTO content_topics(
                   topic_name,category,status,content_year,source,source_type,source_reference,tags_json,
                   legacy_system_name,legacy_table_name,legacy_record_id,legacy_created_at,legacy_updated_at,
                   imported_at,imported_by,import_batch_id,potential_duplicate,migration_notes,created_at,updated_at)
                   VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                (
                    title, category, "Active", content_year, "CRM 手动新建", "crm_manual", "",
                    tags_json, "CRM", "content_create", None, None, None, stamp,
                    self.user["id"], "crm_manual_create", 0, "", stamp, stamp,
                ),
            ).lastrowid
            script_id = conn.execute(
                """INSERT INTO content_scripts(
                   title,body,category,topic_id,status,review_status,version_number,source_type,
                   content_year,content_month,content_week,tags_json,notes,legacy_system_name,
                   legacy_table_name,legacy_record_id,legacy_created_at,legacy_updated_at,imported_at,
                   imported_by,import_batch_id,potential_duplicate,migration_notes,created_at,updated_at)
                   VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                (
                    title, body, category, topic_id, status, "待录制", 1, "crm_manual",
                    content_year, content_month, content_week, tags_json, notes, "CRM",
                    "content_create", None, None, None, stamp, self.user["id"],
                    "crm_manual_create", 0, "", stamp, stamp,
                ),
            ).lastrowid
            conn.execute(
                """INSERT INTO content_script_versions(
                   script_id,title,body,version_number,version_note,legacy_system_name,legacy_table_name,
                   legacy_record_id,legacy_created_at,legacy_updated_at,imported_at,imported_by,
                   import_batch_id,potential_duplicate,migration_notes,created_at)
                   VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                (
                    script_id, title, body, 1, "Initial manual create", "CRM", "content_create",
                    None, None, None, stamp, self.user["id"], "crm_manual_create", 0, "", stamp,
                ),
            )
            if planned_publish_date:
                conn.execute(
                    """INSERT INTO content_publish_plans(
                       script_id,planned_publish_date,channel,status,legacy_system_name,legacy_table_name,
                       legacy_record_id,imported_at,imported_by,import_batch_id,potential_duplicate,
                       migration_notes,created_at,updated_at)
                       VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                    (
                        script_id, planned_publish_date, "Xiaohongshu", "Planned", "CRM", "content_create",
                        None, stamp, self.user["id"], "crm_manual_create", 0, "", stamp, stamp,
                    ),
                )
        docx_path = create_content_script_docx(
            title,
            body,
            category=category,
            status=status,
            tags=tags,
            notes=notes,
            content_date=content_date,
            planned_publish_date=planned_publish_date,
            script_id=script_id,
        )
        docx_hash = hashlib.sha256(docx_path.read_bytes()).hexdigest()
        with db.transaction() as conn:
            conn.execute(
                "UPDATE content_topics SET source_reference=?,updated_at=? WHERE id=?",
                (str(docx_path), now_iso(), topic_id),
            )
            conn.execute(
                """INSERT INTO content_materials(
                   script_id,material_type,title,source_path,source_url,file_hash,legacy_system_name,
                   legacy_table_name,legacy_record_id,legacy_created_at,legacy_updated_at,imported_at,
                   imported_by,import_batch_id,potential_duplicate,migration_notes,created_at,updated_at)
                   VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                (
                    script_id, "Word", title, str(docx_path), "", docx_hash, "CRM",
                    "content_create_docx", script_id, None, None, stamp, self.user["id"],
                    "crm_manual_create", 0, "Word document generated for manually created content script.",
                    stamp, stamp,
                ),
            )
        db.audit(
            self.user, "content_script_created", "content_center", record_id=script_id, file_path=str(docx_path),
            new_value=json.dumps({"title": title, "topic_id": topic_id, "status": status, "category": category, "docx_path": str(docx_path)}, ensure_ascii=False),
            ip=self.client_address[0], device=self.headers.get("User-Agent"),
        )
        db.audit(
            self.user, "content_script_docx_generated", "content_center", record_id=script_id, file_path=str(docx_path),
            new_value=json.dumps({"docx_path": str(docx_path), "file_hash": docx_hash}, ensure_ascii=False),
            ip=self.client_address[0], device=self.headers.get("User-Agent"),
        )
        return self.flash_redirect(f"/content/scripts/{script_id}", f"文案已保存，Word 文档已生成：{docx_path.name}")

    def content_script_save(self, method, script_id):
        if method != "POST":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        if not (can_module_action(self.user, "content_center", "edit_scripts") or is_content_center_allowed_user(self.user)):
            db.audit(self.user, "content_access_denied", "content_center", record_id=script_id, status="denied", ip=self.client_address[0], device=self.headers.get("User-Agent"))
            return self.deny_module_access("content_center")
        old = db.one("SELECT * FROM content_scripts WHERE id=?", (script_id,))
        if not old:
            return self.error_page("文案不存在", HTTPStatus.NOT_FOUND)
        title = str(self.form.get("title", "")).strip()
        if not title:
            return self.flash_redirect(f"/content/scripts/{script_id}", "标题为必填项。", "error")
        body = str(self.form.get("body", "")).strip()
        category = str(self.form.get("category", "")).strip()
        status = content_status_value(self.form.get("status"))
        review_status = str(self.form.get("review_status", "")).strip()
        notes = str(self.form.get("notes", "")).strip()
        tags_json = json.dumps(parse_tags(self.form.get("tags", "")), ensure_ascii=False)
        content_year = content_int(self.form.get("content_year")) or None
        stamp = now_iso()
        changes = {
            "title": [old["title"], title],
            "category": [old["category"], category],
            "status": [old["status"], status],
            "review_status": [old["review_status"], review_status],
            "content_year": [old["content_year"], content_year],
        }
        db.execute(
            """UPDATE content_scripts SET title=?,body=?,category=?,status=?,review_status=?,content_year=?,
               tags_json=?,notes=?,updated_at=? WHERE id=?""",
            (title, body, category, status, review_status, content_year, tags_json, notes, stamp, script_id),
        )
        db.audit(
            self.user, "script_updated", "content_center", record_id=script_id,
            old_value=json.dumps({k: v[0] for k, v in changes.items()}, ensure_ascii=False),
            new_value=json.dumps({k: v[1] for k, v in changes.items()}, ensure_ascii=False),
            ip=self.client_address[0], device=self.headers.get("User-Agent"),
        )
        return self.flash_redirect(f"/content/scripts/{script_id}", "文案已保存。")

    def content_script_version(self, method, script_id):
        if method != "POST":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        if not (can_module_action(self.user, "content_center", "edit_scripts") or is_content_center_allowed_user(self.user)):
            return self.deny_module_access("content_center")
        script = db.one("SELECT * FROM content_scripts WHERE id=?", (script_id,))
        if not script:
            return self.error_page("文案不存在", HTTPStatus.NOT_FOUND)
        title = str(self.form.get("title", script["title"])).strip() or script["title"]
        body = str(self.form.get("body", script["body"] or "")).strip()
        category = str(self.form.get("category", script["category"] or "")).strip()
        tags_json = json.dumps(parse_tags(self.form.get("tags", "")) or stored_content_tags(script["tags_json"]), ensure_ascii=False)
        notes = str(self.form.get("notes", script["notes"] or "")).strip()
        stamp = now_iso()
        new_version = int(script["version_number"] or 1) + 1
        with db.transaction() as conn:
            conn.execute(
                """INSERT INTO content_script_versions(
                   script_id,title,body,version_number,version_note,legacy_system_name,legacy_table_name,
                   legacy_record_id,legacy_created_at,legacy_updated_at,imported_at,imported_by,
                   import_batch_id,potential_duplicate,migration_notes,created_at)
                   VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                (script_id, title, body, new_version, "Manual new version", script["legacy_system_name"], script["legacy_table_name"],
                 script["legacy_record_id"], script["legacy_created_at"], script["legacy_updated_at"], stamp, self.user["id"],
                 script["import_batch_id"], 0, "Saved as new version in CRM.", stamp),
            )
            conn.execute(
                "UPDATE content_scripts SET title=?,body=?,category=?,tags_json=?,notes=?,version_number=?,updated_at=? WHERE id=?",
                (title, body, category, tags_json, notes, new_version, stamp, script_id),
            )
        db.audit(self.user, "script_updated", "content_center", record_id=script_id, new_value=json.dumps({"new_version": new_version, "title": title}, ensure_ascii=False), ip=self.client_address[0], device=self.headers.get("User-Agent"))
        return self.flash_redirect(f"/content/scripts/{script_id}", f"已保存为 V{new_version}。")

    def content_script_action(self, method, script_id):
        if method != "POST":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        action = str(self.form.get("action", "")).strip()
        return_to = str(self.form.get("return_to", "")).strip()
        if not return_to.startswith("/content"):
            return_to = f"/content/scripts/{script_id}"
        script = db.one("SELECT * FROM content_scripts WHERE id=?", (script_id,))
        if not script:
            return self.error_page("文案不存在", HTTPStatus.NOT_FOUND)
        action_map = {
            "set_draft": ("Draft", "Pending", "script_set_draft", "已设为草稿。"),
            "set_recorded": ("Recorded", "Approved", "script_set_recorded", "已设为已录制。"),
            "mark_published": ("Published", "Approved", "post_marked_published", "已标记为发布。"),
        }
        if action not in action_map:
            return self.flash_redirect(return_to, "未知操作。", "error")
        new_status, review_status, audit_action, message = action_map[action]
        status_date = str(self.form.get("status_date", "")).strip() or date.today().isoformat()
        try:
            date.fromisoformat(status_date)
        except ValueError:
            return self.flash_redirect(return_to, "日期格式无效。", "error")
        update_fields = ["status=?", "review_status=?", "updated_at=?"]
        update_values = [new_status, review_status, now_iso()]
        if action == "set_recorded":
            update_fields.append("recorded_at=?")
            update_values.append(status_date)
        if action == "mark_published":
            update_fields.append("published_at=?")
            update_values.append(status_date)
        update_values.append(script_id)
        db.execute(f"UPDATE content_scripts SET {','.join(update_fields)} WHERE id=?", tuple(update_values))
        if action == "mark_published":
            stamp = now_iso()
            existing = db.one("SELECT id FROM content_published_posts WHERE script_id=? LIMIT 1", (script_id,))
            if not existing:
                db.execute(
                    """INSERT INTO content_published_posts(script_id,topic_id,published_at,platform,status,post_title,
                       legacy_system_name,legacy_table_name,legacy_record_id,imported_at,imported_by,import_batch_id,potential_duplicate,migration_notes,created_at,updated_at)
                       VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                    (script_id, script["topic_id"], status_date, "Xiaohongshu", "Published", script["title"],
                     "CRM", "content_scripts", script_id, stamp, self.user["id"], "crm_manual_publish", 0, "", stamp, stamp),
                )
            else:
                db.execute("UPDATE content_published_posts SET published_at=?,updated_at=? WHERE id=?", (status_date, stamp, existing["id"]))
        db.audit(
            self.user, audit_action, "content_center", record_id=script_id,
            old_value=script["status"],
            new_value=json.dumps({"status": new_status, "date": status_date}, ensure_ascii=False),
            ip=self.client_address[0], device=self.headers.get("User-Agent"),
        )
        return self.flash_redirect(return_to, message)

    def content_script_ref(self):
        raw = str(self.form.get("script_ref", "")).strip()
        script_id = content_int(raw.split("|", 1)[0])
        script = db.one("SELECT * FROM content_scripts WHERE id=?", (script_id,))
        return script

