    def content_publish_plan_create(self, method):
        if method != "POST":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        if not (can_module_action(self.user, "content_center", "schedule_posts") or is_content_center_allowed_user(self.user)):
            return self.deny_module_access("content_center")
        script = self.content_script_ref()
        if not script:
            return self.flash_redirect("/content?tab=plans", "请选择文案。", "error")
        planned_date = str(self.form.get("planned_publish_date", "")).strip()
        if not planned_date:
            return self.flash_redirect("/content?tab=plans", "请选择发布日期。", "error")
        stamp = now_iso()
        db.execute(
            """INSERT INTO content_publish_plans(script_id,topic_id,planned_publish_date,planned_publish_time,channel,platform,status,publish_status,
               account_name,responsible_user,reminder_enabled,notes,legacy_system_name,legacy_table_name,legacy_record_id,imported_at,imported_by,
               import_batch_id,potential_duplicate,migration_notes,created_at,updated_at)
               VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
            (
                script["id"], script["topic_id"], planned_date, str(self.form.get("planned_publish_time", "")).strip(),
                str(self.form.get("platform", "Xiaohongshu")).strip() or "Xiaohongshu",
                str(self.form.get("platform", "Xiaohongshu")).strip() or "Xiaohongshu",
                "Planned", "Planned", str(self.form.get("account_name", "")).strip(), str(self.form.get("responsible_user", "")).strip(),
                1 if self.form.get("reminder_enabled") else 0, str(self.form.get("notes", "")).strip(),
                "CRM", "content_publish_plan", script["id"], stamp, self.user["id"], "crm_manual_schedule", 0, "", stamp, stamp,
            ),
        )
