    def content_cleanup_confirm_year(self, method, staging_id):
        if method != "POST":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        if not self.can_cleanup_content_import():
            db.audit(self.user, "content_access_denied", "content_center", record_id=staging_id, status="denied", ip=self.client_address[0], device=self.headers.get("User-Agent"))
            return self.deny_module_access("content_center")
        row = db.one("SELECT * FROM content_import_staging WHERE id=?", (staging_id,))
        if not row:
            return self.flash_redirect("/content?tab=import&issue=missing_year", "记录不存在。", "error")
        year = maybe_int(self.form.get("confirmed_year"))
        if not year or year < 2000 or year > date.today().year + 2:
            return self.flash_redirect("/content?tab=import&issue=missing_year", "请填写有效年份。", "error")
        with db.transaction() as conn:
            status, _flags = update_content_cleanup_record(conn, row, self.user, confirmed_year=year, note=f"Confirmed year as {year}.")
        db.audit(self.user, "content_year_confirmed", "content_center", record_id=staging_id, old_value=str(row["old_year"] or row["confirmed_year"] or ""), new_value=str(year), ip=self.client_address[0], device=self.headers.get("User-Agent"))
        db.audit(self.user, "content_cleanup_record_reviewed", "content_center", record_id=staging_id, new_value=status, ip=self.client_address[0], device=self.headers.get("User-Agent"))
        return self.flash_redirect("/content?tab=import&issue=missing_year", f"已确认年份：{year}。")

