        if not ids or not year or year < 2000 or year > date.today().year + 2:
            return self.flash_redirect("/content?tab=import&issue=missing_year", "请选择记录并填写有效年份。", "error")
        placeholders = ",".join("?" for _ in ids)
        rows = db.all(f"SELECT * FROM content_import_staging WHERE id IN ({placeholders})", tuple(ids))
        with db.transaction() as conn:
            for row in rows:
                update_content_cleanup_record(conn, row, self.user, confirmed_year=year, note=f"Batch confirmed year as {year}.")
        db.audit(self.user, "content_batch_year_updated", "content_center", record_id="phase6a", new_value=json.dumps({"count": len(rows), "year": year}, ensure_ascii=False), ip=self.client_address[0], device=self.headers.get("User-Agent"))
        return self.flash_redirect("/content?tab=import&issue=missing_year", f"已批量确认 {len(rows)} 条年份为 {year}。")

