    def reminder_query_rows(self):
        return db.all(
            """SELECT r.*,s.passport_first_name,s.passport_last_name,
                      u.display_name assigned_name,creator.display_name created_by_name
               FROM reminders r
               LEFT JOIN students s ON s.student_id=r.student_id
               LEFT JOIN users u ON u.id=r.assigned_to_user_id
               LEFT JOIN users creator ON creator.id=r.created_by
              WHERE COALESCE(r.source_type,'')<>'student_followup_note_deleted'
               ORDER BY COALESCE(r.reminder_datetime,r.due_datetime,r.due_date) ASC, r.id DESC"""
        )

    def reminder_rows_for_user(self, tab, rows=None):
        rows = rows if rows is not None else self.reminder_query_rows()
        today = date.today()
        week_end = today + timedelta(days=7)
        filtered = []
        for row in rows:
            effective = reminder_effective_status(row)
            if effective == "Snoozed":
                continue
            due_day_text = reminder_due_date(row)
            try:
                due_day = datetime.fromisoformat(due_day_text).date() if due_day_text else None
            except ValueError:
                due_day = None
            if self.user.get("role_name") not in {"Admin", "Manager"}:
                if row["assigned_to_user_id"] and row["assigned_to_user_id"] != self.user["id"] and row["created_by"] != self.user["id"]:
                    continue
            if tab == "today" and due_day != today and effective != "Due":
                continue
            if tab == "overdue" and effective != "Overdue":
                continue
            if tab == "week" and not (due_day and today <= due_day <= week_end):
                continue
            if tab == "auto" and not row["auto_generated"]:
                continue
            if tab == "manual" and row["auto_generated"]:
                continue
            if tab == "completed" and effective != "Completed":
                continue
            if tab == "dismissed" and effective != "Dismissed":
                continue
            if tab not in {"all", "completed", "dismissed"} and effective in {"Completed", "Dismissed", "Cancelled"}:
                continue
            filtered.append((row, effective))
        return filtered

    def reminder_card_html(self, row, effective):
        student_name = f'{row["passport_first_name"] or ""} {row["passport_last_name"] or ""}'.strip() if row["student_id"] else ""
        student_link = f'<a href="/students/{esc(row["student_id"])}">{esc(student_name or row["student_id"])}</a>' if row["student_id"] else '<span class="muted-line">无关联学生</span>'
        related = reminder_related_link(row)
        related_button = f'<form method="post" action="/reminders/{row["id"]}/open"><input type="hidden" name="csrf" value="{esc(self.csrf)}"><button class="secondary compact">打开相关模块</button></form>' if related else ""
        complete_button = dismiss_button = snooze_form = cancel_button = copy_button = ""
        if effective not in {"Completed", "Dismissed", "Cancelled"}:
            if can_reminder_action(self.user, "complete"):
                complete_button = f'<form method="post" action="/reminders/{row["id"]}/complete"><input type="hidden" name="csrf" value="{esc(self.csrf)}"><button class="primary compact">标记完成</button></form>'
                snooze_form = f"""<form method="post" action="/reminders/{row["id"]}/snooze" class="inline-form">
                  <input type="hidden" name="csrf" value="{esc(self.csrf)}">
                  <select name="snooze"><option value="30m">30分钟</option><option value="1h">1小时</option><option value="3h">3小时</option><option value="tomorrow">明天</option></select>
                  <button class="secondary compact">稍后提醒</button>
                </form>"""
            if can_reminder_action(self.user, "dismiss"):
                dismiss_button = f'<form method="post" action="/reminders/{row["id"]}/dismiss"><input type="hidden" name="csrf" value="{esc(self.csrf)}"><button class="ghost compact">忽略</button></form>'
            if can_reminder_action(self.user, "edit"):
                cancel_button = f'<form method="post" action="/reminders/{row["id"]}/cancel"><input type="hidden" name="csrf" value="{esc(self.csrf)}"><button class="ghost compact">取消</button></form>'
        if can_reminder_action(self.user, "create"):
            copy_button = f'<form method="post" action="/reminders/{row["id"]}/copy-to-mine"><input type="hidden" name="csrf" value="{esc(self.csrf)}"><button class="secondary compact">复制为我的提醒</button></form>'
        return f"""
        <article class="reminder-card reminder-status-{esc(effective.lower())} priority-{esc((row["priority"] or "Normal").lower())}">
          <div class="reminder-card-main">
            <div><span class="status {esc(effective.lower())}">{esc(reminder_status_label(effective))}</span><h3>{esc(row["title"] or reminder_type_label(row["reminder_type"]))}</h3><p>{esc(row["description"] or row["notes"] or "")}</p></div>
            <div class="reminder-meta"><span>{esc(reminder_type_label(row["reminder_type"]))}</span><span>{esc(reminder_priority_label(row["priority"]))}</span><span>{esc(display_datetime(row["reminder_datetime"] or row["due_datetime"] or row["due_date"]))}</span></div>
          </div>
          <div class="reminder-detail-grid">
            <div><span>学生</span><strong>{student_link}</strong></div>
            <div><span>发送给</span><strong>{esc(row["assigned_name"] or row["assigned_to_name"] or "未分配")}</strong></div>
            <div><span>创建人</span><strong>{esc(row["created_by_name"] or "系统")}</strong></div>
            <div><span>建议动作</span><strong>{esc(row["suggested_action"] or "按提醒内容跟进")}</strong></div>
          </div>
          <div class="row-actions">{complete_button}{snooze_form}{copy_button}{related_button}{dismiss_button}{cancel_button}</div>
        </article>"""

    def reminders(self, method):
        if method == "POST":
            if not can_reminder_action(self.user, "create"):
                return self.deny_module_access("reminders")
            title = str(self.form.get("title", "")).strip()
            due_date = str(self.form.get("due_date", "")).strip()
            if not title or not due_date:
                return self.flash_redirect("/reminders", "请填写提醒标题和到期日期。", "error")
            due_time = str(self.form.get("due_time", "")).strip() or "09:00"
            reminder_time = str(self.form.get("reminder_time", "")).strip() or due_time
            assigned_ids = []
            for raw_id in split_multi(self.form, "assigned_to_user_id"):
                try:
                    assigned_ids.append(int(raw_id))
                except (TypeError, ValueError):
                    continue
            if not assigned_ids:
                assigned_ids = [self.user["id"]]
            assigned_ids = list(dict.fromkeys(assigned_ids))
            assigned_rows = db.all(
                f"SELECT id,display_name FROM users WHERE is_active=1 AND deleted_at IS NULL AND id IN ({','.join('?' for _ in assigned_ids)})",
                tuple(assigned_ids),
            )
            assigned_by_id = {row["id"]: row for row in assigned_rows}
            if not assigned_by_id:
                return self.flash_redirect("/reminders", "请选择有效的提醒接收人。", "error")
            created_ids = []
            base_payload = {
                "student_id": str(self.form.get("student_id", "")).strip() or None,
                "reminder_type": str(self.form.get("reminder_type", "manual")).strip() or "manual",
                "title": title,
                "description": str(self.form.get("description", "")).strip(),
                "related_module": str(self.form.get("related_module", "")).strip(),
                "priority": str(self.form.get("priority", "Normal")).strip() or "Normal",
                "due_datetime": f"{due_date}T{due_time}:00",
                "reminder_datetime": f"{due_date}T{reminder_time}:00",
                "repeat_rule": str(self.form.get("repeat_rule", "none")).strip() or "none",
                "status": "Pending",
                "created_by": self.user["id"],
                "updated_by": self.user["id"],
                "source_type": "manual",
                "source_record_id": "",
                "auto_generated": False,
                "suggested_action": "按提醒内容跟进。",
                "notes": str(self.form.get("notes", "")).strip(),
            }
            for assigned_id in assigned_ids:
                assigned = assigned_by_id.get(assigned_id)
                if not assigned:
                    continue
                payload = dict(base_payload)
                payload["assigned_to_user_id"] = assigned_id
                payload["assigned_to_name"] = assigned["display_name"]
                reminder_id = reminder_insert(payload)
                created_ids.append(reminder_id)
                db.audit(self.user, "reminder_created", "reminders", reminder_id, new_value=json.dumps({"title": title, "assigned_to": assigned["display_name"]}, ensure_ascii=False), ip=self.client_address[0], device=self.headers.get("User-Agent"), student_id=self.form.get("student_id") or "")
            assigned_names = "、".join(assigned_by_id[user_id]["display_name"] for user_id in assigned_ids if user_id in assigned_by_id)
            return self.flash_redirect("/reminders?tab=manual", f"已发送 {len(created_ids)} 条提醒给：{assigned_names}。")
        if not can_reminder_action(self.user, "view"):
            return self.deny_module_access("reminders")
        tab = (self.query.get("tab") or ["today"])[0]
        if tab not in {key for key, _ in REMINDER_TABS}:
            tab = "today"
        run_reminder_engine_if_due()
        base_rows = self.reminder_query_rows()
        rows = self.reminder_rows_for_user(tab, base_rows)
        counts = {key: len(self.reminder_rows_for_user(key, base_rows)) for key, _ in REMINDER_TABS}
        tab_links = "".join(
            f'<a class="{"active" if tab == key else ""}" href="/reminders?tab={esc(key)}">{esc(label)} <span>{counts.get(key, 0)}</span></a>'
            for key, label in REMINDER_TABS
        )
        cards = "".join(self.reminder_card_html(row, effective) for row, effective in rows) or '<div class="empty">暂无提醒</div>'
        popup = next(((row, effective) for row, effective in self.reminder_rows_for_user("today", base_rows) if effective in {"Due", "Overdue"}), None)
        popup_html = ""
        if popup:
            row, effective = popup
            popup_html = f"""
            <div class="reminder-popup">
              <div><span class="status {esc(effective.lower())}">{esc(reminder_status_label(effective))}</span><h2>{esc(row["title"] or reminder_type_label(row["reminder_type"]))}</h2><p>{esc(row["description"] or "")}</p><small>{esc(student_name_by_id(row["student_id"]))} {esc(row["student_id"] or "")}</small></div>
              <div class="row-actions">
                <form method="post" action="/reminders/{row["id"]}/complete"><input type="hidden" name="csrf" value="{esc(self.csrf)}"><button class="primary">标记完成</button></form>
                <form method="post" action="/reminders/{row["id"]}/snooze"><input type="hidden" name="csrf" value="{esc(self.csrf)}"><input type="hidden" name="snooze" value="1h"><button class="secondary">1小时后提醒</button></form>
                {f'<form method="post" action="/reminders/{row["id"]}/open"><input type="hidden" name="csrf" value="{esc(self.csrf)}"><button class="secondary">打开相关模块</button></form>' if reminder_related_link(row) else ''}
                <form method="post" action="/reminders/{row["id"]}/dismiss"><input type="hidden" name="csrf" value="{esc(self.csrf)}"><button class="ghost">忽略</button></form>
              </div>
            </div>"""
            db.audit(self.user, "reminder_popup_shown", "reminders", row["id"], student_id=row["student_id"], ip=self.client_address[0], device=self.headers.get("User-Agent"))
        users = db.all("SELECT id,display_name FROM users WHERE is_active=1 AND deleted_at IS NULL ORDER BY display_name")
        user_options = "".join(f'<option value="{u["id"]}" {"selected" if u["id"] == self.user["id"] else ""}>{esc(u["display_name"])}</option>' for u in users)
        student_options = '<option value="">不关联学生</option>' + "".join(
            f'<option value="{esc(s["student_id"])}">{esc(s["passport_first_name"])} {esc(s["passport_last_name"])} · {esc(s["student_id"])}</option>'
            for s in db.all("SELECT student_id,passport_first_name,passport_last_name FROM students ORDER BY updated_at DESC LIMIT 200")
        )
        reminder_type_options = "".join(
            f'<option value="{esc(kind)}">{esc(reminder_type_label(kind))}</option>'
            for kind in REMINDER_CREATE_TYPES
        )
        settings_link = '<a class="secondary button-link" href="/reminders/settings">提醒规则设置</a>' if can_reminder_action(self.user, "manage_rules") else ""
        body = f"""
        <div class="reminders-page">
        {popup_html}
        <section class="panel reminder-hero"><div class="panel-head"><div><h2>提醒中心</h2><p>集中管理自动提醒和员工自定义提醒。</p></div><div class="row-actions">{settings_link}</div></div>
          <div class="reminder-tabs">{tab_links}</div>
        </section>
        <section class="reminder-layout">
          <div class="panel"><div class="panel-head"><div><h2>提醒列表</h2><p>{esc(dict(REMINDER_TABS).get(tab, "提醒"))}</p></div></div><div class="reminder-list">{cards}</div></div>
          <aside class="panel"><h2>新建提醒</h2><form method="post" action="/reminders" class="stack-form">
            <input type="hidden" name="csrf" value="{esc(self.csrf)}">
            <label>标题<input name="title" required placeholder="例如 明天下午联系家长补护照"></label>
            <label>关联学生<select name="student_id">{student_options}</select></label>
            <label>提醒类型<select name="reminder_type">{reminder_type_options}</select></label>
            <label>相关模块<select name="related_module"><option value="">无</option><option value="applications">Applications</option><option value="offer">Offer</option><option value="coe_oshc">COE + OSHC</option><option value="visa">VISA</option><option value="payments">Payments</option><option value="contracts">合同</option></select></label>
            <label>描述<textarea name="description" rows="3"></textarea></label>
            <div class="form-grid two"><label>到期日期<input type="date" name="due_date" required></label><label>到期时间<input type="time" name="due_time" value="09:00"></label></div>
            <label>提醒时间<input type="time" name="reminder_time" value="09:00"></label>
            <label>重复<select name="repeat_rule"><option value="none">不重复</option><option value="daily">每天</option><option value="weekly">每周</option><option value="monthly">每月</option><option value="yearly">每年</option><option value="custom">自定义</option></select></label>
            <label>发送给同事 / 接收人<select name="assigned_to_user_id" multiple size="6">{user_options}</select><small>可按住 Command 选择多个同事；每个接收人会收到一条独立提醒。</small></label>
            <label>优先级<select name="priority"><option value="Normal">普通</option><option value="Low">低</option><option value="High">高</option><option value="Urgent">紧急</option></select></label>
            <label>备注<textarea name="notes" rows="2"></textarea></label>
            <button class="primary">Create Reminder / 新建提醒</button>
          </form></aside>
        </section>
        </div>"""
        message, kind = self.message()
        self.send_html(page("提醒中心", body, self.user, self.csrf, "reminders", nas.status(), message, kind))

    def reminder_action(self, method, reminder_id, action):
        if method != "POST":
            return self.error_page("Method not allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        row = db.one("SELECT * FROM reminders WHERE id=?", (reminder_id,))
        if not row:
            return self.flash_redirect("/reminders", "提醒不存在。", "error")
        if not can_use_reminder(self.user, row):
            db.audit(self.user, "access_denied", "reminders", reminder_id, error_message="reminder not assigned or created by user", status="denied", ip=self.client_address[0], device=self.headers.get("User-Agent"))
            return self.deny_module_access("reminders")
        if action == "open":
            stamp = now_iso()
            mark_opened_canonical_reminder(db, reminder_id, self.user["id"], stamp)
            target = reminder_related_link(row) or "/reminders"
            db.audit(
                self.user, "reminder_opened", "reminders", reminder_id,
                old_value=row["status"], new_value=target, student_id=row["student_id"],
                ip=self.client_address[0], device=self.headers.get("User-Agent"),
            )
            return self.redirect(target)
        if action == "copy-to-mine":
            if not can_reminder_action(self.user, "create"):
                return self.deny_module_access("reminders")
            now_value = datetime.now().astimezone()
            due_at = parse_local_datetime(row["due_datetime"] or row["due_date"])
            reminder_at = parse_local_datetime(row["reminder_datetime"] or row["due_datetime"] or row["due_date"])
            if not due_at or due_at < now_value:
                due_at = datetime.combine(date.today() + timedelta(days=1), datetime.min.time()).replace(hour=9).astimezone()
                reminder_at = due_at
            title = row["title"] or reminder_type_label(row["reminder_type"])
            copied_id = reminder_insert({
                "student_id": row["student_id"],
                "reminder_type": row["reminder_type"] or "manual",
                "title": f"我的跟进：{title}",
                "description": row["description"] or row["notes"] or "",
                "related_module": row["related_module"] or "",
                "related_record_id": reminder_id,
                "assigned_to_user_id": self.user["id"],
                "assigned_to_name": self.user["display_name"],
                "priority": row["priority"] or "Normal",
                "due_datetime": due_at.isoformat(timespec="seconds"),
                "reminder_datetime": (reminder_at or due_at).isoformat(timespec="seconds"),
                "repeat_rule": row["repeat_rule"] or "none",
                "status": "Pending",
                "created_by": self.user["id"],
                "updated_by": self.user["id"],
                "source_type": "related_reminder",
                "source_record_id": reminder_id,
                "auto_generated": False,
                "suggested_action": "基于同事提醒继续跟进。",
                "notes": f"关联原提醒 #{reminder_id}",
            })
            db.audit(self.user, "reminder_copied_to_mine", "reminders", copied_id, old_value=str(reminder_id), new_value=title, student_id=row["student_id"], ip=self.client_address[0], device=self.headers.get("User-Agent"))
            return self.flash_redirect("/reminders?tab=manual", "已复制为你的个人后续提醒。")
        if action == "complete":
            if not can_reminder_action(self.user, "complete"):
                return self.deny_module_access("reminders")
            stamp = now_iso()
            result = complete_canonical_reminder(db, reminder_id, self.user["id"], stamp)
            changed = bool(result.pop("_changed", False))
            if changed:
                close_related_auto_reminders(reminder_id, "Completed", self.user["id"], "Manually completed related automatic reminder.")
            audit_action, msg = "reminder_completed", "提醒已完成。"
        elif action == "dismiss":
            if not can_reminder_action(self.user, "dismiss"):
                return self.deny_module_access("reminders")
            result = dismiss_canonical_reminder(db, reminder_id, self.user["id"], now_iso())
            changed = bool(result.pop("_changed", False))
            if changed:
                close_related_auto_reminders(reminder_id, "Dismissed", self.user["id"], "Manually dismissed related automatic reminder.")
            audit_action, msg = "reminder_dismissed", "提醒已忽略。"
        elif action == "cancel":
            if not can_reminder_action(self.user, "edit"):
                return self.deny_module_access("reminders")
            changed = row["status"] not in {"Completed", "Dismissed", "Cancelled"}
            if changed:
                db.execute("UPDATE reminders SET status='Cancelled',updated_by=?,updated_at=? WHERE id=? AND status NOT IN ('Completed','Dismissed','Cancelled')", (self.user["id"], now_iso(), reminder_id))
                close_related_auto_reminders(reminder_id, "Cancelled", self.user["id"], "Manually cancelled related automatic reminder.")
            result = {"status": "Cancelled" if changed else row["status"]}
            audit_action, msg = "reminder_cancelled", "提醒已取消。"
        elif action == "snooze":
            if not can_reminder_action(self.user, "complete"):
                return self.deny_module_access("reminders")
            option = str(self.form.get("snooze", "1h"))
            now_value = datetime.now().astimezone()
            if option == "30m":
                until = now_value + timedelta(minutes=30)
            elif option == "3h":
                until = now_value + timedelta(hours=3)
            elif option == "tomorrow":
                until = datetime.combine(date.today() + timedelta(days=1), datetime.min.time()).replace(hour=9).astimezone()
            else:
                until = now_value + timedelta(hours=1)
            result = snooze_canonical_reminder(
                db, reminder_id, self.user["id"], until.isoformat(), now_iso()
            )
            changed = bool(result.pop("_changed", False))
            audit_action, msg = "reminder_snoozed", "已稍后提醒。"
        else:
            return self.error_page("未知提醒操作", 400)
        if changed:
            db.audit(self.user, audit_action, "reminders", reminder_id, old_value=row["status"], new_value=action, student_id=row["student_id"], ip=self.client_address[0], device=self.headers.get("User-Agent"))
        else:
            audit_action = "reminder_action_noop"
            current_status = result.get("status") or row["status"]
            msg = f"提醒已是{reminder_status_label(current_status)}状态，未重复修改。"
            db.audit(self.user, audit_action, "reminders", reminder_id, old_value=row["status"], new_value=current_status, student_id=row["student_id"], ip=self.client_address[0], device=self.headers.get("User-Agent"))
        wants_json = "application/json" in (self.headers.get("Accept") or "") or self.headers.get("X-Requested-With") == "fetch"
        if wants_json:
            return self.json_response({"ok": True, "message": msg, "action": action, "reminder_id": reminder_id, "changed": changed, "status": result.get("status")})
        return self.flash_redirect("/reminders", msg)

    def reminder_settings(self, method):
        if not can_reminder_action(self.user, "manage_rules"):
            return self.deny_module_access("reminders")
        if method == "POST":
            keys = {
                "reminder_contract_enabled": "false", "reminder_contract_days_after_sent": "3",
                "reminder_contract_repeat_every_days": "2", "reminder_offer_enabled": "false",
                "reminder_offer_days_before_expiry": "14,7,3,1", "reminder_oshc_enabled": "false",
                "reminder_oshc_days_before_expiry": "30", "reminder_visa_enabled": "false",
                "reminder_visa_days_before_expiry": "180,90,30,14", "reminder_year_transition_enabled": "false",
                "reminder_year_transition_level": "Year 6", "reminder_year_transition_months_before": "6,3",
            }
            values = {}
            for key, default in keys.items():
                value = "true" if key.endswith("_enabled") and self.form.get(key) == "true" else str(self.form.get(key, default)).strip() or default
                db.set_setting(key, value, self.user["id"])
                values[key] = value
            db.audit(self.user, "reminder_rule_changed", "reminders", "settings", new_value=json.dumps(values, ensure_ascii=False), ip=self.client_address[0], device=self.headers.get("User-Agent"))
            return self.flash_redirect("/reminders/settings", "提醒规则已保存。")
        def checked(key):
            return "checked" if bool_setting(key, True) else ""
        body = f"""
        <div class="reminder-settings-page">
        <section class="panel"><div class="panel-head"><div><h2>提醒规则设置</h2><p>自动提醒规则只读取 CRM 数据库字段，不扫描学生文件夹。</p></div><a class="secondary button-link" href="/reminders">返回提醒中心</a></div>
          <form method="post" class="settings-grid">
            <input type="hidden" name="csrf" value="{esc(self.csrf)}">
            <div class="reminder-settings-section panel"><div class="reminder-settings-section-header"><h2>签约提醒</h2><span class="reminder-settings-note">已生效</span></div><label class="reminder-settings-enabled choice wide"><input type="checkbox" name="reminder_contract_enabled" value="true" {checked("reminder_contract_enabled")}><span>启用</span></label><label class="reminder-settings-field">发送后几天提醒<input name="reminder_contract_days_after_sent" value="{esc(db.setting("reminder_contract_days_after_sent", "3"))}"></label><label class="reminder-settings-field">每几天重复<input name="reminder_contract_repeat_every_days" value="{esc(db.setting("reminder_contract_repeat_every_days", "2"))}"><span class="reminder-settings-note">目前仅记录重复间隔，尚未接入重复调度。</span></label></div>
            <div class="reminder-settings-section panel"><div class="reminder-settings-section-header"><h2>Offer 过期提醒</h2><span class="reminder-settings-note">已生效</span></div><label class="reminder-settings-enabled choice wide"><input type="checkbox" name="reminder_offer_enabled" value="true" {checked("reminder_offer_enabled")}><span>启用</span></label><label class="reminder-settings-field">到期前天数<input name="reminder_offer_days_before_expiry" value="{esc(db.setting("reminder_offer_days_before_expiry", "14,7,3,1"))}"></label></div>
            <div class="reminder-settings-section panel"><div class="reminder-settings-section-header"><h2>OSHC 到期提醒</h2><span class="reminder-settings-note">已生效</span></div><label class="reminder-settings-enabled choice wide"><input type="checkbox" name="reminder_oshc_enabled" value="true" {checked("reminder_oshc_enabled")}><span>启用</span></label><label class="reminder-settings-field">到期前天数<input name="reminder_oshc_days_before_expiry" value="{esc(db.setting("reminder_oshc_days_before_expiry", "30"))}"><span class="reminder-settings-note">当前只使用第一个天数。</span></label></div>
            <div class="reminder-settings-section panel"><div class="reminder-settings-section-header"><h2>签证到期提醒</h2><span class="reminder-settings-note">已生效</span></div><label class="reminder-settings-enabled choice wide"><input type="checkbox" name="reminder_visa_enabled" value="true" {checked("reminder_visa_enabled")}><span>启用</span></label><label class="reminder-settings-field">到期前天数<input name="reminder_visa_days_before_expiry" value="{esc(db.setting("reminder_visa_days_before_expiry", "180,90,30,14"))}"></label></div>
            <div class="reminder-settings-section reminder-settings-unimplemented panel"><div class="reminder-settings-section-header"><h2>小学升中学提醒</h2><span>仅保存</span></div><label class="reminder-settings-enabled choice wide"><input type="checkbox" name="reminder_year_transition_enabled" value="true" {checked("reminder_year_transition_enabled")}><span>启用</span></label><label class="reminder-settings-field">触发年级<input name="reminder_year_transition_level" value="{esc(db.setting("reminder_year_transition_level", "Year 6"))}"></label><label class="reminder-settings-field">入读前月数<input name="reminder_year_transition_months_before" value="{esc(db.setting("reminder_year_transition_months_before", "6,3"))}"><span class="reminder-settings-note">当前仅保存设置，尚未接入自动生成。</span></label></div>
            <div class="reminder-settings-save-panel panel"><div><h2>保存</h2><p>面试提醒 MVP 通过自定义提醒创建；后续增加面试字段后可接入自动规则。</p></div><button class="primary">保存提醒规则</button></div>
          </form>
        </section>
        </div>"""
        self.send_html(page("提醒规则设置", body, self.user, self.csrf, "reminders", nas.status()))

    def students(self, method):
        if not self.require("students.view"):
            return
        q = (self.query.get("q") or [""])[0].strip()
        sort = (self.query.get("sort") or ["recent"])[0]
        view = "table"
        stage_filter = (self.query.get("stage") or [""])[0]
        lifecycle_type_filter = (self.query.get("lifecycle_type") or [""])[0]
        if lifecycle_type_filter not in {"", "initial", "transfer", "progression"}:
            lifecycle_type_filter = ""
        consultant_filter = (self.query.get("consultant_id") or [""])[0]
        year_filter = (self.query.get("year_level") or [""])[0]
        alert_filter = (self.query.get("alert") or [""])[0]
        contract_filter = (self.query.get("contract_status") or [""])[0]
        created_from = (self.query.get("created_from") or [""])[0]
        created_to = (self.query.get("created_to") or [""])[0]
        updated_from = (self.query.get("updated_from") or [""])[0]
        updated_to = (self.query.get("updated_to") or [""])[0]
        sort_options = {
            "recent": "最近更新",
            "created": "创建时间",
            "student_name": "学生姓名",
            "student_id": "Student ID",
            "stage": "当前阶段",
            "consultant": "负责顾问",
            "waiting": "等待家长",
            "risk": "风险优先",
            "offer_expiry": "Offer即将过期",
            "visa_expiry": "签证即将到期",
        }
        if sort not in sort_options:
            sort = "recent"
        params = []
        where_parts = ["s.deleted_at IS NULL"]
        if alert_filter == "missing_school_plan":
            where_parts.append(missing_school_plan_predicate("s"))
        if q:
            like = f"%{q}%"
            where_parts.append(
                """(s.student_id LIKE ? OR s.passport_first_name LIKE ? OR s.passport_last_name LIKE ?
                OR TRIM(COALESCE(s.passport_first_name,'') || ' ' || COALESCE(s.passport_last_name,'')) LIKE ?
                OR TRIM(COALESCE(s.passport_last_name,'') || ' ' || COALESCE(s.passport_first_name,'')) LIKE ?
                OR s.mobile_phone LIKE ? OR s.student_email LIKE ?
                OR EXISTS (
                    SELECT 1 FROM parents p WHERE p.student_id=s.student_id
                    AND (p.passport_first_name LIKE ? OR p.passport_last_name LIKE ? OR p.mobile LIKE ? OR p.email LIKE ?)
                ))"""
            )
            params.extend([like] * 11)
        if consultant_filter:
            where_parts.append("s.consultant_id=?")
            params.append(consultant_filter)
        if year_filter:
            where_parts.append("(s.current_year_level=? OR s.applying_year_level=?)")
            params.extend([year_filter, year_filter])
        if contract_filter:
            where_parts.append("EXISTS (SELECT 1 FROM contracts c WHERE c.student_id=s.student_id AND c.contract_status=?)")
            params.append(contract_filter)
        if created_from:
            where_parts.append("date(s.created_date)>=date(?)")
            params.append(created_from)
        if created_to:
            where_parts.append("date(s.created_date)<=date(?)")
            params.append(created_to)
        if updated_from:
            where_parts.append("date(s.updated_at)>=date(?)")
            params.append(updated_from)
        if updated_to:
            where_parts.append("date(s.updated_at)<=date(?)")
            params.append(updated_to)
        where = "WHERE " + " AND ".join(where_parts) if where_parts else ""
        rows_data = db.all(
            f"""SELECT s.*,u.display_name consultant_name,w.materials_checked,w.current_stage
                FROM students s LEFT JOIN users u ON u.id=s.consultant_id
                LEFT JOIN workflow_status w ON w.student_id=s.student_id {where}
                ORDER BY s.updated_at DESC""",
            params,
        )
        summary_connection = db.connect()
        try:
            summary_map = load_student_management_summary_map(
                summary_connection, [row["student_id"] for row in rows_data]
            )
        finally:
            db._release_connection(summary_connection)
        if stage_filter:
            if stage_filter == "transfer_active":
                rows_data = [row for row in rows_data if is_active_transfer_stage(
                    summary_map[row["student_id"]].lifecycle_type,
                    summary_map[row["student_id"]].stage_key,
                )]
            else:
                rows_data = [
                    row for row in rows_data
                    if summary_map[row["student_id"]].stage_key == stage_filter
                ]
        if lifecycle_type_filter:
            rows_data = [
                row for row in rows_data
                if summary_map[row["student_id"]].lifecycle_type
                == lifecycle_type_filter
            ]
        student_ids = [row["student_id"] for row in rows_data]
        uploaded_by_student = {student_id: set() for student_id in student_ids}
        for row in db.all("SELECT student_id,document_type FROM student_documents WHERE is_active=1"):
            if row["student_id"] in uploaded_by_student:
                uploaded_by_student[row["student_id"]].add(row["document_type"])
        offer_expiry = {}
        for row in db.all("SELECT student_id,MIN(offer_expiry_date) offer_expiry_date FROM offers WHERE offer_expiry_date IS NOT NULL AND offer_expiry_date<>'' GROUP BY student_id"):
            offer_expiry[row["student_id"]] = row["offer_expiry_date"]
        visa_expiry = {}
        for row in db.all("SELECT student_id,MIN(visa_expiry_date) visa_expiry_date FROM visas WHERE visa_expiry_date IS NOT NULL AND visa_expiry_date<>'' GROUP BY student_id"):
            visa_expiry[row["student_id"]] = row["visa_expiry_date"]
        row_alerts = {
            row["student_id"]: workflow_alert_tags(row, uploaded_by_student.get(row["student_id"], set()), offer_expiry.get(row["student_id"], ""), visa_expiry.get(row["student_id"], ""))
            for row in rows_data
        }
        if alert_filter and alert_filter != "missing_school_plan":
            def alert_matches(row):
                keys = {item.get("key") for item in row_alerts[row["student_id"]]}
                levels = {item.get("level") for item in row_alerts[row["student_id"]]}
                if alert_filter == "waiting":
                    return "waiting" in levels
                if alert_filter == "risk":
                    return "risk" in levels
                if alert_filter == "materials_pending":
                    return not bool(row["materials_checked"])
                if alert_filter == "missing_docs":
                    return bool({"missing_passport", "missing_birth"} & keys)
                return alert_filter in keys
            rows_data = [row for row in rows_data if alert_matches(row)]
        next_actions = {
            row["student_id"]: row
            for row in db.all(
                """SELECT r.* FROM reminders r
                   JOIN (SELECT student_id,MAX(id) id FROM reminders WHERE reminder_type='next_action' AND status='open' GROUP BY student_id) latest
                   ON latest.id=r.id"""
            )
        }
        latest_tokens = {}
        for token_row in db.all("SELECT * FROM parent_form_tokens WHERE student_id IS NOT NULL AND student_id<>'' ORDER BY created_at DESC"):
            if token_row["student_id"] not in latest_tokens:
                latest_tokens[token_row["student_id"]] = token_row
        if sort == "stage":
            rows_data = sorted(
                rows_data,
                key=lambda row: (
                    summary_map[row["student_id"]].stage_order,
                    summary_map[row["student_id"]].student_name.casefold(),
                ),
            )
        elif sort == "waiting":
            rows_data = sorted(rows_data, key=lambda row: ("waiting" not in {item.get("level") for item in row_alerts[row["student_id"]]}, row["updated_at"] or ""), reverse=False)
        elif sort == "risk":
            rows_data = sorted(rows_data, key=lambda row: ("risk" not in {item.get("level") for item in row_alerts[row["student_id"]]}, row["updated_at"] or ""), reverse=False)
        elif sort == "offer_expiry":
            rows_data = sorted(rows_data, key=lambda row: (offer_expiry.get(row["student_id"], "9999-12-31"), row["updated_at"] or ""))
        elif sort == "visa_expiry":
            rows_data = sorted(rows_data, key=lambda row: (visa_expiry.get(row["student_id"], "9999-12-31"), row["updated_at"] or ""))
        elif sort == "consultant":
            rows_data = sorted(rows_data, key=lambda row: ((row["consultant_name"] or "未分配").lower(), row["passport_first_name"] or ""))
        elif sort == "student_name":
            rows_data = sorted(rows_data, key=lambda row: student_display_name(row).lower())
        elif sort == "student_id":
            rows_data = sorted(rows_data, key=lambda row: row["student_id"])
        elif sort == "created":
            rows_data = sorted(rows_data, key=lambda row: row["created_date"] or "", reverse=True)
        else:
            rows_data = sorted(rows_data, key=lambda row: row["updated_at"] or row["created_date"] or "", reverse=True)
        sort_select = "".join(
            f'<option value="{esc(key)}" {"selected" if sort == key else ""}>{esc(label)}</option>'
            for key, label in sort_options.items()
        )
        active_stage_definitions = (
            CANONICAL_APPLICATION_STAGE_DEFINITIONS
            if any(
                str(summary.stage_key)[:2].isdigit()
                for summary in summary_map.values()
            )
            else APPLICATION_STAGE_DEFINITIONS
        )
        management_stages = (
            (("not_started", "尚未开始申请"),)
            + active_stage_definitions
            + (("granted", "已下签"), ("refused", "已拒签"), ("closed", "申请已结案"))
        )
        known_management_stages = {key for key, _label in management_stages}
        observed_management_stages = []
        for summary in sorted(
            summary_map.values(), key=lambda item: (item.stage_order, item.stage_key)
        ):
            if summary.stage_key and summary.stage_key not in known_management_stages:
                observed_management_stages.append(
                    (summary.stage_key, summary.stage_label)
                )
                known_management_stages.add(summary.stage_key)
        management_stages += tuple(observed_management_stages)
        stage_options = '<option value="">全部阶段</option>' + "".join(
            f'<option value="{esc(stage)}" {"selected" if stage_filter == stage else ""}>{esc(label)}</option>'
            for stage, label in management_stages
        )
        lifecycle_type_options = "".join(
            f'<option value="{esc(key)}" {"selected" if lifecycle_type_filter == key else ""}>{label}</option>'
            for key, label in (
                ("", "全部 Lifecycle"), ("initial", "Initial"),
                ("transfer", "Transfer"), ("progression", "Progression"),
            )
        )
        consultants = db.all("SELECT id,display_name FROM users WHERE is_active=1 AND deleted_at IS NULL ORDER BY display_name")
