    def soft_delete_student_record(self, student_id):
        student = db.one("SELECT student_id,deleted_at FROM students WHERE student_id=?", (student_id,))
        if not student or student["deleted_at"]:
            return False
        db.execute(
            "UPDATE students SET deleted_at=?,deleted_by=?,updated_at=?,updated_by=? WHERE student_id=?",
            (now_iso(), self.user["id"], now_iso(), self.user["id"], student_id),
        )
        db.audit(
            self.user, "student_deleted", "students", student_id,
            new_value=json.dumps({"deleted_at": now_iso()}, ensure_ascii=False),
            ip=self.client_address[0], device=self.headers.get("User-Agent"), student_id=student_id,
        )
        return True

    def bulk_soft_delete_student_records(self, student_ids):
        changed = []
        seen = set()
        for value in student_ids or []:
            student_id = str(value or "").strip()
            if not student_id.isdigit() or student_id in seen:
                continue
            seen.add(student_id)
            if self.soft_delete_student_record(student_id):
                changed.append(student_id)
        if changed:
            db.audit(
                self.user, "students_bulk_deleted", "students", "bulk-delete",
                new_value=json.dumps({"count": len(changed), "student_ids": changed}, ensure_ascii=False),
                ip=self.client_address[0], device=self.headers.get("User-Agent"),
            )
        return changed

    def bulk_manual_update_workflow_stage_records(self, student_ids, target_stage):
        if is_workflow_v2_active(db):
            raise CycleConflictError(
                "canonical Workflow V2 does not accept bulk legacy stage writes"
            )
        valid_stages = {stage for stage, _label in WORKFLOW_STAGES}
        target_stage = normalize_workflow_stage(target_stage)
        if target_stage not in valid_stages:
            return []
        changed = []
        old_stages = {}
        seen = set()
        stamp = now_iso()
        for value in student_ids or []:
            student_id = str(value or "").strip()
            if not student_id.isdigit() or student_id in seen:
                continue
            seen.add(student_id)
            student = db.one(
                "SELECT student_id,current_status FROM students WHERE student_id=? AND deleted_at IS NULL",
                (student_id,),
            )
            if not student:
                continue
            workflow = db.one("SELECT current_stage FROM workflow_status WHERE student_id=?", (student_id,))
            old_stage = normalize_workflow_stage((workflow["current_stage"] if workflow else "") or student["current_status"])
            old_stages[student_id] = old_stage
            if workflow:
                db.execute("UPDATE workflow_status SET current_stage=? WHERE student_id=?", (target_stage, student_id))
            else:
                db.execute(
                    "INSERT INTO workflow_status(student_id,current_stage) VALUES(?,?)",
                    (student_id, target_stage),
                )
            db.execute(
                "UPDATE students SET current_status=?,updated_at=? WHERE student_id=?",
                (target_stage, stamp, student_id),
            )
            changed.append(student_id)
        if changed:
            db.audit(
                self.user,
                "workflow_stage_manual_bulk_updated",
                "students",
                "bulk-workflow-stage",
                old_value=json.dumps({"student_old_stages": old_stages}, ensure_ascii=False),
                new_value=json.dumps({"target_stage": target_stage, "student_ids": changed}, ensure_ascii=False),
                ip=self.client_address[0],
                device=self.headers.get("User-Agent"),
            )
        return changed

    def restore_student_record(self, student_id):
        student = db.one("SELECT student_id,deleted_at FROM students WHERE student_id=?", (student_id,))
        if not student or not student["deleted_at"]:
            return False
        db.execute(
            "UPDATE students SET deleted_at=NULL,deleted_by=NULL,updated_at=?,updated_by=? WHERE student_id=?",
            (now_iso(), self.user["id"], student_id),
        )
        db.audit(
            self.user, "student_restored", "students", student_id,
            new_value=json.dumps({"restored_at": now_iso()}, ensure_ascii=False),
            ip=self.client_address[0], device=self.headers.get("User-Agent"), student_id=student_id,
        )
        return True

    def student_delete_restore(self, method, student_id, action):
        if method != "POST":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        if not can_delete_student_record(self.user):
            return self.deny_module_access("students")
        if action == "delete":
            ok = self.soft_delete_student_record(student_id)
            return self.flash_redirect("/students", "学生已删除，可在已删除学生中恢复。" if ok else "学生不存在或已经删除。", "ok" if ok else "error")
        ok = self.restore_student_record(student_id)
        return self.flash_redirect("/students/deleted", "学生已恢复。" if ok else "学生不存在或未处于删除状态。", "ok" if ok else "error")

    def students_bulk_delete(self, method):
        if method != "POST":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        if not can_delete_student_record(self.user):
            return self.deny_module_access("students")
        student_ids = split_multi(self.form, "student_ids")
        if not student_ids:
            return self.flash_redirect("/students", "请选择要删除的学生。", "error")
        changed = self.bulk_soft_delete_student_records(student_ids)
        if not changed:
            return self.flash_redirect("/students", "没有可删除的学生；可能已被删除或记录不存在。", "error")
        return self.flash_redirect("/students", f"已批量删除 {len(changed)} 个学生，可在已删除学生中恢复。")

    def students_bulk_workflow_stage(self, method):
        if method != "POST":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        if not self.require("students.edit"):
            return
        student_ids = split_multi(self.form, "student_ids")
        if not student_ids:
            return self.flash_redirect("/students", "请选择要更新阶段的学生。", "error")
        requested_stage = str(self.form.get("stage", "")).strip()
        if not requested_stage:
            return self.flash_redirect("/students", "请选择有效目标阶段。", "error")
        target_stage = normalize_workflow_stage(requested_stage)
        if target_stage not in {stage for stage, _label in WORKFLOW_STAGES}:
            return self.flash_redirect("/students", "请选择有效目标阶段。", "error")
        if is_workflow_v2_active(db):
            return self.flash_redirect(
                "/students",
                "Workflow V2 阶段由业务事件自动计算，不能批量写入旧阶段字段。",
                "error",
            )
        changed = self.bulk_manual_update_workflow_stage_records(student_ids, target_stage)
        if not changed:
            return self.flash_redirect("/students", "没有可更新阶段的学生；可能已删除或记录不存在。", "error")
        return self.flash_redirect(
            "/students",
            f"已手动更新 {len(changed)} 名学生的 Workflow 当前阶段为：{workflow_stage_label(target_stage)}。",
        )

    def deleted_students(self, method):
        if method != "GET":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        if not can_delete_student_record(self.user):
            return self.deny_module_access("students")
        rows = db.all(
            """SELECT s.*,u.display_name consultant_name,deleter.display_name deleted_by_name
               FROM students s
               LEFT JOIN users u ON u.id=s.consultant_id
               LEFT JOIN users deleter ON deleter.id=s.deleted_by
               WHERE s.deleted_at IS NOT NULL
               ORDER BY s.deleted_at DESC"""
        )
        table_rows = "".join(
            f"""<tr>
              <td><code>{esc(row['student_id'])}</code></td>
              <td>{esc(student_display_name(row))}</td>
              <td>{esc(row['consultant_name'] or '未分配')}</td>
              <td>{esc(display_datetime(row['deleted_at']))}</td>
              <td>{esc(row['deleted_by_name'] or '')}</td>
              <td><form class="inline-form" method="post" action="/students/{esc(row['student_id'])}/restore" onsubmit="return confirm('确认恢复这个学生？');"><input type="hidden" name="csrf" value="{esc(self.csrf)}"><button class="secondary compact">恢复</button></form></td>
            </tr>"""
            for row in rows
        ) or '<tr><td colspan="6" class="empty">没有已删除学生</td></tr>'
        body = f"""
        <section class="panel deleted-students-page">
          <div class="panel-head"><div><h2>已删除学生</h2><p>这里显示软删除的学生记录。恢复后会重新回到学生列表。</p></div><a class="secondary button-link" href="/students">返回学生管理</a></div>
          <div class="table-wrap"><table><thead><tr><th>Student ID</th><th>学生</th><th>顾问</th><th>删除时间</th><th>删除人</th><th>操作</th></tr></thead><tbody>{table_rows}</tbody></table></div>
        </section>"""
        message, kind = self.message()
        self.send_html(page("已删除学生", body, self.user, self.csrf, "students", nas.status(), message, kind))

    def student_next_action_update(self, method, student_id):
        if method != "POST" or not self.require("students.edit"):
            return
        student = db.one("SELECT * FROM students WHERE student_id=?", (student_id,))
        if not student:
            return self.flash_redirect("/students", "学生不存在", "error")
        next_action = (self.form.get("next_action") or "").strip()
        if not next_action:
            return self.flash_redirect("/students", "请填写下一步事项。", "error")
        due_date = (self.form.get("due_date") or "").strip() or date.today().isoformat()
        payload = {
            "next_action": next_action,
            "assigned_to": (self.form.get("assigned_to") or "").strip(),
            "priority": (self.form.get("priority") or "Normal").strip(),
            "notes": (self.form.get("notes") or "").strip(),
        }
        old = db.one("SELECT * FROM reminders WHERE student_id=? AND reminder_type='next_action' AND status='open' ORDER BY id DESC LIMIT 1", (student_id,))
        reminder_insert({
            "student_id": student_id,
            "reminder_type": "next_action",
            "due_date": due_date,
            "status": "open",
            "notes": json.dumps(payload, ensure_ascii=False),
            "source_type": "manual",
            "source_record_id": student_id,
            "source_module": "students",
            "source_object_type": "student",
            "source_object_id": student_id,
            "source_event_type": "student.next_action.created",
        })
        db.audit(
            self.user, "next_action_updated", "students", student_id,
            old_value=old["notes"] if old else "", new_value=json.dumps({"due_date": due_date, **payload}, ensure_ascii=False),
            ip=self.client_address[0], device=self.headers.get("User-Agent"), student_id=student_id,
        )
        return self.flash_redirect("/students", "下一步事项已更新。")

    def student_workflow_stage_update(self, method, student_id):
        if method != "POST" or not self.require("students.edit"):
            return
        if is_workflow_v2_active(db):
            return self.flash_redirect(
                "/students",
                "Workflow V2 阶段由业务事件自动计算，不能直接写入旧阶段字段。",
                "error",
            )
        row = db.one("SELECT current_stage FROM workflow_status WHERE student_id=?", (student_id,))
        if not row:
            return self.flash_redirect("/students", "学生流程不存在", "error")
        old_stage = normalize_workflow_stage(row["current_stage"])
        requested = normalize_workflow_stage(self.form.get("stage") or "")
        set_workflow_stage(student_id, requested)
        new_row = db.one("SELECT current_stage FROM workflow_status WHERE student_id=?", (student_id,))
        new_stage = normalize_workflow_stage(new_row["current_stage"]) if new_row else old_stage
        db.audit(
            self.user, "workflow_stage_updated", "students", student_id,
            old_value=old_stage, new_value=f"requested:{requested}; applied:{new_stage}",
            ip=self.client_address[0], device=self.headers.get("User-Agent"), student_id=student_id,
        )
        message = "当前阶段已按系统顺序推进。" if new_stage != old_stage else "当前阶段未变化；系统不允许跳步或倒退。"
        return self.flash_redirect("/students", message)

    def student_parent_link_create(self, method, student_id):
        if method != "POST" or not self.require("students.edit"):
            return
        route_start = time.perf_counter()
        student = db.one("SELECT * FROM students WHERE student_id=?", (student_id,))
        if not student:
            return self.flash_redirect("/students", "学生不存在", "error")
        student_hint = student_display_name(student)
        try:
            link_record = secure_parent_form_service().create_link(
                consultant_id=student["consultant_id"] or self.user["id"],
                student_hint=student_hint,
                created_by=self.user["id"],
                student_id=student_id,
                intake_type=self.form.get("intake_type"),
            )
        except CycleConflictError as exc:
            return self.flash_redirect(
                f"/students/{quote(student_id)}?tab=profile",
                f"无法建立家长表单：{exc}",
                "error",
            )
        token = link_record.token
        db.audit(
            self.user, "parent_form_token_created", "parent_form", token,
            new_value=parent_form_url(token), ip=self.client_address[0], device=self.headers.get("User-Agent"), student_id=student_id,
        )
        link = parent_form_url(token)
        student_perf_log("parent_link_generated", student_id, elapsed_ms=perf_ms(route_start))
        return self.toast_redirect(
            f"/students/{quote(student_id)}?tab=profile",
            f"家长表单链接已生成：{link}",
            title="家长链接已生成",
            copy_text=link,
        )

    def student_new(self, method):
        if not self.require("students.edit"):
            return
        if method == "GET":
            body = f'<div class="student-new-page">{internal_student_form("/students/new", self.csrf)}</div>'
            return self.send_html(page("手动新建学生", body, self.user, self.csrf, "students", nas.status()))
        data = normalize_form(self.form)
        missing_names = missing_student_fields(data)
        missing = missing_student_labels(missing_names)
        if missing:
            body = f'<div class="student-new-page">{internal_student_form("/students/new", self.csrf, missing, data, missing_names)}</div>'
            return self.send_html(page("手动新建学生", body, self.user, self.csrf, "students", nas.status()), 422)
        student_id = create_student_from_form(data, consultant_id=self.user["id"], source_token="manual")
        db.audit(self.user, "create", "students", student_id, new_value="manual")
        return self.flash_redirect(f"/students/{student_id}", f"学生已创建：{student_id}")

    def student_import(self, method):
        if method != "POST" or not self.require("students.edit"):
            return
        upload = self.uploaded_for("template")
        if not upload:
            raise ValueError("请选择 AAIE 学生信息 Excel 模板")
        if not upload.filename.lower().endswith(".xlsx"):
            raise ValueError("请上传 .xlsx 格式的 AAIE 学生信息模板")
        data = data_from_template_bytes(upload.data)
        missing = validate_student_data(data)
        if missing:
            return self.flash_redirect("/students", "Excel 模板缺少必填项：" + "、".join(missing), "error")
        student_id = create_student_from_form(data, consultant_id=self.user["id"], source_token="excel_template")
        db.audit(self.user, "create", "students", student_id, new_value=f"excel_template:{upload.filename}")
        return self.flash_redirect(f"/students/{student_id}", f"已从 Excel 模板创建学生：{student_id}")

    def student_template_download(self, method):
        if not self.require("students.edit"):
            return
        path = ensure_student_template()
        payload = path.read_bytes()
        self.send_response(200)
        self.send_header("Content-Type", "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")
        self.send_header("Content-Disposition", f"attachment; filename*=UTF-8''{quote(path.name)}")
        self.send_header("Content-Length", str(len(payload)))
        self.end_headers()
        self.wfile.write(payload)

    def student_profile_edit(self, method, student_id):
        if not can_edit_student_profile(self.user):
            return self.deny_module_access("students")
        student = db.one("SELECT * FROM students WHERE student_id=?", (student_id,))
        if not student:
            return self.error_page("学生不存在", 404)
        values = student_form_values(student)
        if method == "GET":
            body = student_edit_form(f"/students/{student_id}/edit", self.csrf, values)
            return self.send_html(page("编辑学生资料", body, self.user, self.csrf, "students", nas.status()))
        if method != "POST":
            return self.error_page("方法不允许", 405)
        data = normalize_form(self.form)
        missing_names = missing_student_fields(data)
        missing = missing_student_labels(missing_names)
        if missing:
            body = student_edit_form(f"/students/{student_id}/edit", self.csrf, data, missing, missing_names)
            return self.send_html(page("编辑学生资料", body, self.user, self.csrf, "students", nas.status()), 422)
        old_folder = student["folder_path"]
        old_student_id = student["student_id"]
        changes = update_student_profile(student, data, self.user, self.client_address[0], self.headers.get("User-Agent"))
        refreshed = db.one("SELECT * FROM students WHERE student_id=?", (student_id,))
        if refreshed["student_id"] != old_student_id or refreshed["folder_path"] != old_folder:
            return self.error_page("安全检查失败：Student ID 或学生文件夹路径发生变化。", 500)
        doc_message = ""
        if self.form.get("regenerate_studentinfo") == "yes":
            try:
                target = regenerate_student_info_version(refreshed, self.user)
                doc_message = f" 已重新生成：{target.name}"
            except Exception as exc:
                doc_message = f" StudentInfo.docx 未重新生成：{exc}"
        return self.flash_redirect(f"/students/{student_id}?tab=profile", f"学生资料已更新，共 {len(changes)} 项变化。{doc_message}")

