    def student_visa_result_display(self, case):
        if not case:
            return "Pending"
        result = str((case["result_status"] if "result_status" in case.keys() else "") or "").strip()
        decision = str((case["decision_status"] if "decision_status" in case.keys() else "") or "").strip()
        status = str((case["status"] if "status" in case.keys() else "") or "").strip()
        value = result or decision
        if not value or value == "Pending":
            lowered = status.lower()
            if lowered in {"granted", "refused", "withdrawn", "closed"}:
                value = status
            else:
                value = "Pending"
        return value

