    def progression_case_route_error(self, error):
        if isinstance(error, ProgressionCaseNotFoundError):
            return self.error_page("升学Case不存在。", HTTPStatus.NOT_FOUND)
        if isinstance(error, ProgressionCaseError):
            status = HTTPStatus.FORBIDDEN if getattr(error, "code", "") == "progression_case_access_denied" else HTTPStatus.BAD_REQUEST
            return self.error_page("升学Case操作未能安全完成。", status)
        if isinstance(error, ValueError):
            return self.error_page("升学Case字段无效。", HTTPStatus.BAD_REQUEST)
        if isinstance(error, sqlite3.IntegrityError):
            return self.error_page("升学Case关联数据无效。", HTTPStatus.BAD_REQUEST)
        raise error

    def student_lifecycle_module_disposition(
        self, method, student_id, cycle_id, module_key
    ):
        if method != "POST":
            return self.error_page(
                "只允许POST。", HTTPStatus.METHOD_NOT_ALLOWED
            )
        allowed_fields = {
            "csrf", "event_uid", "handling", "existing_choice", "reason",
            # Compatibility for already-open pages rendered before this UI
            # convergence.  New Student Profile forms never expose these.
            "disposition", "source_record_type", "source_record_id",
        }
        if set(self.form) - allowed_fields or module_key not in LIFECYCLE_MODULE_KEYS:
            return self.error_page("包含未允许字段。", HTTPStatus.BAD_REQUEST)
        connection = sqlite3.connect(db.path)
        connection.row_factory = sqlite3.Row
        connection.execute("PRAGMA foreign_keys=ON")
        try:
            connection.execute("BEGIN IMMEDIATE")
            cycle = connection.execute(
                """SELECT cycle.id,cycle.student_id,cycle.cycle_type,
                          cycle.status,cycle.source_student_case_id
                     FROM application_cycles AS cycle
                    WHERE cycle.id=? AND cycle.student_id=?""",
                (int(cycle_id), str(student_id)),
            ).fetchone()
            if cycle is None:
                connection.rollback()
                return self.error_page(
                    "Lifecycle不存在。", HTTPStatus.NOT_FOUND
                )
            permission = (
                "progression_cases.update"
                if cycle["cycle_type"] == "progression"
                else "student_cases.edit"
            )
            if cycle["cycle_type"] not in {"transfer", "progression"} or (
                not allowed(self.user, permission)
            ):
                connection.rollback()
                return self.error_page("无权限。", HTTPStatus.FORBIDDEN)
            if cycle["status"] != "active":
                connection.rollback()
                return self.error_page(
                    "只能更新当前Active Lifecycle。", HTTPStatus.CONFLICT
                )
            handling = form_text_value(self.form, "handling").strip()
            if handling:
                resolved = resolve_business_submission(
                    connection,
                    application_cycle_id=int(cycle_id),
                    module_key=module_key,
                    handling=handling,
                    existing_choice=(
                        form_text_value(self.form, "existing_choice").strip()
                        or None
                    ),
                    reason=form_text_value(self.form, "reason") or None,
                )
                disposition = resolved.disposition
                reason = resolved.reason
                source_type = resolved.source_record_type
                source_id = resolved.source_record_id
            else:
                source_type = form_text_value(
                    self.form, "source_record_type"
                ).strip() or None
                source_id_text = form_text_value(
                    self.form, "source_record_id"
                ).strip()
                source_id = int(source_id_text) if source_id_text else None
                disposition = form_text_value(self.form, "disposition")
                reason = form_text_value(self.form, "reason") or None
            record_module_disposition(
                connection,
                event_uid=form_text_value(self.form, "event_uid"),
                application_cycle_id=int(cycle_id),
                module_key=module_key,
                disposition=disposition,
                reason=reason,
                source_record_type=source_type,
                source_record_id=source_id,
                actor_user_id=int(self.user["id"]),
                occurred_at=now_iso(),
            )
            connection.commit()
        except (
            BusinessDispositionSelectionError,
            ModuleDispositionError,
            TypeError,
            ValueError,
        ):
            connection.rollback()
            return self.flash_redirect(
                f"/students/{quote(str(student_id))}#workflow-progress",
                "模块处理方式未保存：请检查本轮选择及说明。",
                "error",
            )
        except Exception:
            connection.rollback()
            raise
        finally:
            connection.close()
        return self.flash_redirect(
            f"/students/{quote(str(student_id))}#workflow-progress",
            "本轮处理方式已保存。",
        )

    def progression_case_context(self, student_id, case_id):
        service = ProgressionCaseService(db.path)
        case = service.get_case(int(case_id))
        if case.student_id != str(student_id):
            raise ProgressionCaseNotFoundError(case_id)
        return service, case

