    def student_progression_case_activate(self, method, student_id, case_id):
        if method != "POST":
            return self.error_page("只允许POST。", HTTPStatus.METHOD_NOT_ALLOWED)
        if not self.require("students.view"):
            return
        flags = self.transfer_case_flags()
        student = self.student_capability_subject(student_id)
        if not student:
            return self.error_page("学生不存在", HTTPStatus.NOT_FOUND)
        if (
            not student_capabilities.can_edit_progression_case(
                self.user, student, flags=flags
            )
            or set(self.form) - {
                "csrf", "idempotency_key", "takeover_confirmed"
            }
        ):
            return self.error_page("无权限或字段无效。", HTTPStatus.FORBIDDEN)
        try:
            service, case = self.progression_case_context(student_id, case_id)
            key = form_text_value(self.form, "idempotency_key")
            service.activate_case(
                case.case_id,
                actor_user_id=int(self.user["id"]),
                idempotency_key=key,
                takeover_confirmed=(
                    form_text_value(self.form, "takeover_confirmed") == "1"
                ),
            )
            self.progression_audit(
                "progression_lifecycle_activated",
                student_id,
                case.case_id,
                {"idempotency_key": key},
            )
        except (ProgressionCaseError, ValueError, sqlite3.IntegrityError) as error:
            return self.progression_case_route_error(error)
        return self.progression_case_redirect(
            student_id, case.case_id, "升学Lifecycle已激活。"
        )

    def student_progression_case_cancel(self, method, student_id, case_id):
        if method != "POST":
            return self.error_page("只允许POST。", HTTPStatus.METHOD_NOT_ALLOWED)
        if not self.require("students.view"):
            return
        flags = self.transfer_case_flags()
        student = self.student_capability_subject(student_id)
        if (
            not student
            or not student_capabilities.can_edit_progression_case(
                self.user, student, flags=flags
            )
            or set(self.form) - {"csrf", "reason", "idempotency_key"}
        ):
            return self.error_page("无权限或字段无效。", HTTPStatus.FORBIDDEN)
        try:
            _service, case = self.progression_case_context(student_id, case_id)
            if case.status != "draft":
                return self.error_page(
                    "只有 Draft 可以从此入口取消。",
                    HTTPStatus.BAD_REQUEST,
                )
            StudentLifecycleService(
                db.path,
                clock=lambda: datetime.now(timezone.utc).isoformat(),
            ).cancel_lifecycle(
                case_id=case.case_id,
                actor_user_id=int(self.user["id"]),
                reason=form_text_value(self.form, "reason"),
                idempotency_key=form_text_value(self.form, "idempotency_key"),
            )
            self.progression_audit(
                "progression_lifecycle_cancelled", student_id, case.case_id
            )
        except StudentLifecycleError:
            return self.error_page(
                "Progression Draft取消未能安全完成。",
                HTTPStatus.BAD_REQUEST,
            )
        except (ProgressionCaseError, ValueError) as error:
            return self.progression_case_route_error(error)
        return self.flash_redirect(
            f"/students/{quote(str(student_id))}/progression-cases",
            "Progression Draft已取消。",
        )

    def student_progression_case_edit(self, method, student_id, case_id):
        if method!="POST": return self.error_page("只允许POST。",HTTPStatus.METHOD_NOT_ALLOWED)
        flags=self.transfer_case_flags(); allowed={"csrf","priority","target_education_stage","target_course_type","target_institution_id","target_institution_name_snapshot","target_start_date","notes"}
        if not self.require("students.view"): return
        student = self.student_capability_subject(student_id)
        if not student:
            return self.error_page("学生不存在", HTTPStatus.NOT_FOUND)
        if not student_capabilities.can_edit_progression_case(self.user, student, flags=flags) or set(self.form)-allowed: return self.error_page("无权限或字段无效。",HTTPStatus.FORBIDDEN)
        try:
            service,_=self.progression_case_context(student_id,case_id)
            changes={key:form_text_value(self.form,key) or None for key in allowed if key!="csrf"}
            changes={key:value for key,value in changes.items() if value is not None}
            if "target_institution_id" in changes: changes["target_institution_id"]=self.transfer_case_optional_id(changes["target_institution_id"])
            service.update_case(int(case_id),changes=changes,actor_user_id=int(self.user["id"]),actor_permissions=get_permissions(self.user),flags=flags)
            self.progression_audit("progression_case_updated",student_id,case_id,changes)
        except (ProgressionCaseError,ValueError,sqlite3.IntegrityError) as error: return self.progression_case_route_error(error)
        return self.progression_case_redirect(student_id,case_id,"升学Case已更新。")

