    def student_progression_target_application_final(
        self, method, student_id, case_id, application_id
    ):
        if method != "POST":
            return self.error_page("只允许POST。", HTTPStatus.METHOD_NOT_ALLOWED)
        if not self.require("students.view") or set(self.form) - {
            "csrf", "canonical_application_kind"
        }:
            return self.error_page("无权限或字段无效。", HTTPStatus.FORBIDDEN)
        try:
            service, _ = self.progression_case_context(student_id, case_id)
            current = next(
                (
                    item for item in service.get_case_data(int(case_id))[
                        "target_applications"
                    ]
                    if int(item["id"]) == int(application_id)
                ),
                None,
            )
            if current and current["is_final"]:
                service.deselect_final_application(
                    int(case_id), int(application_id),
                    actor_user_id=int(self.user["id"]),
                    actor_permissions=get_permissions(self.user),
                    flags=self.transfer_case_flags(),
                )
                event_type = "progression_final_application_deselected"
                message = "已从最终升学方案中取消。"
            else:
                canonical_application_kind = form_text_value(
                    self.form, "canonical_application_kind"
                )
                if canonical_application_kind not in {"public", "private"}:
                    raise ProgressionCaseError(
                        "最终升学方案必须明确选择 Public 或 Private Application"
                    )
                service.select_final_application(
                    int(case_id), int(application_id),
                    actor_user_id=int(self.user["id"]),
                    actor_permissions=get_permissions(self.user),
                    flags=self.transfer_case_flags(),
                    canonical_application_kind=canonical_application_kind,
                )
                event_type = "progression_final_application_selected"
                message = "已加入最终升学方案。"
            self.progression_audit(
                event_type, student_id, case_id,
                {"target_application_id": int(application_id)},
            )
        except (ProgressionCaseError, ValueError, sqlite3.IntegrityError) as error:
            return self.progression_case_route_error(error)
        return self.progression_case_redirect(
            student_id, case_id, message
        )

