    def transfer_case_flags(self):
        return student_case_views.resolve_student_case_feature_flags(
            getattr(self, "student_case_feature_flags", None),
            setting_reader=db.setting,
        )

    def transfer_case_staff_users(self):
        flags = self.transfer_case_flags()
        rows = db.all(
                """SELECT u.id,u.username,u.display_name,r.name role_name,
                          r.permissions_json
                   FROM users u JOIN roles r ON r.id=u.role_id
                   WHERE is_active=1
                   ORDER BY lower(coalesce(u.display_name,u.username,'')),u.id"""
        )
        result = []
        for row in rows:
            candidate = dict(row)
            candidate["permissions"] = get_permissions(candidate)
            if not student_capabilities.can_assign_transfer_case(
                candidate, None, flags=flags
            ):
                continue
            candidate["is_current"] = int(candidate["id"]) == int(self.user["id"])
            result.append(candidate)
        return result

    def progression_case_staff_users(self):
        return [
            dict(row)
            for row in db.all(
                """SELECT id,username,display_name
                   FROM users WHERE is_active=1
                   ORDER BY lower(coalesce(display_name,username,'')),id"""
            )
        ]

    def progression_case_school_choices(self):
        columns = {
            str(row["name"])
            for row in db.all("PRAGMA table_info(schools)")
        }
        select_parts = ["id"]
        for name in ("school_name", "state", "suburb", "postcode"):
            select_parts.append(
                name if name in columns else f"'' AS {name}"
            )
        where = (
            "WHERE COALESCE(deleted_at,'')=''"
            if "deleted_at" in columns else ""
        )
        rows = db.all(
            f"SELECT {','.join(select_parts)} FROM schools {where} "
            "ORDER BY school_name,id"
        )
        choices = []
        for row in rows:
            name = row["school_name"] or f"School #{row['id']}"
            label = " · ".join(
                str(value) for value in (
                    name, row["suburb"], row["state"]
                ) if value
            )
            choices.append({
                "id": int(row["id"]),
                "label": label,
                "name": name,
                "state": row["state"] or "",
                "suburb": row["suburb"] or "",
                "postcode": row["postcode"] or "",
            })
        return choices

    def transfer_case_school_choices(self):
        rows = db.all(
            """SELECT s.id,s.school_name,s.state,s.suburb,s.postcode,
                      s.sector_key,s.region,s.school_type,c.city_name
               FROM schools s
               LEFT JOIN school_cities c ON c.id=s.city_id
               WHERE COALESCE(s.deleted_at,'')=''
               ORDER BY s.state,s.school_name"""
        )
        choices = []
        for row in rows:
            label = " · ".join(
                str(value) for value in (
                    row["school_name"], row["suburb"], row["state"]
                ) if value
            )
            choices.append({
                "id": int(row["id"]),
                "label": label,
                "name": row["school_name"] or "",
                "city_key": str(row["city_name"] or "").strip().lower(),
                "city_name": row["city_name"] or "",
                "region": row["region"] or row["city_name"] or "",
                "school_type": row["school_type"] or "",
                "sector_key": row["sector_key"] or "",
                "state": row["state"] or "",
                "suburb": row["suburb"] or "",
                "postcode": row["postcode"] or "",
            })
        return choices

    def transfer_case_city_choices(self):
        return [
            {
                "key": str(row["city_name"] or "").strip().lower(),
                "name": row["city_name"],
            }
            for row in db.all(
                """SELECT city_name FROM school_cities
                   WHERE is_active=1 ORDER BY sort_order,city_name"""
            )
        ]

    def transfer_case_selected_school(self, school_id, submitted_name):
        selected = next(
            (
                item for item in self.transfer_case_school_choices()
                if int(item["id"]) == int(school_id)
            ),
            None,
        )
        if selected is None:
            raise ValueError("school is not in the school library")
        if str(submitted_name or "").strip() != str(selected["name"]).strip():
            raise ValueError("school name and identifier do not match")
        return selected

    def transfer_case_validate_city_sector(self, city_key, sector_key):
        normalized_city = str(city_key or "").strip()
        allowed_cities = {item["key"] for item in self.transfer_case_city_choices()}
        if normalized_city and normalized_city not in allowed_cities:
            raise ValueError("invalid city")
        normalized_sector = str(sector_key or "").strip()
        if normalized_sector not in {"", "public", "private", "unknown"}:
            raise ValueError("invalid school sector")
        return normalized_city or None, normalized_sector or None

    @staticmethod
    def transfer_case_optional_id(value):
        normalized = str(value or "").strip()
        if not normalized:
            return None
        if not normalized.isdigit() or int(normalized) < 1:
            raise ValueError("invalid identifier")
        return int(normalized)

    def transfer_case_route_error(self, error):
        if isinstance(error, TransferCaseNotFoundError):
            return self.error_page("转学Case不存在。", HTTPStatus.NOT_FOUND)
        if isinstance(error, TransferCaseSchemaNotReadyError):
            return self.error_page(
                "Transfer Case数据结构尚未启用。",
                HTTPStatus.SERVICE_UNAVAILABLE,
            )
        if isinstance(error, TransferCaseAccessDeniedError):
            return self.error_page(
                "无权限执行该Transfer Case操作。",
                HTTPStatus.FORBIDDEN,
            )
        if isinstance(error, TransferCaseActiveConflictError):
            return self.error_page(
                "该学生已有进行中的Student Case。",
                HTTPStatus.CONFLICT,
            )
        if isinstance(
            error,
            (
                TransferCaseTitleInvalidError,
                TransferCaseFieldNotEditableError,
                ValueError,
            ),
        ):
            return self.error_page(
                "提交的Transfer Case字段无效。",
                HTTPStatus.BAD_REQUEST,
            )
        if isinstance(error, (TransferCaseError, StudentCaseError)):
            return self.error_page(
                "Transfer Case操作未能安全完成。",
                HTTPStatus.BAD_REQUEST,
            )
        raise error

    def transfer_case_for_student(self, service, student_id, case_id):
        transfer_case = service.get_transfer_case(int(case_id))
        if transfer_case.student_id != str(student_id):
            raise TransferCaseNotFoundError()
        return transfer_case

    def transfer_v2_schema_ready(self):
        connection = db.connect()
        transfer_columns = {
            str(row[1]) for row in connection.execute("PRAGMA table_info(transfer_cases)")
        }
        return (
            "v2_version" in transfer_columns
            and connection.execute(
                """SELECT 1 FROM sqlite_master
                    WHERE type='table' AND name='transfer_v2_origin_events'"""
            ).fetchone() is not None
        )

    def transfer_v2_case_context(self, case_id, student_id=None):
        if not self.transfer_v2_schema_ready():
            return None
        parameters = [int(case_id)]
        student_filter = ""
        if student_id is not None:
            student_filter = " AND cycle.student_id=?"
            parameters.append(str(student_id))
        return db.connect().execute(
            f"""SELECT cycle.id AS cycle_id,cycle.student_id,cycle.status,
                       transfer.case_id,transfer.v2_version
                  FROM transfer_cases AS transfer
                  JOIN application_cycles AS cycle
                    ON cycle.source_student_case_id=transfer.case_id
                 WHERE transfer.case_id=? AND transfer.v2_version=2
                   AND cycle.cycle_type='transfer'{student_filter}
                 ORDER BY cycle.id DESC LIMIT 1""",
            tuple(parameters),
        ).fetchone()

    def transfer_v2_action_context(self, cycle_id, student_id):
        connection = db.connect()
        offers_by_branch = {}
        for row in connection.execute(
            """SELECT offer.id,offer.transfer_branch_id,offer.school_name_snapshot,
                      offer.received_at,authoritative.id AS authoritative_offer_id,
                      authoritative.document_type,authoritative.offer_status,
                      authoritative.offer_date,authoritative.offer_expiry_date,
                      authoritative.offer_file_path,
                      COALESCE((SELECT state.state
                          FROM offer_received_event_state_events AS state
                         WHERE state.offer_received_event_id=offer.id
                         ORDER BY state.occurred_at DESC,state.id DESC LIMIT 1
                      ),'UNCONFIRMED') AS state,
                      CASE WHEN offer.id=(
                        SELECT latest.id FROM offer_received_events AS latest
                         WHERE latest.application_cycle_id=offer.application_cycle_id
                           AND latest.transfer_branch_id=offer.transfer_branch_id
                         ORDER BY latest.received_at DESC,latest.id DESC LIMIT 1
                      ) THEN 1 ELSE 0 END AS is_latest
                 FROM offer_received_events AS offer
                 JOIN offers AS authoritative ON authoritative.id=offer.legacy_offer_id
                WHERE offer.application_cycle_id=?
                  AND offer.transfer_branch_id IS NOT NULL
                ORDER BY offer.transfer_branch_id,offer.received_at DESC,offer.id DESC""",
            (int(cycle_id),),
        ):
            offers_by_branch.setdefault(int(row["transfer_branch_id"]), []).append(
                dict(row)
            )
        payments_by_branch = {}
        for row in connection.execute(
            """SELECT payment.id,payment.payment_category,payment.amount,payment.currency,
                      payment.paid_date,payment.receipt_file_path,
                      confirmation.confirmed_by,confirmation.confirmed_at,
                      link.transfer_application_id AS branch_id
                 FROM case_record_links AS link
                 JOIN payments AS payment ON payment.id=link.record_id
                 JOIN transfer_school_applications AS branch
                   ON branch.id=link.transfer_application_id
                 LEFT JOIN transfer_payment_confirmations AS confirmation
                   ON confirmation.payment_link_id=link.id
                WHERE branch.application_cycle_id=? AND link.record_type='payment'
                  AND link.validity_status IN ('current','carried_forward')
                ORDER BY branch_id,COALESCE(NULLIF(payment.paid_date,''),payment.created_at) DESC,
                         payment.id DESC""",
            (int(cycle_id),),
        ):
            payments_by_branch.setdefault(int(row["branch_id"]), []).append(dict(row))
        coe_records = tuple(
            dict(row) for row in connection.execute(
                """SELECT coe.id,coe.file_path,link.transfer_application_id AS branch_id
                     FROM case_record_links AS link
                     JOIN coe_oshc AS coe ON coe.id=link.record_id
                     JOIN transfer_school_applications AS branch
                       ON branch.id=link.transfer_application_id
                    WHERE coe.student_id=? AND coe.document_kind IN ('COE','COE_CAAW')
                      AND branch.application_cycle_id=? AND link.record_type='coe'
                      AND link.validity_status IN ('current','carried_forward')
                    ORDER BY coe.id DESC""",
                (str(student_id), int(cycle_id)),
            )
        )
        history_events = []
        history_queries = (
            ("transfer_v2_origin_events", "new_source_label"),
            ("transfer_target_state_events", "new_state"),
            ("offer_received_event_state_events", "state"),
            ("transfer_v2_lifecycle_events", "note"),
            ("transfer_coe_events", "event_type"),
        )
        for table, detail_column in history_queries:
            table_columns = {
                str(row[1]) for row in connection.execute(f"PRAGMA table_info('{table}')")
            }
            cycle_column = (
                "application_cycle_id" if "application_cycle_id" in table_columns else None
            )
            if cycle_column is None:
                continue
            event_column = "event_type" if "event_type" in table_columns else (
                "action" if "action" in table_columns else "'source_changed'"
            )
            occurred_column = "occurred_at" if "occurred_at" in table_columns else "created_at"
            actor_column = "actor_user_id" if "actor_user_id" in table_columns else (
                "confirmed_by" if "confirmed_by" in table_columns else "NULL"
            )
            if detail_column not in table_columns:
                detail_column = "NULL"
            history_events.extend(
                dict(row) for row in connection.execute(
                    f"""SELECT {event_column} AS event_type,
                               {occurred_column} AS occurred_at,
                               {actor_column} AS actor_user_id,
                               {detail_column} AS detail
                          FROM {table} WHERE {cycle_column}=?""",
                    (int(cycle_id),),
                )
            )
        history_events.sort(
            key=lambda item: str(item.get("occurred_at") or ""), reverse=True
        )
        return offers_by_branch, payments_by_branch, coe_records, tuple(history_events)

    def block_legacy_mutation_for_transfer_v2(self, method):
        if method != "POST" or "/transfer-v2/" in self.parsed.path:
            return False
        match = re.match(
            r"^/students/\d+/transfer-cases/(\d+)(?:/|$)", self.parsed.path
        )
        if match is None or self.transfer_v2_case_context(int(match.group(1))) is None:
            return False
        self.error_page(
            "Transfer V2 禁止通过 Legacy workflow/status 接口修改；请使用 V2 精确操作。",
            HTTPStatus.CONFLICT,
        )
        return True

    def student_transfer_v2_create_post(self, student_id):
        choices = {item["id"]: item for item in self.transfer_case_school_choices()}
        raw_target_ids = list(split_multi(self.form, "target_school_id"))
        target_name_field = (
            "target_school_name"
            if "target_school_name" in self.form
            else "target_school_manual"
        )
        raw_target_names = list(split_multi(self.form, target_name_field))
        row_count = max(len(raw_target_ids), len(raw_target_names))
        raw_target_ids.extend([""] * (row_count - len(raw_target_ids)))
        raw_target_names.extend([""] * (row_count - len(raw_target_names)))
        target_rows = []
        seen_targets = set()
        for raw_id, raw_name in zip(raw_target_ids, raw_target_names):
            target_id = self.transfer_case_optional_id(raw_id)
            submitted_name = str(raw_name or "").strip()
            if target_id is None and not submitted_name:
                continue
            if target_id is not None and not submitted_name and target_name_field == "target_school_manual":
                legacy_choice = choices.get(target_id)
                submitted_name = str((legacy_choice or {}).get("name") or "")
            selected = (
                self.transfer_case_selected_school(target_id, submitted_name)
                if target_id is not None else None
            )
            identity = ("id", target_id) if target_id is not None else (
                "manual", submitted_name.casefold()
            )
            if identity in seen_targets:
                raise ValueError("target schools must be unique")
            seen_targets.add(identity)
            target_rows.append((target_id, submitted_name, selected))
        if not target_rows:
            raise ValueError("at least one target school is required")
        current_school_id = self.transfer_case_optional_id(
            form_text_value(self.form, "current_school_id")
        )
        current_name_field = (
            "current_school_name"
            if "current_school_name" in self.form
            else "current_school_manual"
        )
        current_name = form_text_value(self.form, current_name_field).strip()
        if current_school_id is not None and not current_name and current_name_field == "current_school_manual":
            legacy_choice = choices.get(current_school_id)
            current_name = str((legacy_choice or {}).get("name") or "")
        if current_school_id is None and not current_name:
            raise ValueError("current school is required")
        current_school = (
            self.transfer_case_selected_school(current_school_id, current_name)
            if current_school_id is not None else {
                "name": current_name,
                "state": form_text_value(self.form, "current_school_state") or None,
                "region": form_text_value(self.form, "current_school_region") or None,
                "school_type": form_text_value(self.form, "current_school_type") or None,
            }
        )
        targets = []
        for target_id, submitted_name, selected in target_rows:
            if target_id is None:
                targets.append(TransferV2TargetInput(None, submitted_name))
                continue
            choice = selected
            targets.append(TransferV2TargetInput(
                school_id=target_id,
                school_name=str(choice["name"]),
                state=str(choice["state"] or "") or None,
                region=str(choice.get("region") or choice.get("city_name") or "") or None,
                school_type=str(choice.get("school_type") or "") or (
                    "Government" if choice.get("sector_key") == "public" else "Independent"
                ),
            ))
        service = TransferV2Service(db.path, clock=now_iso)
        created = service.create_cycle(
            TransferV2CreateInput(
                student_id=str(student_id),
                source_contract_id=self.transfer_case_optional_id(
                    form_text_value(self.form, "source_contract_id")
                ),
                source_label=form_text_value(self.form, "source_label"),
                current_school_id=current_school_id,
                current_school_name=str(current_school["name"]),
                current_school_state=str(current_school.get("state") or "") or None,
                current_school_region=str(
                    current_school.get("region") or current_school.get("city_name") or ""
                ) or None,
                current_school_type=str(current_school.get("school_type") or "") or (
                    "Government"
                    if current_school.get("sector_key") == "public"
                    else "Independent" if current_school_id is not None else None
                ),
                current_year_level=form_text_value(self.form, "current_year_level"),
                application_year_level=form_text_value(
                    self.form, "application_year_level"
                ),
                transfer_year=int(form_text_value(self.form, "transfer_year")),
                transfer_term=form_text_value(self.form, "transfer_term"),
                targets=tuple(targets),
            ),
            actor_user_id=int(self.user["id"]),
            idempotency_key=form_text_value(self.form, "idempotency_key"),
        )
        reconcile_transfer_v2_reminders(
            db, now=now_iso(), cycle_ids=(created.cycle_id,)
        )
        return self.flash_redirect(
            f"/students/{quote(str(student_id))}/transfer-cases/{created.case_id}#transfer-v2-overview",
            "Transfer V2 已建立。",
        )

    def student_transfer_case_create(self, method, student_id):
        if method not in {"GET", "POST"}:
            return self.error_page("只允许GET或POST。", HTTPStatus.METHOD_NOT_ALLOWED)
        if not self.require("students.view"):
            return
        flags = self.transfer_case_flags()
        student = self.student_capability_subject(student_id)
        if not student:
            return self.error_page("学生不存在", HTTPStatus.NOT_FOUND)
        if self.transfer_v2_schema_ready():
            if method == "GET":
                if not student_capabilities.can_view_transfer_cases(
                    self.user, student, flags=flags
                ):
                    return self.error_page(
                        "无权限查看Transfer Case。", HTTPStatus.FORBIDDEN
                    )
                connection = db.connect()
                current = connection.execute(
                    """SELECT id,school_id,school_name_snapshot
                        FROM student_school_enrolments
                        WHERE student_id=? AND enrolment_role='current'
                          AND status='active' ORDER BY id DESC LIMIT 1""",
                    (str(student_id),),
                ).fetchone()
                student_year = connection.execute(
                    "SELECT current_year_level FROM students WHERE student_id=?",
                    (str(student_id),),
                ).fetchone()
                eligibility = TransferV2Service(
                    db.path, clock=now_iso
                ).creation_eligibility(str(student_id))
                source_options, source_authority, source_label, source_error = (
                    {}, None, None, ""
                )
                source_notice, source_notice_kind = self.message()
                if source_notice_kind == "error":
                    source_error = source_notice
                    source_notice = ""
                try:
                    source_options = transfer_source_authority.list_source_options(
                        connection, str(student_id)
                    )
                    if eligibility.contract_id:
                        source_authority = (
                            transfer_source_authority.resolve_for_creation(
                                connection, str(student_id), eligibility.contract_id
                            )
                        )
                        source_label = source_authority["source_classification"]
                except transfer_source_authority.SourceAuthorityError as error:
                    source_error = (
                        "来源待确认，请在正常合同表单确认本次业务资料。"
                        + str(error)
                    )
                body = transfer_v2_views.render_transfer_v2_creation_form(
                    student_id=str(student_id),
                    csrf=self.csrf,
                    eligibility=eligibility,
                    current_school=(
                        {"id":current["school_id"],"name":current["school_name_snapshot"]}
                        if current is not None else None
                    ),
                    current_year_level=(
                        str(student_year[0] or "") if student_year is not None else ""
                    ),
                    school_choices=self.transfer_case_school_choices(),
                    source_label=source_label,
                    source_options=source_options,
                    source_authority=source_authority,
                    source_error=source_error,
                    source_notice=source_notice,
                    can_manage_contract=can_manage_transfer_contract(self.user),
                )
                return self.send_html(
                    page("Transfer V2", body, self.user, self.csrf, "students", nas.status()),
                    headers=[("Cache-Control", "no-store")],
                )
            if not student_capabilities.can_create_transfer_case(
                self.user, student, flags=flags
            ):
                return self.error_page("无权限创建Transfer Case。", HTTPStatus.FORBIDDEN)
            allowed_v2_fields = {
                "csrf","idempotency_key","source_contract_id",
                "source_action","source_parent_form_token","source_existing_evidence",
                "current_school_id","current_year_level","application_year_level",
                "current_school_name","current_school_state","current_school_region",
                "current_school_type","current_school_manual","transfer_year","transfer_term",
                "target_school_id","target_school_name","target_school_state",
                "target_school_region","target_school_type","target_school_manual",
            }
            if set(self.form) - allowed_v2_fields:
                return self.error_page("Transfer V2 字段无效。", HTTPStatus.BAD_REQUEST)
            try:
                if form_text_value(self.form, "source_action") or {
                    "source_parent_form_token", "source_existing_evidence"
                } & set(self.form):
                    raise ValueError("请在正常合同表单确认本次转学资料。")
                return self.student_transfer_v2_create_post(student_id)
            except (TransferV2Error, ValueError) as error:
                return self.error_page(str(error), HTTPStatus.BAD_REQUEST)
        if method == "GET":
            if not student_capabilities.can_view_transfer_cases(
                self.user, student, flags=flags
            ):
                return self.error_page(
                    "无权限查看Transfer Case。", HTTPStatus.FORBIDDEN
                )
            body = transfer_case_views.render_transfer_case_tab(
                db.path,
                str(student_id),
                self.user,
                flags,
                csrf=self.csrf,
                staff_users=self.transfer_case_staff_users(),
                school_choices=self.transfer_case_school_choices(),
                city_choices=self.transfer_case_city_choices(),
                entry_contract_id=self.transfer_case_optional_id(
                    str((self.query.get("source_contract_id") or [""])[0])
                ),
            )
            return self.send_html(
                page(
                    "Transfer Case", body, self.user, self.csrf,
                    "students", nas.status()
                ),
                headers=[("Cache-Control", "no-store")],
            )
        if not student_capabilities.can_create_transfer_case(
            self.user, student, flags=flags
        ):
            return self.error_page(
                "无权限创建Transfer Case。",
                HTTPStatus.FORBIDDEN,
            )
        allowed_form_fields = {
            "csrf",
            "idempotency_key",
            "owner_user_id",
            "title",
            "current_school_name_snapshot",
            "current_school_id",
            "current_city_key",
            "current_school_sector",
            "initial_note",
            "source_contract_id",
        }
        if set(self.form) - allowed_form_fields:
            return self.transfer_case_route_error(
                TransferCaseFieldNotEditableError()
            )
        try:
            owner_user_id = self.transfer_case_optional_id(
                form_text_value(self.form, "owner_user_id")
            )
            if owner_user_id is None:
                raise ValueError("owner is required")
            eligible_owner_ids = {
                int(item["id"]) for item in self.transfer_case_staff_users()
            }
            if owner_user_id not in eligible_owner_ids:
                return self.error_page(
                    "所选负责人无Transfer分配权限。", HTTPStatus.FORBIDDEN
                )
            current_school_id = self.transfer_case_optional_id(
                form_text_value(self.form, "current_school_id")
            )
            if current_school_id is None:
                raise ValueError("school selection is required")
            selected_school = self.transfer_case_selected_school(
                current_school_id,
                form_text_value(self.form, "current_school_name_snapshot"),
            )
            city_key, sector_key = self.transfer_case_validate_city_sector(
                form_text_value(self.form, "current_city_key"),
                form_text_value(self.form, "current_school_sector"),
            )
            raw_title = form_text_value(self.form, "title")
            raw_initial_note = form_text_value(self.form, "initial_note")
            service = TransferCaseService(db.path)
            created = service.create_internal_transfer(
                student_id=str(student_id),
                actor_user_id=int(self.user["id"]),
                actor_permissions=get_permissions(self.user),
                flags=flags,
                owner_user_id=owner_user_id,
                title=(raw_title if str(raw_title).strip() else None),
                current_school_name_snapshot=selected_school["name"],
                current_school_id=current_school_id,
                current_city_key=city_key,
                current_school_sector=sector_key,
                initial_note=(
                    raw_initial_note
                    if str(raw_initial_note).strip()
                    else None
                ),
                source_contract_id=self.transfer_case_optional_id(
                    form_text_value(self.form, "source_contract_id")
                ),
                idempotency_key=form_text_value(
                    self.form, "idempotency_key"
                ),
            )
        except (TransferCaseError, StudentCaseError, ValueError) as error:
            return self.transfer_case_route_error(error)
        try:
            record_picker_and_uploader.auto_match_student_records(
                db.path,
                case_id=created.case_id,
                student_id=str(student_id),
                actor_user_id=int(self.user["id"]),
            )
        except (sqlite3.Error, ValueError) as error:
            db.audit(
                self.user,
                "transfer_record_candidate_discovery_failed",
                "student_case",
                created.case_id,
                student_id=str(student_id),
                status="failed",
                error_message=type(error).__name__,
            )
            return self.flash_redirect(
                f"/students/{quote(str(student_id))}#workflow-progress",
                "转学记录已创建，但系统未能生成已有记录建议；请在 Student Profile 人工核对已有资料。",
                "error",
            )
        return self.flash_redirect(
            f"/students/{quote(str(student_id))}#workflow-progress",
            "转学记录及 Active Lifecycle 已建立。",
        )

    def student_transfer_case_activate(self, method, student_id, case_id):
        if method != "POST":
            return self.error_page("只允许POST。", HTTPStatus.METHOD_NOT_ALLOWED)
        if not self.require("students.view"):
            return
        flags = self.transfer_case_flags()
        student = self.student_capability_subject(student_id)
        if not student:
            return self.error_page("学生不存在", HTTPStatus.NOT_FOUND)
        if (
            not student_capabilities.can_edit_transfer_case(
                self.user, student, flags=flags
            )
            or set(self.form) - {
                "csrf", "idempotency_key", "takeover_confirmed"
            }
        ):
            return self.error_page(
                "无权限或字段无效。", HTTPStatus.FORBIDDEN
            )
        try:
            service = TransferCaseService(db.path)
            transfer_case = self.transfer_case_for_student(
                service, student_id, case_id
            )
            key = form_text_value(self.form, "idempotency_key")
            service.activate_transfer_case(
                transfer_case.case_id,
                actor_user_id=int(self.user["id"]),
                idempotency_key=key,
                takeover_confirmed=(
                    form_text_value(self.form, "takeover_confirmed") == "1"
                ),
            )
            db.audit(
                self.user,
                "transfer_lifecycle_activated",
                "student_case",
                transfer_case.case_id,
                new_value=json.dumps(
                    {"idempotency_key": key}, sort_keys=True
                ),
                ip=self.client_address[0],
                device=self.headers.get("User-Agent"),
                student_id=str(student_id),
            )
        except (TransferCaseError, StudentCaseError, ValueError) as error:
            return self.transfer_case_route_error(error)
        return self.flash_redirect(
            f"/students/{quote(str(student_id))}/transfer-cases/"
            f"{transfer_case.case_id}#transfer-case-overview",
            "转学业务已激活。",
        )

    def student_transfer_case_contract(self, method, student_id, case_id):
        if method != "POST":
            return self.error_page("只允许POST。", HTTPStatus.METHOD_NOT_ALLOWED)
        if not self.require("students.view"):
            return
        flags = self.transfer_case_flags()
        student = self.student_capability_subject(student_id)
        if (
            not student
            or not student_capabilities.can_edit_transfer_case(
                self.user, student, flags=flags
            )
            or set(self.form) - {"csrf", "source_contract_id"}
        ):
            return self.error_page("无权限或字段无效。", HTTPStatus.FORBIDDEN)
        try:
            service = TransferCaseService(db.path)
            self.transfer_case_for_student(service, student_id, case_id)
            contract_id = self.transfer_case_optional_id(
                form_text_value(self.form, "source_contract_id")
            )
            if contract_id is None:
                raise ValueError("contract required")
            service.ensure_contract_ownership(
                int(case_id), source_contract_id=contract_id,
                actor_user_id=int(self.user["id"]),
            )
        except (TransferCaseError, StudentCaseError, ValueError) as error:
            return self.transfer_case_route_error(error)
        return self.flash_redirect(
            f"/students/{quote(str(student_id))}/transfer-cases/{int(case_id)}#transfer-contract-ownership",
            "转学合同已关联到本记录。",
        )

    def student_transfer_case_detail(self, method, student_id, case_id):
        if method != "GET":
            return self.error_page("只允许GET。", HTTPStatus.METHOD_NOT_ALLOWED)
        if not self.require("students.view"):
            return
        flags = self.transfer_case_flags()
        if not student_case_permissions.can_view_student_cases(
            self.user, flags
        ):
            return self.error_page(
                "无权限查看Transfer Case。",
                HTTPStatus.FORBIDDEN,
            )
        if self.transfer_v2_schema_ready():
            cycle = db.connect().execute(
                """SELECT cycle.id
                    FROM application_cycles AS cycle
                    JOIN transfer_cases AS transfer
                      ON transfer.case_id=cycle.source_student_case_id
                    WHERE transfer.case_id=? AND cycle.student_id=?
                      AND cycle.cycle_type='transfer'
                    ORDER BY cycle.id DESC LIMIT 1""",
                (int(case_id),str(student_id)),
            ).fetchone()
            if cycle is not None:
                try:
                    overview = TransferV2Service(
                        db.path, clock=now_iso
                    ).load_overview(int(cycle["id"]))
                    legacy_history = (
                        load_legacy_transfer_history(
                            db.connect(), int(cycle["id"])
                        )
                        if overview.is_legacy else None
                    )
                    projection = (
                        None
                        if overview.is_legacy
                        else load_transfer_v2_projection(
                            db.connect(), int(cycle["id"])
                        )
                    )
                    documents_by_branch = {}
                    checklists_by_branch = {}
                    if projection is not None:
                        documents = TransferV2DocumentService(
                            db.path, clock=now_iso
                        )
                        documents_by_branch = {
                            branch.branch_id: documents.list_document_sections(
                                overview.cycle_id, branch.branch_id
                            )
                            for branch in overview.branches
                        }
                        checklists_by_branch = {
                            branch.branch_id: documents.load_checklist(
                                overview.cycle_id,branch.branch_id
                            )
                            for branch in overview.branches
                        }
                    available_documents = tuple(
                        dict(row) for row in db.all(
                            """SELECT id,document_type,document_date,uploaded_at,file_path
                                FROM student_documents WHERE student_id=?
                                ORDER BY COALESCE(document_date,uploaded_at) DESC,id DESC""",
                            (str(student_id),),
                        )
                    ) if projection is not None else ()
                    offers_by_branch, payments_by_branch, coe_records, history_events = self.transfer_v2_action_context(
                        int(cycle["id"]), student_id
                    ) if projection is not None else ({}, (), (), ())
                    student = self.student_capability_subject(student_id)
                    body = transfer_v2_views.render_transfer_v2_detail(
                        overview,projection,csrf=self.csrf,
                        can_edit=bool(student) and student_capabilities.can_edit_transfer_case(
                            self.user,student,flags=flags
                        ),
                        documents_by_branch=documents_by_branch,
                        checklists_by_branch=checklists_by_branch,
                        available_documents=available_documents,
                        offers_by_branch=offers_by_branch,
                        payments_by_branch=payments_by_branch,
                        coe_records=coe_records,
                        history_events=history_events,
                        school_choices=self.transfer_case_school_choices(),
                        legacy_history=legacy_history,
                    )
                    message,kind = self.message()
                except (TransferV2Error,TransferV2DocumentError,TransferV2ProjectionError) as error:
                    return self.error_page(str(error),HTTPStatus.BAD_REQUEST)
                return self.send_html(
                    page(
                        f"转学记录 #{overview.cycle_id}",body,self.user,self.csrf,
                        "students",nas.status(),message,kind,
                    ),
                    headers=[("Cache-Control","no-store")],
                )
        try:
            summary = load_lifecycle_case_summary_from_path(
                db.path, str(student_id), int(case_id), expected_type="transfer"
            )
            body = render_lifecycle_case_summary(summary)
            message, kind = self.message()
        except LookupError:
            return self.error_page("Transfer Case不存在。", HTTPStatus.NOT_FOUND)
        except (TransferCaseError, StudentCaseError, ValueError) as error:
            return self.transfer_case_route_error(error)
        self.send_html(
            page(
                f"转学记录 #{summary.case_sequence}",
                body,
                self.user,
                self.csrf,
                "students",
                nas.status(),
                message,
                kind,
            ),
            headers=[("Cache-Control", "no-store")],
        )

    def student_transfer_v2_action(self, method, student_id, case_id):
        if method != "POST":
            return self.error_page("只允许POST。",HTTPStatus.METHOD_NOT_ALLOWED)
        if not self.require("students.view"):
            return
        flags = self.transfer_case_flags()
        student = self.student_capability_subject(student_id)
        if not student or not student_capabilities.can_edit_transfer_case(
            self.user,student,flags=flags
        ):
            return self.error_page("无权限执行 Transfer V2 操作。",HTTPStatus.FORBIDDEN)
        context = self.transfer_v2_case_context(case_id,student_id)
        if context is None:
            return self.error_page("Transfer V2 不存在。",HTTPStatus.NOT_FOUND)
        cycle_id = int(context["cycle_id"])
        submitted_cycle_id = self.transfer_case_optional_id(
            form_text_value(self.form,"cycle_id")
        )
        if submitted_cycle_id != cycle_id:
            return self.error_page("Transfer V2 Cycle 不匹配。",HTTPStatus.CONFLICT)
        action = form_text_value(self.form,"action")
        action_fields = {
            "change_origin":{"new_source_label","note"},
            "add_target_school":{"target_school_id","target_school_name","target_school_state","target_school_region","target_school_type"},
            "remove_target_school":{"branch_id"},
            "request_school_library":{"branch_id","proposed_name","proposed_state","proposed_region","proposed_school_type"},
            "branch_transition":{"branch_id","new_state","allow_missing","note"},
            "add_requirement":{"branch_id","document_type","label","requires_current_cycle"},
            "bind_document":{"branch_id","document_id","source_cycle_id","document_type","document_date"},
            "adopt_document":{"requirement_id","binding_id"},
            "invalidate_binding":{"binding_id","reason"},
            "confirm_offer_valid":{"branch_id","offer_event_id"},
            "invalidate_offer":{"branch_id","offer_event_id","reason"},
            "accept_offer":{"branch_id","offer_event_id","confirm_non_latest"},
            "switch_acceptance":{"acceptance_id","new_branch_id","new_offer_event_id","old_branch_outcome","payment_action","reason"},
            "start_waiting_coe":{"branch_id","acceptance_id"},
            "confirm_coe":{"branch_id","acceptance_id","coe_oshc_id","document_id","issued_date"},
            "confirm_application_complete":{"branch_id","acceptance_id"},
            "complete_transfer":{"acceptance_id","update_current_school","update_current_year_level","close_unfinished_branches"},
        }
        common_fields = {
            "csrf","action","cycle_id","idempotency_key","branch_id","acceptance_id"
        }
        if action not in action_fields or set(self.form) - common_fields - action_fields[action]:
            return self.error_page("Transfer V2 操作字段无效。",HTTPStatus.BAD_REQUEST)
        key = form_text_value(self.form,"idempotency_key")
        actor_id = int(self.user["id"])
        branch_id = self.transfer_case_optional_id(form_text_value(self.form,"branch_id"))
        acceptance_id = self.transfer_case_optional_id(
            form_text_value(self.form,"acceptance_id")
        )
        admissions = TransferV2AdmissionsService(db.path,clock=now_iso)
        completion = TransferV2CompletionService(db.path,clock=now_iso)
        documents = TransferV2DocumentService(db.path,clock=now_iso)
        try:
            if action == "change_origin":
                TransferV2Service(db.path,clock=now_iso).change_origin(
                    cycle_id,new_source_label=form_text_value(
                        self.form,"new_source_label"
                    ),actor_user_id=actor_id,
                    note=form_text_value(self.form,"note") or None,
                    idempotency_key=key,
                )
            elif action == "add_target_school":
                target_school_id = self.transfer_case_optional_id(
                    form_text_value(self.form,"target_school_id")
                )
                target_school_name = form_text_value(
                    self.form,"target_school_name"
                )
                if target_school_id is not None:
                    selected = self.transfer_case_selected_school(
                        target_school_id,target_school_name
                    )
                    target = TransferV2TargetInput(
                        school_id=int(selected["id"]),
                        school_name=str(selected["name"]),
                        state=str(selected.get("state") or "") or None,
                        region=str(selected.get("region") or "") or None,
                        school_type=str(selected.get("school_type") or "") or None,
                    )
                else:
                    target = TransferV2TargetInput(
                        school_id=None,school_name=target_school_name,
                        state=form_text_value(self.form,"target_school_state") or None,
                        region=form_text_value(self.form,"target_school_region") or None,
                        school_type=form_text_value(self.form,"target_school_type") or None,
                    )
                TransferV2Service(db.path,clock=now_iso).add_target_branch(
                    cycle_id,target=target,actor_user_id=actor_id,
                    idempotency_key=key,
                )
            elif action == "request_school_library":
                TransferV2Service(db.path,clock=now_iso).request_school_library(
                    cycle_id,branch_id=branch_id,
                    proposed_name=form_text_value(self.form,"proposed_name"),
                    proposed_state=form_text_value(self.form,"proposed_state") or None,
                    proposed_region=form_text_value(self.form,"proposed_region") or None,
                    proposed_school_type=form_text_value(
                        self.form,"proposed_school_type"
                    ) or None,actor_user_id=actor_id,idempotency_key=key,
                )
            elif action == "remove_target_school":
                if branch_id is None:
                    raise ValueError("exact Target School is required")
                TransferV2Service(db.path,clock=now_iso).remove_target_branch(
                    cycle_id,
                    branch_id=branch_id,
                    actor_user_id=actor_id,
                    idempotency_key=key,
                )
            elif action == "add_requirement":
                current_only = form_text_value(self.form,"requires_current_cycle")
                if branch_id is None or current_only not in {"", "1"}:
                    raise ValueError("exact Branch and valid requirement scope are required")
                documents.add_requirement(
                    cycle_id=cycle_id,branch_id=branch_id,
                    document_type=form_text_value(self.form,"document_type"),
                    label=form_text_value(self.form,"label"),
                    requires_current_cycle=current_only=="1",
                    actor_user_id=actor_id,idempotency_key=key,
                )
            elif action == "bind_document":
                if branch_id is None:
                    raise ValueError("exact Branch is required")
                document_id = self.transfer_case_optional_id(
                    form_text_value(self.form,"document_id")
                )
                if document_id is None:
                    raise ValueError("exact Student Document is required")
                documents.bind_document(
                    cycle_id=cycle_id,branch_id=branch_id,document_id=document_id,
                    source_cycle_id=self.transfer_case_optional_id(
                        form_text_value(self.form,"source_cycle_id")
                    ),document_type=form_text_value(self.form,"document_type"),
                    document_date=form_text_value(self.form,"document_date") or None,
                    actor_user_id=actor_id,idempotency_key=key,
                )
            elif action == "adopt_document":
                requirement_id = self.transfer_case_optional_id(
                    form_text_value(self.form,"requirement_id")
                )
                binding_id = self.transfer_case_optional_id(
                    form_text_value(self.form,"binding_id")
                )
                if requirement_id is None or binding_id is None or db.one(
                    """SELECT 1 FROM transfer_document_requirements AS requirement
                        JOIN transfer_document_bindings AS binding
                          ON binding.current_cycle_id=requirement.application_cycle_id
                         AND binding.branch_id=requirement.branch_id
                         AND binding.document_type=requirement.document_type
                        WHERE requirement.id=? AND binding.id=?
                          AND requirement.application_cycle_id=?""",
                    (requirement_id,binding_id,cycle_id),
                ) is None:
                    raise ValueError("document adoption does not belong to this Cycle")
                documents.adopt_document(
                    requirement_id=requirement_id,binding_id=binding_id,
                    actor_user_id=actor_id,idempotency_key=key,
                )
            elif action == "invalidate_binding":
                binding_id = self.transfer_case_optional_id(
                    form_text_value(self.form,"binding_id")
                )
                if binding_id is None or db.one(
                    """SELECT 1 FROM transfer_document_bindings
                        WHERE id=? AND current_cycle_id=?""",
                    (binding_id,cycle_id),
                ) is None:
                    raise ValueError("document binding does not belong to this Cycle")
                documents.invalidate_binding(
                    binding_id=binding_id,actor_user_id=actor_id,
                    reason=form_text_value(self.form,"reason") or None,
                    idempotency_key=key,
                )
            elif action == "branch_transition":
                if branch_id is None:
                    raise ValueError("branch required")
                documents.transition_branch(
                    cycle_id=cycle_id,branch_id=branch_id,
                    new_state=form_text_value(self.form,"new_state"),
                    actor_user_id=actor_id,
                    allow_missing=form_text_value(self.form,"allow_missing")=="1",
                    note=form_text_value(self.form,"note") or None,
                    idempotency_key=key,
                )
            elif action in {"confirm_offer_valid","invalidate_offer","accept_offer"}:
                offer_id = self.transfer_case_optional_id(
                    form_text_value(self.form,"offer_event_id")
                )
                if branch_id is None or offer_id is None:
                    raise ValueError("exact Branch and Offer are required")
                if action == "confirm_offer_valid":
                    admissions.confirm_offer_valid(
                        cycle_id=cycle_id,branch_id=branch_id,offer_event_id=offer_id,
                        actor_user_id=actor_id,idempotency_key=key,
                    )
                elif action == "invalidate_offer":
                    admissions.invalidate_offer(
                        cycle_id=cycle_id,branch_id=branch_id,offer_event_id=offer_id,
                        actor_user_id=actor_id,reason=form_text_value(self.form,"reason"),
                        idempotency_key=key,
                    )
                else:
                    admissions.accept_offer(
                        cycle_id=cycle_id,branch_id=branch_id,offer_event_id=offer_id,
                        actor_user_id=actor_id,
                        confirm_non_latest=form_text_value(self.form,"confirm_non_latest")=="1",
                        idempotency_key=key,
                    )
            elif action == "switch_acceptance":
                new_branch_id = self.transfer_case_optional_id(
                    form_text_value(self.form,"new_branch_id")
                )
                new_offer_id = self.transfer_case_optional_id(
                    form_text_value(self.form,"new_offer_event_id")
                )
                if acceptance_id is None or new_branch_id is None or new_offer_id is None:
                    raise ValueError("exact acceptance, Branch and Offer are required")
                admissions.switch_acceptance(
                    cycle_id=cycle_id,current_acceptance_id=acceptance_id,
                    new_branch_id=new_branch_id,new_offer_event_id=new_offer_id,
                    old_branch_outcome=form_text_value(self.form,"old_branch_outcome"),
                    payment_action=form_text_value(self.form,"payment_action"),
                    actor_user_id=actor_id,reason=form_text_value(self.form,"reason"),
                    idempotency_key=key,
                )
            elif action == "start_waiting_coe":
                if branch_id is None or acceptance_id is None:
                    raise ValueError("exact Branch and acceptance are required")
                admissions.start_waiting_coe(
                    cycle_id=cycle_id,branch_id=branch_id,acceptance_id=acceptance_id,
                    actor_user_id=actor_id,idempotency_key=key,
                )
            elif action == "confirm_coe":
                coe_id = self.transfer_case_optional_id(form_text_value(self.form,"coe_oshc_id"))
                if branch_id is None or acceptance_id is None or coe_id is None:
                    raise ValueError("exact Branch, acceptance and COE are required")
                admissions.confirm_coe(
                    cycle_id=cycle_id,branch_id=branch_id,acceptance_id=acceptance_id,
                    coe_oshc_id=coe_id,
                    document_id=self.transfer_case_optional_id(
                        form_text_value(self.form,"document_id")
                    ),
                    issued_date=form_text_value(self.form,"issued_date"),
                    actor_user_id=actor_id,idempotency_key=key,
                )
            elif action == "confirm_application_complete":
                if branch_id is None or acceptance_id is None:
                    raise ValueError("exact Branch and acceptance are required")
                completion.confirm_application_complete(
                    cycle_id=cycle_id,branch_id=branch_id,acceptance_id=acceptance_id,
                    actor_user_id=actor_id,idempotency_key=key,
                )
            elif action == "complete_transfer":
                if acceptance_id is None or not student_capabilities.can_complete_transfer_case(
                    self.user,student,flags=flags
                ):
                    return self.error_page("无权限完成 Transfer V2。",HTTPStatus.FORBIDDEN)
                choices = validate_completion_choices({
                    name: form_text_value(self.form, name, "")
                    for name in (
                        "update_current_school",
                        "update_current_year_level",
                        "close_unfinished_branches",
                    )
                })
                completion.complete_transfer(
                    cycle_id=cycle_id,acceptance_id=acceptance_id,
                    **choices,
                    actor_user_id=actor_id,idempotency_key=key,
                )
            else:
                raise ValueError("unsupported Transfer V2 action")
        except (
            TransferV2AdmissionsError,TransferV2DocumentError,
            TransferV2ProjectionError,TransferV2Error,ValueError,
        ) as error:
            return self.error_page(str(error),HTTPStatus.BAD_REQUEST)
        reconcile_transfer_v2_reminders(
            db,now=now_iso(),cycle_ids=(cycle_id,)
        )
        return self.flash_redirect(
            f"/students/{quote(str(student_id))}/transfer-cases/{int(case_id)}#transfer-v2-overview",
            "Transfer V2 已更新。",
        )

    def student_transfer_case_edit(self, method, student_id, case_id):
        if method != "POST":
            return self.error_page("只允许POST。", HTTPStatus.METHOD_NOT_ALLOWED)
        if not self.require("students.view"):
            return
        flags = self.transfer_case_flags()
        student = self.student_capability_subject(student_id)
        if not student:
            return self.error_page("学生不存在", HTTPStatus.NOT_FOUND)
        if not student_capabilities.can_edit_transfer_case(
            self.user, student, flags=flags
        ):
            return self.error_page(
                "无权限编辑Transfer Case。",
                HTTPStatus.FORBIDDEN,
            )
        allowed_form_fields = {
            "csrf",
            "title",
            "current_school_name_snapshot",
            "current_school_id",
            "current_city_key",
            "current_school_sector",
        }
        if set(self.form) - allowed_form_fields:
            return self.transfer_case_route_error(
                TransferCaseFieldNotEditableError()
            )
        try:
            service = TransferCaseService(db.path)
            self.transfer_case_for_student(service, student_id, case_id)
            raw_title = form_text_value(self.form, "title")
            current_school_id = self.transfer_case_optional_id(
                form_text_value(self.form, "current_school_id")
            )
            if current_school_id is None:
                raise ValueError("school selection is required")
            selected_school = self.transfer_case_selected_school(
                current_school_id,
                form_text_value(self.form, "current_school_name_snapshot"),
            )
            city_key, sector_key = self.transfer_case_validate_city_sector(
                form_text_value(self.form, "current_city_key"),
                form_text_value(self.form, "current_school_sector"),
            )
            service.update_transfer_case(
                int(case_id),
                changes={
                    "title": (
                        raw_title if str(raw_title).strip() else None
                    ),
                    "current_school_name_snapshot": selected_school["name"],
                    "current_school_id": current_school_id,
                    "current_city_key": city_key,
                    "current_school_sector": sector_key,
                },
                actor_user_id=int(self.user["id"]),
                actor_permissions=get_permissions(self.user),
                flags=flags,
            )
        except (TransferCaseError, StudentCaseError, ValueError) as error:
            return self.transfer_case_route_error(error)
        return self.flash_redirect(
            f"/students/{quote(str(student_id))}/transfer-cases/"
            f"{int(case_id)}#transfer-case-overview",
            "Transfer Case基础信息已保存。",
        )

    def student_transfer_case_workflow(self, method, student_id, case_id):
        if method != "POST":
            return self.error_page("只允许POST。", HTTPStatus.METHOD_NOT_ALLOWED)
        if not self.require("students.view"):
            return
        flags = self.transfer_case_flags()
        if not student_case_permissions.can_edit_student_case(
            self.user, flags, "transfer"
        ):
            return self.error_page(
                "无权限更新Transfer workflow。",
                HTTPStatus.FORBIDDEN,
            )
        try:
            service = TransferCaseService(db.path)
            self.transfer_case_for_student(service, student_id, case_id)
            service.transition_transfer(
                int(case_id),
                form_text_value(self.form, "target_state"),
                actor_user_id=int(self.user["id"]),
                actor_permissions=get_permissions(self.user),
                flags=flags,
            )
        except (TransferCaseError, StudentCaseError, ValueError) as error:
            return self.transfer_case_route_error(error)
        return self.flash_redirect(
            f"/students/{quote(str(student_id))}/transfer-cases/"
            f"{int(case_id)}#transfer-case-workflow",
            "Transfer workflow已更新。",
        )

    def transfer_school_application_redirect(
        self, student_id, case_id, message, kind="success"
    ):
        return self.flash_redirect(
            f"/students/{quote(str(student_id))}/transfer-cases/"
            f"{int(case_id)}#transfer-school-applications",
            message,
            kind,
        )

    def transfer_school_application_route_context(
        self, method, student_id, case_id, allowed_fields
    ):
        if method != "POST":
            self.error_page("只允许POST。", HTTPStatus.METHOD_NOT_ALLOWED)
            return None
        if not self.require("students.view"):
            return None
        flags = self.transfer_case_flags()
        if not student_case_permissions.can_edit_student_case(
            self.user, flags, "transfer"
        ):
            self.error_page(
                "无权限编辑目标学校申请。",
                HTTPStatus.FORBIDDEN,
            )
            return None
        if set(self.form) - set(allowed_fields):
            self.transfer_school_application_redirect(
                student_id,
                case_id,
                "目标学校申请包含不允许修改的字段。",
                "error",
            )
            return None
        try:
            service = TransferCaseService(db.path)
            self.transfer_case_for_student(service, student_id, case_id)
            return service, flags
        except (TransferCaseError, StudentCaseError, ValueError):
            self.transfer_school_application_redirect(
                student_id,
                case_id,
                "无法读取该Transfer Case。",
                "error",
            )
            return None

