        if context is None:
            return
        service, flags = context
        try:
            preference_order = self.transfer_case_optional_id(
                form_text_value(self.form, "preference_order")
            )
            service.add_transfer_school_application(
                int(case_id),
                **self.transfer_school_application_common_values(),
                preference_order=preference_order,
                application_status=(
                    form_text_value(self.form, "application_status")
                    or "preparing"
                ),
                actor_user_id=int(self.user["id"]),
                actor_permissions=get_permissions(self.user),
                flags=flags,
                request_id=(
                    form_text_value(self.form, "request_id") or None
                ),
            )
        except (TransferCaseError, StudentCaseError, ValueError) as error:
            return self.transfer_school_application_write_error(
                student_id, case_id, error
            )
        return self.transfer_school_application_redirect(
            student_id, case_id, "目标学校申请已添加。"
        )

