    @staticmethod
    def transfer_payment_proof_source(value):
        source = str(value or "").strip()
        record_type, separator, record_id = source.partition(":")
        if (
            not separator
            or record_type not in {"payment", "student_document"}
            or not record_id.isdigit()
            or int(record_id) < 1
        ):
            raise ValueError("invalid payment proof source")
        return record_type, int(record_id)

    def student_transfer_payment_proof_attach(
        self,
        method,
        student_id,
        case_id,
        application_id,
        requirement_id,
    ):
        return self._student_transfer_payment_proof_write(
            method,
            student_id,
            case_id,
            application_id,
            requirement_id,
            replace=False,
        )

    def student_transfer_payment_proof_replace(
        self,
        method,
        student_id,
        case_id,
        application_id,
        requirement_id,
    ):
        return self._student_transfer_payment_proof_write(
            method,
            student_id,
            case_id,
            application_id,
            requirement_id,
            replace=True,
        )

    def _student_transfer_payment_proof_write(
        self,
        method,
        student_id,
        case_id,
        application_id,
        requirement_id,
        *,
        replace,
    ):
        context = self.transfer_admission_route_context(
            method,
            student_id,
            case_id,
            {"csrf", "proof_source"},
        )
        if context is None:
            return
        service, flags = context
        try:
            record_type, record_id = self.transfer_payment_proof_source(
                form_text_value(self.form, "proof_source")
            )
            if record_type == "student_document":
                record_id = (
                    record_picker_and_uploader.create_payment_record_from_document(
                        db.path,
                        case_id=int(case_id),
                        document_id=record_id,
                        actor_user_id=int(self.user["id"]),
                    )
                )
            picker_context = record_picker_and_uploader.begin_record_upload(
                int(case_id),
                "payment",
                application_id=int(application_id),
                payment_requirement_id=int(requirement_id),
            )
            record_picker_and_uploader.select_existing_record(
                db.path,
                context=picker_context,
                record_id=record_id,
                actor_user_id=int(self.user["id"]),
                actor_permissions=get_permissions(self.user),
                flags=flags,
                replace=replace,
            )
        except (TransferCaseError, StudentCaseError, ValueError) as error:
            return self.transfer_admission_write_error(
                student_id, case_id, error
            )
        return self.transfer_admission_redirect(
            student_id, case_id, "付款证明已更新。"
        )

