    @staticmethod
    def transfer_arrangement_evidence_source(value):
        source_type, separator, raw_id = str(value or "").partition(":")
        if (
            not separator
            or source_type not in {"document", "record_link"}
            or not raw_id.isdigit()
            or int(raw_id) < 1
        ):
            raise ValueError("invalid evidence source")
        source_id = int(raw_id)
        return (
            source_id if source_type == "record_link" else None,
            source_id if source_type == "document" else None,
        )

    def transfer_arrangement_evidence_target(
        self, service, case_id, arrangement_type
    ):
        if arrangement_type in {"visa", "oshc"}:
            arrangement = getattr(
                service,
                f"get_transfer_{arrangement_type}_arrangement",
            )(int(case_id))
            if arrangement.confirmation is None:
                raise ValueError("confirmation required")
            return {
                "arrangement_confirmation_id":
                    arrangement.confirmation.confirmation_id,
                "guardianship_arrangement_id": None,
                "accommodation_arrangement_id": None,
            }
        arrangement = getattr(
            service,
            f"get_transfer_{arrangement_type}_arrangement",
        )(int(case_id))
        if arrangement.current_arrangement is None:
            raise ValueError("current arrangement required")
        return {
            "arrangement_confirmation_id": None,
            "guardianship_arrangement_id": (
                arrangement.current_arrangement.arrangement_id
                if arrangement_type == "guardianship"
                else None
            ),
            "accommodation_arrangement_id": (
                arrangement.current_arrangement.arrangement_id
                if arrangement_type == "accommodation"
                else None
            ),
        }

    def student_transfer_arrangement_evidence_attach(
        self, method, student_id, case_id, arrangement_type
    ):
        context = self.transfer_arrangement_route_context(
            method,
            student_id,
            case_id,
            {"csrf", "request_id", "evidence_source", "evidence_role"},
        )
        if context is None:
            return
        service, flags = context
        try:
            record_link_id, document_id = (
                self.transfer_arrangement_evidence_source(
                    form_text_value(self.form, "evidence_source")
                )
            )
            service.attach_arrangement_evidence(
                int(case_id),
                arrangement_type,
                **self.transfer_arrangement_evidence_target(
                    service, case_id, arrangement_type
                ),
                case_record_link_id=record_link_id,
                document_id=document_id,
                evidence_role=form_text_value(
                    self.form, "evidence_role"
                ),
                **self.transfer_arrangement_write_arguments(flags),
            )
        except (
            TransferArrangementError,
            TransferCaseError,
            StudentCaseError,
            ValueError,
        ) as error:
            return self.transfer_arrangement_write_error(
                student_id, case_id, error
            )
        return self.transfer_arrangement_redirect(
            student_id, case_id, "Evidence已添加。"
        )

