    def student_transfer_arrangement_evidence_historical(
        self,
        method,
        student_id,
        case_id,
        arrangement_type,
        evidence_id,
    ):
        context = self.transfer_arrangement_route_context(
            method,
            student_id,
            case_id,
            {"csrf", "request_id"},
        )
        if context is None:
            return
        service, flags = context
        try:
            evidence = next(
                (
                    item for item in service.list_arrangement_evidence(
                        int(case_id), arrangement_type
                    )
                    if item.evidence_id == int(evidence_id)
                ),
                None,
            )
            if evidence is None:
                raise ValueError("evidence not found")
            service.mark_arrangement_evidence_historical(
                int(case_id),
                int(evidence_id),
                **self.transfer_arrangement_write_arguments(flags),
            )
        except (
            TransferArrangementError,
            TransferCaseError,
            StudentCaseError,
            ValueError,
        ) as error:
            return self.transfer_arrangement_write_error(
                student_id, case_id, error
            )
        return self.transfer_arrangement_redirect(
            student_id, case_id, "Evidence已转为历史。"
        )

