            {"LetterOfConfirmation"},
            (
                ("Language Course / English Language Centre", "letter_language_course_name", "text", ""),
                ("Language Course Start Date", "letter_language_start_date", "date", ""),
                ("Language Course End Date", "letter_language_end_date", "date", ""),
                ("Year Level", "letter_year_level", "text", ""),
                ("Main Course / Host School", "letter_main_course_name", "text", ""),
                ("Main Course Start Date", "letter_main_start_date", "date", ""),
                ("Main Course End Date", "letter_main_end_date", "date", ""),
            ),
