    def visa_lodgement_file_type_options(self):
        return tuple(
            (item.form_value, item.label, item.document_type)
            for item in VISA_DOCUMENT_TYPE_DEFINITIONS
        )

    def visa_lodgement_file_type_value(self, value):
        return visa_document_type_definition(value).form_value

    def visa_lodgement_document_type(self, value):
        return visa_document_type_definition(value).document_type

    def visa_lodgement_file_type_label(self, value):
        return visa_document_type_definition(value).label

    def visa_lodgement_material_targets(self, value):
        value = self.visa_lodgement_file_type_value(value)
        if value in {"grant_letter", "refusal_letter"}:
            return ("IMMI Grant Letter / IMMI Refusal Letter",)
        if value in {"s56_request", "s56_response"}:
            return ("Supplement",)
        if value == "lodgement_receipt":
            return ("Receipt",)
        if value == "immi_acknowledgment":
            return ("IMMI Acknowledgment Letter",)
        if value == "bridging_visa":
            return ("Bridging Visa",)
        if value in {"health_examination", "hap_id"}:
            return ("Health Examination",)
        if value == "withdrawal_confirmation":
            return ("Other", "IMMI Grant Letter / IMMI Refusal Letter")
        return ("Other",)

    def visa_lodgement_result_status(self, value, filename=""):
        value = self.visa_lodgement_file_type_value(value)
        filename_text = str(filename or "").lower()
        if value == "grant_letter":
            return "Granted"
        if value == "refusal_letter":
            return "Refused"
        if value == "withdrawal_confirmation":
            return "Withdrawn"
        if value == "other":
            return ""
        if value == "s56_request" or value == "s56_response":
            return ""
        if "refusal" in filename_text or "refused" in filename_text or "拒签" in filename_text:
            return "Refused"
        if "grant" in filename_text or "granted" in filename_text or "下签" in filename_text:
            return "Granted"
        return ""

    def visa_lodgement_file_type_from_material_item(self, item, filename=""):
        title = self.visa_material_item_title(item).lower()
        filename_text = str(filename or "").lower()
        if "immi grant letter" in title or "immi refusal letter" in title:
            if "refusal" in filename_text or "refused" in filename_text or "拒签" in filename_text:
                return "refusal_letter"
            if "withdraw" in filename_text or "撤签" in filename_text:
                return "withdrawal_confirmation"
            if "grant" in filename_text or "granted" in filename_text or "下签" in filename_text:
                return "grant_letter"
            return "other"
        if title == "supplement":
            return "s56_response" if ("response" in filename_text or "回复" in filename_text) else "s56_request"
        if title == "receipt":
            return "lodgement_receipt"
        if "acknowledgment" in title:
            return "immi_acknowledgment"
        if "bridging visa" in title:
            return "bridging_visa"
        if "health examination" in title:
            return "hap_id" if "hap" in filename_text else "health_examination"
        return "other"

    def visa_open_case_rows_for_student(self, student_id):
        return db.all(
            """SELECT * FROM visa_cases
               WHERE student_id=? AND archived_at IS NULL
                 AND LOWER(COALESCE(status,'')) NOT IN ('granted','refused','withdrawn','closed','archived')
               ORDER BY created_at DESC,id DESC""",
            (student_id,),
        )

    def visa_case_select_html(self, student_id, current=""):
        rows = db.all("SELECT * FROM visa_cases WHERE student_id=? AND archived_at IS NULL ORDER BY created_at DESC,id DESC",(student_id,))
        current = str(current or "")
        options = ['<option value="">请选择要关联的 Visa Case</option>']
        for row in rows:
            label = f"#{row['id']} · {row['visa_type'] if 'visa_type' in row.keys() else 'Visa Case'} · {row['status']}"
            selected = " selected" if current == str(row["id"]) or (not current and len(rows) == 1) else ""
            options.append(f'<option value="{esc(row["id"])}"{selected}>{esc(label)}</option>')
        note = "暂无 VISA Management Case，文件会先保存在旧 VISA tab。" if not rows else "多个 Visa Case 时必须选择，避免自动挂错案子。"
        return f'<label>关联 Visa Case<select name="visa_case_id">{"".join(options)}</select><small>{esc(note)}</small></label>'

    def visa_lodgement_file_type_select_html(self, current="", disabled=False):
        current = visa_document_type_definition(current).form_value
        options = []
        for definition in VISA_DOCUMENT_TYPE_DEFINITIONS:
            selected = " selected" if definition.form_value == current else ""
            options.append(
                f'<option value="{esc(definition.form_value)}"{selected}>{esc(definition.label)}</option>'
            )
        disabled_attr = " disabled" if disabled else ""
        return f'<select name="visa_document_type" data-visa-document-type-select{disabled_attr}>{"".join(options)}</select>'

    def visa_document_for_file_path(self, student_id, file_path):
        if not file_path:
            return None
        return db.one(
            """SELECT * FROM student_documents
               WHERE student_id=? AND file_path=?
               ORDER BY uploaded_at DESC,id DESC LIMIT 1""",
            (student_id, file_path),
        )

    def visa_confirmed_file_metadata(self, student_id, visa):
        """Resolve a retained source through its exact canonical event, never filename guesses.

        Case-owned files need no synthetic StudentDocument or duplicate physical file.
        Older schemas continue using their existing StudentDocument metadata.
        """
        required = ("visa_case_confirmed_decisions", "visa_decision_events",
                    "visa_letter_extractions", "visa_case_documents", "visa_cases", "visas")
        present = db.one(
            "SELECT COUNT(*) total FROM sqlite_master WHERE type='table' AND name IN (?,?,?,?,?,?)",
            required,
        )
        if not present or present["total"] != len(required):
            return None
        return db.one(
            """SELECT document.original_name,document.version,document.sha256,
                      decision.visa_case_id,
                      CASE decision.decision_type WHEN 'grant' THEN 'VisaGrantLetter'
                           WHEN 'refusal' THEN 'VisaRefusalLetter' END document_type
                 FROM visa_case_confirmed_decisions decision
                 JOIN visa_decision_events event ON event.id=decision.canonical_event_id
                      AND event.visa_case_id=decision.visa_case_id
                      AND event.decision_type=decision.decision_type
                 JOIN visa_cases visa_case ON visa_case.id=decision.visa_case_id
                      AND visa_case.student_id=event.student_id
                 JOIN visa_letter_extractions extraction ON extraction.id=decision.extraction_id
                      AND extraction.visa_case_id=decision.visa_case_id
                 JOIN visa_case_documents document ON document.id=extraction.document_id
                      AND document.visa_case_id=decision.visa_case_id
                 JOIN visas record ON record.id=event.visa_record_id
                      AND record.student_id=event.student_id AND record.file_path=document.file_path
                WHERE record.id=? AND event.student_id=? AND document.file_path=?
                  AND decision.decision_type IN ('grant','refusal')
                ORDER BY decision.id LIMIT 1""",
            (visa["id"], student_id, visa["file_path"] or ""),
        )

    def visa_lodgement_resolve_target_case(self, student_id, selected_case_id, has_upload):
        selected_case_id = str(selected_case_id or "").strip()
        if selected_case_id:
            case = db.one(
                "SELECT * FROM visa_cases WHERE id=? AND student_id=? AND archived_at IS NULL",
                (selected_case_id, student_id),
            )
            if not case:
                return None, "请选择有效的 Visa Case。"
            return case, ""
        if not has_upload:
            return None, ""
        open_cases = self.visa_open_case_rows_for_student(student_id)
        if len(open_cases) == 1:
            return open_cases[0], ""
        if len(open_cases) > 1:
            return None, "该学生有多个 Visa Case，请选择要关联的 Visa Case。"
        return None, ""

    def visa_existing_evidence_cycle(self, student_id, visa_record_id=None):
        parameters = [str(student_id)]
        source_filter = ""
        if visa_record_id is not None:
            source_filter = (
                " AND disposition.module_key='visa'"
                " AND disposition.disposition='existing'"
                " AND disposition.source_record_type='visa'"
                " AND disposition.source_record_id=?"
            )
            parameters.append(int(visa_record_id))
        try:
            return db.one(
                f"""SELECT cycle.id,cycle.cycle_type
                       FROM application_cycles AS cycle
                       {"JOIN lifecycle_module_disposition_events AS disposition ON disposition.application_cycle_id=cycle.id" if visa_record_id is not None else ""}
                      WHERE cycle.student_id=? AND cycle.status='active'
                        AND cycle.cycle_type IN ('transfer','progression')
                        {source_filter}
                      ORDER BY {"disposition.occurred_at DESC,disposition.id DESC," if visa_record_id is not None else ""}cycle.id DESC
                      LIMIT 1""",
                tuple(parameters),
            )
        except sqlite3.OperationalError:
            return None

    def visa_lodgement_find_material_item(self, case_id, file_type_value):
        targets = self.visa_lodgement_material_targets(file_type_value)
        rows = db.all("SELECT * FROM visa_checklist_items WHERE visa_case_id=? ORDER BY id", (case_id,))
        for target in targets:
            target_norm = self.visa_material_normalized_text(target)
            for item in rows:
                if self.visa_material_normalized_text(self.visa_material_item_title(item)) == target_norm:
                    return item
        return None

    def visa_lodgement_update_case_result(self, case_id, file_type_value, filename=""):
        # Document detection is a proposal; Staff Confirm owns the decision.
        return None

    def visa_lodgement_link_document_to_case(self, student_id, case, document_id, file_type_value, filename=""):
        if not case or not document_id:
            return "该学生暂无 VISA Management Case，本文件暂未关联到具体 Visa Case。"
        item = self.visa_lodgement_find_material_item(case["id"], file_type_value)
        if not item:
            return "当前 Visa Case Checklist 中没有对应材料项，文件已保存但未自动挂载。"
        notes = f"Linked from Student VISA tab as {self.visa_lodgement_file_type_label(file_type_value)}."
        if self.visa_lodgement_file_type_value(file_type_value) == "withdrawal_confirmation":
            notes += " Withdrawal Confirmation."
        self.visa_material_insert_document_link(case, item, document_id, source="Student VISA tab", notes=notes)
        self.visa_material_mark_item_uploaded_if_missing(case["id"], item["id"])
        self.visa_lodgement_update_case_result(case["id"], file_type_value, filename)
        return f"已关联到 VISA Management Case #{case['id']}。"

    def visa_lodgement_sync_material_upload_to_visa_tab(self, case, item, document_id, filename):
        file_type_value = self.visa_lodgement_file_type_from_material_item(item, filename)
        if file_type_value == "other" and self.visa_material_item_title(item).lower() not in {"other"}:
            return
        document = db.one("SELECT * FROM student_documents WHERE id=?", (document_id,))
        if not document:
            return
        existing = db.one(
            "SELECT * FROM visas WHERE student_id=? AND file_path=? LIMIT 1",
            (case["student_id"], document["file_path"]),
        )
        result_status = self.visa_lodgement_result_status(file_type_value, filename)
        visa_status = "pending"
        if existing:
            pass  # Preserve existing confirmed Visa state during document upload.
        else:
            db.execute(
                """INSERT INTO visas(student_id,file_path,visa_type,visa_sector,visa_grant_date,visa_start_date,visa_expiry_date,
                   visa_conditions,visa_status,created_at) VALUES(?,?,?,?,?,?,?,?,?,?)""",
                (
                    case["student_id"],
                    document["file_path"],
                    case["visa_type"] if "visa_type" in case.keys() else "",
                    "590 陪读" if "590" in str(case["visa_type"] if "visa_type" in case.keys() else "") else "Schools Sector",
                    "",  # Unconfirmed uploads never carry an authoritative grant date.
                    "",
                    case["expiry_date"] if "expiry_date" in case.keys() else "",
                    self.visa_lodgement_file_type_label(file_type_value),
                    visa_status,
                    now_iso(),
                ),
            )
        self.visa_lodgement_update_case_result(case["id"], file_type_value, filename)

