    def visa_table_rows(self, student_id, visas):
        can_edit = can_save_visa_record(self.user)
        status_options = ("granted", "pending", "refused", "cancelled", "active", "expired")
        sector_options = ("Schools Sector", "Higher Education", "590 陪读", "Other")

        def select_options(options, current):
            current = str(current or "")
            return "".join(
                f'<option value="{esc(option)}" {"selected" if current == option else ""}>{esc(option)}</option>'
                for option in options
            )

        rows = []
        dialogs = []
        for visa in visas:
            visa_id = visa["id"]
            existing_evidence_cycle = self.visa_existing_evidence_cycle(
                student_id, visa_id
            )
            file_path = visa["file_path"] if "file_path" in visa.keys() else ""
            document = self.visa_document_for_file_path(student_id, file_path)
            confirmed_source = self.visa_confirmed_file_metadata(student_id, visa)
            presentation_document = confirmed_source or document
            filename = (presentation_document["original_name"] if presentation_document else "") or (Path(file_path).name if file_path else "")
            visa_document_type = presentation_document["document_type"] if presentation_document else "VisaFile"
            visa_document_label = self.visa_lodgement_file_type_label(visa_document_type)
            file_preview = student_file_preview_panel(
                preview_src=f"/visas/{visa_id}/preview?size=large" if file_path else "",
                download_url=f"/visas/{visa_id}/download" if file_path else "",
                title=filename or "VISA File",
                thumb_src=f"/visas/{visa_id}/preview" if file_path else "",
                has_file=bool(file_path),
            )
            edit_button = (
                f'<button type="button" class="secondary" data-dialog-open="visa-edit-{visa_id}">修改</button>'
                if can_edit else ""
            )
            if confirmed_source:
                edit_button = (
                    f'<a class="secondary button-link" href="/visa-management/cases/{confirmed_source["visa_case_id"]}/workspace#visa-result">'
                    f'查看已确认来源（版本 {esc(confirmed_source["version"])}）</a>'
                    '<small>已确认来源只读；更正需经过单独审计流程。</small>'
                )
            rows.append(
                '<article class="student-file-record visa-record-card">'
                '<div class="student-file-record-main">'
                f'<div class="student-file-record-head"><div><span class="status">{"沿用现有签证" if existing_evidence_cycle else esc(visa["visa_status"])}</span>'
                f'<strong>{esc(visa["visa_type"])}</strong><small>{esc(filename or "暂无文件")}</small></div>'
                f'<small>{esc(display_datetime(visa["created_at"] if "created_at" in visa.keys() else ""))}</small></div>'
                '<div class="student-file-meta-grid">'
                f'<div><span>文件类型</span><strong>{esc(visa_document_label)}</strong></div>'
                f'<div><span>Sector</span><strong>{esc(visa["visa_sector"] if "visa_sector" in visa.keys() else "")}</strong></div>'
                f'<div><span>{"拒签" if confirmed_source and visa_document_type == "VisaRefusalLetter" else "批准"}</span><strong>{esc(display_date_value(visa["visa_grant_date"]))}</strong></div>'
                f'<div><span>到期</span><strong>{esc(display_date_value(visa["visa_expiry_date"]))}</strong></div>'
                f'<div><span>状态</span><strong>{esc(visa["visa_status"])}</strong></div>'
                '</div>'
                f'<div class="student-file-record-actions">{edit_button}</div>'
                '</div>'
                f'<aside class="student-file-record-file">{file_preview}</aside>'
                '</article>'
            )
            if not can_edit or confirmed_source:
                continue
            dialogs.append(
                f"""<dialog id="visa-edit-{visa_id}"><form method="post" enctype="multipart/form-data" data-ajax-student-tab-form data-refresh-tab="visa" data-visa-document-type-form data-visa-document-type-has-file="{str(bool(file_path)).lower()}" action="/students/{student_id}/visa/{visa_id}/update"><input type="hidden" name="csrf" value="{esc(self.csrf)}"><input type="hidden" name="visa_record_purpose" value="{'existing_evidence' if existing_evidence_cycle else 'current_application'}"><div class="dialog-head"><h2>修改 VISA 记录</h2><button type="button" class="icon-button" data-dialog-close>×</button></div>
                  <div class="dialog-grid">
                    <label>类型<input name="visa_type" value="{esc(visa["visa_type"] or "")}" required></label>
                    <label>Sector<select name="visa_sector"><option value="">请选择</option>{select_options(sector_options, visa["visa_sector"] if "visa_sector" in visa.keys() else "")}</select></label>
                    {self.visa_case_select_html(student_id)}
                    <label>文件类型{self.visa_lodgement_file_type_select_html(visa_document_type, disabled=not bool(file_path))}{'<small>暂无文件，文件类型不可修改</small>' if not file_path else ''}</label>
                    <label>批准日期{crm_display_date_input("visa_grant_date", visa["visa_grant_date"])}</label>
                    <label>开始日期{crm_display_date_input("visa_start_date", visa["visa_start_date"] if "visa_start_date" in visa.keys() else "")}</label>
                    <label>到期日期{crm_display_date_input("visa_expiry_date", visa["visa_expiry_date"])}</label>
                    <label>状态<select name="visa_status"><option value="">请选择</option>{select_options(status_options, visa["visa_status"])}</select></label>
                    <label><input type="checkbox" name="confirm_visa_decision" value="yes" style="width:auto"> Staff Confirm official Visa Decision / 已核对正式签证结果及日期</label><label class="full">备注<textarea name="visa_conditions" rows="3">{esc(visa["visa_conditions"] if "visa_conditions" in visa.keys() else "")}</textarea></label>
                    <label>替换 VISA 文件<input type="file" name="file" accept=".pdf,.docx,.txt,.jpg,.jpeg,.png" data-visa-document-type-file></label>
                  </div>
                  <div class="dialog-actions"><button type="button" class="ghost" data-dialog-close>取消</button><button class="primary">保存修改</button><small class="inline-save-status" data-save-status></small></div></form></dialog>"""
            )
        return "".join(rows) or '<div class="empty">暂无记录</div>', "".join(dialogs)

    def business_panel(self, title, route, student_id, rows, fields, headers, extra_html="", as_cards=False):
        controls = []
        for spec in fields:
            label, name, kind, required = spec.split("|")
            req = " required" if required else ""
            if kind.startswith("select:"):
                options = "".join(f'<option value="{esc(v)}">{esc(v)}</option>' for v in kind.split(":", 1)[1].split(","))
                control = f'<select name="{esc(name)}"{req}><option value="">请选择</option>{options}</select>'
            elif kind == "file_multiple":
                control = f'<input type="file" name="{esc(name)}" multiple{req}>'
            elif kind == "date":
                control = crm_display_date_input(name, required=bool(required))
            else:
                control = f'<input type="{kind}" name="{esc(name)}"{req}>'
            controls.append(f'<label>{esc(label)}{control}</label>')
        heads = "".join(f"<th>{esc(h)}</th>" for h in headers)
        content = f'<div class="student-file-list">{rows}</div>' if as_cards else f'<div class="table-wrap"><table><thead><tr>{heads}</tr></thead><tbody>{rows}</tbody></table></div>'
        return f"""<section class="panel"><div class="panel-head"><div><h2>{esc(title)}</h2><p>MVP 基础记录与文件归档</p></div><button class="secondary" type="button" data-dialog-open="{route}-dialog">新增记录</button></div>
        {content}</section>
        <dialog id="{route}-dialog"><form method="post" enctype="multipart/form-data" action="/students/{student_id}/{route}"><input type="hidden" name="csrf" value="{esc(self.csrf)}"><div class="dialog-head"><h2>新增 {esc(title)}</h2><button type="button" class="icon-button" data-dialog-close>×</button></div><div class="dialog-grid">{"".join(controls)}</div><div class="dialog-actions"><button type="button" class="ghost" data-dialog-close>取消</button><button class="primary">保存</button></div></form></dialog>{extra_html}"""

