    def visa_material_document_status_options(self):
        return ("uploaded", "missing", "not_applicable")

    def visa_material_normalized_document_status(self, status):
        raw = str(status or "").strip().lower()
        if raw in {"uploaded", "reviewed", "已收到", "已审核"}:
            return "uploaded"
        if raw in {"not_applicable", "不适用"}:
            return "not_applicable"
        return "missing"

    def visa_material_document_status_labels(self):
        return {
            "missing": "未收到",
            "uploaded": "已收到",
            "not_applicable": "不适用",
        }

    def visa_material_required_status_label(self, required_status):
        return {
            "required": "必交",
            "conditional": "条件材料",
            "optional": "可选",
        }.get(str(required_status or ""), required_status or "—")

