    def visa_material_template_key(self, profile, category, material_name):
        raw = f"{profile}_{category}_{material_name}".lower()
        key = "".join(ch if ch.isalnum() else "_" for ch in raw)
        return "_".join(part for part in key.split("_") if part)

    def visa_material_item(self, profile, category, material_name, owner_type, upload_to_immi, purpose, application_type, required_status):
        return {
            "item_key": self.visa_material_template_key(profile, category, material_name),
            "category": category,
            "material_name": material_name,
            "owner_type": owner_type,
            "upload_to_immi": upload_to_immi,
            "purpose": purpose,
            "application_type": application_type,
            "required_status": required_status,
        }

