    def visa_material_profile(self, case):
        parts = []
        for key in ("visa_type", "case_type", "visa_subclass", "application_type", "guardian_applicant"):
            if key in case.keys():
                parts.append(str(case[key] or ""))
        text = " ".join(parts).lower()
        if "590" in text or "guardian" in text:
            return "guardian"
        return "student"

    def visa_material_template(self, case):
        return self.visa_material_guardian_template() if self.visa_material_profile(case) == "guardian" else self.visa_material_student_template()

    def visa_material_profile_label(self, case):
        return "亲属陪读" if self.visa_material_profile(case) == "guardian" else "学生单独"

    def visa_material_case_or_404(self, student_id, case_id):
        student = self.student_detail_row(student_id)
        if not student:
            self.error_page("学生不存在", 404)
            return None
        case = db.one(
            "SELECT * FROM visa_cases WHERE id=? AND student_id=? AND archived_at IS NULL",
            (case_id, student_id),
        )
        if not case:
            self.error_page("Visa Case 不存在。", HTTPStatus.NOT_FOUND)
            return None
        return case

    def visa_material_initialize_checklist(self, case):
        stamp = now_iso()
        columns = {row["name"] for row in db.all("PRAGMA table_info(visa_checklist_items)")}
        existing_keys = {
            row["item_key"]
            for row in db.all("SELECT item_key FROM visa_checklist_items WHERE visa_case_id=? AND item_key IS NOT NULL", (case["id"],))
            if str(row["item_key"] or "").strip()
        }
        ordered_columns = (
            "visa_case_id",
            "item_key",
            "title",
            "status",
            "required",
            "notes",
            "created_at",
            "updated_at",
            "item_name",
            "category",
            "document_type",
            "requirement_status",
            "item_status",
            "sort_order",
            "created_by",
            "updated_by",
        )
        user_id = (self.user or {}).get("id") if hasattr(self, "user") else None
        for sort_order, item in enumerate(self.visa_material_template(case), start=1):
            if item["item_key"] in existing_keys:
                continue
            data = {
                "visa_case_id": case["id"],
                "item_key": item["item_key"],
                "title": item["material_name"],
                "status": "missing",
                "required": 1 if item["required_status"] == "required" else 0,
                "notes": "",
                "created_at": stamp,
                "updated_at": stamp,
                "item_name": item["material_name"],
                "category": item["category"],
                "document_type": item["material_name"],
                "requirement_status": self.visa_material_required_status_label(item["required_status"]),
                "item_status": "missing",
                "sort_order": sort_order,
                "created_by": user_id,
                "updated_by": user_id,
            }
            insert_columns = [column for column in ordered_columns if column in columns]
            placeholders = ",".join("?" for _ in insert_columns)
            db.execute(
                f"""INSERT OR IGNORE INTO visa_checklist_items
                   ({",".join(insert_columns)})
                   VALUES({placeholders})""",
                [data[column] for column in insert_columns],
            )
            existing_keys.add(item["item_key"])
        count_row = db.one("SELECT COUNT(*) total FROM visa_checklist_items WHERE visa_case_id=?", (case["id"],))
        return count_row["total"] if count_row else 0

    def visa_material_checklist_rows(self, case):
        columns = {row["name"] for row in db.all("PRAGMA table_info(visa_checklist_items)")}
        order_clause = "COALESCE(sort_order,0),id" if "sort_order" in columns else "id"
        stored_rows = db.all(f"SELECT * FROM visa_checklist_items WHERE visa_case_id=? ORDER BY {order_clause}", (case["id"],))
        existing = {row["item_key"]: row for row in stored_rows if str(row["item_key"] or "").strip()}
        rows = []
        template_keys = set()
        for item in self.visa_material_template(case):
            template_keys.add(item["item_key"])
            stored = existing.get(item["item_key"])
            rows.append({
                **item,
                "id": stored["id"] if stored else "",
                "document_status": self.visa_material_normalized_document_status(stored["status"] if stored else "missing"),
                "notes": stored["notes"] if stored else "",
                "is_initialized": bool(stored),
            })
        for stored in stored_rows:
            stored_key = str((stored["item_key"] if "item_key" in stored.keys() else "") or "").strip()
            if stored_key and stored_key in template_keys:
                continue
            title = stored["title"] if "title" in stored.keys() else ""
            item_name = stored["item_name"] if "item_name" in stored.keys() else ""
            category = stored["category"] if "category" in stored.keys() else "Other"
            document_type = stored["document_type"] if "document_type" in stored.keys() else ""
            requirement_status = str(stored["requirement_status"] if "requirement_status" in stored.keys() else "").lower()
            required_status = "required" if (stored["required"] if "required" in stored.keys() else 0) else "optional"
            if "conditional" in requirement_status or "条件" in requirement_status:
                required_status = "conditional"
            status = stored["status"] if "status" in stored.keys() else ""
            item_status = stored["item_status"] if "item_status" in stored.keys() else ""
            rows.append({
                "item_key": stored_key or f"legacy_item_{stored['id']}",
                "category": category or "Other",
                "material_name": title or item_name or document_type or "Legacy Material",
                "owner_type": "Other",
                "upload_to_immi": "Conditional",
                "purpose": "Other supporting evidence",
                "application_type": self.visa_material_profile_label(case),
                "required_status": required_status,
                "id": stored["id"],
                "document_status": self.visa_material_normalized_document_status(status or item_status or "missing"),
                "notes": stored["notes"] if "notes" in stored.keys() else "",
                "is_initialized": True,
            })
        return rows

    def visa_material_status_select_html(self, item, form_id=""):
        options = []
        current = self.visa_material_normalized_document_status(item["document_status"])
        labels = self.visa_material_document_status_labels()
        for status in self.visa_material_document_status_options():
            selected = "selected" if status == current else ""
            options.append(f'<option value="{esc(status)}" {selected}>{esc(labels.get(status, status))}</option>')
        form_attr = f' form="{esc(form_id)}"' if form_id else ""
        return f'<select name="document_status_{esc(item["id"])}" aria-label="当前状态"{form_attr}>{"".join(options)}</select>'

    def visa_material_is_completed(self, item):
        return self.visa_material_normalized_document_status(item["document_status"]) in {"uploaded", "not_applicable"}

    def visa_material_filter_options(self):
        return (
            ("all", "全部"),
            ("required", "必交"),
            ("optional", "可选"),
            ("conditional", "条件材料"),
            ("missing", "未收到"),
            ("uploaded", "已收到"),
            ("not_applicable", "不适用"),
            ("unfinished", "只看未完成材料"),
            ("required_unfinished", "只看必交未完成材料"),
        )

    def visa_material_current_filter(self):
        raw = ""
        query = getattr(self, "query", {}) or {}
        if query.get("material_filter"):
            raw = (query.get("material_filter") or [""])[0]
        allowed = {key for key, _label in self.visa_material_filter_options()}
        return raw if raw in allowed else "all"

    def visa_material_matches_filter(self, item, filter_key):
        if filter_key == "all":
            return True
        if filter_key in {"required", "optional", "conditional"}:
            return item["required_status"] == filter_key
        if filter_key in set(self.visa_material_document_status_options()):
            return self.visa_material_normalized_document_status(item["document_status"]) == filter_key
        if filter_key == "unfinished":
            return not self.visa_material_is_completed(item)
        if filter_key == "required_unfinished":
            return item["required_status"] == "required" and not self.visa_material_is_completed(item)
        return True

    def visa_material_filter_bar_html(self, student_id, case_id, current_filter, tab_key="material_checklist"):
        links = []
        for filter_key, label in self.visa_material_filter_options():
            active = " active" if filter_key == current_filter else ""
            href = f"/students/{quote(student_id)}/visa-cases/{case_id}?visa_tab={quote(tab_key)}&material_filter={quote(filter_key)}#material-checklist"
            links.append(f'<a class="visa-material-filter-chip{active}" href="{href}">{esc(label)}</a>')
        return f'<div class="visa-material-filter-bar" aria-label="材料筛选">{"".join(links)}</div>'

    def visa_material_summary_counts(self, rows):
        total = len(rows)
        uploaded = sum(1 for row in rows if self.visa_material_normalized_document_status(row["document_status"]) == "uploaded")
        missing = sum(1 for row in rows if self.visa_material_normalized_document_status(row["document_status"]) == "missing")
        not_applicable = sum(1 for row in rows if self.visa_material_normalized_document_status(row["document_status"]) == "not_applicable")
        completed = uploaded + not_applicable
        completion = round((completed / total) * 100) if total else 0
        return {
            "total": total,
            "missing": missing,
            "uploaded": uploaded,
            "not_applicable": not_applicable,
            "completed": completed,
            "completion": completion,
        }

    def visa_material_effective_rows(self, student_id, case, rows):
        effective_rows = []
        for row in rows:
            effective = dict(row)
            effective["document_status"] = self.visa_material_normalized_document_status(effective.get("document_status"))
            if effective.get("is_initialized") and effective["document_status"] == "missing":
                if self.get_visa_required_files_for_material(student_id, case["id"], effective):
                    effective["document_status"] = "uploaded"
                    effective["auto_reference_status"] = True
            effective_rows.append(effective)
        return effective_rows

