    def visa_evidence_review_path(self, student_id, case_id, anchor=""):
        path = f"/students/{quote(student_id)}/visa-cases/{case_id}/evidence-ai-review"
        return f"{path}#{anchor}" if anchor else path

    def visa_evidence_review_tab_path(self, student_id, case_id, anchor=""):
        path = f"/students/{quote(student_id)}/visa-cases/{case_id}?visa_tab=evidence_ai_review"
        return f"{path}#{anchor}" if anchor else path

    def visa_evidence_safe_return_path(self, student_id, case_id, fallback_anchor="evidence-information"):
        fallback = self.visa_evidence_review_path(student_id, case_id, fallback_anchor)
        raw = form_text_value(getattr(self, "form", {}) or {}, "return_to")
        if not raw:
            return fallback
        case_prefix = f"/students/{quote(student_id)}/visa-cases/{case_id}"
        allowed_prefixes = (
            f"{case_prefix}?visa_tab=evidence_ai_review",
            f"{case_prefix}/evidence-ai-review",
        )
        return raw if any(raw.startswith(prefix) for prefix in allowed_prefixes) else fallback

