    def visa_evidence_decimal(self, value):
        try:
            text = str(value or "").replace(",", "").strip()
            return Decimal(text) if text else Decimal("0")
        except Exception:
            return Decimal("0")

    def visa_evidence_valid_nonnegative_decimal(self, value):
        try:
            text = str(value or "").replace(",", "").strip()
            if not text:
                return False
            return Decimal(text) >= 0
        except Exception:
            return False

    def visa_evidence_amount_label(self, value):
        amount = self.visa_evidence_decimal(value)
        if amount == amount.to_integral_value():
            return f"{int(amount):,}"
        return f"{amount:,.2f}".rstrip("0").rstrip(".")

    def visa_evidence_option_label(self, option_key, value):
        value = str(value or "")
        options = {}
        options.update(self.visa_evidence_financial_item_options())
        options.update(self.visa_evidence_asset_item_options())
        for option_value, option_label in options.get(option_key, ()):
            if value == option_value:
                return option_label
        return value

    def visa_evidence_financial_summary(self, rows):
        summary = {
            "deposit_total": Decimal("0"),
            "salary_annualized_total": Decimal("0"),
            "rental_annualized_total": Decimal("0"),
            "business_bonus_dividend_total": Decimal("0"),
            "investment_stock_total": Decimal("0"),
            "other_income_total": Decimal("0"),
            "all_annualized_income_total": Decimal("0"),
        }
        for row in rows:
            item_type = str(row["item_type"] or "")
            amount = self.visa_evidence_decimal(row["amount"])
            annualized = self.visa_evidence_financial_effective_annualized(row)
            if item_type == "Deposit":
                summary["deposit_total"] += amount
                continue
            if item_type == "Salary":
                summary["salary_annualized_total"] += annualized
            elif item_type == "Rental Income":
                summary["rental_annualized_total"] += annualized
            elif item_type in {"Business Income", "Dividend", "Bonus"}:
                summary["business_bonus_dividend_total"] += annualized
            elif item_type in {"Investment Return", "Stock Return"}:
                summary["investment_stock_total"] += annualized
            elif item_type == "Other":
                summary["other_income_total"] += annualized
            summary["all_annualized_income_total"] += annualized
        return summary

    def visa_evidence_financial_effective_annualized(self, row):
        item_type = str(row["item_type"] or "")
        if item_type == "Deposit":
            return Decimal("0")
        annualized_raw = str(row["annualized_amount"] or "").replace(",", "").strip()
        if annualized_raw:
            return self.visa_evidence_decimal(annualized_raw)
        amount = self.visa_evidence_decimal(row["amount"])
        frequency = str(row["frequency"] or "")
        if frequency == "Monthly":
            return amount * Decimal("12")
        if frequency == "Annual":
            return amount
        if frequency == "One-off" and item_type in {"Business Income", "Dividend", "Bonus"}:
            return amount
        return Decimal("0")

    def visa_evidence_financial_needs_annualized_hint(self, row):
        item_type = str(row["item_type"] or "")
        frequency = str(row["frequency"] or "")
        annualized_raw = str(row["annualized_amount"] or "").replace(",", "").strip()
        return item_type != "Deposit" and frequency == "Irregular" and not annualized_raw

    def visa_evidence_asset_summary(self, rows):
        summary = {
            "property_total": Decimal("0"),
            "business_total": Decimal("0"),
            "investment_total": Decimal("0"),
            "insurance_total": Decimal("0"),
            "vehicle_total": Decimal("0"),
            "other_total": Decimal("0"),
            "total_asset_value": Decimal("0"),
        }
        for row in rows:
            asset_type = str(row["asset_type"] or "")
            amount = self.visa_evidence_decimal(row["estimated_value"])
            if asset_type == "Property":
                summary["property_total"] += amount
            elif asset_type == "Business":
                summary["business_total"] += amount
            elif asset_type in {"Wealth Management Product", "Stock", "Fund"}:
                summary["investment_total"] += amount
            elif asset_type == "Insurance Cash Value":
                summary["insurance_total"] += amount
            elif asset_type == "Vehicle":
                summary["vehicle_total"] += amount
            elif asset_type == "Other":
                summary["other_total"] += amount
            summary["total_asset_value"] += amount
        return summary

    def visa_evidence_select_html(self, name, value, options):
        value = str(value or "")
        option_values = {str(option_value) for option_value, _option_label in options}
        rendered = []
        if value and value not in option_values:
            rendered.append(f'<option value="{esc(value)}" selected>{esc(value)}（现有值）</option>')
        for option_value, option_label in options:
            selected = " selected" if value == option_value else ""
            rendered.append(f'<option value="{esc(option_value)}"{selected}>{esc(option_label)}</option>')
        return f'<select name="{esc(name)}"><option value="">请选择</option>{"".join(rendered)}</select>'

