    def visa_evidence_form_html(self, student_id, case, return_path=""):
        profile = self.visa_evidence_profile(case["id"]) or {}

        def value_for(name):
            try:
                return str(profile[name] or "") if name in profile.keys() else ""
            except Exception:
                return ""

        def field_html(field):
            name, label, field_type = field[:3]
            value = value_for(name)
            if field_type == "textarea":
                control = f'<textarea name="{esc(name)}" rows="3">{esc(value)}</textarea>'
            elif field_type == "select":
                option_values = {str(option_value) for option_value, _option_label in field[3]}
                options = "".join(
                    f'<option value="{esc(option_value)}" {"selected" if value == option_value else ""}>{esc(option_label)}</option>'
                    for option_value, option_label in field[3]
                )
                if value and value not in option_values:
                    options = f'<option value="{esc(value)}" selected>{esc(value)}（现有值）</option>' + options
                control = f'<select name="{esc(name)}"><option value="">请选择</option>{options}</select>'
            else:
                input_type = "number" if field_type == "number" else "text"
                step = ' step="0.01"' if field_type == "number" else ""
                control = f'<input type="{input_type}"{step} name="{esc(name)}" value="{esc(value)}">'
            help_text = self.visa_evidence_field_help(name)
            help_html = f'<small class="visa-evidence-field-help">{esc(help_text)}</small>' if help_text else ""
            return f'<label class="visa-evidence-field"><span>{esc(label)}</span>{control}{help_html}</label>'

        sections_html = []
        for section in self.visa_evidence_sections():
            fields = "".join(field_html(field) for field in section["fields"])
            description = str(section.get("description") or "")
            description_html = f'<p class="visa-evidence-section-note">{esc(description)}</p>' if description else ""
            focus_items = section.get("focus") or ()
            focus_html = ""
            if focus_items:
                focus_html = '<div class="visa-evidence-focus-chips">' + "".join(
                    f'<span>{esc(item)}</span>' for item in focus_items
                ) + "</div>"
            sections_html.append(
                f"""
                <section class="visa-evidence-section{' visa-evidence-guided-section' if focus_items else ''}">
                  <h3>{esc(section["title"])}</h3>
                  {description_html}
                  {focus_html}
                  <div class="visa-evidence-grid">{fields}</div>
                </section>
                """
            )
        return f"""
        <section class="panel visa-evidence-panel" id="evidence-information">
          <div class="panel-head">
            <div>
              <h2>Family Financial Profile / 家庭资金与资产画像</h2>
              <p>后台人工录入当前 Visa Case 的家庭资金、收入、资产、国内约束力、学习计划和风险说明；本阶段只保存人工录入数据。</p>
              <p class="visa-evidence-position-note">Material Checklist 用于管理签证文件；Evidence / AI Review 用于记录文件背后的资金、收入、资产、家庭约束力和学习计划等结构化信息，后续用于签证分析、GS/GTE、Word/PDF 和家长填写链接。</p>
            </div>
          </div>
          <form method="post" action="/students/{quote(student_id)}/visa-cases/{case['id']}/evidence">
            <input type="hidden" name="csrf" value="{esc(self.csrf)}">
            {f'<input type="hidden" name="return_to" value="{esc(return_path)}">' if return_path else ''}
            {''.join(sections_html)}
            <div class="dialog-actions visa-evidence-actions">
              <button class="primary" type="submit">保存签证证据信息</button>
            </div>
          </form>
          {self.visa_evidence_financial_items_html(student_id, case, return_path)}
          {self.visa_evidence_asset_items_html(student_id, case, return_path)}
        </section>
        """

    def student_visa_case_financial_item_save(self, method, student_id, case_id):
        if method != "POST":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        if not can_access_module(self.user, "visa"):
            return self.error_page("你没有访问 Visa Management 的权限。", HTTPStatus.FORBIDDEN)
        case = self.visa_material_case_or_404(student_id, case_id)
        if not case:
            return
        form = getattr(self, "form", None)
        if form is None:
            form, _files = parse_request_body(self)
            self.form = form
        fields = self.visa_evidence_financial_item_fields()
        values = {name: form_text_value(form, name) for name in fields}
        required_message = "空白明细无法增加。请至少填写类型、提供人、金额、币种和频率。"
        if (
            not values["item_type"]
            or not values["provider"]
            or not values["amount"]
            or not values["currency"]
            or not values["frequency"]
            or not self.visa_evidence_valid_nonnegative_decimal(values["amount"])
        ):
            return self.flash_redirect(
                self.visa_evidence_safe_return_path(student_id, case_id, "financial-items"),
                required_message,
                "error",
            )
        item_id = form_text_value(form, "financial_item_id")
        stamp = now_iso()
        if item_id:
            existing = db.one(
                "SELECT * FROM visa_evidence_financial_items WHERE id=? AND visa_case_id=? AND COALESCE(is_archived,0)=0",
                (item_id, case["id"]),
            )
            if existing:
                assignments = ",".join(f"{name}=?" for name in fields)
                params = [values[name] for name in fields] + [stamp, item_id, case["id"]]
                db.execute(
                    f"UPDATE visa_evidence_financial_items SET {assignments},updated_at=? WHERE id=? AND visa_case_id=?",
                    params,
                )
        else:
            columns = ["visa_case_id"] + list(fields) + ["is_archived", "created_at", "updated_at"]
            placeholders = ",".join("?" for _ in columns)
            params = [case["id"]] + [values[name] for name in fields] + [0, stamp, stamp]
            db.execute(
                f"INSERT INTO visa_evidence_financial_items({','.join(columns)}) VALUES({placeholders})",
                params,
            )
        return self.flash_redirect(
            self.visa_evidence_safe_return_path(student_id, case_id, "financial-items"),
            "资金与收入明细已保存。",
        )

    def student_visa_case_financial_item_archive(self, method, student_id, case_id, item_id):
        if method != "POST":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        if not can_access_module(self.user, "visa"):
            return self.error_page("你没有访问 Visa Management 的权限。", HTTPStatus.FORBIDDEN)
        case = self.visa_material_case_or_404(student_id, case_id)
        if not case:
            return
        db.execute(
            "UPDATE visa_evidence_financial_items SET is_archived=1,updated_at=? WHERE id=? AND visa_case_id=?",
            (now_iso(), item_id, case["id"]),
        )
        return self.flash_redirect(
            self.visa_evidence_safe_return_path(student_id, case_id, "financial-items"),
            "资金与收入明细已删除。",
        )

    def student_visa_case_asset_item_save(self, method, student_id, case_id):
        if method != "POST":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        if not can_access_module(self.user, "visa"):
            return self.error_page("你没有访问 Visa Management 的权限。", HTTPStatus.FORBIDDEN)
        case = self.visa_material_case_or_404(student_id, case_id)
        if not case:
            return
        form = getattr(self, "form", None)
        if form is None:
            form, _files = parse_request_body(self)
            self.form = form
        fields = self.visa_evidence_asset_item_fields()
        values = {name: form_text_value(form, name) for name in fields}
        required_message = "空白资产明细无法增加。请至少填写资产类型、持有人、估值金额和币种。"
        if (
            not values["asset_type"]
            or not values["owner"]
            or not values["estimated_value"]
            or not values["currency"]
            or not self.visa_evidence_valid_nonnegative_decimal(values["estimated_value"])
        ):
            return self.flash_redirect(
                self.visa_evidence_safe_return_path(student_id, case_id, "asset-items"),
                required_message,
                "error",
            )
        item_id = form_text_value(form, "asset_item_id")
        stamp = now_iso()
        if item_id:
            existing = db.one(
                "SELECT * FROM visa_evidence_asset_items WHERE id=? AND visa_case_id=? AND COALESCE(is_archived,0)=0",
                (item_id, case["id"]),
            )
            if existing:
                assignments = ",".join(f"{name}=?" for name in fields)
                params = [values[name] for name in fields] + [stamp, item_id, case["id"]]
                db.execute(
                    f"UPDATE visa_evidence_asset_items SET {assignments},updated_at=? WHERE id=? AND visa_case_id=?",
                    params,
                )
        else:
            columns = ["visa_case_id"] + list(fields) + ["is_archived", "created_at", "updated_at"]
            placeholders = ",".join("?" for _ in columns)
            params = [case["id"]] + [values[name] for name in fields] + [0, stamp, stamp]
            db.execute(
                f"INSERT INTO visa_evidence_asset_items({','.join(columns)}) VALUES({placeholders})",
                params,
            )
        return self.flash_redirect(
            self.visa_evidence_safe_return_path(student_id, case_id, "asset-items"),
            "资产明细已保存。",
        )

    def student_visa_case_asset_item_archive(self, method, student_id, case_id, item_id):
        if method != "POST":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        if not can_access_module(self.user, "visa"):
            return self.error_page("你没有访问 Visa Management 的权限。", HTTPStatus.FORBIDDEN)
        case = self.visa_material_case_or_404(student_id, case_id)
        if not case:
            return
        db.execute(
            "UPDATE visa_evidence_asset_items SET is_archived=1,updated_at=? WHERE id=? AND visa_case_id=?",
            (now_iso(), item_id, case["id"]),
        )
        return self.flash_redirect(
            self.visa_evidence_safe_return_path(student_id, case_id, "asset-items"),
            "资产明细已删除。",
        )

