    def visa_information_collection_form_type_label(self, form_type):
        for value, label, _version in self.visa_information_collection_form_types():
            if form_type == value:
                return label
        return form_type or "—"

    def visa_information_collection_default_template_version(self, form_type):
        for value, _label, version in self.visa_information_collection_form_types():
            if form_type == value:
                return version
        return "canonical-v1"

    def visa_information_collection_default_form_types_for_case(self, case):
        profile = self.visa_material_profile(case) if case else "student"
        if profile == "guardian":
            return (
                "visa_application_info_500_590_485",
                "gte_statement_guardian_raw",
            )
        visa_type = str(case["visa_type"] or case["case_type"] or "").lower() if case else ""
        if "500" in visa_type:
            return (
                "visa_application_info_500_590_485",
                "au_student_visa_information_declaration",
                "parent_statement_zh",
                "genuine_student_statement_raw",
            )
        return ("visa_application_info_500_590_485",)

    def visa_information_collection_ensure_assignment(self, case, respondent, form_type):
        if not case or not respondent:
            return None, False
        existing = db.one(
            "SELECT * FROM visa_form_assignments WHERE respondent_id=? AND visa_case_id=? AND form_type=?",
            (respondent["id"], case["id"], form_type),
        )
        if existing:
            return existing, False
        stamp = now_iso()
        db.execute(
            """INSERT INTO visa_form_assignments(
               package_id,respondent_id,visa_case_id,form_type,template_version,status,progress_percent,created_at,updated_at)
               VALUES(?,?,?,?,?,?,?,?,?)""",
            (
                respondent["package_id"],
                respondent["id"],
                case["id"],
                form_type,
                self.visa_information_collection_default_template_version(form_type),
                "Not Started",
                0,
                stamp,
                stamp,
            ),
        )
        return db.one(
            "SELECT * FROM visa_form_assignments WHERE respondent_id=? AND visa_case_id=? AND form_type=?",
            (respondent["id"], case["id"], form_type),
        ), True

    def visa_information_collection_ensure_default_assignments(self, case, respondent):
        created = []
        for form_type in self.visa_information_collection_default_form_types_for_case(case):
            _assignment, was_created = self.visa_information_collection_ensure_assignment(case, respondent, form_type)
            if was_created:
                created.append(form_type)
        return created

    def visa_information_collection_overall_progress(self, assignments):
        rows = [row for row in (assignments or []) if str(row["status"] or "") != "Cancelled"]
        if not rows:
            return 0
        completed = 0
        for row in rows:
            status = str(row["status"] or "")
            progress = self.visa_information_collection_progress_value(row["progress_percent"])
            if status in {"Submitted", "Reviewed", "Locked"} or progress >= 100:
                completed += 1
        return int(round((completed / max(1, len(rows))) * 100))

    def visa_information_collection_assignment_public_href(self, token, assignment):
        if assignment["form_type"] == "visa_application_info_500_590_485":
            return f"/visa-information-collection/{quote(token)}/forms/visa_application_info_500_590_485"
        return f"/visa-information-collection/{quote(token)}/forms/{quote(str(assignment['form_type']))}"

    def visa_information_collection_next_assignment(self, respondent, assignment):
        if not respondent or not assignment:
            return None
        assignments = db.all(
            """SELECT * FROM visa_form_assignments
               WHERE respondent_id=? AND visa_case_id=? AND status<>'Cancelled'
               ORDER BY id""",
            (respondent["id"], respondent["visa_case_id"]),
        )
        for index, row in enumerate(assignments):
            if int(row["id"]) == int(assignment["id"]):
                return assignments[index + 1] if index + 1 < len(assignments) else None
        return None

    def visa_information_collection_next_assignment_prompt(self, token, respondent, assignment):
        status = str(assignment["status"] or "")
        progress = self.visa_information_collection_progress_value(assignment["progress_percent"])
        if status not in {"Submitted", "Reviewed", "Locked"} and progress < 100:
            return ""
        next_assignment = self.visa_information_collection_next_assignment(respondent, assignment)
        if not next_assignment:
            return "<div class='notice success'>所有已分配表单已完成或已进入下一阶段。</div>"
        href = self.visa_information_collection_assignment_public_href(token, next_assignment)
        return f"""
        <div class="notice success">
          <strong>本表已完成。</strong>
          <p>是否继续填写下一份表：{esc(self.visa_information_collection_form_type_label(next_assignment["form_type"]))}</p>
          <div class="share-actions"><a class="primary button-link" href="{esc(href)}">进入下一份表</a></div>
        </div>
        """

