        if not respondent:
            return case, None, None
        assignment = db.one(
            """SELECT * FROM visa_form_assignments
               WHERE id=? AND respondent_id=? AND visa_case_id=?""",
            (assignment_id, respondent["id"], case["id"]),
        )
        return case, respondent, assignment

