    def student_visa_case_information_assignment_edit(self, method, student_id, case_id, respondent_id, assignment_id):
        if method not in {"GET", "POST"}:
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        if not can_access_module(self.user, "visa"):
            return self.error_page("你没有访问 Visa Management 的权限。", HTTPStatus.FORBIDDEN)
        case, respondent, assignment = self.student_visa_case_information_assignment_row(student_id, case_id, respondent_id, assignment_id)
        if not case:
            return
        if not respondent or not assignment:
            return self.flash_redirect(
                self.visa_case_return_path(student_id, case_id, "info_collection", "applicant-information-collection"),
                "未找到对应表单。",
                "error",
            )
        is_500_form = assignment["form_type"] == "visa_application_info_500_590_485"
        structured_spec = self.visa_information_collection_structured_form_spec(assignment["form_type"])
        if is_500_form:
            _draft, payload = self.visa_aic_500_assignment_draft(assignment)
            payload = self.visa_aic_500_apply_student_profile_prefill(payload, respondent)
        elif structured_spec:
            _draft, payload = self.visa_information_collection_structured_assignment_draft(assignment)
        else:
            return self.flash_redirect(
                self.visa_case_return_path(student_id, case_id, "info_collection", "applicant-information-collection"),
                "系统缺少该表单 Word 模板，请联系顾问配置。",
                "error",
            )
        if method == "POST":
            form = getattr(self, "form", None)
            if form is None:
                form, _files = parse_request_body(self)
                self.form = form
            if is_500_form:
                payload = self.visa_aic_500_admin_edit_payload(payload, form)
                payload = self.visa_aic_500_apply_student_profile_prefill(payload, respondent)
            else:
                payload = self.visa_information_collection_structured_admin_edit_payload(payload, structured_spec, form)
            status = assignment["status"] or "Draft"
            if is_500_form:
                self.visa_aic_500_upsert_draft(assignment, respondent, payload, status, submitted=False)
            else:
                self.visa_information_collection_structured_upsert_draft(assignment, respondent, payload, status, submitted=False)
            return self.toast_redirect(
                f"/students/{quote(student_id)}/visa-cases/{case_id}/information-collection/respondents/{respondent_id}/content#assignment-{assignment_id}",
                "后台修改已保存。",
                "success",
                "Applicant Information",
            )
        if is_500_form:
            body = self.visa_aic_500_admin_edit_html(student_id, case_id, respondent, assignment, payload)
        else:
            body = self.visa_information_collection_structured_admin_edit_html(student_id, case_id, respondent, assignment, payload)
        return self.send_html(page("后台修改签证申请信息表", body, self.user, self.csrf, "visa_management", nas.status()))

    def student_visa_case_information_assignment_return_for_update(self, method, student_id, case_id, respondent_id, assignment_id):
        if method != "POST":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        if not can_access_module(self.user, "visa"):
            return self.error_page("你没有访问 Visa Management 的权限。", HTTPStatus.FORBIDDEN)
        case, respondent, assignment = self.student_visa_case_information_assignment_row(student_id, case_id, respondent_id, assignment_id)
        if not case:
            return
        if not respondent or not assignment:
            return self.flash_redirect(
                self.visa_case_return_path(student_id, case_id, "info_collection", "applicant-information-collection"),
                "未找到对应表单。",
                "error",
            )
        stamp = now_iso()
        db.execute(
            """UPDATE visa_form_assignments
               SET status='Returned for Update',updated_at=?
               WHERE id=? AND respondent_id=? AND visa_case_id=?""",
            (stamp, assignment["id"], respondent["id"], case["id"]),
        )
        db.execute(
            """UPDATE visa_form_drafts
               SET status='Returned for Update',updated_at=?
               WHERE assignment_id=? AND respondent_id=? AND visa_case_id=?""",
            (stamp, assignment["id"], respondent["id"], case["id"]),
        )
        db.execute(
            """UPDATE visa_information_collection_respondents
               SET status='Returned for Update',updated_at=?
               WHERE id=? AND visa_case_id=?""",
            (stamp, respondent["id"], case["id"]),
        )
        return self.toast_redirect(
            self.visa_case_return_path(student_id, case_id, "info_collection", "applicant-information-collection"),
            "表单已退回修改，原草稿和提交内容已保留。",
            "success",
            "Applicant Information",
        )

    def visa_information_collection_token_row(self, token):
        row = db.one(
            """SELECT r.*,p.status package_status,p.visa_case_id package_case_id
               FROM visa_information_collection_respondents r
               JOIN visa_information_collection_packages p ON p.id=r.package_id
               WHERE r.token=?""",
            (token,),
        )
        if row and (not row["token_created_at"] or not row["expires_at"]):
            token_created_at = row["token_created_at"] or row["created_at"] or self.visa_information_collection_now_utc()
            expires_at = row["expires_at"] or self.visa_information_collection_expiry_from(token_created_at)
            db.execute(
                """UPDATE visa_information_collection_respondents
                   SET token_created_at=?,expires_at=?
                   WHERE id=?""",
                (token_created_at, expires_at, row["id"]),
            )
            row = db.one(
                """SELECT r.*,p.status package_status,p.visa_case_id package_case_id
                   FROM visa_information_collection_respondents r
                   JOIN visa_information_collection_packages p ON p.id=r.package_id
                   WHERE r.token=?""",
                (token,),
            )
        return row

    def visa_information_collection_assignment_draft_text(self, assignment_id):
        draft = db.one("SELECT * FROM visa_form_drafts WHERE assignment_id=?", (assignment_id,))
        if not draft:
            return ""
        try:
            payload = json.loads(draft["draft_json"] or "{}")
        except Exception:
            payload = {}
        return str(payload.get("generic_draft") or "")

