    def visa_aic_500_case_context(self, respondent):
        case = None
        student = None
        if respondent:
            case = db.one("SELECT * FROM visa_cases WHERE id=?", (respondent["visa_case_id"],))
            if case:
                student = db.one("SELECT * FROM students WHERE student_id=?", (case["student_id"],))
        return case, student

    def visa_aic_500_is_student_500_case(self, respondent):
        case, _student = self.visa_aic_500_case_context(respondent)
        if not case:
            return False
        visa_type = str(case["visa_type"] or "").lower()
        return "500" in visa_type and "590" not in visa_type and "guardian" not in visa_type

    def visa_aic_500_student_profile_values(self, respondent):
        _case, student = self.visa_aic_500_case_context(respondent)
        if not student:
            return {"applicant_name": "", "birth_date": "", "gender": "", "missing": ["学生档案"]}
        first = str(student["passport_first_name"] or "").strip()
        last = str(student["passport_last_name"] or "").strip()
        name = " ".join(part for part in (first, last) if part).strip() or str(student["student_id"] or "").strip()
        birth_date = display_date_value(student["date_of_birth"] or "")
        gender = str(student["gender"] or "").strip()
        missing = []
        if not birth_date:
            missing.append("出生日期")
        if not gender:
            missing.append("性别")
        return {"applicant_name": name, "birth_date": birth_date, "gender": gender, "missing": missing}

    def visa_aic_500_empty_payload(self, assignment=None):
        sections = {}
        section_confirmed = {}
        for key, _label, _desc in self.visa_aic_500_sections():
            if key in {"overview", "submit"}:
                continue
            sections[key] = {}
            section_confirmed[key] = False
        for section, fields in self.visa_aic_500_scalar_fields().items():
            sections.setdefault(section, {})
            section_confirmed.setdefault(section, False)
            for name, _label, field_type in fields:
                sections[section].setdefault(name, "" if field_type != "checkbox" else "")
        for group, config in self.visa_aic_500_repeat_groups().items():
            sections.setdefault(config["section"], {})
            section_confirmed.setdefault(config["section"], False)
            sections[config["section"]].setdefault(group, [])
        return {
            "form_type": "visa_application_info_500_590_485",
            "template_version": assignment["template_version"] if assignment else "2026(7)",
            "sections": sections,
            "section_confirmed": section_confirmed,
        }

    def visa_aic_500_apply_student_profile_prefill(self, payload, respondent):
        if not self.visa_aic_500_is_student_500_case(respondent):
            return payload
        profile = self.visa_aic_500_student_profile_values(respondent)
        applicants = dict(payload["sections"].get("applicants") or {})
        applicants["applicant_name"] = profile["applicant_name"]
        applicants["birth_date"] = profile["birth_date"]
        applicants["gender"] = profile["gender"]
        payload["sections"]["applicants"] = applicants
        return payload

    def visa_aic_500_assignment_draft(self, assignment):
        existing = db.one("SELECT * FROM visa_form_drafts WHERE assignment_id=?", (assignment["id"],))
        payload = self.visa_aic_500_empty_payload(assignment)
        if existing:
            try:
                loaded = json.loads(existing["draft_json"] or "{}")
                if isinstance(loaded, dict):
                    if "sections" in loaded and isinstance(loaded.get("sections"), dict):
                        for key, value in loaded["sections"].items():
                            if isinstance(value, dict):
                                payload["sections"].setdefault(key, {})
                                payload["sections"][key].update(value)
                        if isinstance(loaded.get("section_confirmed"), dict):
                            for key, value in loaded["section_confirmed"].items():
                                if key in payload["section_confirmed"]:
                                    payload["section_confirmed"][key] = bool(value)
                    else:
                        payload["legacy_generic_draft"] = loaded.get("generic_draft", "")
            except Exception:
                pass
        return existing, payload

    def visa_aic_500_date_field_names(self):
        names = {"birth_date", "marriage_or_de_facto_date", "first_arrival_australia_date", "from_date", "to_date"}
        for config in self.visa_aic_500_repeat_groups().values():
            for field, _label, field_type in config["fields"]:
                if field_type == "date" or field.endswith("_date"):
                    names.add(field)
        return names

    def visa_aic_500_normalize_date_value(self, value):
        text = str(value or "").strip()
        compact = re.sub(r"\D", "", text)
        if len(compact) == 8 and text == compact:
            return f"{compact[:2]}/{compact[2:4]}/{compact[4:]}"
        return text

    def visa_aic_500_strict_date_ok(self, value):
        text = str(value or "").strip()
        if not text:
            return True
        if not re.match(r"^\d{2}/\d{2}/\d{4}$", text):
            return False
        try:
            datetime.strptime(text, "%d/%m/%Y")
            return True
        except Exception:
            return False

    def visa_aic_500_field_value(self, form, name, field_type):
        if field_type == "checkbox":
            return "yes" if form_text_value(form, name).lower() in {"on", "yes", "true", "1", "是"} else ""
        value = form_text_value(form, name)
        if field_type == "date" or name in self.visa_aic_500_date_field_names():
            return self.visa_aic_500_normalize_date_value(value)
        return value

    def visa_aic_500_collect_repeat_rows(self, form, group, fields, existing_rows):
        prefix = f"{group}__"
        has_group_input = any(str(key).startswith(prefix) for key in form.keys())
        if not has_group_input:
            return list(existing_rows or [])
        row_numbers = set()
        for key in form.keys():
            parts = str(key).split("__")
            if len(parts) == 3 and parts[0] == group and parts[1].isdigit():
                row_numbers.add(int(parts[1]))
        rows = []
        for index in sorted(row_numbers):
            row = {}
            for field, _label, field_type in fields:
                row[field] = self.visa_aic_500_field_value(form, f"{group}__{index}__{field}", field_type)
            if any(str(value or "").strip() for value in row.values()):
                rows.append(row)
            else:
                rows.append(row)
        return rows

    def visa_aic_500_save_section_payload(self, payload, section, form, action):
        scalar_fields = self.visa_aic_500_scalar_fields().get(section, ())
        section_data = dict(payload["sections"].get(section) or {})
        for name, _label, field_type in scalar_fields:
            section_data[name] = self.visa_aic_500_field_value(form, name, field_type)
        for group, config in self.visa_aic_500_repeat_groups().items():
            if config["section"] != section:
                continue
            rows = self.visa_aic_500_collect_repeat_rows(form, group, config["fields"], section_data.get(group, []))
            if action == f"add_row:{group}":
                rows.append({field: "" for field, _label, _field_type in config["fields"]})
            elif action.startswith(f"remove_row:{group}:"):
                try:
                    remove_index = int(action.rsplit(":", 1)[-1])
                    rows = [row for index, row in enumerate(rows) if index != remove_index]
                except Exception:
                    pass
            section_data[group] = rows
        payload["sections"][section] = section_data
        if action in {"save_section", "save_and_next", "save_and_prev"}:
            payload.setdefault("section_confirmed", {})[section] = True
        return payload

    def visa_aic_500_payload_has_value(self, value):
        if isinstance(value, dict):
            return any(self.visa_aic_500_payload_has_value(item) for item in value.values())
        if isinstance(value, list):
            return any(self.visa_aic_500_payload_has_value(item) for item in value)
        return bool(str(value or "").strip())

    def visa_aic_500_progress(self, payload):
        section_keys = [key for key, _label, _desc in self.visa_aic_500_sections() if key not in {"overview", "submit"}]
        completed = sum(1 for key in section_keys if self.visa_aic_500_section_is_confirmed(payload, key))
        return int(round((completed / max(1, len(section_keys))) * 100))

    def visa_aic_500_section_is_confirmed(self, payload, section):
        confirmed = payload.get("section_confirmed") or {}
        if bool(confirmed.get(section)):
            return True
        return self.visa_aic_500_payload_has_value((payload.get("sections") or {}).get(section, {}))

    def visa_aic_500_unconfirmed_sections(self, payload):
        missing = []
        for key, label, _desc in self.visa_aic_500_sections():
            if key in {"overview", "submit"}:
                continue
            if not self.visa_aic_500_section_is_confirmed(payload, key):
                missing.append((key, label))
        return missing

    def visa_aic_500_upsert_draft(self, assignment, respondent, payload, status="Draft", submitted=False):
        stamp = now_iso()
        is_submitted_record = submitted or status == "Submitted" or str(assignment["status"] or "") == "Submitted"
        status = "Submitted" if is_submitted_record else status
        progress = 100 if is_submitted_record else self.visa_aic_500_progress(payload)
        draft_json = json.dumps(payload, ensure_ascii=False)
        existing = db.one("SELECT * FROM visa_form_drafts WHERE assignment_id=?", (assignment["id"],))
        submitted_at = stamp if submitted else None
        if existing:
            db.execute(
                """UPDATE visa_form_drafts
                   SET draft_json=?,status=?,progress_percent=?,last_saved_at=?,submitted_at=COALESCE(?,submitted_at),updated_at=?
                   WHERE assignment_id=?""",
                (draft_json, status, progress, stamp, submitted_at, stamp, assignment["id"]),
            )
        else:
            db.execute(
                """INSERT INTO visa_form_drafts(
                   assignment_id,respondent_id,visa_case_id,draft_json,status,progress_percent,last_saved_at,submitted_at,created_at,updated_at)
                   VALUES(?,?,?,?,?,?,?,?,?,?)""",
                (assignment["id"], respondent["id"], respondent["visa_case_id"], draft_json, status, progress, stamp, submitted_at, stamp, stamp),
            )
        db.execute(
            """UPDATE visa_form_assignments
               SET status=?,progress_percent=?,last_saved_at=?,submitted_at=COALESCE(?,submitted_at),updated_at=?
               WHERE id=?""",
            (status, progress, stamp, submitted_at, stamp, assignment["id"]),
        )
        self.visa_information_collection_update_respondent_summary(respondent)
        return stamp, progress

    def visa_aic_500_review_errors(self, payload):
        sections = payload.get("sections") or {}
        errors = []
        for _key, label in self.visa_aic_500_unconfirmed_sections(payload):
            errors.append(f"请先确认：{label}")
        date_field_names = self.visa_aic_500_date_field_names()
        def check_dates(value, key_name=""):
            if isinstance(value, dict):
                for key, item in value.items():
                    check_dates(item, key)
            elif isinstance(value, list):
                for item in value:
                    check_dates(item, key_name)
            elif isinstance(value, str):
                text = value.strip()
                if key_name in date_field_names and text and not self.visa_aic_500_strict_date_ok(text):
                    errors.append("日期格式请使用 DD/MM/YYYY，例如 10/05/1990。")
        for section in sections.values():
            check_dates(section)
        return list(dict.fromkeys(errors))

    def visa_aic_500_section_status(self, payload, section):
        if section == "overview":
            return "—"
        if section == "submit":
            return "已完成" if not self.visa_aic_500_review_errors(payload) else "未确认"
        has_value = self.visa_aic_500_payload_has_value(payload["sections"].get(section, {}))
        confirmed = bool((payload.get("section_confirmed") or {}).get(section))
        if confirmed and has_value:
            return "已完成"
        if confirmed:
            return "已确认无相关信息"
        if has_value:
            return "已保存"
        return "未确认"

    def visa_aic_500_admin_content_html(self, assignment, payload):
        scalar_fields = self.visa_aic_500_scalar_fields()
        repeat_groups = self.visa_aic_500_repeat_groups()

        def value_line(label, value):
            text = str(value or "").strip() or "—"
            return f"<div class='visa-information-content-field'><span>{esc(label)}</span><strong>{esc(text)}</strong></div>"

        def repeat_block(group, config, rows):
            rendered_rows = []
            for index, row in enumerate(rows or []):
                cells = "".join(value_line(label, (row or {}).get(field, "")) for field, label, _field_type in config["fields"])
                rendered_rows.append(
                    f"""
                    <article class="visa-information-content-row">
                      <h5>{esc(config["label"])} {index + 1}</h5>
                      <div class="visa-information-content-grid">{cells}</div>
                    </article>
                    """
                )
            intro = f"<p class='muted-line'>{esc(config.get('intro') or '')}</p>" if config.get("intro") else ""
            empty = "<p class='muted-line'>暂无记录。</p>" if not rendered_rows else ""
            return f"<section class='visa-information-content-repeat'><h4>{esc(config['label'])}</h4>{intro}{empty}{''.join(rendered_rows)}</section>"

        sections_html = []
        sections = payload.get("sections") or {}
        for section_key, section_label, _desc in self.visa_aic_500_sections():
            if section_key in {"overview", "submit"}:
                continue
            section_data = sections.get(section_key) or {}
            blocks = []
            if section_key == "visa" and "other_passports" in repeat_groups:
                config = repeat_groups["other_passports"]
                blocks.append(repeat_block("other_passports", config, section_data.get("other_passports", [])))
            scalar_html = "".join(value_line(label, section_data.get(name, "")) for name, label, _field_type in scalar_fields.get(section_key, ()))
            if scalar_html:
                blocks.append(f"<div class='visa-information-content-grid'>{scalar_html}</div>")
            for group, config in repeat_groups.items():
                if section_key == "visa" and group == "other_passports":
                    continue
                if config["section"] == section_key:
                    blocks.append(repeat_block(group, config, section_data.get(group, [])))
            sections_html.append(
                f"""
                <section class="panel visa-information-content-section">
                  <h3>{esc(section_label)}</h3>
                  {''.join(blocks) if blocks else '<p class="muted-line">暂无内容。</p>'}
                </section>
                """
            )
        return f"""
        <section class="panel visa-information-content-form" id="assignment-{esc(assignment['id'])}">
          <div class="panel-head"><div>
            <h2>{esc(self.visa_information_collection_form_type_label(assignment["form_type"]))}</h2>
            <p>模板版本：{esc(assignment["template_version"] or "")} · 状态：{esc(self.visa_information_collection_status_label(assignment["status"] or "Not Started"))} · 完成度：{esc(assignment["progress_percent"] or 0)}%</p>
          </div></div>
        </section>
        {''.join(sections_html)}
        """

    def visa_information_collection_form_wizard_entry(self, method, token, form_type):
        return self.visa_information_collection_form_wizard(method, token, form_type, "overview")

    def visa_information_collection_placeholder_form_page(self, method, token, form_type):
        respondent = self.visa_information_collection_token_row(token)
        problem = self.visa_information_collection_token_problem(respondent)
        if problem:
            return self.visa_information_collection_public_page(
                "链接已失效",
                f"<section class='panel'><h1>链接已失效</h1><p>{esc(problem)}</p></section>",
                HTTPStatus.GONE,
            )
        if method not in {"GET", "POST"}:
            return self.visa_information_collection_public_page(
                "Method Not Allowed",
                "<section class='panel'><h1>Method Not Allowed</h1></section>",
                HTTPStatus.METHOD_NOT_ALLOWED,
            )
        if not self.visa_information_collection_cookie_valid(respondent):
            self.visa_information_collection_record_log(respondent, "wechat_required", metadata={"method": method, "form_type": form_type})
            return self.visa_information_collection_login_required_page(token, respondent)
        allowed_form_types = {value for value, _label, _version in self.visa_information_collection_form_types()}
        if form_type not in allowed_form_types:
            return self.visa_information_collection_public_page(
                "未分配表单",
                "<section class='panel'><h1>未找到对应表单</h1><p>请联系顾问确认当前信息采集链接。</p></section>",
                HTTPStatus.NOT_FOUND,
            )
        assignment = db.one(
            """SELECT * FROM visa_form_assignments
               WHERE respondent_id=? AND visa_case_id=? AND form_type=? AND status<>'Cancelled'
               ORDER BY id LIMIT 1""",
            (respondent["id"], respondent["visa_case_id"], form_type),
        )
        if not assignment:
            return self.visa_information_collection_public_page(
                "未分配表单",
                "<section class='panel'><h1>当前链接未分配此表单</h1><p>请返回表单列表或联系顾问确认。</p></section>",
                HTTPStatus.NOT_FOUND,
            )
        note = self.visa_information_collection_form_note(form_type)
        note_html = f"<div class='notice'>{esc(note)}</div>" if note else ""
        body = f"""
        <main class="public-page visa-information-public-page">
          <section class="panel">
            <h1>{esc(self.visa_information_collection_form_type_label(form_type))}</h1>
            <p>当前状态：{esc(self.visa_information_collection_status_label(assignment["status"] or "Not Started"))}</p>
            <p>当前完成度：{esc(assignment["progress_percent"] or 0)}% · 最后保存时间：{esc(self.visa_information_collection_display_datetime(assignment["last_saved_at"]))}</p>
            {note_html}
            <div class="notice error">系统缺少该表单 Word 模板，请联系顾问配置。</div>
            <div class="share-actions">
              <a class="secondary button-link" href="/visa-information-collection/{esc(token)}">返回表单列表</a>
            </div>
          </section>
        </main>
        """
        self.visa_information_collection_record_log(respondent, "placeholder_form_opened", metadata={"form_type": form_type})
        return self.visa_information_collection_public_page(self.visa_information_collection_form_type_label(form_type), body)

    def visa_information_collection_form_wizard(self, method, token, form_type, section):
        if form_type != "visa_application_info_500_590_485":
            return self.visa_information_collection_structured_form_page(method, token, form_type, section)
        section = section if section in self.visa_aic_500_section_labels() else "overview"
        respondent = self.visa_information_collection_token_row(token)
        problem = self.visa_information_collection_token_problem(respondent)
        if problem:
            return self.visa_information_collection_public_page(
                "链接已失效",
                f"<section class='panel'><h1>链接已失效</h1><p>{esc(problem)}</p></section>",
                HTTPStatus.GONE,
            )
        if method not in {"GET", "POST"}:
            return self.visa_information_collection_public_page(
                "Method Not Allowed",
                "<section class='panel'><h1>Method Not Allowed</h1></section>",
                HTTPStatus.METHOD_NOT_ALLOWED,
            )
        if not self.visa_information_collection_cookie_valid(respondent):
            self.visa_information_collection_record_log(respondent, "wechat_required", metadata={"method": method, "form_type": form_type, "section": section})
            return self.visa_information_collection_login_required_page(token, respondent)
        assignment = db.one(
            """SELECT * FROM visa_form_assignments
               WHERE respondent_id=? AND visa_case_id=? AND form_type=? AND status<>'Cancelled'
               ORDER BY id LIMIT 1""",
            (respondent["id"], respondent["visa_case_id"], form_type),
        )
        if not assignment:
            return self.visa_information_collection_public_page(
                "未分配表单",
                "<section class='panel'><h1>当前链接未分配 500/590/485 签证申请信息表</h1><p>请联系顾问确认表单分配。</p></section>",
                HTTPStatus.NOT_FOUND,
            )
        _draft, payload = self.visa_aic_500_assignment_draft(assignment)
        payload = self.visa_aic_500_apply_student_profile_prefill(payload, respondent)
        message = ""
        errors = []
        readonly_statuses = {"Locked"}
        readonly = str(respondent["status"] or "") in readonly_statuses or str(assignment["status"] or "") in readonly_statuses
        if method == "POST":
            form = getattr(self, "form", None)
            if form is None:
                form, _files = parse_request_body(self)
                self.form = form
            query_action = ""
            try:
                query_action = (self.query.get("aic_action") or [""])[0]
            except Exception:
                query_action = ""
            action = form_text_value(form, "aic_action") or query_action or "save_section"
            if readonly:
                message = "此表单已锁定，如需修改请联系顾问。"
            elif section == "submit" and action == "submit_final":
                errors = self.visa_aic_500_review_errors(payload)
                if errors:
                    message = "提交失败，请检查以下信息："
                else:
                    stamp, _progress = self.visa_aic_500_upsert_draft(assignment, respondent, payload, "Submitted", submitted=True)
                    assignment = db.one("SELECT * FROM visa_form_assignments WHERE id=?", (assignment["id"],))
                    respondent = db.one("SELECT * FROM visa_information_collection_respondents WHERE id=?", (respondent["id"],))
                    message = "已提交，请等待顾问审核"
            elif section not in {"overview", "submit"}:
                payload = self.visa_aic_500_save_section_payload(payload, section, form, action)
                payload = self.visa_aic_500_apply_student_profile_prefill(payload, respondent)
                save_status = "Submitted" if str(assignment["status"] or "") == "Submitted" else "Draft"
                stamp, _progress = self.visa_aic_500_upsert_draft(assignment, respondent, payload, save_status, submitted=False)
                if action in {"save_and_next", "save_and_prev"}:
                    previous_key, next_key = self.visa_aic_500_section_adjacent(section)
                    target = next_key if action == "save_and_next" else previous_key
                    target = target or "overview"
                    return self.redirect(f"/visa-information-collection/{quote(token)}/forms/visa_application_info_500_590_485/{quote(target)}")
                if action.startswith("add_row:") or action.startswith("remove_row:"):
                    return self.redirect(f"/visa-information-collection/{quote(token)}/forms/visa_application_info_500_590_485/{quote(section)}")
                assignment = db.one("SELECT * FROM visa_form_assignments WHERE id=?", (assignment["id"],))
                respondent = db.one("SELECT * FROM visa_information_collection_respondents WHERE id=?", (respondent["id"],))
                message = f"已保存，最后保存时间：{esc(self.visa_information_collection_display_datetime(stamp))}"
        body = self.visa_aic_500_wizard_html(token, respondent, assignment, payload, section, message, errors, readonly)
        self.visa_information_collection_record_log(respondent, "aic_500_wizard_opened", metadata={"section": section, "method": method})
        return self.visa_information_collection_public_page("500/590/485 签证申请信息表", body)

    def visa_aic_500_nav_html(self, token, current_section):
        labels = self.visa_aic_500_section_labels()
        links = []
        for key, _label, _desc in self.visa_aic_500_sections():
            active = " active" if key == current_section else ""
            links.append(f'<a class="aic-step-link{active}" href="/visa-information-collection/{esc(token)}/forms/visa_application_info_500_590_485/{esc(key)}">{esc(labels[key])}</a>')
        return '<nav class="aic-step-nav">' + "".join(links) + "</nav>"

    def visa_aic_500_section_adjacent(self, current_section):
        section_order = [key for key, _label, _desc in self.visa_aic_500_sections()]
        try:
            index = section_order.index(current_section)
        except ValueError:
            index = 0
        previous_key = section_order[index - 1] if index > 0 else ""
        next_key = section_order[index + 1] if index + 1 < len(section_order) else ""
        return previous_key, next_key

    def visa_aic_500_prev_next_html(self, token, current_section, post_buttons=False):
        previous_key, next_key = self.visa_aic_500_section_adjacent(current_section)
        links = [f'<a class="secondary button-link" href="/visa-information-collection/{esc(token)}/forms/visa_application_info_500_590_485/overview">返回概览</a>']
        if previous_key:
            if post_buttons:
                links.append(f'<button class="secondary" type="submit" name="aic_action" value="save_and_prev" formaction="/visa-information-collection/{esc(token)}/forms/visa_application_info_500_590_485/{esc(current_section)}?aic_action=save_and_prev">上一页</button>')
            else:
                links.append(f'<a class="secondary button-link" href="/visa-information-collection/{esc(token)}/forms/visa_application_info_500_590_485/{esc(previous_key)}">上一页</a>')
        if next_key:
            if post_buttons:
                links.append(f'<button class="secondary" type="submit" name="aic_action" value="save_and_next" formaction="/visa-information-collection/{esc(token)}/forms/visa_application_info_500_590_485/{esc(current_section)}?aic_action=save_and_next">下一页</button>')
            else:
                links.append(f'<a class="secondary button-link" href="/visa-information-collection/{esc(token)}/forms/visa_application_info_500_590_485/{esc(next_key)}">下一页</a>')
        return '<div class="share-actions aic-wizard-nav-actions">' + "".join(links) + "</div>"

    def visa_aic_500_input_html(self, name, label, field_type, value, readonly=False):
        safe_value = esc(value or "")
        if readonly:
            return f"<div class='aic-field-readonly'><span>{esc(label)}</span><strong>{safe_value or '—'}</strong></div>"
        if field_type == "textarea":
            return f'<label>{esc(label)}<textarea name="{esc(name)}" rows="4">{safe_value}</textarea></label>'
        if field_type == "checkbox":
            checked = " checked" if str(value or "").strip() else ""
            return f'<label class="aic-check"><input type="checkbox" name="{esc(name)}" value="on"{checked}> {esc(label)}</label>'
        if field_type == "select":
            if name == "gender" or str(name).endswith("__gender"):
                options = (("男", "男 / Male"), ("女", "女 / Female"), ("其他", "其他 / Other"))
            else:
                options = (("", ""),)
            option_html = "".join(
                f'<option value="{esc(option_value)}"{" selected" if str(value or "") == option_value else ""}>{esc(option_label)}</option>'
                for option_value, option_label in options
            )
            return f'<label>{esc(label)}<select name="{esc(name)}"><option value="">请选择</option>{option_html}</select></label>'
        date_hint = " placeholder='DD/MM/YYYY，例如 10/05/1990' inputmode='numeric'" if field_type == "date" else ""
        return f'<label>{esc(label)}<input name="{esc(name)}" value="{safe_value}"{date_hint}></label>'

    def visa_aic_500_repeat_html(self, token, section, group, config, rows, readonly=False):
        section_action_url = f"/visa-information-collection/{esc(token)}/forms/visa_application_info_500_590_485/{esc(section)}"
        rendered_rows = []
        for index, row in enumerate(rows or []):
            cells = []
            for field, label, field_type in config["fields"]:
                input_name = f"{group}__{index}__{field}"
                cells.append(self.visa_aic_500_input_html(input_name, label, field_type, (row or {}).get(field, ""), readonly))
            remove_action = f"remove_row:{group}:{index}"
            remove_button = "" if readonly else f'<button class="secondary" type="submit" name="aic_action" value="{esc(remove_action)}" formaction="{section_action_url}?aic_action={quote(remove_action)}">删除此行</button>'
            rendered_rows.append(
                f"""
                <article class="aic-repeat-card" style="border:1px solid #d7dee8;border-radius:14px;padding:14px;margin:12px 0;background:#fff;">
                  <h4 style="margin:0 0 10px;font-size:1.05rem;">{esc(config['label'])} {index + 1}</h4>
                  <div class="aic-repeat-row">{''.join(cells)}{remove_button}</div>
                </article>
                """
            )
        add_action = f"add_row:{group}"
        add_button = "" if readonly else f'<button class="secondary" type="submit" name="aic_action" value="{esc(add_action)}" formaction="{section_action_url}?aic_action={quote(add_action)}">新增{esc(config["label"])}</button>'
        empty = "<p class='muted-line'>暂无记录，可点击新增。</p>" if not rendered_rows else ""
        intro = f"<p class='muted-line'>{esc(config.get('intro') or '')}</p>" if config.get("intro") else ""
        return f"<section class='aic-repeat-group'><h3>{esc(config['label'])}</h3>{intro}{empty}{''.join(rendered_rows)}{add_button}</section>"

    def visa_aic_500_section_form_html(self, token, respondent, assignment, payload, section, readonly=False):
        labels = self.visa_aic_500_section_labels()
        section_data = payload["sections"].get(section, {})
        fields_html = []
        student_profile_notice = ""
        student_profile_missing_notice = ""
        optional_hints = {
            "contact": "如果没有其他联系方式或地址补充，可以直接点击保存本页或下一页，系统会记录为已确认无相关信息。",
            "visa": "如果没有其他护照、过往签证或特殊签证情况，可以直接点击保存本页或下一页，系统会记录为已确认无相关信息。",
            "study_work": "如果没有学习或工作经历需要填写，可以直接点击保存本页或下一页，系统会记录为已确认无相关信息。",
            "travel": "如果过去十年没有相关访问记录，可以直接点击保存本页或下一页，系统会记录为已确认无相关信息。",
            "family": "家庭成员类别可为空；如果某类没有相关成员，保存本页后系统会记录为已确认。",
        }
        optional_hint = f"<div class='notice'>{esc(optional_hints[section])}</div>" if section in optional_hints else ""
        profile = self.visa_aic_500_student_profile_values(respondent)
        student_profile_fields_readonly = self.visa_aic_500_is_student_500_case(respondent)
        if section == "applicants" and student_profile_fields_readonly:
            student_profile_notice = "<div class='notice'>以上信息来自学生档案，如需修改请联系顾问。</div>"
            if profile["missing"]:
                student_profile_missing_notice = f"<div class='notice warn'>学生档案暂无该信息，请联系顾问补充：{esc('、'.join(profile['missing']))}。</div>"
        if section == "visa":
            config = self.visa_aic_500_repeat_groups().get("other_passports")
            if config:
                fields_html.append(self.visa_aic_500_repeat_html(token, section, "other_passports", config, section_data.get("other_passports", []), readonly))
        for name, label, field_type in self.visa_aic_500_scalar_fields().get(section, ()):
            field_readonly = readonly or (student_profile_fields_readonly and section == "applicants" and name in {"applicant_name", "birth_date", "gender"})
            fields_html.append(self.visa_aic_500_input_html(name, label, field_type, section_data.get(name, ""), field_readonly))
        for group, config in self.visa_aic_500_repeat_groups().items():
            if section == "visa" and group == "other_passports":
                continue
            if config["section"] == section:
                fields_html.append(self.visa_aic_500_repeat_html(token, section, group, config, section_data.get(group, []), readonly))
        buttons = "" if readonly else "<button class='primary' type='submit' name='aic_action' value='save_section'>保存本页</button>"
        nav_actions = self.visa_aic_500_prev_next_html(token, section, post_buttons=not readonly)
        return f"""
        <form method="post" action="/visa-information-collection/{esc(token)}/forms/visa_application_info_500_590_485/{esc(section)}" class="aic-section-form">
          <input type="hidden" name="assignment_id" value="{esc(assignment['id'])}">
          <div class="aic-section-head"><h2>{esc(labels[section])}</h2><p>本页保存只会更新当前分区，不会覆盖其他分区。</p></div>
          {student_profile_notice}
          {student_profile_missing_notice}
          {optional_hint}
          <div class="aic-field-grid">{''.join(fields_html)}</div>
          <div class="share-actions">{buttons}</div>
          {nav_actions}
        </form>
        """

    def visa_aic_500_overview_html(self, token, payload):
        cards = []
        missing_sections = self.visa_aic_500_unconfirmed_sections(payload)
        missing_html = ""
        if self.visa_aic_500_progress(payload) < 100 and missing_sections:
            missing_html = "<section class='aic-missing-section-list'><h3>还需要完成 / 确认以下部分：</h3>" + "".join(
                f"""
                <article class="aic-missing-section-card">
                  <strong>{esc(label)}</strong>
                  <a class="secondary button-link" href="/visa-information-collection/{esc(token)}/forms/visa_application_info_500_590_485/{esc(key)}">去确认</a>
                </article>
                """
                for key, label in missing_sections
            ) + "</section>"
        for key, label, desc in self.visa_aic_500_sections():
            if key == "overview":
                continue
            status = self.visa_aic_500_section_status(payload, key)
            button_label = "进入填写"
            cards.append(
                f"""
                <article class="aic-overview-section-card" style="display:block;width:100%;box-sizing:border-box;border:1px solid #d7dee8;border-radius:14px;padding:16px;margin:12px 0;background:#fff;">
                  <h3 style="margin:0 0 6px;font-size:1.15rem;">{esc(label)}</h3>
                  <p style="margin:0 0 10px;color:#697386;line-height:1.45;">{esc(desc)}</p>
                  <p style="margin:0 0 12px;font-weight:800;">状态：{esc(status)}</p>
                  <a class="primary button-link aic-overview-enter" style="display:block;width:100%;box-sizing:border-box;text-align:center;min-height:46px;padding:12px 14px;border-radius:12px;" href="/visa-information-collection/{esc(token)}/forms/visa_application_info_500_590_485/{esc(key)}">{esc(button_label)}</a>
                </article>
                """
            )
        return f"{missing_html}<section class='aic-overview-card-list' style='display:block;width:100%;'>{''.join(cards)}</section>"

    def visa_aic_500_submit_html(self, token, assignment, payload, readonly=False):
        labels = self.visa_aic_500_section_labels()
        rows = []
        missing_sections = self.visa_aic_500_unconfirmed_sections(payload)
        missing_html = ""
        progress = self.visa_aic_500_progress(payload)
        is_complete = progress >= 100 and not missing_sections
        if not is_complete and missing_sections:
            missing_html = "<section class='aic-missing-section-list'><h3>当前表单尚未完成，不能递交。</h3><p>请先完成 / 确认以下部分：</p>" + "".join(
                f"""
                <article class="aic-missing-section-card">
                  <strong>{esc(label)}</strong>
                  <a class="secondary button-link" href="/visa-information-collection/{esc(token)}/forms/visa_application_info_500_590_485/{esc(key)}">去确认</a>
                </article>
                """
                for key, label in missing_sections
            ) + "</section>"
        for key, label, _desc in self.visa_aic_500_sections():
            if key in {"overview", "submit"}:
                continue
            status = self.visa_aic_500_section_status(payload, key)
            rows.append(
                f"""
                <article class="aic-review-section-card">
                  <div><strong>{esc(label)}</strong><span>状态：{esc(status)}</span></div>
                  <a class="secondary button-link" href="/visa-information-collection/{esc(token)}/forms/visa_application_info_500_590_485/{esc(key)}">查看</a>
                </article>
                """
            )
        submit_action = f"/visa-information-collection/{esc(token)}/forms/visa_application_info_500_590_485/submit"
        if readonly:
            submit_button = ""
        elif not is_complete:
            submit_button = '<button class="primary" type="button" disabled aria-disabled="true">确认提交</button>'
        else:
            submit_button = f'<button class="primary" type="submit" name="aic_action" value="submit_final" formaction="{submit_action}?aic_action=submit_final">确认提交</button>'
        nav_actions = self.visa_aic_500_prev_next_html(token, "submit")
        return f"""
        <section class="aic-review-panel">
          <h2>{esc(labels['submit'])}</h2>
          <p>核对以上信息。</p>
          {missing_html}
          <div class="aic-review-section-list">{''.join(rows)}</div>
          <form method="post" action="{submit_action}" class="aic-submit-form">
            <input type="hidden" name="assignment_id" value="{esc(assignment['id'])}">
            <div class="share-actions"><a class="secondary button-link" href="/visa-information-collection/{esc(token)}/forms/visa_application_info_500_590_485/overview">保存</a>{submit_button}</div>
          </form>
          {nav_actions}
        </section>
        """

    def visa_aic_500_wizard_html(self, token, respondent, assignment, payload, section, message="", errors=None, readonly=False):
        labels = self.visa_aic_500_section_labels()
        progress = 100 if str(assignment["status"] or respondent["status"] or "") == "Submitted" else self.visa_aic_500_progress(payload)
        status_label = self.visa_information_collection_status_label(assignment["status"] or respondent["status"] or "Not Started")
        readonly_note = ""
        completed_edit_note = ""
        if readonly:
            readonly_note = "<div class='notice'>此表单已锁定，如需修改请联系顾问。</div>" if str(respondent["status"] or "") == "Locked" or str(assignment["status"] or "") == "Locked" else "<div class='notice'>已提交，请等待顾问审核</div>"
        elif str(assignment["status"] or "") == "Submitted":
            completed_edit_note = "<div class='notice success'>已完成，可继续修改。保存后系统会保留已提交状态。</div>"
        message_html = f"<div class='notice success'>{esc(message)}</div>" if message else ""
        error_html = ""
        if errors:
            error_html = "<div class='notice error'><strong>提交前请修正：</strong><ul>" + "".join(f"<li>{esc(item)}</li>" for item in errors) + "</ul></div>"
        if section == "overview":
            content = self.visa_aic_500_overview_html(token, payload)
        elif section == "submit":
            content = self.visa_aic_500_submit_html(token, assignment, payload, readonly)
        else:
            content = self.visa_aic_500_section_form_html(token, respondent, assignment, payload, section, readonly)
        next_assignment_prompt = self.visa_information_collection_next_assignment_prompt(token, respondent, assignment)
        style = """
        <style>
        .visa-information-public-page,.visa-aic-500-wizard,.visa-aic-500-wizard *{box-sizing:border-box}
        .visa-aic-500-wizard{max-width:1040px;width:100%;margin:0 auto;padding:16px;overflow-x:hidden}
        .visa-aic-500-wizard .panel{border-radius:14px;max-width:100%;overflow-x:hidden}
        .visa-aic-500-wizard h1,.visa-aic-500-wizard h2,.visa-aic-500-wizard h3,.visa-aic-500-wizard p,.visa-aic-500-wizard a,.visa-aic-500-wizard strong,.visa-aic-500-wizard span{overflow-wrap:anywhere;word-break:break-word}
        .aic-step-nav{display:flex;flex-wrap:wrap;gap:8px;overflow-x:hidden;padding:10px 4px;margin:8px auto 14px;max-width:1040px;width:100%}
        .aic-step-link{flex:1 1 220px;border:1px solid #d7dee8;border-radius:999px;padding:10px 14px;background:#fff;color:#172033;text-decoration:none;font-weight:700;white-space:normal;text-align:center}
        .aic-step-link.active{background:#e7f6f4;border-color:#62aaa4;color:#0f6f68}
        .aic-field-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:14px;align-items:start}
        .aic-field-grid label,.aic-repeat-row label{display:flex;flex-direction:column;gap:6px;font-weight:700;color:#5c6678}
        .aic-field-grid input,.aic-field-grid textarea,.aic-repeat-row input,.aic-repeat-row textarea{width:100%;box-sizing:border-box;border:1px solid #cfd8e3;border-radius:10px;padding:12px;font:inherit;min-height:44px;background:#fff;color:#172033}
        .aic-check{grid-column:1/-1;flex-direction:row!important;align-items:center;color:#172033!important}
        .aic-check input{width:auto!important;min-height:auto!important}
        .aic-repeat-group{grid-column:1/-1;border-top:1px solid #e4e9f0;margin-top:6px;padding-top:14px}
        .aic-repeat-row{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px;border:1px solid #e1e7ef;border-radius:12px;padding:12px;margin:10px 0;background:#fbfcfe}
        .aic-overview-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px}
        .aic-overview-card{border:1px solid #e1e7ef;border-radius:12px;padding:14px;text-decoration:none;color:#172033;background:#fff;display:flex;flex-direction:column;gap:6px}
        .aic-overview-card span{color:#697386}
        .aic-overview-card em{font-style:normal;font-weight:800;color:#0f6f68}
        .aic-field-readonly{border:1px solid #e1e7ef;border-radius:10px;padding:12px;background:#fbfcfe}
        .aic-field-readonly span{display:block;color:#697386;font-weight:700;margin-bottom:4px}
        .aic-wizard-nav-actions{margin-top:12px}
        .aic-review-section-list,.aic-missing-section-list{display:flex;flex-direction:column;gap:10px;max-width:100%;overflow-x:hidden}
        .aic-review-section-card,.aic-missing-section-card{display:flex;align-items:center;justify-content:space-between;gap:12px;border:1px solid #d7dee8;border-radius:14px;padding:12px;background:#fff;max-width:100%}
        .aic-review-section-card div{display:flex;flex-direction:column;gap:4px;min-width:0}
        .aic-review-section-card span{color:#697386;font-weight:700}
        .aic-submit-form{max-width:100%;overflow-x:hidden}
        @media (max-width:640px){
          .visa-aic-500-wizard{padding:10px;width:100%;max-width:100vw}
          .aic-field-grid,.aic-repeat-row,.aic-overview-grid{grid-template-columns:1fr}
          .aic-step-link{flex:1 1 100%;border-radius:12px}
          .aic-review-section-card,.aic-missing-section-card{align-items:stretch;flex-direction:column}
          .visa-aic-500-wizard .share-actions{display:flex;flex-direction:column;align-items:stretch;gap:10px}
          .visa-aic-500-wizard .button-link,.visa-aic-500-wizard button{width:100%;box-sizing:border-box;text-align:center;min-height:46px}
        }
        </style>
        """
        return f"""
        {style}
        <main class="public-page visa-information-public-page visa-aic-500-wizard">
          <section class="panel">
            <h1>500/590/485 签证申请信息表</h1>
            <p>分步骤填写向导 · 填写人：{esc(respondent["respondent_name"] or self.visa_information_collection_respondent_type_label(respondent["respondent_type"]))}</p>
            <p>当前状态：{esc(status_label)} · 当前完成度：{esc(progress)}% · 最后保存时间：{esc(self.visa_information_collection_display_datetime(assignment["last_saved_at"]))}</p>
            <p class="muted-line">每个分区可以单独保存。新增行和删除行均由服务器处理，手机微信端无需依赖复杂脚本。</p>
            {message_html}
            {error_html}
            {readonly_note}
            {completed_edit_note}
          </section>
          {'' if section == 'overview' else self.visa_aic_500_nav_html(token, section)}
          <section class="panel">{content}</section>
          {next_assignment_prompt}
        </main>
        """

    def visa_information_collection_public_page(self, title, body, status=200):
        return self.send_html(page(title, body, None, "", "", None), status)

    def visa_information_collection_portal(self, method, token):
        respondent = self.visa_information_collection_token_row(token)
        problem = self.visa_information_collection_token_problem(respondent)
        if problem:
            return self.visa_information_collection_public_page(
                "链接已失效",
                f"<section class='panel'><h1>链接已失效</h1><p>{esc(problem)}</p></section>",
                HTTPStatus.GONE,
            )
        if method not in {"GET", "POST"}:
            return self.visa_information_collection_public_page(
                "Method Not Allowed",
                "<section class='panel'><h1>Method Not Allowed</h1></section>",
                HTTPStatus.METHOD_NOT_ALLOWED,
            )
        if not self.visa_information_collection_cookie_valid(respondent):
            self.visa_information_collection_record_log(respondent, "wechat_required", metadata={"method": method})
            return self.visa_information_collection_login_required_page(token, respondent)
        assignments = db.all(
            """SELECT * FROM visa_form_assignments
               WHERE respondent_id=? AND visa_case_id=? AND status<>'Cancelled'
               ORDER BY id""",
            (respondent["id"], respondent["visa_case_id"]),
        )
        message = ""
        if method == "POST":
            form = getattr(self, "form", None)
            if form is None:
                form, _files = parse_request_body(self)
                self.form = form
            assignment_id = form_text_value(form, "assignment_id")
            assignment = db.one(
                """SELECT * FROM visa_form_assignments
                   WHERE id=? AND respondent_id=? AND visa_case_id=?""",
                (assignment_id, respondent["id"], respondent["visa_case_id"]),
            )
            if not assignment:
                message = "无法保存：表单不属于当前链接。"
            elif str(respondent["status"] or "") == "Locked":
                message = "此表单已锁定，如需修改请联系顾问。"
            elif assignment["status"] in {"Locked", "Expired", "Cancelled"}:
                message = "此表单已锁定，如需修改请联系顾问。" if assignment["status"] == "Locked" else "此信息填写链接已过期，请联系顾问获取新的填写链接。"
            else:
                stamp = now_iso()
                progress = self.visa_information_collection_progress_value(form_text_value(form, "progress_percent"))
                draft_payload = {"generic_draft": form_text_value(form, "generic_draft")}
                existing = db.one("SELECT * FROM visa_form_drafts WHERE assignment_id=?", (assignment["id"],))
                if existing:
                    db.execute(
                        """UPDATE visa_form_drafts
                           SET draft_json=?,status='Draft',progress_percent=?,last_saved_at=?,updated_at=?
                           WHERE assignment_id=?""",
                        (json.dumps(draft_payload, ensure_ascii=False), progress, stamp, stamp, assignment["id"]),
                    )
                else:
                    db.execute(
                        """INSERT INTO visa_form_drafts(
                           assignment_id,respondent_id,visa_case_id,draft_json,status,progress_percent,last_saved_at,created_at,updated_at)
                           VALUES(?,?,?,?,?,?,?,?,?)""",
                        (
                            assignment["id"],
                            respondent["id"],
                            respondent["visa_case_id"],
                            json.dumps(draft_payload, ensure_ascii=False),
                            "Draft",
                            progress,
                            stamp,
                            stamp,
                            stamp,
                        ),
                    )
                db.execute(
                    """UPDATE visa_form_assignments
                       SET status='Draft',progress_percent=?,last_saved_at=?,updated_at=?
                       WHERE id=?""",
                    (progress, stamp, stamp, assignment["id"]),
                )
                db.execute(
                    """UPDATE visa_information_collection_respondents
                       SET status='Draft',progress_percent=?,last_saved_at=?,updated_at=?
                       WHERE id=?""",
                    (progress, stamp, stamp, respondent["id"]),
                )
                message = f"草稿已保存。最后保存时间：{display_datetime(stamp)}"
                assignments = db.all(
                    """SELECT * FROM visa_form_assignments
                       WHERE respondent_id=? AND visa_case_id=? AND status<>'Cancelled'
                       ORDER BY id""",
                    (respondent["id"], respondent["visa_case_id"]),
                )

        overall_progress = self.visa_information_collection_overall_progress(assignments)
        rows = []
        respondent_locked = str(respondent["status"] or "") == "Locked"
        for assignment in assignments:
            note = self.visa_information_collection_form_note(assignment["form_type"])
            note_html = f"<div class='notice'>{esc(note)}</div>" if note else ""
            assignment_status = self.visa_information_collection_status_label(assignment["status"] or "Not Started")
            assignment_progress = self.visa_information_collection_progress_value(assignment["progress_percent"])
            assignment_last_saved = self.visa_information_collection_display_datetime(assignment["last_saved_at"])
            assignment_submitted = self.visa_information_collection_display_datetime(assignment["submitted_at"])
            assignment_href = self.visa_information_collection_assignment_public_href(token, assignment)
            if assignment["form_type"] == "visa_application_info_500_590_485":
                action_label = "查看已提交内容" if str(assignment["status"] or "") in {"Submitted", "Reviewed", "Locked"} else ("继续填写" if assignment_progress else "进入填写")
                form_action_html = f"""
                  <p class="muted-line">请按分区逐步填写。每个分区可单独保存，适合手机微信端继续填写。</p>
                  <div class="share-actions">
                    <a class="primary button-link" href="{esc(assignment_href)}">{esc(action_label)}</a>
                  </div>
                """
            else:
                action_label = "查看已提交内容" if str(assignment["status"] or "") in {"Submitted", "Reviewed", "Locked"} else ("继续填写" if assignment_progress else "进入填写")
                form_action_html = f"""
                  <p class="muted-line">该表单已分配，可进入填写。内容按原始 Word 模板保存，提交后顾问可在 CRM 查看、下载和修改。</p>
                  <div class="share-actions"><a class="primary button-link" href="{esc(assignment_href)}">{esc(action_label)}</a></div>
                """
            rows.append(
                f"""
                <article class="visa-information-public-assignment" id="assignment-{esc(assignment['id'])}">
                  <h2>{esc(self.visa_information_collection_form_type_label(assignment["form_type"]))}</h2>
                  <p>当前状态：{esc(assignment_status)} · 当前完成度：{esc(assignment_progress)}% · 最后保存时间：{esc(assignment_last_saved)} · 提交时间：{esc(assignment_submitted)}</p>
                  {note_html}
                  {form_action_html}
                </article>
                """
            )
        locked_note = (
            "<div class='notice'>此表单已锁定，如需修改请联系顾问。</div>"
            if respondent_locked
            else ""
        )
        self.visa_information_collection_record_log(respondent, "portal_opened", metadata={"assignment_count": len(assignments)})
        body = f"""
        <main class="public-page visa-information-public-page">
          <section class="panel">
            <h1>Applicant Information Collection / 申请人信息采集</h1>
            <h2>签证信息表填写中心</h2>
            <p>填写人：{esc(respondent["respondent_name"] or self.visa_information_collection_respondent_type_label(respondent["respondent_type"]))} · 填写人类型：{esc(self.visa_information_collection_respondent_type_label(respondent["respondent_type"]))}</p>
            <p>链接状态：{esc(self.visa_information_collection_status_label(respondent["status"] or "Not Started"))} · 整体进度：{esc(overall_progress)}% · 最后保存时间：{esc(self.visa_information_collection_display_datetime(respondent["last_saved_at"]))}</p>
            {notice("success", message)}
            {locked_note}
          </section>
          {''.join(rows) if rows else '<section class="panel"><p>当前链接暂未分配表单。</p></section>'}
        </main>
        """
        return self.visa_information_collection_public_page("Applicant Information Collection", body)

    def student_visa_case_evidence_save(self, method, student_id, case_id):
        if method != "POST":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        if not can_access_module(self.user, "visa"):
            return self.error_page("你没有访问 Visa Management 的权限。", HTTPStatus.FORBIDDEN)
        case = self.visa_material_case_or_404(student_id, case_id)
        if not case:
            return
        form = getattr(self, "form", None)
        if form is None:
            form, _files = parse_request_body(self)
            self.form = form
        fields = self.visa_evidence_field_names()
        values = {name: form_text_value(form, name) for name in fields}
        stamp = now_iso()
        existing = self.visa_evidence_profile(case["id"])
        if existing:
            assignments = ",".join(f"{name}=?" for name in fields)
            params = [values[name] for name in fields] + [stamp, case["id"]]
            db.execute(
                f"UPDATE visa_evidence_profiles SET {assignments},updated_at=? WHERE visa_case_id=?",
                params,
            )
        else:
            columns = ["visa_case_id"] + fields + ["created_at", "updated_at"]
            placeholders = ",".join("?" for _ in columns)
            params = [case["id"]] + [values[name] for name in fields] + [stamp, stamp]
            db.execute(
                f"INSERT INTO visa_evidence_profiles({','.join(columns)}) VALUES({placeholders})",
                params,
            )
        return self.flash_redirect(
            self.visa_evidence_safe_return_path(student_id, case_id, "evidence-information"),
            "Evidence / AI Review 已保存。",
        )

    def visa_material_link_document_expr(self, alias="l"):
        columns = self.visa_material_link_columns()
        if "student_document_id" in columns and "document_id" in columns:
            return f"COALESCE({alias}.student_document_id,{alias}.document_id)"
        if "student_document_id" in columns:
            return f"{alias}.student_document_id"
        return f"{alias}.document_id"

    def visa_material_match_text(self, *values):
        return " ".join(str(value or "").lower() for value in values)

    def visa_material_normalized_text(self, *values):
        return re.sub(r"[^a-z0-9]+", "", self.visa_material_match_text(*values))

    def visa_material_record_value(self, record, key, default=""):
        if isinstance(record, dict):
            return record.get(key, default)
        try:
            return record[key] if key in record.keys() else default
        except Exception:
            return default

    def visa_material_source_area(self, document):
        source_area = str(self.visa_material_record_value(document, "source_area", "") or "").strip()
        if source_area:
            return source_area
        folder_category = str(self.visa_material_record_value(document, "folder_category", "") or "").strip().lower()
        if folder_category in {"visa management", "visa"}:
            return "VISA Upload"
        if folder_category == "offer":
            return "Offer"
        if "coe" in folder_category and "oshc" in folder_category:
            return "COE+OSHC"
        if "homestay" in folder_category or "accommodation" in folder_category:
            return "Homestay"
        if folder_category in {"applications", "application"}:
            return "Application"
        return "Other"

    def visa_material_is_visa_result_receipt_item(self, item):
        material_name = str(
            self.visa_material_record_value(item, "material_name")
            or self.visa_material_record_value(item, "title")
            or ""
        )
        category = str(self.visa_material_record_value(item, "category") or "")
        item_key = str(self.visa_material_record_value(item, "item_key") or "")
        item_key_norm = self.visa_material_normalized_text(item_key)
        return (
            self.visa_material_normalized_text(material_name) == "receipt"
            and (
                self.visa_material_normalized_text(category) == "visaresults56"
                or "visaresults56receipt" in item_key_norm
            )
        )

    def visa_material_visa_receipt_match_info(self, document):
        text = self.visa_material_match_text(
            self.visa_material_record_value(document, "document_type"),
            self.visa_material_record_value(document, "original_name"),
            self.visa_material_record_value(document, "stored_name"),
        )
        text_norm = self.visa_material_normalized_text(text)
        explicit_norm_markers = {
            "visalodgementreceipt",
            "visapaymentreceipt",
            "immipaymentreceipt",
            "immireceipt",
            "visaapplicationchargereceipt",
            "immiapplicationchargereceipt",
        }
        explicit_phrase_markers = (
            "visa lodgement receipt",
            "visa payment receipt",
            "immi payment receipt",
            "immi receipt",
            "visa application charge receipt",
            "immi application charge receipt",
            "签证递交收据",
            "签证付款收据",
            "移民局付款收据",
        )
        if any(marker in text_norm for marker in explicit_norm_markers) or any(marker in text for marker in explicit_phrase_markers):
            return {"matched_reason": "explicit Visa Payment / IMMI Receipt match", "confidence": 94}
        return None

    def visa_material_document_match_info(self, document, item, student):
        material_name = str(
            self.visa_material_record_value(item, "material_name")
            or self.visa_material_record_value(item, "title")
            or ""
        )
        category = str(self.visa_material_record_value(item, "category") or "")
        material_norm = self.visa_material_normalized_text(material_name)
        category_norm = self.visa_material_normalized_text(category)
        doc_type = str(self.visa_material_record_value(document, "document_type") or "")
        doc_type_norm = self.visa_material_normalized_text(doc_type)
        file_name = " ".join(
            part for part in (
                str(self.visa_material_record_value(document, "original_name") or ""),
                str(self.visa_material_record_value(document, "stored_name") or ""),
            )
            if part
        )
        filename_text = file_name.lower()
        filename_norm = self.visa_material_normalized_text(file_name)
        source_area = self.visa_material_source_area(document)
        student_tokens = [
            token.lower()
            for token in (
                self.visa_material_record_value(student, "student_id"),
                self.visa_material_record_value(student, "passport_first_name"),
                self.visa_material_record_value(student, "passport_last_name"),
                self.visa_material_record_value(student, "preferred_name"),
            )
            if str(token or "").strip()
        ]

        def accepted(reason, confidence=90):
            return {"matched_reason": reason, "confidence": confidence}

        def filename_has_any(markers):
            return any(marker in filename_text for marker in markers)

        if self.visa_material_is_visa_result_receipt_item(item):
            return self.visa_material_visa_receipt_match_info(document)

        parent_markers = ("father", "dad", "mother", "mum", "mom", "guardian", "carer", "父亲", "爸爸", "母亲", "妈妈", "陪读", "监护")
        if material_norm == "studentpassport":
            if doc_type_norm in {"studentpassport", "passportstudent"}:
                return accepted("document_type matched Student Passport", 98)
            if doc_type_norm == "passport" and not filename_has_any(parent_markers) and (
                filename_has_any(("student", "学生", "child")) or any(token and token in filename_text for token in student_tokens)
            ):
                return accepted("generic Passport with student marker in filename", 82)
            return None
        if material_norm == "fatherpassport":
            if doc_type_norm in {"fatherpassport", "passportfather"}:
                return accepted("document_type matched Father Passport", 98)
            if doc_type_norm == "passport" and filename_has_any(("father", "dad", "父亲", "爸爸")):
                return accepted("generic Passport with father marker in filename", 82)
            return None
        if material_norm == "motherpassport":
            if doc_type_norm in {"motherpassport", "passportmother"}:
                return accepted("document_type matched Mother Passport", 98)
            if doc_type_norm == "passport" and filename_has_any(("mother", "mum", "mom", "母亲", "妈妈")):
                return accepted("generic Passport with mother marker in filename", 82)
            return None
        if material_norm == "guardianpassport":
            if doc_type_norm in {"guardianpassport", "passportguardian"}:
                return accepted("document_type matched Guardian Passport", 98)
            if doc_type_norm == "passport" and filename_has_any(("guardian", "carer", "陪读", "监护")):
                return accepted("generic Passport with guardian marker in filename", 82)
            return None
        if material_norm == "offer":
            if doc_type_norm in {"offer", "signedoffer", "offeracceptance", "offerletter", "schooloffer"}:
                return accepted("document_type matched Offer", 96)
            if source_area == "Offer" and not filename_has_any(("coe", "oshc", "caaw", "welfare")) and filename_has_any(("offer letter", "signed offer", "school offer", "offer")):
                return accepted("Offer source module with offer filename", 82)
            return None
        if material_norm == "coe":
            if doc_type_norm in {"coe", "coecaaw", "certificateofenrolment", "confirmationofenrolment"}:
                return accepted("document_type matched COE", 96)
            if source_area == "COE+OSHC" and not filename_has_any(("oshc", "overseas student health cover", "ovhc", "caaw")) and (
                filename_has_any(("certificate of enrolment", "confirmation of enrolment")) or re.search(r"\bcoe\b", filename_text)
            ):
                return accepted("COE+OSHC source module with COE filename", 82)
            return None
        if material_norm == "oshc":
            if doc_type_norm in {"oshc", "oshcreceipt", "overseasstudenthealthcover"}:
                return accepted("document_type matched OSHC", 96)
            if source_area == "COE+OSHC" and not filename_has_any(("coe", "certificate of enrolment", "confirmation of enrolment", "caaw")) and (
                "oshc" in filename_text or "overseas student health cover" in filename_text or "overseasstudenthealthcover" in filename_norm
            ):
                return accepted("COE+OSHC source module with OSHC filename", 82)
            return None
        if material_norm == "ovhc":
            if doc_type_norm in {"ovhc", "ovhcreceipt"}:
                return accepted("document_type matched OVHC", 96)
            if source_area in {"COE+OSHC", "Other"} and "ovhc" in filename_text:
                return accepted("OVHC filename marker", 80)
            return None
        if material_norm == "caawwelfareaccommodation":
            if doc_type_norm in {"caaw", "coecaaw", "welfare", "accommodation", "homestay", "homestayplacement", "homestayagreement", "letterofconfirmation"}:
                return accepted("document_type matched welfare/accommodation", 94)
            if source_area in {"COE+OSHC", "Homestay"} and filename_has_any(("caaw", "welfare", "accommodation", "homestay", "conarr", "confirmation arrangement", "confirmation of accommodation")):
                return accepted(f"{source_area} source module with welfare/accommodation filename", 82)
            return None
        if material_norm in {"notarialbirthcertificate", "birthcertificate", "notarialofbirth"}:
            if doc_type_norm in {"notarialbirthcertificate", "birthcertificate", "notarialofbirth"}:
                return accepted("document_type matched Birth Certificate", 94)
            if source_area == "Application" and filename_has_any(("birth certificate", "birth notarial", "出生公证", "出生证明")):
                return accepted("Application source with birth certificate filename", 80)
            return None
        relationship_doc_types = {
            "householdbook", "marriagecertificate", "divorcecertificate", "guardianship",
            "guardianshipcertificate", "notarialkinship", "kinshipcertificate",
        }
        if "relationship" in category_norm or material_norm in {"householdbook", "notarialkinship", "marriagecertificatedivorcecertificate", "marriagecertificatedivorcecertificateguardianship"}:
            if doc_type_norm in relationship_doc_types:
                return accepted("document_type matched relationship evidence", 92)
            if source_area == "Application" and filename_has_any(("household", "marriage", "divorce", "guardianship", "kinship", "户口", "结婚", "离婚", "监护", "亲属关系")):
                return accepted("Application source with relationship evidence filename", 80)
            return None
        if material_norm and material_norm not in {"other", "draft", "deposit", "salary", "rent", "business"}:
            if doc_type_norm == material_norm:
                return accepted("document_type exact match", 90)
            if source_area in {"Application", "Offer", "COE+OSHC", "Homestay", "Other"} and material_norm in filename_norm:
                return accepted("source filename contains material name", 76)
        return None

    def visa_material_document_matches_item(self, document, item, student):
        match_info = self.visa_material_document_match_info(document, item, student)
        if match_info:
            return True
        # Legacy fallback below stays intentionally narrow for older tests/data.
        if isinstance(item, dict):
            material_name = str(item.get("material_name") or item.get("title") or "")
        else:
            item_keys = set(item.keys())
            material_name = str((item["material_name"] if "material_name" in item_keys else "") or (item["title"] if "title" in item_keys else ""))
        material_norm = self.visa_material_normalized_text(material_name)
        doc_type_norm = self.visa_material_normalized_text(document["document_type"] if "document_type" in document.keys() else "")
        filename_text = self.visa_material_match_text(
            document["original_name"] if "original_name" in document.keys() else "",
            document["stored_name"] if "stored_name" in document.keys() else "",
        )
        filename_norm = self.visa_material_normalized_text(filename_text)
        text = self.visa_material_match_text(
            document["document_type"] if "document_type" in document.keys() else "",
            document["original_name"] if "original_name" in document.keys() else "",
            document["stored_name"] if "stored_name" in document.keys() else "",
            document["folder_category"] if "folder_category" in document.keys() else "",
        )
        text_norm = self.visa_material_normalized_text(text)
        student_tokens = [
            token.lower()
            for token in (
                student["student_id"] if "student_id" in student.keys() else "",
                student["passport_first_name"] if "passport_first_name" in student.keys() else "",
                student["passport_last_name"] if "passport_last_name" in student.keys() else "",
                student["preferred_name"] if "preferred_name" in student.keys() else "",
            )
            if str(token or "").strip()
        ]
        parent_passport_markers = ("father", "dad", "mother", "mum", "mom", "guardian", "carer", "父亲", "爸爸", "母亲", "妈妈", "陪读", "监护")

        if material_norm == "studentpassport":
            if "passport" in text and any(marker in text for marker in parent_passport_markers):
                return False
            return (
                doc_type_norm in {"studentpassport", "passportstudent"}
                or "studentpassport" in text_norm
                or ("passport" in text and any(token in text for token in student_tokens))
                or ("passport" in text and any(marker in text for marker in ("student", "学生", "child")))
            )
        if material_norm == "fatherpassport":
            return (
                doc_type_norm in {"fatherpassport", "passportfather"}
                or "fatherpassport" in text_norm
                or ("passport" in text and any(marker in text for marker in ("father", "dad", "父亲", "爸爸")))
            )
        if material_norm == "motherpassport":
            return (
                doc_type_norm in {"motherpassport", "passportmother"}
                or "motherpassport" in text_norm
                or ("passport" in text and any(marker in text for marker in ("mother", "mum", "mom", "母亲", "妈妈")))
            )
        if material_norm == "guardianpassport":
            return (
                doc_type_norm in {"guardianpassport", "passportguardian"}
                or "guardianpassport" in text_norm
                or ("passport" in text and any(marker in text for marker in ("guardian", "carer", "陪读", "监护")))
            )
        if material_norm == "offer":
            if any(marker in filename_text for marker in ("coe", "oshc", "caaw", "welfare")):
                return False
            return (
                doc_type_norm in {"offer", "signedoffer", "offerletter", "schooloffer"}
                or any(marker in filename_text for marker in ("offer letter", "signed offer", "school offer"))
                or ("offer" in filename_text and "deposit" not in filename_text)
            )
        if material_norm == "coe":
            if doc_type_norm in {"coe", "coecaaw", "certificateofenrolment", "confirmationofenrolment"}:
                return True
            if any(marker in filename_text for marker in ("oshc", "overseas student health cover", "ovhc")):
                return False
            return (
                any(marker in filename_text for marker in ("certificate of enrolment", "confirmation of enrolment"))
                or re.search(r"\bcoe\b", filename_text) is not None
                or "certificateofenrolment" in filename_norm
                or "confirmationofenrolment" in filename_norm
            )
        if material_norm == "oshc":
            if doc_type_norm in {"oshc", "oshcreceipt", "overseasstudenthealthcover"}:
                return True
            if any(marker in filename_text for marker in ("coe", "certificate of enrolment", "confirmation of enrolment", "caaw")):
                return False
            return "oshc" in filename_text or "overseas student health cover" in filename_text or "overseasstudenthealthcover" in filename_norm
        if material_norm == "ovhc":
            return doc_type_norm in {"ovhc", "ovhcreceipt"} or "ovhc" in filename_text
        if material_norm == "caawwelfareaccommodation":
            return (
                doc_type_norm in {"caaw", "coecaaw", "welfare", "accommodation", "homestay", "letterofconfirmation"}
                or any(marker in filename_text for marker in ("caaw", "welfare", "accommodation", "homestay", "conarr", "confirmation arrangement", "confirmation of accommodation"))
            )
        if self.visa_material_is_visa_result_receipt_item(item):
            return bool(self.visa_material_visa_receipt_match_info(document))
        return False

    def visa_material_application_candidate_documents(self, student_id):
        return db.all(
            """SELECT d.*,u.display_name uploaded_by_name
               FROM student_documents d
               LEFT JOIN users u ON u.id=d.uploaded_by
               WHERE d.student_id=?
                 AND d.is_active=1
                 AND LOWER(COALESCE(d.document_status,'active')) NOT IN ('voided','archived','deleted','inactive')
                 AND LOWER(COALESCE(d.folder_category,'')) NOT IN ('visa management')
                 AND LOWER(COALESCE(d.document_type,'')) <> 'visamaterialchecklist'
               ORDER BY d.uploaded_at DESC,d.id DESC""",
            (student_id,),
        )

    def get_visa_required_files_for_material(self, student_id, visa_case_id, material_item):
        student = self.student_detail_row(student_id)
        if not student:
            return []
        item_id = self.visa_material_record_value(material_item, "id")
        results = []
        seen_document_ids = set()

        if item_id:
            for row in self.visa_material_linked_file_rows(visa_case_id, item_id):
                if self.visa_material_file_source_kind(row) != "visa":
                    continue
                document_id = int(row["id"])
                if document_id in seen_document_ids:
                    continue
                source_area = "VISA Upload"
                record = dict(row)
                record.update({
                    "source_area": source_area,
                    "document_id": document_id,
                    "filename": row["original_name"] or row["stored_name"],
                    "file_path": row["file_path"],
                    "confidence": 100,
                    "matched_reason": "manual VISA material upload",
                    "is_auto_reference": False,
                    "link_source": source_area,
                })
                results.append(record)
                seen_document_ids.add(document_id)

        for document in self.visa_material_application_candidate_documents(student_id):
            document_id = int(document["id"])
            if document_id in seen_document_ids:
                continue
            match_info = self.visa_material_document_match_info(document, material_item, student)
            if not match_info:
                continue
            source_area = self.visa_material_source_area(document)
            record = dict(document)
            record.update({
                "source_area": source_area,
                "document_id": document_id,
                "filename": document["original_name"] or document["stored_name"],
                "file_path": document["file_path"],
                "confidence": match_info["confidence"],
                "matched_reason": match_info["matched_reason"],
                "is_auto_reference": True,
                "document_role": f"material_item:{item_id}" if item_id else "",
                "visa_case_id": visa_case_id,
                "link_source": source_area,
                "link_notes": match_info["matched_reason"],
            })
            results.append(record)
            seen_document_ids.add(document_id)
        return sorted(results, key=lambda row: (-int(row.get("confidence") or 0), str(row.get("uploaded_at") or "")), reverse=False)

    def visa_material_find_application_document(self, student_id, item):
        student = self.student_detail_row(student_id)
        if not student:
            return None
        for document in self.visa_material_application_candidate_documents(student_id):
            if self.visa_material_document_matches_item(document, item, student):
                return document
        return None

    def visa_material_insert_document_link(self, case, item, document_id, source="Visa Material Checklist", notes=""):
        columns = self.visa_material_link_columns()
        stamp = now_iso()
        data = {
            "visa_case_id": case["id"],
            "document_id": document_id,
            "student_document_id": document_id,
            "document_category": item["category"] if "category" in item.keys() else "",
            "document_type": item["document_type"] if "document_type" in item.keys() else (item["title"] if "title" in item.keys() else item["material_name"]),
            "link_purpose": "Visa Material Checklist",
            "used_in_this_case": 1,
            "version_note": "",
            "notes": notes,
            "created_by": (self.user or {}).get("id"),
            "created_at": stamp,
            "source": source,
            "status": "Linked",
            "document_role": f"material_item:{item['id']}",
            "updated_at": stamp,
        }
        ordered = (
            "visa_case_id",
            "document_id",
            "student_document_id",
            "document_category",
            "document_type",
            "link_purpose",
            "used_in_this_case",
            "version_note",
            "notes",
            "created_by",
            "created_at",
            "source",
            "status",
            "document_role",
            "updated_at",
        )
        insert_columns = [column for column in ordered if column in columns]
        placeholders = ",".join("?" for _ in insert_columns)
        db.execute(
            f"INSERT OR IGNORE INTO visa_case_document_links({','.join(insert_columns)}) VALUES({placeholders})",
            [data[column] for column in insert_columns],
        )

    def visa_material_mark_item_uploaded_if_missing(self, case_id, item_id):
        stamp = now_iso()
        columns = {row["name"] for row in db.all("PRAGMA table_info(visa_checklist_items)")}
        set_parts = []
        params = []
        if "status" in columns:
            set_parts.append("status='uploaded'")
        if "item_status" in columns:
            set_parts.append("item_status='uploaded'")
        if "updated_at" in columns:
            set_parts.append("updated_at=?")
            params.append(stamp)
        if not set_parts:
            return
        if "status" in columns and "item_status" in columns:
            current_status_expr = "LOWER(COALESCE(status,item_status,'missing'))"
        elif "status" in columns:
            current_status_expr = "LOWER(COALESCE(status,'missing'))"
        elif "item_status" in columns:
            current_status_expr = "LOWER(COALESCE(item_status,'missing'))"
        else:
            return
        params.extend([item_id, case_id])
        db.execute(
            f"""UPDATE visa_checklist_items
                SET {','.join(set_parts)}
                WHERE id=? AND visa_case_id=?
                  AND {current_status_expr} IN ('', 'missing', '未收到')""",
            params,
        )

    def visa_material_auto_link_application_documents(self, student_id, case, rows):
        student = self.student_detail_row(student_id)
        if not student:
            return
        for item in rows:
            item_id = item.get("id") if isinstance(item, dict) else item["id"]
            if not item_id:
                continue
            linked_rows = self.visa_material_linked_file_rows(case["id"], item_id)
            valid_linked_rows = [
                row
                for row in linked_rows
                if self.visa_material_file_source_kind(row) == "visa"
                or self.visa_material_document_matches_item(row, item, student)
            ]
            if valid_linked_rows:
                self.visa_material_mark_item_uploaded_if_missing(case["id"], item_id)
                continue
            document = self.visa_material_find_application_document(student_id, item)
            if not document:
                continue
            before_count = db.one(
                "SELECT COUNT(*) total FROM visa_case_document_links WHERE visa_case_id=? AND document_role=?",
                (case["id"], f"material_item:{item_id}"),
            )["total"]
            self.visa_material_insert_document_link(
                case,
                item,
                document["id"],
                source="Application File Center",
                notes="Auto matched from Application file center.",
            )
            after_count = db.one(
                "SELECT COUNT(*) total FROM visa_case_document_links WHERE visa_case_id=? AND document_role=?",
                (case["id"], f"material_item:{item_id}"),
            )["total"]
            if after_count > before_count:
                self.visa_material_mark_item_uploaded_if_missing(case["id"], item_id)

    def visa_material_file_source_kind(self, file):
        source_area = str(self.visa_material_record_value(file, "source_area") or "").lower()
        if source_area == "visa upload":
            return "visa"
        if source_area == "coe+oshc":
            return "coe_oshc"
        if source_area == "offer":
            return "offer"
        if source_area == "homestay":
            return "homestay"
        if source_area == "application":
            return "application"
        link_source = str(file["link_source"] if "link_source" in file.keys() else "").lower()
        folder_category = str(file["folder_category"] if "folder_category" in file.keys() else "").lower()
        document_type = str(file["document_type"] if "document_type" in file.keys() else "").lower()
        if folder_category in {"visa management", "visa"} or document_type == "visamaterialchecklist":
            return "visa"
        if "coe" in folder_category and "oshc" in folder_category:
            return "coe_oshc"
        if folder_category == "offer":
            return "offer"
        if "homestay" in folder_category or "accommodation" in folder_category:
            return "homestay"
        if folder_category in {"applications", "application"} or link_source == "application file center":
            return "application"
        return "application" if folder_category else "visa"

    def visa_material_file_source_label(self, file):
        source_kind = self.visa_material_file_source_kind(file)
        if source_kind == "coe_oshc":
            return "来源：COE+OSHC"
        if source_kind == "offer":
            return "来源：Offer"
        if source_kind == "homestay":
            return "来源：Homestay"
        if source_kind == "application":
            return "来源：Application"
        return "来源：VISA Upload"

    def visa_material_linked_file_rows(self, case_id, item_id):
        document_expr = self.visa_material_link_document_expr("l")
        link_columns = self.visa_material_link_columns()
        source_expr = "l.source" if "source" in link_columns else "''"
        notes_expr = "l.notes" if "notes" in link_columns else "''"
        return db.all(
            f"""SELECT d.*,l.document_role,l.visa_case_id,{source_expr} link_source,{notes_expr} link_notes,u.display_name uploaded_by_name
                FROM visa_case_document_links l
                JOIN student_documents d ON d.id={document_expr}
                LEFT JOIN users u ON u.id=d.uploaded_by
                WHERE l.visa_case_id=?
                  AND l.document_role=?
                  AND d.is_active=1
                  AND LOWER(COALESCE(d.document_status,'active')) NOT IN ('voided','archived','deleted','inactive')
                  AND COALESCE(l.status,'Linked') <> 'Removed'
                ORDER BY d.uploaded_at DESC,d.id DESC""",
            (case_id, f"material_item:{item_id}"),
        )

    def visa_material_file_rows(self, case_id, item_id, item=None, student_id=None):
        if item is None or not student_id:
            return self.visa_material_linked_file_rows(case_id, item_id)
        return self.get_visa_required_files_for_material(student_id, case_id, item)

    def visa_material_file_size_label(self, size):
        try:
            size = int(size or 0)
        except (TypeError, ValueError):
            size = 0
        if size >= 1024 * 1024:
            return f"{size / (1024 * 1024):.1f} MB"
        if size >= 1024:
            return f"{size / 1024:.1f} KB"
        return f"{size} B"

    def visa_material_previewable_file(self, filename):
        return Path(str(filename or "")).suffix.lower() in {".pdf", ".docx", ".jpg", ".jpeg", ".png", ".gif", ".webp", ".bmp", ".tif", ".tiff", ".heic"}

    def visa_material_file_type_label(self, filename):
        mime_type = mimetypes.guess_type(str(filename or ""))[0]
        if mime_type:
            return mime_type
        suffix = Path(str(filename or "")).suffix.lower().lstrip(".")
        return suffix.upper() if suffix else "unknown"

    def visa_material_file_area_html(self, student_id, case_id, item):
        item_id = item["id"]
        files = self.visa_material_file_rows(case_id, item_id, item, student_id)
        def render_file_rows(selected_files):
            file_rows = []
            for file in selected_files:
                file_name = self.visa_legacy_document_display_name(case_id, file)
                stored_name = file["stored_name"] or file_name
                uploaded_by = file["uploaded_by_name"] or "系统"
                source_label = self.visa_material_file_source_label(file)
                source_badge = "自动引用" if file.get("is_auto_reference") else "VISA 补充上传"
                matched_reason = file.get("matched_reason") or file.get("link_notes") or ""
                preview_url = f"/documents/{file['id']}/preview"
                download_url = f"/documents/{file['id']}/download"
                preview_button = (
                    f"""<button type="button" class="secondary" data-preview-open
                        data-preview-src="{esc(preview_url)}?size=large"
                        data-download-url="{esc(download_url)}"
                        data-preview-title="{esc(file_name)}">预览</button>"""
                    if self.visa_material_previewable_file(stored_name or file_name)
                    else '<span class="visa-material-preview-unavailable">暂不支持在线预览，请下载查看</span>'
                )
                thumb = (
                    f"""<button type="button" class="visa-material-file-thumb" data-preview-open
                        data-preview-src="{esc(preview_url)}?size=large"
                        data-download-url="{esc(download_url)}"
                        data-preview-title="{esc(file_name)}">
                        <img src="{esc(preview_url)}?size=thumb" alt="{esc(file_name)} 缩略图" loading="lazy">
                      </button>"""
                    if self.visa_material_previewable_file(stored_name or file_name)
                    else '<div class="visa-material-file-thumb visa-material-file-thumb--empty"><span>文件</span></div>'
                )
                legacy_controls = self.visa_legacy_document_controls_html(case_id, file)
                file_rows.append(f"""
                  <div class="visa-material-file-row">
                    {thumb}
                    <div class="visa-material-file-info">
                      <strong>{esc(file_name)}</strong>
                      <small><span class="visa-material-file-source">{esc(source_label)}</span> · <span class="visa-material-file-source">{esc(source_badge)}</span></small>
                      <small>材料项：{esc(self.visa_material_name_label(item['material_name']))}</small>
                      <small>上传时间：{esc(display_datetime(file["uploaded_at"]))} · 上传人：{esc(uploaded_by)}</small>
                      <small>文件大小：{esc(self.visa_material_file_size_label(file["file_size"]))}</small>
                      {f'<small>匹配原因：{esc(matched_reason)}</small>' if matched_reason else ''}
                    </div>
                    <div class="row-actions">
                      {preview_button}
                      <a class="secondary button-link" href="{esc(download_url)}">下载</a>
                      {legacy_controls}
                    </div>
                  </div>""")
            return "".join(file_rows)

        auto_files = [file for file in files if file.get("is_auto_reference")]
        visa_upload_files = [file for file in files if not file.get("is_auto_reference")]
        receipt_scope_note = (
            '<p class="visa-material-file-note">此处仅用于签证申请付款收据 / IMMI Receipt，不自动引用 Application 或学校付款收据。</p>'
            if self.visa_material_is_visa_result_receipt_item(item)
            else ""
        )
        auto_html = (
            f'<div class="visa-material-file-group"><h4>系统已自动引用文件</h4>{render_file_rows(auto_files)}</div>'
            if auto_files else ""
        )
        visa_upload_html = (
            f'<div class="visa-material-file-group"><h4>VISA 补充上传文件</h4>{render_file_rows(visa_upload_files)}</div>'
            if visa_upload_files else ""
        )
        if not files:
            files_html = '<p class="visa-material-file-empty">未找到对应文件。可先到 Application / Offer / COE+OSHC 等来源模块上传，或使用 Smart Batch Upload / 智能批量上传补充。</p>'
        else:
            files_html = auto_html + visa_upload_html
        return f"""
        <div class="visa-material-files">
          <div class="visa-material-files-head"><span>材料文件</span><strong>{len(files)} 个文件</strong></div>
          {receipt_scope_note}
          <div class="visa-material-file-list">{files_html}</div>
        </div>"""

    def visa_material_row_excluded_from_material_tab(self, row, excluded_categories):
        category = str(row.get("category") or "")
        if category in excluded_categories:
            return True
        if not excluded_categories:
            return False
        title = str(row.get("material_name") or "").strip()
        non_material_titles = set()
        if "Visa Result / S56" in excluded_categories:
            non_material_titles.update({
                "Draft",
                "Receipt",
                "Receipt / 付款收据",
                "IMMI Acknowledgment Letter",
                "IMMI Acknowledgment Letter / 递交确认信",
                "Bridging Visa",
                "Bridging Visa / 过桥签证",
                "Health Examination",
                "Health Examination / 体检材料",
                "IMMI Grant Letter / IMMI Refusal Letter",
                "IMMI Grant Letter / IMMI Refusal Letter / 下签信或拒签信",
                "Supplement",
                "Supplement / 补材料",
            })
        if "Declaration" in excluded_categories:
            non_material_titles.update({"Declaration", "Declaration / 声明信息"})
        if "Visa Information Form" in excluded_categories:
            non_material_titles.update({
                "父母声明",
                "真实学生个人陈述",
                "签证信息申报表",
                "真实短暂入境陈述",
                "签证申请信息表",
            })
        return title in non_material_titles

    def visa_material_checklist_html(
        self,
        student_id,
        case,
        category_filter="",
        panel_id="material-checklist",
        title="Material Checklist / 签证材料清单",
        description="",
        show_smart_batch=True,
        show_filter_bar=True,
        form_id_suffix="",
        tab_key="material_checklist",
        exclude_categories=(),
    ):
        existing_count_row = db.one("SELECT COUNT(*) total FROM visa_checklist_items WHERE visa_case_id=?", (case["id"],))
        existing_count = int(existing_count_row["total"] if existing_count_row else 0)
        if existing_count:
            self.visa_material_initialize_checklist(case)
        rows = self.visa_material_checklist_rows(case)
        excluded_categories = set(exclude_categories or ())
        if category_filter:
            rows = [row for row in rows if row["category"] == category_filter]
        elif excluded_categories:
            rows = [row for row in rows if not self.visa_material_row_excluded_from_material_tab(row, excluded_categories)]
        initialized_rows = [row for row in rows if row["is_initialized"]]
        if initialized_rows:
            rows = self.visa_material_effective_rows(student_id, case, rows)
            if category_filter:
                rows = [row for row in rows if row["category"] == category_filter]
            elif excluded_categories:
                rows = [row for row in rows if not self.visa_material_row_excluded_from_material_tab(row, excluded_categories)]
            initialized_rows = [row for row in rows if row["is_initialized"]]
        initialized = bool(initialized_rows)
        summary = self.visa_material_summary_counts(initialized_rows)
        total = summary["total"]
        description = description or f"申请类型：{self.visa_material_profile_label(case)}。VISA 显示系统已有文件引用，也支持补充上传。"
        summary_cards = "".join(
            f'<div class="visa-material-summary-card"><span>{esc(label)}</span><strong>{esc(value)}</strong></div>'
            for label, value in (
                ("申请类型", self.visa_material_profile_label(case)),
                ("总材料项", str(summary["total"])),
                ("未收到", str(summary["missing"])),
                ("已收到", str(summary["uploaded"])),
                ("不适用", str(summary["not_applicable"])),
                ("完成度", f"{summary['completion']}%"),
            )
        )
        if not initialized:
            return f"""
        <section class="panel visa-material-checklist-panel" id="{esc(panel_id)}">
          <div class="panel-head">
            <div><h2>{esc(title)}</h2><p>当前 Visa Case 还没有生成材料清单。</p></div>
            <span class="visa-management-section-count">0 项</span>
          </div>
          <div class="visa-material-summary-grid">{summary_cards}</div>
          <div class="visa-management-empty visa-material-empty">
            <h3>暂无材料清单</h3>
            <p>点击初始化后，系统会按当前申请类型生成 Phase 2A 材料清单。此阶段只记录材料状态和备注。</p>
            <p class="visa-material-phase-note">初始化后将自动显示系统已有来源文件；VISA 不复制、不移动源文件，只做签证材料视角引用。</p>
            <form method="post" action="/students/{quote(student_id)}/visa-cases/{case['id']}/material-items/init">
              <input type="hidden" name="csrf" value="{esc(self.csrf)}">
              <button class="primary" type="submit">初始化材料清单</button>
            </form>
          </div>
        </section>"""
        active_filter = self.visa_material_current_filter() if show_filter_bar else "all"
        filter_bar = self.visa_material_filter_bar_html(student_id, case["id"], active_filter, tab_key) if show_filter_bar else ""
        display_rows = [row for row in initialized_rows if self.visa_material_matches_filter(row, active_filter)]
        grouped = {}
        category_totals = {}
        for row in initialized_rows:
            category_totals.setdefault(row["category"], []).append(row)
        for row in display_rows:
            grouped.setdefault(row["category"], []).append(row)
        category_sections = []
        for category, items in grouped.items():
            category_all_items = category_totals.get(category, items)
            category_completed = sum(1 for item in category_all_items if self.visa_material_is_completed(item))
            item_cards = []
            save_form_id = f"visa-material-save-{case['id']}{form_id_suffix}"
            for item in items:
                status_cell = self.visa_material_status_select_html(item, save_form_id)
                notes_cell = f'<textarea name="notes_{esc(item["id"])}" rows="2" aria-label="备注" form="{esc(save_form_id)}">{esc(item["notes"])}</textarea>'
                files_cell = self.visa_material_file_area_html(student_id, case["id"], item)
                item_cards.append(f"""
                <div class="visa-material-row">
                  <div class="visa-material-cell visa-material-cell--name"><strong>{esc(self.visa_material_name_label(item['material_name']))}</strong></div>
                  <div class="visa-material-cell"><span>归属对象</span><strong>{esc(self.visa_material_owner_type_label(item['owner_type']))}</strong></div>
                  <div class="visa-material-cell"><span>是否递交移民局</span><strong>{esc(self.visa_material_upload_to_immi_label(item['upload_to_immi']))}</strong></div>
                  <div class="visa-material-cell visa-material-cell--purpose"><span>用途说明</span><strong>{esc(self.visa_material_purpose_label(item['purpose']))}</strong></div>
                  <div class="visa-material-cell"><span>要求</span><strong>{esc(self.visa_material_required_status_label(item['required_status']))}</strong></div>
                  <label class="visa-material-cell visa-material-cell--status"><span>当前状态</span>{status_cell}</label>
                  <label class="visa-material-cell visa-material-cell--notes"><span>备注</span>{notes_cell}</label>
                  <div class="visa-material-cell visa-material-cell--files">{files_cell}</div>
                </div>""")
            category_sections.append(f"""
            <section class="visa-material-category">
              <div class="visa-material-category-head">
                <h3>{esc(self.visa_material_category_label(category))}：</h3>
                <span>{category_completed} / {len(category_all_items)} 已完成</span>
              </div>
              <div class="visa-material-list">{''.join(item_cards)}</div>
            </section>""")
        if not category_sections:
            category_sections.append(
                '<div class="visa-management-empty visa-material-filter-empty"><h3>当前筛选没有匹配材料</h3><p>可以切换为“全部”查看完整清单。</p></div>'
            )
        save_form_id = f"visa-material-save-{case['id']}{form_id_suffix}"
        material_filter_input = f'<input type="hidden" name="material_filter" value="{esc(active_filter)}">' if show_filter_bar else ""
        form_start = f"""
        <form id="{esc(save_form_id)}" method="post" action="/students/{quote(student_id)}/visa-cases/{case['id']}/material-items">
          <input type="hidden" name="csrf" value="{esc(self.csrf)}">
          <input type="hidden" name="visa_tab" value="{esc(tab_key)}">
          <input type="hidden" name="return_anchor" value="{esc(panel_id)}">
          {material_filter_input}
        </form>
          <div class="visa-material-save-bar"><button class="primary" form="{esc(save_form_id)}">保存材料状态</button></div>
          <div class="visa-material-grid-head"><span>材料名称</span><span>归属对象</span><span>是否递交移民局</span><span>用途说明</span><span>要求</span><span>当前状态</span><span>备注</span></div>
          {''.join(category_sections)}
          <div class="dialog-actions visa-material-bottom-actions"><button class="primary" form="{esc(save_form_id)}">保存材料状态</button></div>
        """
        smart_batch_link = (
            f'<a class="secondary button-link" href="/students/{quote(student_id)}/visa-cases/{case["id"]}/material-batch-upload?visa_tab={quote(tab_key)}">Smart Batch Upload / 智能批量上传</a>'
            if show_smart_batch else ""
        )
        return f"""
        <section class="panel visa-material-checklist-panel" id="{esc(panel_id)}">
          <div class="panel-head">
            <div><h2>{esc(title)}</h2><p>{esc(description)}</p></div>
            <div class="row-actions">
              {smart_batch_link}
              <span class="visa-management-section-count">{total} 项</span>
            </div>
          </div>
            <p class="visa-material-phase-note">系统会从 Application / Offer / COE+OSHC / Homestay 等来源自动引用匹配文件；源文件仍保留在原模块。</p>
          <div class="visa-material-summary-grid">{summary_cards}</div>
          {filter_bar}
          {form_start}
        </section>"""

