    def visa_evidence_case_review_summary_html(self, student_id, case):
        summary_fields = (
            ("Visa Case Type", case["visa_type"] if "visa_type" in case.keys() else case["case_type"] if "case_type" in case.keys() else ""),
            ("Main Applicant", case["main_applicant"] if "main_applicant" in case.keys() else case["applicant_name"] if "applicant_name" in case.keys() else ""),
            ("Guardian", case["guardian_applicant"] if "guardian_applicant" in case.keys() else ""),
            ("Case Owner", case["case_owner"] if "case_owner" in case.keys() else case["responsible_consultant"] if "responsible_consultant" in case.keys() else ""),
            ("Actual Lodgement Date", display_date_value(case["actual_lodgement_date"] if "actual_lodgement_date" in case.keys() else case["lodgement_date"] if "lodgement_date" in case.keys() else "")),
            ("Final Result", self.student_visa_result_display(case)),
            ("Result Date", display_date_value(case["result_date"] if "result_date" in case.keys() else "")),
            ("Last Updated", display_datetime(case["updated_at"] if "updated_at" in case.keys() else "")),
        )
        cards = "".join(
            f'<div class="visa-management-field-card"><dt>{esc(label)}</dt><dd>{esc(self.visa_management_text(value))}</dd></div>'
            for label, value in summary_fields
        )
        return f"""
        <section class="panel visa-management-detail-panel" id="case-review-summary">
          <div class="panel-head"><div><h2>Case Review Summary</h2><p>只读案件摘要，用于 Evidence / AI Review 页面快速核对案件背景。</p></div></div>
          <dl class="visa-management-detail-grid">{cards}</dl>
        </section>
        """

