    def render_contract_revision_page(self, contract, action_url, back_url):
        form = getattr(self, "form", None)
        if not hasattr(form, "get"):
            form = {}
        normalized_status = normalize_contract_status(contract["contract_status"])
        versions = db.all(
            "SELECT * FROM contract_versions WHERE contract_id=? ORDER BY version_number DESC,id DESC",
            (contract["id"],),
        )
        version_rows = "".join(
            f'<tr><td>V{row["version_number"]}</td><td>{esc(row["revision_reason"] or "")}</td>'
            f'<td>{esc(display_datetime(row["generated_at"]))}</td><td>{esc(Path(row["file_path_docx"] or "").name)}</td></tr>'
            for row in versions
        ) or '<tr><td colspan="4" class="muted-line">暂无版本记录；首次修改时会自动记录当前 V1。</td></tr>'
        if normalized_status in {"ParentSigned", "FullyExecuted"}:
            body = f"""
            <section class="panel contract-revision-panel">
              <div class="panel-head"><div><h2>编辑并重新生成</h2><p>该合同状态为 {esc(CONTRACT_STATUS_LABELS.get(normalized_status, normalized_status))}，不能直接修改已签署内容。</p></div></div>
              <div class="notice warning"><strong>已签署合同不可无痕修改。</strong><br>如需变更，请重新制作新合同，或后续使用补充协议流程。</div>
              <div class="dialog-actions"><a class="secondary button-link" href="{esc(back_url)}">返回</a></div>
              <h3>版本历史</h3><div class="table-wrap"><table><thead><tr><th>版本</th><th>原因</th><th>时间</th><th>文件</th></tr></thead><tbody>{version_rows}</tbody></table></div>
            </section>"""
            return body
        payload = get_contract_content_for_student(contract["student_id"], contract["id"]) if contract["student_id"] else contract_payload_from_existing(contract)
        section_contents = contract_editor_section_contents(payload)
        current_file_name = Path(contract["contract_file_path"] or "").name if contract["contract_file_path"] else "未生成"
        current_doc = None
        if contract["student_id"] and contract["contract_file_path"]:
            current_doc = db.one(
                "SELECT id,original_name,stored_name,file_path FROM student_documents WHERE file_path=? AND is_active=1 ORDER BY id DESC LIMIT 1",
                (contract["contract_file_path"],),
            )
        if current_doc:
            current_contract_actions = f"""
            <div class="row-actions">
              <button type="button" class="secondary" data-preview-open
                data-preview-src="/documents/{current_doc["id"]}/preview?size=large"
                data-download-url="/documents/{current_doc["id"]}/download"
                data-preview-title="当前学生合同">预览当前合同</button>
              <a class="ghost button-link" href="/documents/{current_doc["id"]}/download">下载 Word</a>
            </div>
            """
        else:
            current_contract_actions = f"""
            <div class="row-actions">
              <span class="muted-line">预览当前合同：请从学生合同列表打开文件预览</span>
              <a class="ghost button-link" href="/contracts/{contract["id"]}/download/draft">下载 Word</a>
            </div>
            """
        reset_action = action_url.rstrip("/") + "/reset-standard"
        reset_form = f"""
        <form method="post" action="{esc(reset_action)}" data-confirm-message="确定恢复使用标准模板吗？这会为当前学生生成新的合同版本，并使旧的 active 家长签署链接失效。已签署合同不会被覆盖。">
          <input type="hidden" name="csrf" value="{esc(self.csrf)}">
          <button class="ghost">恢复使用标准模板</button>
        </form>
        """
        pending_transfer = is_unbound_transfer_draft(contract)
        revision_base_fee = str(contract["consulting_and_visa_service_fee"] or "")
        revision_final_fee = str(contract["final_fee_amount"] or "")
        revision_fee_authority = ""
        revision_source_notice = ""
        revision_contract_type = normalize_contract_type(contract["contract_type"])
        revision_scope_config = contract_type_config(revision_contract_type)
        revision_scope_items = tuple(
            (value, contract_domain_service_label(value))
            for value in revision_scope_config.allowed_services
        )
        revision_scope_defaults = tuple(revision_scope_config.default_services)
        revision_scope_ready = True
        revision_source_ready = True
        if pending_transfer:
            reset_form = ""
            revision_fee_authority = ' data-contract-fee-authority="source"'
            revision_connection = db.connect()
            try:
                try:
                    revision_commercial = transfer_contract_authority.commercials(
                        revision_connection,
                        str(contract["student_id"]),
                        int(contract["id"]),
                        payment_method=str(contract["service_fee_currency"] or ""),
                    )
                    revision_base_fee = format_money(
                        money_decimal(revision_commercial["base_fee"])
                    )
                    revision_final_fee = format_money(
                        money_decimal(revision_commercial["final_fee"])
                    )
                    revision_source_notice = (
                        '<div class="notice success">Transfer 来源已核验；'
                        '服务费由来源权威锁定，保存后将生成 Published V2 合同及签署链接。</div>'
                    )
                except (sqlite3.Error, transfer_source_authority.SourceAuthorityError):
                    revision_source_ready = False
                    revision_base_fee = ""
                    revision_final_fee = ""
                    revision_source_notice = (
                        '<div class="notice warning">SOURCE VERIFICATION HOLD：'
                        '来源尚未唯一核验，不能生成可签署合同。</div>'
                    )
            finally:
                db._release_connection(revision_connection)
            try:
                revision_scope_package = current_published_contract_package(
                    revision_contract_type
                )
                revision_scope_items, revision_scope_defaults = (
                    published_service_scope_options(revision_scope_package)
                )
            except (sqlite3.Error, PublishedTemplateAuthorityError):
                revision_scope_ready = False
                revision_scope_items = ()
                revision_scope_defaults = ()
                revision_base_fee = ""
                revision_final_fee = ""
                revision_source_notice = (
                    '<div class="notice warning">SOURCE VERIFICATION HOLD：'
                    '当前 Transfer Published V2 服务范围不可用，不能生成可签署合同。</div>'
                )
        try:
            selected_scope_list = json.loads(contract["service_scope_json"] or "[]")
        except Exception:
            selected_scope_list = []
        if pending_transfer and revision_scope_ready and not selected_scope_list:
            selected_scope_list = list(revision_scope_defaults)
        selected_scope_values = set(selected_scope_list)
        selected_scope_lines = [f"{index}. {service_scope_label(value)}" for index, value in enumerate(selected_scope_list, 1)]
        if contract["other_service_scope_text"]:
            selected_scope_lines.append(f"其他服务范围：{contract['other_service_scope_text']}")
        default_scope_text = "\n".join(selected_scope_lines)
        custom_scope_section = latest_contract_section(contract["id"], "service_scope")
        custom_scope_text = ""
        if custom_scope_section and str(custom_scope_section["section_content"] or "").strip() != default_scope_text.strip():
            custom_scope_text = str(custom_scope_section["section_content"] or "").strip()
        scope_checks = "".join(
            f'<label class="choice wide" data-scope-choice><input type="checkbox" name="service_scope" value="{esc(value)}" {"checked" if value in selected_scope_values else ""}><span>{esc(label)}</span></label>'
            for value, label in revision_scope_items
        )
        contract_body_section_groups = [
            ("三、服务费用与第三方费用", (("fee_explanation", "服务费用说明"), ("third_party_fees", "第三方费用说明"), ("third_party_decisions", "第三方结果说明"))),
            ("四、甲方权利义务", (("party_a_obligations", "甲方权利义务"),)),
            ("五、乙方权利义务", (("party_b_obligations", "乙方权利义务"),)),
            ("六、退费及违约责任", (("refund_intro", "退费原则"), ("third_party_refund", "第三方费用退费"), ("refund_policy", "当前退款规则"), ("termination_no_refund", "终止服务责任"), ("false_documents", "虚假材料责任"))),
            ("七、不可抗力、结果说明及免责", (("outcome_disclaimer", "结果说明及免责"), ("force_majeure", "不可抗力"))),
            ("八、适用法律及争议解决", (("governing_law", "适用法律"), ("dispute_resolution", "争议解决"))),
            ("九、合同补充、变更和生效", (("contract_variation", "合同补充、变更"), ("minor_guardian", "未成年人监护人确认"), ("contract_effective", "合同生效方式"), ("personal_expenses", "个人费用说明"))),
            ("十、特别条款", (("special_conditions", "特别条款"),)),
        ]
        contract_body_editors = []
        for group_title, fields in contract_body_section_groups:
            field_html_parts = []
            for section_key, label in fields:
                rows = 3 if section_key in {"governing_law", "dispute_resolution"} else 6
                field_html_parts.append(
                    f'<label>{esc(label)}<textarea name="contract_section_{esc(section_key)}" rows="{rows}">{esc(section_contents.get(section_key) or "")}</textarea></label>'
                )
            contract_body_editors.append(
                f'<details class="contract-section-editor"><summary>{esc(group_title)}</summary><div class="contract-section-editor-fields">{"".join(field_html_parts)}</div></details>'
            )
        contract_body_editor_html = "".join(contract_body_editors)
        refund_checks = refund_policy_checkboxes(active_refund_templates(), normalize_refund_policy_types(contract["refund_policy_type"]))
        service_options = contract_service_type_options(contract["service_type"], contract["consulting_and_visa_service_fee"] or "")
        payment_options = contract_payment_method_options(contract["service_fee_currency"] or "")
        relationship_options = parent_signer_relationship_options(payload.get("parent_signer_relationship") or "")
        discount_enabled = discount_enabled_from_amount(contract["discount_amount"])
        discount_hidden = "" if discount_enabled == "yes" else " hidden"
        fee_readonly = (
            " readonly"
            if pending_transfer
            else ("" if (contract["service_fee_currency"] or "") in CONTRACT_EDITABLE_FEE_PAYMENT_METHODS else " readonly")
        )
        revision_submit_disabled = (
            ' disabled aria-disabled="true" title="Transfer 来源或 Published V2 服务范围不可用"'
            if pending_transfer and not (revision_source_ready and revision_scope_ready)
            else ""
        )
        body = f"""
        <section class="panel contract-revision-panel">
          <div class="panel-head"><div><h2>编辑并重新生成</h2><p>本次修改只影响当前学生合同，不会修改全局合同模板。</p></div><a class="secondary button-link" href="{esc(back_url)}">返回</a></div>
          <div class="notice warning"><strong>只改当前这一份合同。</strong><br>保存后会生成新的合同版本；旧的 active 家长签署链接会自动失效，需要重新生成并发送新链接。已签署合同不能在这里覆盖。</div>
          {revision_source_notice}
          <section class="contract-section">
            <div class="panel-head compact-head"><div><h3>当前实际合同文件</h3><p>{esc(current_file_name)}</p></div><div class="row-actions">{reset_form}</div></div>
            {current_contract_actions}
          </section>
          <form class="stack-form contract-revision-form contract-form" method="post" action="{esc(action_url)}">
            <input type="hidden" name="csrf" value="{esc(self.csrf)}">
            <input type="hidden" name="service_scope_submitted" value="1">
            <div class="dialog-grid">
              <label>Contract date<input type="date" name="contract_date" value="{esc(contract["contract_date"] or date.today().isoformat())}" required></label>
              <label>收到修改日期<input type="date" name="request_received_date" value="{esc(date.today().isoformat())}"></label>
              <label>来源渠道<select name="request_channel"><option value="">未选择</option><option>微信</option><option>Email</option><option>电话</option><option>面谈</option><option>内部修改</option></select></label>
              <label>修改原因（必填）<input name="revision_reason" required placeholder="例如：家长要求补充退款说明"></label>
              <label>监护人姓名<input name="parent_signer_name" value="{esc(contract["parent_signer_name"] or payload.get("parent_signer_name") or "")}" required></label>
              <label>监护人关系<select name="parent_signer_relationship">{relationship_options}</select></label>
              <label>家长电话<input name="parent_phone" value="{esc(contract["parent_phone"] or payload.get("parent_phone") or "")}"></label>
              <label>家长邮箱<input name="parent_email" value="{esc(contract["parent_email"] or payload.get("parent_email") or "")}"></label>
              <label>家长地址<input name="parent_address" value="{esc(contract["parent_address"] or payload.get("parent_address") or "")}"></label>
              <label>Service type<select name="service_type" data-contract-service-type>{service_options}</select></label>
              <label>支付方式<select name="service_fee_currency" required data-contract-payment-method><option value="">请选择</option>{payment_options}</select></label>
              <label>服务费<input name="consulting_and_visa_service_fee" value="{esc(revision_base_fee)}" inputmode="decimal"{fee_readonly} data-fixed-fee="{esc(revision_base_fee)}"{revision_fee_authority} data-contract-service-fee></label>
              <div class="contract-discount-control"><label>是否有优惠<select name="discount_enabled" data-contract-discount-toggle><option value="no" {"selected" if discount_enabled == "no" else ""}>无</option><option value="yes" {"selected" if discount_enabled == "yes" else ""}>有</option></select></label>
              <label data-contract-discount-amount{discount_hidden}>优惠数目<input name="discount_amount" value="{esc(contract["discount_amount"] or "")}" data-contract-discount-input></label></div>
              <label class="contract-final-fee-field">最终费用<input name="final_fee_amount" value="{esc(revision_final_fee)}" readonly data-contract-final-fee></label>
              <label>付款截止日期<input type="date" name="payment_due_date" value="{esc(contract["payment_due_date"] or "")}"></label>
            </div>
            <label>家长/内部修改要求<textarea name="parent_request_text" rows="3" placeholder="记录收到的原始要求，方便以后追溯。"></textarea></label>
            <label>修改说明<textarea name="revision_instruction" rows="3" placeholder="说明这次准备怎么改。"></textarea></label>
            <section class="contract-section"><div class="panel-head compact-head"><div><h3>服务范围勾选项</h3><p>这里只决定哪些服务范围进入当前合同；合同正文条款请在下方“合同正文章节内容修改”里改。</p></div><div class="row-actions"><button type="button" class="secondary" data-scope-select="all">全选</button><button type="button" class="ghost" data-scope-select="none">清空</button></div></div><div class="choices scope-choices">{scope_checks}</div></section>
            <label>服务范围正文<textarea name="service_scope_override_text" rows="8" placeholder="可选：只有需要手写覆盖服务范围时才填写。留空则按上方勾选项生成。">{esc(custom_scope_text)}</textarea></label>
            <section class="contract-section"><h3>退款规则</h3><div class="refund-rule-list">{refund_checks}</div></section>
            <label>退款备注<input name="refund_notes" value="{esc(contract["refund_notes"] or "")}"></label>
            <label>服务内容 / 其他服务范围<textarea name="other_service_scope_text" rows="3">{esc(contract["other_service_scope_text"] or "")}</textarea></label>
            <section class="contract-section contract-body-editor"><div class="panel-head compact-head"><div><h3>合同正文章节内容修改</h3><p>展开对应章节，只修改当前学生这份合同内容；不会修改标准合同模板。</p></div></div>{contract_body_editor_html}</section>
            <label>内部备注<textarea name="notes" rows="2">{esc(contract["notes"] or "")}</textarea></label>
            <div class="dialog-actions"><button class="primary"{revision_submit_disabled}>保存并重新生成当前学生合同</button></div>
          </form>
          <h3>版本历史</h3><div class="table-wrap"><table><thead><tr><th>版本</th><th>原因</th><th>时间</th><th>文件</th></tr></thead><tbody>{version_rows}</tbody></table></div>
        </section>"""
        return body

    def contract_center_revision_assistant(self, method, contract_id):
        if not can_revise_contract(self.user):
            db.audit(self.user, "contract_revision_access_denied", "contracts", contract_id, ip=self.client_address[0], device=self.headers.get("User-Agent"), contract_id=str(contract_id))
            return self.error_page("你没有修改合同的权限。", 403)
        contract = db.one("SELECT * FROM contracts WHERE id=?", (contract_id,))
        if not contract:
            return self.error_page("合同不存在", 404)
        if normalize_contract_type(contract["contract_type"]) == "TransferApplicationContract" and not can_manage_transfer_contract(self.user):
            return self.error_page("仅 Admin / Manager 可以管理转学合同", 403)
        if method == "POST":
            if is_unbound_transfer_draft(contract):
                self.form = dict(self.form)
                self.form["contract_type"] = "TransferApplicationContract"
                self.form.setdefault(
                    "parent_signer_source",
                    "father"
                    if self.form.get("parent_signer_relationship") == "父亲"
                    else "mother",
                )
                return self.transfer_contract_prepare(str(contract["student_id"]))
            try:
                result = generate_contract_editor_revision(contract_id, self.user, self.form)
            except PermissionError as exc:
                return self.flash_redirect(f"/contracts/{contract_id}/revise", str(exc), "error")
            except ValueError as exc:
                return self.flash_redirect(f"/contracts/{contract_id}/revise", str(exc), "error")
            suffix = "；旧签署链接已失效，请重新生成并发送新链接。" if result.get("invalidated_links") else ""
            return self.flash_redirect("/contracts?view=list", f"当前合同已编辑并重新生成 V{result['version_number']}{suffix}")
        body = self.render_contract_revision_page(contract, f"/contracts/{contract_id}/revise", "/contracts?view=list")
        self.send_html(page("合同修改助手", body, self.user, self.csrf, "contracts", nas.status()))

