    def document_download(self, method, document_id):
        if not self.require("documents.view"):
            return
        doc = db.one("SELECT * FROM student_documents WHERE id=? AND is_active=1", (document_id,))
        if not doc:
            return self.error_page("文件记录不存在", 404)
        student = db.one("SELECT * FROM students WHERE student_id=?", (doc["student_id"],))
        if SAFE_PRODUCTION_ACTIVE:
            pass
        elif doc["document_type"] == "StudentInfo":
            try:
                doc = ensure_student_info_document_filename(student, doc)
            except Exception as exc:
                append_service_log("admin", "student_info_filename_sync_failed", repr(exc), document_id=document_id)
        else:
            try:
                doc = ensure_generated_application_document_filename(doc)
            except Exception as exc:
                append_service_log("admin", "generated_document_filename_sync_failed", repr(exc), document_id=document_id)
        try:
            doc = effective_contract_document_for_output(doc, self.user)
        except Exception as exc:
            append_service_log("admin", "contract_document_download_effective_source_failed", repr(exc), document_id=document_id)
        folder = nas.student_folder(student)
        path = ensure_within(doc["file_path"], folder)
        if not path.is_file():
            return self.error_page("NAS 文件不存在", 404)
        if doc["document_type"] in {"StudyAbroadContract", "StudyAbroadContractRevision"}:
            contract_output_debug_log("document_download", document=doc, actual_download_source=path)
        db.audit(self.user, "download", "documents", document_id, str(path), ip=self.client_address[0])
        payload = path.read_bytes()
        self.send_response(200)
        self.send_header("Content-Type", mimetypes.guess_type(path.name)[0] or "application/octet-stream")
        self.send_header("Content-Disposition", f"attachment; filename*=UTF-8''{quote(doc['stored_name'] or path.name)}")
        self.send_header("Content-Length", str(len(payload)))
        self.end_headers()
        self.wfile.write(payload)

    def document_preview(self, method, document_id):
        if method != "GET" or not self.require("documents.view"):
            return
        doc = db.one("SELECT * FROM student_documents WHERE id=? AND is_active=1", (document_id,))
        if not doc:
            return self.text("Not found", 404)
        student = db.one("SELECT * FROM students WHERE student_id=?", (doc["student_id"],))
        if SAFE_PRODUCTION_ACTIVE:
            pass
        elif doc["document_type"] == "StudentInfo":
            try:
                doc = ensure_student_info_document_filename(student, doc)
            except Exception as exc:
                append_service_log("admin", "student_info_filename_sync_failed", repr(exc), document_id=document_id)
        else:
            try:
                doc = ensure_generated_application_document_filename(doc)
            except Exception as exc:
                append_service_log("admin", "generated_document_filename_sync_failed", repr(exc), document_id=document_id)
        try:
            doc = effective_contract_document_for_output(doc, self.user)
        except Exception as exc:
            append_service_log("admin", "contract_document_preview_effective_source_failed", repr(exc), document_id=document_id)
        size = "large" if (self.query.get("size") or [""])[0] == "large" else "thumb"
        try:
            page_number = max(1, int((self.query.get("page") or ["1"])[0]))
        except ValueError:
            page_number = 1
        name = doc["stored_name"] or doc["original_name"]
        suffix = Path(name).suffix.lower()
        target = preview_target(document_id, size, page_number).resolve()
        source_data = None
        content_type = mimetypes.guess_type(name)[0] or ""
        preview_data = None
        preview_name = name
        preview_content_type = content_type
        source_path = None
        total_pages = 1
        preview_status = "ok"
        preview_error_code = ""
        preview_errors = []
        previewable_suffixes = {".pdf", ".docx", ".jpg", ".jpeg", ".png", ".gif", ".webp", ".bmp", ".tif", ".tiff"}
        if suffix in previewable_suffixes:
            folder = nas.student_folder(student)
            source_path = ensure_within(doc["file_path"], folder)
            if doc["document_type"] in {"StudyAbroadContract", "StudyAbroadContractRevision"}:
                contract_output_debug_log("document_preview", document=doc, actual_preview_source=source_path)
            if source_path.is_file():
                if source_path.stat().st_size <= 0:
                    preview_status = "error"
                    preview_error_code = "empty_file"
                else:
                    source_data = source_path.read_bytes()
                if source_data and suffix == ".pdf":
                    try:
                        preview_data = source_data
                        total_pages = max(1, preview_pdf_page_count(source_data, doc, name))
                        page_number = max(1, min(total_pages, page_number))
                        target = preview_target(document_id, size, page_number).resolve()
                    except Exception as exc:
                        preview_status = "error"
                        preview_error_code = preview_render_error_code(exc) if isinstance(exc, PreviewRenderError) else "pdf_page_count_failed"
                        total_pages = 1
                        append_service_log(
                            "admin",
                            "document_preview_pdf_page_count_failed",
                            repr(exc),
                            document_id=document_id,
                            filename=name,
                            reason=preview_error_code,
                        )
                elif source_data and suffix == ".docx":
                    if is_contract_preview_document(doc, name):
                        try:
                            preview_pdf = contract_docx_preview_pdf(source_path, document_id)
                            preview_data = preview_pdf.read_bytes()
                            preview_name = f"{Path(name).stem}.pdf"
                            preview_content_type = "application/pdf"
                            total_pages = max(1, preview_pdf_page_count(preview_data, doc, preview_name))
                            page_number = max(1, min(total_pages, page_number))
                            target = preview_target(document_id, size, page_number).resolve()
                        except Exception as exc:
                            preview_status = "error"
                            preview_error_code = preview_render_error_code(exc) if isinstance(exc, PreviewRenderError) else "docx_render_failed"
                            total_pages = 1
                            append_service_log(
                                "admin",
                                "document_preview_contract_docx_pdf_failed",
                                repr(exc),
                                document_id=document_id,
                                filename=name,
                                reason=preview_error_code,
                            )
                    else:
                        preview_data = source_data
                        total_pages = max(1, docx_preview_page_count(source_data))
                        page_number = max(1, min(total_pages, page_number))
                        target = preview_target(document_id, size, page_number).resolve()
                elif source_data:
                    preview_data = source_data
            else:
                preview_status = "error"
                preview_error_code = "source_missing"
                append_service_log(
                    "admin",
                    "document_preview_source_missing",
                    "",
                    document_id=document_id,
                    filename=name,
                    path_summary=preview_path_summary(doc["file_path"]),
                )
        else:
            preview_status = "unavailable"
            preview_error_code = "unsupported"
        should_refresh_preview = bool(preview_data) and (
            suffix in {".pdf", ".docx"}
            or not target.is_file()
            or (source_path and target.stat().st_mtime < source_path.stat().st_mtime)
        )
        def build_preview(data=None):
            kwargs = {
                "size": size,
                "page": page_number,
                "error_collector": preview_errors,
            }
            if preview_error_code:
                kwargs["fallback_code"] = preview_error_code
            return make_preview(document_id, preview_name, data, preview_content_type, **kwargs)

        if should_refresh_preview:
            preview_path = build_preview(preview_data)
            if preview_errors and not preview_error_code:
                preview_status = "error"
                preview_error_code = preview_errors[0]
            if size == "thumb" and page_number == 1:
                db.execute("UPDATE student_documents SET preview_path=? WHERE id=?", (preview_path, document_id))
            target = Path(preview_path).resolve()
        elif not target.is_file():
            preview_path = build_preview()
            if preview_errors and not preview_error_code:
                preview_status = "error"
                preview_error_code = preview_errors[0]
            if size == "thumb" and page_number == 1:
                db.execute("UPDATE student_documents SET preview_path=? WHERE id=?", (preview_path, document_id))
            target = Path(preview_path).resolve()
        if PREVIEW_DIR.resolve() not in target.parents or not target.is_file():
            preview_path = build_preview()
            if preview_errors and not preview_error_code:
                preview_status = "error"
                preview_error_code = preview_errors[0]
            if size == "thumb" and page_number == 1:
                db.execute("UPDATE student_documents SET preview_path=? WHERE id=?", (preview_path, document_id))
            target = Path(preview_path).resolve()
        if preview_status != "ok" or preview_error_code:
            log_document_preview_fallback(
                preview_error_code or preview_status,
                document_id=document_id,
                filename=name,
                file_path=doc["file_path"],
                size=size,
                page=page_number,
            )
        payload = target.read_bytes()
        self.send_response(200)
        self.send_header("Content-Type", "image/png")
        self.send_header("Content-Length", str(len(payload)))
        self.send_header("Cache-Control", "no-cache")
        self.send_header("X-Preview-Status", preview_status)
        self.send_header("X-Preview-Error-Code", preview_error_code)
        if preview_status != "ok" or preview_error_code:
            self.send_header("X-Preview-Fallback", "download_original")
            self.send_header("X-Preview-Fallback-Reason", re.sub(r"[^A-Za-z0-9_-]", "", preview_error_code or preview_status or "unknown")[:80])
        self.send_header("X-Preview-Page", str(page_number))
        self.send_header("X-Preview-Page-Count", str(total_pages))
        self.end_headers()
        self.wfile.write(payload)

    def document_preview_regenerate(self, method, document_id):
        if method != "POST" or not self.require("documents.manage"):
            return
        doc = db.one("SELECT * FROM student_documents WHERE id=? AND is_active=1", (document_id,))
        if not doc:
            return self.flash_redirect((self.headers.get("Referer") or "/students"), "文件记录不存在。", "error")
        student = db.one("SELECT * FROM students WHERE student_id=?", (doc["student_id"],))
        if not student:
            return self.flash_redirect((self.headers.get("Referer") or "/students"), "学生记录不存在。", "error")
        if doc["document_type"] == "StudentInfo":
            doc = ensure_student_info_document_filename(student, doc)
        else:
            doc = ensure_generated_application_document_filename(doc)
        name = doc["stored_name"] or doc["original_name"]
        suffix = Path(name).suffix.lower()
        previewable_suffixes = {".pdf", ".docx", ".jpg", ".jpeg", ".png", ".gif", ".webp", ".bmp", ".tif", ".tiff"}
        if suffix not in previewable_suffixes:
            return self.flash_redirect((self.headers.get("Referer") or f"/students/{student['student_id']}"), "该文件类型暂不支持在线预览。", "error")
        folder = nas.student_folder(student)
        source_path = ensure_within(doc["file_path"], folder)
        if not source_path.is_file():
            append_service_log("admin", "document_preview_regenerate_source_missing", "", document_id=document_id, file_path=doc["file_path"])
            return self.flash_redirect((self.headers.get("Referer") or f"/students/{student['student_id']}"), "重新生成预览失败：文件不存在。", "error")
        data = source_path.read_bytes()
        content_type = mimetypes.guess_type(name)[0] or ""
        preview_data = data
        preview_name = name
        preview_content_type = content_type
        try:
            if suffix == ".pdf":
                total_pages = max(1, preview_pdf_page_count(data, doc, name))
            elif suffix == ".docx":
                if is_contract_preview_document(doc, name):
                    preview_pdf = contract_docx_preview_pdf(source_path, document_id)
                    preview_data = preview_pdf.read_bytes()
                    preview_name = f"{Path(name).stem}.pdf"
                    preview_content_type = "application/pdf"
                    total_pages = max(1, preview_pdf_page_count(preview_data, doc, preview_name))
                else:
                    total_pages = max(1, docx_preview_page_count(data))
            else:
                total_pages = 1
            errors = []
            first_preview = ""
            for page_number in range(1, total_pages + 1):
                thumb = make_preview(document_id, preview_name, preview_data, preview_content_type, size="thumb", page=page_number, error_collector=errors)
                make_preview(document_id, preview_name, preview_data, preview_content_type, size="large", page=page_number, error_collector=errors)
                if page_number == 1:
                    first_preview = thumb
            if errors:
                code = errors[0]
                append_service_log("admin", "document_preview_regenerate_failed", code, document_id=document_id, filename=name)
                return self.flash_redirect((self.headers.get("Referer") or f"/students/{student['student_id']}"), f"重新生成预览失败：{preview_error_message(code)}", "error")
            db.execute("UPDATE student_documents SET preview_path=? WHERE id=?", (first_preview, document_id))
            db.audit(self.user, "regenerate_preview", "documents", document_id, str(source_path), new_value=f"pages={total_pages}", student_id=student["student_id"])
            return self.flash_redirect((self.headers.get("Referer") or f"/students/{student['student_id']}?tab=applications"), f"已重新生成预览：共 {total_pages} 页。")
        except Exception as exc:
            append_service_log("admin", "document_preview_regenerate_exception", repr(exc), document_id=document_id, filename=name)
            return self.flash_redirect((self.headers.get("Referer") or f"/students/{student['student_id']}"), f"重新生成预览失败：{exc}", "error")

    def document_final_confirmed_school_plan_regenerate(self, method, document_id):
        if method != "POST" or not self.require("documents.manage"):
            return
        doc = db.one("SELECT * FROM student_documents WHERE id=? AND is_active=1", (document_id,))
        if not doc:
            return self.flash_redirect((self.headers.get("Referer") or "/students"), "文件记录不存在。", "error")
        if doc["document_type"] != "FinalConfirmedSchoolPlan":
            return self.flash_redirect((self.headers.get("Referer") or "/students"), "只有最终确认方案可以重新生成。", "error")
        event_rows = db.all(
            """SELECT * FROM school_plan_report_events
               WHERE event_type='confirmation_archived_to_application'
               ORDER BY event_at DESC,id DESC LIMIT 200"""
        )
        confirmation_id = None
        for row in event_rows:
            try:
                metadata = json.loads(row["metadata_json"] or "{}")
            except Exception:
                metadata = {}
            if int(metadata.get("final_document_id") or 0) == int(document_id):
                confirmation_id = metadata.get("confirmation_id")
                break
        if not confirmation_id:
            return self.flash_redirect((self.headers.get("Referer") or f"/students/{doc['student_id']}?tab=applications"), "找不到该最终确认方案对应的家长确认记录，无法自动重新生成。", "error")
        try:
            result = self.school_plan_archive_confirmation_documents(int(confirmation_id), user=self.user)
            return self.flash_redirect(
                (self.headers.get("Referer") or f"/students/{doc['student_id']}?tab=applications"),
                f"已重新生成最终确认方案：{Path(result['final_document_path']).name}",
            )
        except Exception as exc:
            append_service_log("admin", "document_final_confirmed_school_plan_regenerate_failed", repr(exc), document_id=document_id, confirmation_id=confirmation_id)
            return self.flash_redirect((self.headers.get("Referer") or f"/students/{doc['student_id']}?tab=applications"), f"重新生成最终确认方案失败：{exc}", "error")

    def file_manager_access_denied(self, message="无权限访问该功能。"):
        db.audit(
            self.user, "access_denied", "file_manager", record_id=self.parsed.path,
            ip=self.client_address[0], device=self.headers.get("User-Agent"),
            status="denied", error_message=message,
        )
        return self.error_page(message, 403)

    def file_manager_breadcrumb(self, year="", student="", folder=""):
        crumbs = ['<a href="/file-manager">Students</a>']
        if year:
            crumbs.append(f'<a href="/file-manager?year={quote(year)}">{esc(year)}</a>')
        if student:
            crumbs.append(f'<a href="/file-manager?year={quote(year)}&student={quote(student)}">{esc(student)}</a>')
        if folder:
            crumbs.append(f'<span>{esc(folder)}</span>')
        return '<nav class="fm-breadcrumb file-manager-breadcrumbs">' + '<span>/</span>'.join(crumbs) + '</nav>'

    def file_manager(self, method):
        if method != "GET":
            return self.error_page("File Manager 只支持浏览操作。", 405)
        if not can_file_manager_action(self.user, "view"):
            return self.file_manager_access_denied("无权限查看文件管理。")
        try:
            year = (self.query.get("year") or [""])[0]
            student_name = (self.query.get("student") or [""])[0]
            module_folder = (self.query.get("folder") or [""])[0]
            filter_status = (self.query.get("filter") or ["all"])[0]
            search = (self.query.get("q") or [""])[0].strip().lower()
            root, current, student_name, module_folder = file_manager_resolve(year, student_name, module_folder)
        except NasSafetyError as exc:
            return self.error_page(str(exc), 400)
        db.audit(
            self.user, "folder_viewed", "file_manager", record_id=str(current),
            file_path=str(current), ip=self.client_address[0], device=self.headers.get("User-Agent"),
        )
        notice = '<p class="locked-note file-manager-nas-status">MVP 安全模式：File Manager 不会创建、删除、移动或重命名任何真实文件夹/文件。删除、移动、重命名按钮只会写入标记和操作日志。</p>'
        if not year:
            cards = ""
            if root.is_dir():
                cards = (
                    f'<a class="fm-card file-manager-folder-card" href="/file-manager?year={quote(root.name)}">'
                    f'<strong>{esc(root.name)}</strong><span>当前允许根目录</span><small>{esc(str(root))}</small></a>'
                )
            else:
                cards = '<div class="empty file-manager-empty-state file-manager-error-state">学生文件目录当前不可用。请先确认 NAS 已挂载。</div>'
            body = f"""
            <div class="file-manager-page">
            <section class="panel file-manager-panel">
              <div class="panel-head file-manager-header"><div><h2>文件管理</h2><p>根目录只读。MVP 阶段只显示当前安全根目录，不扫描真实年份目录。</p></div></div>
              {notice}
              {self.file_manager_breadcrumb()}
              <div class="fm-card-grid file-manager-root-grid">{cards}</div>
            </section>
            </div>"""
            return self.send_html(page("文件管理", body, self.user, self.csrf, "file_manager", nas.status()))

        if year and not student_name:
            if not root.is_dir():
                return self.error_page("当前根目录不存在或不可读取。", 404)
            cards = []
            for item in sorted(root.iterdir(), key=lambda p: p.name.lower()):
                if not item.is_dir():
                    continue
                if search and search not in item.name.lower():
                    continue
                student = file_manager_student_for_folder(item)
                subtitle = student["student_id"] if student else "未关联 CRM 学生记录"
                cards.append(
                    f'<a class="fm-card file-manager-folder-card" href="/file-manager?year={quote(year)}&student={quote(item.name)}">'
                    f'<strong>{esc(item.name)}</strong><span>{esc(subtitle)}</span><small>学生文件夹</small></a>'
                )
            body = f"""
            <div class="file-manager-page">
            <section class="panel file-manager-panel">
              <div class="panel-head file-manager-header"><div><h2>{esc(year)}</h2><p>存储根目录只读；学生文件夹只能通过 CRM 学生流程创建。</p></div>
              <form class="search file-manager-search" method="get"><input type="hidden" name="year" value="{esc(year)}"><input name="q" value="{esc(search)}" placeholder="在当前目录搜索学生文件夹"><button class="secondary">搜索</button></form></div>
              {notice}
              {self.file_manager_breadcrumb(year)}
              <div class="fm-card-grid file-manager-folder-grid">{''.join(cards) or '<div class="empty file-manager-empty-state">当前目录没有学生文件夹</div>'}</div>
            </section>
            </div>"""
            return self.send_html(page("文件管理", body, self.user, self.csrf, "file_manager", nas.status()))

        if student_name and not module_folder:
            student_path = current
            if not student_path.is_dir():
                return self.error_page("学生文件夹不存在。", 404)
            cards = []
            for folder_name in STANDARD_FOLDERS:
                folder_path = ensure_within(student_path / folder_name, root)
                count = len([p for p in folder_path.iterdir() if p.is_file()]) if folder_path.is_dir() else 0
                cards.append(
                    f'<a class="fm-card file-manager-folder-card file-manager-module-card" href="/file-manager?year={quote(year)}&student={quote(student_name)}&folder={quote(folder_name)}">'
                    f'<strong>{esc(folder_name)}</strong><span>{count} 个文件</span><small>模块文件夹 · 只读结构</small></a>'
                )
            body = f"""
            <div class="file-manager-page">
            <section class="panel file-manager-panel">
              <div class="panel-head file-manager-header"><div><h2>{esc(student_name)}</h2><p>学生内部标准文件夹由 CRM 控制，不允许在 File Manager 中新增/删除/重命名。</p></div></div>
              {notice}
              {self.file_manager_breadcrumb(year, student_name)}
              <div class="fm-card-grid file-manager-folder-grid">{''.join(cards)}</div>
            </section>
            </div>"""
            return self.send_html(page("文件管理", body, self.user, self.csrf, "file_manager", nas.status()))

        return self.file_manager_folder_view(root, year, student_name, module_folder, current, filter_status, search, notice)

    def file_manager_folder_view(self, root, year, student_name, module_folder, folder_path, filter_status, search, notice):
        if not folder_path.is_dir():
            return self.error_page("模块文件夹不存在。", 404)
        student_record = file_manager_student_for_folder(folder_path.parent)
        docs = db.all(
            """SELECT d.*,u.display_name uploaded_by_name FROM student_documents d
               LEFT JOIN users u ON u.id=d.uploaded_by WHERE d.is_active=1"""
        )
        docs_by_path = {row["file_path"]: row for row in docs}
        filters = [
            ("all", "Show all"), ("PendingDelete", "Pending Delete"), ("PendingMove", "Pending Move"),
            ("PendingRename", "Pending Rename"), ("Processed", "Processed"), ("Cancelled", "Cancelled"),
        ]
        filter_links = "".join(
            f'<a class="{"active" if filter_status == key else ""}" href="/file-manager?year={quote(year)}&student={quote(student_name)}&folder={quote(module_folder)}&filter={quote(key)}">{esc(label)}</a>'
            for key, label in filters
        )
        upload_box = ""
        if module_folder in FILE_MANAGER_UPLOAD_MODULES:
            if can_file_manager_action(self.user, "upload"):
                upload_box = f"""
                <form class="fm-upload file-manager-upload-panel" method="post" enctype="multipart/form-data" action="/file-manager/upload">
                  <input type="hidden" name="csrf" value="{esc(self.csrf)}">
                  <input type="hidden" name="year" value="{esc(year)}">
                  <input type="hidden" name="student" value="{esc(student_name)}">
                  <input type="hidden" name="folder" value="{esc(module_folder)}">
                  <input type="file" name="files" multiple required>
                  <button class="primary">上传并进入 Review</button>
                </form>"""
            else:
                upload_box = '<p class="muted-line file-manager-upload-panel">你没有 File Manager 上传权限。</p>'
        else:
            upload_box = '<p class="muted-line file-manager-upload-panel">此模块 MVP 不支持随机上传，请从对应业务页面上传。</p>'
        rows = []
        for file_path in sorted(folder_path.iterdir(), key=lambda p: p.name.lower()):
            if not file_path.is_file():
                continue
            if search and search not in file_path.name.lower():
                continue
            marker = file_manager_marker_for_path(file_path)
            visual_status = file_manager_marker_visual_status(marker)
            if filter_status != "all" and visual_status != filter_status:
                continue
            stat = file_path.stat()
            doc = docs_by_path.get(str(file_path))
            marker_note = ""
            if marker:
                suggestion = marker["suggested_new_filename"] or marker["suggested_target_folder"] or ""
                marker_note = f'<small>{esc(suggestion)} {esc(marker["reason"] or "")}</small>'
            preview_button = f'<button type="button" class="secondary" data-preview-open data-preview-src="/file-manager/preview?year={quote(year)}&student={quote(student_name)}&folder={quote(module_folder)}&file={quote(file_path.name)}&size=large" data-download-url="/file-manager/download?year={quote(year)}&student={quote(student_name)}&folder={quote(module_folder)}&file={quote(file_path.name)}" data-preview-title="{esc(file_path.name)}">预览</button>'
            download_button = ""
            if can_file_manager_action(self.user, "download"):
                download_button = f'<a class="secondary button-link" href="/file-manager/download?year={quote(year)}&student={quote(student_name)}&folder={quote(module_folder)}&file={quote(file_path.name)}">下载</a>'
            actions = self.file_manager_file_actions(year, student_name, module_folder, file_path.name, marker)
            audit_rows = db.all("SELECT * FROM audit_logs WHERE file_path=? ORDER BY created_at DESC LIMIT 20", (str(file_path),))
            audit_html = "".join(
                f'<tr><td>{esc(display_datetime(r["created_at"]))}</td><td>{esc(r["username"])}</td><td>{esc(audit_summary(r))}</td></tr>'
                for r in audit_rows
            ) or '<tr><td colspan="3" class="empty">暂无文件日志</td></tr>'
            log_dialog = (
                f'<button class="ghost file-manager-audit-action" type="button" data-dialog-open="fm-log-{len(rows)}">日志</button>'
                f'<dialog id="fm-log-{len(rows)}"><div class="dialog-head"><h2>文件日志</h2><button type="button" class="icon-button" data-dialog-close>×</button></div>'
                f'<div class="table-wrap"><table><thead><tr><th>时间</th><th>用户</th><th>动作</th></tr></thead><tbody>{audit_html}</tbody></table></div>'
                f'<div class="dialog-actions"><button type="button" class="ghost" data-dialog-close>关闭</button></div></dialog>'
            )
            rows.append(
                f'<tr class="file-manager-file-row"><td><div class="doc-file file-manager-file-name"><strong>{esc(file_path.name)}</strong><span class="file-manager-file-meta">{esc(file_path.suffix.lower() or "file")}</span></div></td>'
                f'<td>{esc(module_folder)}</td><td>{file_manager_marker_tag(marker)}{marker_note}</td>'
                f'<td>{esc(file_size_label(stat.st_size))}</td><td>{esc(display_datetime(datetime.fromtimestamp(stat.st_mtime).isoformat()))}</td>'
                f'<td>{esc(student_record["student_id"] if student_record else "")}</td><td>{esc(doc["document_type"] if doc else "")}</td>'
                f'<td>{esc(doc["uploaded_by_name"] if doc else "")}</td><td class="path-cell file-manager-file-path"><code>{esc(str(file_path))}</code></td>'
                f'<td><div class="row-actions file-manager-file-actions">{preview_button}{download_button}{actions}{log_dialog}</div></td></tr>'
            )
        body = f"""
        <div class="file-manager-page">
        <section class="panel file-manager-panel file-manager-file-panel">
          <div class="panel-head file-manager-header file-manager-toolbar"><div><h2>{esc(module_folder)}</h2><p>文件级操作只创建标记，不改变原始文件路径。</p></div>{upload_box}</div>
          {notice}
          {self.file_manager_breadcrumb(year, student_name, module_folder)}
          <form class="search fm-search file-manager-search" method="get"><input type="hidden" name="year" value="{esc(year)}"><input type="hidden" name="student" value="{esc(student_name)}"><input type="hidden" name="folder" value="{esc(module_folder)}"><input type="hidden" name="filter" value="{esc(filter_status)}"><input name="q" value="{esc(search)}" placeholder="在当前模块文件夹内搜索"><button class="secondary">搜索</button></form>
          <div class="fm-filter-bar file-manager-marker-filters">{filter_links}</div>
          <div class="table-wrap file-manager-table-wrap"><table class="file-manager-file-table"><thead><tr><th>文件</th><th>模块</th><th>标记状态</th><th>大小</th><th>修改时间</th><th>Student ID</th><th>DocumentType</th><th>Uploaded By</th><th>完整路径</th><th>操作</th></tr></thead><tbody>{''.join(rows) or '<tr><td colspan="10" class="empty file-manager-empty-state">当前文件夹没有文件</td></tr>'}</tbody></table></div>
          {preview_dialog_html()}
        </section>
        </div>"""
        return self.send_html(page("文件管理", body, self.user, self.csrf, "file_manager", nas.status()))

    def file_manager_file_actions(self, year, student_name, module_folder, file_name, marker):
        dialog_key = hashlib.sha256(f"{year}/{student_name}/{module_folder}/{file_name}".encode("utf-8")).hexdigest()[:14]
        hidden = (
            f'<input type="hidden" name="csrf" value="{esc(self.csrf)}">'
            f'<input type="hidden" name="year" value="{esc(year)}">'
            f'<input type="hidden" name="student" value="{esc(student_name)}">'
            f'<input type="hidden" name="folder" value="{esc(module_folder)}">'
            f'<input type="hidden" name="file" value="{esc(file_name)}">'
        )
        pieces = []
        if can_file_manager_action(self.user, "mark_delete"):
            pieces.append(f'<button class="ghost" type="button" data-dialog-open="fm-delete-{dialog_key}">标记删除</button><dialog id="fm-delete-{dialog_key}"><form method="post" action="/file-manager/mark">{hidden}<input type="hidden" name="marker_type" value="PendingDelete"><div class="dialog-head"><h2>标记待删除</h2><button type="button" class="icon-button" data-dialog-close>×</button></div><p>此操作不会真正删除文件，只会将文件标记为待删除，并记录操作日志。是否继续？</p><label>原因<input name="reason" placeholder="可选"></label><label>Notes<textarea name="notes" rows="2"></textarea></label><div class="dialog-actions"><button type="button" class="ghost" data-dialog-close>取消</button><button class="danger">确认标记</button></div></form></dialog>')
        if can_file_manager_action(self.user, "mark_move"):
            pieces.append(f'<button class="ghost" type="button" data-dialog-open="fm-move-{dialog_key}">标记移动</button><dialog id="fm-move-{dialog_key}"><form method="post" action="/file-manager/mark">{hidden}<input type="hidden" name="marker_type" value="PendingMove"><div class="dialog-head"><h2>标记待移动</h2><button type="button" class="icon-button" data-dialog-close>×</button></div><p>此操作不会真正移动文件，只会记录建议移动目标。</p><label>Suggested target folder<input name="suggested_target_folder" required></label><label>原因<input name="reason" placeholder="可选"></label><label>Notes<textarea name="notes" rows="2"></textarea></label><div class="dialog-actions"><button type="button" class="ghost" data-dialog-close>取消</button><button class="primary">确认标记</button></div></form></dialog>')
        if can_file_manager_action(self.user, "mark_rename"):
            pieces.append(f'<button class="ghost" type="button" data-dialog-open="fm-rename-{dialog_key}">标记重命名</button><dialog id="fm-rename-{dialog_key}"><form method="post" action="/file-manager/mark">{hidden}<input type="hidden" name="marker_type" value="PendingRename"><div class="dialog-head"><h2>标记待重命名</h2><button type="button" class="icon-button" data-dialog-close>×</button></div><p>此操作不会真正重命名文件，只会记录建议新文件名。</p><label>Suggested new filename<input name="suggested_new_filename" required></label><label>原因<input name="reason" placeholder="可选"></label><label>Notes<textarea name="notes" rows="2"></textarea></label><div class="dialog-actions"><button type="button" class="ghost" data-dialog-close>取消</button><button class="primary">确认标记</button></div></form></dialog>')
        if marker and marker["marker_status"] == "Active":
            if can_file_manager_action(self.user, "cancel_file_marker"):
                pieces.append(f'<form method="post" action="/file-manager/markers/{marker["id"]}/cancel"><input type="hidden" name="csrf" value="{esc(self.csrf)}"><input name="reason" placeholder="取消原因"><button class="ghost">取消标记</button></form>')
            if can_file_manager_action(self.user, "mark_file_marker_processed"):
                pieces.append(f'<form method="post" action="/file-manager/markers/{marker["id"]}/processed"><input type="hidden" name="csrf" value="{esc(self.csrf)}"><input name="notes" placeholder="处理说明"><button class="secondary">标记已处理</button></form>')
        return "".join(pieces)

    def file_manager_upload(self, method):
        if method != "POST":
            return self.error_page("上传请求无效。", 405)
        if not can_file_manager_action(self.user, "upload"):
            return self.file_manager_access_denied("无权限在文件管理中上传。")
        try:
            year = str(self.form.get("year", ""))
            student_name = str(self.form.get("student", ""))
            module_folder = str(self.form.get("folder", ""))
            root, folder_path, student_name, module_folder = file_manager_resolve(year, student_name, module_folder)
        except NasSafetyError as exc:
            return self.error_page(str(exc), 400)
        module = FILE_MANAGER_UPLOAD_MODULES.get(module_folder)
        if not module:
            return self.flash_redirect(f"/file-manager?year={quote(year)}&student={quote(student_name)}&folder={quote(module_folder)}", "此模块请从对应业务页面上传。", "error")
        student = file_manager_student_for_folder(folder_path.parent)
        if not student:
            return self.flash_redirect(f"/file-manager?year={quote(year)}&student={quote(student_name)}&folder={quote(module_folder)}", "该学生文件夹未关联 CRM 学生记录，不能进入 Upload Review。", "error")
        uploads = [item for item in self.files if item.field_name == "files" and item.filename]
        if not uploads:
            return self.flash_redirect(f"/file-manager?year={quote(year)}&student={quote(student_name)}&folder={quote(module_folder)}", "请选择文件。", "error")
        token = create_upload_review(student["student_id"], module, uploads, self.user, self.form)
        db.audit(self.user, "file_uploaded", "file_manager", student["student_id"], file_path=str(folder_path), student_id=student["student_id"], ip=self.client_address[0], device=self.headers.get("User-Agent"))
        return self.redirect(f"/students/{student['student_id']}/upload-review/{quote(token)}")

    def file_manager_preview(self, method):
        if method != "GET" or not can_file_manager_action(self.user, "view"):
            return self.file_manager_access_denied("无权限预览文件。")
        try:
            year = (self.query.get("year") or [""])[0]
            student_name = (self.query.get("student") or [""])[0]
            module_folder = (self.query.get("folder") or [""])[0]
            file_name = (self.query.get("file") or [""])[0]
            _root, file_path, _student_name, _module_folder = file_manager_resolve(year, student_name, module_folder, file_name)
        except NasSafetyError as exc:
            return self.text(str(exc), 400)
        if not file_path.is_file():
            return self.text("Not found", 404)
        try:
            page_number = max(1, int((self.query.get("page") or ["1"])[0]))
        except ValueError:
            page_number = 1
        size = "large" if (self.query.get("size") or [""])[0] == "large" else "thumb"
        data = file_path.read_bytes()
        total_pages = 1
        if file_path.suffix.lower() == ".pdf":
            try:
                total_pages = max(1, pdf_page_count(data, max_pages=None))
                page_number = max(1, min(total_pages, page_number))
            except Exception:
                total_pages = 1
        preview_id = "fm_" + hashlib.sha256(str(file_path).encode("utf-8")).hexdigest()[:24]
        preview_path = make_preview(preview_id, file_path.name, data, mimetypes.guess_type(file_path.name)[0] or "", size=size, page=page_number)
        target = Path(preview_path).resolve()
        if PREVIEW_DIR.resolve() not in target.parents or not target.is_file():
            return self.text("Not found", 404)
        db.audit(self.user, "file_previewed", "file_manager", record_id=file_path.name, file_path=str(file_path), ip=self.client_address[0], device=self.headers.get("User-Agent"))
        payload = target.read_bytes()
        self.send_response(200)
        self.send_header("Content-Type", "image/png")
        self.send_header("Content-Length", str(len(payload)))
        self.send_header("Cache-Control", "no-cache")
        self.send_header("X-Preview-Page", str(page_number))
        self.send_header("X-Preview-Page-Count", str(total_pages))
        self.end_headers()
        self.wfile.write(payload)

    def file_manager_download(self, method):
        if method != "GET" or not can_file_manager_action(self.user, "download"):
            return self.file_manager_access_denied("无权限下载文件。")
        try:
            year = (self.query.get("year") or [""])[0]
            student_name = (self.query.get("student") or [""])[0]
            module_folder = (self.query.get("folder") or [""])[0]
            file_name = (self.query.get("file") or [""])[0]
            _root, file_path, _student_name, _module_folder = file_manager_resolve(year, student_name, module_folder, file_name)
        except NasSafetyError as exc:
            return self.error_page(str(exc), 400)
        if not file_path.is_file():
            return self.error_page("文件不存在。", 404)
        db.audit(self.user, "file_downloaded", "file_manager", record_id=file_path.name, file_path=str(file_path), ip=self.client_address[0], device=self.headers.get("User-Agent"))
        payload = file_path.read_bytes()
        self.send_response(200)
        self.send_header("Content-Type", mimetypes.guess_type(file_path.name)[0] or "application/octet-stream")
        self.send_header("Content-Disposition", f"attachment; filename*=UTF-8''{quote(file_path.name)}")
        self.send_header("Content-Length", str(len(payload)))
        self.end_headers()
        self.wfile.write(payload)

    def file_manager_mark(self, method):
        if method != "POST":
            return self.error_page("标记请求无效。", 405)
        marker_type = str(self.form.get("marker_type", "")).strip()
        permission = {
            "PendingDelete": "mark_delete",
            "PendingMove": "mark_move",
            "PendingRename": "mark_rename",
        }.get(marker_type)
        if not permission or not can_file_manager_action(self.user, permission):
            return self.file_manager_access_denied("无权限创建此文件标记。")
        try:
            year = str(self.form.get("year", ""))
            student_name = str(self.form.get("student", ""))
            module_folder = str(self.form.get("folder", ""))
            file_name = str(self.form.get("file", ""))
            _root, file_path, _student_name, module_folder = file_manager_resolve(year, student_name, module_folder, file_name)
        except NasSafetyError as exc:
            return self.error_page(str(exc), 400)
        if not file_path.is_file():
            return self.error_page("文件不存在。", 404)
        student = file_manager_student_for_folder(file_path.parent.parent)
        suggested_target = str(self.form.get("suggested_target_folder", "")).strip()
        suggested_name = str(self.form.get("suggested_new_filename", "")).strip()
        reason = str(self.form.get("reason", "")).strip()
        notes = str(self.form.get("notes", "")).strip()
        if marker_type == "PendingMove" and not suggested_target:
            return self.flash_redirect(f"/file-manager?year={quote(year)}&student={quote(student_name)}&folder={quote(module_folder)}", "请填写建议移动目标。", "error")
        if marker_type == "PendingRename" and not suggested_name:
            return self.flash_redirect(f"/file-manager?year={quote(year)}&student={quote(student_name)}&folder={quote(module_folder)}", "请填写建议新文件名。", "error")
        marker_id = db.execute(
            """INSERT INTO file_action_markers(
               student_id,file_path,file_name,module_folder,marker_type,marker_status,
               suggested_target_folder,suggested_new_filename,reason,notes,created_by,created_at
            ) VALUES(?,?,?,?,?,'Active',?,?,?,?,?,?)""",
            (
                student["student_id"] if student else "",
                str(file_path), file_path.name, module_folder, marker_type,
                suggested_target, suggested_name, reason, notes, self.user["id"], now_iso(),
            ),
        )
        db.audit(
            self.user, FILE_MANAGER_MARKER_ACTIONS[marker_type], "file_manager", marker_id, str(file_path),
            new_value=file_manager_audit_value(marker_type=marker_type, new_status="Active", suggested_target_folder=suggested_target, suggested_new_filename=suggested_name, reason=reason, notes=notes),
            student_id=student["student_id"] if student else "", ip=self.client_address[0], device=self.headers.get("User-Agent"),
        )
        return self.flash_redirect(f"/file-manager?year={quote(year)}&student={quote(student_name)}&folder={quote(module_folder)}", "文件已标记，原文件未被修改。")

    def file_manager_marker_status(self, method, marker_id, status_action):
        if method != "POST":
            return self.error_page("标记状态请求无效。", 405)
        permission = "cancel_file_marker" if status_action == "cancel" else "mark_file_marker_processed"
        if not can_file_manager_action(self.user, permission):
            return self.file_manager_access_denied("无权限处理文件标记。")
        marker = db.one("SELECT * FROM file_action_markers WHERE id=?", (marker_id,))
        if not marker:
            return self.error_page("文件标记不存在。", 404)
        if marker["marker_status"] != "Active":
            return self.flash_redirect("/file-manager", "该标记已经处理过。", "error")
        new_status = "Cancelled" if status_action == "cancel" else "Processed"
        reason = str(self.form.get("reason", "")).strip()
        notes = str(self.form.get("notes", "")).strip()
        if new_status == "Cancelled":
            db.execute(
                "UPDATE file_action_markers SET marker_status='Cancelled',cancelled_by=?,cancelled_at=?,notes=? WHERE id=?",
                (self.user["id"], now_iso(), reason or notes or marker["notes"], marker_id),
            )
            action = "file_marker_cancelled"
        else:
            db.execute(
                "UPDATE file_action_markers SET marker_status='Processed',processed_by=?,processed_at=?,notes=? WHERE id=?",
                (self.user["id"], now_iso(), notes or marker["notes"], marker_id),
            )
            action = "file_marker_marked_processed"
        db.audit(
            self.user, action, "file_manager", marker_id, marker["file_path"],
            old_value=file_manager_audit_value(old_status="Active"),
            new_value=file_manager_audit_value(new_status=new_status, reason=reason, notes=notes),
            student_id=marker["student_id"], ip=self.client_address[0], device=self.headers.get("User-Agent"),
        )
        try:
            root = file_manager_root()
            path = ensure_within(marker["file_path"], root)
            student_name = path.parent.parent.name
            module_folder = path.parent.name
            return self.flash_redirect(f"/file-manager?year={quote(root.name)}&student={quote(student_name)}&folder={quote(module_folder)}", "文件标记状态已更新。")
        except Exception:
            return self.flash_redirect("/file-manager", "文件标记状态已更新。")

    def parent_form_login_required_page(self, token, token_row):
        body = parent_form_login(
            token,
            display_datetime(token_row["expires_at"]),
            oauth_enabled=self.school_plan_wechat_oauth_enabled(),
        )
        return self.send_html(page("微信验证", body))

    def parent_form_authenticated_openid(self, token):
        binding = ParentFormRepository(db).get_binding(token)
        if not binding:
            return ""
        cookie = SimpleCookie(self.headers.get("Cookie", ""))
        morsel = cookie.get(parent_form_cookie_name(token))
        if not morsel:
            return ""
        openid = str(binding["bound_wechat_openid"] or "")
        expected = parent_form_cookie_value(
            token,
            openid,
            SECRET_PATH.read_bytes().strip(),
        )
        return openid if safe_compare(morsel.value, expected) else ""

    def parent_form_auth_cookie(self, token, openid, expires_at):
        expires = parse_local_datetime(expires_at)
        remaining = int((expires - datetime.now().astimezone()).total_seconds()) if expires else 0
        max_age = max(0, min(604800, remaining))
        value = parent_form_cookie_value(
            token,
            openid,
            SECRET_PATH.read_bytes().strip(),
        )
        return (
            f"{parent_form_cookie_name(token)}={value}; Path=/; HttpOnly; "
            f"SameSite=Lax; Max-Age={max_age}"
        )

    def parent_form_wechat_oauth_start(self, token, token_row):
        state = new_token(24)
        expires_at = (datetime.now().astimezone() + timedelta(minutes=10)).isoformat(timespec="seconds")
        callback_url = self.school_plan_wechat_oauth_callback_url()
        db.set_setting(
            wechat_oauth_state_setting_key(state),
            json.dumps({
                "state": state,
                "purpose": "parent_form",
                "token": token,
                "return_url": f"/parent-form/{token}",
                "callback_url": callback_url,
                "created_at": now_iso(),
                "expires_at": expires_at,
            }, ensure_ascii=False),
            None,
        )
        auth_url = "https://open.weixin.qq.com/connect/oauth2/authorize?" + urlencode({
            "appid": wechat_setting_value(WECHAT_APP_ID_SETTING),
            "redirect_uri": callback_url,
            "response_type": "code",
            "scope": wechat_oauth_scope(),
            "state": state,
        }) + "#wechat_redirect"
        append_service_log(
            "parent",
            "parent_form_wechat_oauth_started",
            token_last4=str(token)[-4:],
            expires_at=token_row["expires_at"],
        )
        return self.redirect(auth_url)

    def parent_form_wechat_login(self, method, token):
        token_row = ParentFormRepository(db).get_link(token)
        status = parent_token_status(token_row)
        if status != "Pending":
            title, message = parent_token_problem_message(status)
            return self.parent_result_page(title, message, HTTPStatus.GONE)
        if method != "POST":
            if self.school_plan_wechat_oauth_enabled():
                return self.parent_form_wechat_oauth_start(token, token_row)
            return self.parent_form_login_required_page(token, token_row)

        form, _files = parse_request_body(self)
        nickname = str(form.get("wechat_nickname") or "").strip() or "微信家长"
        openid = re.sub(r"[^A-Za-z0-9_\-]", "", str(form.get("wechat_openid") or "").strip())
        if not openid:
            openid = "dev_" + hashlib.sha256(
                f"{nickname}|{self.client_address[0]}".encode("utf-8")
            ).hexdigest()[:16]
        try:
            secure_parent_form_service().bind_wechat(
                token,
                {"openid": openid, "nickname": nickname},
            )
        except ParentFormIdentityMismatch:
            return self.parent_result_page(
                "微信身份不一致",
                "该表单链接已绑定其他微信身份，请联系 AAIE 顾问重新发送。",
                HTTPStatus.FORBIDDEN,
            )
        cookie = self.parent_form_auth_cookie(token, openid, token_row["expires_at"])
        return self.redirect(f"/parent-form/{quote(token)}", cookie=cookie)

    def parent_links(self, method):
        if not self.require("students.edit"):
            return
        status_filter = (self.query.get("status") or [""])[0]
        if status_filter not in {"", "Pending", "Submitted", "Expired", "Revoked"}:
            status_filter = ""
        if method == "POST":
            try:
                link = secure_parent_form_service().create_link(
                    consultant_id=int(self.form.get("consultant_id") or self.user["id"]),
                    student_hint=self.form.get("student_hint", ""),
                    created_by=self.user["id"],
                    intake_type=self.form.get("intake_type"),
                )
            except ParentFormIntakeTypeInvalid:
                return self.flash_redirect(
                    "/parent-links", "请选择申请类型后再生成家长链接。", "error"
                )
            token = link.token
            db.audit(self.user, "create", "parent_form_tokens", token)
            new_parent_link = parent_form_url(token)
            return self.toast_redirect(
                "/parent-links",
                f"家长链接已生成：{new_parent_link}",
                title="家长链接已生成",
                copy_text=new_parent_link,
            )
        consultants = db.all("SELECT id,display_name FROM users WHERE is_active=1 ORDER BY display_name")
        options = "".join(f'<option value="{u["id"]}" {"selected" if u["id"] == self.user["id"] else ""}>{esc(u["display_name"])}</option>' for u in consultants)
        links = db.all(
            """SELECT t.*,u.display_name consultant_name,
                      CASE WHEN b.token IS NULL THEN 0 ELSE 1 END wechat_bound,
                      b.bound_wechat_openid,b.bound_wechat_nickname,b.bound_at,
                      d.revision draft_revision,d.last_saved_at draft_last_saved_at
               FROM parent_form_tokens t
               LEFT JOIN users u ON u.id=t.consultant_id
               LEFT JOIN parent_form_access_bindings b ON b.token=t.token
               LEFT JOIN parent_form_drafts d ON d.token=t.token
               ORDER BY t.created_at DESC LIMIT 100"""
        )
        repository = ParentFormRepository(db)
        access_summaries = repository.access_event_summaries(
            [item["token"] for item in links]
        )
        rows = []
        mobile_items = []
        for item in links:
            item_intake_type = (
                item["intake_type"] if "intake_type" in item.keys() else None
            )
            status = parent_token_status(item)
            if status_filter and status != status_filter:
                continue
            url = parent_form_url(item["token"])
            student_cell = f'<a href="/students/{esc(item["student_id"])}">{esc(item["student_id"])}</a>' if item["student_id"] else ""
            wechat_cell = render_parent_form_access_summary(
                item,
                access_summaries.get(item["token"]),
                f'/parent-links/{quote(str(item["token"]), safe="")}/access-history',
            )
            if status == "Submitted":
                draft_cell = '<span class="status ok">已递交</span>'
            elif item["draft_revision"]:
                saved_label = display_datetime(item["draft_last_saved_at"])
                draft_cell = f'<span class="status info">填写中</span><small>最后保存：{esc(saved_label)}</small>'
            else:
                draft_cell = '<span class="status">尚未填写</span>'
            actions = f'<button class="copy-button" type="button" data-copy="{esc(url)}">复制链接</button>'
            if status in ("Pending", "Expired", "Revoked"):
                regenerate_type_control = (
                    '<label>申请类型<select name="intake_type" required>'
                    '<option value="">请选择</option>'
                    '<option value="ordinary_new_application">普通新申请</option>'
                    '<option value="new_student_transfer">新学生转学</option>'
                    '</select></label>'
                    if item_intake_type is None
                    else f'<input type="hidden" name="intake_type" value="{esc(item_intake_type)}">'
                )
                actions += f'<form method="post" action="/parent-links/{esc(item["token"])}/regenerate"><input type="hidden" name="csrf" value="{esc(self.csrf)}">{regenerate_type_control}<button class="secondary">重新生成</button></form>'
            if item_intake_type is not None:
                correction_options = "".join(
                    f'<option value="{esc(value)}" {"selected" if item_intake_type == value else ""}>{esc(label)}</option>'
                    for value, label in (
                        ("ordinary_new_application", "普通新申请"),
                        ("new_student_transfer", "新学生转学"),
                    )
                )
                actions += (
                    f'<form method="post" action="/parent-links/{esc(item["token"])}/intake-type">'
                    f'<input type="hidden" name="csrf" value="{esc(self.csrf)}">'
                    f'<label>申请类型<select name="intake_type">{correction_options}</select></label>'
                    '<button class="ghost">纠正类型</button></form>'
                )
            if status == "Pending":
                actions += f'<form method="post" action="/parent-links/{esc(item["token"])}/revoke"><input type="hidden" name="csrf" value="{esc(self.csrf)}"><button class="ghost">撤销</button></form>'
            mobile_items.append({
                "name": item["student_hint"] or "未命名",
                "token": item["token"],
                "expires_at": item["expires_at"][:10],
                "status": status,
                "wechat_html": wechat_cell,
                "draft_html": draft_cell,
                "consultant_name": item["consultant_name"],
                "created_at": item["created_at"][:16].replace("T", " "),
                "student_html": student_cell,
                "actions_html": actions,
            })
            rows.append(
                f'<tr><td><code>{esc(item["token"])}</code><small>{esc(item["student_hint"] or "未命名")}</small></td>'
                f'<td>{esc(item["expires_at"][:10])}</td><td><span class="status link-status-{status.lower()} {parent_token_status_class(status)}">{esc(status)}</span></td>'
                f'<td>{wechat_cell}</td><td>{draft_cell}</td><td>{esc(item["consultant_name"])}</td><td>{esc(item["created_at"][:16].replace("T"," "))}</td><td>{student_cell}</td>'
                f'<td class="row-actions">{actions}</td></tr>'
            )
        status_tabs = "".join(
            f'<a class="{"active" if status_filter == key else ""}" href="/parent-links{("?status=" + esc(key)) if key else ""}">{esc(label)}</a>'
            for key, label in [
                ("", "全部链接"),
                ("Pending", "待提交"),
                ("Submitted", "已提交"),
                ("Expired", "已过期"),
                ("Revoked", "已撤销"),
            ]
        )
        is_mobile_view = getattr(self, "headers", None) is not None and self.request_view_mode() == MOBILE_MODE
        if is_mobile_view:
            recent_links_content = render_recent_link_cards(mobile_items)
        else:
            desktop_rows = "".join(rows) or '<tr><td colspan="9" class="empty">没有符合条件的链接</td></tr>'
            recent_links_content = (
                '<div class="table-wrap parent-links-table-wrap"><table class="parent-links-table">'
                '<thead><tr><th>Token</th><th>有效期</th><th>链接状态</th><th>微信绑定</th><th>草稿状态</th><th>创建人</th><th>创建时间</th><th>提交状态</th><th>操作</th></tr></thead>'
                f'<tbody>{desktop_rows}</tbody>'
                '</table></div>'
            )
        copy_parent_link = str((self.query.get("copy_parent_link") or [""])[0]).strip()
        parent_link_auto_copy_notice = ""
        if copy_parent_link:
            parent_link_auto_copy_notice = f"""
            <div class="notice success parent-link-auto-copy">
              <span>链接已生成，正在尝试自动复制到剪贴板。</span>
              <button class="copy-button secondary compact" type="button" data-copy="{esc(copy_parent_link)}" data-auto-copy data-auto-copy-success="链接已生成并复制，可以直接发送给家长。" data-auto-copy-failure="链接已生成，请手动复制。">复制家长链接</button>
            </div>"""
        body = f"""<div class="parent-links-page">
        {parent_link_auto_copy_notice}
        <section class="panel parent-link-create-panel">
          <div class="panel-head"><div><h2>生成一次性链接</h2><p>填写学生提示和负责顾问后生成家长表单链接；有效期固定 7 天。</p></div><span class="status info">Parent Form</span></div>
          <form method="post" action="/parent-links" class="parent-link-create-form">
            <input type="hidden" name="csrf" value="{esc(self.csrf)}">
            <label>学生姓名提示<input name="student_hint" placeholder="例如 Jesse Zhang"></label>
            <label>负责顾问<select name="consultant_id">{options}</select></label>
            <label>申请类型<select name="intake_type" required><option value="">请选择</option><option value="ordinary_new_application">普通新申请</option><option value="new_student_transfer">新学生转学</option></select></label>
            <label>有效期<input value="固定 7 天" readonly aria-readonly="true"></label>
            <button class="primary">生成链接</button>
          </form>
          <p class="muted-line">当前家长端地址：<code>{esc(parent_form_base_url())}</code></p>
        </section>
        <section class="panel parent-links-recent-panel"><div class="panel-head"><div><h2>最近链接</h2><p>提交后自动失效；工作台只统计“待提交且未过期”的链接。</p></div></div><div class="link-status-tabs">{status_tabs}</div>{recent_links_content}</section></div>"""
        message, kind = self.message()
        self.send_html(page("家长表单链接", body, self.user, self.csrf, "links", nas.status(), message, kind))

    def parent_link_access_history(self, method, token):
        if method != "GET":
            return self.error_page("访问记录页面只支持查看。", HTTPStatus.METHOD_NOT_ALLOWED)
        if not self.require("students.edit"):
            return
        repository = ParentFormRepository(db)
        link = repository.get_link(token)
        if not link:
            return self.error_page("家长表单链接不存在。", HTTPStatus.NOT_FOUND)
        consultant = db.one(
            "SELECT display_name FROM users WHERE id=?",
            (link["consultant_id"],),
        )
        body = render_parent_form_access_history(
            link,
            repository.get_binding(token),
            repository.list_access_events(token),
            status=parent_token_status(link),
            consultant_name=(consultant["display_name"] if consultant else "—"),
        )
        return self.send_html(
            page(
                "家长表单访问记录",
                body,
                self.user,
                self.csrf,
                "links",
                nas.status(),
            )
        )

    def parent_link_revoke(self, method, token):
        if method != "POST" or not self.require("students.edit"):
            return
        row = db.one("SELECT * FROM parent_form_tokens WHERE token=?", (token,))
        if not row:
            return self.flash_redirect("/parent-links", "链接不存在", "error")
        if row["submitted_at"]:
            return self.flash_redirect("/parent-links", "已提交的链接不能撤销", "error")
        if not ParentFormRepository(db).invalidate_if_writable(token, now_iso()):
            return self.flash_redirect("/parent-links", "链接已撤销或已经提交", "error")
        db.audit(self.user, "revoke", "parent_form_tokens", token)
        return self.flash_redirect("/parent-links", "链接已撤销")

    def parent_link_regenerate(self, method, token):
        if method != "POST" or not self.require("students.edit"):
            return
        row = db.one("SELECT * FROM parent_form_tokens WHERE token=?", (token,))
        if not row:
            return self.flash_redirect("/parent-links", "链接不存在", "error")
        try:
            regenerated = secure_parent_form_service().regenerate_link(
                token,
                self.user["id"],
                intake_type=self.form.get("intake_type"),
            )
        except ParentFormIntakeTypeInvalid:
            return self.flash_redirect(
                "/parent-links", "历史链接必须明确选择申请类型后才能重新生成。", "error"
            )
        except ParentFormSubmitted:
            return self.flash_redirect("/parent-links", "已提交的链接不能重新生成", "error")
        new_form_token = regenerated.token
        db.audit(self.user, "regenerate", "parent_form_tokens", new_form_token, old_value=token)
        new_parent_link = parent_form_url(new_form_token)
        return self.toast_redirect(
            "/parent-links",
            f"新家长链接已生成：{new_parent_link}",
            title="家长链接已生成",
            copy_text=new_parent_link,
        )

    def parent_link_intake_type_correct(self, method, token):
        if method != "POST" or not self.require("students.edit"):
            return
        try:
            corrected = secure_parent_form_service().correct_intake_type(
                token,
                self.form.get("intake_type"),
                changed_by=self.user["id"],
            )
        except ParentFormNotFound:
            return self.flash_redirect("/parent-links", "链接不存在", "error")
        except ParentFormIntakeTypeInvalid:
            return self.flash_redirect(
                "/parent-links", "历史未分类链接不能原地纠正；重新生成时请明确选择申请类型。", "error"
            )
        except ParentFormIntakeCorrectionBlocked:
            return self.flash_redirect(
                "/parent-links", "正式业务已经开始，申请类型已锁定，不能修改。", "error"
            )
        db.audit(
            self.user,
            "parent_intake_type_corrected",
            "parent_form_tokens",
            token,
            new_value=corrected.intake_type,
        )
        return self.flash_redirect("/parent-links", "申请类型已纠正。")

    def parent_result_page(self, title, message, status=200, *, tone=None, details=()):
        resolved_tone = tone or ("danger" if int(status) >= 500 else "warning")
        body = parent_form_result(title, message, tone=resolved_tone, details=details)
        return self.send_html(page(title, body), status)

    def parent_form_request_wants_json(self):
        accept = str(self.headers.get("Accept", "") or "").lower()
        requested_with = str(self.headers.get("X-Requested-With", "") or "").lower()
        return "application/json" in accept or requested_with == "fetch"

    def parent_form_submit_json_response(self, ok, status=200, **payload):
        payload["ok"] = bool(ok)
        return self.json_response(payload, status)

    def parent_form_link_error_message(self, status):
        if status == "Submitted":
            return "该表单已经提交过，不能重复提交。"
        return "该表单链接已失效，请联系顾问重新发送。"

    def school_plan_share_login_required_page(self, token, link):
        student_name = " ".join(part for part in [link["passport_first_name"], link["passport_last_name"]] if part) or link["student_id"]
        oauth_enabled = self.school_plan_wechat_oauth_enabled()
        if not oauth_enabled and getattr(STAGING, "mode", None) == "production":
            return self.school_plan_share_public_page(
                "微信验证暂不可用",
                "<h1>微信验证暂不可用</h1><p>请联系 AAIE 顾问处理后重新打开原链接。</p>",
                HTTPStatus.SERVICE_UNAVAILABLE,
            )
        if oauth_enabled:
            auth_control = f"""
            <div class="share-actions"><a class="button-link" href="/school-plan-share/{esc(token)}/wechat-login">微信验证后查看方案</a></div>
            <p class="muted-line">请在微信中打开此链接完成身份验证。首次查看后，本链接将绑定当前微信身份。</p>
            """
        else:
            auth_control = f"""
            <form method="post" action="/school-plan-share/{esc(token)}/wechat-login">
              <label>昵称<input name="wechat_nickname" placeholder="请输入昵称" required></label>
              <label>访问识别码<input name="wechat_openid" placeholder="请设置一个便于记住的识别码" required><small>后续访问请使用相同识别码。</small></label>
              <div class="share-actions"><button type="submit">确认身份并查看</button></div>
            </form>
            <p class="muted-line">请记住本次填写的身份信息，以便再次查看方案。</p>
            """
        identity_title = "请先完成微信身份验证" if oauth_enabled else "请先完成身份确认"
        identity_note = (
            "该学校方案为客户专属文件。每位授权家长将使用自己的专属链接查看报告。首次查看后，本链接将绑定当前微信身份，之后仅允许同一微信继续查看。"
            if oauth_enabled else
            "该学校方案为客户专属文件。每位授权家长将使用自己的专属链接查看报告。首次确认后，本链接将绑定当前身份，之后请使用相同身份信息继续查看。"
        )
        body = f"""
        <div class="share-brand"><div><strong>AAIE School Advisory Report</strong><small>Secure parent access</small></div><small>有效期至<br>{esc(display_datetime(link['expires_at']))}</small></div>
        <h1>{identity_title}</h1>
        <p>{identity_note}</p>
        <div class="viewer-lock-note">当前方案：{esc(student_name)} · v{esc(link['report_version'])}</div>
        {auth_control}
        """
        return self.school_plan_share_public_page("微信验证" if oauth_enabled else "身份确认", body)

    def school_plan_share_wechat_oauth_start(self, token, link):
        state = new_token(24)
        expires_at = (datetime.now().astimezone() + timedelta(minutes=10)).isoformat(timespec="seconds")
        callback_url = self.school_plan_wechat_oauth_callback_url()
        db.set_setting(
            wechat_oauth_state_setting_key(state),
            json.dumps({
                "state": state,
                "report_id": link["report_id"],
                "viewer_id": link["viewer_id"],
                "link_id": link["id"],
                "token": token,
                "return_url": f"/school-plan-share/{token}",
                "callback_url": callback_url,
                "created_at": now_iso(),
                "expires_at": expires_at,
            }, ensure_ascii=False),
            None,
        )
        auth_url = "https://open.weixin.qq.com/connect/oauth2/authorize?" + urlencode({
            "appid": wechat_setting_value(WECHAT_APP_ID_SETTING),
            "redirect_uri": callback_url,
            "response_type": "code",
            "scope": wechat_oauth_scope(),
            "state": state,
        }) + "#wechat_redirect"
        self.school_plan_share_record_log(link, "wechat_oauth_started", metadata={"scope": wechat_oauth_scope(), "callback_url": callback_url})
        return self.redirect(auth_url)

    def school_plan_share_wechat_login(self, method, token):
        link = self.school_plan_share_row_by_token(token)
        title, message, status = self.school_plan_share_status_problem(link)
        if status != 200:
            return self.school_plan_share_public_page(title, f"<h1>{esc(title)}</h1><p>{esc(message)}</p>", status)
        if self.school_plan_wechat_oauth_enabled():
            return self.school_plan_share_wechat_oauth_start(token, link)
        if method != "POST" or getattr(STAGING, "mode", None) == "production":
            return self.school_plan_share_login_required_page(token, link)
        form, _files = parse_request_body(self)
        nickname = str(form.get("wechat_nickname") or "").strip() or "微信家长"
        openid = re.sub(r"[^A-Za-z0-9_\-]", "", str(form.get("wechat_openid") or "").strip())
        if not openid:
            openid = "dev_" + hashlib.sha256(f"{nickname}|{self.client_address[0]}".encode("utf-8")).hexdigest()[:16]
        link, blocked_response = self.school_plan_bind_wechat_identity(link, openid, nickname)
        if blocked_response:
            return blocked_response
        cookie_value = self.school_plan_share_cookie_value(link, openid)
        cookie = f"{self.school_plan_share_cookie_name(link['id'])}={cookie_value}; Path=/; HttpOnly; SameSite=Lax; Max-Age=604800"
        return self.redirect(f"/school-plan-share/{quote(token)}", cookie=cookie)

    def school_plan_wechat_oauth_callback(self, method):
        if method != "GET":
            return self.school_plan_share_public_page("无法完成操作", "<h1>无法完成操作</h1><p>微信回调请求无效。</p>", HTTPStatus.METHOD_NOT_ALLOWED)
        error = (self.query.get("error") or [""])[0].strip()
        code = (self.query.get("code") or [""])[0].strip()
        state = (self.query.get("state") or [""])[0].strip()
        if error:
            return self.school_plan_share_public_page("微信验证失败", f"<h1>微信验证失败</h1><p>{esc(error)}</p>", HTTPStatus.FORBIDDEN)
        try:
            state_payload = json.loads(str(db.setting(wechat_oauth_state_setting_key(state), "{}") or "{}"))
        except json.JSONDecodeError:
            state_payload = {}
        expected_state = str(state_payload.get("state") or "")
        created_at = parse_local_datetime(state_payload.get("created_at"))
        expires_at = parse_local_datetime(state_payload.get("expires_at"))
        if not code or not state or not expected_state or not safe_compare(state, expected_state):
            return self.school_plan_share_public_page("微信验证失败", "<h1>微信验证失败</h1><p>授权安全校验失败，请联系 AAIE 顾问重新发送链接。</p>", HTTPStatus.FORBIDDEN)
        if (expires_at and datetime.now().astimezone() > expires_at) or (created_at and datetime.now().astimezone() - created_at > timedelta(minutes=10)):
            return self.school_plan_share_public_page("微信验证超时", "<h1>微信验证超时</h1><p>请重新打开 AAIE 提供的方案链接。</p>", HTTPStatus.GONE)
        if state_payload.get("purpose") == "wechat_settings_test":
            return self.school_plan_wechat_oauth_test_callback(state_payload, code)
        if state_payload.get("purpose") == "parent_form":
            token = str(state_payload.get("token") or "").strip()
            token_row = ParentFormRepository(db).get_link(token)
            status = parent_token_status(token_row)
            if status != "Pending":
                title, message = parent_token_problem_message(status)
                return self.parent_result_page(title, message, HTTPStatus.GONE)
            try:
                token_data = wechat_exchange_oauth_code(code)
            except Exception as exc:
                append_service_log(
                    "parent",
                    "parent_form_wechat_oauth_failed",
                    exc.__class__.__name__,
                    token_last4=token[-4:],
                )
                return self.parent_result_page(
                    "微信验证失败",
                    "微信授权未完成，请联系 AAIE 顾问重新发送链接或稍后再试。",
                    HTTPStatus.BAD_GATEWAY,
                )
            openid = str(token_data.get("openid") or "").strip()
            unionid = str(token_data.get("unionid") or "").strip()
            nickname = "已验证用户"
            avatar_url = ""
            if wechat_oauth_scope() == "snsapi_userinfo":
                profile = wechat_fetch_userinfo(token_data.get("access_token"), openid)
                nickname = str(profile.get("nickname") or nickname).strip() or nickname
                unionid = str(profile.get("unionid") or unionid).strip()
                avatar_url = str(profile.get("headimgurl") or "").strip()
            try:
                secure_parent_form_service().bind_wechat(token, {
                    "openid": openid,
                    "unionid": unionid,
                    "nickname": nickname,
                    "avatar_url": avatar_url,
                })
            except ParentFormIdentityMismatch:
                return self.parent_result_page(
                    "微信身份不一致",
                    "该表单链接已绑定其他微信身份，请联系 AAIE 顾问重新发送。",
                    HTTPStatus.FORBIDDEN,
                )
            except ParentFormAuthenticationRequired:
                return self.parent_result_page(
                    "微信验证失败",
                    "微信未返回有效身份，请重新打开链接完成验证。",
                    HTTPStatus.FORBIDDEN,
                )
            cookie = self.parent_form_auth_cookie(token, openid, token_row["expires_at"])
            return self.redirect(f"/parent-form/{quote(token)}", cookie=cookie)
        if state_payload.get("purpose") == "visa_information_collection":
            respondent = db.one("SELECT * FROM visa_information_collection_respondents WHERE id=?", (state_payload.get("respondent_id"),))
            problem = self.visa_information_collection_token_problem(respondent)
            if problem:
                return self.visa_information_collection_public_page(
                    "链接已失效",
                    f"<section class='panel'><h1>链接已失效</h1><p>{esc(problem)}</p></section>",
                    HTTPStatus.GONE,
                )
            try:
                token_data = wechat_exchange_oauth_code(code)
            except Exception as exc:
                self.visa_information_collection_record_log(respondent, "wechat_oauth_failed", metadata={"error": str(exc)})
                return self.visa_information_collection_public_page(
                    "微信验证失败",
                    "<section class='panel'><h1>微信验证失败</h1><p>微信授权未完成，请联系 AAIE 顾问重新发送链接或稍后再试。</p></section>",
                    HTTPStatus.BAD_GATEWAY,
                )
            openid = str(token_data.get("openid") or "").strip()
            unionid = str(token_data.get("unionid") or "").strip()
            nickname = "已验证用户"
            avatar_url = ""
            if wechat_oauth_scope() == "snsapi_userinfo":
                profile = wechat_fetch_userinfo(token_data.get("access_token"), openid)
                nickname = str(profile.get("nickname") or nickname).strip() or nickname
                unionid = str(profile.get("unionid") or unionid).strip()
                avatar_url = str(profile.get("headimgurl") or "").strip()
            respondent, blocked_response = self.visa_information_collection_bind_wechat_identity(respondent, openid, nickname, unionid, avatar_url)
            if blocked_response:
                return blocked_response
            token = str(state_payload.get("token") or "").strip()
            cookie_value = self.visa_information_collection_cookie_value(respondent, openid)
            cookie = f"{self.visa_information_collection_cookie_name(respondent['id'])}={cookie_value}; Path=/; HttpOnly; SameSite=Lax; Max-Age=604800"
            return self.redirect(f"/visa-information-collection/{quote(token)}", cookie=cookie)
        if state_payload.get("purpose") == "contract_signing":
            link = self.contract_signing_row_by_id(state_payload.get("link_id"))
            title, message, status = self.contract_signing_status_problem(link, allow_signed=True)
            if status != 200:
                return self.school_plan_share_public_page(title, f"<h1>{esc(title)}</h1><p>{esc(message)}</p>", status)
            try:
                token_data = wechat_exchange_oauth_code(code)
            except Exception as exc:
                self.contract_signing_record_log(link, "wechat_oauth_failed", {"error": str(exc)})
                return self.school_plan_share_public_page(
                    "微信验证失败",
                    "<h1>微信验证失败</h1><p>微信授权未完成，请联系 AAIE 顾问重新发送链接或稍后再试。</p>",
                    HTTPStatus.BAD_GATEWAY,
                )
            openid = str(token_data.get("openid") or "").strip()
            unionid = str(token_data.get("unionid") or "").strip()
            nickname = "已验证用户"
            avatar_url = ""
            if wechat_oauth_scope() == "snsapi_userinfo":
                profile = wechat_fetch_userinfo(token_data.get("access_token"), openid)
                nickname = str(profile.get("nickname") or nickname).strip() or nickname
                unionid = str(profile.get("unionid") or unionid).strip()
                avatar_url = str(profile.get("headimgurl") or "").strip()
            link, blocked_response = self.contract_signing_bind_wechat_identity(link, openid, nickname, unionid, avatar_url)
            if blocked_response:
                return blocked_response
            token = str(state_payload.get("token") or "").strip()
            cookie_value = self.contract_signing_cookie_value(link, openid)
            cookie = f"{self.contract_signing_cookie_name(link['id'])}={cookie_value}; Path=/; HttpOnly; SameSite=Lax; Max-Age=604800"
            return self.redirect(f"/contract-sign/{quote(token)}", cookie=cookie)
        link = self.school_plan_share_row_by_token_by_id(state_payload.get("link_id"))
        title, message, status = self.school_plan_share_status_problem(link)
        if status != 200:
            return self.school_plan_share_public_page(title, f"<h1>{esc(title)}</h1><p>{esc(message)}</p>", status)
        try:
            token_data = wechat_exchange_oauth_code(code)
        except Exception as exc:
            self.school_plan_share_record_log(link, "wechat_oauth_failed", metadata={"error": str(exc)})
            return self.school_plan_share_public_page(
                "微信验证失败",
                "<h1>微信验证失败</h1><p>微信授权未完成，请联系 AAIE 顾问重新发送链接或稍后再试。</p>",
                HTTPStatus.BAD_GATEWAY,
            )
        openid = str(token_data.get("openid") or "").strip()
        unionid = str(token_data.get("unionid") or "").strip()
        nickname = "已验证用户"
        avatar_url = ""
        if wechat_oauth_scope() == "snsapi_userinfo":
            profile = wechat_fetch_userinfo(token_data.get("access_token"), openid)
            nickname = str(profile.get("nickname") or nickname).strip() or nickname
            unionid = str(profile.get("unionid") or unionid).strip()
            avatar_url = str(profile.get("headimgurl") or "").strip()
        link, blocked_response = self.school_plan_bind_wechat_identity(link, openid, nickname, unionid, avatar_url)
        if blocked_response:
            return blocked_response
        token = str(state_payload.get("token") or "").strip()
        cookie_value = self.school_plan_share_cookie_value(link, openid)
        cookie = f"{self.school_plan_share_cookie_name(link['id'])}={cookie_value}; Path=/; HttpOnly; SameSite=Lax; Max-Age=604800"
        return self.redirect(f"/school-plan-share/{quote(token)}", cookie=cookie)

    def settings_wechat_oauth_check(self, method):
        if method != "GET" or not allowed(self.user, "*"):
            return self.error_page("仅 Admin 可以查看微信接入自检。", HTTPStatus.FORBIDDEN)
        checks = self.wechat_oauth_self_check()

        def row(label, value, ok=None, note=""):
            if ok is None:
                badge = ""
            else:
                badge = f"<strong class=\"{'done' if ok else 'missing'}\">{'通过' if ok else '需处理'}</strong>"
            return f"""
            <tr>
              <th>{esc(label)}</th>
              <td>{value}</td>
              <td>{badge}</td>
              <td>{esc(note)}</td>
            </tr>"""

        rows = "\n".join([
            row("服务号", esc(checks["service_account"]), True, "CRM 正式接入该微信公众号服务号。"),
            row("AppID", esc(checks["app_id_display"]), checks["app_id_ok"], "AppID 可以明文显示。"),
            row("AppSecret", "AppSecret 已配置，不显示明文" if checks["app_secret_ok"] else "未配置", checks["app_secret_ok"], "密钥只从服务端环境变量读取，不进入前端。"),
            row("OAuth callback URL", f"<code>{esc(checks['callback_url'])}</code>", checks["callback_ok"], f"正式应为 {WECHAT_EXPECTED_CALLBACK_URL}"),
            row("OAuth scope", esc(checks["scope"]), checks["scope_ok"], "正式获取昵称和头像需要 snsapi_userinfo。"),
            row("网页授权域名", esc(checks["auth_domain"]), checks["auth_domain_ok"], "微信后台只填域名，不带 https:// 和路径。"),
            row("TXT 校验文件", checks["verify_file_html"], checks["verify_file_ok"], checks["verify_file_note"]),
            row("服务器公网 IP", esc(checks["public_ip_display"]), checks["public_ip_ok"], f"微信 API IP 白名单应为 {WECHAT_EXPECTED_PUBLIC_IP}。"),
        ])
        oauth_button = (
            '<a class="primary button-link" href="/settings/wechat-oauth/test/start">微信授权检查</a>'
            if checks["app_id_ok"] and checks["app_secret_ok"] and checks["callback_ok"]
            else '<span class="button-link disabled">先完成 AppID / AppSecret / Callback 配置</span>'
        )
        body = f"""
        <section class="panel">
          <h2>微信服务号 OAuth 自检</h2>
          <p>用于确认 CRM 正式接入 <strong>{esc(WECHAT_SERVICE_ACCOUNT_NAME)}</strong> 服务号。AppSecret 不会在页面显示，也不会写入前端。</p>
          <div class="row-actions">{oauth_button}<a class="secondary button-link" href="/settings">返回系统设置</a></div>
          <table class="data-table"><tbody>{rows}</tbody></table>
          <p class="muted-line">微信授权检查会跳转到微信网页授权，成功后应返回 openid、昵称和头像状态。请在微信内完成验证。</p>
        </section>
        """
        message, kind = self.message()
        self.send_html(page("微信 OAuth 自检", body, self.user, self.csrf, "settings", None, message, kind))

    def wechat_oauth_self_check(self):
        app_id = wechat_setting_value(WECHAT_APP_ID_SETTING)
        app_secret = wechat_setting_value(WECHAT_APP_SECRET_SETTING)
        callback_url = self.school_plan_wechat_oauth_callback_url()
        scope = wechat_oauth_scope()
        parsed_callback = urlparse(callback_url)
        verify_files = sorted(WECHAT_VERIFY_DIR.glob("MP_verify*.txt"))
        verify_file = verify_files[0] if verify_files else None
        verify_url = f"https://{WECHAT_EXPECTED_AUTH_DOMAIN}/{verify_file.name}" if verify_file else ""
        verify_ok = False
        verify_note = "未找到 MP_verify*.txt 校验文件。"
        verify_file_html = "未找到"
        if verify_file:
            verify_file_html = f'<code>{esc(verify_file.name)}</code>'
            try:
                request = urllib.request.Request(
                    verify_url,
                    headers={"User-Agent": "Mozilla/5.0 AAIE-CRM-WeChat-SelfCheck"},
                    method="GET",
                )
                with urllib.request.urlopen(request, timeout=8) as response:
                    content_type = response.headers.get("Content-Type", "")
                    body = response.read(200).decode("utf-8", errors="replace").strip()
                    local_body = verify_file.read_text(encoding="utf-8").strip()
                    verify_ok = response.status == 200 and body == local_body and "text/html" not in content_type.lower()
                    verify_note = "微信域名校验文件可直接访问。" if verify_ok else f"返回内容或类型不一致：HTTP {response.status}, {content_type}"
            except Exception as exc:
                verify_note = f"检查失败：{exc}"
        public_ip = ""
        public_ip_ok = False
        try:
            request = urllib.request.Request(
                "https://api.ipify.org",
                headers={"User-Agent": "Mozilla/5.0 AAIE-CRM-WeChat-SelfCheck"},
                method="GET",
            )
            with urllib.request.urlopen(request, timeout=8) as response:
                public_ip = response.read(80).decode("utf-8", errors="replace").strip()
                public_ip_ok = public_ip == WECHAT_EXPECTED_PUBLIC_IP
        except Exception as exc:
            public_ip = f"检查失败：{exc}"
        return {
            "service_account": WECHAT_SERVICE_ACCOUNT_NAME,
            "app_id_display": app_id or "未配置",
            "app_id_ok": bool(app_id),
            "app_secret_ok": bool(app_secret),
            "callback_url": callback_url,
            "callback_ok": callback_url == WECHAT_EXPECTED_CALLBACK_URL,
            "scope": scope,
            "scope_ok": scope == "snsapi_userinfo",
            "auth_domain": parsed_callback.netloc or WECHAT_EXPECTED_AUTH_DOMAIN,
            "auth_domain_ok": (parsed_callback.netloc or WECHAT_EXPECTED_AUTH_DOMAIN) == WECHAT_EXPECTED_AUTH_DOMAIN,
            "verify_file_html": verify_file_html,
            "verify_file_ok": verify_ok,
            "verify_file_note": verify_note,
            "public_ip_display": public_ip or "未读取到公网 IP",
            "public_ip_ok": public_ip_ok,
        }

    def settings_wechat_oauth_test_start(self, method):
        if method != "GET" or not allowed(self.user, "*"):
            return self.error_page("仅 Admin 可以发起微信授权检查。", HTTPStatus.FORBIDDEN)
        if not wechat_oauth_configured():
            return self.flash_redirect("/settings/wechat-oauth/check", "微信 AppID / AppSecret 未配置，无法发起微信授权验证。", "error")
        state = new_token(24)
        expires_at = (datetime.now().astimezone() + timedelta(minutes=10)).isoformat(timespec="seconds")
        callback_url = self.school_plan_wechat_oauth_callback_url()
        db.set_setting(
            wechat_oauth_state_setting_key(state),
            json.dumps({
                "state": state,
                "purpose": "wechat_settings_test",
                "callback_url": callback_url,
                "created_at": now_iso(),
                "expires_at": expires_at,
                "started_by_user_id": self.user["id"],
                "started_by_name": self.user["display_name"],
            }, ensure_ascii=False),
            self.user["id"],
        )
        db.audit(self.user, "wechat_oauth_test_started", "system_settings", "wechat_oauth", new_value=json.dumps({"callback_url": callback_url, "scope": wechat_oauth_scope()}, ensure_ascii=False))
        auth_url = "https://open.weixin.qq.com/connect/oauth2/authorize?" + urlencode({
            "appid": wechat_setting_value(WECHAT_APP_ID_SETTING),
            "redirect_uri": callback_url,
            "response_type": "code",
            "scope": wechat_oauth_scope(),
            "state": state,
        }) + "#wechat_redirect"
        user_agent = self.headers.get("User-Agent", "")
        if "MicroMessenger" not in user_agent:
            body = f"""
            <section class="panel">
              <h2>请用微信打开授权验证链接</h2>
              <p>微信服务号网页授权需要在微信内置浏览器中完成。当前浏览器看起来不是微信，直接跳转到 <code>open.weixin.qq.com</code> 时，Safari / Chrome 可能会显示 “Oops! Something went wrong”。</p>
              <p>请复制下面的一次性验证链接，到微信里打开；链接 10 分钟内有效。</p>
              <label>微信授权验证链接<input readonly value="{esc(auth_url)}" onclick="this.select()"></label>
              <div class="row-actions">
                <button class="copy-button primary" type="button" data-copy="{esc(auth_url)}">复制微信授权验证链接</button>
                <a class="secondary button-link" href="{esc(auth_url)}">继续在当前浏览器打开</a>
                <a class="ghost button-link" href="/settings/wechat-oauth/check">返回微信接入自检</a>
              </div>
              <p class="muted-line">如果你在手机上验证，建议把链接复制到微信“文件传输助手”或任意聊天窗口后点击打开。</p>
            </section>
            """
            message, kind = self.message()
            return self.send_html(page("微信授权检查", body, self.user, self.csrf, "settings", None, message, kind))
        return self.redirect(auth_url)

    def school_plan_wechat_oauth_test_callback(self, state_payload, code):
        try:
            token_data = wechat_exchange_oauth_code(code)
            openid = str(token_data.get("openid") or "").strip()
            unionid = str(token_data.get("unionid") or "").strip()
            profile = {}
            if wechat_oauth_scope() == "snsapi_userinfo":
                profile = wechat_fetch_userinfo(token_data.get("access_token"), openid)
                unionid = str(profile.get("unionid") or unionid).strip()
            nickname = str(profile.get("nickname") or "已验证用户").strip() or "已验证用户"
            avatar_url = str(profile.get("headimgurl") or "").strip()
        except Exception as exc:
            append_service_log("parent", "wechat_oauth_test_failed", str(exc), callback_url=state_payload.get("callback_url"))
            body = """
            <h1>微信授权验证失败</h1>
            <p>微信授权验证未完成，请检查 AppID / AppSecret、网页授权域名、回调地址和 API IP 白名单。</p>
            <p class="muted-line">错误详情已写入服务端日志；页面不会显示或泄露 AppSecret。</p>
            """
            return self.school_plan_share_public_page("微信授权验证失败", body, HTTPStatus.BAD_GATEWAY)
        rows = "\n".join([
            f"<tr><th>openid</th><td>{esc(self.school_plan_share_masked_openid(openid))}</td></tr>",
            f"<tr><th>unionid</th><td>{esc(self.school_plan_share_masked_openid(unionid)) if unionid else '未返回 / 未绑定开放平台'}</td></tr>",
            f"<tr><th>微信昵称</th><td>{esc(nickname)}</td></tr>",
            f"<tr><th>头像</th><td>{'已返回' if avatar_url else '未返回'}</td></tr>",
        ])
        avatar_html = f'<p><img src="{esc(avatar_url)}" alt="微信头像" style="width:72px;height:72px;border-radius:50%;object-fit:cover"></p>' if avatar_url else ""
        body = f"""
        <h1>微信授权验证成功</h1>
        <p>{esc(WECHAT_SERVICE_ACCOUNT_NAME)} 服务号已成功返回微信身份信息。</p>
        {avatar_html}
        <table class="share-confirm-table"><tbody>{rows}</tbody></table>
        <p class="muted-line">openid 与 unionid 仅显示脱敏结果；AppSecret 不会出现在页面或前端。</p>
        """
        append_service_log("parent", "wechat_oauth_test_passed", nickname=nickname, openid_suffix=re.sub(r"[^A-Za-z0-9]", "", openid)[-6:])
        return self.school_plan_share_public_page("微信授权验证成功", body)

    def school_plan_share_masked_openid(self, openid):
        suffix = re.sub(r"[^A-Za-z0-9]", "", str(openid or ""))[-6:]
        return f"****{suffix}" if suffix else "****"

    def school_plan_share_viewer_watermark(self, link, student_name=None, viewed_at=None):
        link_data = rowdict(link) if link and not isinstance(link, dict) else (link or {})
        student_name = student_name or " ".join(
            part
            for part in [link_data.get("passport_first_name"), link_data.get("passport_last_name")]
            if part
        ) or str(link_data.get("student_id") or "")
        nickname = str(link_data.get("bound_wechat_nickname") or "").strip() or "已验证用户"
        viewer_role = str(link_data.get("viewer_role") or "Primary Parent").strip() or "Primary Parent"
        viewer_name = str(link_data.get("viewer_name") or "").strip()
        viewer_label = f"{viewer_role} / {viewer_name}" if viewer_name else viewer_role
        viewed_at = viewed_at or now_iso()
        viewed_dt = parse_local_datetime(viewed_at) or datetime.now().astimezone()
        return "\n".join([
            "AAIE / AOYA",
            "AAIE 客户专属报告",
            f"学生：{student_name}",
            f"查看人：{viewer_label}",
            f"微信：{nickname}",
            f"日期：{viewed_dt.strftime('%Y-%m-%d')}",
            f"时间：{viewed_dt.strftime('%H:%M:%S')}",
            f"识别码：{self.school_plan_share_masked_openid(link_data.get('bound_wechat_openid'))}",
            f"查看时间：{display_datetime(viewed_at)}",
        ])

    def school_plan_recommended_schools_for_confirmation(self, snapshot):
        schools = []
        for index, school in enumerate(snapshot.get("schools") or [], 1):
            basic = school.get("basic_info") or {}
            school_id = basic.get("id") or index
            name = basic.get("school_name") or basic.get("school_name_english") or f"School {index}"
            schools.append({"school_id": school_id, "school_name": name, "rank_key": f"school_{index}"})
        return schools

    def school_plan_confirmation_rank_field_name(self, school):
        return f"rank_{school.get('rank_key') or school.get('school_id')}"

    def school_plan_share_brochure_report_year(self, snapshot):
        student = snapshot.get("student") or {}
        for value in (
            snapshot.get("report_year"),
            snapshot.get("school_year"),
            student.get("preferred_intake_year"),
            student.get("intake_year"),
        ):
            text = str(value or "").strip()
            if re.fullmatch(r"\d{4}", text):
                return text
        return ""

    def school_plan_share_brochure_appendix_html(self, snapshot, token):
        schools = snapshot.get("schools") or []
        report_year = self.school_plan_share_brochure_report_year(snapshot)
        cards = []
        for index, school in enumerate(schools, 1):
            basic = school.get("basic_info") or {}
            school_id = basic.get("id") or school.get("school_id") or index
            school_name = basic.get("school_name") or basic.get("school_name_english") or school.get("school_name") or f"School {index}"
            document = school_plan_find_school_brochure_document(school_id, report_year)
            if document:
                action = f'<a class="school-brochure-button" href="/school-plan-share/{quote(str(token or ""))}/brochures/{esc(document["id"])}">查看学校官方 Brochure</a>'
            else:
                action = '<span class="school-brochure-missing">暂无官方资料，请联系顾问获取</span>'
            cards.append(f"""
            <article class="school-brochure-card">
              <h3>{esc(school_name)}</h3>
              <p>以下为学校官方 Brochure / 官方介绍资料。该资料由学校官方提供，仅供家长进一步了解学校环境、课程设置、设施和校园生活。最终信息以学校官方确认为准。</p>
              {action}
            </article>""")
        if not cards:
            cards.append("""
            <article class="school-brochure-card">
              <h3>学校官方介绍资料</h3>
              <p>以下为学校官方 Brochure / 官方介绍资料。该资料由学校官方提供，仅供家长进一步了解学校环境、课程设置、设施和校园生活。最终信息以学校官方确认为准。</p>
              <span class="school-brochure-missing">暂无官方资料，请联系顾问获取</span>
            </article>""")
        return f"""
        <section class="school-plan-brochure-appendix">
          <h2>学校官方介绍资料</h2>
          <p class="school-brochure-intro">以下为学校官方 Brochure / 官方介绍资料。该资料由学校官方提供，仅供家长进一步了解学校环境、课程设置、设施和校园生活。最终信息以学校官方确认为准。</p>
          <div class="school-brochure-card-grid">{''.join(cards)}</div>
        </section>"""

    def school_plan_share_brochure_context(self, method, token, document_id):
        if method != "GET":
            return None, self.school_plan_share_public_page("无法完成操作", "<h1>无法完成操作</h1><p>请从 AAIE 提供的安全链接查看学校官方资料。</p>", HTTPStatus.METHOD_NOT_ALLOWED)
        link = self.school_plan_share_row_by_token(token)
        title, message, status = self.school_plan_share_status_problem(link)
        if status != 200:
            return None, self.school_plan_share_public_page(title, f"<h1>{esc(title)}</h1><p>{esc(message)}</p>", status)
        if not self.school_plan_share_cookie_valid(link):
            return None, self.school_plan_share_login_required_page(token, link)
        document = db.one("SELECT * FROM school_documents WHERE id=?", (document_id,))
        if not document:
            return None, self.school_plan_share_public_page("资料不存在", "<h1>资料不存在</h1><p>暂无官方资料，请联系顾问获取。</p>", HTTPStatus.NOT_FOUND)
        snapshot = self.school_plan_snapshot(link)
        allowed_school_ids = {
            str((school.get("basic_info") or {}).get("id") or school.get("school_id") or "")
            for school in (snapshot.get("schools") or [])
        }
        if str(document["school_id"]) not in allowed_school_ids or document["document_type"] != "School Brochure":
            return None, self.school_plan_share_public_page("无权查看资料", "<h1>无权查看资料</h1><p>该学校官方资料不属于当前学校方案。</p>", HTTPStatus.FORBIDDEN)
        filename = document["original_filename"] or document["stored_filename"] or "school-brochure.pdf"
        file_path = str(document["file_path"] or "").strip()
        target = Path(file_path).resolve() if file_path else None
        if not target or not target.is_file():
            return None, self.school_plan_share_public_page("资料暂不可用", "<h1>资料暂不可用</h1><p>暂无官方资料，请联系顾问获取。</p>", HTTPStatus.NOT_FOUND)
        filename = Path(document["original_filename"] or target.name).name
        school = db.one("SELECT school_name FROM schools WHERE id=?", (document["school_id"],))
        school_name = (school["school_name"] if school else "") or "学校"
        return {
            "link": link,
            "document": document,
            "snapshot": snapshot,
            "filename": filename,
            "target": target,
            "school_name": school_name,
        }, None

    def school_plan_share_brochure_page_count(self, source_path, document, filename):
        try:
            data = Path(source_path).read_bytes()
            return max(1, pdf_page_count(data, max_pages=None))
        except Exception as exc:
            append_service_log(
                "parent",
                "school_plan_brochure_page_count_failed",
                repr(exc),
                document_id=document["id"],
                school_id=document["school_id"],
                filename=Path(filename).name,
            )
            return 1

