    def system_restore_point_create(self, method):
        if method != "POST":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        from tools.system_restore_point import create_system_restore_point
        task_name = form_text_value(self.form, "task_name")
        reason = form_text_value(self.form, "reason")
        if not task_name or not reason:
            return self.flash_redirect("/safebox/system-restore-points", "任务名称和原因必须填写。", "error")
        expected_files = [line.strip() for line in form_text_value(self.form, "expected_files_to_change").splitlines() if line.strip()]
        affected_modules = [part.strip() for part in form_text_value(self.form, "affected_modules").split(",") if part.strip()]
        result = create_system_restore_point(
            root=APP_DIR,
            db_path=db.path,
            reason=reason,
            task_name=task_name,
            trigger_type="manual",
            expected_files_to_change=expected_files,
            affected_modules=affected_modules,
            risk_level=form_text_value(self.form, "risk_level", "medium"),
            created_by=self.user.get("username") or self.user.get("display_name") or "CRM Admin",
            notes=form_text_value(self.form, "notes"),
        )
        db.audit(self.user, "system_restore_point_created", "safebox_centre", result["restore_point_id"], new_value=json.dumps(result, ensure_ascii=False), ip=self.client_address[0], device=self.headers.get("User-Agent"))
        return self.flash_redirect(f"/safebox/system-restore-points/{result['restore_point_id']}", "System Restore Point 已创建。")

