    def safebox_restore_calendar_day_cell(self, day, month_value, selected_date, counts):
        date_key = day.strftime("%Y-%m-%d")
        day_counts = counts.get(date_key, {})
        is_current_month = day.strftime("%Y-%m") == month_value
        classes = ["crm-restore-calendar-day"]
        if not is_current_month:
            classes.append("muted")
        if date_key == selected_date:
            classes.append("selected")
        badges = []
        for key, label in (("stable", "Stable"), ("dirty", "Dirty"), ("skipped", "Skipped"), ("failed", "Failed")):
            value = int(day_counts.get(key, 0) or 0)
            if value:
                badges.append(f'<span class="restore-badge {key}">{esc(label)} {value}</span>')
        return f"""
        <a class="{' '.join(classes)}" href="/safebox/restore-calendar?month={esc(month_value)}&date={esc(date_key)}">
          <strong>{day.day}</strong>
          <div class="crm-restore-calendar-badges">{''.join(badges) or '<span class="restore-badge empty">No records</span>'}</div>
        </a>"""

    def safebox_restore_calendar_point_row(self, point, selected_point_id):
        selected = " selected" if point["id"] == selected_point_id else ""
        reason = f" - {point['reason']}" if point["category"] == "skipped" and point["reason"] else ""
        label = {
            "stable": "Stable Restore Point",
            "dirty": "Dirty Backup",
            "skipped": f"Skipped{reason}",
            "failed": "Failed - metadata 缺失 / 无法读取",
        }.get(point["category"], point["label"])
        aria_label = f"{point['hour']} {label}"
        return f"""
        <a class="crm-restore-hour-row {esc(point['category'])}{selected}" aria-label="{esc(aria_label)}" href="/safebox/restore-calendar?month={esc(point['month'])}&date={esc(point['date'])}&point={esc(point['id'])}">
          <time>{esc(point['hour'])}</time>
          <span>{esc(label)}</span>
        </a>"""

    def safebox_restore_calendar_detail_html(self, point):
        meta = point["metadata"]
        can_stable = point["category"] == "stable" and meta.get("restore_point_type") == "stable"
        stable_note = "这是稳定恢复点，可作为人工恢复参考。" if can_stable else ""
        dirty_note = "这不是稳定恢复点，只是未提交工作区备份。不能直接作为系统稳定恢复点。" if point["category"] == "dirty" else ""
        failed_note = point["read_error"] if point["read_error"] else ""
        modified_files = meta.get("modified_files")
        if isinstance(modified_files, list):
            modified_files_text = "\n".join(str(item) for item in modified_files) or "无"
        else:
            modified_files_text = str(modified_files or "无")
        detail = {
            "时间": point["stamp"].isoformat(timespec="seconds"),
            "类型": point["label"],
            "当前分支": meta.get("branch") or "未记录",
            "当前 commit": meta.get("commit") or "未记录",
            "git status clean": meta.get("git_status_clean"),
            "modified files": modified_files_text,
            "stash 是否存在": meta.get("stash_exists"),
            "数据库 quick_check": meta.get("db_quick_check") or "未记录",
            "admin health 8780": restore_calendar_health_text(meta.get("admin_health")),
            "parent health 8781": restore_calendar_health_text(meta.get("parent_health")),
            "latest stable tag": meta.get("latest_stable_tag") or "未记录",
            "restore point path": point["path"],
            "是否可以作为稳定恢复点": "是" if can_stable else "否",
            "metadata 摘要": point["metadata_summary"],
        }
        rows = "".join(
            f'<div class="crm-component-safebox-detail-row"><span>{esc(key)}</span><pre>{esc(value)}</pre></div>'
            for key, value in detail.items()
        )
        plan = restore_calendar_restore_plan(point)
        precheck = restore_calendar_precheck_command()
        warning = "".join(
            f'<div class="notice {"warn" if text != stable_note else "success"}">{esc(text)}</div>'
            for text in (stable_note, dirty_note, failed_note)
            if text
        )
        return f"""
        <section class="panel crm-restore-detail-panel">
          <div class="panel-head"><div><span class="eyebrow">Restore Point Detail</span><h2>{esc(point['hour'])} {esc(point['label'])}</h2><p>{esc(point['path'])}</p></div></div>
          {warning}
          <div class="row-actions">
            <button class="copy-button secondary" type="button" data-copy="{esc(precheck)}">复制恢复前检查命令</button>
            <button class="copy-button secondary" type="button" data-copy="{esc(plan)}">复制恢复计划</button>
            <button class="copy-button secondary" type="button" data-copy="{esc(point['path'])}">复制路径</button>
            <button class="copy-button secondary" type="button" data-copy="{esc(meta.get('commit') or '')}">复制 commit hash</button>
            <button class="copy-button secondary" type="button" data-copy="{esc(point['metadata_summary'])}">复制 metadata 摘要</button>
          </div>
          <div class="crm-component-safebox-detail-grid">{rows}</div>
        </section>"""

    def safebox_restore_calendar(self, method):
        if method != "GET":
            return self.error_page("Method Not Allowed", HTTPStatus.METHOD_NOT_ALLOWED)
        points = restore_calendar_load_points(APP_DIR)
        counts = restore_calendar_counts(points)
        selected_date = (self.query.get("date") or [""])[0].strip()
        if selected_date not in counts and points:
            selected_date = points[-1]["date"]
        if not selected_date:
            selected_date = date.today().strftime("%Y-%m-%d")
        month_value = (self.query.get("month") or [selected_date[:7]])[0].strip() or selected_date[:7]
        month_value, month_days = restore_calendar_month_days(month_value)
        selected_points = [point for point in points if point["date"] == selected_date]
        selected_point_id = (self.query.get("point") or [""])[0].strip()
        if selected_point_id not in {point["id"] for point in selected_points} and selected_points:
            selected_point_id = selected_points[0]["id"]
        selected_point = next((point for point in selected_points if point["id"] == selected_point_id), None)
        calendar_rows = []
        for index in range(0, len(month_days), 7):
            calendar_rows.append('<div class="crm-restore-calendar-week">' + "".join(
                self.safebox_restore_calendar_day_cell(day, month_value, selected_date, counts)
                for day in month_days[index:index + 7]
            ) + "</div>")
        hour_rows = "".join(self.safebox_restore_calendar_point_row(point, selected_point_id) for point in selected_points)
        detail_html = self.safebox_restore_calendar_detail_html(selected_point) if selected_point else """
        <section class="panel crm-restore-detail-panel"><div class="empty">请选择一个日期查看每小时 Restore Point。</div></section>"""
        body = f"""
        <a class="back-link" href="/safebox">← 返回 SAFEBOX / 恢复记录</a>
        <section class="panel crm-restore-calendar-panel">
          <div class="panel-head"><div><span class="eyebrow">SAFEBOX / 恢复功能</span><h2>每小时恢复点日历</h2><p>Restore Points Calendar 只读取 metadata 并提供复制计划，不执行恢复动作。</p></div>
            <div class="row-actions"><a class="secondary button-link" href="/safebox">SAFEBOX Records</a><a class="secondary button-link" href="/safebox/system-restore-points">System Restore Points</a><button class="secondary" type="button" disabled>一键恢复禁用</button></div></div>
          <div class="notice warn">第一版只允许查看和复制恢复计划；不会执行 Git 恢复、数据库覆盖、文件覆盖、stash 恢复、自动提交或自动 tag。</div>
          <div class="crm-restore-layout">
            <div class="crm-restore-calendar">
              <div class="crm-restore-calendar-head"><strong>{esc(month_value)}</strong></div>
              <div class="crm-restore-weekdays"><span>Mon</span><span>Tue</span><span>Wed</span><span>Thu</span><span>Fri</span><span>Sat</span><span>Sun</span></div>
              {''.join(calendar_rows)}
            </div>
            <section class="crm-restore-hours">
              <h3>{esc(selected_date)} 每小时 Restore Point</h3>
              <div class="crm-restore-hour-list">{hour_rows or '<div class="empty">当天暂无 Restore Point。</div>'}</div>
            </section>
          </div>
        </section>
        {detail_html}"""
        message, kind = self.message()
        self.send_html(page("每小时恢复点日历", body, self.user, self.csrf, "safebox", nas.status(), message, kind))

