        drive_oauth_public_uri = self.google_drive_public_oauth_redirect_uri()
        drive_oauth_redirect_uri = self.google_drive_oauth_redirect_uri()
        drive_last_redirect_uri = google_drive_setting_value(GOOGLE_DRIVE_LAST_OAUTH_REDIRECT_URI_SETTING)
        drive_last_redirect_mode = google_drive_setting_value(GOOGLE_DRIVE_LAST_OAUTH_REDIRECT_MODE_SETTING)
        drive_oauth_ready = drive_auth_status["client_id"] and drive_auth_status["client_secret"]
        drive_connection_status = google_drive_setting_value(GOOGLE_DRIVE_CONNECTION_STATUS_SETTING)
