        drive_connected_at = google_drive_setting_value(GOOGLE_DRIVE_CONNECTED_AT_SETTING)
        drive_token_expiry = google_drive_setting_value(GOOGLE_DRIVE_TOKEN_EXPIRY_SETTING)
        drive_granted_scopes = google_drive_setting_value(GOOGLE_DRIVE_SCOPE_SETTING)
